  /*****************************************************************
  FUNCTION f_jrep_trad
  Formatea un varchar con saltos para su visualizaci?n correcta en CSV
  param IN pentrada  : texto de entrada
  return             : texto formateado para csv
  Bug 19927 - 28/11/2011 - JTS
  ******************************************************************/
  --
  --INI BUG 0045579 - 10/08/2018 - CASL - Se cambian los parametros por CLOB
  --
FUNCTION f_jrep_trad(
    pentrada IN VARCHAR2)--BUG 0045660 - 22/08/2018 - CASL - Se cambian los parametros por VARCHAR2
  RETURN VARCHAR2        --BUG 0045660 - 22/08/2018 - CASL - Se cambian los parametros por VARCHAR2
IS
  --
  --INI BUG 0043014 - 04/05/2018 - CASL - Se crea variable
  --
  v_entrada CLOB;
  --
  --FIN BUG 0043014 - 04/05/2018 - CASL
  --
BEGIN
  IF pentrada IS NULL THEN
    RETURN NULL; -- para que funcionen los NVLS
  END IF;
  --
  --INI BUG 0043014 - 04/05/2018 - CASL - Se reemplaza el texto <br> en Mayuscula y minuscula
  --
  v_entrada := REPLACE(pentrada, '<BR>', '\par ');
  v_entrada := REPLACE(pentrada, '<br>', '\par ');
  --
  --FIN BUG 0043014 - 04/05/2018 - CASL
  --
  --Bug 22798 - 16/07/2012 - ECP -LCOL897 - Tratamiento de comillas dobles en la caratula
  -- Se cambio RETURN REPLACE(REPLACE('"' || pentrada || '"', '\par "', '"'), '\par ', CHR(10)); por
  --
  --INI BUG 0043014 - 04/05/2018 - CASL - Se cambia pentrada por v_entrada
  --
  -- INI - QT0053764 - Inforcol/soto - 12/10/2020
  RETURN REPLACE(REPLACE(REPLACE('"' || REPLACE(v_entrada, CHR(34), CHR(39)) || '"', '\par "', '"'), '\par ', CHR(10) || ''), -- JFN QT_28989
  '\tab ', CHR(32));
 /* RETURN REPLACE(REPLACE(REPLACE('"' || REPLACE(v_entrada, CHR(34), CHR(39)) || '"', '\par "', '"'), '\par ', CHR(10) || ''), -- JFN QT_28989
  '\tab ', CHR(32));*/
   -- FIN - QT0053764 - Inforcol/soto - 12/10/2020
  --FIN BUG 0043014 - 04/05/2018 - CASL
  --
END f_jrep_trad;
--
--FIN BUG 0045579 - 10/08/2018 - CASL
--
--INI BUG 0046692 - 26/09/2018 - AMC
/*****************************************************************
FUNCTION f_jrep_trad_clob
Formatea un CLOB con saltos para su visualizacion correcta en CSV
param IN pentrada  : texto de entrada
return             : texto formateado para csv
Bug 0046692 - 27/09/2018 - AMC
******************************************************************/
FUNCTION f_jrep_trad_clob(
    pentrada IN CLOB)
  RETURN CLOB
IS
  v_entrada CLOB;
BEGIN
  IF pentrada IS NULL THEN
    RETURN NULL; -- para que funcionen los NVLS
  END IF;
  -- Se reemplaza el texto <br> en Mayuscula y minuscula
  v_entrada := REPLACE(pentrada, '<BR>', '\par ');
  v_entrada := REPLACE(pentrada, '<br>', '\par ');
  -- Tratamiento de comillas dobles en la caratula
  RETURN REPLACE(REPLACE(REPLACE('"' || REPLACE(v_entrada, CHR(34), CHR(39)) || '"', '\par "', '"'), '\par ', CHR(10) || ' '), '\tab ', CHR(32));
END f_jrep_trad_clob;
--FIN BUG 0046692 - 27/09/2018 - AMC
/*****************************************************************
FUNCTION f_garantias_riesgo
Devuelve las garant?as de un riesgo
param IN psseguro  : codigo de seguro
param IN pnriesgo  : n?mero de riesgo
param IN pcidioma  : codigo de idioma
param IN pmodo     : modo EST/POL
return             : texto con las garant?as del riesgo
Bug 19927 - 28/11/2011 - JTS
******************************************************************/
FUNCTION f_garantias_riesgo(
    psseguro IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(2000);
    v_tlinia    VARCHAR2(200);
    -- INI BUG 0035054/0017140 -- ECP -- 11/03/2015 - Se cambia v_tpargar      VARCHAR2(200); por
    v_tpargar VARCHAR2(300);
    -- FIN BUG 0035054/0017140 -- ECP -- 11/03/2015
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
    v_es_admin  NUMBER; --Bug 33145/192146 - 03/12/2014 - AMC
    v_ncertif   NUMBER; --BUG 0036927 - 18/08/2017 - CASL - Se crea la variable del certificado.
    v_sproduc   NUMBER; --BUG 0056504 20/11/2019 GZG
  BEGIN
    --INI GZG AITSSD-3915 15/07/2025
    BEGIN
        SELECT sproduc INTO v_sproduc FROM seguros WHERE sseguro = psseguro;
    EXCEPTION
    WHEN OTHERS THEN
        SELECT sproduc INTO v_sproduc FROM ESTseguros WHERE sseguro = psseguro;
    END;
    --FIN GZG AITSSD-3915 15/07/2025
    -- BUG 16092 - 12/01/2011 - JMP - AGA RC: Miramos si las garant?as est?n definidas para la actividad del seguro
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0, IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    --INI GZG AITSSD-3915 17/07/2025
    IF NVL(pac_parametros.f_parproducto_n(v_sproduc, 'GARANT_IMP0'), 0) = 1 THEN
    v_tconsulta         := 'SELECT CASE WHEN NVL(pac_parametros.f_pargaranpro_n(se.sproduc, se.cactivi, p.cgarant, ''GARANT_IMP''), 0) = 1 THEN';
    v_tconsulta         := v_tconsulta || ' ''<b>''||REPLACE(pac_isqlfor_lcol.f_des_garpro(se.sseguro,s.nriesgo,' || NVL(pcidioma, 2) || ',p.cgarant,se.sproduc,''' || pmodo || '''), CHR(39), CHR(39) || CHR(39))||''</b>''  ';
    v_tconsulta         := v_tconsulta || ' ELSE REPLACE(pac_isqlfor_lcol.f_des_garpro(se.sseguro,s.nriesgo,' || NVL(pcidioma, 2) || ',p.cgarant,se.sproduc,''' || pmodo || '''), CHR(39), CHR(39) || CHR(39)) END a ';
    ELSE
    v_tconsulta         := 'SELECT REPLACE(pac_isqlfor_lcol.f_des_garpro(se.sseguro,s.nriesgo,' || NVL(pcidioma, 2) || ',p.cgarant,se.sproduc,''' || pmodo || '''), CHR(39), CHR(39) || CHR(39)) a';
    END IF;
    --FIN GZG AITSSD-3915 17/07/2025
    v_tconsulta         := v_tconsulta || ' FROM garanpro p, ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || 'estgaranseg s, estseguros se';
      v_csituac         := '(0,7,5,2,4)';
    ELSE
      v_tconsulta                                 := v_tconsulta || 'garanseg s, seguros se';
      IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
        -- INI BUG 45008 GNRZ 19/07/2018  Se incluyen  estados posibles de pÃ³liza
        -- Inicio QT44626 Amantium 12/07/2018
        -- Se incluyen las pÃ³lizas vencidas
        --v_csituac                                 := '(0,7,5,2,4)'; --BUG 0028151 - 01/03/2017 - CASL - se aÃ¿Â±anden las propuestas
        --v_csituac := '(0,7,5,2,4,3)';
        v_csituac := '(0,7,5,2,4,3,17,1,7,8,9,10,16)';
        -- Fin QT44626 Amantium 12/07/2018
        -- FIN BUG 45008 GNRZ 19/07/2018  Se incluyen  estados posibles de pÃ³liza
      ELSE
        v_csituac := '(0,7,5,2,4)';
      END IF;
    END IF;
    v_tconsulta         := v_tconsulta || ' WHERE p.cgarant = s.cgarant';
    v_tconsulta         := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta         := v_tconsulta || ' AND p.CACTIVI = ' || v_actividad;
    v_tconsulta         := v_tconsulta || ' AND se.csituac in ' || v_csituac;
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      --Bug 33145/192146 - 03/12/2014 - AMC
      v_es_admin    := pac_seguros.f_es_col_admin(psseguro, 'EST');
      IF v_es_admin  = 1 THEN
        v_tconsulta := v_tconsulta || ' AND s.cobliga = 1 and s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg ga WHERE sseguro =' || psseguro;
        v_tconsulta := v_tconsulta || ' AND ga.nmovimi <= (SELECT MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.SSEGURO = GA.SSEGURO AND MV.CMOVSEG!=3 AND MV.NMOVIMI =(select max(nmovimi_cert) from detmovsegurocol WHERE sseguro_0 =  (select sseguro from seguros where npoliza = (select npoliza from seguros where sseguro = ' || psseguro || ')  and ncertif = 0 ) '
        --INI 0023950: Vida grupo-GNO-poliza 135291-se genran los PDF de los certificados y salen sin los amparos
        || ' AND sseguro_cert = ' || psseguro;
        --FIN 0023950: Vida grupo-GNO-poliza 135291-se genran los PDF de los certificados y salen sin los amparos
        IF (pnmovimi  IS NOT NULL) THEN
          v_tconsulta := v_tconsulta || ' AND nmovimi_0 <=' || pnmovimi || '))) ';
        ELSE
          v_tconsulta := v_tconsulta || ')))';
        END IF;
      ELSE
        v_tconsulta   := v_tconsulta || ' AND s.cobliga = 1 and s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg WHERE sseguro =' || psseguro;
        IF (pnmovimi  IS NOT NULL) THEN
          v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
        ELSE
          v_tconsulta := v_tconsulta || ')';
        END IF;
      END IF;
      --Fi Bug 33145/192146 - 03/12/2014 - AMC
     --INI GZG AITSSD-3915 15/07/2025
     IF NVL(pac_parametros.f_parproducto_n(v_sproduc, 'GARANT_IMP0'), 0) = 1 THEN
          SELECT ' AND ((NVL(pac_parametros.f_pargaranpro_n('
            || sproduc
            || ', '
            || cactivi
            || ', p.cgarant, ''GARANT_IMP2''), 0) = 1) )'
          INTO v_tpargar
          FROM
            (SELECT seg.sproduc,
              seg.cactivi
            FROM estseguros seg
            WHERE seg.sseguro = psseguro
            );
      ELSE
          -- INI 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo  -- INI BUG 00350431/0017560 -- ECP -- 13/04/2015 - Se agrega condiciÃ¿Â¿Ã¿Â³n para mostrar la garantÃ¿Â¿Ã¿Â­a Cobertura al deducible en Suplemento
          SELECT ' AND ((NVL(pac_parametros.f_pargaranpro_n('
            || sproduc
            || ', '
            || cactivi
            || ', p.cgarant, ''GARANT_IMP''), 0) = 1) )'
            --|| ', p.cgarant, ''GARANT_IMP''), 0) = 1) OR exists (select 1 from garanseg where sseguro = s.sseguro and nmovimi = s.nmovimi and cgarant = 777 and iprianu <> 0))'
            -- FIN BUG 0035431/0017560 -- ECP -- 13/04/2015
            -- FIN 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo
          INTO v_tpargar
          FROM
            (SELECT seg.sproduc,
              seg.cactivi
            FROM estseguros seg
            WHERE seg.sseguro = psseguro
            );
      END IF;
    --FIN GZG AITSSD-3915 15/07/2025
  ELSE
    --
    --INI BUG 0036927 - 18/08/2017 - CASL - Se obtiene el certificado a imprimir
    --
    SELECT ncertif,sproduc--BUG 0056504 20/11/2019 GZG
    INTO v_ncertif,v_sproduc--BUG 0056504 20/11/2019 GZG
    FROM seguros
    WHERE sseguro = psseguro;
    --
    --FIN BUG 0036927 - 18/08/2017 - CASL
    --
    --Bug 33145/192146 - 03/12/2014 - AMC
    v_es_admin    := pac_seguros.f_es_col_admin(psseguro, 'POL');
    IF v_es_admin  = 1 THEN
      v_tconsulta := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG ga WHERE sseguro =' || psseguro;
      --INI BUG 0056504 20/11/2019 GZG
      IF NVL(pac_parametros.f_parproducto_n(v_sproduc, 'IMP_AMPAR_RECIB_0'), 0) = 1 AND v_ncertif = 0 THEN
      v_tconsulta := v_tconsulta || '  and ga.nmovimi <= (SELECT MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.SSEGURO = GA.SSEGURO AND MV.CMOVSEG!=3 AND MV.NMOVIMI =(select max(nmovimi_cert) from detmovsegurocol WHERE sseguro_0 = (select sseguro from seguros where npoliza = (select npoliza from seguros where sseguro = ' || psseguro || ' )  and ncertif = 0 )';
      ELSE
      --FIN BUG 0056504 20/11/2019 GZG
      v_tconsulta := v_tconsulta || '  and ga.nmovimi <= (SELECT MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.SSEGURO = GA.SSEGURO AND MV.CMOVSEG!=3 AND MV.NMOVIMI =(select max(nmovimi_cert) from detmovsegurocol WHERE sseguro_0 = (select sseguro from seguros where npoliza = (select npoliza from seguros where sseguro = ' || psseguro || ' )  and ncertif = 0 )'
      --INI 0024170: Vida grupo-GNO-poliza 141199-los pdf salen sin valor asegurado en los certificados
      || ' AND sseguro_cert = ' || psseguro;
      --FIN 0024170: Vida grupo-GNO-poliza 141199-los pdf salen sin valor asegurado en los certificados
      END IF;--BUG 0056504 20/11/2019 GZG
      IF (pnmovimi IS NOT NULL) THEN
        --
        --INI BUG 0036927 - 18/08/2017 - CASL - Si la poliza es administrada y el certificado es diferente de 0 se filtra por el nmovimi_cert
        --
        IF v_ncertif <> 0 THEN
          --
          v_tconsulta := v_tconsulta || ' AND nmovimi_cert <=' || pnmovimi || '))) ';
          --
        ELSE
          --
          v_tconsulta := v_tconsulta || ' AND nmovimi_0 <=' || pnmovimi || '))) ';
          --
        END IF;
        --
        --FIN BUG 0036927 - 18/08/2017 - CASL
        --
      ELSE
        v_tconsulta := v_tconsulta || ')))';
      END IF;
    ELSE
      v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro;
      IF (pnmovimi  IS NOT NULL) THEN
        v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
        v_tconsulta := v_tconsulta || ')';
      END IF;
    END IF;
    --Fi Bug 33145/192146 - 03/12/2014 - AMC
    --INI GZG AITSSD-3915 15/07/2025
     IF NVL(pac_parametros.f_parproducto_n(v_sproduc, 'GARANT_IMP0'), 0) = 1 THEN
        SELECT ' AND ((NVL(pac_parametros.f_pargaranpro_n('
          || sproduc
          || ', '
          || cactivi
          || ', p.cgarant, ''GARANT_IMP2''), 0) = 1) )'
        INTO v_tpargar
        FROM
          (SELECT seg.sproduc,
            seg.cactivi
          FROM seguros seg
          WHERE seg.sseguro = psseguro
          );
      ELSE
        -- INI 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo  -- INI BUG 0035054/0017140 -- ECP -- 11/03/2015 - Se agrega condiciÃ¿Â¿Ã¿Â³n para mostrar la garantÃ¿Â¿Ã¿Â­a Cobertura al deducible en Suplemento
        SELECT ' AND ((NVL(pac_parametros.f_pargaranpro_n('
          || sproduc
          || ', '
          || cactivi
          || ', p.cgarant, ''GARANT_IMP''), 0) = 1) )'
          --|| ', p.cgarant, ''GARANT_IMP''), 0) = 1) OR exists (select 1 from garanseg where sseguro = s.sseguro and nmovimi = s.nmovimi and cgarant = 777 and iprianu <> 0))'
          -- FIN 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo  -- FIN BUG 0035054/0017140 -- ECP -- 11/03/2015
        INTO v_tpargar
        FROM
          (SELECT seg.sproduc,
            seg.cactivi
          FROM seguros seg
          WHERE seg.sseguro = psseguro
          );
      END IF;
    --FIN GZG AITSSD-3915 15/07/2025
  END IF;
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY s.norden';--AITSSD-2546 GZG 31/10/2022
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_tlinia;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_garantias_riesgo;
--INICIO JMG 26/06/2024 I4PPE-2 - Asistencia diferenciada-PDF
/*****************************************************************
FUNCTION f_amparo_pregdesc
Devuelve la descripcion del importe para la garantia de asistencia
param IN psproduc  : codigo de producto
param IN psseguro  : codigo de sseguro
param IN pcgarant  : n?mero de garantia
param IN pmodo     : modo EST/POL
return             : texto
Bug 19927 - 28/11/2011 - JTS
******************************************************************/
FUNCTION f_amparo_pregdesc(
	psproduc    IN NUMBER,
    psseguro    IN NUMBER,
	pcgarant      IN NUMBER,
	pcpregunta	IN NUMBER,
	pmodo       IN VARCHAR2 DEFAULT 'POL')
  RETURN VARCHAR2
IS
vtexto varchar2(100) := null;
v_trespuegar varchar2(100) :=null;
v_parhomologa varchar2(100) := null;
BEGIN

IF pcgarant = 768 THEN

	--De acuerdo al modo se trae la respuesta de la pregunta

	IF pcpregunta in ('4922','9240') THEN

			v_parhomologa := (CASE WHEN pcpregunta= '4922' THEN 'AMP768_PREGDES_4922'
								   WHEN pcpregunta= '9240' THEN 'AMP768_PREGDES_9240'
							  END );

			IF NVL(pmodo, 'POL') = 'EST' THEN

				SELECT pac_int_online.f_buscar_valor_emp(12, v_parhomologa,crespue) into v_trespuegar FROM
					ESTPREGUNGARANSEG p
				WHERE sseguro=psseguro AND cgarant=pcgarant AND cpregun=pcpregunta
				AND p.nmovimi = (SELECT max(nmovimi) FROM ESTPREGUNGARANSEG p2 WHERE p2.sseguro= psseguro AND p2.cgarant=pcgarant AND cpregun=pcpregunta) ;

			ELSIF NVL(pmodo, 'POL') = 'POL' THEN

				SELECT pac_int_online.f_buscar_valor_emp(12, v_parhomologa,crespue) into v_trespuegar FROM
					PREGUNGARANSEG p
				WHERE sseguro=psseguro AND cgarant=pcgarant AND cpregun=pcpregunta
				AND p.nmovimi = (SELECT max(nmovimi) FROM PREGUNGARANSEG p2 WHERE p2.sseguro= psseguro AND p2.cgarant=pcgarant AND cpregun=pcpregunta) ;

			ELSIF NVL(pmodo, 'POL') = 'CAR' THEN

				SELECT pac_int_online.f_buscar_valor_emp(12, v_parhomologa,crespue) into v_trespuegar FROM
					PREGUNGARANCAR p
				WHERE sseguro=psseguro AND cgarant=pcgarant AND cpregun=pcpregunta
				AND p.nmovimi = (SELECT max(nmovimi) FROM PREGUNGARANCAR p2 WHERE p2.sseguro= psseguro AND p2.cgarant=pcgarant AND cpregun=pcpregunta) ;

			END IF;

	 END IF;

	IF v_trespuegar IS NOT NULL AND v_trespuegar <> '@@SINVALOR@@' THEN
		vtexto := v_trespuegar;
	ELSE
		vtexto := NULL;
	END IF;


END IF;

RETURN vtexto;
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END;

--FIN JMG 26/06/2024 I4PPE-2 - Asistencia diferenciada-PDF
/*****************************************************************
FUNCTION f_capitales_riesgo
Devuelve los capitales de un riesgo
param IN psseguro  : codigo de seguro
param IN pnriesgo  : n?mero de riesgo
param IN pmodo     : modo EST/POL
return             : texto con los capitales del riesgo
Bug 19927 - 28/11/2011 - JTS
******************************************************************/
FUNCTION f_importes_riesgo(
    psseguro    IN NUMBER,
    pcampo      IN NUMBER,
    pnriesgo    IN NUMBER DEFAULT 1,
    pcidioma    IN NUMBER DEFAULT 1,
    pmodo       IN VARCHAR2 DEFAULT 'POL',
    pnmovimi    IN NUMBER DEFAULT NULL,
    pmodoacceso IN NUMBER DEFAULT NULL, --BUG 0028151 - 10/02/2017 - CASL - Se aÃ¿Â±ade nuevo parametro
    psproces    IN NUMBER DEFAULT NULL) --BUG 47494 MPC 08/03/2019 Se adiciona parametro.
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult     VARCHAR2(32000) := '';
    v_tconsulta   VARCHAR2(4000);
    v_tconsulta_1 VARCHAR2(4000) := ''; --BUG 47494 MPC 08/03/2019 Se crea variable.
    v_tlinia      VARCHAR2(50);
    -- INI BUG 0035431/0017560-- ECP -- 13/04/2015 - Se cambia v_tpargar      VARCHAR2(200); por
    v_tpargar VARCHAR2(300);
    -- FIN BUG 0035431/0017560 -- ECP -- 13/04/2015
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot VARCHAR2(200);
    v_ctipcap garanpro.ctipcap%TYPE;
    v_cimpres garanpro.cimpres%TYPE;
    v_npargar   NUMBER := 0;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
    v_es_admin  NUMBER; --Bug 33145/192146 - 03/12/2014 - AMC
    nerror      NUMBER; --BUG 33488/196537 - 26/01/2015 - AMC
    vncertif    NUMBER;
    vsproduc    NUMBER; --    BUG 48286 11/12/2018 GNRZ ITAU no debe dejar la etiqueta "INCLUIDA" cuando el capital es 0
	v_trespuegar varchar2(100) :=null; --INI/FIN JMG I4PPE-2
	v_cgarant   NUMBER; --INI/FIN JMG I4PPE-2
	--INI JMC 26/06/2024 AITSSD-19067
	v_preglimite NUMBER;
	--FIN JMC 26/06/2024 AITSSD-19067
  BEGIN
	    --INI GZG AITSSD-3915 15/07/2025
    BEGIN
        SELECT sproduc INTO vsproduc FROM seguros WHERE sseguro = psseguro;
    EXCEPTION
    WHEN OTHERS THEN
        SELECT sproduc INTO vsproduc FROM ESTseguros WHERE sseguro = psseguro;
    END;
    --FIN GZG AITSSD-3915 15/07/2025
    -- BUG 16092 - 12/01/2011 - JMP - AGA RC: Miramos si las garant?as est?n definidas para la actividad del seguro
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    --INI GZG AITSSD-3915 17/07/2025
    IF NVL(pac_parametros.f_parproducto_n(vsproduc, 'GARANT_IMP0'), 0) = 1 THEN
        IF NVL(pmodo, 'POL') = 'EST' THEN
          v_tconsulta := 'SELECT CASE WHEN NVL(pac_parametros.f_pargaranpro_n(se.sproduc, se.cactivi, s.cgarant, ''GARANT_IMP''), 0) = 1 THEN';
          v_tconsulta := v_tconsulta || ' ''<b>''||pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*NVL(s.icapital,s.icaptot)))||''</b>'' ELSE';
          v_tconsulta := v_tconsulta || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*NVL(s.icapital,s.icaptot))) END a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP2''), 0), ' || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d , g.cgarant, nvl( pac_parametros.f_pargaranpro_n( p.sproduc,  p.cactivi, g.cgarant, ''PREGUNTA_LIMITE'' ), 0) limite  ';
        ELSE
          v_tconsulta := 'SELECT CASE WHEN NVL(pac_parametros.f_pargaranpro_n(se.sproduc, se.cactivi, s.cgarant, ''GARANT_IMP''), 0) = 1 THEN';
          v_tconsulta := v_tconsulta || ' ''<b>''||pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*NVL(s.icapital,s.icaptot)))||''</b>'' ELSE';
          v_tconsulta := v_tconsulta || ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*NVL(s.icapital,s.icaptot))) END a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP2''), 0), ' || ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot) d , g.cgarant, nvl( pac_parametros.f_pargaranpro_n( p.sproduc,  p.cactivi, g.cgarant, ''PREGUNTA_LIMITE'' ), 0) limite  ';
        END IF;
    ELSE
        IF NVL(pmodo, 'POL') = 'EST' THEN
        --INI BUG 0056243 GZG 15/11/2019
        --INI JMG 26/06/2024 I4PPE-2
        --INI JMC 26/06/2024 AITSSD-19067
          v_tconsulta := 'SELECT pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*NVL(s.icapital,s.icaptot))) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d , g.cgarant, nvl( pac_parametros.f_pargaranpro_n( p.sproduc,  p.cactivi, g.cgarant, ''PREGUNTA_LIMITE'' ), 0) limite  ';
        ELSE
          v_tconsulta := 'SELECT pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*NVL(s.icapital,s.icaptot))) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot) d , g.cgarant, nvl( pac_parametros.f_pargaranpro_n( p.sproduc,  p.cactivi, g.cgarant, ''PREGUNTA_LIMITE'' ), 0) limite  ';
        --FIN JMC 26/06/2024 AITSSD-19067
        --FIN JMG 26/06/2024 I4PPE-2
        --FIN BUG 0056243 GZG 15/11/2019
        END IF;
    END IF;
    --FIN GZG AITSSD-3915 17/07/2025
    v_tconsulta         := v_tconsulta || ' FROM  garangen g, garanpro p, productos pp, ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' estgaranseg s, estseguros se';
      v_csituac         := '(0,7,5,2,4)';
    ELSE
      --INI BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
      IF NVL(pmodo, 'POL') = 'CAR' THEN
        --
        v_tconsulta   := v_tconsulta || ' garancar s, seguros se';
        v_tconsulta_1 := ' AND s.sproces = '||psproces;
        --
      ELSE
        v_tconsulta_1   := v_tconsulta_1 || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM garanseg WHERE sseguro =' || psseguro;
        IF (pnmovimi    IS NOT NULL) THEN
          v_tconsulta_1 := v_tconsulta_1 || ' AND nmovimi <=' || pnmovimi || ') ';
        ELSE
          v_tconsulta_1 := v_tconsulta_1 || ')';
        END IF;
        --FIN BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
        v_tconsulta := v_tconsulta || ' garanseg s, seguros se';
      END IF; --BUG 47494 MPC 08/03/2019 Se adiciona condicÃ³n.
      IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
        -- INI BUG 45008 GNRZ 19/07/2018  Se incluyen  estados posibles de pÃ³liza
        -- Inicio QT44626 Amantium 12/07/2018
        -- Se incluyen las pÃ³lizas vencidas
        --v_csituac                                 := '(0,7,5,2,4)'; --BUG 0028151 - 01/03/2017 - CASL - se aÃ¿Â±anden las propuestas
        --v_csituac := '(0,7,5,2,4,3)';
        v_csituac := '(0,7,5,2,4,3,17,1,7,8,9,10,16)';
        -- Fin QT44626 Amantium 12/07/2018
        -- FIN BUG 45008 GNRZ 19/07/2018  Se incluyen  estados posibles de pÃ³liza
      ELSE
        v_csituac := '(0,7,5,2,4)';
      END IF;
    END IF;
    v_tconsulta := v_tconsulta || ' WHERE g.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = pp.sproduc';
    v_tconsulta := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' AND se.csituac in ' || v_csituac;
    --v_tconsulta := v_tconsulta || ' AND s.ffinefe IS NULL';
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      --Bug 33145/192146 - 03/12/2014 - AMC
      v_es_admin := pac_seguros.f_es_col_admin(psseguro, 'EST');
      --BUG 33488/196537 - 26/01/2015 - AMC
      SELECT ncertif
      INTO vncertif
      FROM estseguros
      WHERE sseguro  = psseguro;
    IF v_es_admin    = 1 AND vncertif <> 0 THEN
      v_tconsulta   := v_tconsulta || ' AND s.cobliga = 1';
      v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg ga WHERE sseguro =' || psseguro;
      v_tconsulta   := v_tconsulta || '  and ga.nmovimi <= (SELECT MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.SSEGURO = GA.SSEGURO AND MV.CMOVSEG!=3 AND MV.NMOVIMI =(select max(nmovimi_cert) from detmovsegurocol WHERE sseguro_0 = (select sseguro from seguros where npoliza = (select npoliza from seguros where sseguro = ' || psseguro || ')  and ncertif = 0) and sseguro_cert =ga.sseguro';
      IF (pnmovimi  IS NOT NULL) THEN
        v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || '))) ';
      ELSE
        v_tconsulta := v_tconsulta || ')))';
      END IF;
    ELSE
      v_tconsulta   := v_tconsulta || ' AND s.cobliga = 1';
      v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg WHERE sseguro =' || psseguro;
      IF (pnmovimi  IS NOT NULL) THEN
        v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
        v_tconsulta := v_tconsulta || ')';
      END IF;
    END IF;
    --Fi Bug 33145/192146 - 03/12/2014 - AMC
    -- INI 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo  -- INI BUG 0035431/0017560 -- ECP -- 13/04/2015 - Se agrega condiciÃ¿Â³n para mostrar la garantÃ¿Â­a Cobertura al deducible en Suplemento
    --INI GZG AITSSD-3915 15/07/2025
     IF NVL(pac_parametros.f_parproducto_n(vsproduc, 'GARANT_IMP0'), 0) = 1 THEN
        SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
          || sproduc
          || ', '
          || cactivi
          || ', g.cgarant, ''GARANT_IMP2''), 0) = 1 )'
        INTO v_tpargar
        FROM
          (SELECT seg.sproduc,
            seg.cactivi
          FROM estseguros seg
          WHERE seg.sseguro = psseguro
          );
      ELSE
        SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
          || sproduc
          || ', '
          || cactivi
          || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
          --|| ', g.cgarant, ''GARANT_IMP''), 0) = 1 OR exists (select 1 from garanseg where sseguro = s.sseguro and nmovimi = s.nmovimi and cgarant = 777 and iprianu <> 0))'
          -- FIN 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo    -- FIN BUG 0035431/0017560 -- ECP -- 13/04/2015
        INTO v_tpargar
        FROM
          (SELECT seg.sproduc,
            seg.cactivi
          FROM estseguros seg
          WHERE seg.sseguro = psseguro
          );
      END IF;
    --FIN GZG AITSSD-3915 15/07/2025
  ELSE
    --Bug 33145/192146 - 03/12/2014 - AMC
    v_es_admin := pac_seguros.f_es_col_admin(psseguro, 'POL');
    --BUG 33488/196537 - 26/01/2015 - AMC
    SELECT ncertif
    INTO vncertif
    FROM seguros
    WHERE sseguro  = psseguro;
    IF v_es_admin  = 1 AND vncertif <> 0 AND NVL(pmodo, 'POL') != 'CAR' THEN --BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
      v_tconsulta := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM garanseg ga WHERE sseguro =' || psseguro;
      v_tconsulta := v_tconsulta || '  and ga.nmovimi <= (SELECT MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.SSEGURO = GA.SSEGURO AND MV.CMOVSEG!=3 AND MV.NMOVIMI =(select nvl(max(nmovimi_cert),1) from detmovsegurocol WHERE sseguro_0 = (select sseguro from seguros where npoliza = (select npoliza from seguros where sseguro = ' || psseguro || ')  and ncertif = 0) AND nmovimi_cert';
      -- inicio BUG 46441 - 28/09/2018 - ARM
      v_tconsulta := v_tconsulta || ' NOT IN (SELECT MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.SSEGURO = ' || psseguro || ' AND MV.CMOVSEG = 3) ';
      -- fin BUG 46441 - 28/09/2018 - ARM
      v_tconsulta   := v_tconsulta || ' and sseguro_cert =ga.sseguro';
      IF (pnmovimi  IS NOT NULL) THEN
        v_tconsulta := v_tconsulta || ' AND nmovimi_cert <=' || pnmovimi || '))) '; --BUG 0036927 - 18/08/2017 - CASL - Si la poliza es administrada y el certificado es diferente de 0 se filtra por el nmovimi_cert
      ELSE
        v_tconsulta := v_tconsulta || ')))';
      END IF;
    ELSE
      --INI BUG 47494 MPC 08/03/2019 Se modifica codigo.
      v_tconsulta := v_tconsulta || v_tconsulta_1;
      /*v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM garanseg WHERE sseguro =' || psseguro;
      IF (pnmovimi  IS NOT NULL) THEN
      v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
      v_tconsulta := v_tconsulta || ')';
      END IF;*/
      --FIN BUG 47494 MPC 08/03/2019 Se modifica codigo.
    END IF;
    --Fi Bug 33145/192146 - 03/12/2014 - AMC
    --INI GZG AITSSD-3915 15/07/2025
      IF NVL(pac_parametros.f_parproducto_n(vsproduc, 'GARANT_IMP0'), 0) = 1 THEN
        SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
          || sproduc
          || ', '
          || cactivi
          || ', g.cgarant, ''GARANT_IMP2''), 0) = 1 )'
        INTO v_tpargar
        FROM
          (SELECT seg.sproduc,
            seg.cactivi
          FROM seguros seg
          WHERE seg.sseguro = psseguro
          );
      ELSE
        -- INI 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo  -- INI BUG 0035431/0017560 -- ECP -- 13/04/2015
        SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
          || sproduc
          || ', '
          || cactivi
          || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
          --|| ', g.cgarant, ''GARANT_IMP''), 0) = 1 OR exists (select 1 from garanseg where sseguro = s.sseguro and nmovimi = s.nmovimi and cgarant = 777 and iprianu <> 0))'
          -- FIN 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo    -- FIN BUG 0035431/0017560 -- ECP -- 13/04/2015
        INTO v_tpargar
        FROM
          (SELECT seg.sproduc,
            seg.cactivi
          FROM seguros seg
          WHERE seg.sseguro = psseguro
          );
      END IF;
    --FIN GZG AITSSD-3915 15/07/2025
  END IF;
  --INI BUG 0068006 GZG 27/04/2021 se reversa bug por generar errores en produccion.
  -- INICIO 259.0   18/08/2020  INFORCOL   259
  v_tconsulta := v_tconsulta || v_tpargar;
  -- FIN 259.0   18/08/2020  INFORCOL   259
  --FIN BUG 0068006 GZG 27/04/2021
  v_tconsulta := v_tconsulta || ' ORDER BY s.norden';--AITSSD-2546 GZG 31/10/2022
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor
    INTO v_tlinia,
      v_icaptot,
      v_ctipcap,
      v_cimpres,
      v_npargar,
      v_ipritot, --INI/FIN JMG 26/06/2024 I4PPE-2
	  --INI JMC 26/06/2024 AITSSD-19067
	  --v_cgarant; --INI/FIN JMG 26/06/2024 I4PPE-2
	  v_cgarant,
	  v_preglimite;
      --FIN JMC 26/06/2024 AITSSD-19067
    EXIT
  WHEN vr_cursor%NOTFOUND;
    -- INI BUG 48286 11/12/2018 GNRZ ITAU no debe dejar la etiqueta "INCLUIDA" cuando el capital es 0
    -- INI BUG 0048784: impresiÃ³n Null 03/01/2019 GNRZ
    BEGIN
      --
      SELECT sproduc INTO vsproduc FROM seguros WHERE sseguro = psseguro;
      --
    EXCEPTION
    WHEN OTHERS THEN
      --
      --
      SELECT sproduc INTO vsproduc FROM estseguros WHERE sseguro = psseguro;
      --
      --
    END;
    -- FIN BUG 0048784: impresiÃ³n Null 03/01/2019 GNRZ
	--INICIO JMG 26/06/2024 I4PPE-2 - Asistencia diferenciada-PDF
    IF v_npargar = 1 AND v_icaptot = 0 AND NVL(f_parproductos_v(vsproduc, 'REVALORI_VIDA'), 0) = 0 THEN
      -- FIN BUG 48286 11/12/2018 GNRZ  ITAU no debe dejar la etiqueta "INCLUIDA" cuando el capital es 0
		v_trespuegar := NULL;
	  IF v_cgarant = 768 THEN
		IF vsproduc = 900753 THEN
			v_trespuegar := f_amparo_pregdesc(vsproduc,psseguro,v_cgarant,9240,pmodo);
		ELSE
			v_trespuegar := f_amparo_pregdesc(vsproduc,psseguro,v_cgarant,4922,pmodo);
		END IF;
	  END IF;
	 IF v_trespuegar IS NOT NULL THEN
	 	v_tlinia := v_trespuegar;
	 ELSE
        --INI GZG AITSSD-3915 17/07/2025
        IF NVL(pac_parametros.f_pargaranpro_n(vsproduc, 0, v_cgarant, 'GARANT_IMP'), 0) = 1 AND NVL(pac_parametros.f_parproducto_n(vsproduc, 'GARANT_IMP0'), 0) = 1 THEN--GZG AITSSD-3915 24/07/2025
              SELECT '<b>'||tatribu||'</b>'
              INTO v_tlinia
              FROM detvalores
              WHERE cvalor = 126
              AND catribu  = NVL(v_cimpres, 59) -- INCLUIDA
              AND cidioma  = NVL(pcidioma, 8);
     -- INICIO AITSSD-4783
     --ELSIF v_cgarant = 9419 AND vsproduc = 10001 THEN
     ELSIF  NVL(pac_parametros.f_pargaranpro_n(vsproduc,0,9419,'ASISTENCIA_DOMIPRI'), 0) = 1 AND v_cgarant = 9419 THEN
      SELECT tatribu
      INTO v_tlinia
      FROM detvalores
      WHERE cvalor = 126
      AND catribu  = NVL(v_cimpres, 59) -- INCLOSA
      AND cidioma  = NVL(pcidioma, 8);
     ELSIF NVL(pac_parametros.f_pargaranpro_n(vsproduc,0,v_cgarant,'ASISTENCIA_SUBPART'), 0) = 1 AND v_cgarant IN(9694,9695,9696,9697,9698) THEN
     --v_cgarant IN(9694,9695,9696,9697,9698) AND vsproduc = 10001  THEN
     v_tlinia := '';
     -- FIN AITSSD-4783
        ELSE
              SELECT tatribu
              INTO v_tlinia
              FROM detvalores
              WHERE cvalor = 126
              AND catribu  = NVL(v_cimpres, 59) -- INCLOSA
              AND cidioma  = NVL(pcidioma, 8);
        END IF;
        --FIN GZG AITSSD-3915 17/07/2025
	 END IF;
    END IF;
    --INI AITSSD-23276 GZG 14/12/2024
    IF NVL(pac_parametros.f_pargaranpro_n(vsproduc, 0, v_cgarant, 'INCLUIDA_PDF'), 0) = 1 THEN
      SELECT tatribu
      INTO v_tlinia
      FROM detvalores
      WHERE cvalor = 126
      AND catribu  = NVL(v_cimpres, 59) -- INCLUIDA
      AND cidioma  = NVL(pcidioma, 8);
    END IF;
    --FIN AITSSD-23276 GZG 14/12/2024
	--FIN JMG 26/06/2024 I4PPE-2 - Asistencia diferenciada-PDF
    -- INICIO AITSSD-4507
     IF NVL(pac_parametros.f_pargaranpro_n(vsproduc, 0, v_cgarant, 'AP_INCLUIDA_PDF'), 0) = 1 AND pcampo = 1 THEN
      SELECT tatribu
      INTO v_tlinia
      FROM detvalores
      WHERE cvalor = 126
      AND catribu  = NVL(v_cimpres, 59) -- INCLUIDA
      AND cidioma  = NVL(pcidioma, 8);
    END IF;
    -- FIN AITSSD-4507
    IF pcampo = 2 THEN
      --
      --INI 0028151 - 10/02/2017 - CASL - Si el modo de acceso es 1 solo se asigna un espacio en blanco
      --
      IF pmodoacceso = 1 THEN
        --
        v_tlinia := ' ';
        --
      ELSE
        --
        v_tlinia := v_ipritot;
        --
      END IF;
      --
      --FIN 0028151 - 10/02/2017 - CASL
      --
    --INI JMC 26/06/2024 AITSSD-19067
    ELSE
       IF v_ctipcap = 4 AND NVL(v_preglimite,0) <> 0 THEN
          IF NVL(pmodo, 'POL') = 'EST' THEN
             SELECT r.trespue
               INTO v_tlinia
               FROM estpregungaranseg pg, respuestas r
              WHERE sseguro = psseguro
                AND nriesgo = NVL(pnriesgo,1)
                AND cgarant = v_cgarant
                AND nmovimi = NVL(pnmovimi,1)
                AND pg.cpregun = v_preglimite
                AND r.cpregun=pg.cpregun
                AND r.crespue=pg.crespue
                AND r.cidioma=pcidioma;
          --INI  JMC  01/08/2024   AITSSD-19067
          ELSIF NVL(pmodo, 'POL') = 'CAR' THEN
             SELECT r.trespue
               INTO v_tlinia
               FROM pregungarancar pg, respuestas r
              WHERE sseguro = psseguro
                AND nriesgo = NVL(pnriesgo,1)
                AND cgarant = v_cgarant
                AND nmovimi = NVL(pnmovimi,1)
                AND sproces = psproces
                AND pg.cpregun = v_preglimite
                AND r.cpregun=pg.cpregun
                AND r.crespue=pg.crespue
                AND r.cidioma=pcidioma;
          --FIN  JMC  01/08/2024   AITSSD-19067
          ELSE
             SELECT r.trespue
               INTO v_tlinia
               FROM pregungaranseg pg, respuestas r
              WHERE sseguro = psseguro
                AND nriesgo = NVL(pnriesgo,1)
                AND cgarant = v_cgarant
				--INI JMC 16/07/2024 AITSSD-19067
                --AND nmovimi = NVL(pnmovimi,1)
				AND nmovimi = (SELECT MAX(nmovimi) FROM pregungaranseg WHERE sseguro = pg.sseguro AND nriesgo = pg.nriesgo AND cgarant=pg.cgarant AND cpregun=pg.cpregun AND nmovimi <= pnmovimi)
				--FIN JMC 16/07/2024 AITSSD-19067
                AND pg.cpregun = v_preglimite
                AND r.cpregun=pg.cpregun
                AND r.crespue=pg.crespue
                AND r.cidioma=pcidioma;
          END IF;
       END IF;
    --FIN JMC 26/06/2024 AITSSD-19067
    END IF;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_riesgo;
/*****************************************************************
FUNCTION f_importes_riesgo_gar
Devuelve los capitales de un riesgo y de una garantia
param IN psseguro  : codigo de seguro
param IN campo  :   recupera capital o prima
param IN pcgarant  :   codigo garantia
param IN pnriesgo  : n?mero de riesgo
param IN pcidioma  : codigo idioma
param IN pmodo     : modo EST/POL
return             : texto con los capitales del riesgo y garantia
Bug 25583 - 30/01/2013 - FAL
******************************************************************/
FUNCTION f_importes_riesgo_gar(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pcgarant IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL,
    psproces IN NUMBER DEFAULT NULL) --BUG 47494 MPC 08/03/2019 Se crea parametro de entrada.
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(4000);
    v_tlinia    VARCHAR2(50);
    v_tpargar   VARCHAR2(200);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot VARCHAR2(200);
    v_ctipcap garanpro.ctipcap%TYPE;
    v_cimpres garanpro.cimpres%TYPE;
    v_npargar   NUMBER := 0;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_cgarant   NUMBER;
    v_es_admin  NUMBER; --Bug 33145/192146 - 03/12/2014 - AMC
    vncertif    NUMBER;
  BEGIN
    -- BUG 16092 - 12/01/2011 - JMP - AGA RC: Miramos si las garant?as est?n definidas para la actividad del seguro
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := 'SELECT s.cgarant,pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d';
    ELSE
      v_tconsulta := 'SELECT s.cgarant,pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot) d';
    END IF;
    v_tconsulta         := v_tconsulta || ' FROM  garangen g, garanpro p, productos pp, ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' estgaranseg s, estseguros se';
      --INI BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
    ELSIF NVL(pmodo, 'POL') = 'CAR' THEN
      v_tconsulta          := v_tconsulta || ' garancar s, seguros se';
      --FIN BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
    ELSE
      v_tconsulta := v_tconsulta || ' garanseg s, seguros se';
    END IF;
    v_tconsulta := v_tconsulta || ' WHERE g.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = pp.sproduc';
    v_tconsulta := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' AND se.csituac in (0,7,5,2)';
    -- v_tconsulta := v_tconsulta || ' AND s.ffinefe IS NULL';
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      --Bug 33145/192146 - 03/12/2014 - AMC
      v_es_admin := pac_seguros.f_es_col_admin(psseguro, 'EST');
      SELECT ncertif INTO vncertif FROM estseguros WHERE sseguro = psseguro;
    IF v_es_admin    = 1 AND vncertif <> 0 THEN
      v_tconsulta   := v_tconsulta || ' AND s.cobliga = 1';
      v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM estGARANSEG ga WHERE sseguro =' || psseguro;
      v_tconsulta   := v_tconsulta || ' and ga.nmovimi <= (SELECT MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.SSEGURO = GA.SSEGURO AND MV.CMOVSEG!=3 AND MV.NMOVIMI =(select max(nmovimi_cert) from detmovsegurocol WHERE sseguro_0 = ' || psseguro; --|| ' and sseguro_cert =ga.sseguro ';
      IF (pnmovimi  IS NOT NULL) THEN
        v_tconsulta := v_tconsulta || ' AND nmovimi_0 <=' || pnmovimi || '))) ';
      ELSE
        v_tconsulta := v_tconsulta || ')))';
      END IF;
    ELSE
      v_tconsulta   := v_tconsulta || ' AND s.cobliga = 1';
      v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM estGARANSEG WHERE sseguro =' || psseguro;
      IF (pnmovimi  IS NOT NULL) THEN
        v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
        v_tconsulta := v_tconsulta || ')';
      END IF;
    END IF;
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM estseguros seg
      WHERE seg.sseguro = psseguro
      );
  ELSE
    --Bug 33145/192146 - 03/12/2014 - AMC
    v_es_admin := pac_seguros.f_es_col_admin(psseguro, 'POL');
    SELECT ncertif INTO vncertif FROM seguros WHERE sseguro = psseguro;
    --INI BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
    IF NVL(pmodo, 'POL') = 'CAR' THEN
      --
      v_tconsulta := v_tconsulta || ' and s.sproces = '||psproces;
      --
    ELSE
      --FIN BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
      IF v_es_admin    = 1 AND vncertif <> 0 THEN
        v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG ga WHERE sseguro =' || psseguro;
        v_tconsulta   := v_tconsulta || ' and ga.nmovimi <= (SELECT MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.SSEGURO = GA.SSEGURO AND MV.CMOVSEG!=3 AND MV.NMOVIMI =(select max(nmovimi_cert) from detmovsegurocol WHERE sseguro_0 = ' || psseguro; -- || ' and sseguro_cert =ga.sseguro ';
        IF (pnmovimi  IS NOT NULL) THEN
          v_tconsulta := v_tconsulta || ' AND nmovimi_0 <=' || pnmovimi || '))) ';
        ELSE
          v_tconsulta := v_tconsulta || ')))';
        END IF;
      ELSE
        v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro;
        IF (pnmovimi  IS NOT NULL) THEN
          v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
        ELSE
          v_tconsulta := v_tconsulta || ')';
        END IF;
      END IF;
    END IF; --BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  END IF;
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor
    INTO v_cgarant,
      v_tlinia,
      v_icaptot,
      v_ctipcap,
      v_cimpres,
      v_npargar,
      v_ipritot;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF v_npargar = 1 AND v_icaptot = 0 THEN
      SELECT tatribu
      INTO v_tlinia
      FROM detvalores
      WHERE cvalor = 126
      AND catribu  = NVL(v_cimpres, 59) -- INCLOSA
      AND cidioma  = NVL(pcidioma, 8);
    END IF;
    IF pcampo   = 2 THEN
      v_tlinia := v_ipritot;
    END IF;
    IF v_cgarant <> pcgarant THEN
      v_tlinia   := ' ';
    END IF;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_riesgo_gar;
/*****************************************************************
FUNCTION f_garantias_riesgo_partida
Devuelve las garant?as de un riesgo
param IN psseguro  : codigo de seguro
param IN pnriesgo  : n?mero de riesgo
param IN pcidioma  : codigo de idioma
param IN pmodo     : modo EST/POL
return             : texto con las garant?as del riesgo
Bug 19927 - 28/11/2011 - JTS
******************************************************************/
FUNCTION f_garantias_riesgo_partida(
    psseguro IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(2000);
    v_tlinia    VARCHAR2(200);
    v_tpargar   VARCHAR2(200);
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
  BEGIN
    -- BUG 16092 - 12/01/2011 - JMP - AGA RC: Miramos si las garant?as est?n definidas para la actividad del seguro
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    v_tconsulta         := 'SELECT REPLACE(pac_isqlfor_lcol.f_des_garpro(se.sseguro,s.nriesgo,' || NVL(pcidioma, 2) || ',p.cgarant,se.sproduc,''' || pmodo || '''), CHR(39), CHR(39) || CHR(39)) a';
    v_tconsulta         := v_tconsulta || ' FROM garanpro p, ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || 'estgaranseg s, estseguros se';
      v_csituac         := '(0,7,5,2,4)';
    ELSE
      v_tconsulta                                 := v_tconsulta || 'garanseg s, seguros se';
      IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
        -- INI BUG 45008 GNRZ 19/07/2018  Se incluyen  estados posibles de pÃ³liza
        --v_csituac                                 := '(0,7,5,2)';
        v_csituac := '(0,7,5,2,4,3,17,1,7,8,9,10,16)';
        -- FIN BUG 45008 GNRZ 19/07/2018  Se incluyen  estados posibles de pÃ³liza
      ELSE
        v_csituac := '(0,7,5,2,4)';
      END IF;
    END IF;
    v_tconsulta := v_tconsulta || ' WHERE p.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta := v_tconsulta || ' AND p.CACTIVI = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' AND se.csituac in ' || v_csituac;
    -- v_tconsulta := v_tconsulta || ' AND s.ffinefe IS NULL';
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' AND s.cobliga = 1 and s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg WHERE sseguro =' || psseguro;
      IF (pnmovimi      IS NOT NULL) THEN
        v_tconsulta     := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
        v_tconsulta := v_tconsulta || ')';
      END IF;
      SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
        || sproduc
        || ', '
        || cactivi
        || ', p.cgarant, ''GARANT_IMP''), 0) = 0 )'
      INTO v_tpargar
      FROM
        (SELECT seg.sproduc,
          seg.cactivi
        FROM estseguros seg
        WHERE seg.sseguro = psseguro
        );
  ELSE
    v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro;
    IF (pnmovimi  IS NOT NULL) THEN
      v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
    ELSE
      v_tconsulta := v_tconsulta || ')';
    END IF;
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', p.cgarant, ''GARANT_IMP''), 0) = 0 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  END IF;
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_tlinia;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_garantias_riesgo_partida;
/*****************************************************************
FUNCTION f_capitales_riesgo
Devuelve los capitales de un riesgo
param IN psseguro  : codigo de seguro
param IN pnriesgo  : n?mero de riesgo
param IN pmodo     : modo EST/POL
return             : texto con los capitales del riesgo
Bug 19927 - 28/11/2011 - JTS
******************************************************************/
FUNCTION f_importes_riesgo_partida(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(4000);
    v_tlinia    VARCHAR2(50);
    v_tpargar   VARCHAR2(200);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot VARCHAR2(200);
    v_ctipcap garanpro.ctipcap%TYPE;
    v_cimpres garanpro.cimpres%TYPE;
    v_npargar   NUMBER := 0;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
  BEGIN
    -- BUG 16092 - 12/01/2011 - JMP - AGA RC: Miramos si las garant?as est?n definidas para la actividad del seguro
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := 'SELECT pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d';
    ELSE
      v_tconsulta := 'SELECT pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot) d';
    END IF;
    v_tconsulta         := v_tconsulta || ' FROM  garangen g, garanpro p, productos pp, ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' estgaranseg s, estseguros se';
      v_csituac         := '(0,7,5,2,4)';
    ELSE
      v_tconsulta                                 := v_tconsulta || ' garanseg s, seguros se';
      IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
        -- INI BUG 45008 GNRZ 19/07/2018  Se incluyen  estados posibles de pÃ³liza
        --v_csituac                                 := '(0,7,5,2)';
        v_csituac := '(0,7,5,2,4,3,17,1,7,8,9,10,16)';
        -- FIN BUG 45008 GNRZ 19/07/2018  Se incluyen  estados posibles de pÃ³liza
      ELSE
        v_csituac := '(0,7,5,2,4)';
      END IF;
    END IF;
    v_tconsulta := v_tconsulta || ' WHERE g.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = pp.sproduc';
    v_tconsulta := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' AND se.csituac in ' || v_csituac;
    --v_tconsulta := v_tconsulta || ' AND s.ffinefe IS NULL';
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' AND s.cobliga = 1';
      v_tconsulta       := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg WHERE sseguro =' || psseguro;
      IF (pnmovimi      IS NOT NULL) THEN
        v_tconsulta     := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
        v_tconsulta := v_tconsulta || ')';
      END IF;
      SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
        || sproduc
        || ', '
        || cactivi
        || ', g.cgarant, ''GARANT_IMP''), 0) = 0 )'
      INTO v_tpargar
      FROM
        (SELECT seg.sproduc,
          seg.cactivi
        FROM estseguros seg
        WHERE seg.sseguro = psseguro
        );
  ELSE
    v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM garanseg WHERE sseguro =' || psseguro;
    IF (pnmovimi  IS NOT NULL) THEN
      v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
    ELSE
      v_tconsulta := v_tconsulta || ')';
    END IF;
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 0 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  END IF;
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor
    INTO v_tlinia,
      v_icaptot,
      v_ctipcap,
      v_cimpres,
      v_npargar,
      v_ipritot;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF v_npargar = 1 AND v_icaptot = 0 THEN
      SELECT tatribu
      INTO v_tlinia
      FROM detvalores
      WHERE cvalor = 126
      AND catribu  = NVL(v_cimpres, 59) -- INCLOSA
      AND cidioma  = NVL(pcidioma, 8);
    END IF;
    IF pcampo   = 2 THEN
      v_tlinia := v_ipritot;
    END IF;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_riesgo_partida;
/*****************************************************************
FUNCTION f_importes_riesgo_gar
Devuelve los capitales de un riesgo y de una garantia
param IN psseguro  : codigo de seguro
param IN campo  :   recupera capital o prima
param IN pcgarant  :   codigo garantia
param IN pnriesgo  : n?mero de riesgo
param IN pcidioma  : codigo idioma
param IN pmodo     : modo EST/POL
return             : texto con los capitales del riesgo y garantia
Bug 25583 - 30/01/2013 - FAL
******************************************************************/
FUNCTION f_importes_riesgo_gar_partida(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pcgarant IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(4000);
    v_tlinia    VARCHAR2(50);
    v_tpargar   VARCHAR2(200);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot VARCHAR2(200);
    v_ctipcap garanpro.ctipcap%TYPE;
    v_cimpres garanpro.cimpres%TYPE;
    v_npargar   NUMBER := 0;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_cgarant   NUMBER;
  BEGIN
    -- BUG 16092 - 12/01/2011 - JMP - AGA RC: Miramos si las garant?as est?n definidas para la actividad del seguro
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := 'SELECT s.cgarant,pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d';
    ELSE
      v_tconsulta := 'SELECT s.cgarant,pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot) d';
    END IF;
    v_tconsulta         := v_tconsulta || ' FROM  garangen g, garanpro p, productos pp, ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' estgaranseg s, estseguros se';
    ELSE
      v_tconsulta := v_tconsulta || ' garanseg s, seguros se';
    END IF;
    v_tconsulta := v_tconsulta || ' WHERE g.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = pp.sproduc';
    v_tconsulta := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' AND se.csituac in (0,7,5,2)';
    -- v_tconsulta := v_tconsulta || ' AND s.ffinefe IS NULL';
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' AND s.cobliga = 1';
      v_tconsulta       := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM estGARANSEG WHERE sseguro =' || psseguro;
      IF (pnmovimi      IS NOT NULL) THEN
        v_tconsulta     := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
        v_tconsulta := v_tconsulta || ')';
      END IF;
      SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
        || sproduc
        || ', '
        || cactivi
        || ', g.cgarant, ''GARANT_IMP''), 0) = 0 )'
      INTO v_tpargar
      FROM
        (SELECT seg.sproduc,
          seg.cactivi
        FROM estseguros seg
        WHERE seg.sseguro = psseguro
        );
  ELSE
    v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro;
    IF (pnmovimi  IS NOT NULL) THEN
      v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
    ELSE
      v_tconsulta := v_tconsulta || ')';
    END IF;
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 0 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  END IF;
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor
    INTO v_cgarant,
      v_tlinia,
      v_icaptot,
      v_ctipcap,
      v_cimpres,
      v_npargar,
      v_ipritot;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF v_npargar = 1 AND v_icaptot = 0 THEN
      SELECT tatribu
      INTO v_tlinia
      FROM detvalores
      WHERE cvalor = 126
      AND catribu  = NVL(v_cimpres, 59) -- INCLOSA
      AND cidioma  = NVL(pcidioma, 8);
    END IF;
    IF pcampo   = 2 THEN
      v_tlinia := v_ipritot;
    END IF;
    IF v_cgarant <> pcgarant THEN
      v_tlinia   := ' ';
    END IF;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_riesgo_gar_partida;
/*****************************************************************
FUNCTION f_proyeccion_ahorro
param IN psseguro  : codigo de seguro
param IN pnmovimi  : movimiento
param IN pcampo    : Codigo de campo
return             : texto
Bug 19927 - 28/11/2011 - JTS
******************************************************************/
FUNCTION f_proyeccion_ahorro(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER,
    pcampo   IN NUMBER,
    ptablas VARCHAR2 DEFAULT 'EST')
  RETURN VARCHAR2
IS
  CURSOR v_cur
  IS
    SELECT evp.sseguro,
      evp.nmovimi,
      TO_CHAR(evp.nanyo, 'FM990') proyano,
      TO_CHAR(evp.pinttec, 'FM990') proyedad,
      pac_isqlfor_lcol.f_imporige(s.sseguro, evp.ivalres) proyvrasegbasico,
      pac_isqlfor_lcol.f_imporige(s.sseguro, evp.icapfall) proyprimaprot,
      pac_isqlfor_lcol.f_imporige(s.sseguro, evp.iprovest) proyprimaho,
      pac_isqlfor_lcol.f_imporige(s.sseguro, evp.iprovest + evp.icapfall) proypimtot,
      pac_isqlfor_lcol.f_imporige(s.sseguro, evp.iprovmat) proyfondacum,
      pac_isqlfor_lcol.f_imporige(s.sseguro, DECODE(s.sproduc, 6005, 0, 6006, 0, evp.iprima)) proyvalresc
    FROM estevoluprovmatseg evp,
      estseguros s
    WHERE s.sseguro = evp.sseguro
    AND s.sseguro   = psseguro
    AND evp.nmovimi = pnmovimi;
  CURSOR v_cur_pol
  IS
    SELECT evp.sseguro,
      evp.nmovimi,
      TO_CHAR(evp.nanyo, 'FM990') proyano,
      TO_CHAR(evp.pinttec, 'FM990') proyedad,
      pac_isqlfor_lcol.f_imporig(s.sseguro, evp.ivalres) proyvrasegbasico,
      pac_isqlfor_lcol.f_imporig(s.sseguro, evp.icapfall) proyprimaprot,
      pac_isqlfor_lcol.f_imporig(s.sseguro, evp.iprovest) proyprimaho,
      pac_isqlfor_lcol.f_imporig(s.sseguro, evp.iprovest + evp.icapfall) proypimtot,
      pac_isqlfor_lcol.f_imporig(s.sseguro, evp.iprovmat) proyfondacum,
      pac_isqlfor_lcol.f_imporig(s.sseguro, DECODE(s.sproduc, 6005, 0, 6006, 0, evp.iprima)) proyvalresc
    FROM evoluprovmatseg evp,
      seguros s
    WHERE s.sseguro         = evp.sseguro
    AND s.sseguro           = psseguro
    AND evp.nmovimi         = pnmovimi;
  v_tresult VARCHAR2(4000) := '';
BEGIN
  IF ptablas = 'EST' THEN
    FOR i IN v_cur
    LOOP
      IF pcampo    = 1 THEN
        v_tresult := v_tresult || i.proyano || ' \par ';
      ELSIF pcampo = 2 THEN
        v_tresult := v_tresult || i.proyedad || ' \par ';
      ELSIF pcampo = 3 THEN
        v_tresult := v_tresult || i.proyvrasegbasico || ' \par ';
      ELSIF pcampo = 4 THEN
        v_tresult := v_tresult || i.proyprimaprot || ' \par ';
      ELSIF pcampo = 5 THEN
        v_tresult := v_tresult || i.proyprimaho || ' \par ';
      ELSIF pcampo = 6 THEN
        v_tresult := v_tresult || i.proypimtot || ' \par ';
      ELSIF pcampo = 7 THEN
        v_tresult := v_tresult || i.proyvalresc || ' \par ';
      ELSIF pcampo = 8 THEN
        v_tresult := v_tresult || i.proyfondacum || ' \par ';
      END IF;
    END LOOP;
  ELSE
    FOR i IN v_cur_pol
    LOOP
      IF pcampo    = 1 THEN
        v_tresult := v_tresult || i.proyano || ' \par ';
      ELSIF pcampo = 2 THEN
        v_tresult := v_tresult || i.proyedad || ' \par ';
      ELSIF pcampo = 3 THEN
        v_tresult := v_tresult || i.proyvrasegbasico || ' \par ';
      ELSIF pcampo = 4 THEN
        v_tresult := v_tresult || i.proyprimaprot || ' \par ';
      ELSIF pcampo = 5 THEN
        v_tresult := v_tresult || i.proyprimaho || ' \par ';
      ELSIF pcampo = 6 THEN
        v_tresult := v_tresult || i.proypimtot || ' \par ';
      ELSIF pcampo = 7 THEN
        v_tresult := v_tresult || i.proyvalresc || ' \par ';
      ELSIF pcampo = 8 THEN
        v_tresult := v_tresult || i.proyfondacum || ' \par ';
      END IF;
    END LOOP;
  END IF;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_proyeccion_ahorro;
