/*****************************************************************
FUNCTION f_amparos_pago
param IN psidepag  :
param IN pcidioma  : Codigo de campo
return             : texto
Bug 20029 - 28/11/2011 - JTS
******************************************************************/
FUNCTION f_amparos_pago(
    psidepag IN NUMBER,
    pcidioma IN NUMBER,
    pcamp    IN NUMBER)
  RETURN VARCHAR2
IS
  v_tresult VARCHAR2(4000);
BEGIN
  IF pcamp = 1 THEN
    FOR i IN
    (SELECT g.trotgar
    FROM sin_tramita_pago_gar stpg,
      garangen g
    WHERE stpg.sidepag = psidepag
    AND g.cidioma      = pcidioma
    AND stpg.cgarant   = g.cgarant
    ORDER BY 1
    )
    LOOP
      v_tresult := v_tresult || i.trotgar || ' \par ';
    END LOOP;
  ELSIF pcamp = 2 THEN
    FOR i IN
    (SELECT g.tgarant
    FROM sin_tramita_pago_gar stpg,
      garangen g
    WHERE stpg.sidepag = psidepag
    AND g.cidioma      = pcidioma
    AND stpg.cgarant   = g.cgarant
    ORDER BY 1
    )
    LOOP
      v_tresult := v_tresult || i.tgarant || ' \par ';
    END LOOP;
  ELSIF pcamp = 3 THEN
    SELECT fu_formato(p_valor => SUM(g.iprianu)) -- BUG 0035431/0203621 - 29/04/2015 - JAE - Formato numÃ¿Â©rico
    INTO v_tresult
    FROM sin_tramita_pago stp,
      sin_tramita_pago_gar stpg,
      sin_siniestro ss,
      garanseg g
    WHERE stp.sidepag = psidepag
    AND stp.sidepag   = stpg.sidepag
    AND ss.nsinies    = stp.nsinies
    AND g.cgarant     = stpg.cgarant
    AND g.sseguro     = ss.sseguro
    AND ss.fsinies BETWEEN g.finiefe AND NVL(g.ffinefe, f_sysdate);
  END IF;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_amparos_pago;
/*****************************************************************
FUNCTION f_cod_barras
param IN psseguro  :
param IN pnmovimi  :
return             : texto
Bug 19927 - 29/12/2011 - JTS
Bug 14374 - 09/09/2014 - JJGQ se adiciona Funcion para que el codigo de barras
sea parametrico
******************************************************************/
FUNCTION f_cod_barras(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER,
    pcdup    IN NUMBER DEFAULT 0,
    pnrecibo IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
  v_tresult VARCHAR2(4000);
  vcod      VARCHAR2(100);
  vnrec     VARCHAR2(100);
  vtot      VARCHAR2(100);
  vfefec    VARCHAR2(100);
  v_nrecibo recibos.nrecibo%TYPE;
  vcramo     NUMBER;
  vcccompani NUMBER;
  v_cod_ean  NUMBER;
  v_ncertif  NUMBER;
  flimite    DATE;
  vitotalr   NUMBER; -- Bug 37028/212553 - 25/08/2015 - AMC
  v_ctiprec  NUMBER; -- Bug 48662 14/01/2019 - GZG
  --
  --INI BUG 0028151 - 03/03/2017 - CASL - Se crea nueva variable
  --INI BUG 0028151 - 09/03/2017 - CASL - Se crea nueva variable
  --
  v_ult_nrecibo NUMBER;
  --
  --FIN BUG 0028151 - 09/03/2017 - CASL
  --FIN BUG 0028151 - 03/03/2017 - CASL
  --
  -- INI SPV 19/02/2019 0049630: 900720-exequias
  v_cod_bar_exeq CONSTANT NUMBER(20):= 7707274730192;
  v_sproduc seguros.sproduc%TYPE;
  -- FIN SPV 19/02/2019 0049630: 900720-exequias
BEGIN
  --
  --INI BUG 0028151 - 03/03/2017 - CASL - Se valida si la poliza es administrada o agrupada
  --INI BUG 0028151 - 09/03/2017 - CASL - Se valida si la poliza es administrada o agrupada
  --
  --INI BUG 0036002 - 26/07/2017 - CASL - Se valida si el recibo viene nulo
  --
  IF pnrecibo IS NULL THEN
    --
    v_ult_nrecibo := f_recibo_mov(psseguro => psseguro, pnmovimi => pnmovimi);
    --
  END IF;
  --
  --FIN BUG 0036002 - 26/07/2017 - CASL
  --
  --FIN BUG 0028151 - 09/03/2017 - CASL
  --FIN BUG 0028151 - 03/03/2017 - CASL
  --
  --INI BUG 0048662 - 30/01/2019 - GZG - Se agrega condicional para omitir valor absoluto cuando el recibo es tipo extorno
  SELECT ctiprec
  INTO v_ctiprec
  FROM recibos
  WHERE nrecibo = pnrecibo;
  IF v_ctiprec  = 9 THEN
    RETURN NULL;
  END IF;
  --FIN BUG 0048662 - 30/01/2019 - GZG
  IF pcdup = 1 THEN
    RETURN NULL;
  END IF;
  SELECT cramo,
    DECODE(ccompani, 325, 0, ccompani),
    ncertif
  INTO vcramo,
    vcccompani,
    v_ncertif
  FROM seguros
  WHERE sseguro = psseguro;
  IF vcramo     = 103 AND pnrecibo IS NULL AND v_ncertif <> 0 THEN
    RETURN NULL;
  END IF;
  IF pnrecibo IS NULL THEN
    BEGIN
      SELECT nrecibo
      INTO v_nrecibo
      FROM recibos
      WHERE sseguro = psseguro
      AND nrecibo   =
        (SELECT MAX(nrecibo)
        FROM recibos r
        WHERE r.sseguro = psseguro
        AND r.nmovimi   = pnmovimi
        AND r.nrecibo   = NVL(v_ult_nrecibo, r.nrecibo)
        ); --BUG 0028151 - 09/03/2017 - CASL - Se filtra por fecha de efecto del movimiento
    EXCEPTION
    WHEN OTHERS THEN
      v_nrecibo := 0;
    END;
  ELSE
    v_nrecibo := NVL(v_ult_nrecibo, pnrecibo); --BUG 0028151 - 09/03/2017 - CASL - Se asigna el recibo
  END IF;
  -- Bug 37028/212553 - 25/08/2015 - AMC
  BEGIN
    SELECT itotalr INTO vitotalr FROM vdetrecibos WHERE nrecibo = v_nrecibo;
  EXCEPTION
  WHEN NO_DATA_FOUND THEN
    NULL;
  END;
  IF vitotalr = 0 THEN
    RETURN NULL;
  END IF;
  -- Fi Bug 37028/212553 - 25/08/2015 - AMC
  -- BUG 24878 - 28/11/2012 - ECP -  Se utilza la funci?n f_recibo_tipo
  --      v_nrecibo := NVL(pnrecibo,
  --                       NVL(pac_isqlfor_lcol.f_recibo_tipo(psseguro, pnmovimi, 6),
  --                           NVL(pac_isqlfor_lcol.f_recibo_tipo(psseguro, pnmovimi, 3),
  --                               pac_isqlfor_lcol.f_recibo_tipo(psseguro, pnmovimi, 4))));
  --Bug 0014374 - 09/09/2014 - JJQG - Utilizamos Funcion de Subtablas para retornar Cod EAN
  --Bug 0035887 - 10/06/2014 - JMG - se modifica la fecha para que llame a la funcion f_flimitepag
  v_cod_ean := pac_subtablas.f_vsubtabla(-1, 3032, 33, 1, vcccompani, vcramo);
  -- RMGA 23/11/2015 BUG 0017255: Error fechas limite pago cÃ¿Â³digo barras se envia motivo de pago
  --
  --INI BUG 0033953 - 26/05/2017 - CASL - Se obtiene el valor absoluto de los totales del recibo
  --
  -- INI SPV 19/02/2019 0049630: 900720-exequias
  BEGIN
    -- Se halla el codigo del producto de la poliza
    SELECT sproduc
    INTO v_sproduc
    FROM seguros
    WHERE sseguro = psseguro;
  EXCEPTION
  WHEN OTHERS THEN
    v_sproduc := 0;
  END;
  --
  IF NVL(f_parproductos_v(v_sproduc, 'COD_BARRA_EXEQUIAL'), 0) = 1 THEN
    -- Solo aplicara para Exequial Colectivo Nominado
    v_cod_ean := v_cod_bar_exeq;
  END IF;
  -- FIN SPV 19/02/2019 0049630: 900720-exequias
  SELECT '415'
    || v_cod_ean cod,
    '-8020'
    || LPAD(r.nrecibo, 20, '0') nrec,
    '-3900'
    || LPAD(NVL(ROUND(ABS(vd.itotalr), 0), 0), ((TRUNC(LENGTH(ROUND(ABS(vd.itotalr), 0)) / 2) + (((LENGTH(ROUND(ABS(vd.itotalr), 0)) / 2) - TRUNC(LENGTH(ROUND(ABS(vd.itotalr), 0)) / 2)) * 2)) * 2), '0') tot,
    '-96'
    || TO_CHAR(NVL(f_flimitepag(psseguro, pnmovimi, m.cmotmov, 1, pnrecibo), (m.femisio + pac_propio_lcol.f_numdias_periodo_gracia(s.sseguro))), 'yyyymmdd') fefec
    --
    --FIN BUG 0033953 - 26/05/2017 - CASL
    --
  INTO vcod,
    vnrec,
    vtot,
    vfefec
  FROM vdetrecibos_monpol vd,
    recibos r,
    seguros s,
    productos pp,
    movseguro m
  WHERE vd.nrecibo = r.nrecibo
  AND r.sseguro    = s.sseguro
  AND s.sseguro    = m.sseguro
  AND r.nmovimi    = m.nmovimi
  AND r.sseguro    = psseguro
  AND s.sproduc    = pp.sproduc
  AND r.nmovimi    = pnmovimi
  AND r.nrecibo    = v_nrecibo; -- BUG 24878 - 28/11/2012 - ECP -  Se utilza la funci?n f_recibo_tipo
  v_tresult       := vcod || vnrec || vtot || vfefec;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_cod_barras;
/*****************************************************************
FUNCTION f_flimitepag
param IN psseguro  :
param IN pnmovimi  :
param IN pcmotmov
return             : texto
Bug 35887 - 10/06/2015 - JMG Se crea funcion para el limite de pago
******************************************************************/
FUNCTION f_flimitepag(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER,
    pcmotmov IN NUMBER,
    pcodbarr IN NUMBER DEFAULT 0,
    pnrecibo IN NUMBER DEFAULT NULL)
  RETURN DATE
IS
  vfecha      DATE;
  vemisio     DATE;
  vefecto     DATE;
  vmigrada    VARCHAR2(1000);
  vtiprecibo  NUMBER;
  vvalidfelim NUMBER;
  v_sproduc   NUMBER;
  vcforpag    NUMBER;
  vcramo      NUMBER;
  --Bug 37363
  vfracci  NUMBER;
  vnanuali NUMBER;
BEGIN
  -- Solucion BUG 20892
  BEGIN
    SELECT sproduc INTO v_sproduc FROM estseguros WHERE sseguro = psseguro;
  EXCEPTION
  WHEN OTHERS THEN
    BEGIN
      SELECT sproduc INTO v_sproduc FROM seguros WHERE sseguro = psseguro;
    EXCEPTION
    WHEN OTHERS THEN
      v_sproduc := NULL;
    END;
  END;
  BEGIN
    SELECT polissa_ini INTO vmigrada FROM cnvpolizas WHERE sseguro = psseguro;
  EXCEPTION
  WHEN OTHERS THEN
    vmigrada := NULL;
  END;
  SELECT cforpag,
    cramo,
    nanuali
  INTO vcforpag,
    vcramo,
    vnanuali
  FROM seguros
  WHERE sseguro = psseguro;
  BEGIN
    IF pnrecibo IS NULL THEN
      SELECT ctiprec,
        GREATEST(femisio, fefecto),
        nfracci
      INTO vtiprecibo,
        vefecto,
        vfracci
      FROM recibos
      WHERE sseguro = psseguro
      AND nrecibo   =
        (SELECT MAX(r2.nrecibo)
        FROM recibos r2,
          movseguro m2,
          movrecibo mv2
        WHERE r2.sseguro = psseguro
        AND r2.nmovimi  <= pnmovimi
        AND m2.sseguro   = r2.sseguro
        AND m2.nmovimi   = r2.nmovimi
          --AND m2.cmotmov IN(100, 404, 407, 996, 997, 700)   --Alta de certificados y cartera
        AND mv2.nrecibo  = r2.nrecibo
        AND mv2.cestrec  = 0
        AND r2.cestaux   = 0 --SÃ¿Â³lo los agrupados
        AND mv2.fmovfin IS NULL
        );
    ELSE
      SELECT ctiprec,
        GREATEST(femisio, fefecto),
        nfracci
      INTO vtiprecibo,
        vefecto,
        vfracci
      FROM recibos
      WHERE sseguro = psseguro
      AND nrecibo   = pnrecibo;
    END IF;
  EXCEPTION
  WHEN OTHERS THEN
    vtiprecibo := 0;
    vefecto    := NULL;
    vfracci    := 0;
  END;
  IF pcmotmov = 500 AND vtiprecibo = 4 THEN
    vfecha   := 1 + vefecto;
  ELSE
    IF vcramo     = 101 AND pcodbarr = 0 THEN
      IF (vfracci = 0 AND vnanuali = 1) THEN --Ramo Vida ind, forma de pago dif a anual o Ã¿Âºnica y primer recibo, no muestra fecha limite de pago y primera anualidad
        vfecha   := NULL;
      ELSE
        vfecha := vefecto + pac_propio_lcol.f_numdias_periodo_gracia(psseguro);
      END IF;
    ELSE
      -- INI 17329 JRNC se valida que el producto este configurado para que tome 45 dias de gracias y no sea para el campos del codbarras
      IF NVL(pac_parametros.f_parproducto_n(v_sproduc, 'DIASGRAUAT'), 0) = 1 THEN --and pcodbarr = 0 THEN segÃ¿Âºn solicitud nueva en el bug se quita la validacion para que el codbarras tambien se modifique
        vfecha                                                          := vefecto + NVL(pac_parametros.f_parproducto_n(v_sproduc, 'DIASAUT'), 0);
      ELSE
        vfecha := vefecto + pac_propio_lcol.f_numdias_periodo_gracia(psseguro);
      END IF;
      -- FIN 17329 JRNC se valida que el producto este configurado para que tome 45 dias de gracias y no sea para el campos del codbarras
    END IF;
  END IF;
  RETURN vfecha;
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_flimitepag;
/*****************************************************************
FUNCTION f_benespseg
param IN psidepag  :
param IN pcidioma  :
param IN pcamp     : Codigo de campo
return             : texto
Bug 19927 - 29/12/2011 - JTS
BUG 37907 - 17/10/2017 - LGG
******************************************************************/
FUNCTION f_benespseg(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER,
    pcidioma IN NUMBER,
    pcamp    IN NUMBER)
  RETURN VARCHAR2
IS
  v_tresult  VARCHAR2(4000);
  v_tresult2 VARCHAR2(4000);--BUG 0043516 - 24/05/2018 - CASL - Se crea nueva variable
  --Inicio QT44484 Amantium 25/09/2018
  v_ncont   NUMBER := 0;
  v_sproduc NUMBER;
  v_nerror  NUMBER;
  --Fin QT44484 Amantium 25/09/2018
BEGIN
  --
  --Inicio QT44484 Amantium 25/09/2018
  --Luego de algunas pruebas realizadas para el producto 70107, se puede concluir que
  --la baja de un beneficiario en la tabla benespseg implica la no existencia de un
  --registro del beneficiario para el movimiento consultado y movimientos posteriores.
  --Dado esto, a la baja de un beneficiario, en lugar de retornar su informaciÃ³n encontrada
  --en registros anteriores al movimiento consultado, retornaremos NULL.
  v_nerror := pac_seguros.f_get_sproduc(psseguro, 'POL', v_sproduc);
  FOR i IN
  (SELECT b.sperson
  FROM benespseg b
  WHERE b.sseguro = psseguro
  AND b.nmovimi   = pnmovimi
  )
  LOOP
    v_ncont := v_ncont + 1;
  END LOOP;
  /* Inicio 08/11/2018  ARM    Bug 0047474 */
  IF v_ncont = 0 THEN
    FOR i IN
    (SELECT b.sperson
    FROM benespseg b
    WHERE b.sseguro = psseguro
    AND b.nmovimi   =
      (SELECT MAX(nmovimi) FROM benespseg WHERE sseguro = psseguro
      )
    )
    LOOP
      v_ncont := v_ncont + 1;
    END LOOP;
  END IF;
  /* Fin 08/11/2018  ARM    Bug 0047474 */
  IF NVL(pac_parametros.f_parproducto_n(v_sproduc, 'VIG_BENEFICIARIO'), 0) = 1 AND v_ncont = 0 AND v_nerror = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;
  --
  --Fin QT44484 Amantium 25/09/2018
  --
  ---INI BUG GZG 0054426 03/09/2019
BEGIN
  SELECT sproduc INTO v_sproduc FROM seguros WHERE sseguro = psseguro;
EXCEPTION
WHEN OTHERS THEN
  BEGIN
    SELECT sproduc INTO v_sproduc FROM estseguros WHERE sseguro = psseguro;
  EXCEPTION
  WHEN OTHERS THEN
    v_sproduc := NULL;
  END;
END;
  ---FIN BUG GZG 0054426 03/09/2019
  FOR i IN
  (SELECT SUBSTR(f_dades_persona(ben.sperson, 8, pcidioma, 'POL'), 1, 5)
    || ' '
    || f_dades_persona(ben.sperson, 1, pcidioma, 'POL') idbenef,
    --INI AITSSD-6023 GZG 06/10/2025 cuando es una persona juridica no debe concatenar (se estaba duplicando)
    DECODE(( SELECT p2.ctipide FROM per_personas p2 WHERE p2.sperson = ben.sperson AND ROWNUM = 1),37,
    (SELECT NVL(TRIM(tapelli1), TRIM(tnombre))
    FROM per_detper
    WHERE sperson = ben.sperson
    AND ROWNUM    = 1),(SELECT TRIM(tnombre)
      || ' '
      || TRIM(tapelli1
      || ' '
      || tapelli2)
    FROM per_detper
    WHERE sperson = ben.sperson
    AND ROWNUM    = 1
    )) nombenef,
    --FIN AITSSD-6023 GZG 06/10/2025
    ff_desvalorfijo(1054, pcidioma, ben.cparen) parentbenef,
    ben.pparticip porcbenef,
    f_dades_persona(ben.sperson_tit, 8, pcidioma, 'POL')
    || ' '
    || f_dades_persona(ben.sperson_tit, 1, pcidioma, 'POL') contbenef,
    NULL acrebenef,
    -- inicio 164.0 22/10/2018  AAN   0046937 se ajusta funcion F_BENESPSEG
    'S' benefaccid,
    -- fin 164.0 22/10/2018  AAN   0046937 se ajusta funcion F_BENESPSEG
    -- Ini  47966 -- ECP -- 11/12/2019
    --INI  22/11/2024  JMC  AITSSD-1603 antes AITSSD-230072
    --NVL((-- BUG 0058142 GZG 22/01/2020
    ---- INI BUG 0063587 GZG 23/09/2020 -- se agrega alias a la consulta y tipos de telefono 5 y 6
    --SELECT p.tvalcon
    --FROM per_contactos p
    --WHERE p.sperson = ben.sperson
    --AND p.ctipcon   =
    --  (SELECT MIN(p2.ctipcon)
    --    FROM per_contactos p2
    --    WHERE p2.sperson = ben.sperson
    --      AND p2.ctipcon IN(1,5,6))--Se filtra por telefono,telefono solicitud y telefono celular
    --AND p.cmodcon   =
    --  (SELECT MAX(p3.cmodcon)
    --  FROM per_contactos p3
    --  WHERE p3.sperson = ben.sperson
    --  AND p3.ctipcon   = p.ctipcon)
    --  -- FIN BUG 0063587 GZG 23/09/2020
    --  -- Fin  47966 -- ECP -- 11/12/2019
    --  -- INI BUG 0058142 GZG 22/01/2020
    --),(SELECT tvalcon
    --FROM per_contactos
    --WHERE sperson = ben.sperson
    --AND rownum = 1)) telefonobnf,
	pac_isqlfor.f_telefono(ben.sperson) telefonobnf,
    --FIN  22/11/2024  JMC  AITSSD-1603 antes AITSSD-230072
    --FIN BUG 0058142 GZG 22/01/2020
    --pac_isqlfor.f_poblacion(ben.sperson, 1) bnfpoblac,  -- RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios Se pone en comentario ya que se va a realizar el proceso abajo en el recorrido de cursor
    NULL bnfpoblac, -- RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios Se envia NULL ya que se va a realizar el proceso abajo en el recorrido de cursor
    -- INI RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios Se pone en comentario ya que se va a realizar el proceso abajo en el recorrido de cursor
    /*PAC_ISQLFOR_LCOL.F_DIRECCION(BEN.SPERSON, (select max(CDOMICI) as RMAX_DOMICI from PER_DIRECCIONES where SPERSON = BEN.SPERSON)) -- BUG 0021554/0021678/0021636 SYT 14/10/2015 Se ajusta ya que se puede tener mas de un beneficiario
    (SELECT pac_isqlfor_lcol.f_direccion(ben.sperson, rmax_domici,
    'POL')
    FROM (SELECT MAX(cdomici) AS rmax_domici
    FROM per_direcciones
    WHERE sperson = (SELECT sperson
    FROM benespseg
    WHERE sseguro = psseguro
    AND cgarant = 0
    AND nmovimi =
    (SELECT MAX(nmovimi)
    FROM benespseg
    WHERE sseguro = psseguro
    AND nmovimi <= pnmovimi))))*/
    NULL bnfdirec,
    ben.sperson, -- Bug 0019273-VCG-15/07/2015 -- RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios Se envia NULL ya que se va a realizar el proceso abajo en el recorrido de cursor
    -- FIN RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios Se pone en comentario ya que se va a realizar el proceso abajo en el recorrido de cursor
    (
    SELECT fnacimi
    FROM per_personas
    WHERE sperson = ben.sperson
    ) fechanacim -- Bug 31777 - LRGG - Adicion de la fecha de Nacimiento
  FROM benespseg ben
  WHERE ben.sseguro = psseguro
  AND cgarant       = 0 --beneficiarios de riesgo
  ---INI BUG GZG 0054426 03/09/2019
  --INI BUG GZG 0057748 17/01/2019 SE ADICIONA FILTRO 'and be.cgarant = ben.cgarant'
  AND ((ben.CTIPBEN = (select NVL(max(be.CTIPBEN),3) FROM benespseg be WHERE be.sseguro = psseguro and be.ctipben <= 2 and be.nmovimi = ben.nmovimi  and be.cgarant = ben.cgarant) AND NVL(pac_parametros.f_parproducto_n(v_sproduc, 'BEN_ENDOSO_AU'), 0) = 1)--BUG 0055009 18/09/2019 GZG se agrega nmovimi
  --FIN BUG GZG 0057748 17/01/2019
  OR (ben.CTIPBEN IS NOT NULL AND NVL(pac_parametros.f_parproducto_n(v_sproduc, 'BEN_ENDOSO_AU'), 0) = 0))
  ---FIN BUG GZG 0054426 03/09/2019
  AND nmovimi       =
    (SELECT MAX(nmovimi)
    FROM benespseg
    WHERE sseguro = psseguro
    AND nmovimi  <= pnmovimi
    )
  ORDER BY nriesgo ASC,
    sperson_tit ASC,
    pparticip DESC,
    fmovimi ASC,
    ROWID ASC
  )
  LOOP
    IF pcamp     = 1 THEN
      v_tresult := v_tresult || i.idbenef || ' \par ';
    ELSIF pcamp  = 2 THEN
      v_tresult := v_tresult || i.nombenef || ' \par ';
    ELSIF pcamp  = 3 THEN
      v_tresult := v_tresult || i.parentbenef || ' \par ';
    ELSIF pcamp  = 4 THEN
      v_tresult := v_tresult || i.porcbenef || ' \par ';
    ELSIF pcamp  = 5 THEN
      v_tresult := v_tresult || i.contbenef || ' \par ';
    ELSIF pcamp  = 6 THEN
      v_tresult := v_tresult || i.acrebenef || ' \par ';
    ELSIF pcamp  = 7 THEN
      v_tresult := v_tresult || i.telefonobnf || ' \par ';
    ELSIF pcamp  = 8 THEN
      -- INI RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios. Se busca en asegurados - tomadores - La Direccion de Residencia -  La Maxima Direccion
      --v_tresult := v_tresult || i.bnfpoblac || ' \par ';
     --INI DV 0062334 03/08/2020
       BEGIN
        SELECT DISTINCT pac_isqlfor.f_poblacion(i.sperson, rmax_domici)
           || ' \par '
        INTO v_tresult2--BUG  0067837 GZG 12/05/2021
        FROM
         (
            SELECT a.cdomici AS rmax_domici
              FROM benespseg a
              WHERE a.sseguro = psseguro
              AND a.sperson   = i.sperson
              AND a.cgarant   = 0
              AND a.nmovimi   =
                       (SELECT MAX(nmovimi)
                        FROM benespseg
                        WHERE sseguro = psseguro
                        AND nmovimi  <= pnmovimi
                        )
          );
           IF v_tresult2 = ' \par ' THEN--BUG  0067837 GZG 12/05/2021
          RAISE NO_DATA_FOUND;
          ELSE --BUG  0067837 GZG 12/05/2021
          v_tresult := v_tresult ||v_tresult2;--BUG  0067837 GZG 12/05/2021
        END IF;
       EXCEPTION
      WHEN NO_DATA_FOUND THEN
      -- FIN DV 0062334 03/08/2020
      BEGIN
        --INICIO BUG 37907 - 17/10/2017 - LGG
        SELECT DISTINCT pac_isqlfor.f_poblacion(i.sperson, rmax_domici) --SELECT PAC_ISQLFOR.F_POBLACION(i.SPERSON, RMAX_DOMICI)
          --FIN BUG 37907 - 17/10/2017 - LGG
          || ' \par '
        INTO v_tresult
        FROM
          -- Ini  47966 -- ECP -- 11/12/2019
          (
          SELECT MAX(b.cdomici) AS rmax_domici
          FROM benespseg a,
            asegurados b
          WHERE a.sseguro = psseguro
          AND a.sseguro   = b.sseguro
          AND a.sperson   = b.sperson
          AND a.sperson   = i.sperson
          AND a.cgarant   = 0
          AND a.nmovimi   =
            (SELECT MAX(nmovimi)
            FROM benespseg
            WHERE sseguro = psseguro
            AND nmovimi  <= pnmovimi
            )
          );
        -- Fin  47966 -- ECP -- 11/12/2019
        -- INI BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
        IF v_tresult = ' \par ' THEN
          RAISE NO_DATA_FOUND;
        END IF;
        -- FIN BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
      EXCEPTION
      WHEN NO_DATA_FOUND THEN
        BEGIN
          --INICIO BUG 37907 - 17/10/2017 - LGG
          SELECT DISTINCT pac_isqlfor.f_poblacion(i.sperson, rmax_domici) --SELECT PAC_ISQLFOR.F_POBLACION(i.SPERSON, RMAX_DOMICI)
            --FIN BUG 37907 - 17/10/2017 - LGG
            || ' \par '
          INTO v_tresult
          FROM
            -- Ini  47966 -- ECP -- 11/12/2019
            (
            SELECT MAX(b.cdomici) AS rmax_domici
            FROM benespseg a,
              tomadores b
            WHERE a.sseguro = psseguro
            AND a.sseguro   = b.sseguro
            AND a.sperson   = b.sperson
            AND a.sperson   = i.sperson
            AND a.cgarant   = 0
            AND a.nmovimi   =
              (SELECT MAX(nmovimi)
              FROM benespseg
              WHERE sseguro = psseguro
              AND nmovimi  <= pnmovimi
              )
            );
          -- Fin  47966 -- ECP -- 11/12/2019
          -- INI BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
          IF v_tresult = ' \par ' THEN
            RAISE NO_DATA_FOUND;
          END IF;
          -- FIN BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
        EXCEPTION
        WHEN NO_DATA_FOUND THEN
          BEGIN
            SELECT pac_isqlfor.f_poblacion(i.sperson, MAX(cdomici))
              || ' \par ' AS rmax_domici -- BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
            INTO v_tresult
            FROM per_direcciones
            WHERE sperson = i.sperson
            AND ctipdir   = 9;
            -- INI BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
            IF v_tresult = ' \par ' THEN
              RAISE NO_DATA_FOUND;
            END IF;
            -- FIN BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
          EXCEPTION
          WHEN NO_DATA_FOUND THEN
            BEGIN
              SELECT pac_isqlfor.f_poblacion(i.sperson, MAX(cdomici))
                || ' \par ' AS rmax_domici -- BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
              INTO v_tresult
              FROM per_direcciones
              WHERE sperson = i.sperson;
            EXCEPTION
            WHEN OTHERS THEN
              RETURN ('');
            END;
          END;
        END;
      END;
      -- INI DV 0062334 03/08/2020
      END;
      -- FIN DV 0062334 03/08/2020
      -- FIN RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios. Se busca en asegurados - tomadores - La Direccion de Residencia -  La Maxima Direccion
    ELSIF pcamp = 9 THEN
      -- INI RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios. Se busca en asegurados - tomadores - La Direccion de Residencia -  La Maxima Direccion
      --v_tresult := v_tresult || i.bnfdirec || ' \par ';
      -- INI DV 0062334 03/08/2020
      BEGIN
         SELECT PAC_ISQLFOR_LCOL.F_DIRECCION(i.SPERSON, RMAX_DOMICI)
            || ' \par '
        INTO v_tresult2
        FROM
          ( SELECT a.cdomici AS rmax_domici
              FROM benespseg a
              WHERE a.sseguro = psseguro
              AND a.sperson   = i.sperson
              AND a.cgarant   = 0
              AND a.nmovimi   =
                       (SELECT MAX(nmovimi)
                        FROM benespseg
                        WHERE sseguro = psseguro
                        AND nmovimi  <= pnmovimi
                        )
          );
        IF v_tresult2 = ' \par ' THEN
          RAISE NO_DATA_FOUND;
        END IF;
      EXCEPTION
      WHEN NO_DATA_FOUND THEN
      -- FIN DV 0062334 03/08/2020
      BEGIN
        --Inicio bug 0039987 - YMG
        SELECT PAC_ISQLFOR_LCOL.F_DIRECCION(i.SPERSON, RMAX_DOMICI)
          --Fin bug
          || ' \par '
        INTO v_tresult2--BUG 0043516 - 24/05/2018 - CASL - Se cambia la variable del resultado
        FROM
          (SELECT b.cdomici AS rmax_domici
          FROM benespseg a,
            asegurados b
          WHERE a.sseguro = psseguro
          AND a.sseguro   = b.sseguro
          AND a.sperson   = b.sperson
          AND a.sperson   = i.sperson
          AND a.cgarant   = 0
          AND a.nmovimi   =
            (SELECT MAX(nmovimi)
            FROM benespseg
            WHERE sseguro = psseguro
            AND nmovimi  <= pnmovimi
            )
          );
        -- INI BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
        IF v_tresult2 = ' \par ' THEN--BUG 0043516 - 24/05/2018 - CASL - Se cambia la variable del resultado
          RAISE NO_DATA_FOUND;
        END IF;
        -- FIN BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
      EXCEPTION
      WHEN NO_DATA_FOUND THEN
        BEGIN
          --Inicio bug 0039987 - YMG
          --Ini 47966 -- ECP -- 11/12/2018
          SELECT PAC_ISQLFOR_LCOL.F_DIRECCION(i.SPERSON, RMAX_DOMICI)
            --Fin bug 0039987
            || ' \par '
          INTO v_tresult2--BUG 0043516 - 24/05/2018 - CASL - Se cambia la variable del resultado
          FROM
            (SELECT MAX(b.cdomici) AS rmax_domici
            FROM benespseg a,
              tomadores b
            WHERE a.sseguro = psseguro
            AND a.sseguro   = b.sseguro
            AND a.sperson   = b.sperson
            AND a.sperson   = i.sperson
            AND a.cgarant   = 0
            AND a.nmovimi   =
              (SELECT MAX(nmovimi)
              FROM benespseg
              WHERE sseguro = psseguro
              AND nmovimi  <= pnmovimi
              )
            );
          --Fin 47966 -- ECP -- 11/12/2018
          -- INI BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
          IF v_tresult2 = ' \par ' THEN--BUG 0043516 - 24/05/2018 - CASL - Se cambia la variable del resultado
            RAISE NO_DATA_FOUND;
          END IF;
          -- FIN BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
        EXCEPTION
        WHEN NO_DATA_FOUND THEN
          BEGIN
            --Inicio bug 0039987 - YMG
            SELECT PAC_ISQLFOR_LCOL.F_DIRECCION(I.SPERSON,MAX(CDOMICI))
              --Fin bug 0039987
              || ' \par ' AS rmax_domici
            INTO v_tresult2--BUG 0043516 - 24/05/2018 - CASL - Se cambia la variable del resultado
            FROM per_direcciones
            WHERE sperson = i.sperson
            AND ctipdir   = 9;
            -- INI BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
            IF v_tresult2 = ' \par ' THEN--BUG 0043516 - 24/05/2018 - CASL - Se cambia la variable del resultado
              RAISE NO_DATA_FOUND;
            END IF;
            -- FIN BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
          EXCEPTION
          WHEN NO_DATA_FOUND THEN
            BEGIN
              --Inicio bug 0039987 - YMG
              SELECT PAC_ISQLFOR_LCOL.F_DIRECCION(I.SPERSON,MAX(CDOMICI))
                --Fin bug 0039987
                || ' \par ' AS rmax_domici
              INTO v_tresult2--BUG 0043516 - 24/05/2018 - CASL - Se cambia la variable del resultado
              FROM per_direcciones
              WHERE sperson = i.sperson;
            EXCEPTION
            WHEN OTHERS THEN
              RETURN ('');
            END;
          END;
        END;
      END;
      -- INI DV 0062334 03/08/2020
      END;
      -- FIN DV 0062334 03/08/2020
      --
      --INI BUG 0043516 - 24/05/2018 - CASL - Se asigna el resultado concatenado
      --
      v_tresult := v_tresult||v_tresult2;
      --
      --FIN BUG 0043516 - 24/05/2018 - CASL
      --
      -- FIN RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios. Se busca en asegurados - tomadores - La Direccion de Residencia -  La Maxima Direccion
      -- INICIO Bug 31777 - LRGG - Adicion de la fecha de Nacimiento
    ELSIF pcamp  = 10 THEN
      v_tresult := v_tresult || i.fechanacim || ' \par ';
      -- FIN Bug 31777 - LRGG - Adicion de la fecha de Nacimiento
      -- inicio 164.0 22/10/2018  AAN   0046937 se ajusta funcion F_BENESPSEG
    ELSIF pcamp  = 11 THEN
      v_tresult := v_tresult || i.benefaccid || ' \par ';
      --INI SPV 24/05/2019 0050736: Solicitud sabana de migraciÃ³n iAxis para PUAC (Funcion hallar dpto benef para el reporte)
    ELSIF pcamp = 12 THEN
      --Halla el nombre del departamento del beneficiario
      --
     -- INI DV 0062334 03/08/2020
      BEGIN
        SELECT DISTINCT pac_isqlfor.f_provincia(i.sperson, rmax_domici)
          || ' \par '
        INTO v_tresult
        FROM
          ( SELECT a.cdomici AS rmax_domici
              FROM benespseg a
              WHERE a.sseguro = psseguro
              AND a.sperson   = i.sperson
              AND a.cgarant   = 0
              AND a.nmovimi   =
                       (SELECT MAX(nmovimi)
                        FROM benespseg
                        WHERE sseguro = psseguro
                        AND nmovimi  <=pnmovimi
                        )
          );
        IF v_tresult = ' \par ' THEN
          RAISE NO_DATA_FOUND;
        END IF;
      EXCEPTION
      WHEN NO_DATA_FOUND THEN
      -- FIN DV 0062334 03/08/2020
      BEGIN
        SELECT DISTINCT pac_isqlfor.f_provincia(i.sperson, rmax_domici) --SELECT PAC_ISQLFOR.F_POBLACION(i.SPERSON, RMAX_DOMICI)
          || ' \par '
        INTO v_tresult
        FROM
          (SELECT MAX(b.cdomici) AS rmax_domici
          FROM benespseg a,
            asegurados b
          WHERE a.sseguro = psseguro
          AND a.sseguro   = b.sseguro
          AND a.sperson   = b.sperson
          AND a.sperson   = i.sperson
          AND a.cgarant   = 0
          AND a.nmovimi   =
            (SELECT MAX(nmovimi)
            FROM benespseg
            WHERE sseguro = psseguro
            AND nmovimi  <= pnmovimi
            )
          );
        IF v_tresult = ' \par ' THEN
          RAISE NO_DATA_FOUND;
        END IF;
      EXCEPTION
      WHEN NO_DATA_FOUND THEN
        BEGIN
          SELECT DISTINCT pac_isqlfor.f_provincia(i.sperson, rmax_domici) --SELECT PAC_ISQLFOR.F_POBLACION(i.SPERSON, RMAX_DOMICI)
            || ' \par '
          INTO v_tresult
          FROM
            (SELECT MAX(b.cdomici) AS rmax_domici
            FROM benespseg a,
              tomadores b
            WHERE a.sseguro = psseguro
            AND a.sseguro   = b.sseguro
            AND a.sperson   = b.sperson
            AND a.sperson   = i.sperson
            AND a.cgarant   = 0
            AND a.nmovimi   =
              (SELECT MAX(nmovimi)
              FROM benespseg
              WHERE sseguro = psseguro
              AND nmovimi  <= pnmovimi
              )
            );
          IF v_tresult = ' \par ' THEN
            RAISE NO_DATA_FOUND;
          END IF;
        EXCEPTION
        WHEN NO_DATA_FOUND THEN
          BEGIN
            SELECT pac_isqlfor.f_provincia(i.sperson, MAX(cdomici))
              || ' \par ' AS rmax_domici
            INTO v_tresult
            FROM per_direcciones
            WHERE sperson = i.sperson
            AND ctipdir   = 9;
            IF v_tresult  = ' \par ' THEN
              RAISE NO_DATA_FOUND;
            END IF;
          EXCEPTION
          WHEN NO_DATA_FOUND THEN
            BEGIN
              SELECT pac_isqlfor.f_provincia(i.sperson, MAX(cdomici))
                || ' \par ' AS rmax_domici
              INTO v_tresult
              FROM per_direcciones
              WHERE sperson = i.sperson;
            EXCEPTION
            WHEN OTHERS THEN
              RETURN ('');
            END;
          END;
        END;
      END;
      -- INI DV 0062334 03/08/2020
      END;
      -- FIN DV 0062334 03/08/2020
      --
      --FIN SPV 24/05/2019 0050736: Solicitud sabana de migraciÃ³n iAxis para PUAC (Funcion hallar dpto benef para el reporte)
    END IF;
    -- fin 164.0 22/10/2018  AAN  0046937 se ajusta funcion F_BENESPSEG
  END LOOP;
  RETURN (REPLACE(f_jrep_trad(v_tresult), CHR(39), ''));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_benespseg;
/*****************************************************************
FUNCTION f_convimp
Converteix l'import a la moneda tmoneda, si es ORIG es deixa igual
(del producte o instal?laci?)
Si la moneda desti (tant si s'ha convertit, com si es ORIG) es COP
s'arrodoneix l'import per a que no tingui decimals.
param IN pimport  :
param IN tmoneda  :
param IN psseguro :
param IN pfecha   :
param IN ptablas  :
return            : number
Bug 19927 - 11/01/2011 - JTS
******************************************************************/
FUNCTION f_convimp(
    pimport  IN NUMBER,
    tmoneda  IN VARCHAR2,
    psseguro IN NUMBER,
    pfecha   IN DATE,
    ptablas  IN VARCHAR2 DEFAULT 'POL')
  RETURN VARCHAR2
IS
  tmonseg VARCHAR2(10);
  iimport NUMBER;
  itasa   NUMBER;
  vfecha  DATE;
BEGIN
  IF ptablas = 'EST' THEN
    SELECT pac_monedas.f_cmoneda_t(NVL(p.cdivisa, f_parinstalacion_n('MONEDAINST'))),
      NVL(pfecha, s.fefecto)
    INTO tmonseg,
      vfecha
    FROM estseguros s,
      productos p
    WHERE s.sseguro = psseguro
    AND s.sproduc   = p.sproduc;
  ELSE
    -- QT 6988 --ECP -- 03/04/2013 Se cambia m.fefecto por m.femisio
    SELECT pac_monedas.f_cmoneda_t(NVL(p.cdivisa, f_parinstalacion_n('MONEDAINST'))),
      NVL(pfecha, m.femisio)
    INTO tmonseg,
      vfecha
    FROM seguros s,
      productos p,
      movseguro m
    WHERE s.sseguro = psseguro
    AND s.sproduc   = p.sproduc
    AND m.sseguro   = s.sseguro
    AND m.nmovimi   = pac_isqlfor.f_max_nmovimi(s.sseguro);
  END IF;
  IF tmoneda   = 'ORIG' THEN
    IF tmonseg = 'COP' THEN
      iimport := ROUND(pimport, 0);
      RETURN fu_formato(p_valor => iimport, p_dg_dec => 0); -- BUG 0035431/0203621 - 29/04/2015 - JAE - Formato numÃ¿Â©rico
    ELSE
      iimport := ROUND(pimport, 2);
      RETURN fu_formato(p_valor => iimport); -- BUG 0035431/0203621 - 29/04/2015 - JAE - Formato numÃ¿Â©rico
    END IF;
  ELSE
    SELECT pac_eco_tipocambio.f_cambio(tmonseg, tmoneda, NVL(pac_eco_tipocambio.f_fecha_max_cambio(tmonseg, tmoneda, vfecha), vfecha))
    INTO itasa
    FROM DUAL;
    IF tmoneda = 'COP' THEN
      iimport := ROUND(pimport * itasa, 0);
      -- jlb I
      RETURN fu_formato(p_valor => iimport, p_dg_dec => 0); -- BUG 0035431/0203621 - 29/04/2015 - JAE - Formato numÃ¿Â©rico
    ELSE
      -- jlb F
      iimport := ROUND(pimport * itasa, 2);
      RETURN fu_formato(p_valor => iimport); -- BUG 0035431/0203621 - 29/04/2015 - JAE - Formato numÃ¿Â©rico
    END IF;
  END IF;
  p_tab_error(f_sysdate, f_user, 'F_IMPCONV', 1, 'Importe', iimport);
  RETURN iimport;
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_convimp;
FUNCTION f_gastexp(
    psseguro IN NUMBER,
    ptabla   IN VARCHAR2 DEFAULT 'EST',
    pfefecto IN DATE DEFAULT f_sysdate)
  RETURN NUMBER
IS
  vgastexp  NUMBER;
  vcempres  NUMBER;
  vfinivig  DATE;
  vcforpag  NUMBER;
  vcramo    NUMBER;
  vcmodali  NUMBER;
  vctipseg  NUMBER;
  vccolect  NUMBER;
  vcactivi  NUMBER;
  vdummy    NUMBER;
  verror    NUMBER;
  vcount    NUMBER;
  vpregpro  NUMBER;
  v_sproduc NUMBER;--BUG 0046804 - 10/10/2018 - CASL - Se crea nueva variable
BEGIN
  --
  --INI BUG 0046804 - 10/10/2018 - CASL - Se obtiene el producto
  --
  BEGIN
    --
    SELECT sproduc INTO v_sproduc FROM seguros WHERE sseguro = psseguro;
    --
  EXCEPTION
  WHEN OTHERS THEN
    --
    BEGIN
      --
      SELECT sproduc INTO v_sproduc FROM estseguros WHERE sseguro = psseguro;
      --
    EXCEPTION
    WHEN OTHERS THEN
      --
      v_sproduc := NULL;
      --
    END;
  END;
  --
  --FIN BUG 0046804 - 10/10/2018 - CASL
  --
  IF ptabla = 'EST' THEN
    SELECT COUNT(1)
    INTO vcount
    FROM estpregunpolseg
    WHERE cpregun = 4044
    AND sseguro   = psseguro;
    IF vcount     > 0 THEN
      RETURN 0;
    END IF;
    --Bug 30819 - 08/04/2012 - JMG - Inicio - Se aplica validaciÃ¿Â³n  productos que tengan la pregunta.
    SELECT COUNT(1)
    INTO vpregpro
    FROM pregunpro
      --INI BUG 0046804 - 10/10/2018 - CASL - Se filtra por el producto
    WHERE sproduc = v_sproduc
      --FIN BUG 0046804 - 10/10/2018 - CASL
    AND cpregun = 4093;
    IF vpregpro > 0 THEN
      BEGIN
        SELECT NVL(crespue, 0)
        INTO vcount
        FROM estpregunpolseg
        WHERE cpregun = 4093
        AND sseguro   = psseguro;
      EXCEPTION
      WHEN NO_DATA_FOUND THEN
        RETURN 0;
      END;
      IF (vcount = 0) THEN
        RETURN 0;
      END IF;
    END IF;
    --Bug 30819 - 08/04/2012 - JMG - Fin - Se aplica validaci??n  productos que tengan la pregunta.
    BEGIN
      -- Inicio Bug 40686  AABC 17/04/2018 Version 122 se agrega exception cuando no encuentra datos
      SELECT cempres,
        pfefecto,
        cforpag,
        cramo,
        cmodali,
        ctipseg,
        ccolect,
        cactivi
      INTO vcempres,
        vfinivig,
        vcforpag,
        vcramo,
        vcmodali,
        vctipseg,
        vccolect,
        vcactivi
      FROM estseguros
      WHERE sseguro = psseguro;
    EXCEPTION
    WHEN NO_DATA_FOUND THEN
      -- Bug 40686 Inicio   Version 122
      SELECT cempres,
        pfefecto,
        cforpag,
        cramo,
        cmodali,
        ctipseg,
        ccolect,
        cactivi
      INTO vcempres,
        vfinivig,
        vcforpag,
        vcramo,
        vcmodali,
        vctipseg,
        vccolect,
        vcactivi
      FROM seguros
      WHERE sseguro = psseguro;
      -- Fin Bug 40686  AABC 17/04/2018 Version 122 se agrega exception cuando no encuentra datos
    END;
    verror := f_concepto(14, vcempres, vfinivig, vcforpag, vcramo, vcmodali, vctipseg, vccolect, vcactivi, NULL, vdummy, vgastexp, vdummy, vdummy, vdummy, vdummy, vdummy, vdummy);
    -- Inicio Bug 40686  AABC 17/04/2018 Version 122 se agrega exception cuando no encuentra datos
    BEGIN
      SELECT vgastexp * pac_eco_tipocambio.f_cambio('COP', pac_monedas.f_cmoneda_t(NVL(p.cdivisa, f_parinstalacion_n('MONEDAINST'))) , NVL(pac_eco_tipocambio.f_fecha_max_cambio('COP', pac_monedas.f_cmoneda_t(NVL(p.cdivisa, f_parinstalacion_n('MONEDAINST'))), s.fefecto), s.fefecto) ) tax
      INTO vgastexp
      FROM estseguros s,
        productos p
      WHERE s.sseguro = psseguro
      AND s.sproduc   = p.sproduc;
    EXCEPTION
    WHEN NO_DATA_FOUND THEN
      --Bug 40686 Inicio AABC
      SELECT vgastexp * pac_eco_tipocambio.f_cambio('COP', pac_monedas.f_cmoneda_t(NVL(p.cdivisa, f_parinstalacion_n('MONEDAINST'))) , NVL(pac_eco_tipocambio.f_fecha_max_cambio('COP', pac_monedas.f_cmoneda_t(NVL(p.cdivisa, f_parinstalacion_n('MONEDAINST'))), s.fefecto), s.fefecto) ) tax
      INTO vgastexp
      FROM seguros s,
        productos p
      WHERE s.sseguro = psseguro
      AND s.sproduc   = p.sproduc;
      -- Inicio Bug 40686  AABC 17/04/2018 Version 122 se agrega exception cuando no encuentra datos
    END;
  ELSE
    IF ptabla <> 'MIG_GASTEXP' THEN
      SELECT COUNT(1)
      INTO vcount
      FROM pregunpolseg
      WHERE cpregun = 4044
      AND sseguro   = psseguro;
      IF vcount     > 0 THEN
        RETURN 0;
      END IF;
    END IF;
    --Bug 30819 - 08/04/2012 - JMG - Inicio - Se aplica validaciÃ¿Â³n  productos que tengan la pregunta.
    SELECT COUNT(1)
    INTO vpregpro
    FROM pregunpro
      --INI BUG 0046804 - 10/10/2018 - CASL - Se filtra por el producto
    WHERE sproduc = v_sproduc
      --FIN BUG 0046804 - 10/10/2018 - CASL
    AND cpregun = 4093;
    IF vpregpro > 0 THEN
      BEGIN
        SELECT NVL(crespue, 0)
        INTO vcount
        FROM pregunpolseg
        WHERE cpregun = 4093
        AND sseguro   = psseguro
        AND nmovimi   =
          (SELECT MAX(nmovimi)
          FROM pregunpolseg
          WHERE cpregun = 4093
          AND sseguro   = psseguro
          );
      EXCEPTION
      WHEN NO_DATA_FOUND THEN
        RETURN 0;
      END;
      IF (vcount = 0) THEN
        RETURN 0;
      END IF;
    END IF;
    --Bug 30819 - 08/04/2012 - JMG - Fin - Se aplica validaciÃ¿Â³n  productos que tengan la pregunta.
    SELECT cempres,
      pfefecto,
      cforpag,
      cramo,
      cmodali,
      ctipseg,
      ccolect,
      cactivi
    INTO vcempres,
      vfinivig,
      vcforpag,
      vcramo,
      vcmodali,
      vctipseg,
      vccolect,
      vcactivi
    FROM seguros
    WHERE sseguro = psseguro;
    verror       := f_concepto(14, vcempres, vfinivig, vcforpag, vcramo, vcmodali, vctipseg, vccolect, vcactivi, NULL, vdummy, vgastexp, vdummy, vdummy, vdummy, vdummy, vdummy, vdummy);
    SELECT vgastexp * pac_eco_tipocambio.f_cambio('COP', pac_monedas.f_cmoneda_t(NVL(p.cdivisa, f_parinstalacion_n('MONEDAINST'))) , NVL(pac_eco_tipocambio.f_fecha_max_cambio('COP', pac_monedas.f_cmoneda_t(NVL(p.cdivisa, f_parinstalacion_n('MONEDAINST'))), m.fefecto), m.fefecto) ) tax
    INTO vgastexp
    FROM seguros s,
      productos p,
      movseguro m
    WHERE s.sseguro = psseguro
    AND s.sproduc   = p.sproduc
    AND m.sseguro   = s.sseguro
    AND m.nmovimi   = pac_isqlfor.f_max_nmovimi(s.sseguro);
  END IF;
  RETURN vgastexp;
END f_gastexp;
FUNCTION f_clausulas(
    psseguro  IN NUMBER,
    pnmovimi  IN NUMBER,
    pcidioma  IN NUMBER,
    ptabla    IN VARCHAR2 DEFAULT 'POL',
    pcduplica IN NUMBER DEFAULT 0,
    pcart IN NUMBER DEFAULT 0)-- BUG AITSSD-5766 02/03/2023 GZG
  RETURN CLOB
IS
  vret CLOB;
  vcparams NUMBER;
  vtclatex CLOB; --INTEGRACIÃ¿Â¿N--LIB_LCOL_1524
  vsproduc NUMBER;-- BUG 0050125 05/11/2019 GZG
  vcmotmov number;-- BUG 0050125 05/11/2019 GZG
  vgaran VARCHAR2(1100);-- BUG AITSSD-5766 02/03/2023 GZG
  --INI BUG AITSSD-14737 GZG 28/12/2023
  vexistecla NUMBER :=0;
  w_cversion NUMBER;
  v_cprovin NUMBER;
  v_cpoblac NUMBER;
  w_anyo autriesgos.anyo%TYPE;
  w_disp_contrac NUMBER := 0;
  --FIN BUG AITSSD-14737 GZG 28/12/2023
BEGIN
-- INI BUG 0050125 05/11/2019 GZG SE REVERSA BUG POR GENERAR ERROR -- SE COMENTAN LINEAS
/*
   SELECT cramo
   INTO vsproduc
   FROM SEGUROS
   WHERE SSEGURO = psseguro;
   IF vsproduc IN (700,702) THEN
   select cmotmov
   into vcmotmov
   from movseguro
   WHERE SSEGURO = psseguro
   and nmovimi = pnmovimi;
   IF vcmotmov not in (100,700) THEN
  IF pnmovimi > 1 THEN
    vret     := vret || f_descsup(psseguro, pnmovimi);
   RETURN TO_CLOB(f_jrep_trad(vret));
  END IF;
    END IF;
   END IF;
   */
-- INI BUG 0050125 05/11/2019 GZG SE REVERSA BUG POR GENERAR ERROR -- SE COMENTAN LINEAS
   --p_control_error('gzg','clausulas',4);
  --INTEGRACIÃ¿Â¿N--LIB_LCOL_1524- Ini
  IF ptabla = 'POL' THEN
    FOR i IN
    (SELECT clau,
      nordcla,
      sclagen
    FROM
      (SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        c.nordcla,
        c.sclagen
      FROM clausugen cg,
        claususeg c
      WHERE cg.sclagen = c.sclagen
      AND c.sseguro    = psseguro
        --                                  AND c.nmovimi = pnmovimi
      AND c.nmovimi =
        (SELECT MAX(nmovimi)
        FROM claususeg
        WHERE sseguro = psseguro
        AND nmovimi  <= pnmovimi
        )
      AND cg.cidioma = pcidioma
        -- Ini JMO QT-0045027 (23/06/2018)
      AND c.ffinclau IS NULL
      -- Fin JMO QT-0045027 (23/06/2018)
      UNION
      SELECT REPLACE(REPLACE(REGEXP_REPLACE(tclaesp, '[[:space:]][[:space:]]*', ' '),'<br><br>','<br>'),'<br>','\par ') clau,--AITSSD-8394 GZG 09/03/2026
        nordcla,
        sclagen
      FROM clausuesp
      WHERE sseguro = psseguro
        --                                  AND nmovimi = pnmovimi
        --Inicio bug 0044653 YMG (09/07/2018)
        -- Ini JMO QT-0045027 (23/06/2018)
        --AND nmovimi = pnmovimi
      AND nmovimi IN
        (SELECT MAX(nmovimi)
        FROM clausuesp
        WHERE sseguro = psseguro
        AND nmovimi  <= pnmovimi
        AND sclagen  IS NULL
        AND ffinclau IS NULL
        )
        --Fin bug 0044653 YMG
        -- Fin JMO QT-0045027 (23/06/2018)
      AND sclagen IS NULL
        --INI BUG 0047302 - 01/11/2018 - AMC
      AND ffinclau IS NULL
      --FIN BUG 0047302 - 01/11/2018 - AMC
      UNION
      SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        --INI 17/09/2021  JMC  QT66271
        --c.nordcla,
        CASE
        WHEN c.sclagen IN (9177,9176) THEN -1
        ELSE nordcla
        END AS nordcla,
        --FIN 17/09/2021  JMC  QT66271
        c.sclagen
      FROM clausugen cg,
        clausuesp c,
        seguros s
      WHERE s.sseguro = c.sseguro
      AND cg.sclagen  = c.sclagen
      AND c.sseguro   = psseguro
        --                                  AND c.nmovimi = pnmovimi
      AND c.nmovimi =
        (SELECT MAX(nmovimi)
        FROM clausuesp
        WHERE sseguro = psseguro
        AND nmovimi  <= pnmovimi
        AND sclagen  IS NOT NULL
        )
      AND c.sclagen IS NOT NULL
      --INI 27/10/2022  JMC  AITSSD-2267
      AND ffinclau IS NULL
      --FIN 27/10/2022  JMC  AITSSD-2267
      AND cg.cidioma = pcidioma
        -- INI BUG 53240 GNRZ 23/07/2019
        /*AND (s.cramo  <> 103
        OR ncertif     = 0)*/
        -- FIN BUG 53240 GNRZ 23/07/2019
      ORDER BY nordcla
      )
    GROUP BY clau,
      nordcla,
      sclagen
    ORDER BY nordcla
    )
    LOOP
      -- JPJ 23/07/2015.- Control de clausulas con parametros
      IF i.sclagen IS NOT NULL THEN
        SELECT COUNT(1)
        INTO vcparams
        FROM clauparaseg cp
        WHERE cp.sseguro = psseguro
        AND cp.sclagen   = i.sclagen
        AND cp.nriesgo   = 0
        AND cp.nmovimi   =
          (SELECT MAX(cp1.nmovimi)
          FROM clauparaseg cp1
          WHERE cp1.sseguro = cp.sseguro
          AND cp1.sclagen   = cp.sclagen
          );
        IF vcparams <> 0 THEN
          vtclatex  := i.clau;
          FOR cur IN
          (SELECT cp.nparame,
            cp.tparame
          FROM clauparaseg cp
          WHERE cp.sseguro = psseguro
          AND cp.sclagen   = i.sclagen
          AND cp.nriesgo   = 0
          AND cp.nmovimi   =
            (SELECT MAX(cp1.nmovimi)
            FROM clauparaseg cp1
            WHERE cp1.sseguro = cp.sseguro
            AND cp1.sclagen   = cp.sclagen
            )
          )
          LOOP
            vtclatex := REPLACE(vtclatex, '#' || cur.nparame || '#', cur.tparame);
          END LOOP;
        ELSE
        --INI BUG AITSSD-5766 02/03/2023 GZG
         IF i.sclagen = 9177 AND pcart = 1 THEN
            select tclatit||'\par '||tclatex into vgaran from clausugen where sclagen = 9176 and cidioma = 8;
            i.clau := vgaran;
         END IF;
        --FIN BUG AITSSD-5766 02/03/2023 GZG
          vtclatex := i.clau;
        END IF;
      ELSE
        vtclatex := i.clau;
      END IF;
      -- Fin Control
      vret := vret || vtclatex || ' \par \par ';
    END LOOP;
    --INTEGRACIÃ¿Â¿N--LIB_LCOL_1524- Fin
    --INI BUG AITSSD-14737 GZG 28/12/2023
    IF vexistecla = 0 AND pcart = 1 THEN
    --
      SELECT cversion,
             anyo
        INTO w_cversion,
             w_anyo
        FROM autriesgos
       WHERE sseguro = psseguro
         AND nriesgo   = 1
         AND nmovimi   = pnmovimi;
    --
      SELECT ep.cprovin
        INTO v_cprovin
      FROM seguros s,
        autconductores e,
        per_direcciones ep
      WHERE s.sseguro = psseguro
      AND s.sseguro   = e.sseguro
      AND e.nriesgo   = 1
      AND e.nmovimi   = pnmovimi
      AND e.sperson   = ep.sperson
      AND e.cdomici   = ep.cdomici;
    -- Obtenemos codigo de poblacion o ciudad del conductor
      SELECT ep.cpoblac
      INTO v_cpoblac
      FROM seguros s,
        autconductores e,
        per_direcciones ep
      WHERE s.sseguro = psseguro
      AND s.sseguro   = e.sseguro
      AND e.nriesgo   = 1
      AND e.nmovimi   = pnmovimi
      AND e.sperson   = ep.sperson
      AND e.cdomici   = ep.cdomici;
      --
        vexistecla := pac_subtablas.f_vsubtabla (-1, 700000346, 333324,  1, 0, w_cversion, v_cprovin, v_cpoblac, w_anyo, w_anyo);
        IF vexistecla = 2 THEN
          SELECT COUNT (1)
          INTO w_disp_contrac
          FROM autdisriesgos
          WHERE sseguro     = psseguro
          AND nriesgo       = 1
          AND nmovimi       = pnmovimi
          AND cversion      = w_cversion
          AND cdispositivo  = vexistecla;
          IF w_disp_contrac = 0 THEN
            select tclatit||'\par '||tclatex into vgaran from clausugen where sclagen = 9176 and cidioma = 8;
            vret := vret || vgaran || ' \par \par ';
          END IF;
        END IF;
    END IF;
    --FIN BUG AITSSD-14737 GZG 28/12/2023
  ELSE
    FOR i IN
    (SELECT clau,
      nordcla
    FROM
      (SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        c.nordcla
      FROM clausugen cg,
        estclaususeg c
      WHERE cg.sclagen = c.sclagen
      AND c.sseguro    = psseguro
      AND c.nmovimi    = pnmovimi
      AND cg.cidioma   = pcidioma
      UNION
      SELECT REPLACE(REPLACE(REGEXP_REPLACE(tclaesp, '[[:space:]][[:space:]]*', ' '),'<br><br>','<br>'),'<br>','\par ') clau,--AITSSD-8394 GZG 09/03/2026
        nordcla
      FROM estclausuesp
      WHERE sseguro = psseguro
      AND nmovimi   = pnmovimi
      AND sclagen  IS NULL
      UNION
      SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        --INI 02/11/2021  JMC  QT66271
        --c.nordcla
        CASE
        WHEN c.sclagen IN (9177,9176) THEN -1
        ELSE nordcla
        END AS nordcla
        --FIN 02/11/2021  JMC  QT66271
      FROM clausugen cg,
        estclausuesp c,
        estseguros s
      WHERE s.sseguro = c.sseguro
      AND cg.sclagen  = c.sclagen
      AND c.sseguro   = psseguro
      AND c.nmovimi   = pnmovimi
      AND c.sclagen  IS NOT NULL
      AND cg.cidioma  = pcidioma
      AND (s.cramo   <> 103
      OR ncertif      = 0)
      ORDER BY nordcla
      )
    GROUP BY clau,
      nordcla
    ORDER BY nordcla
    )
    LOOP
      vret := vret || i.clau || ' \par \par ';
    END LOOP;
  END IF;
  --INI AITSSD-9009 GZG 23/05/2023 Se comentan lineas
  /*IF pnmovimi > 1 AND pcduplica = 0 THEN
    vret     := vret || f_descsup(psseguro, pnmovimi);
  END IF;*/
  --FIN AITSSD-9009 GZG 23/05/2023
  RETURN TO_CLOB(f_jrep_trad(vret));
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_clausulas;
/*****************************************************************
FUNCTION f_clausulas_hog
Clausulas de hogar que debe salir el titulo del plan poliza 0
param IN psseguro  :
param IN pnmovimi  :
param IN pcidioma :
param IN ptabla   :
param IN ptablas  :
para IN pcduplica:
return            : number
Bug  - 19/10/2015 - CALL
******************************************************************/
FUNCTION f_clausulas_hog(
    psseguro  IN NUMBER,
    pnmovimi  IN NUMBER,
    pcidioma  IN NUMBER,
    ptabla    IN VARCHAR2 DEFAULT 'POL',
    pcduplica IN NUMBER DEFAULT 0)
  RETURN CLOB
IS
  vret CLOB;
BEGIN
  IF ptabla = 'POL' THEN
    FOR i IN
    (SELECT clau,
      nordcla
    FROM
      (SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        c.nordcla
      FROM clausugen cg,
        claususeg c
      WHERE cg.sclagen = c.sclagen
      AND c.sseguro    = psseguro
        --                                  AND c.nmovimi = pnmovimi
      AND c.nmovimi =
        (SELECT MAX(nmovimi)
        FROM claususeg
        WHERE sseguro = psseguro
        AND nmovimi  <= pnmovimi
        )
      AND cg.cidioma = pcidioma
      UNION
      SELECT REPLACE(REPLACE(REGEXP_REPLACE(tclaesp, '[[:space:]][[:space:]]*', ' '),'<br><br>','<br>'),'<br>','\par ') clau,--AITSSD-8394 GZG 09/03/2026
        nordcla
      FROM clausuesp
      WHERE sseguro = psseguro
        --                                  AND nmovimi = pnmovimi
      AND nmovimi =
        (SELECT MAX(nmovimi)
        FROM clausuesp
        WHERE sseguro = psseguro
        AND nmovimi  <= pnmovimi
        AND sclagen  IS NULL
        )
      AND sclagen IS NULL
      AND ffinclau is null -- BUG 0072662 GZG 15/12/2021
      UNION
      SELECT DECODE( cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '( '
        || r.tnatrie
        || ' )'
        || '\par '
        || cg.tclatex) clau,
        c.nordcla
      FROM clausugen cg,
        clausuesp c,
        seguros s,
        riesgos r
      WHERE s.sseguro = c.sseguro
      AND cg.sclagen  = c.sclagen
      AND c.sseguro   = psseguro
        --                                  AND c.nmovimi = pnmovimi
      AND s.sseguro = r.sseguro
      AND c.nmovimi = r.nmovima
      AND c.nriesgo = r.nriesgo
      AND c.nmovimi =
        (SELECT MAX(nmovimi)
        FROM clausuesp
        WHERE sseguro = psseguro
        AND nmovimi  <= pnmovimi
        AND sclagen  IS NOT NULL
        )
      AND c.sclagen IS NOT NULL
      AND cg.cidioma = pcidioma
      AND (s.cramo  <> 103
      OR ncertif     = 0)
      ORDER BY nordcla
      )
    GROUP BY clau,
      nordcla
    ORDER BY nordcla
    )
    LOOP
      vret := vret || i.clau || ' \par \par ';
    END LOOP;
  ELSE
    FOR i IN
    (SELECT clau,
      nordcla
    FROM
      (SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        c.nordcla
      FROM clausugen cg,
        estclaususeg c
      WHERE cg.sclagen = c.sclagen
      AND c.sseguro    = psseguro
      AND c.nmovimi    = pnmovimi
      AND cg.cidioma   = pcidioma
      UNION
      SELECT REPLACE(REPLACE(REGEXP_REPLACE(tclaesp, '[[:space:]][[:space:]]*', ' '),'<br><br>','<br>'),'<br>','\par ') clau,--AITSSD-8394 GZG 09/03/2026
        nordcla
      FROM estclausuesp
      WHERE sseguro = psseguro
      AND nmovimi   = pnmovimi
      AND sclagen  IS NULL
      UNION
      SELECT DECODE( cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '( '
        || r.tnatrie
        || ' )'
        || '\par '
        || cg.tclatex) clau,
        c.nordcla
      FROM clausugen cg,
        estclausuesp c,
        estseguros s,
        estriesgos r
      WHERE s.sseguro = c.sseguro
      AND cg.sclagen  = c.sclagen
      AND c.sseguro   = psseguro
      AND c.nmovimi   = pnmovimi
      AND c.sclagen  IS NOT NULL
      AND cg.cidioma  = pcidioma
      AND s.sseguro   = r.sseguro
      AND c.nmovimi   = r.nmovima
      AND c.nriesgo   = r.nriesgo
      AND (s.cramo   <> 103
      OR ncertif      = 0)
      ORDER BY nordcla
      )
    GROUP BY clau,
      nordcla
    ORDER BY nordcla
    )
    LOOP
      vret := vret || i.clau || ' \par \par ';
    END LOOP;
  END IF;
  IF pnmovimi > 1 AND pcduplica = 0 THEN
    vret     := vret || f_descsup(psseguro, pnmovimi);
  END IF;
  RETURN TO_CLOB(f_jrep_trad(vret));
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_clausulas_hog;
