/** Fin ARM Bug: 0046812 **/
FUNCTION f_monprod(
    psproduc IN NUMBER)
  RETURN VARCHAR2
IS
  vret VARCHAR2(255);
BEGIN
  SELECT DECODE(pac_monedas.f_cmoneda_t(NVL(cdivisa, f_parinstalacion_n('MONEDAINST'))), 'USD', 'US$', 'COP', '$', pac_monedas.f_cmoneda_t(NVL(cdivisa, f_parinstalacion_n('MONEDAINST'))))
  INTO vret
  FROM productos
  WHERE sproduc = psproduc;
  RETURN vret;
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_monprod;
/*****************************************************************
FUNCTION f_numerotexto
Converteix un numero a text (fins a 9999 i sense decimals)
S'utilitzar? b?sicament per a dates.
La creem a sac "sense idioma" en castell?
per falta de temps, per al pac_isqlfor com? es pot adaptar sense gaires problemes
creant detvalores o literals i substitu?nt el text posat a sac
param IN pnumero  :
return            : varchar2
Bug 20213 - 18/01/2011 - JTS
******************************************************************/
FUNCTION f_numerotexto(
    pnumero IN NUMBER)
  RETURN VARCHAR2
IS
  vunidad    NUMBER(1) := 0;
  vdecena    NUMBER(1) := 0;
  vcentena   NUMBER(1) := 0;
  vunidadmil NUMBER(1) := 0;
  vtexto     VARCHAR2(100);
  vnumero    NUMBER := pnumero;
BEGIN
  vunidadmil := TRUNC(vnumero / 1000); --Obtenemos 1er. digito
  vnumero    := MOD(vnumero, 1000);
  --Es como que hicieramos Numero:=NUmero-(Unidad_Mil*1000)
  vcentena := TRUNC(vnumero / 100); --Obtenemos 2do. digito
  vnumero  := MOD(vnumero, 100);
  vdecena  := TRUNC(vnumero / 10); --Obtenemos 3er. digito
  vunidad  := MOD(vnumero, 10);    --Obtenemos 4to. digito
  SELECT DECODE(vunidadmil, 1, 'Mil ', 2, 'Dos Mil ', 3, 'Tres Mil ', 4, 'Cuatro Mil ', 5, 'Cinco Mil ', 6, 'Seis Mil ', 7, 'Siete mil ', 8, 'Ocho mil ', 9, 'Nueve Mil ', '')
  INTO vtexto
  FROM DUAL;
  SELECT vtexto
    || DECODE(vcentena, 1, 'Ciento ', 2, 'doscientos ', 3, 'trescientos ', 4, 'cuatrocientos ', 5, 'quinientos ', 6, 'seiscientos ', 7, 'setecientos ', 8, 'ochocientos ', 9, 'novecientos ', '')
  INTO vtexto
  FROM DUAL;
  IF (vdecena = 1) THEN
    SELECT vtexto
      || DECODE(vunidad, 0, 'diez', 1, 'once', 2, 'doce', 3, 'trece', 4, 'catorce', 5, 'quince', 6, 'dieciseis', 7, 'diecisiete', 8, 'dieciocho', 9, 'diecinueve', '')
    INTO vtexto
    FROM DUAL;
  ELSE
    IF (vunidad = 0) THEN
      SELECT vtexto
        || DECODE(vdecena, 2, 'veinte', 3, 'treinta', 4, 'cuarenta', 5, 'cincuenta', 6, 'sesenta', 7, 'setenta', 8, 'ochenta', 9, 'noventa', '')
      INTO vtexto
      FROM DUAL;
    ELSE
      SELECT vtexto
        || DECODE(vdecena, 2, 'veinti', 3, 'treinta y ', 4, 'cuarenta y ', 5, 'cincuenta y ', 6, 'sesenta y ', 7, 'setenta y ', 8, 'ochenta y ', 9, 'noventa y ', '')
      INTO vtexto
      FROM DUAL;
    END IF;
  END IF;
  IF (vdecena <> 1) THEN
    SELECT vtexto
      || DECODE(vunidad, 1, 'uno', 2, 'dos', 3, 'tres', 4, 'cuatro', 5, 'cinco', 6, 'seis', 7, 'siete', 8, 'ocho', 9, 'nueve', '')
    INTO vtexto
    FROM DUAL;
  END IF;
  RETURN (LOWER(vtexto));
END f_numerotexto;
