FUNCTION f_fecha(
    pfecha   IN DATE,
    pcidioma IN NUMBER DEFAULT 8)
  RETURN VARCHAR2
IS
  vret VARCHAR2(12);
BEGIN
  SELECT TO_CHAR(pfecha, 'YYYY-')
    || ff_desvalorfijo(800071, pcidioma, TO_CHAR(pfecha, 'MM'))
    || TO_CHAR(pfecha, '-DD')
  INTO vret
  FROM DUAL;
  RETURN vret;
EXCEPTION
WHEN OTHERS THEN
  RETURN '';
END f_fecha;
FUNCTION f_direccion(
    p_sperson IN NUMBER,
    p_cdomici IN NUMBER,
    p_mode    IN VARCHAR2 DEFAULT 'POL')
  RETURN VARCHAR2
IS
  pcsiglas per_direcciones.csiglas%TYPE;
  ptnomvia per_direcciones.tnomvia%TYPE;
  pnnumvia per_direcciones.nnumvia%TYPE;
  ptcomple per_direcciones.tcomple%TYPE;
  pcviavp per_direcciones.cviavp%TYPE;
  pclitvp per_direcciones.clitvp%TYPE;
  pcbisvp per_direcciones.cbisvp%TYPE;
  pcorvp per_direcciones.corvp%TYPE;
  pnviaadco per_direcciones.nviaadco%TYPE;
  pclitco per_direcciones.clitco%TYPE;
  pcorco per_direcciones.corco%TYPE;
  pnplacaco per_direcciones.nplacaco%TYPE;
  pcor2co per_direcciones.cor2co%TYPE;
  pcdet1ia per_direcciones.cdet1ia%TYPE;
  ptnum1ia per_direcciones.tnum1ia%TYPE;
  pcdet2ia per_direcciones.cdet2ia%TYPE;
  ptnum2ia per_direcciones.tnum2ia%TYPE;
  pcdet3ia per_direcciones.cdet3ia%TYPE;
  ptnum3ia per_direcciones.tnum3ia%TYPE;
  -- ini 0050464: CUMPLIMIENTO: EL PDF DE POLIZA 296183 NO TRAE LA DIRECCION DEL ASEGURADO
  ptdomici per_direcciones.tdomici%TYPE;
  --fin 0050464: CUMPLIMIENTO: EL PDF DE POLIZA 296183 NO TRAE LA DIRECCION DEL ASEGURADO
  vtsiglas VARCHAR2(2) := NULL;
  vnnomvia NUMBER;
  vnnumvia NUMBER;
  vncomple NUMBER;
  vtdomici per_direcciones.tdomici%TYPE;
  tviavp  VARCHAR2(250);
  tdet1ia VARCHAR2(50);
  tdet2ia VARCHAR2(50);
  tdet3ia VARCHAR2(50);
  tclitvp VARCHAR2(50);
  tbisvp  VARCHAR2(50);
  tcorvp  VARCHAR2(50);
  tlitco  VARCHAR2(50);
  tcorco  VARCHAR2(50);
  tor2co  VARCHAR2(50);
BEGIN
  IF p_mode = 'POL' THEN
    -- INI 0050464: CUMPLIMIENTO: EL PDF DE POLIZA 296183 NO TRAE LA DIRECCION DEL ASEGURADO
    SELECT csiglas,
      tnomvia,
      nnumvia,
      tcomple,
      cviavp,
      clitvp,
      cbisvp,
      corvp,
      nviaadco,
      clitco,
      corco,
      nplacaco,
      cor2co,
      cdet1ia,
      tnum1ia,
      cdet2ia,
      tnum2ia,
      cdet3ia,
      tnum3ia,
      tdomici
    INTO pcsiglas,
      ptnomvia,
      pnnumvia,
      ptcomple,
      pcviavp,
      pclitvp,
      pcbisvp,
      pcorvp,
      pnviaadco,
      pclitco,
      pcorco,
      pnplacaco,
      pcor2co,
      pcdet1ia,
      ptnum1ia,
      pcdet2ia,
      ptnum2ia,
      pcdet3ia,
      ptnum3ia,
      ptdomici
    FROM per_direcciones
    WHERE sperson = p_sperson
    AND cdomici   = p_cdomici;
  ELSE
    SELECT csiglas,
      tnomvia,
      nnumvia,
      tcomple,
      cviavp,
      clitvp,
      cbisvp,
      corvp,
      nviaadco,
      clitco,
      corco,
      nplacaco,
      cor2co,
      cdet1ia,
      tnum1ia,
      cdet2ia,
      tnum2ia,
      cdet3ia,
      tnum3ia,
      ptdomici
    INTO pcsiglas,
      ptnomvia,
      pnnumvia,
      ptcomple,
      pcviavp,
      pclitvp,
      pcbisvp,
      pcorvp,
      pnviaadco,
      pclitco,
      pcorco,
      pnplacaco,
      pcor2co,
      pcdet1ia,
      ptnum1ia,
      pcdet2ia,
      ptnum2ia,
      pcdet3ia,
      ptnum3ia,
      ptdomici
    FROM estper_direcciones
    WHERE sperson = p_sperson
    AND cdomici   = p_cdomici;
  END IF;
  -- FIN 0050464: CUMPLIMIENTO: EL PDF DE POLIZA 296183 NO TRAE LA DIRECCION DEL ASEGURADO
  IF pcsiglas IS NOT NULL THEN
    BEGIN
      SELECT tsiglas INTO vtsiglas FROM tipos_via WHERE csiglas = pcsiglas;
      vtdomici := vtsiglas || ' ';
    EXCEPTION
    WHEN OTHERS THEN
      vtsiglas := NULL;
    END;
  END IF;
  IF pcviavp IS NOT NULL THEN
    BEGIN
      SELECT tsiglas INTO vtsiglas FROM tipos_via WHERE csiglas = pcviavp;
      vtdomici := vtsiglas || ' ';
    EXCEPTION
    WHEN OTHERS THEN
      vtsiglas := NULL;
    END;
  END IF;
  vnnomvia                               := NVL(LENGTH(ptnomvia), 0);
  vnnumvia                               := NVL(LENGTH(pnnumvia), 0);
  vncomple                               := NVL(LENGTH(ptcomple), 0);
  IF (vnnomvia + vnnumvia + vncomple + 8) < 100 THEN
    SELECT vtdomici
      || ptnomvia
      || DECODE(pnnumvia, NULL, NULL, ' ')
      || pnnumvia
      || f_axis_literales(9001323, f_usu_idioma)
      || DECODE(ptcomple, NULL, NULL, ' ')
      || ptcomple
    INTO vtdomici
    FROM DUAL;
  ELSE
    SELECT vtdomici
      || SUBSTR(ptnomvia, 0, 100 - (vnnumvia + vncomple + 8))
      || DECODE(pnnumvia, NULL, NULL, ' ')
      || pnnumvia
      || f_axis_literales(9001323, f_usu_idioma)
      || DECODE(ptcomple, NULL, NULL, ' ')
      || ptcomple
    INTO vtdomici
    FROM DUAL;
  END IF;
  IF pclitvp IS NOT NULL THEN
    BEGIN
      SELECT tatribu
      INTO tclitvp
      FROM detvalores
      WHERE cidioma = f_usu_idioma
      AND cvalor    = 800043
      AND catribu   = pclitvp;
      IF vtdomici  IS NULL THEN
        vtdomici   := tclitvp;
      ELSE
        vtdomici := vtdomici || ' ' || tclitvp;
      END IF;
    EXCEPTION
    WHEN OTHERS THEN
      NULL;
    END;
  END IF;
  IF pcbisvp IS NOT NULL THEN
    BEGIN
      SELECT tatribu
      INTO tbisvp
      FROM detvalores
      WHERE cidioma = f_usu_idioma
      AND cvalor    = 800044
      AND catribu   = pcbisvp;
      IF vtdomici  IS NULL THEN
        vtdomici   := tbisvp;
      ELSE
        vtdomici := vtdomici || ' ' || tbisvp;
      END IF;
    EXCEPTION
    WHEN OTHERS THEN
      NULL;
    END;
  END IF;
  IF pcorvp IS NOT NULL THEN
    BEGIN
      SELECT tatribu
      INTO tcorvp
      FROM detvalores
      WHERE cidioma = f_usu_idioma
      AND cvalor    = 800045
      AND catribu   = pcorvp;
      IF vtdomici  IS NULL THEN
        vtdomici   := tcorvp;
      ELSE
        vtdomici := vtdomici || ' ' || tcorvp;
      END IF;
    EXCEPTION
    WHEN OTHERS THEN
      NULL;
    END;
  END IF;
  IF pnviaadco IS NOT NULL THEN
    vtdomici   := vtdomici || ' ' || pnviaadco;
  END IF;
  IF pclitco IS NOT NULL THEN
    BEGIN
      SELECT tatribu
      INTO tlitco
      FROM detvalores
      WHERE cidioma = f_usu_idioma
      AND cvalor    = 800043
      AND catribu   = pclitco;
      IF vtdomici  IS NULL THEN
        vtdomici   := tlitco;
      ELSE
        vtdomici := vtdomici || ' ' || tlitco;
      END IF;
    EXCEPTION
    WHEN OTHERS THEN
      NULL;
    END;
  END IF;
  IF pcorco IS NOT NULL THEN
    BEGIN
      SELECT tatribu
      INTO tcorco
      FROM detvalores
      WHERE cidioma = f_usu_idioma
      AND cvalor    = 800045
      AND catribu   = pcorco;
      IF vtdomici  IS NULL THEN
        vtdomici   := tcorco;
      ELSE
        vtdomici := vtdomici || ' ' || tcorco;
      END IF;
    EXCEPTION
    WHEN OTHERS THEN
      NULL;
    END;
  END IF;
  IF pnplacaco IS NOT NULL THEN
    vtdomici   := vtdomici || ' ' || pnplacaco;
  END IF;
  IF pcor2co IS NOT NULL THEN
    BEGIN
      SELECT tatribu
      INTO tor2co
      FROM detvalores
      WHERE cidioma = f_usu_idioma
      AND cvalor    = 800045
      AND catribu   = pcor2co;
      IF vtdomici  IS NULL THEN
        vtdomici   := tor2co;
      ELSE
        vtdomici := vtdomici || ' ' || tor2co;
      END IF;
    EXCEPTION
    WHEN OTHERS THEN
      NULL;
    END;
  END IF;
  IF pcdet1ia IS NOT NULL THEN
    BEGIN
      SELECT tatribu
      INTO tdet1ia
      FROM detvalores
      WHERE cidioma = f_usu_idioma
      AND cvalor    = 800047
      AND catribu   = pcdet1ia;
      IF vtdomici  IS NULL THEN
        vtdomici   := tdet1ia;
      ELSE
        vtdomici := vtdomici || ' ' || tdet1ia;
      END IF;
    EXCEPTION
    WHEN OTHERS THEN
      NULL;
    END;
  END IF;
  IF ptnum1ia   IS NOT NULL THEN
    IF vtdomici IS NULL THEN
      vtdomici  := ptnum1ia;
    ELSE
      vtdomici := vtdomici || ' ' || ptnum1ia;
    END IF;
  END IF;
  IF pcdet2ia IS NOT NULL THEN
    BEGIN
      SELECT tatribu
      INTO tdet2ia
      FROM detvalores
      WHERE cidioma = f_usu_idioma
      AND cvalor    = 800047
      AND catribu   = pcdet2ia;
      IF vtdomici  IS NULL THEN
        vtdomici   := tdet2ia;
      ELSE
        vtdomici := vtdomici || ' ' || tdet2ia;
      END IF;
    EXCEPTION
    WHEN OTHERS THEN
      NULL;
    END;
  END IF;
  IF ptnum2ia   IS NOT NULL THEN
    IF vtdomici IS NULL THEN
      vtdomici  := ptnum2ia;
    ELSE
      vtdomici := vtdomici || ' ' || ptnum2ia;
    END IF;
  END IF;
  IF pcdet3ia IS NOT NULL THEN
    BEGIN
      SELECT tatribu
      INTO tdet3ia
      FROM detvalores
      WHERE cidioma = f_usu_idioma
      AND cvalor    = 800047
      AND catribu   = pcdet3ia;
      IF vtdomici  IS NULL THEN
        vtdomici   := tdet3ia;
      ELSE
        vtdomici := vtdomici || ' ' || tdet3ia;
      END IF;
    EXCEPTION
    WHEN OTHERS THEN
      NULL;
    END;
  END IF;
  IF ptnum3ia   IS NOT NULL THEN
    IF vtdomici IS NULL THEN
      vtdomici  := ptnum3ia;
    ELSE
      vtdomici := vtdomici || ' ' || ptnum3ia;
    END IF;
  END IF;
  -- INI 0050464: CUMPLIMIENTO: EL PDF DE POLIZA 296183 NO TRAE LA DIRECCION DEL ASEGURADO
  IF vtdomici IS NULL THEN
    vtdomici  := ptdomici;
  END IF;
  -- FIN 0050464: CUMPLIMIENTO: EL PDF DE POLIZA 296183 NO TRAE LA DIRECCION DEL ASEGURADO
  RETURN UPPER(f_jrep_trad(vtdomici));
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_direccion;
