return               : varchar2
Bug 20905 - 09/02/2012 - JTS
******************************************************************/
FUNCTION f_descsup(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER)
  RETURN CLOB
IS
  vret CLOB;
  vcmotven NUMBER;
  vcmovseg movseguro.cmovseg%TYPE;
  vimprtit NUMBER := 0;
  vsproduc NUMBER;--GZG AITSSD-13179 18/10/2023
BEGIN
  --INI GZG AITSSD-13179 18/10/2023
  BEGIN
    SELECT sproduc INTO vsproduc FROM seguros WHERE sseguro = psseguro;
  EXCEPTION
  WHEN NO_DATA_FOUND THEN
    SELECT sproduc INTO vsproduc FROM estseguros WHERE sseguro = psseguro;
  END;
  IF ( NVL ( f_parproductos_v ( vsproduc, 'NO_SUPL_ANT' ), 0 ) = 1) THEN
  RETURN '';
  END IF;
  --FIN GZG AITSSD-13179 18/10/2023
  SELECT cmotven,
    cmovseg
  INTO vcmotven,
    vcmovseg
  FROM movseguro
  WHERE sseguro = psseguro
  AND nmovimi   = pnmovimi;
  --      IF vcmotven IS NULL
  --         OR vcmotven != 998 THEN
  IF (vcmovseg != 3) THEN
    FOR i IN
    --INI BUG 0054805 GZG 11/09/2019
    -- 0050387: CUMPLIMIENTO- SUPLEMENTOS: CARACTERES ESPECIALES A CAMBIO DE ESPACIO DE ENTER
    (SELECT TRIM(REPLACE(REGEXP_REPLACE(tvalora, lower('[[:space:]][[:space:]]*'), ' '),'Valor param.','')) detmov
    --SELECT TRIM(REPLACE(tvalora
    --  /*tvalord*/
    --  ,'Valor param.','')) detmov--BUG 0051613 GZG 13/05/2019 se reemplaza tvalord por tvalora para visualizar situacion anterior
      -- 0050387: CUMPLIMIENTO- SUPLEMENTOS: CARACTERES ESPECIALES A CAMBIO DE ESPACIO DE ENTER
    --FIN BUG 0054805 GZG 11/09/2019
    FROM detmovseguro dm,
      movseguro m
    WHERE dm.sseguro = psseguro
    AND dm.nmovimi   =
      (SELECT MAX(m2.nmovimi)
      FROM detmovseguro dm2,
        movseguro m2
      WHERE dm2.sseguro = dm.sseguro
      AND dm2.sseguro   = m2.sseguro
      AND m2.cmotmov   != 100
      AND m2.cmovseg   != 3
      AND (m2.cmotven  != 998
      OR m2.cmotven    IS NULL)
      AND m2.nmovimi   <= pnmovimi
      )
    AND m.sseguro = dm.sseguro
    AND m.nmovimi = dm.nmovimi
      --ORDER BY cpregun
    ORDER BY dm.nmovimi,
      dm.cpregun,
      dm.nriesgo,
      dm.cgarant --Bug 0046972 - AGP - 17/10/2018
    )
    LOOP
      --Cumplimiento -- Bug 0023706 --INTEGRACIÃ¿Â¿N--LIB_LCOL_1524- Ini
      --if vimprtit = 0 then
      --   vret := 'SituaciÃ¿Â³n anterior: \par ';
      --   vimprtit := 1;
      --end if;
      --INTEGRACIÃ¿Â¿N--LIB_LCOL_1524- Fin
      --end if;
      --0050387: CUMPLIMIENTO- SUPLEMENTOS: CARACTERES ESPECIALES A CAMBIO DE ESPACIO DE ENTER
      vret := vret || REPLACE(i.detmov,'<br>','\par ') || '\par ';
      --0050387: CUMPLIMIENTO- SUPLEMENTOS: CARACTERES ESPECIALES A CAMBIO DE ESPACIO DE ENTER
    END LOOP;
    --Inicio 11/03/2019  WAFS   BUG 49495: PDF Judicial
    vret := 'Situacion anterior: \par '||vret;
    --Fin 11/03/2019  WAFS   BUG 49495: PDF Judicial
  END IF;
  --      END IF;
  --INTEGRACIÃ¿Â¿N--LIB_LCOL_1524- Ini
  --Cumplimiento        vimprtit := 0;
  --      IF vcmotven IS NULL
  --         OR vcmotven != 998 THEN
  IF (vcmovseg != 3) THEN
    FOR i IN
    --INI BUG 0054805 GZG 11/09/2019
    -- INICIO 0050387: CUMPLIMIENTO- SUPLEMENTOS: CARACTERES ESPECIALES A CAMBIO DE ESPACIO DE ENTER
    (SELECT TRIM(REPLACE(REGEXP_REPLACE(tvalord, lower('[[:space:]][[:space:]]*'), ' '),'Valor param.','')) detmov,
    --SELECT TRIM(REPLACE(tvalord,'Valor param.','')) detmov,
      -- FINAL 0050387: CUMPLIMIENTO- SUPLEMENTOS: CARACTERES ESPECIALES A CAMBIO DE ESPACIO DE ENTER
    --FIN BUG 0054805 GZG 11/09/2019
      (
      SELECT tgarant
      FROM garangen
      WHERE cgarant = dm.cgarant
      AND cidioma   = pac_iax_common.f_get_cxtidioma()
      ) desgaran
    FROM detmovseguro dm,
      movseguro m
    WHERE dm.sseguro = psseguro
    AND dm.nmovimi   =
      (SELECT MAX(m2.nmovimi)
      FROM detmovseguro dm2,
        movseguro m2
      WHERE dm2.sseguro = dm.sseguro
      AND dm2.sseguro   = m2.sseguro
      AND m2.cmotmov   != 100
      AND m2.cmovseg   != 3
      AND (m2.cmotven  != 998
      OR m2.cmotven    IS NULL)
      AND m2.nmovimi   <= pnmovimi
      )
    AND m.sseguro = dm.sseguro
    AND m.nmovimi = dm.nmovimi
      --ORDER BY cpregun
    ORDER BY dm.nmovimi,
      dm.cpregun,
      dm.nriesgo,
      dm.cgarant --Bug 0046972 - AGP - 17/10/2018
    )
    LOOP
      --INTEGRACIÃ¿Â¿N--LIB_LCOL_1524- Fin
      -- Bug 0023706
      IF vimprtit = 0 THEN
        --bug 0045049 ARM Inicio
        vret := vret || ' \par Situacion actual: \par ';
        --bug 0045049 ARM fin
        vimprtit := 1;
      END IF;
      --0050387: CUMPLIMIENTO- SUPLEMENTOS: CARACTERES ESPECIALES A CAMBIO DE ESPACIO DE ENTER
      vret := vret || REPLACE(i.detmov,'<br>','\par ') || '\par ';
      --0050387: CUMPLIMIENTO- SUPLEMENTOS: CARACTERES ESPECIALES A CAMBIO DE ESPACIO DE ENTER
    END LOOP;
  END IF;
  --      END IF;
  RETURN vret;
  --Cumplimiento --INTEGRACIÃ¿Â¿N--LIB_LCOL_1524    RETURN vret;
EXCEPTION
WHEN OTHERS THEN
  RETURN '';
END f_descsup;
/*****************************************************************
FUNCTION f_notificaciones
psseguro   IN pnumero  :
pnmovimi   IN pnumero  :
return               : varchar2
Bug 20905 - 10/02/2012 - JTS
******************************************************************/
FUNCTION f_notificaciones(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER)
  RETURN VARCHAR2
IS
  vret VARCHAR2(2000);
BEGIN
  --18/09/2012  ECP  0023690: LCOL897 - Incidencias de impresiones (QTRACKER 4756)
  --Se cambia UNIDAD DE SERVICIO AL CLIENTE: BOGOT? 3077050 - L?NEA NACIONAL
  --por UNIDAD DE SERVICIO AL CLIENTE: BOGOTÃ¿Â 3077050 - LÃ¿Â­NEA NACIONAL
  --20/11/2014  INFORCOL  LCO021 - Incidencias de impresiones (QTRACKER 14828)
  --Se cambia UNIDAD DE SERVICIO AL CLIENTE: BOGOT? 3077050 - L?NEA NACIONAL
  --por UNIDAD DE SERVICIO AL CLIENTE: BOGOTA 3077050 - LINEA NACIONAL
  SELECT REPLACE (REPLACE (UPPER ('NOTIFICACIONES '
    || pac_isqlfor.f_agente(s.sucursal)
    || ' '
    || pac_isqlfor.f_pobagente(s.sucursal, 1)
    || ' '
    || pac_isqlfor_lcol.f_direccion(
    (SELECT sa.sperson FROM agentes sa WHERE sa.cagente = s.sucursal
    ), 1, 'POL')
    || ' '
    || pac_isqlfor.f_telefono(
    (SELECT sa.sperson FROM agentes sa WHERE sa.cagente = s.sucursal
    ))
    || ' \par '
    || 'UNIDAD DE SERVICIO AL CLIENTE: BOGOTA 3077050 - LINEA NACIONAL 018000 113390'), '"', ''), ' \PAR ', ' \par ') ret
  INTO vret
    -- AMJ 29/11/2012 BUG:24827. Se cambia el agente de 2 a3
    --FROM (SELECT pac_agentes.f_get_cageliq(seg.cempres, 2, seg.cagente) sucursal,
    -- BUG:24878 AMJ 08/01/2013 se cambia direccion y telefono de intermediario por sucursal y notificacion debe ser con
    -- nombre de adn.
    /*FROM (SELECT pac_agentes.f_get_cageliq(seg.cempres, 3, seg.cagente) sucursal,
    seg.cagente
    FROM seguros seg
    WHERE seg.sseguro = psseguro) s;*/
  FROM
    (SELECT DECODE(pac_agentes.f_get_cageliq(seg.cempres, 2, seg.cagente), cagente, pac_agentes.f_get_cageliq(seg.cempres, 3, seg.cagente), pac_agentes.f_get_cageliq(seg.cempres, 2, seg.cagente)) sucursal,
      seg.cagente
    FROM seguros seg
    WHERE seg.sseguro = psseguro
    ) s;
  RETURN f_jrep_trad(vret);
EXCEPTION
WHEN OTHERS THEN
  RETURN '';
END f_notificaciones;
/*****************************************************************
FUNCTION f_vfijo
pcvalor   IN pnumero  :
pcempres   IN pnumero  :
pcatribu  IN pnumero  :
return               : varchar2
Bug 20905 - 14/02/2012 - JTS
******************************************************************/
FUNCTION f_vfijo(
    pcvalor  IN NUMBER,
    pcempres IN NUMBER,
    pcatribu IN NUMBER,
    pcidioma IN NUMBER)
  RETURN VARCHAR2
IS
  vret VARCHAR2(100);
BEGIN
  SELECT cvalemp
  INTO vret
  FROM int_codigos_emp
  WHERE ccodigo =
    (SELECT ccodigo
    FROM int_codigos
    WHERE ccodaxis = TO_CHAR(pcvalor)
    AND ccodigo    = 'VF'
      || pcvalor
      || '_IMP'
    AND ctipval = 1
    )
  AND cvalaxis = pcatribu
  AND cempres  = pcempres;
  RETURN vret;
EXCEPTION
WHEN NO_DATA_FOUND THEN
  RETURN ff_desvalorfijo(pcvalor, pcidioma, pcatribu);
END f_vfijo;
/*****************************************************************
FUNCTION f_dades_persona
p_sperson IN NUMBER
p_tipo IN NUMBER
p_idioma IN NUMBER
p_mode IN VARCHAR2
******************************************************************/
FUNCTION f_dades_persona(
    p_sperson IN NUMBER,
    p_tipo    IN NUMBER,
    p_idioma  IN NUMBER DEFAULT 1,
    p_mode    IN VARCHAR2 DEFAULT 'POL')
  RETURN VARCHAR2
IS
  -- 1 DNI, 2 Data Naixement , 3 Sexe , 4 nom, 5 cognoms , 6 pais, 7 nacionalitat, 8 tipus document
  v_tipdoc    VARCHAR2(100);
  v_nombre    VARCHAR2(200);
  v_apellidos VARCHAR2(200);
  v_fecha     VARCHAR2(10);
  --
  -- INI BUG 0053334 - 17/06/2019 - CASL - Se crean nuevas variables
  --
  vnombre    VARCHAR2(2000);
  vapellidos VARCHAR2(2000);
  --
  -- FIN BUG 0053334 - 17/06/2019 - CASL
  --
  -- INI JGB Bug:51673 21/05/2019 campos adicionales para reporte
  v_apelli1 VARCHAR2(200);
  v_apelli2 VARCHAR2(200);
  v_numide  VARCHAR2(100);
BEGIN
  IF p_tipo NOT IN (4, 5, 8, 9, 10, 11, 12) THEN
    RETURN pac_isqlfor.f_dades_persona(p_sperson, p_tipo, p_idioma, p_mode);
  ELSIF p_tipo IN (4, 5, 10, 11) THEN
    IF p_mode = 'POL' THEN
      SELECT TRIM(tnombre) nombre,
        TRIM(tapelli1
        || ' '
        || tapelli2) apellidos,
        REPLACE(DECODE(tapelli1, NULL, NULL, tapelli1), CHR(39), CHR(39)
        || CHR(39)),
        REPLACE(DECODE(tapelli2, NULL, NULL, tapelli1), CHR(39), CHR(39)
        || CHR(39))
      INTO v_nombre,
        v_apellidos,
        v_apelli1,
        v_apelli2
      FROM per_detper
      WHERE sperson = p_sperson
      AND ROWNUM    = 1;
      --
      -- INI BUG 0053334 - 17/06/2019 - CASL - Se obtiene el nombre con caracteres especiales
      --
      BEGIN
        --
        SELECT TRIM(tnombre) nombre,
          TRIM(tapelli1
          || ' '
          || tapelli2) apellidos
        INTO vnombre,
          vapellidos
        FROM per_detper_ce
        WHERE sperson = p_sperson
        AND ROWNUM    = 1;
        --
        v_nombre    := vnombre;
        v_apellidos := vapellidos;
        --
      EXCEPTION
      WHEN OTHERS THEN
        --
        NULL;
        --
      END;
      --
      -- FIN BUG 0053334 - 17/06/2019 - CASL
      --
    ELSE
      SELECT TRIM(tnombre1
        || ' '
        || tnombre2) nombre,
        TRIM(tapelli1
        || ' '
        || tapelli2) apellidos,
        REPLACE(DECODE(tapelli1, NULL, NULL, tapelli1), CHR(39), CHR(39)
        || CHR(39)),
        REPLACE(DECODE(tapelli2, NULL, NULL, tapelli1), CHR(39), CHR(39)
        || CHR(39))
      INTO v_nombre,
        v_apellidos,
        v_apelli1,
        v_apelli2
      FROM estper_detper p
      WHERE p.sperson = p_sperson
      AND ROWNUM      = 1;
      --
      -- INI BUG 0053334 - 17/06/2019 - CASL - Se obtiene el nombre con caracteres especiales
      --
      BEGIN
        --
        SELECT TRIM(tnombre) nombre,
          TRIM(tapelli1
          || ' '
          || tapelli2) apellidos
        INTO vnombre,
          vapellidos
        FROM estper_detper_ce
        WHERE sperson = p_sperson
        AND ROWNUM    = 1;
        --
        v_nombre    := vnombre;
        v_apellidos := vapellidos;
        --
      EXCEPTION
      WHEN OTHERS THEN
        --
        NULL;
        --
      END;
      --
      -- FIN BUG 0053334 - 17/06/2019 - CASL
      --
    END IF;
    --Ini Bug  26902 -- ECP -- 21/05/2013
    IF p_tipo = 4 THEN
      RETURN REPLACE(REPLACE(v_nombre, CHR(34), CHR(180)), CHR(39), CHR(180));
    ELSIF p_tipo = 5 THEN
      RETURN REPLACE(REPLACE(v_apellidos, CHR(34), CHR(180)), CHR(39), CHR(180));
    ELSIF p_tipo = 10 THEN
      RETURN REPLACE(REPLACE(v_apelli1, CHR(34), CHR(180)), CHR(39), CHR(180));
    ELSIF p_tipo = 11 THEN
      RETURN REPLACE(REPLACE(v_apelli2, CHR(34), CHR(180)), CHR(39), CHR(180));
    END IF;
    --Fin Bug  26902 -- ECP -- 21/05/2013
  ELSIF p_tipo IN (8, 12) THEN
    --Ini Bug  32232 -- LRGG -- 10/04/2017
    --Se modificÃ¿Â³ porque no indicaba el tipo = 8 que es tipo documento
    IF NVL(p_mode, 'POL') = 'EST' THEN
      SELECT f_vfijo(672, 12, p.ctipide, 8),
        nnumide
      INTO v_tipdoc,
        v_numide
      FROM estper_personas p
      WHERE p.sperson = p_sperson;
    ELSE
      SELECT f_vfijo(672, 12, p.ctipide, 8),
        nnumide
      INTO v_tipdoc,
        v_numide
      FROM per_personas p
      WHERE p.sperson = p_sperson;
    END IF;
    IF p_tipo = 8 THEN
      RETURN v_tipdoc;
    ELSIF p_tipo = 12 THEN
      RETURN v_numide;
    END IF;
    --Fin Bug  32232 -- LRGG -- 10/04/2017
    --Ini Bug  32232 -- LRGG -- 10/04/2017
  ELSE
    IF p_tipo = 9 THEN
      BEGIN
        IF p_mode = 'POL' THEN
          SELECT fnacimi INTO v_fecha FROM per_personas a WHERE a.sperson = p_sperson;
        ELSE
          SELECT fnacimi
          INTO v_fecha
          FROM estper_personas a
          WHERE a.sperson = p_sperson;
        END IF;
        --RETURN REPLACE(REPLACE(v_fecha, CHR(34), CHR(180)), CHR(39), CHR(180));
      EXCEPTION
      WHEN NO_DATA_FOUND THEN
        NULL;
      END;
      RETURN v_fecha;
    END IF;
    --Fin Bug  32232 -- LRGG -- 10/04/2017
  END IF;-- FIN JGB Bug:51673 21/05/2019 campos adicionales para reporte
END f_dades_persona;
/*****************************************************************
FUNCTION f_fvencim
psseguro   IN pnumero  :
return               : varchar2
Bug 20905 - 16/02/2012 - JTS
******************************************************************/
FUNCTION f_fvencim(
    psseguro IN NUMBER,
    ptablas  IN VARCHAR2 DEFAULT 'POL', --BUG 47494 MPC 08/03/2019 Se adiciona parametro.
    psproces IN NUMBER DEFAULT NULL)    --BUG 47494 MPC 08/03/2019 Se adiciona parametro.
  RETURN DATE
IS
  fvencim     DATE;
  vcduraci    NUMBER;
  vdd         VARCHAR2(2);
  vfefecto    DATE;
  vnrenova    NUMBER;
  vfcaranu    DATE;
  v_ncertif   NUMBER; --BUG 47494 MPC 08/03/2019 Se crea variable.
  v_exist_rec NUMBER; --BUG 47494 MPC 08/03/2019 Se crea variable.
BEGIN
  SELECT cduraci
  INTO vcduraci
  FROM productos
  WHERE sproduc =
    (SELECT sproduc FROM seguros WHERE sseguro = psseguro
    );
  IF vcduraci = 0 THEN --si es anual
    --INI BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
    IF NVL(ptablas,'POL') = 'CAR' THEN
      --
      SELECT ncertif,
        (SELECT COUNT(*)
        FROM reciboscar
        WHERE sseguro = s.sseguro
        AND sproces   = psproces
        )
      INTO v_ncertif,
        v_exist_rec
      FROM seguros s
      WHERE sseguro = psseguro;
      --
      IF v_ncertif = 0 AND v_exist_rec = 0 THEN
        --
        SELECT MAX(r.fvencim)
        INTO fvencim
        FROM reciboscar r,
          detreciboscar d
        WHERE r.nrecibo = d.nrecibo
        AND r.sproces   = psproces;
        --
      ELSE
        --
        SELECT MAX(r.fvencim)
        INTO fvencim
        FROM reciboscar r,
          detreciboscar d
        WHERE r.nrecibo = d.nrecibo
        AND r.sseguro   = psseguro
        AND r.sproces   = psproces;
        --
      END IF;
      --
      RETURN fvencim;
      --
    ELSE
      --FIN BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
      SELECT s.fcaranu
      INTO fvencim
      FROM seguros s
      WHERE s.sseguro = psseguro;
      IF fvencim     IS NULL THEN
        SELECT fefecto,
          nrenova
        INTO vfefecto,
          vnrenova
        FROM seguros
        WHERE sseguro = psseguro;
        vdd          := SUBSTR(LPAD(vnrenova, 4, 0), 3, 2);
        vfcaranu     := f_summeses(vfefecto, 12, vdd);
        RETURN vfcaranu;
      END IF;
    END IF; --BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
  ELSE
    BEGIN --si tiene informada pregunta 4778
      SELECT TO_DATE(crespue, 'yyyymmdd')
      INTO fvencim
      FROM pregunpolseg
      WHERE cpregun = 4778
      AND sseguro   = psseguro
      AND nmovimi   =
        (SELECT MAX(nmovimi)
        FROM pregunpolseg
        WHERE cpregun = 4778
        AND sseguro   = psseguro
        );
    EXCEPTION --en cualquier otro caso
    WHEN NO_DATA_FOUND THEN
      SELECT NVL(s.fvencim, ADD_MONTHS(p.fnacimi, 1200))
      INTO fvencim
      FROM seguros s,
        asegurados a,
        per_personas p
      WHERE s.sseguro = psseguro
      AND a.sseguro   = s.sseguro
      AND p.sperson   = a.sperson
      AND a.norden    = 1;
    END;
  END IF;
  RETURN fvencim;
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_fvencim;
