END f_importes_mov;
/*****************************************************************
INI BUG 47494 MPC 08/03/2019 Se adiciona funcion.
FUNCTION f_importes_movcar
psseguro   IN pnumero  :
psproces   IN pnumero  :
pcampo     IN pnumero  :
return               : varchar2
Bug 20905 - 20/02/2012 - JTS
******************************************************************/
FUNCTION f_importes_movcar(
    psseguro IN NUMBER,
    psproces IN NUMBER,
    pnrecibo IN NUMBER,
    pfemisio IN DATE,
    pcampo   IN NUMBER,
    pcdup    IN NUMBER DEFAULT 0)
  RETURN VARCHAR2
IS
  vimporte     VARCHAR2(20);
  vimporte_aux NUMBER; --BUG 47494 MPC 08/03/2019 Se crea variable.
  --
  v_ult_nrecibo NUMBER;
  v_crespue4084 NUMBER; --BUG 47494 MPC 03/05/2019 Se crea variable.
  v_sproduc NUMBER;--INTRAO-133 31/08/2022 INICIO HRE (INTRAO-89)
  --
BEGIN
  --
  DBMS_OUTPUT.put_line('ENTRO: pcampo:'||pcampo);
  IF pcdup = 1 THEN
    RETURN NULL;
  END IF;
  --INI BUG 47494 MPC 03/05/2019 Se adiciona consulta.
  BEGIN
    SELECT crespue
    INTO v_crespue4084
    FROM pregunpolseg
    WHERE cpregun = 4084
    AND sseguro   = psseguro
    AND nmovimi   =
      (SELECT MAX(nmovimi)
      FROM pregunpolseg
      WHERE sseguro = psseguro
      AND cpregun   = 4084
      );
  EXCEPTION
  WHEN NO_DATA_FOUND THEN
    v_crespue4084 := 2; -- por defecto
  END;
  --FIN BUG 47494 MPC 03/05/2019 Se adiciona consulta.
  IF pcampo = 1 THEN
    --INI BUG 47494 MPC 03/05/2019 Se adiciona condicion
    IF v_crespue4084 = 1 THEN
      vimporte      := 'Cobro con base en los despachos';
    ELSE
      --FIN BUG 47494 MPC 03/05/2019 Se adiciona condicion
      SELECT pac_isqlfor_lcol.f_imporignomon(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) *(iprinet + irecfra + icednet + it2rec)))
      INTO vimporte
      FROM vdetreciboscar v,
        reciboscar r
      WHERE r.sproces = v.sproces
      AND r.nrecibo   = v.nrecibo
      AND r.sseguro   = psseguro
      AND r.sproces   = psproces
      AND r.nrecibo  IN
        (SELECT nrecibo
        FROM detreciboscar
        WHERE nrecibo = r.nrecibo
        AND sproces   = r.sproces
        );
      --
      IF NVL(vimporte,'0') = '0' THEN
        --
        SELECT pac_isqlfor_lcol.f_imporignomon(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) *(iprinet + irecfra + icednet + it2rec)))
        INTO vimporte
        FROM vdetreciboscar v,
          reciboscar r,
          seguros s
        WHERE r.nrecibo = v.nrecibo
        AND r.sproces   = v.sproces
        AND r.sseguro   = s.sseguro
        AND s.npoliza  IN
          (SELECT NPOLIZA FROM SEGUROS WHERE SSEGURO = psseguro
          )
        AND r.nrecibo IN
          (SELECT nrecibo
          FROM detreciboscar
          WHERE nrecibo = r.nrecibo
          AND sproces   = r.sproces
          )
        AND r.sproces = psproces;
        --
      END IF;
      --
    END IF; --BUG 47494 MPC 03/05/2019 Se adiciona condiciÃ³n.
  END IF;
  IF pcampo = 2 THEN
    --
    SELECT fu_formato(p_valor => (NVL((pac_eco_tipocambio.f_cambio(pac_monedas.f_cmoneda_t(NVL(p.cdivisa, f_parinstalacion_n('MONEDAINST'))), 'COP', NVL(pac_eco_tipocambio.f_fecha_max_cambio(pac_monedas.f_cmoneda_t(NVL(p.cdivisa, f_parinstalacion_n('MONEDAINST'))), 'COP', pfemisio), pfemisio))), 1)))
    INTO vimporte
    FROM seguros s,
      productos p
    WHERE s.sseguro = psseguro
    AND s.sproduc   = p.sproduc;
    --
  END IF;
  IF pcampo > 2 AND pcampo <= 12 THEN
    --INI BUG 47494 MPC 03/05/2019 Se adiciona condicion
    IF v_crespue4084 = 1 THEN
      vimporte      := 'Cobro con base en los despachos';
    ELSE
      --FIN BUG 47494 MPC 03/05/2019 Se adiciona condicion
      SELECT DECODE( pcampo, 3, pac_isqlfor_lcol.f_impcop(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * (iprinet + irecfra + icednet)), 1), 4, pac_isqlfor_lcol.f_impcop(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * iderreg), 1), 5, pac_isqlfor_lcol.f_impcop(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * itotalr), 1), 6, pac_isqlfor_lcol.f_imp(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * (iprinet + irecfra + icednet)), 1), 7, pac_isqlfor_lcol.f_imp(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * iderreg), 1), 8, pac_isqlfor_lcol.f_imp(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * itotalr), 1), 10, pac_isqlfor_lcol.f_imp(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * it1imp), 1), 11, pac_isqlfor_lcol.f_imp(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * it1imp)+SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) *(iprinet + irecfra + icednet)),1) , 12, pac_isqlfor_lcol.f_imp(psseguro, SUM(DECODE(
        r.ctiprec, 9,                                                                        -1, 13, 0, 15, 0, 1) * it2rec), 1))
      INTO vimporte
      FROM vdetreciboscar v,
        reciboscar r
      WHERE r.sproces = v.sproces
      AND r.sproces   = psproces
      AND r.nrecibo   = v.nrecibo
      AND r.sseguro   = psseguro
      AND r.nrecibo   =
        (SELECT MAX(y.nrecibo)
        FROM detreciboscar d,
          reciboscar y
        WHERE y.sproces = d.sproces
        AND y.nrecibo   = d.nrecibo
        AND y.sseguro   = r.sseguro
        AND y.sproces   = r.sproces
        );
        --INTRAO-133 31/08/2022 INICIO HRE (INTRAO-89)
      --IF NVL(vimporte,'0') = '0' THEN
        BEGIN
        SELECT sproduc
        INTO v_sproduc
        FROM seguros
        WHERE sseguro = psseguro;
        EXCEPTION
          WHEN OTHERS THEN
            v_sproduc := NULL;
        END;
        IF (NVL(vimporte,'0') = '0' AND pcampo != 7 AND v_sproduc != 900747) THEN
        --INTRAO-133 31/08/2022 FIN HRE (INTRAO-89)
        --
        SELECT DECODE( pcampo, 3, pac_isqlfor_lcol.f_impcop(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * (iprinet + irecfra + icednet)), 1), 4, pac_isqlfor_lcol.f_impcop(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * iderreg), 1), 5, pac_isqlfor_lcol.f_impcop(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * itotalr), 1), 6, pac_isqlfor_lcol.f_imp(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * (iprinet + irecfra + icednet)), 1), 7, pac_isqlfor_lcol.f_imp(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * iderreg), 1), 8, pac_isqlfor_lcol.f_imp(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * itotalr), 1), 10, pac_isqlfor_lcol.f_imp(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * it1imp), 1), 11, pac_isqlfor_lcol.f_imp(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * it1imp)+SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) *(iprinet + irecfra + icednet)),1) , 12, pac_isqlfor_lcol.f_imp(psseguro, SUM(DECODE(
          r.ctiprec, 9,                                                                        -1, 13, 0, 15, 0, 1) * it2rec), 1) )
        INTO vimporte
        FROM vdetreciboscar v,
          reciboscar r,
          seguros s
        WHERE r.nrecibo = v.nrecibo
        AND r.sproces   = v.sproces
        AND r.sproces   = psproces
        AND r.sseguro   = s.sseguro
        AND s.npoliza  IN
          (SELECT NPOLIZA FROM SEGUROS WHERE SSEGURO = psseguro
          )
        AND r.nrecibo =
          (SELECT MAX(y.nrecibo)
          FROM detreciboscar d,
            reciboscar y
          WHERE y.sproces = d.sproces
          AND y.nrecibo   = d.nrecibo
          AND y.sseguro   = r.sseguro
          AND y.sproces   = r.sproces
          );
        --
      END IF;
    END IF; --BUG 47494 MPC 03/05/2019 Se adiciona condicion
  ELSIF pcampo > 12 THEN
    --INI BUG 47494 MPC 03/05/2019 Se adiciona condicion
    IF v_crespue4084 = 1 THEN
      vimporte      := 'Cobro con base en los despachos';
    ELSE
      --FIN BUG 47494 MPC 03/05/2019 Se adiciona condicion
      SELECT SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * it1imp)
      INTO vimporte_aux
      FROM vdetreciboscar v,
        reciboscar r,
        seguros s
      WHERE r.nrecibo = v.nrecibo
      AND r.sproces   = v.sproces
      AND r.sproces   = psproces
      AND r.nrecibo   = v.nrecibo
      AND r.sseguro   = s.sseguro
      AND s.npoliza  IN
        (SELECT NPOLIZA FROM SEGUROS WHERE SSEGURO = psseguro
        )
      AND r.nrecibo =
        (SELECT MAX(y.nrecibo)
        FROM detreciboscar d,
          reciboscar y
        WHERE y.sproces = d.sproces
        AND y.nrecibo   = d.nrecibo
        AND y.sseguro   = r.sseguro
        AND y.sproces   = r.sproces
        );
      --
      vimporte := pac_isqlfor_lcol.f_imp(psseguro,(vimporte_aux + pac_isqlfor_lcol.f_gast4095(psseguro,2,pfemisio)));
      --
    END IF;-- BUG 47494 MPC 03/05/2019 Se adiciona condiciÃ³n.
  END IF;
  RETURN vimporte;
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_importes_movcar;
--FIN BUG 47494 MPC 08/03/2019 Se adiciono nueva funcion.
/*****************************************************************
FUNCTION f_importes_mov_vg
psseguro   IN pnumero  :
pnmovimi   IN pnumero  :
pcampo     IN pnumero  :
return               : varchar2
BUG 25583/0137184 - FAL - 05/02/2013
******************************************************************/
FUNCTION f_importes_mov_vg(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER,
    pcampo   IN NUMBER,
    pcdup    IN NUMBER DEFAULT 0)
  RETURN VARCHAR2
IS
  vimporte VARCHAR2(20);
  --
  --INI BUG 0028151 - 03/03/2017 - CASL - Se crea nueva variable
  --INI BUG 0028151 - 09/03/2017 - CASL - Se crea nueva variable
  --
  v_ult_nrecibo NUMBER;
  v_hay_mov_sig NUMBER;
  --
  --FIN BUG 0028151 - 09/03/2017 - CASL
  --FIN BUG 0028151 - 03/03/2017 - CASL
  --
  -- INICIO 257.0   22/04/2020  INFORCOL FVG-276
  pnmovimi2 NUMBER;
  pnmovimi3 NUMBER;
  nExiste   NUMBER;
  nExisteRH NUMBER;
  -- FIN 257.0   22/04/2020  INFORCOL FVG-276
BEGIN
  --
  --INI BUG 0028151 - 03/03/2017 - CASL - Se valida si la poliza es administrada o agrupada
  --INI BUG 0028151 - 09/03/2017 - CASL - Se valida si la poliza es administrada o agrupada
  --
  v_ult_nrecibo := f_recibo_mov(psseguro => psseguro, pnmovimi => pnmovimi);
  --
  SELECT COUNT(1)
  INTO v_hay_mov_sig
  FROM movseguro
  WHERE sseguro = psseguro
  AND nmovimi   = pnmovimi + 1;
  --
  --FIN BUG 0028151 - 09/03/2017 - CASL
  --FIN BUG 0028151 - 03/03/2017 - CASL
  --
  IF pcdup = 1 THEN
    RETURN NULL;
  END IF;
  --INI BUG 0068006 GZG 27/04/2021 se reversa bug por generar errores en produccion.
  -- INICIO 257.0   22/04/2020  INFORCOL FVG-276
  /*
  BEGIN
    SELECT DISTINCT 1
    INTO nExisteRH
    FROM parproductos P
    WHERE P.sproduc IN
      (SELECT S.sproduc FROM SEGUROS S WHERE S.SSEGURO = psseguro
      )
    AND P.cparpro = 'RHPDF_VIDA_FENIX';
  EXCEPTION
  WHEN NO_DATA_FOUND THEN
    nExisteRH := 0;
  END;
  BEGIN
    SELECT DISTINCT 1
    INTO nExiste
    FROM movseguro
    WHERE SSEGURO = psseguro
    AND NMOVIMI   = pnmovimi
    AND CMOTMOV   = 700;
  EXCEPTION
  WHEN NO_DATA_FOUND THEN
    nExiste := 0;
  END;
  pnmovimi2        := 0;
  IF NVL(nExiste,0) = 1 AND NVL(nExisteRH,0) = 1 THEN
    pnmovimi3      := NVL(pnmovimi,0) - 1;
    DBMS_OUTPUT.put_line(' pnmovimi3: '||pnmovimi3);
    BEGIN
      SELECT MAX(NMOVIMI)
      INTO pnmovimi2
      FROM movseguro M
      WHERE SSEGURO = psseguro
      AND NMOVIMI   = pnmovimi3 - 1
      AND CMOTMOV  <> 700;
    EXCEPTION
    WHEN NO_DATA_FOUND THEN
      pnmovimi2 := NULL;
    END;
    BEGIN
      SELECT NRECIBO
      INTO v_ult_nrecibo
      FROM RECIBOS
      WHERE SSEGURO = psseguro
      AND NMOVIMI   = pnmovimi2;
    EXCEPTION
    WHEN NO_DATA_FOUND THEN
      v_ult_nrecibo := NULL;
    END;
  END IF;
  -- FIN 257.0   22/04/2020  INFORCOL FVG-276
  */
  --FIN BUG 0068006 GZG 27/04/2021
  IF pcampo = 1 THEN
    --
    --Total neto MENOS ajuste prima minima
    SELECT pac_isqlfor_lcol.f_imporignomon(psseguro, net - primin)
    INTO vimporte
    FROM
      (SELECT SUM(net) net,
        SUM(primin) primin
      FROM
        (SELECT SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * (iprinet + irecfra + icednet + icedrfr)) net,
          0 primin
        FROM vdetrecibos v,
          recibos r
        WHERE v.nrecibo IN
          (SELECT nrecibo
          FROM recibos
          WHERE sseguro = psseguro
          AND nmovimi   = NVL(pnmovimi2,pnmovimi) -- INICIO 257.0   22/04/2020  INFORCOL FVG-276
          )
        AND r.nrecibo = v.nrecibo
        AND r.nrecibo = NVL(v_ult_nrecibo, r.nrecibo) --BUG 0028151 - 09/03/2017 - CASL - Se filtra por fecha de efecto del movimiento
        AND r.cestaux = 0
          --AND f_cestrec(r.nrecibo, f_sysdate) <> 2
        AND f_cestrec(r.nrecibo, NULL) <> DECODE(v_hay_mov_sig, 1, 999, 2) --BUG 0028151 - 09/03/2017 - CASL - Se a?aden los recibos anulados
        UNION
        SELECT 0 net,
          NVL( SUM( DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * iconcep), 0) primin
        FROM detrecibos d,
          recibos r
        WHERE d.nrecibo IN
          (SELECT nrecibo
          FROM recibos
          WHERE sseguro = psseguro
          AND nmovimi   = NVL(pnmovimi2,pnmovimi) -- INICIO 257.0   22/04/2020  INFORCOL FVG-276
          )
        AND d.cconcep IN (0, 50) --A pi?on
        AND d.cgarant  = 400     --A pi?on
        AND r.nrecibo  = d.nrecibo
        AND r.nrecibo  = NVL(v_ult_nrecibo, r.nrecibo) --BUG 0028151 - 09/03/2017 - CASL - Se filtra por fecha de efecto del movimiento
        AND r.cestaux  = 0
          --AND f_cestrec(r.nrecibo, f_sysdate) <> 2
        AND f_cestrec(r.nrecibo, NULL) <> DECODE(v_hay_mov_sig, 1, 999, 2) --BUG 0028151 - 09/03/2017 - CASL - Se a?aden los recibos anulados
        GROUP BY r.sseguro
        )
      );
  END IF;
  IF pcampo = 2 THEN
    -- INI BUG 0035054/0200504 - 12/03/2015 - JAE - Tasa de cambio
    -- INI BUG 0035431/0203621 - 29/04/2015 - JAE - Formato numÃ¿Â©rico
    SELECT fu_formato(p_valor => (NVL((pac_eco_tipocambio.f_cambio(pac_monedas.f_cmoneda_t(NVL(p.cdivisa, f_parinstalacion_n('MONEDAINST'))), 'COP', NVL(pac_eco_tipocambio.f_fecha_max_cambio(pac_monedas.f_cmoneda_t(NVL(p.cdivisa, f_parinstalacion_n('MONEDAINST'))), 'COP', d.fcambio), d.fcambio))), 1)))
      --FIN BUG 0035431/0203621 - 29/04/2015 - JAE
    INTO vimporte
    FROM seguros s,
      recibos r,
      detrecibos d,
      productos p
    WHERE s.sseguro = psseguro
    AND r.nmovimi   = NVL(pnmovimi2,pnmovimi)       -- INICIO 257.0   22/04/2020  INFORCOL FVG-276
    AND r.nrecibo   = NVL(v_ult_nrecibo, r.nrecibo) --BUG 0028151 - 09/03/2017 - CASL - Se filtra por fecha de efecto del movimiento
    AND s.sseguro   = r.sseguro
    AND s.sproduc   = p.sproduc
    AND r.nrecibo   = d.nrecibo
    AND ROWNUM      = 1;
    -- FIN BUG 0035054/0200504 - 12/03/2015 - JAE
  END IF;
  --Ajuste de prima m?nima
  IF pcampo = 9 THEN
    SELECT pac_isqlfor_lcol.f_imporignomon(r.sseguro, NVL(SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * iconcep), 0))
    INTO vimporte
    FROM detrecibos d,
      recibos r
    WHERE d.nrecibo IN
      (SELECT nrecibo
      FROM recibos
      WHERE sseguro = psseguro
      AND nmovimi   = NVL(pnmovimi2,pnmovimi) -- INICIO 257.0   22/04/2020  INFORCOL FVG-276
      )
    AND d.cconcep IN (0, 50) --A piÃ¿Â±on
    AND d.cgarant  = 400     --A piÃ¿Â±on
    AND r.nrecibo  = d.nrecibo
    AND r.nrecibo  = NVL(v_ult_nrecibo, r.nrecibo) --BUG 0028151 - 09/03/2017 - CASL - Se filtra por fecha de efecto del movimiento
    AND r.cestaux  = 0
      --AND f_cestrec(r.nrecibo, f_sysdate) <> 2
    AND f_cestrec(r.nrecibo, NULL) <> DECODE(v_hay_mov_sig, 1, 999, 2) --BUG 0028151 - 09/03/2017 - CASL - Se aÃ¿Â±aden los recibos anulados
    GROUP BY r.sseguro;
  END IF;
  IF pcampo > 2 AND pcampo < 9 THEN
    SELECT DECODE( pcampo, 3, pac_isqlfor_lcol.f_impcop(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * (iprinet + irecfra + icednet)), 1), 4, pac_isqlfor_lcol.f_impcop(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * iderreg), 1), 5, pac_isqlfor_lcol.f_impcop(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * itotalr), 1), 6, pac_isqlfor_lcol.f_imp(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * (iprinet + irecfra + icednet + icedrfr)), 1), 7, pac_isqlfor_lcol.f_imp(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * iderreg), 1), 8, pac_isqlfor_lcol.f_imp(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * itotalr), 1), 10, pac_isqlfor_lcol.f_imp(psseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * it1imp), 1))
    INTO vimporte
    FROM vdetrecibos_monpol v,
      recibos r,
      movseguro m
    WHERE r.sseguro = psseguro
    AND r.nrecibo   = NVL(v_ult_nrecibo, r.nrecibo) --BUG 0028151 - 09/03/2017 - CASL - Se filtra por fecha de efecto del movimiento
    AND r.nmovimi   = NVL(pnmovimi2,pnmovimi)       -- INICIO 257.0   22/04/2020  INFORCOL FVG-276
    AND r.nrecibo   = v.nrecibo
    AND r.cestaux   = 0
    AND m.sseguro   = r.sseguro
    AND m.nmovimi   = r.nmovimi
      --AND f_cestrec(r.nrecibo, m.fefecto) <> 2;
    AND f_cestrec(r.nrecibo, NULL) <> DECODE(v_hay_mov_sig, 1, 999, 2); --BUG 0028151 - 09/03/2017 - CASL - Se aÃ¿Â±aden los recibos anulados
    /*
    INTO vimporte
    FROM vdetrecibos_monpol v, recibos r
    WHERE v.nrecibo IN(SELECT nrecibo
    FROM recibos
    WHERE sseguro = psseguro
    AND nmovimi = pnmovimi)
    AND r.nrecibo = v.nrecibo
    AND r.cestaux = 0
    AND f_cestrec(r.nrecibo, f_sysdate) <> 2;
    */
  END IF;
  RETURN vimporte;
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_importes_mov_vg;
/*****************************************************************
FUNCTION f_importes_rec
pnrecibo   IN pnumero  :
pcampo     IN pnumero  :
return               : varchar2
******************************************************************/
FUNCTION f_importes_rec(
    pnrecibo IN NUMBER,
    pcampo   IN NUMBER)
  RETURN VARCHAR2
IS
  vimporte VARCHAR2(20);
BEGIN
  IF pcampo = 1 THEN
    SELECT pac_isqlfor_lcol.f_imporignomon(sseguro, net - primin)
    INTO vimporte
    FROM
      (SELECT SUM(net) net,
        SUM(primin) primin,
        sseguro
      FROM
        (SELECT SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * (iprinet + irecfra + icednet)) net,
          0 primin,
          r.sseguro
        FROM vdetrecibos v,
          recibos r
        WHERE v.nrecibo = pnrecibo
        AND r.nrecibo   = v.nrecibo
        GROUP BY sseguro
        UNION
        SELECT 0 net,
          NVL( SUM( DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * iconcep), 0) primin,
          r.sseguro
        FROM detrecibos d,
          recibos r
        WHERE d.nrecibo = pnrecibo
        AND d.cconcep  IN (0, 50) --A piÃ¿Â±on
        AND d.cgarant   = 400     --A piÃ¿Â±on
        AND r.nrecibo   = d.nrecibo
        GROUP BY sseguro
        )
      GROUP BY sseguro
      );
  END IF;
  --  Ini Bug 0028416 --ECP-- 03/10/2013
  IF pcampo = 2 THEN
    --INI BUG 0035054/0200504 - 23/06/2015 - JAE - Tasa de cambio
    --INI BUG 0035431/0203621 - 29/04/2015 - JAE - Formato numÃ¿Â©rico
    SELECT fu_formato(p_valor => (NVL((pac_eco_tipocambio.f_cambio(pac_monedas.f_cmoneda_t(NVL(p.cdivisa, f_parinstalacion_n('MONEDAINST'))), 'COP', NVL(pac_eco_tipocambio.f_fecha_max_cambio(pac_monedas.f_cmoneda_t(NVL(p.cdivisa, f_parinstalacion_n('MONEDAINST'))), 'COP', d.fcambio), d.fcambio))), 1)))
      --FIN BUG 0035431/0203621 - 29/04/2015 - JAE
    INTO vimporte
    FROM seguros s,
      movseguro m,
      productos p,
      recibos r,
      movrecibo mr,
      detrecibos d
    WHERE r.nrecibo = pnrecibo
    AND m.sseguro   = r.sseguro
    AND m.nmovimi   = r.nmovimi
    AND s.sseguro   = m.sseguro
    AND s.sproduc   = p.sproduc
    AND r.nrecibo   = mr.nrecibo
    AND r.nrecibo   = d.nrecibo
    AND mr.cestrec  = 0
    AND ROWNUM      = 1;
    --FIN BUG 0035054/0200504 - 23/06/2015 - JAE
  END IF;
  --  Fin Bug 0028416 --ECP-- 03/10/2013
  --Ajuste de prima mÃ¿Â­nima
  IF pcampo = 9 THEN
    SELECT pac_isqlfor_lcol.f_imporignomon(r.sseguro, NVL(SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * iconcep), 0))
    INTO vimporte
    FROM detrecibos d,
      recibos r
    WHERE d.nrecibo = pnrecibo
    AND d.cconcep  IN (0, 50) --A piÃ¿Â±on
    AND d.cgarant   = 400     --A piÃ¿Â±on
    AND r.nrecibo   = d.nrecibo
    GROUP BY r.sseguro;
  END IF;
  IF pcampo > 2 THEN
    SELECT DECODE( pcampo, 3, pac_isqlfor_lcol.f_impcop(r.sseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * (iprinet + irecfra + icednet)), 1), 4, pac_isqlfor_lcol.f_impcop(r.sseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * iderreg), 1), 5, pac_isqlfor_lcol.f_impcop(r.sseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * itotalr), 1), 6, pac_isqlfor_lcol.f_imp(r.sseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * (iprinet + irecfra + icednet)), 1), 7, pac_isqlfor_lcol.f_imp(r.sseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * iderreg), 1), 8, pac_isqlfor_lcol.f_imp(r.sseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * itotalr), 1), 10, pac_isqlfor_lcol.f_imp(r.sseguro, SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * it1imp), 1))
    INTO vimporte
    FROM vdetrecibos_monpol v,
      recibos r
    WHERE v.nrecibo = pnrecibo
    AND r.nrecibo   = v.nrecibo
    GROUP BY r.sseguro;
  END IF;
  RETURN vimporte;
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_importes_rec;
/*****************************************************************
FUNCTION f_desc_cta
psseguro   IN pnumero  :
pnnumlin   IN pnumero  :
return               : varchar2
Bug 20905 - 28/02/2012 - JTS ctaseguro
******************************************************************/
FUNCTION f_desc_cta(
    psseguro IN NUMBER,
    pnnumlin IN NUMBER)
  RETURN VARCHAR2
IS
  vret VARCHAR2(150);
BEGIN
  BEGIN
    SELECT SUBSTR(ff_desvalorfijo(83, 2, cmovimi), 1, 20)
    INTO vret
    FROM ctaseguro
    WHERE sseguro = psseguro
    AND nnumlin   = pnnumlin - 1;
  EXCEPTION
  WHEN NO_DATA_FOUND THEN
    SELECT SUBSTR(ff_desvalorfijo(83, 2, cmovimi), 1, 20)
    INTO vret
    FROM ctaseguro
    WHERE sseguro = psseguro
    AND nnumlin   = pnnumlin;
  END;
  RETURN vret;
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_desc_cta;
