v_fanulac  IN pfecha   :
return                 : number
Bug 22530 - 26/06/2012 - GAG valor de cesion
******************************************************************/
FUNCTION f_valor_cesion(
    psseguro  IN NUMBER,
    v_fanulac IN DATE)
  RETURN NUMBER
IS
  PRAGMA AUTONOMOUS_TRANSACTION;
  v_iprovces NUMBER := 0;
BEGIN
  v_iprovces := pac_provmat_formul.f_calcul_formulas_provi(psseguro, TRUNC(v_fanulac), 'IPROVAC');
  RETURN f_round(v_iprovces, pac_oper_monedas.f_monpol(psseguro));
EXCEPTION
WHEN OTHERS THEN
  RETURN f_round(v_iprovces, pac_oper_monedas.f_monpol(psseguro));
END f_valor_cesion;
