/*****************************************************************
Bug 23690 - 01/10/2012 - JLTS, Se adicionan los campos psseguro y pnmovimi
FUNCTION f_view_flimpago
psseguro IN seguros.sseguro%TYPE
pnmovimi IN movseguro.nmovimi%TYPE
pcmotmov   IN pnumero  :
return               : NUMBER
NULL: No existen datos en codimotmov o si no existen registros retornaremos
0 : NO estÃ¿Â¡ en la lista
1 : EstÃ¿Â¡ en la lista
Bug 22365 - 03/07/2012 - JLTS, Muestra fecha lÃ¿Â­mite de pago
100 Alta de Poliza
306 Anulacion sin efecto
307 Falta de pago
314 Decision del cliente con extorno
324 Anulacion inmediata
333 Anulacion por fallo judicial
335 Anulacion por no interes en renovacion
336 Anulacion por seguro saldado
337 Anulacion por seguro prorrogado
368 Baja por Defuncion
503 Anulacion de poliza por edad maxima
926 Baja por error
******************************************************************/
FUNCTION f_view_flimpago(
    psseguro IN seguros.sseguro%TYPE,
    pnmovimi IN movseguro.nmovimi%TYPE,
    pcmotmov IN motmovseg.cmotmov%TYPE)
  RETURN NUMBER
IS
  v_existe NUMBER := 1;
  v_cmovseg motmovseg.cmotmov%TYPE;
  v_contrec NUMBER := 0;
  v_cramo   NUMBER;
  v_sproduc NUMBER;
BEGIN
  --Si se trata del ramo de autos, se imprime siempre -- se adicionan los ramos de Generales
  BEGIN
    SELECT cramo,
      sproduc
    INTO v_cramo,
      v_sproduc
    FROM seguros
    WHERE sseguro = psseguro;
  EXCEPTION
  WHEN NO_DATA_FOUND THEN
    NULL;
  END;
  IF v_cramo IN (104, 105) THEN --Bug 34471/197362 - 04/02/2015 - AMC
    RETURN 1;
  END IF;
  --fin ramo de autos
  -- INI BUG 001994 Impresion fecha limite de pago por paramaotr de producto
  IF NVL(pac_parametros.f_parproducto_n(v_sproduc, 'IMP_FECLIM'), 0) = 1 THEN
    RETURN 1;
  END IF;
  -- FIN BUG 001994 Impresion fecha limite de pago por paramaotr de producto
  --Bug 23690 - 01/10/2012 - JLTS, Inicio
  BEGIN
    SELECT c.cmovseg INTO v_cmovseg FROM codimotmov c WHERE c.cmotmov = pcmotmov;
  EXCEPTION
  WHEN NO_DATA_FOUND THEN
    RETURN 0;
  END;
  IF v_cmovseg = 3 THEN
    RETURN 0;
  ELSIF pcmotmov = 100 THEN
    RETURN 0;
  ELSE
    SELECT COUNT(1)
    INTO v_contrec
    FROM recibos r
    WHERE r.sseguro = psseguro
    AND r.nmovimi   = pnmovimi
    AND ctiprec    <> 3;
    IF v_contrec    = 0 THEN
      RETURN 0;
    ELSE
      --Bug 23690 - 01/10/2012 - JLTS, Fin
      SELECT (
        CASE
          WHEN pcmotmov IN (100, --    Alta de Poliza
            306,                 --   Anulacion sin efecto
            307,                 --   Falta de pago
            314,                 --   Decision del cliente con extorno
            324,                 --   Anulacion inmediata
            333,                 --   Anulacion por fallo judicial
            335,                 --   Anulacion por no interes en renovacion
            336,                 --   Anulacion por seguro saldado
            337,                 --   Anulacion por seguro prorrogado
            368,                 --   Baja por Defuncion
            503,                 --   Anulacion de poliza por edad maxima
            926)                 --   Baja por error
          THEN 0
          ELSE 1
        END) existe
      INTO v_existe
      FROM DUAL;
    END IF;
  END IF;
  RETURN v_existe;
END f_view_flimpago;
FUNCTION f_intermediarios(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER,
    pcolumn  IN NUMBER,
    pnriesgo IN NUMBER DEFAULT NULL)--BUG AITSSD-8693 GZG 25/05/2023
  RETURN VARCHAR2
IS
  vret VARCHAR2(2000);
BEGIN
  vret := NULL;
  IF pnriesgo IS NULL THEN--BUG AITSSD-8693 GZG 25/05/2023
  FOR i IN
  (SELECT ac.cagente,
    pac_isqlfor.f_agente(ac.cagente) tagente,
    pac_isqlfor.f_per_contactos(
    (SELECT a.sperson FROM agentes a WHERE a.cagente = ac.cagente
    ), 1) telf,
    ac.ppartici
    || '%' porc_part
  FROM age_corretaje ac
  WHERE ac.sseguro = psseguro
  AND nmovimi      =
    (SELECT MAX(nmovimi)
    FROM age_corretaje
    WHERE sseguro = psseguro
    AND nmovimi  <= pnmovimi
    )
  ORDER BY islider DESC,
    cagente
  )
  LOOP
    IF pcolumn    = 1 THEN
      vret       := vret || i.cagente || ' \par ';
    ELSIF pcolumn = 2 THEN
      vret       := vret || i.tagente || ' \par ';
    ELSIF pcolumn = 3 THEN
      vret       := vret || i.telf || ' \par ';
    ELSIF pcolumn = 4 THEN
      vret       := vret || i.porc_part || ' \par ';
    END IF;
  END LOOP;
  --INI BUG AITSSD-8693 GZG 25/05/2023
  ELSE
    FOR i IN
  (SELECT ac.cagente,
    pac_isqlfor.f_agente(ac.cagente) tagente,
    pac_isqlfor.f_per_contactos(
    (SELECT a.sperson FROM agentes a WHERE a.cagente = ac.cagente
    ), 1) telf,
    ac.ppartici
    || '%' porc_part
  FROM plan_age_corretaje ac
  WHERE ac.sseguro = psseguro
  AND nmovimi      =
    (SELECT MAX(nmovimi)
    FROM plan_age_corretaje
    WHERE sseguro = psseguro
    AND nmovimi  <= pnmovimi
    AND nriesgo = pnriesgo
    )
  AND nriesgo = pnriesgo
  ORDER BY islider DESC,
    cagente
  )
  LOOP
    IF pcolumn    = 1 THEN
      vret       := vret || i.cagente || ' \par ';
    ELSIF pcolumn = 2 THEN
      vret       := vret || i.tagente || ' \par ';
    ELSIF pcolumn = 3 THEN
      vret       := vret || i.telf || ' \par ';
    ELSIF pcolumn = 4 THEN
      vret       := vret || i.porc_part || ' \par ';
    END IF;
  END LOOP;
  END IF;
  --FIN BUG AITSSD-8693 GZG 25/05/2023
  RETURN f_jrep_trad(vret);
EXCEPTION
WHEN OTHERS THEN
  RETURN '';
END f_intermediarios;
/*****************************************************************
FUNCTION f_recibo_tipo
psseguro   IN pnumero  :
pnmovimi   IN numbe   :
pctipo IN number
return                 : number
Bug 0024878 - 28/11/2012 - ECP- tipo recibo
******************************************************************/
FUNCTION f_recibo_tipo(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER,
    pctipo   IN NUMBER,
    pcdup    IN NUMBER DEFAULT 0)
  RETURN NUMBER
IS
  v_nrecibo recibos.nrecibo%TYPE;
  --
  --INI BUG 0028151 - 03/03/2017 - CASL - Se crea nueva variable
  --INI BUG 0028151 - 09/03/2017 - CASL - Se crea nueva variable
  --
  v_ult_nrecibo NUMBER;
  --
  --FIN BUG 0028151 - 09/03/2017 - CASL
  --FIN BUG 0028151 - 03/03/2017 - CASL
  --
BEGIN
  --
  --INI BUG 0028151 - 03/03/2017 - CASL - Se valida si la poliza es administrada o agrupada
  --INI BUG 0028151 - 09/03/2017 - CASL - Se valida si la poliza es administrada o agrupada
  --
  v_ult_nrecibo := f_recibo_mov(psseguro => psseguro, pnmovimi => pnmovimi);
  --
  --FIN BUG 0028151 - 09/03/2017 - CASL
  --FIN BUG 0028151 - 03/03/2017 - CASL
  --
  IF pcdup = 1 THEN
    RETURN NULL;
  END IF;
  SELECT MIN(nrecibo)
  INTO v_nrecibo
  FROM
    (SELECT r.nrecibo
    FROM recibos r,
      seguros s,
      detrecibos d,
      pargaranpro p
    WHERE s.sseguro = psseguro
    AND r.sseguro   = s.sseguro
    AND r.nmovimi   = pnmovimi
    AND r.nrecibo   = NVL(v_ult_nrecibo, r.nrecibo) --BUG 0028151 - 09/03/2017 - CASL - Se filtra por fecha de efecto del movimiento
    AND r.nrecibo   = d.nrecibo
    AND s.sproduc   = p.sproduc
    AND d.cgarant   = p.cgarant
    AND p.cpargar   = 'TIPO'
    AND p.cvalpar   = pctipo
    GROUP BY r.nrecibo
    );
  RETURN v_nrecibo;
EXCEPTION
WHEN OTHERS THEN
  RETURN '';
END f_recibo_tipo;
/*****************************************************************
FUNCTION f_recibo_tipo_vg
psseguro   IN pnumero  :
pnmovimi   IN numbe   :
pctipo IN number
return                 : number
BUG 25583/0137184 - FAL - 05/02/2013
******************************************************************/
FUNCTION f_recibo_tipo_vg(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER,
    pcdup    IN NUMBER DEFAULT 0)
  RETURN NUMBER
IS
  v_nrecibo recibos.nrecibo%TYPE;
  --
  --INI BUG 0028151 - 03/03/2017 - CASL - Se crea nueva variable
  --INI BUG 0028151 - 09/03/2017 - CASL - Se crea nueva variable
  --
  v_ult_nrecibo NUMBER;
  v_hay_mov_sig NUMBER;
  --
  --FIN BUG 0028151 - 09/03/2017 - CASL
  --FIN BUG 0028151 - 03/03/2017 - CASL
  --
BEGIN
  --
  --INI BUG 0028151 - 03/03/2017 - CASL - Se valida si la poliza es administrada o agrupada
  --INI BUG 0028151 - 09/03/2017 - CASL - Se valida si la poliza es administrada o agrupada
  --
  v_ult_nrecibo := f_recibo_mov(psseguro => psseguro, pnmovimi => pnmovimi);
  --
  SELECT COUNT(1)
  INTO v_hay_mov_sig
  FROM movseguro
  WHERE sseguro = psseguro
  AND nmovimi   = pnmovimi + 1;
  --
  --FIN BUG 0028151 - 09/03/2017 - CASL
  --FIN BUG 0028151 - 03/03/2017 - CASL
  --
  IF pcdup = 1 THEN
    RETURN NULL;
  END IF;
  BEGIN
    SELECT r.nrecibo
    INTO v_nrecibo
    FROM recibos r,
      seguros s
    WHERE s.sseguro = psseguro
    AND r.sseguro   = s.sseguro
    AND r.nmovimi   = pnmovimi
    AND r.nrecibo   = NVL(v_ult_nrecibo, r.nrecibo) --BUG 0028151 - 09/03/2017 - CASL - Se filtra por fecha de efecto del movimiento
    AND r.cestaux   = 0
    AND f_cestrec(r.nrecibo, (
      CASE
        WHEN r.fefecto > f_sysdate
        THEN r.fefecto
        ELSE f_sysdate
      END)) <> DECODE(v_hay_mov_sig, 1, 999, 2) --INI BUG 0028151 - 09/03/2017 - CASL - Se valida si la poliza es administrada o agrupada
    GROUP BY r.nrecibo;
  EXCEPTION
  WHEN OTHERS THEN
    SELECT r.nrecibo
    INTO v_nrecibo
    FROM recibos r,
      seguros s
    WHERE s.sseguro    = psseguro
    AND r.sseguro      = s.sseguro
    AND r.nmovimi      = pnmovimi
    AND r.nrecibo      = NVL(v_ult_nrecibo, r.nrecibo) --BUG 0028151 - 09/03/2017 - CASL - Se filtra por fecha de efecto del movimiento
    AND r.ctiprec NOT IN (13, 15)
    AND r.cestaux      = 0
    AND f_cestrec(r.nrecibo, (
      CASE
        WHEN r.fefecto > f_sysdate
        THEN r.fefecto
        ELSE f_sysdate
      END)) <> DECODE(v_hay_mov_sig, 1, 999, 2) --BUG 0028151 - 09/03/2017 - CASL - Se aÃ¿Â±aden los recibos anulados
    GROUP BY r.nrecibo;
  END;
  RETURN v_nrecibo;
EXCEPTION
WHEN OTHERS THEN
  RETURN '';
END f_recibo_tipo_vg;
/*****************************************************************
FUNCTION f_es_recibo_tipo
pnrecibo   IN pnumero  :
pctipo IN number
return                 : number
******************************************************************/
FUNCTION f_es_recibo_tipo(
    pnrecibo IN NUMBER,
    pctipo   IN NUMBER)
  RETURN NUMBER
IS
  vcount NUMBER;
BEGIN
  SELECT COUNT(1)
  INTO vcount
  FROM recibos r,
    seguros s,
    detrecibos d,
    pargaranpro p
  WHERE r.sseguro = s.sseguro
  AND r.nrecibo   = d.nrecibo
  AND s.sproduc   = p.sproduc
  AND d.cgarant   = p.cgarant
  AND p.cpargar   = 'TIPO'
  AND p.cvalpar   = pctipo
  AND r.nrecibo   = pnrecibo;
  IF vcount       > 0 THEN
    RETURN pnrecibo;
  ELSE
    RETURN '';
  END IF;
EXCEPTION
WHEN OTHERS THEN
  RETURN '';
END f_es_recibo_tipo;
-- INICIO 256.0   21/04/2020   INFORCOL
FUNCTION f_planes_vida(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnmovimi IN NUMBER,
    -- INICIO 258.0   24/04/2020  INFORCOL  FVG-277
    pnriesgo IN NUMBER,
    -- FIN 258.0   24/04/2020  INFORCOL  FVG-277
    pcidioma IN NUMBER DEFAULT 1)
  RETURN VARCHAR2
IS
  CURSOR v_cur
  IS
    -- BUG 0035431/0203621 - 29/04/2015 - JAE - Formato numÿ©rico
    SELECT NVL( r.tnatrie, TRIM(pac_isqlfor_lcol.f_dades_persona(r.sperson, 4)
      || ' '
      || pac_isqlfor_lcol.f_dades_persona(r.sperson, 5))) nomplan,
      gg.tgarant amparoplan,
      fu_formato(p_valor => (NVL(pac_preguntas.f_get_pregungaranseg_v(r.sseguro, g.cgarant, r.nriesgo, 4081, 'POL'), g.icapital))) valorasegplan,
      --FIN BUG 0035431/0203621 - 29/04/2015 - JAE
      TO_CHAR(NVL(g.prevali, 0), 'FM990D00') incrementoplan
    FROM riesgos r,
      garanseg g,
      garangen gg,
      garanpro ga
    WHERE r.sseguro = psseguro
    AND pnmovimi BETWEEN r.nmovima AND NVL(r.nmovimb, pnmovimi)
    AND g.sseguro  = r.sseguro
    -- INICIO 273.0   30/03/2021  INFORCOL   273. FVG-575
    AND g.nmovimi = pnmovimi
    -- FIN 273.0   30/03/2021  INFORCOL   273. FVG-575
    AND g.nriesgo  = r.nriesgo
    AND gg.cgarant = g.cgarant
    AND gg.cidioma = pcidioma
      -- INICIO 258.0   24/04/2020  INFORCOL  FVG-277
    AND r.nriesgo = pnriesgo
      -- FIN 258.0   24/04/2020  INFORCOL  FVG-277
    AND gg.cgarant = ga.cgarant
    AND EXISTS
      (SELECT 1
      FROM seguros se
      WHERE se.sseguro = g.sseguro
      AND se.sproduc   = ga.sproduc
      )
  GROUP BY NVL(r.tnatrie, TRIM(pac_isqlfor_lcol.f_dades_persona(r.sperson, 4)
    || ' '
    || pac_isqlfor_lcol.f_dades_persona(r.sperson, 5))),
    gg.tgarant,
    -- fu_formato(p_valor => (
    NVL(pac_preguntas.f_get_pregungaranseg_v(r.sseguro, g.cgarant, r.nriesgo, 4081, 'POL'), g.icapital),--)),
    --'FM999G999G999G999G999G990D00'),
    TO_CHAR(NVL(g.prevali, 0), 'FM990D00'),
    ga.norden
  ORDER BY NVL(r.tnatrie, TRIM(pac_isqlfor_lcol.f_dades_persona(r.sperson, 4)
    || ' '
    || pac_isqlfor_lcol.f_dades_persona(r.sperson, 5))),
    ga.norden;
  v_tresult VARCHAR2(4000) := '';
  v_count   NUMBER;
BEGIN
  SELECT COUNT(1)
  INTO v_count
  FROM riesgos
  WHERE sseguro = psseguro
  AND pnmovimi BETWEEN nmovima AND NVL(nmovimb, pnmovimi)
    -- INICIO 258.0   24/04/2020  INFORCOL  FVG-277
  AND nriesgo = pnriesgo;
  -- FIN 258.0   24/04/2020  INFORCOL  FVG-277
  IF v_count  >= 1 THEN
    v_tresult := NULL;
    FOR i IN v_cur
    LOOP
      IF pcampo    = 1 THEN
        v_tresult := v_tresult || i.nomplan || '\par ';
      ELSIF pcampo = 2 THEN
        v_tresult := v_tresult || i.amparoplan || '\par ';
      ELSIF pcampo = 3 THEN
        v_tresult := v_tresult || i.valorasegplan || '\par ';
      ELSIF pcampo = 4 THEN
        v_tresult := v_tresult || i.incrementoplan || '\par ';
      END IF;
    END LOOP;
  ELSE
    FOR i IN v_cur
    LOOP
      IF pcampo    = 4 THEN
        v_tresult := i.incrementoplan;
      END IF;
    END LOOP;
  END IF;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_planes_vida;
-- FIN 256.0   21/04/2020   INFORCOL
/*****************************************************************
Bug 24572-XVM-30/11/2012
FUNCTION f_planes
Devuelve los planes de una pÃ¿Â³liza
param IN psseguro  : cÃ¿Â³digo de seguro
param IN pcampo    : 1
param IN pnmovimi  : movimiento
param IN pcidioma  : cÃ¿Â³digo idioma
return             : texto con los planes
******************************************************************/
FUNCTION f_planes(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnmovimi IN NUMBER,
    pcidioma IN NUMBER DEFAULT 1)
  RETURN VARCHAR2
IS
  CURSOR v_cur
  IS
    -- BUG 0035431/0203621 - 29/04/2015 - JAE - Formato numÃ¿Â©rico
    SELECT NVL( r.tnatrie, TRIM(pac_isqlfor_lcol.f_dades_persona(r.sperson, 4)
      || ' '
      || pac_isqlfor_lcol.f_dades_persona(r.sperson, 5))) nomplan,
      gg.tgarant amparoplan,
      fu_formato(p_valor => (NVL(pac_preguntas.f_get_pregungaranseg_v(r.sseguro, g.cgarant, r.nriesgo, 4081, 'POL'), g.icapital))) valorasegplan,
      --FIN BUG 0035431/0203621 - 29/04/2015 - JAE
      TO_CHAR(NVL(g.prevali, 0), 'FM990D00') incrementoplan
    FROM riesgos r,
      garanseg g,
      garangen gg,
      garanpro ga
    WHERE r.sseguro = psseguro
    AND pnmovimi BETWEEN r.nmovima AND NVL(r.nmovimb, pnmovimi)
    AND g.sseguro  = r.sseguro
    AND g.nriesgo  = r.nriesgo
    AND gg.cgarant = g.cgarant
    AND gg.cidioma = pcidioma
    AND gg.cgarant = ga.cgarant
    AND EXISTS
      (SELECT 1
      FROM seguros se
      WHERE se.sseguro = g.sseguro
      AND se.sproduc   = ga.sproduc
      )
  GROUP BY NVL(r.tnatrie, TRIM(pac_isqlfor_lcol.f_dades_persona(r.sperson, 4)
    || ' '
    || pac_isqlfor_lcol.f_dades_persona(r.sperson, 5))),
    gg.tgarant,
    fu_formato(p_valor => (NVL(pac_preguntas.f_get_pregungaranseg_v(r.sseguro, g.cgarant, r.nriesgo, 4081, 'POL'), g.icapital))),
    --'FM999G999G999G999G999G990D00'),
    TO_CHAR(NVL(g.prevali, 0), 'FM990D00'),
    ga.norden
  ORDER BY NVL(r.tnatrie, TRIM(pac_isqlfor_lcol.f_dades_persona(r.sperson, 4)
    || ' '
    || pac_isqlfor_lcol.f_dades_persona(r.sperson, 5))),
    ga.norden;
  v_tresult VARCHAR2(4000) := '';
  v_count   NUMBER;
BEGIN
  SELECT COUNT(1)
  INTO v_count
  FROM riesgos
  WHERE sseguro = psseguro
  AND pnmovimi BETWEEN nmovima AND NVL(nmovimb, pnmovimi);
  IF v_count > 1 THEN
    FOR i IN v_cur
    LOOP
      IF pcampo    = 1 THEN
        v_tresult := v_tresult || i.nomplan || '\par ';
      ELSIF pcampo = 2 THEN
        v_tresult := v_tresult || i.amparoplan || '\par ';
      ELSIF pcampo = 3 THEN
        v_tresult := v_tresult || i.valorasegplan || '\par ';
      ELSIF pcampo = 4 THEN
        v_tresult := v_tresult || i.incrementoplan || '\par ';
      END IF;
    END LOOP;
  ELSE
    FOR i IN v_cur
    LOOP
      IF pcampo    = 4 THEN
        v_tresult := i.incrementoplan;
      END IF;
    END LOOP;
  END IF;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_planes;
/*****************************************************************
Bug 24572-XVM-30/11/2012
FUNCTION f_garantias_certif
Devuelve todas las garantÃ¿Â­as de todos los certificados N
param IN psseguro  : codigo de seguro
param IN pcidioma  : codigo de idioma
return             : texto con las garantÃ¿Â­as
******************************************************************/
FUNCTION f_garantias_certif(
    psseguro IN NUMBER,
    pcidioma IN NUMBER DEFAULT 1,
    pdummy   IN NUMBER DEFAULT 0,
    pnmovimi IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(2000);
    v_tlinia    VARCHAR2(200);
    v_norden garanpro.norden%TYPE;
    v_tpargar   VARCHAR2(200);
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
  BEGIN
    v_tablaseg  := 'seguros';
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    v_tconsulta := 'SELECT p.norden,REPLACE(pac_isqlfor_lcol.f_des_garpro(se.sseguro,s.nriesgo,' || NVL(pcidioma, 2) || ',p.cgarant,se.sproduc,''POL''), CHR(39), CHR(39) || CHR(39)) a';
    v_tconsulta := v_tconsulta || ' FROM garanpro p, ';
    v_tconsulta := v_tconsulta || 'garanseg s, seguros se';
    v_tconsulta := v_tconsulta || ' WHERE ';
    v_tconsulta := v_tconsulta || ' p.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    --v_tconsulta := v_tconsulta || ' AND se.ncertif <> 0';
    v_tconsulta := v_tconsulta || ' AND se.csituac in (0,7,5,2)';
    v_tconsulta := v_tconsulta || ' AND p.CACTIVI = ' || v_actividad;
    --v_tconsulta := v_tconsulta || ' AND s.ffinefe IS NULL';
    v_tconsulta := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro || ')';
    /* Bug 33488/196141 - 20/01/2015
    IF (pnmovimi IS NOT NULL) THEN
    v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
    ELSE
    v_tconsulta := v_tconsulta || ')';
    END IF;
    v_tconsulta := v_tconsulta || ' AND s.sseguro IN (SELECT sseguro FROM seguros';
    v_tconsulta := v_tconsulta
    || ' WHERE npoliza = (SELECT npoliza FROM seguros WHERE sseguro=  '
    || psseguro || '))';*/
    v_tconsulta := v_tconsulta || ' AND se.sseguro =' || psseguro;
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', p.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' GROUP BY REPLACE(pac_isqlfor_lcol.f_des_garpro(se.sseguro, s.nriesgo,' || NVL(pcidioma, 2) || ',p.cgarant, se.sproduc,''POL''), CHR(39), CHR(39) || CHR(39)),p.norden';
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_norden, v_tlinia;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF pdummy = 1 THEN
      --Necesitamos llenar con "intros" columnas vacÃ¿Â­as para que el nÃ¿Âºmero de filas
      --concuerde con el nÃ¿Âºmero de amparos que si se muestran
      --La libreria de LibertyReportes.jar necesita recibir todos los parÃ¿Â¡metros
      --con las mismas lineas, sino da error, para evitar eso creamos esta cadena vacÃ¿Â­a con intros
      v_tresult := v_tresult || ' ' || '\par ';
    ELSE
      v_tresult := v_tresult || v_tlinia || '\par ';
    END IF;
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_garantias_certif;
/*****************************************************************
GH
FUNCTION f_garantias_certif_glo
Devuelve todas las garantÃ¿Â­as de todos los certificados N
param IN psseguro  : codigo de seguro
param IN pcidioma  : codigo de idioma
return             : texto con las garantÃ¿Â­as
******************************************************************/
FUNCTION f_garantias_certif_glo(
    psseguro IN NUMBER,
    pcidioma IN NUMBER DEFAULT 1,
    pdummy   IN NUMBER DEFAULT 0,
    pnmovimi IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(2000);
    v_tlinia    VARCHAR2(200);
    v_tlinia1   VARCHAR2(200);
    v_tlinia2   VARCHAR2(200);
    v_porcentot NUMBER;
    v_porceninm NUMBER;
    v_porcencon NUMBER;
    v_norden garanpro.norden%TYPE;
    v_tpargar   VARCHAR2(200);
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
  BEGIN
    v_tablaseg  := 'seguros';
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    v_tconsulta := 'SELECT p.norden,REPLACE(pac_isqlfor_lcol.f_des_garpro(se.sseguro,s.nriesgo,' || NVL(pcidioma, 2) || ',p.cgarant,se.sproduc,''POL''), CHR(39), CHR(39) || CHR(39)) a' || ',NVL(sum((select sum(crespue) from pregungaranseg where sseguro in (select sseguro from seguros where  npoliza = se.npoliza and ncertif !=0 and cpregun in (5851,5852)) and cgarant = s.cgarant)),0) porcentot' || ',NVL(sum((select sum(crespue) from pregungaranseg where sseguro in (select sseguro from seguros where  npoliza = se.npoliza and ncertif !=0 and cpregun in (5851)) and cgarant = s.cgarant)),0) porceninm' || ',NVL(sum((select sum(crespue) from pregungaranseg where sseguro in (select sseguro from seguros where  npoliza = se.npoliza and ncertif !=0 and cpregun in (5852)) and cgarant = s.cgarant)),0) porcencon';
    v_tconsulta := v_tconsulta || ' FROM garanpro p, ';
    v_tconsulta := v_tconsulta || 'garanseg s, seguros se';
    v_tconsulta := v_tconsulta || ' WHERE ';
    v_tconsulta := v_tconsulta || ' p.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    --v_tconsulta := v_tconsulta || ' AND se.ncertif <> 0';
    v_tconsulta := v_tconsulta || ' AND se.csituac in (0,7,5,2)';
    v_tconsulta := v_tconsulta || ' AND p.CACTIVI = ' || v_actividad;
    --v_tconsulta := v_tconsulta || ' AND s.ffinefe IS NULL';
    v_tconsulta := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro || ')';
    /* Bug 33488/196141 - 20/01/2015
    IF (pnmovimi IS NOT NULL) THEN
    v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
    ELSE
    v_tconsulta := v_tconsulta || ')';
    END IF;
    v_tconsulta := v_tconsulta || ' AND s.sseguro IN (SELECT sseguro FROM seguros';
    v_tconsulta := v_tconsulta
    || ' WHERE npoliza = (SELECT npoliza FROM seguros WHERE sseguro=  '
    || psseguro || '))';*/
    v_tconsulta := v_tconsulta || ' AND se.sseguro =' || psseguro;
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', p.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' GROUP BY REPLACE(pac_isqlfor_lcol.f_des_garpro(se.sseguro, s.nriesgo,' || NVL(pcidioma, 2) || ',p.cgarant, se.sproduc,''POL''), CHR(39), CHR(39) || CHR(39)),p.norden';
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor
    INTO v_norden,
      v_tlinia,
      v_porcentot,
      v_porceninm,
      v_porcencon;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF pdummy = 1 THEN
      --Necesitamos llenar con "intros" columnas vacÃ¿Â­as para que el nÃ¿Âºmero de filas
      --concuerde con el nÃ¿Âºmero de amparos que si se muestran
      --La libreria de LibertyReportes.jar necesita recibir todos los parÃ¿Â¡metros
      --con las mismas lineas, sino da error, para evitar eso creamos esta cadena vacÃ¿Â­a con intros
      v_tresult := v_tresult || ' ' || '\par ';
    ELSE
      v_tresult       := v_tresult || v_tlinia || '\par ';
      IF v_porcentot   > 0 THEN
        IF v_porceninm > 0 THEN
          BEGIN
            SELECT REPLACE(tpregun, '%', 'Valor')
            INTO v_tlinia1
            FROM preguntas
            WHERE cidioma = 8
            AND cpregun   = 5851;
          EXCEPTION
          WHEN NO_DATA_FOUND THEN
            v_tlinia1 := '';
          END;
          v_tresult := v_tresult || '\tab \tab \tab ' || v_tlinia1 || '\par ';
        END IF;
        IF v_porcencon > 0 THEN
          BEGIN
            SELECT REPLACE(tpregun, '%', 'Valor')
            INTO v_tlinia2
            FROM preguntas
            WHERE cidioma = 8
            AND cpregun   = 5852;
          EXCEPTION
          WHEN NO_DATA_FOUND THEN
            v_tlinia2 := '';
          END;
          v_tresult := v_tresult || '\tab \tab \tab ' || v_tlinia2 || '\par ';
        END IF;
      END IF;
    END IF;
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_garantias_certif_glo;
