FUNCTION f_importes_certif_gar
Devuelve los capitales de todos los certificados diferentes a 0 de una garantia concreta
param IN psseguro  : codigo de seguro padre
param IN pcampo    : 1 Valor Asegurado / 2 Prima amparo
param IN pcgarant  : cÃ¿Â³digo garantia
return             : texto importes
******************************************************************/
FUNCTION f_importes_certif_gar(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pcgarant IN NUMBER,
    pnmovimi IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(4000);
    v1          NUMBER;
    v2          NUMBER;
    v_tlinia    VARCHAR2(50);
    v_tpargar   VARCHAR2(200);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot garanseg.ipritot%TYPE;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    vfmovdia    DATE;
  BEGIN
    IF pnmovimi IS NOT NULL THEN
      SELECT MAX(femisio)
      INTO vfmovdia
      FROM movseguro m
      WHERE m.sseguro = psseguro
      AND m.nmovimi   = pnmovimi;
  ELSE
    SELECT MAX(femisio)
    INTO vfmovdia
    FROM movseguro m
    WHERE m.sseguro = psseguro
    AND m.nmovimi   =
      (SELECT MAX(nmovimi) FROM movseguro WHERE sseguro = psseguro
      );
  END IF;
  v_actividad := 'se.cactivi';
  v_tconsulta := 'SELECT s.cgarant, p.norden, sum(decode(s.cgarant,48,se.cforpag,1)*icaptot) a,sum(ipritot)';
  v_tconsulta := v_tconsulta || ' FROM garanpro p, productos pp, ';
  v_tconsulta := v_tconsulta || ' garanseg s, seguros se';
  v_tconsulta := v_tconsulta || ' WHERE p.cgarant = s.cgarant';
  v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
  v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
  v_tconsulta := v_tconsulta || ' AND p.sproduc = pp.sproduc';
  v_tconsulta := v_tconsulta || ' AND se.csituac in (0,7,5,2)';
  v_tconsulta := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
  v_tconsulta := v_tconsulta || ' AND s.sseguro IN (SELECT sseguro FROM seguros';
  v_tconsulta := v_tconsulta || ' WHERE npoliza = (SELECT npoliza FROM seguros WHERE sseguro=  ' || psseguro || ')and ncertif <> 0)';
  --v_tconsulta := v_tconsulta || ' AND s.ffinefe IS NULL';
  --
  --INI BUG 0028625 - 24/10/2016 - CASL - Se mpodifica la consulta para obtener correctamente el valor asegurado
  --
  v_tconsulta   := v_tconsulta || ' and s.nmovimi IN (SELECT DISTINCT nmovimi FROM GARANSEG ga WHERE sseguro IN ( SELECT sseguro
FROM seguros
WHERE npoliza = (SELECT npoliza
FROM seguros
WHERE sseguro = ' || psseguro || ') AND ncertif <> 0 )';
  --INI AITSSD-21992 01/10/2024
  --v_tconsulta   := v_tconsulta || '  and ga.nmovimi IN (SELECT MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.SSEGURO = GA.SSEGURO AND MV.CMOVSEG!=3 AND MV.NMOVIMI IN(select DISTINCT nmovimi_cert from detmovsegurocol WHERE sseguro_0 = ' || psseguro; -- || ' and sseguro_cert =ga.sseguro ';
  v_tconsulta   := v_tconsulta || '  and (ga.sseguro, ga.nmovimi) IN (SELECT mv.sseguro, mv.nmovimi FROM MOVSEGURO MV WHERE MV.SSEGURO';
  v_tconsulta   := v_tconsulta || '   IN (SELECT sseguro FROM seguros WHERE npoliza = (SELECT npoliza FROM seguros WHERE sseguro =  ' || psseguro || ' ) AND ncertif <> 0)';
  v_tconsulta   := v_tconsulta || '  AND MV.CMOVSEG!=3';
  v_tconsulta   := v_tconsulta || '   AND MV.NMOVIMI IN(select DISTINCT nmovimi_cert from detmovsegurocol WHERE sseguro_0 = ' || psseguro;
  --FIN AITSSD-21992 01/10/2024
  IF (pnmovimi  IS NOT NULL) THEN
    v_tconsulta := v_tconsulta || ' AND nmovimi_0 =' || pnmovimi || '))) ';
  ELSE
    v_tconsulta := v_tconsulta || ')))';
  END IF;
  --
  --FIN BUG 0028625 - 24/10/2016 - CASL
  --
  v_tconsulta := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM movseguro ';
  v_tconsulta := v_tconsulta || ' WHERE sseguro = s.sseguro and femisio <= to_date(''' || TO_CHAR(vfmovdia, 'ddmmyyyy hh24MISS') || ''',''ddmmyyyy hh24MISS''))';
  -- INI 0039502 - MAV 23/11/2017
  -- La consulta debe usar p.cgarant
  SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
    || sproduc
    || ', '
    || cactivi
    || ', p.cgarant, ''GARANT_IMP''), 0) = 1 )'
  INTO v_tpargar
  FROM
    (SELECT seg.sproduc,
      seg.cactivi
    FROM seguros seg
    WHERE seg.sseguro = psseguro
    );
  /*SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
  || sproduc
  || ', '
  || cactivi
  || ', s.cgarant, ''GARANT_IMP''), 0) = 1 )'
  INTO v_tpargar
  FROM
  (SELECT seg.sproduc,
  seg.cactivi
  FROM seguros seg
  WHERE seg.sseguro = psseguro
  );
  */
  -- FIN 0039502 - MAV 23/11/2017
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || 'GROUP BY s.cgarant,p.norden ORDER BY p.norden';
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v1, v2, v_icaptot, v_ipritot;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    v_tlinia   := pac_isqlfor_lcol.f_imporignomon(psseguro, v_icaptot);
    IF pcampo   = 2 THEN
      v_tlinia := pac_isqlfor_lcol.f_imporignomon(psseguro, v_ipritot);
    END IF;
    IF v1      <> pcgarant AND v_ipritot = 0 THEN
      v_tlinia := ' ';
    END IF;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_certif_gar;
/*****************************************************************
INI BUG 47494 MPC 08/03/2019 Se crea procedimiento Previos Cartera.
FUNCTION f_importes_certif_garcar
Devuelve los capitales de todos los certificados diferentes a 0 de una garantia concreta
param IN psseguro  : codigo de seguro padre
param IN pcampo    : 1 Valor Asegurado / 2 Prima amparo
param IN pcgarant  : cÃ³digo garantia
param IN psproces  : Numero de proceso lanzado del previo.
return             : texto importes
******************************************************************/
FUNCTION f_importes_certif_garcar(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pcgarant IN NUMBER,
    psproces IN NUMBER)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(4000);
    v1          NUMBER;
    v2          NUMBER;
    v_tlinia    VARCHAR2(50);
    v_tpargar   VARCHAR2(200);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot garanseg.ipritot%TYPE;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
  BEGIN
    --
    v_actividad := 'se.cactivi';
    v_tconsulta := 'SELECT s.cgarant, p.norden, sum(decode(s.cgarant,48,se.cforpag,1)*icaptot) a,sum(ipritot)';
    v_tconsulta := v_tconsulta || ' FROM garanpro p, productos pp, ';
    v_tconsulta := v_tconsulta || ' garancar s, seguros se';
    v_tconsulta := v_tconsulta || ' WHERE p.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND s.sproces = '||psproces;
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = pp.sproduc';
    v_tconsulta := v_tconsulta || ' AND se.csituac in (0,7,5,2)';
    v_tconsulta := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' AND s.sseguro IN (SELECT sseguro FROM seguros';
    v_tconsulta := v_tconsulta || ' WHERE npoliza = (SELECT npoliza FROM seguros WHERE sseguro=  ' || psseguro || ')and ncertif <> 0)';
    --
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', p.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  --
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || 'GROUP BY s.cgarant,p.norden ORDER BY p.norden';
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v1, v2, v_icaptot, v_ipritot;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    v_tlinia   := pac_isqlfor_lcol.f_imporignomon(psseguro, v_icaptot);
    IF pcampo   = 2 THEN
      v_tlinia := pac_isqlfor_lcol.f_imporignomon(psseguro, v_ipritot);
    END IF;
    IF v1      <> pcgarant AND v_ipritot = 0 THEN
      v_tlinia := ' ';
    END IF;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_certif_garcar;
--FIN BUG 47494 MPC 08/03/2019 Se crea procedimiento Previos Cartera.
/*****************************************************************
Bug 24572-XVM-30/11/2012
FUNCTION f_relasegurados
Devuelve los capitales de todos los certificados diferentes a 0
param IN psseguro  : codigo de seguro padre
return             :
******************************************************************/
FUNCTION f_tiporiesgo(
    pssegurocertif IN NUMBER,
    pnriesgo       IN NUMBER,
    pnmovimi       IN NUMBER)
  RETURN VARCHAR2
IS
  respue VARCHAR2(5);
BEGIN
  BEGIN
    SELECT NVL2(crespue, DECODE(crespue, 1, 'P', 'D'), 'P')
    INTO respue
    FROM pregunseg
    WHERE sseguro = pssegurocertif
    AND nriesgo   = pnriesgo
    AND cpregun   = 4796
    AND nmovimi  IN
      (SELECT MAX(nmovimi)
      FROM pregunseg
      WHERE sseguro = pssegurocertif
      AND nriesgo   = 2
      AND cpregun   = 4796
      AND nmovimi   < pnmovimi
      );
  EXCEPTION
  WHEN NO_DATA_FOUND THEN
    RETURN '';
  END;
  RETURN respue;
EXCEPTION
WHEN OTHERS THEN
  RETURN '';
END f_tiporiesgo;
FUNCTION f_planriesgo(
    psseguro       IN NUMBER,
    pssegurocertif IN NUMBER,
    pnmovimi       IN NUMBER)
  RETURN VARCHAR2
IS
  v_tnatrie riesgos.tnatrie%TYPE;
BEGIN
  SELECT nriesgo --tnatrie
  INTO v_tnatrie
  FROM riesgos
  WHERE sseguro = psseguro --PÃ¿Â³liza cert 0
  AND nriesgo   =
    (SELECT crespue
    FROM pregunpolseg
    WHERE sseguro = pssegurocertif --PÃ¿Â³liza cert X
    AND cpregun   = 4089
    AND nmovimi   = pnmovimi
    );
  RETURN v_tnatrie;
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_planriesgo;
/*****************************************************************
Bug 24572-XVM-30/11/2012
FUNCTION f_aseincluidos
Devuelve los planes del certificado que se le pase
param IN psseguro : codigo seguro padre
param IN pctipo   : Tipo de asegurado: 1.-Incluidos / 2.-Excluidos / 3.-Modificados
param IN pcampo   : Campo:
1.-Num riesgo 2.-Id asegurado 3.-Nombre aseg. 4.-des garantÃ¿Â­a 5.-Valor asegurado 6.-Prima
param IN pcidioma : Idioma
return            :
******************************************************************/
-- inicio 161.0 0046577 AAN 08/10/2018
FUNCTION f_relnovedades(
    psseguro IN NUMBER,
    pctipo   IN NUMBER,
    pcampo   IN NUMBER,
    pcidioma IN NUMBER,
    pcmodo   IN NUMBER DEFAULT 0)
  -- fin 161.0 0046577 AAN 08/10/2018
  RETURN VARCHAR2
IS
  CURSOR c_inc
  IS
    SELECT s.ncertif ncertif,
      pac_isqlfor.f_dades_persona(r.sperson, 1) relidaseg,
      pac_isqlfor.f_dades_persona(r.sperson, 4)
      || ' '
      || pac_isqlfor.f_dades_persona(r.sperson, 5) relnomaseg,
      ff_desgarantia(g.cgarant, pcidioma) descgarant,
      -- inicio 0046577 AAN 08/10/2018
      DECODE(pcmodo,0,g.icapital,0) relvalaseg,
      DECODE(pcmodo,0,
      (SELECT SUM(gar.iprianu)
      FROM garanseg gar
      WHERE g.sseguro = gar.sseguro
      AND g.nriesgo   = gar.nriesgo
      AND g.nmovimi   = gar.nmovimi
      ),0) relvalpriaseg
      -- fin 0046577 AAN 08/10/201
    FROM seguros s,
      riesgos r,
      garanseg g,
      garanpro ga
    WHERE s.sseguro = psseguro
    AND r.sseguro   = s.sseguro
    AND pac_isqlfor.f_max_nmovimi(s.sseguro) BETWEEN r.nmovima AND NVL( r.nmovimb - 1, pac_isqlfor.f_max_nmovimi( s.sseguro))
    AND g.sseguro = s.sseguro
    AND g.nriesgo = r.nriesgo
    AND g.nmovimi =
      (SELECT MAX(gg.nmovimi) FROM garanseg gg WHERE gg.sseguro = s.sseguro
      )
    AND g.cgarant  = ga.cgarant
    AND ga.cmodali = s.cmodali
    AND ga.ccolect = s.ccolect
    AND ga.ctipseg = s.ctipseg
    AND ga.cactivi = s.cactivi
    AND ga.cramo   = s.cramo
    AND ga.cbasica = 1
    ORDER BY s.sseguro,
      r.nriesgo;
    CURSOR c_exc
    IS
      SELECT s.ncertif ncertif,
        pac_isqlfor.f_dades_persona(r.sperson, 1) relidaseg,
        pac_isqlfor.f_dades_persona(r.sperson, 4)
        || ' '
        || pac_isqlfor.f_dades_persona(r.sperson, 5) relnomaseg,
        ff_desgarantia(g.cgarant, pcidioma) descgarant,
        g.icapital relvalaseg,
        (SELECT SUM(gar.iprianu)
        FROM garanseg gar
        WHERE g.sseguro = gar.sseguro
        AND g.nriesgo   = gar.nriesgo
        AND g.nmovimi   = gar.nmovimi
        ) relvalpriaseg
    FROM seguros s,
      riesgos r,
      garanseg g,
      garanpro ga
    WHERE s.sseguro                          = psseguro
    AND r.sseguro                            = s.sseguro
    AND pac_isqlfor.f_max_nmovimi(s.sseguro) = r.nmovimb
    AND g.sseguro                            = s.sseguro
    AND g.nriesgo                            = r.nriesgo
    AND ((s.csituac                          = 0
    AND g.nmovimi                            = pac_isqlfor.f_max_nmovimi(s.sseguro))
    OR (s.csituac                            = 2
    AND g.nmovimi                            = pac_isqlfor.f_max_nmovimi(s.sseguro) - 1))
    AND g.cgarant                            = ga.cgarant
    AND ga.cmodali                           = s.cmodali
    AND ga.ccolect                           = s.ccolect
    AND ga.ctipseg                           = s.ctipseg
    AND ga.cactivi                           = s.cactivi
    AND ga.cramo                             = s.cramo
    AND ga.cbasica                           = 1
    ORDER BY s.sseguro,
      r.nriesgo;
    CURSOR c_mod
    IS
      SELECT s.ncertif ncertif,
        pac_isqlfor.f_dades_persona(r.sperson, 1) relidaseg,
        pac_isqlfor.f_dades_persona(r.sperson, 4)
        || ' '
        || pac_isqlfor.f_dades_persona(r.sperson, 5) relnomaseg,
        ff_desgarantia(g.cgarant, pcidioma) descgarant,
        g.icapital relvalaseg,
        (SELECT SUM(gar.iprianu)
        FROM garanseg gar
        WHERE g.sseguro = gar.sseguro
        AND g.nriesgo   = gar.nriesgo
        AND g.nmovimi   = gar.nmovimi
        ) relvalpriaseg
    FROM seguros s,
      riesgos r,
      garanseg g,
      garanpro ga
    WHERE s.sseguro = psseguro
    AND EXISTS
      (SELECT 1
      FROM detmovseguro dm,
        movseguro mv
      WHERE dm.sseguro = s.sseguro
      AND dm.nmovimi   = g.nmovimi
      AND dm.nriesgo   = r.nriesgo
      AND mv.sseguro   = dm.sseguro
      AND mv.nmovimi   = dm.nmovimi
      AND mv.cmotmov  != 100
      )
    AND s.sseguro  = r.sseguro
    AND g.sseguro  = s.sseguro
    AND g.nriesgo  = r.nriesgo
    AND g.nmovimi  = pac_isqlfor.f_max_nmovimi(s.sseguro)
    AND g.cgarant  = ga.cgarant
    AND ga.cmodali = s.cmodali
    AND ga.ccolect = s.ccolect
    AND ga.ctipseg = s.ctipseg
    AND ga.cactivi = s.cactivi
    AND ga.cramo   = s.cramo
    AND ga.cbasica = 1
    ORDER BY s.sseguro,
      r.nriesgo;
    v_tresult VARCHAR2(4000) := '';
  BEGIN
    IF pctipo = 1 THEN
      FOR i IN c_inc
      LOOP
        IF pcampo    = 1 THEN
          v_tresult := v_tresult || i.ncertif || ' \par ';
        ELSIF pcampo = 2 THEN
          v_tresult := v_tresult || i.relidaseg || ' \par ';
        ELSIF pcampo = 3 THEN
          v_tresult := v_tresult || i.relnomaseg || ' \par ';
        ELSIF pcampo = 4 THEN
          v_tresult := v_tresult || i.descgarant || ' \par ';
        ELSIF pcampo = 5 THEN
          v_tresult := v_tresult || pac_isqlfor_lcol.f_imporignomon(psseguro, i.relvalaseg) || ' \par ';
        ELSIF pcampo = 6 THEN
          v_tresult := v_tresult || pac_isqlfor_lcol.f_imporignomon(psseguro, i.relvalpriaseg) || ' \par ';
        END IF;
      END LOOP;
    ELSIF pctipo = 2 THEN
      FOR i IN c_exc
      LOOP
        IF pcampo    = 1 THEN
          v_tresult := v_tresult || i.ncertif || ' \par ';
        ELSIF pcampo = 2 THEN
          v_tresult := v_tresult || i.relidaseg || ' \par ';
        ELSIF pcampo = 3 THEN
          v_tresult := v_tresult || i.relnomaseg || ' \par ';
        ELSIF pcampo = 4 THEN
          v_tresult := v_tresult || i.descgarant || ' \par ';
        ELSIF pcampo = 5 THEN
          v_tresult := v_tresult || pac_isqlfor_lcol.f_imporignomon(psseguro, i.relvalaseg) || ' \par ';
        ELSIF pcampo = 6 THEN
          v_tresult := v_tresult || pac_isqlfor_lcol.f_imporignomon(psseguro, i.relvalpriaseg) || ' \par ';
        END IF;
      END LOOP;
    ELSIF pctipo = 3 THEN
      FOR i IN c_mod
      LOOP
        IF pcampo    = 1 THEN
          v_tresult := v_tresult || i.ncertif || ' \par ';
        ELSIF pcampo = 2 THEN
          v_tresult := v_tresult || i.relidaseg || ' \par ';
        ELSIF pcampo = 3 THEN
          v_tresult := v_tresult || i.relnomaseg || ' \par ';
        ELSIF pcampo = 4 THEN
          v_tresult := v_tresult || i.descgarant || ' \par ';
        ELSIF pcampo = 5 THEN
          v_tresult := v_tresult || pac_isqlfor_lcol.f_imporignomon(psseguro, i.relvalaseg) || ' \par ';
        ELSIF pcampo = 6 THEN
          v_tresult := v_tresult || pac_isqlfor_lcol.f_imporignomon(psseguro, i.relvalpriaseg) || ' \par ';
        END IF;
      END LOOP;
    END IF;
    RETURN (f_jrep_trad(v_tresult));
  EXCEPTION
  WHEN OTHERS THEN
    RETURN '';
  END f_relnovedades;
  /*****************************************************************
  Tipo de coaseguro: (ctipcoa)
  - si = 8=>>Cedido
  - si <>8 Aceptado
  /*******************************************************************/
FUNCTION f_coaseguro(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    ptablas  IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL)--BUG 0040069 - 29/01/2018 - CASL - Se aÃ±ade parametro
  RETURN VARCHAR2
IS
  v_tresult VARCHAR2(4000);
  vcoaseg seguros.ccompani%TYPE;
  vtcoaseg companias.tcompani%TYPE;
  vpcoaseg    VARCHAR2(4);
  vtipocoaseg VARCHAR2(2);
  vntipocoa   NUMBER;
  -- Bug: 0028455/ 0155064 - JSV - 07/10/2013
BEGIN
  IF ptablas = 'POL' THEN
    SELECT ctipcoa
    INTO vntipocoa
    FROM seguros
    WHERE sseguro = psseguro;
    FOR i IN
    (SELECT DECODE(s.ccompani, 1, 2, 1) coaseg,
      tcompani tcoaseg,
      ploccoa
      || '%' pcoaseg,
      DECODE(vntipocoa, 1, 'C', 2, 'C', 'A') tipocoaseg
    FROM coacuadro cc,
      companias c,
      seguros s
    WHERE s.sseguro = psseguro
    AND cc.sseguro  = s.sseguro
    AND s.ccompani  = c.ccompani
    AND cc.ncuacoa  = NVL(pnmovimi,
      (SELECT MAX(ncuacoa)
      FROM coacedido
      WHERE sseguro = psseguro--BUG 0040069 - 29/01/2018 - CASL - filtra por el movimiento
      ))
    UNION
    SELECT ccompan coaseg,
      tcompani tcoaseg,
      pcescoa
      || '%' pcoaseg,
      DECODE(vntipocoa, 1, 'A', 2, 'A', 'C') tipocoaseg
    FROM coacedido cc,
      companias c
    WHERE cc.sseguro = psseguro
    AND cc.ccompan   = c.ccompani
    AND cc.ncuacoa   = NVL(pnmovimi,
      (SELECT MAX(ncuacoa)
      FROM coacedido
      WHERE sseguro = psseguro--BUG 0040069 - 29/01/2018 - CASL - filtra por el movimiento
      ))
    )
    LOOP
      IF pcampo    = 1 THEN
        v_tresult := v_tresult || i.coaseg || ' \par ';
      ELSIF pcampo = 2 THEN
        v_tresult := v_tresult || i.tcoaseg || ' \par ';
      ELSIF pcampo = 3 THEN
        v_tresult := v_tresult || i.pcoaseg || ' \par ';
      ELSIF pcampo = 4 THEN
        v_tresult := v_tresult || i.tipocoaseg || ' \par ';
      END IF;
    END LOOP;
    --Si no hay, por defecto...
    IF v_tresult IS NULL THEN
      SELECT DECODE(s.ccompani, 1, 2, 1) coaseg,
        tcompani tcoaseg,
        DECODE(s.ccompani, 325, '50%', '100%') pcoaseg,
        'A' tipocoaseg
      INTO vcoaseg,
        vtcoaseg,
        vpcoaseg,
        vtipocoaseg
      FROM companias c,
        seguros s
      WHERE s.sseguro = psseguro
      AND NVL(s.ccompani,0)  = c.ccompani;--CPEMEU-232 GZG 19/01/2026
      IF pcampo       = 1 THEN
        v_tresult    := vcoaseg;
      ELSIF pcampo    = 2 THEN
        v_tresult    := vtcoaseg;
      ELSIF pcampo    = 3 THEN
        v_tresult    := vpcoaseg;
      ELSIF pcampo    = 4 THEN
        v_tresult    := vtipocoaseg;
      END IF;
    END IF;
  ELSE
    SELECT ctipcoa
    INTO vntipocoa
    FROM estseguros
    WHERE sseguro = psseguro;
    FOR i IN
    (SELECT DECODE(s.ccompani, 1, 2, 1) coaseg,
      tcompani tcoaseg,
      ploccoa
      || '%' pcoaseg,
      DECODE(vntipocoa, 1, 'C', 2, 'C', 'A') tipocoaseg
    FROM coacuadro cc,
      companias c,
      estseguros s
    WHERE s.sseguro = psseguro
    AND cc.sseguro  = s.sseguro
    AND s.ccompani  = c.ccompani
    AND cc.ncuacoa  = NVL(pnmovimi,
      (SELECT MAX(ncuacoa)
      FROM coacedido
      WHERE sseguro = psseguro--BUG 0040069 - 29/01/2018 - CASL - filtra por el movimiento
      ))
    UNION
    SELECT ccompan coaseg,
      tcompani tcoaseg,
      pcescoa
      || '%' pcoaseg,
      DECODE(vntipocoa, 1, 'A', 2, 'A', 'C') tipocoaseg
    FROM coacedido cc,
      companias c
    WHERE cc.sseguro = psseguro
    AND cc.ccompan   = c.ccompani
    AND cc.ncuacoa   = NVL(pnmovimi,
      (SELECT MAX(ncuacoa)
      FROM coacedido
      WHERE sseguro = psseguro--BUG 0040069 - 29/01/2018 - CASL - filtra por el movimiento
      ))
    )
    LOOP
      IF pcampo    = 1 THEN
        v_tresult := v_tresult || i.coaseg || ' \par ';
      ELSIF pcampo = 2 THEN
        v_tresult := v_tresult || i.tcoaseg || ' \par ';
      ELSIF pcampo = 3 THEN
        v_tresult := v_tresult || i.pcoaseg || ' \par ';
      ELSIF pcampo = 4 THEN
        v_tresult := v_tresult || i.tipocoaseg || ' \par ';
      END IF;
    END LOOP;
    --Si no hay, por defecto...
    IF v_tresult IS NULL THEN
      SELECT DECODE(s.ccompani, 1, 2, 1) coaseg,
        tcompani tcoaseg,
        DECODE(s.ccompani, 325, '50%', '100%') pcoaseg,
        'A' tipocoaseg
      INTO vcoaseg,
        vtcoaseg,
        vpcoaseg,
        vtipocoaseg
      FROM companias c,
        estseguros s
      WHERE s.sseguro = psseguro
      AND s.ccompani  = c.ccompani;
      IF pcampo       = 1 THEN
        v_tresult    := vcoaseg;
      ELSIF pcampo    = 2 THEN
        v_tresult    := vtcoaseg;
      ELSIF pcampo    = 3 THEN
        v_tresult    := vpcoaseg;
      ELSIF pcampo    = 4 THEN
        v_tresult    := vtipocoaseg;
      END IF;
    END IF;
  END IF;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN '';
END f_coaseguro;
FUNCTION f_extraprimavg(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER,
    pctipo   IN NUMBER)
  RETURN VARCHAR2
IS
  v_tresult VARCHAR2(4000);
  v_num     NUMBER;
  v_temp    NUMBER;
  --INI BUG 0055507 GZG 12/11/2019
  v_sproduc NUMBER;
  v_cforpag NUMBER;
  --FIN BUG 0055507 GZG 12/11/2019
BEGIN
  SELECT ncertif
  INTO v_num
  FROM seguros
  WHERE sseguro = psseguro;
  --
  --INI BUG 0028151 - 13/03/2017 - CASL - Si es certifido cero y el movimiento es 1 no se devuelve extraprima
  --
  IF v_num = 0 AND pnmovimi = 1 THEN
    --
    v_tresult := pac_isqlfor_lcol.f_imporignomon(psseguro, NULL, 0);
    RETURN v_tresult;
    --
  END IF;
  --
  --FIN BUG 0028151 - 13/03/2017 - CASL
  --
  IF v_num = 0 THEN --Si es certf 0
    v_num := 0;
    FOR i IN
    (SELECT sseguro,
      pac_isqlfor.f_max_nmovimi(sseguro) nmovimi
    FROM seguros
    WHERE ncertif != 0
    AND csituac    = 0
    AND npoliza    =
      (SELECT npoliza FROM seguros WHERE sseguro = psseguro
      )
    )
    LOOP
      SELECT SUM((g.icapital / 1000) * pg.crespue)
      INTO v_temp
      FROM garanseg g,
        pregungaranseg pg
      WHERE g.sseguro = i.sseguro
      AND g.ffinefe  IS NULL
      AND pg.cpregun IN (DECODE(pctipo, 1, 4021, 3, 4021, NULL), --Salud
        DECODE(pctipo, 2, 4030, 3, 4030, NULL))                  --OcupaciÃ¿Â³n
      AND pg.sseguro = g.sseguro
      AND pg.nmovimi = i.nmovimi
      AND g.nmovimi  = pg.nmovimi
      AND g.cgarant  = pg.cgarant;
      v_num         := v_num + v_temp;
    END LOOP;
  ELSE
    SELECT SUM((g.icapital / 1000) * pg.crespue)
    INTO v_num
    FROM garanseg g,
      pregungaranseg pg
    WHERE g.sseguro = psseguro
    AND g.ffinefe  IS NULL
    AND pg.cpregun IN (DECODE(pctipo, 1, 4021, 3, 4021, NULL), --Salud
      DECODE(pctipo, 2, 4030, 3, 4030, NULL))                  --OcupaciÃ¿Â³n
    AND pg.sseguro = g.sseguro
    AND pg.nmovimi = pnmovimi
    AND g.nmovimi  = pg.nmovimi
    AND g.cgarant  = pg.cgarant;
  END IF;
  --INI BUG 0055507 GZG 12/11/2019
  SELECT sproduc INTO v_sproduc FROM seguros WHERE sseguro = psseguro;
  IF NVL(pac_parametros.f_parproducto_n(v_sproduc, 'TIPO_PAGO_EXTRAP'), 0) = 1 THEN
  SELECT cforpag INTO v_cforpag FROM seguros WHERE sseguro = psseguro;
  v_num := v_num/v_cforpag;
  END IF;
  --FIN BUG 0055507 GZG 12/11/2019
  v_tresult := pac_isqlfor_lcol.f_imporignomon(psseguro, v_num, 0);
  RETURN v_tresult;
EXCEPTION
WHEN OTHERS THEN
  RETURN '';
END f_extraprimavg;
FUNCTION f_textofinal(
    --INI AITSSD-14129 GZG 23/11/2023 se adicionan 3 campos nuevos
    pnmovimi IN NUMBER,
    pcagente IN NUMBER DEFAULT NULL,
    psucursal IN NUMBER DEFAULT NULL,
    psproduc IN NUMBER DEFAULT NULL)
  RETURN NUMBER
IS
  vret NUMBER;
  vnum_err NUMBER;
  v_cagente NUMBER;
  v_sucursal NUMBER;
  --FIN AITSSD-14129 GZG 23/11/2023
BEGIN
  SELECT valor
  INTO vret
  FROM sgt_det_tramos
  WHERE tramo =
    (SELECT detalle_tramo
    FROM sgt_vigencias_tramos
    WHERE tramo      = 250001
    AND fecha_efecto =
      (SELECT MAX(fecha_efecto)
      FROM sgt_vigencias_tramos
      WHERE tramo       = 250001
      AND fecha_efecto <= f_sysdate
      )
    )
  AND pnmovimi BETWEEN hasta AND desde;
  --INI AITSSD-14129 GZG 23/11/2023 se adicionan 3 campos nuevos
  IF vret = 1 THEN
     vnum_err := f_parproductos(psproduc, 'CREDIORBE', v_cagente);
     vnum_err := f_parproductos(psproduc, 'S_CREDIORBE', v_sucursal);
    IF v_cagente = pcagente AND v_sucursal = psucursal THEN
        vret := 4;
    END IF;
  END IF;
  --FIN AITSSD-14129 GZG 23/11/2023
  RETURN vret;
EXCEPTION
WHEN OTHERS THEN
  RETURN 1;
END f_textofinal;
/*****************************************************************
FUNCTION f_importes_franquicias
param IN psseguro  : codigo de seguro
param IN pcampo  :  campo a devolver 1: porcentaje, 2:valor,campo a devolver 10: porcentaje con el '%', campo a devolver 2:valor ,campo a devolver 20 :valor con el literal 'smmlv'
param IN pnriesgo  : n?mero de riesgo
param IN pcidioma  : idioma
param IN pmodo     : modo EST/POL
return             : texto con los importes de franquicia.
******************************************************************/
FUNCTION f_importes_franquicias(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    /*inicio 08/11/2018   AAN  Bug 0047560:*/
    pnmovimi IN NUMBER DEFAULT NULL)
  /*fin 08/11/2018   AAN  Bug 0047560:*/
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(4000);
    v_tlinia    VARCHAR2(50);
    v_tpargar   VARCHAR2(300); -- BUG 0035431/0017560 -- ECP -- 13/04/2015 Se cambia VARCHAR2(200);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot VARCHAR2(200);
    v_ctipcap garanpro.ctipcap%TYPE;
    v_cimpres garanpro.cimpres%TYPE;
    v_npargar   NUMBER := 0;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_porcded   NUMBER;
    v_smmlv     NUMBER;
    v_sseguro garanseg.sseguro%TYPE;
    v_cgarant garanseg.cgarant%TYPE;
    v_nmovimi garanseg.nmovimi%TYPE;
    v_norden garanpro.norden%TYPE;
    v_nriesgo garanseg.nriesgo%TYPE;
    v_csituac VARCHAR2(100);
    v_tnivel  VARCHAR2(200);
    vsproduc    NUMBER; -- 236. 0055909: PDF Cobertura Autos. VIDRIOS, AU AL
    vformulaselecc NUMBER;   --BUG AITSSD8723 - JAE - BUG AITSSD8723 - JAE - Ajustes Autos Individual 2023 Parametrización deducibles - 13/07/2023
-- Inicio 253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
    v_cimpmin NUMBER;
-- Fin  253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
    v_nmovimi2    NUMBER; --AITSSD_707 GZG 25/08/2022
  BEGIN
    --INI GZG AITSSD-3915 15/07/2025
    BEGIN
        SELECT sproduc INTO vsproduc FROM seguros WHERE sseguro = psseguro;
    EXCEPTION
    WHEN OTHERS THEN
        SELECT sproduc INTO vsproduc FROM ESTseguros WHERE sseguro = psseguro;
    END;
    --FIN GZG AITSSD-3915 15/07/2025
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := 'SELECT s.sseguro, p.cgarant, s.nmovimi, p.norden, s.nriesgo';
    ELSE
      v_tconsulta := 'SELECT s.sseguro, p.cgarant, s.nmovimi, p.norden, s.nriesgo';
    END IF;
    v_tconsulta         := v_tconsulta || ' FROM  garangen g, garanpro p, productos pp, ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' estgaranseg s, estseguros se';
      v_csituac         := '(0,7,5,2,4)';
    ELSE
      v_tconsulta                                 := v_tconsulta || ' garanseg s, seguros se';
      IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
        -- INI BUG 45008 GNRZ 19/07/2018  Se incluyen  estados posibles de pÃ³liza
        -- Inicio QT44626 Amantium 12/07/2018
        -- Se incluyen las pÃ³lizas vencidas
        --v_csituac                                 := '(0,7,5,2,4)'; --BUG 0028151 - 01/03/2017 - CASL - se aÃ¿Â±anden las propuestas
        --v_csituac := '(0,7,5,2,4,3)';
        v_csituac := '(0,7,5,2,4,3,17,1,7,8,9,10,16)';
        -- Fin QT44626 Amantium 12/07/2018
        -- FIN BUG 45008 GNRZ 19/07/2018  Se incluyen  estados posibles de pÃ³liza
      ELSE
        v_csituac := '(0,7,5,2,4)';
      END IF;
    END IF;
    v_tconsulta := v_tconsulta || ' WHERE g.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = pp.sproduc';
    v_tconsulta := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
    --v_tconsulta := v_tconsulta || ' AND s.ffinefe IS NULL';
    v_tconsulta         := v_tconsulta || ' AND se.csituac in ' || v_csituac;
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' AND s.cobliga = 1';
      v_tconsulta       := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM ESTGARANSEG WHERE sseguro =' || psseguro;
      /*IF (pnmovimi IS NOT NULL) THEN
      v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE*/
      v_tconsulta := v_tconsulta || ')';
      --END IF;
    --INI GZG AITSSD-3915 15/07/2025
      IF NVL(pac_parametros.f_parproducto_n(vsproduc, 'GARANT_IMP0'), 0) = 1 THEN
          SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
            || sproduc
            || ', '
            || cactivi
            || ', g.cgarant, ''GARANT_IMP2''), 0) = 1 )'
          INTO v_tpargar
          FROM
            (SELECT seg.sproduc,
              seg.cactivi
            FROM estseguros seg
            WHERE seg.sseguro = psseguro
            );
      ELSE
          -- INI 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo  -- INI BUG 0035431/0017560 -- ECP -- 13/04/2015
          SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
            || sproduc
            || ', '
            || cactivi
            || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
            --|| ', g.cgarant, ''GARANT_IMP''), 0) = 1 OR exists (select 1 from garanseg where sseguro = s.sseguro and nmovimi = s.nmovimi and cgarant = 777 and iprianu <> 0))'
            -- FIN 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo    -- FIN BUG 0035431/0017560 -- ECP -- 13/04/2015
          INTO v_tpargar
          FROM
            (SELECT seg.sproduc,
              seg.cactivi
            FROM estseguros seg
            WHERE seg.sseguro = psseguro
            );
      END IF;
    --FIN GZG AITSSD-3915 15/07/2025
  ELSE
    v_tconsulta := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro;
    -- inicio 08/11/2018   AAN  Bug 0047560:*/
    IF (pnmovimi  IS NOT NULL) THEN
      v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
    ELSE
      v_tconsulta := v_tconsulta || ')';
    END IF;
    -- fin 08/11/2018   AAN  Bug 0047560:*/
    --INI GZG AITSSD-3915 15/07/2025
      IF NVL(pac_parametros.f_parproducto_n(vsproduc, 'GARANT_IMP0'), 0) = 1 THEN
        SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
          || sproduc
          || ', '
          || cactivi
          || ', g.cgarant, ''GARANT_IMP2''), 0) = 1 )'
        INTO v_tpargar
        FROM
          (SELECT seg.sproduc,
            seg.cactivi
          FROM seguros seg
          WHERE seg.sseguro = psseguro
          );

      ELSE
        -- INI 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo  -- INI BUG 0035431/0017560 -- ECP -- 13/04/2015
        SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
          || sproduc
          || ', '
          || cactivi
          || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
          --|| ', g.cgarant, ''GARANT_IMP''), 0) = 1 OR exists (select 1 from garanseg where sseguro = s.sseguro and nmovimi = s.nmovimi and cgarant = 777 and iprianu <> 0))'
          -- FIN 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo  -- FIN BUG 0035431/0017560 -- ECP -- 13/04/2015
        INTO v_tpargar
        FROM
          (SELECT seg.sproduc,
            seg.cactivi
          FROM seguros seg
          WHERE seg.sseguro = psseguro
          );
      END IF;
    --FIN GZG AITSSD-3915 15/07/2025
  END IF;
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_sseguro, v_cgarant, v_nmovimi, v_norden, v_nriesgo;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    BEGIN
      IF NVL(pmodo, 'POL') = 'EST' THEN
       SELECT sproduc INTO vsproduc FROM estseguros WHERE sseguro = psseguro;  -- 236. 0055909: PDF Cobertura Autos. VIDRIOS, AU AL
        SELECT bd.impvalor1 porcded,
          bd.impmin smmlv,
-- Inicio 253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
          bd.cimpmin,
-- Fin  253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
          bn.tnivel,
          bd.formulaselecc  --BUG AITSSD8723 - JAE - BUG AITSSD8723 - JAE - Ajustes Autos Individual 2023 Parametrización deducibles - 13/07/2023
        INTO v_porcded,
          v_smmlv,
-- Inicio 253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
          v_cimpmin,
-- Fin 253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
          v_tnivel,
          vformulaselecc    --BUG AITSSD8723 - JAE - BUG AITSSD8723 - JAE - Ajustes Autos Individual 2023 Parametrización deducibles - 13/07/2023
        FROM bf_progarangrup bp,
          estbf_bonfranseg bf,
          bf_detnivel bd,
          estseguros s,
          bf_desnivel bn
        WHERE s.sseguro = v_sseguro
        AND bp.sproduc  = s.sproduc
        AND bp.cgarant  = v_cgarant
        AND bp.cempres  = s.cempres
        AND bp.cactivi  = s.cactivi
        AND bf.sseguro  = s.sseguro
        AND bf.cgrup    = bp.codgrup
        AND bf.ctipgrup = 2
        AND bf.nriesgo   = v_nriesgo --AITSSD-3915 GZG 17/07/2025
        AND bf.nmovimi  = DECODE(s.cramo, 700,
          (SELECT MAX(nmovimi)
          FROM estbf_bonfranseg
          WHERE sseguro = v_sseguro
          AND nriesgo   = v_nriesgo
            --INI BUG 0048921 11/01/2019 MPC Se adiciona condici?n.
          AND ( nmovimi <= pnmovimi
          OR pnmovimi   IS NULL)
            --FIN BUG 0048921 11/01/2019 MPC Se adiciona condici?n.
          ), DECODE(s.cramo, 701,
          (SELECT MAX(nmovimi)
          FROM estbf_bonfranseg
          WHERE sseguro = v_sseguro
          AND nriesgo   = v_nriesgo
            --INI BUG 0048921 11/01/2019 MPC Se adiciona condici?n.
          AND ( nmovimi <= pnmovimi
          OR pnmovimi   IS NULL)
            --FIN BUG 0048921 11/01/2019 MPC Se adiciona condici?n.
          ),
          (SELECT MAX(nmovimi)
          FROM estbf_bonfranseg bff
          WHERE bff.sseguro = v_sseguro
            --INI BUG 0048921 11/01/2019 MPC Se adiciona condici?n.
          AND ( nmovimi <= pnmovimi
          OR pnmovimi   IS NULL)
            --FIN BUG 0048921 11/01/2019 MPC Se adiciona condici?n.
          )))
        AND bd.cgrup    = bf.cgrup
        AND bd.csubgrup = bf.csubgrup
        AND bd.cversion = bf.cversion
        AND bd.cnivel   = bf.cnivel
        AND bd.cvalor1  = 1
        AND bd.cimpmin IN (2, 4, 55) -- Inicio 241. 0056616  -- Fin
        AND bd.cgrup    = bn.cgrup
        AND bd.csubgrup = bn.csubgrup
        AND bd.cversion = bn.cversion
        AND bd.cnivel   = bn.cnivel
        AND bn.cidioma  = 8;
      ELSE
        SELECT sproduc INTO vsproduc FROM seguros WHERE sseguro = psseguro; -- 236. 0055909: PDF Cobertura Autos. VIDRIOS, AU AL
       BEGIN--AITSSD_707 GZG 25/08/2022
        SELECT bd.impvalor1 porcded,
          bd.impmin smmlv,
-- Inicio 253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
          bd.cimpmin,
-- Fin  253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
          bn.tnivel,
          bd.formulaselecc  --BUG AITSSD8723 - JAE - BUG AITSSD8723 - JAE - Ajustes Autos Individual 2023 Parametrización deducibles - 13/07/2023
        INTO v_porcded,
          v_smmlv,
-- Inicio 253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
          v_cimpmin,
-- Fin  253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
          v_tnivel,
          vformulaselecc    --BUG AITSSD8723 - JAE - BUG AITSSD8723 - JAE - Ajustes Autos Individual 2023 Parametrización deducibles - 13/07/2023
        FROM bf_progarangrup bp,
          bf_bonfranseg bf,
          bf_detnivel bd,
          seguros s,
          bf_desnivel bn
        WHERE s.sseguro = v_sseguro
        AND bp.sproduc  = s.sproduc
        AND bp.cgarant  = v_cgarant
        AND bp.cempres  = s.cempres
        AND bp.cactivi  = s.cactivi
        AND bf.sseguro  = s.sseguro
        AND bf.cgrup    = bp.codgrup
        AND bf.ctipgrup = 2
        AND bf.nriesgo   = v_nriesgo --AITSSD-3915 GZG 17/07/2025
        AND bf.nmovimi  = DECODE(s.cramo, 700,
          (SELECT MAX(nmovimi)
          FROM bf_bonfranseg
          WHERE sseguro = v_sseguro
          AND nriesgo   = v_nriesgo
          AND cgrup = bf.cgrup--BUG AITSSD-8169 GZG 23/05/2023
            --INI BUG 0048921 11/01/2019 MPC Se adiciona condici?n.
          AND ( nmovimi <= pnmovimi
          OR pnmovimi   IS NULL)
            --FIN BUG 0048921 11/01/2019 MPC Se adiciona condici?n.
          ), DECODE(s.cramo, 701,
          (SELECT MAX(nmovimi)
          FROM bf_bonfranseg
          WHERE sseguro = v_sseguro
          AND nriesgo   = v_nriesgo
          AND cgrup = bf.cgrup--BUG AITSSD-8169 GZG 23/05/2023
            --INI BUG 0048921 11/01/2019 MPC Se adiciona condici?n.
          AND ( nmovimi <= pnmovimi
          OR pnmovimi   IS NULL)
            --FIN BUG 0048921 11/01/2019 MPC Se adiciona condici?n.
          ),
          (SELECT MAX(nmovimi)
          FROM bf_bonfranseg bff
          WHERE bff.sseguro = v_sseguro
          AND bff.cgrup = bf.cgrup--BUG AITSSD-8169 GZG 23/05/2023
            --INI BUG 0048921 11/01/2019 MPC Se adiciona condici?n.
          AND ( bff.nmovimi <= pnmovimi
          OR pnmovimi       IS NULL)
            --FIN BUG 0048921 11/01/2019 MPC Se adiciona condici?n.
          )))
        AND bd.cgrup    = bf.cgrup
        AND bd.csubgrup = bf.csubgrup
        AND bd.cversion = bf.cversion
        AND bd.cnivel   = bf.cnivel
        AND bd.cvalor1  = 1
        AND bd.cimpmin IN (2, 4, 55)  --  -- Inicio 241. 0056616  -- Fin
        AND bd.cgrup    = bn.cgrup
        AND bd.csubgrup = bn.csubgrup
        AND bd.cversion = bn.cversion
        AND bd.cnivel   = bn.cnivel
        AND bn.cidioma  = 8;
        --INI AITSSD_707 GZG 25/08/2022
       EXCEPTION WHEN too_many_rows THEN
       --
         SELECT MAX(nmovimi)
           INTO v_nmovimi2
           FROM movseguro
          WHERE sseguro = v_sseguro
            AND nmovimi <= pnmovimi
            AND cmotmov <> 404;
       --
         SELECT bd.impvalor1 porcded,
          bd.impmin smmlv,
          bd.cimpmin,
          bn.tnivel,
          bd.formulaselecc  --BUG AITSSD8723 - JAE - BUG AITSSD8723 - JAE - Ajustes Autos Individual 2023 Parametrización deducibles - 13/07/2023
        INTO v_porcded,
          v_smmlv,
          v_cimpmin,
          v_tnivel,
          vformulaselecc    --BUG AITSSD8723 - JAE - BUG AITSSD8723 - JAE - Ajustes Autos Individual 2023 Parametrización deducibles - 13/07/2023
        FROM bf_progarangrup bp,
          bf_bonfranseg bf,
          bf_detnivel bd,
          seguros s,
          bf_desnivel bn
        WHERE s.sseguro = v_sseguro
        AND bp.sproduc  = s.sproduc
        AND bp.cgarant  = v_cgarant
        AND bp.cempres  = s.cempres
        AND bp.cactivi  = s.cactivi
        AND bf.sseguro  = s.sseguro
        AND bf.cgrup    = bp.codgrup
        AND bf.ctipgrup = 2
        AND bf.nriesgo   = v_nriesgo --AITSSD-3915 GZG 17/07/2025
        AND bf.nmovimi  = DECODE(s.cramo, 700,
          (SELECT MAX(nmovimi)
          FROM bf_bonfranseg
          WHERE sseguro = v_sseguro
          AND nriesgo   = v_nriesgo
          AND ( nmovimi <= v_nmovimi2
          OR v_nmovimi2   IS NULL)
          ), DECODE(s.cramo, 701,
          (SELECT MAX(nmovimi)
          FROM bf_bonfranseg
          WHERE sseguro = v_sseguro
          AND nriesgo   = v_nriesgo
          AND ( nmovimi <= v_nmovimi2
          OR v_nmovimi2   IS NULL)
          ),
          (SELECT MAX(nmovimi)
          FROM bf_bonfranseg bff
          WHERE bff.sseguro = v_sseguro
          AND ( bff.nmovimi <= v_nmovimi2
          OR v_nmovimi2       IS NULL)
          )))
        AND bd.cgrup    = bf.cgrup
        AND bd.csubgrup = bf.csubgrup
        AND bd.cversion = bf.cversion
        AND bd.cnivel   = bf.cnivel
        AND bd.cvalor1  = 1
        AND bd.cimpmin IN (2, 4, 55)
        AND bd.cgrup    = bn.cgrup
        AND bd.csubgrup = bn.csubgrup
        AND bd.cversion = bn.cversion
        AND bd.cnivel   = bn.cnivel
        AND bn.cidioma  = 8;
       END;
       --FIN AITSSD_707 GZG 25/08/2022
      END IF;
       IF ( NVL ( f_parproductos_v ( vsproduc, 'IMP_DEDUCIBLE_PDF' ), 0 ) = 0) THEN  -- 236. 0055909: PDF Cobertura Autos. VIDRIOS, AU AL
      IF pcampo   = 1 AND v_cgarant NOT IN (756, 757) THEN
        v_tlinia := v_porcded;
        --etm
      ELSIF pcampo = 10 AND v_cgarant NOT IN (756, 757) THEN
        v_tlinia  := v_porcded || ' % ';
      ELSIF pcampo = 2 AND v_cgarant NOT IN (756, 757) THEN
           -- INI DV QT0061927 05/08/2020
           -- v_tlinia  := v_smmlv;

              if (instr (v_smmlv, ',') = 1 or instr (v_smmlv, '.')=1) then
               v_tlinia := '0'||v_smmlv;
              else
               v_tlinia  := v_smmlv;
              end if;
          -- FIN DV QT0061927 05/08/2020
      ELSIF pcampo = 20 AND v_cgarant NOT IN (756, 757) THEN
        v_tlinia  := v_smmlv || ' smmlv ';
      ELSIF pcampo = 3 THEN
        v_tlinia  := v_tnivel;
      ELSE
        v_tlinia := ' ';--BUG 0065003 GZG 30/11/2020
      END IF;
-- Inicio 236. 0055909: PDF Cobertura Autos. VIDRIOS, AU AL
       ELSE
         -- Inicio    253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
          IF pcampo   = 1 AND v_cimpmin = 2  AND v_cgarant in (9219,9220,758,759,760,761,762,771) THEN
            v_tlinia := v_tnivel;
          ELSIF pcampo   = 1 AND v_cimpmin <> 2 AND
                (v_cgarant NOT IN (756, 757, 9219) OR vformulaselecc = 104020)  --BUG AITSSD8723 - JAE - BUG AITSSD8723 - JAE - Ajustes Autos Individual 2023 ParametrizaciÃ³n deducibles - 13/07/2023 BUG AITSSD-13074 GZG 06/07/23 Se retira amparo 9220 para que se visualice en el pdf
          THEN
            v_tlinia :=  v_porcded || ' % ';
          ELSIF pcampo = 10 AND v_cimpmin <> 2 AND v_cgarant NOT IN (756, 757, 9219,9220) THEN
            v_tlinia  := v_porcded || ' % ';
          ELSIF pcampo = 2 AND v_cimpmin <> 2 AND
                (v_cgarant NOT IN (756, 757, 9219) OR vformulaselecc = 104020)  --BUG AITSSD8723 - JAE - BUG AITSSD8723 - JAE - Ajustes Autos Individual 2023 ParametrizaciÃ³n deducibles - 13/07/2023 BUG AITSSD-13074 GZG 06/07/23 Se retira amparo 9220 para que se visualice en el pdf
          THEN
          -- INI DV QT0061927 05/08/2020
           -- v_tlinia  := v_smmlv;

              if (instr (v_smmlv, ',') = 1 or instr (v_smmlv, '.')=1) then
               v_tlinia := '0'||v_smmlv;
              else
               v_tlinia  := v_smmlv;
              end if;
          -- FIN DV QT0061927 05/08/2020
          ELSIF pcampo = 20 AND v_cimpmin <> 2 AND v_cgarant NOT IN (756, 757, 9219,9220) THEN
          -- Fin  253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
            v_tlinia  := v_smmlv || ' smmlv ';
          ELSIF pcampo = 3 THEN
            v_tlinia  := v_tnivel;
          ELSE
            v_tlinia := ' ';--BUG 0065003 GZG 30/11/2020
          END IF;
       END IF;
-- Fin 236. 0055909: PDF Cobertura Autos. VIDRIOS, AU AL
    EXCEPTION
    WHEN OTHERS THEN
      v_tlinia := '  ';--BUG 0065003 GZG 30/11/2020
    END;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_franquicias;
-- INI GNRZ BUG 45071 03/08/2018  ajuste en los pdfs condicionado autos
FUNCTION f_importes_franquicias_nmovini(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovini IN NUMBER)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(4000);
    v_tlinia    VARCHAR2(50);
    v_tpargar   VARCHAR2(300);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot VARCHAR2(200);
    v_ctipcap garanpro.ctipcap%TYPE;
    v_cimpres garanpro.cimpres%TYPE;
    v_npargar   NUMBER := 0;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_porcded   NUMBER;
    v_smmlv     NUMBER;
    v_sseguro garanseg.sseguro%TYPE;
    v_cgarant garanseg.cgarant%TYPE;
    v_nmovimi garanseg.nmovimi%TYPE;
    v_norden garanpro.norden%TYPE;
    v_nriesgo garanseg.nriesgo%TYPE;
    v_csituac VARCHAR2(100);
    v_tnivel  VARCHAR2(200);
    vsproduc    NUMBER; -- 236. 0055909: PDF Cobertura Autos. VIDRIOS, AU AL
    vformulaselecc NUMBER;   --BUG AITSSD8723 - JAE - BUG AITSSD8723 - JAE - Ajustes Autos Individual 2023 Parametrización deducibles - 02/08/2023
-- Inicio 253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
    v_cimpmin NUMBER;
-- Fin  253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
  BEGIN
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := 'SELECT s.sseguro, p.cgarant, s.nmovimi, p.norden, s.nriesgo';
    ELSE
      v_tconsulta := 'SELECT s.sseguro, p.cgarant, s.nmovimi, p.norden, s.nriesgo';
    END IF;
    v_tconsulta         := v_tconsulta || ' FROM  garangen g, garanpro p, productos pp, ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' estgaranseg s, estseguros se';
      v_csituac         := '(0,7,5,2,4)';
    ELSE
      v_tconsulta                                 := v_tconsulta || ' garanseg s, seguros se';
      IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
        v_csituac                                 := '(0,7,5,2,4,3)';
      ELSE
        v_csituac := '(0,7,5,2,4)';
      END IF;
    END IF;
    v_tconsulta         := v_tconsulta || ' WHERE g.cgarant = s.cgarant';
    v_tconsulta         := v_tconsulta || ' AND p.cgarant = s.cgarant';
    v_tconsulta         := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta         := v_tconsulta || ' AND p.sproduc = pp.sproduc';
    v_tconsulta         := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
    v_tconsulta         := v_tconsulta || ' AND se.csituac in ' || v_csituac;
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' AND s.cobliga = 1';
      v_tconsulta       := v_tconsulta || ' and s.nmovimi = ' || pnmovini;
      v_tconsulta       := v_tconsulta || ')';
      SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
        || sproduc
        || ', '
        || cactivi
        || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
      INTO v_tpargar
      FROM
        (SELECT seg.sproduc,
          seg.cactivi
        FROM estseguros seg
        WHERE seg.sseguro = psseguro
        );
  ELSE
    v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM garanseg WHERE sseguro =' || psseguro;
    IF (pnmovini  IS NOT NULL) THEN
      v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovini || ') ';
    ELSE
      v_tconsulta := v_tconsulta || ')';
    END IF;
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  END IF;
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY s.norden';--AITSSD-2546 GZG 31/10/2022
  dbms_output.put_line('query:  '||v_tconsulta);
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_sseguro, v_cgarant, v_nmovimi, v_norden, v_nriesgo;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    BEGIN
      IF NVL(pmodo, 'POL') = 'EST' THEN
        SELECT sproduc INTO vsproduc FROM estseguros WHERE sseguro = psseguro;  -- 236. 0055909: PDF Cobertura Autos. VIDRIOS, AU AL
        SELECT bd.impvalor1 porcded,
          bd.impmin smmlv,
-- Inicio 253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
          bd.cimpmin,
-- Fin  253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
          bn.tnivel,
          bd.formulaselecc  --BUG AITSSD8723 - JAE - BUG AITSSD8723 - JAE - Ajustes Autos Individual 2023 Parametrización deducibles - 02/08/2023
        INTO v_porcded,
          v_smmlv,
-- Inicio 253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
          v_cimpmin,
-- Fin 253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
          v_tnivel,
          vformulaselecc    --BUG AITSSD8723 - JAE - BUG AITSSD8723 - JAE - Ajustes Autos Individual 2023 Parametrización deducibles - 02/08/2023
        FROM bf_progarangrup bp,
          estbf_bonfranseg bf,
          bf_detnivel bd,
          estseguros s,
          bf_desnivel bn
        WHERE s.sseguro = v_sseguro
        AND bp.sproduc  = s.sproduc
        AND bp.cgarant  = v_cgarant
        AND bp.cempres  = s.cempres
        AND bp.cactivi  = s.cactivi
        AND bf.sseguro  = s.sseguro
        AND bf.cgrup    = bp.codgrup
        AND bf.ctipgrup = 2
        AND bf.nmovimi  = DECODE(s.cramo, 700, pnmovini, DECODE(s.cramo, 701, pnmovini, pnmovini))
        AND bd.cgrup    = bf.cgrup
        AND bd.csubgrup = bf.csubgrup
        AND bd.cversion = bf.cversion
        AND bd.cnivel   = bf.cnivel
        AND bd.cvalor1  = 1
        AND bd.cimpmin IN (2, 4, 55) -- Inicio 235. 0055750: Cobertura Autos. VIDRIOS, AU AL --  Fin
        AND bd.cgrup    = bn.cgrup
        AND bd.csubgrup = bn.csubgrup
        AND bd.cversion = bn.cversion
        AND bd.cnivel   = bn.cnivel
        AND bn.cidioma  = 8;
      ELSE
        SELECT sproduc INTO vsproduc FROM seguros WHERE sseguro = psseguro; -- 236. 0055909: PDF Cobertura Autos. VIDRIOS, AU AL
        SELECT bd.impvalor1 porcded,
          bd.impmin smmlv,
-- Inicio 253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
          bd.cimpmin,
-- Fin  253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
          bn.tnivel,
          bd.formulaselecc  --BUG AITSSD8723 - JAE - BUG AITSSD8723 - JAE - Ajustes Autos Individual 2023 Parametrización deducibles - 04/08/2023
        INTO v_porcded,
          v_smmlv,
-- Inicio 253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
          v_cimpmin,
-- Fin  253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
          v_tnivel,
          vformulaselecc    --BUG AITSSD8723 - JAE - BUG AITSSD8723 - JAE - Ajustes Autos Individual 2023 Parametrización deducibles - 04/08/2023
        FROM bf_progarangrup bp,
          bf_bonfranseg bf,
          bf_detnivel bd,
          seguros s,
          bf_desnivel bn
        WHERE s.sseguro = v_sseguro
        AND bp.sproduc  = s.sproduc
        AND bp.cgarant  = v_cgarant
        AND bp.cempres  = s.cempres
        AND bp.cactivi  = s.cactivi
        AND bf.sseguro  = s.sseguro
        AND bf.cgrup    = bp.codgrup
        AND bf.ctipgrup = 2
        AND bf.nmovimi  = (SELECT MAX(bf2.nmovimi) FROM bf_bonfranseg bf2 WHERE bf2.sseguro = bf.sseguro and bf2.nmovimi <= pnmovini)-- BUG 0073255 GZG 03/02/2022 --DECODE(s.cramo, 700, pnmovini, DECODE(s.cramo, 701, pnmovini, pnmovini))
        AND bd.cgrup    = bf.cgrup
        AND bd.csubgrup = bf.csubgrup
        AND bd.cversion = bf.cversion
        AND bd.cnivel   = bf.cnivel
        AND bd.cvalor1  = 1
        AND bd.cimpmin IN (2, 4, 55) -- Inicio 235. 0055750: Cobertura Autos. VIDRIOS, AU AL Fin
        AND bd.cgrup    = bn.cgrup
        AND bd.csubgrup = bn.csubgrup
        AND bd.cversion = bn.cversion
        AND bd.cnivel   = bn.cnivel
        AND bn.cidioma  = 8;
      END IF;
       IF ( NVL ( f_parproductos_v ( vsproduc, 'IMP_DEDUCIBLE_PDF' ), 0 ) = 0) THEN  -- 236. 0055909: PDF Cobertura Autos. VIDRIOS, AU AL
          IF pcampo   = 1 AND v_cgarant NOT IN (756, 757) THEN
            v_tlinia := v_porcded;
            --etm
          ELSIF pcampo = 10 AND v_cgarant NOT IN (756, 757) THEN
            v_tlinia  := v_porcded || ' % ';
          ELSIF pcampo = 2 AND v_cgarant NOT IN (756, 757) THEN
           -- INI DV QT0061927 05/08/2020
           -- v_tlinia  := v_smmlv;

              if (instr (v_smmlv, ',') = 1 or instr (v_smmlv, '.')=1) then
               v_tlinia := '0'||v_smmlv;
              else
               v_tlinia  := v_smmlv;
              end if;
          -- FIN DV QT0061927 05/08/2020
          ELSIF pcampo = 20 AND v_cgarant NOT IN (756, 757) THEN
            v_tlinia  := v_smmlv || ' smmlv ';
          ELSIF pcampo = 3 THEN
            v_tlinia  := v_tnivel;
          ELSE
            v_tlinia := ' ';--BUG 0064412 GZG 24/11/2020
          END IF;
-- Inicio 236. 0055909: PDF Cobertura Autos. VIDRIOS, AU AL
       ELSE
         -- Inicio  253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
          IF pcampo   = 1 AND v_cimpmin = 2  AND v_cgarant in (9219,9220,758,759,760,761,762,771) THEN
            v_tlinia := v_tnivel;
          ELSIF pcampo   = 1 AND v_cimpmin <> 2 AND
                (v_cgarant NOT IN (756, 757, 9219) OR vformulaselecc = 104020)  --BUG AITSSD8723 - JAE - BUG AITSSD8723 - JAE - Ajustes Autos Individual 2023 ParametrizaciÃ³n deducibles - 02/08/2023 BUG AITSSD-13074 GZG 06/07/23 Se retira amparo 9220 para que se visualice en el pdf
          THEN
            v_tlinia :=  v_porcded || ' % ';
          ELSIF pcampo = 10 AND v_cimpmin <> 2 AND v_cgarant NOT IN (756, 757, 9219,9220) THEN
            v_tlinia  := v_porcded || ' % ';
          ELSIF pcampo = 2 AND v_cimpmin <> 2 AND
                (v_cgarant NOT IN (756, 757, 9219) OR vformulaselecc = 104020)  --BUG AITSSD8723 - JAE - BUG AITSSD8723 - JAE - Ajustes Autos Individual 2023 ParametrizaciÃ³n deducibles - 02/08/2023 BUG AITSSD-13074 GZG 06/07/23 Se retira amparo 9220 para que se visualice en el pdf
          THEN
           -- INI DV QT0061927 05/08/2020
           -- v_tlinia  := v_smmlv;

              if (instr (v_smmlv, ',') = 1 or instr (v_smmlv, '.')=1) then
               v_tlinia := '0'||v_smmlv;
              else
               v_tlinia  := v_smmlv;
              end if;
          -- FIN DV QT0061927 05/08/2020
          ELSIF pcampo = 20 AND v_cimpmin <> 2 AND v_cgarant NOT IN (756, 757, 9219,9220) THEN
          -- Fin  253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
            v_tlinia  := v_smmlv || ' smmlv ';
          ELSIF pcampo = 3 THEN
            v_tlinia  := v_tnivel;
          ELSE
            v_tlinia := ' ';--BUG 0064412 GZG 24/11/2020
          END IF;
       END IF;
-- Fin 236. 0055909: PDF Cobertura Autos. VIDRIOS, AU AL
    EXCEPTION
    WHEN OTHERS THEN
      v_tlinia := ' ';
    END;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  dbms_output.put_line('var:  '||v_tresult);
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_franquicias_nmovini;
-- FIN GNRZ BUG 45071 03/08/2018  condicionado -> se incluye nueva funcion en base al movimiento
/*****************************************************************
FUNCTION f_descuento
psseguro IN number      :
pnmovimi IN number      :
ptipodesc IN NUMBER     : 1.-tipo tÃ¿Â©cnico, 2.-tipo comercial
pmodo    IN varchar     : modo EST/POL
return                  : number
******************************************************************/
FUNCTION f_descuento(
    psseguro  IN NUMBER,
    pnmovimi  IN NUMBER,
    ptipodesc IN NUMBER,
    pmodo     IN VARCHAR2 DEFAULT 'POL')
  RETURN NUMBER
IS
  vsproduc NUMBER;
  vnum_err NUMBER;
  v_descuento bf_bonfranseg.impvalor1%TYPE;
  v_cgrup bf_bonfranseg.cgrup%TYPE;
BEGIN
  IF NVL(pmodo, 'POL') = 'EST' THEN
    SELECT sproduc INTO vsproduc FROM estseguros WHERE sseguro = psseguro;
  ELSE
    SELECT sproduc INTO vsproduc FROM seguros WHERE sseguro = psseguro;
  END IF;
  BEGIN
    v_descuento := 0;
    IF ptipodesc = 1 THEN
      --   v_cgrup := 603151;   -- JTS 28/05/2013 - A saco paco, a la que haya mÃ¿Â¡s habrÃ¿Â¡ que pensar como diferenciar un tipo de otro
      -- qt 18757
      vnum_err     := f_parproductos(vsproduc, 'GRUPBONUSMALUS', v_cgrup);
    ELSIF ptipodesc = 2 THEN
      --v_cgrup := 603152;   --A saco paco
      -- qt 18757
      vnum_err := f_parproductos(vsproduc, 'GRUPDTOCOM', v_cgrup);
    END IF;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      SELECT bd.impvalor1
      INTO v_descuento
      FROM estbf_bonfranseg bf,
        bf_detnivel bd
      WHERE bf.sseguro = psseguro
      AND bf.nmovimi   =
        (SELECT MAX(nmovimi)
        FROM estbf_bonfranseg bff
        WHERE bff.sseguro = psseguro
        AND bff.nmovimi  <= pnmovimi
        )
      AND bf.ctipgrup = 1
      AND bf.cgrup    = v_cgrup
      AND bd.cgrup    = bf.cgrup
      AND bd.csubgrup = bf.csubgrup
      AND bd.cversion = bf.cversion
      AND bd.cnivel   = bf.cnivel
      AND bd.cvalor1  = 1;
    ELSE
      SELECT bd.impvalor1
      INTO v_descuento
      FROM bf_bonfranseg bf,
        bf_detnivel bd
      WHERE bf.sseguro = psseguro
      AND bf.nmovimi   =
        (SELECT MAX(nmovimi)
        FROM bf_bonfranseg bff
        WHERE bff.sseguro = psseguro
        AND bff.nmovimi  <= pnmovimi
        )
      AND bf.ctipgrup = 1
      AND bf.cgrup    = v_cgrup
      AND bd.cgrup    = bf.cgrup
      AND bd.csubgrup = bf.csubgrup
      AND bd.cversion = bf.cversion
      AND bd.cnivel   = bf.cnivel
      AND bd.cvalor1  = 1;
    END IF;
  EXCEPTION
  WHEN NO_DATA_FOUND THEN
    v_descuento := 0;
  END;
  RETURN v_descuento;
EXCEPTION
WHEN OTHERS THEN
  RETURN 0;
END f_descuento;
/*****************************************************************
FUNCTION f_dsctocomer
psseguro IN number     :
pnriesgo IN number
param    IN pmodo      : modo EST/POL
return                 : number
******************************************************************/
FUNCTION f_dsctocomer(
    psseguro IN NUMBER,
    pnriesgo IN NUMBER,
    pmodo    IN VARCHAR2 DEFAULT 'POL')
  RETURN NUMBER
IS
  v_dsctocomer riesgos.pdtocom%TYPE;
BEGIN
  BEGIN
    v_dsctocomer        := 0;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      SELECT pdtocom + pdtotec
      INTO v_dsctocomer
      FROM estriesgos
      WHERE sseguro = psseguro
      AND nriesgo   = pnriesgo
      ORDER BY sseguro DESC;
    ELSE
      SELECT pdtocom + pdtotec
      INTO v_dsctocomer
      FROM riesgos
      WHERE sseguro = psseguro
      AND nriesgo   = pnriesgo
      ORDER BY sseguro DESC;
    END IF;
  EXCEPTION
  WHEN NO_DATA_FOUND THEN
    v_dsctocomer := 0;
  END;
  RETURN v_dsctocomer;
EXCEPTION
WHEN OTHERS THEN
  RETURN '';
END f_dsctocomer;
/*****************************************************************
FUNCTION f_accesorios
psseguro IN number
pnriesgo IN number
pnmovimi IN number
pmodo    IN varchar    : modo EST/POL
pcampo   IN varchar    : 1 campo descripcion 2 campo valor
pind   in number  default 1: si el valor es diferente de 1 saca la suma del campo ivalacc.
return                 : varchar2
******************************************************************/
FUNCTION f_accesorios(
    psseguro IN NUMBER,
    pnriesgo IN NUMBER,
    pnmovimi IN NUMBER,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pcampo   IN NUMBER,
    p_ind    IN NUMBER DEFAULT 1) --ETM  Bug 33863/195850
  RETURN VARCHAR2
IS
  v_tresult   VARCHAR2(32000) := '';
  v_tconsulta VARCHAR2(2000);
  v_tlinia    VARCHAR2(200);
  v_tsuma     NUMBER := 0;
  vnmovimi    NUMBER := pnmovimi;
  vcount      NUMBER;
BEGIN
  IF NVL(pmodo, 'POL') != 'EST' THEN
    --Bug 39165/221039 - 10/12/2015 - AMC
    /* SELECT COUNT(1)
    INTO vcount
    FROM autdetriesgos
    WHERE sseguro = psseguro
    AND nmovimi = pnmovimi;
    -- INI BUG 0035054/0017470 -- ECP -- 24/03/2015 Se agrega si el movimiento es diferente del primer movimiento
    IF vcount = 0
    AND pnmovimi = 1 THEN
    -- FIN BUG 0035054/0017470 -- ECP -- 24/03/2015
    SELECT NVL(MAX(nmovimi), pnmovimi)
    INTO vnmovimi
    FROM autdetriesgos
    WHERE sseguro = psseguro;
    END IF;*/
    SELECT MAX(nmovimi)
    INTO vnmovimi
    FROM garanseg
    WHERE sseguro = psseguro;
    --Fi Bug 39165/221039 - 10/12/2015 - AMC
  END IF;
  IF NVL(pmodo, 'POL') = 'EST' THEN
    FOR i IN
    (SELECT a.taccesorio
      || ' '
      || e.tdesacc tdesacc,
      e.ivalacc
    FROM estautdetriesgos e,
      aut_accesorios a
    WHERE e.sseguro  = psseguro
    AND e.nmovimi    = pnmovimi
    AND e.nriesgo    = pnriesgo
    AND a.cversion   = 0
    AND a.caccesorio = e.caccesorio
    ORDER BY 1
    )
    LOOP
      IF pcampo   = 1 THEN
        v_tlinia := i.tdesacc;
      ELSE
        v_tlinia := i.ivalacc;
      END IF;
      IF p_ind  <> 1 THEN --ETM  Bug 33863/195850
        v_tsuma := v_tsuma + v_tlinia;
      ELSE
        v_tresult := v_tresult || v_tlinia || ' \par ';
      END IF;
    END LOOP;
  ELSE
    FOR i IN
    (SELECT a.taccesorio
      || ' '
      || e.tdesacc tdesacc,
      e.ivalacc
    FROM autdetriesgos e,
      aut_accesorios a
    WHERE e.sseguro  = psseguro
    AND e.nmovimi    = vnmovimi
    AND e.nriesgo    = pnriesgo
    AND a.cversion   = 0
    AND a.caccesorio = e.caccesorio
    ORDER BY 1
    )
    LOOP
      IF pcampo   = 1 THEN
        v_tlinia := i.tdesacc;
      ELSE
        v_tlinia := i.ivalacc;
      END IF;
      IF p_ind  <> 1 THEN --ETM  Bug 33863/195850
        v_tsuma := v_tsuma + v_tlinia;
      ELSE
        v_tresult := v_tresult || v_tlinia || ' \par ';
      END IF;
    END LOOP;
  END IF;
  IF p_ind <> 1 THEN --ETM  Bug 33863/195850
    RETURN (v_tsuma);
  ELSE
    RETURN (f_jrep_trad(v_tresult));
  END IF;
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_accesorios;
/*****************************************************************
FUNCTION f_dispositivos
psseguro IN number
pnriesgo IN number
pnmovimi IN number
pmodo    IN varchar      : modo EST/POL
return                  : varchar2
******************************************************************/
FUNCTION f_dispositivos(
    psseguro IN NUMBER,
    pnriesgo IN NUMBER,
    pnmovimi IN NUMBER,
    pmodo    IN VARCHAR2 DEFAULT 'POL')
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(2000);
    v_tlinia    VARCHAR2(200);
    v_cversion autdisriesgos.cversion%TYPE;
    v_cdispositivo autdisriesgos.cdispositivo%TYPE;
    vnmovimi NUMBER := pnmovimi;
    vcount   NUMBER;
  BEGIN
    IF NVL(pmodo, 'POL') != 'EST' THEN
      SELECT COUNT(1)
      INTO vcount
      FROM autdisriesgos
      WHERE sseguro = psseguro
      AND nmovimi   = pnmovimi
      AND nriesgo   = pnriesgo;
    IF vcount       = 0 THEN
      SELECT NVL(MAX(nmovimi), pnmovimi)
      INTO vnmovimi
      FROM autdisriesgos
      WHERE sseguro = psseguro
      AND nriesgo   = pnriesgo;
    END IF;
  END IF;
  v_tconsulta         := 'SELECT nvl(cversion,' || CHR(39) || CHR(39) || '), nvl(cdispositivo,' || CHR(39) || CHR(39) || ') ';
  IF NVL(pmodo, 'POL') = 'EST' THEN
    v_tconsulta       := v_tconsulta || 'FROM estautdisriesgos ';
  ELSE
    v_tconsulta := v_tconsulta || 'FROM autdisriesgos ';
  END IF;
  v_tconsulta := v_tconsulta || 'WHERE sseguro = ' || psseguro || ' AND nriesgo = ' || pnriesgo || ' AND nmovimi = ' || vnmovimi;
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_cversion, v_cdispositivo;
    BEGIN
      SELECT NVL(ad.tdispositivo, '')
      INTO v_tlinia
      FROM aut_dispositivos ad
      WHERE ad.cversion   = v_cversion
      AND ad.cdispositivo = v_cdispositivo;
    EXCEPTION
    WHEN NO_DATA_FOUND THEN
      SELECT NVL(ad.tdispositivo, '')
      INTO v_tlinia
      FROM aut_dispositivos ad
      WHERE ad.cversion   = 0
      AND ad.cdispositivo = v_cdispositivo;
    END;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    v_tresult := v_tresult || v_tlinia || ' \par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_dispositivos;
/*****************************************************************
FUNCTION f_tiene_accesorios
psseguro  IN number
pnriesgo  IN number
pnversion IN number
pcidioma  IN varchar2
return      varchar2     : SI , No
******************************************************************/
FUNCTION f_tiene_accesorios(
    psseguro  IN NUMBER,
    pnriesgo  IN NUMBER,
    pcversion IN VARCHAR2,--BUG 0061944 GZG 08/07/2020
    pcidioma  IN NUMBER,pcaccesorio IN NUMBER DEFAULT NULL)--BUG 0061944 GZG 08/07/2020
  RETURN VARCHAR2
IS
  v_tiene_acc VARCHAR2(2) := '';
BEGIN
--INI BUG 0061944 GZG 08/07/2020
IF pcaccesorio IS NOT NULL THEN
  SELECT DECODE(COUNT(*), 0, f_axis_literales(101779, pcidioma), f_axis_literales(103638, pcidioma))
    INTO v_tiene_acc
    FROM estautdetriesgos adtr
   WHERE adtr.sseguro = psseguro
     AND adtr.nriesgo   = pnriesgo
     AND adtr.cversion  = pcversion
     AND adtr.caccesorio  = pcaccesorio
     AND adtr.nmovimi   = (SELECT MAX(adtr2.nmovimi)
                          FROM estautdetriesgos adtr2
                         WHERE adtr2.sseguro   = adtr.sseguro
                           AND adtr2.nriesgo   = adtr.nriesgo
                           AND adtr2.caccesorio  = adtr.caccesorio
                           AND adtr2.cversion  = adtr.cversion);
ELSE
  SELECT DECODE(COUNT(*), 0, f_axis_literales(101779, pcidioma), f_axis_literales(103638, pcidioma))
  INTO v_tiene_acc
  FROM estautdetriesgos adtr
  WHERE adtr.sseguro = psseguro
  AND adtr.nriesgo   = pnriesgo
  AND adtr.cversion  = pcversion;
END IF;
--FIN BUG 0061944 GZG 08/07/2020
  RETURN v_tiene_acc;
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_tiene_accesorios;
/*****************************************************************
FUNCTION f_tiene_dispositivos
psseguro  IN number
pnriesgo  IN number
pnversion IN number
pcidioma  IN varchar2
return      varchar2     : SI , No
******************************************************************/
FUNCTION f_tiene_dispositivos(
    psseguro  IN NUMBER,
    pnriesgo  IN NUMBER,
    pcversion IN NUMBER,
    pcidioma  IN NUMBER)
  RETURN VARCHAR2
IS
  v_tiene_disp VARCHAR2(2) := '';
BEGIN
  SELECT DECODE(COUNT(*), 0, f_axis_literales(101779, pcidioma), f_axis_literales(103638, pcidioma))
  INTO v_tiene_disp
  FROM estautdisriesgos adir
  WHERE adir.sseguro = psseguro
  AND adir.nriesgo   = pnriesgo
  AND adir.cversion  = pcversion;
  RETURN v_tiene_disp;
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_tiene_dispositivos;
/*****************************************************************
FUNCTION f_numero_a_texto
Retorna un numero en la seva correspondencia amb lletres.
imp      IN number        : numero a pasar a texte.
numdec   IN number        : numero de decimales.
pcidioma IN number        : idioma en que estarÃ¿Â¡ el texte del numero. 1 catalÃ¿Â¡n  2 castellano
return      varchar2      : el numero descrit en texte.
******************************************************************/
FUNCTION f_numero_a_texto(
    imp    NUMBER,
    numdec NUMBER DEFAULT 2,
    idioma NUMBER DEFAULT 2)
  RETURN VARCHAR2
IS
  es_un_numero NUMBER;
  imp_let      VARCHAR2(300);
  imp_char     VARCHAR2(20);
  impd_char    VARCHAR2(2);
  importe_let  VARCHAR2(300);
  mascara      VARCHAR2(5);
BEGIN
  IF numdec    = 1 THEN
    mascara   := 'd9';
  ELSIF numdec = 2 THEN
    mascara   := 'd99';
  ELSE
    mascara := NULL;
  END IF;
  -- Se pasa a cadena
  imp_char  := TO_CHAR(TRUNC(imp));
  impd_char := LTRIM(LTRIM(LTRIM(TO_CHAR(imp - TRUNC(imp), mascara), ' '), '.'), ',');
  IF idioma  > 1 THEN
    SELECT --Centenas de miles de millones.
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 1, 1), 1, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 2, 2), '00', 'CIEN ', 'CIENTO '), 2, 'DOSCIENTOS ', 3, 'TRESCIENTOS ', 4, 'CUATROCIENTOS ', 5, 'QUINIENTOS ', 6, 'SEISCIENTOS ', 7, 'SETECIENTOS ', 8, 'OCHOCIENTOS ', 9, 'NOVECIENTOS ', 0, '')
      || --Decenas miles de millones.
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 2, 1), 1, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 1), 0, 'DIEZ ', 1, 'ONCE MIL ', 2, 'DOCE MIL ', 3, 'TRECE MIL ', 4, 'CATORCE MIL ', 5, 'QUINCE MIL ', 6, 'DICISEIS MIL ', 7, 'DIECISIETE MIL ', 8, 'DIECIOCHO MIL ', 9, 'DIECINUEVE MIL '), 2, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 1), 0, 'VEINTE ', 'VEINTI'), 3, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 1), 0, 'TREINTA ', 'TREINTA Y '), 4, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 1), 0, 'CUARENTA ', 'CUARENTA Y '), 5, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 1), 0, 'CINCUENTA ', 'CINCUENTA Y '), 6, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 1), 0, 'SESENTA ', 'SESENTA Y '), 7, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 1), 0, 'SETENTA ', 'SETENTA Y '), 8, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 1), 0, 'OCHENTA ', 'OCHENTA Y '), 9, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 1), 0, 'NOVENTA ', 'NOVENTA Y '), 0, '')
      || --Unidades de milles de millones
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 3, 1), 1, DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 2, 1), '1', '', DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 1, 3), '001', 'MIL ', 'UN MIL ')), 2, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 2, 1), 1, '', 'DOS MIL '), 3, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 2, 1), 1, '', 'TRES MIL '), 4, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 2, 1), 1, '', 'CUATRO MIL '), 5, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 2, 1), 1, '', 'CINCO MIL '), 6, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 2, 1), 1, '', 'SEIS MIL '), 7, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 2, 1), 1, '', 'SIETE MIL '), 8, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 2, 1), 1, '', 'OCHO MIL '), 9, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 2, 1), 1, '', 'NUEVE MIL '), 0, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 1, 3), '000', '', 'MIL '))
      || --Centenas de millon.
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 4, 1), 1, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 5, 2), '00', 'CIEN ', 'CIENTO '), 2, 'DOSCIENTOS ', 3, 'TRESCIENTOS ', 4, 'CUATROCIENTOS ', 5, 'QUINIENTOS ', 6, 'SEISCIENTOS ', 7, 'SETECIENTOS ', 8, 'OCHOCIENTOS ', 9, 'NOVECIENTOS ', 0, '')
      || --Decenas de millon.
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 5, 1), 1, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 6, 1), 0, 'DIEZ ', 1, 'ONCE MILLONES ', 2, 'DOCE MILLONES ', 3, 'TRECE MILLONES ', 4, 'CATORCE MILLONES ', 5, 'QUINCE MILLONES ', 6, 'DICISEIS MILLONES ', 7, 'DIECISIETE MILLONES ', 8, 'DIECIOCHO MILLONES ', 9, 'DIECINUEVE MILLONES '), 2, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 6, 1), 0, 'VEINTE ', 'VEINTI'), 3, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 6, 1), 0, 'TREINTA ', 'TREINTA Y '), 4, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 6, 1), 0, 'CUARENTA ', 'CUARENTA Y '), 5, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 6, 1), 0, 'CINCUENTA ', 'CINCUENTA Y '), 6, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 6, 1), 0, 'SESENTA ', 'SESENTA Y '), 7, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 6, 1), 0, 'SETENTA ', 'SETENTA Y '), 8, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 6, 1), 0, 'OCHENTA ', 'OCHENTA Y '), 9, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 6, 1), 0, 'NOVENTA ', 'NOVENTA Y '), 0, '')
      || --Unidades de millon.
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 6, 1), 1, DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 5, 1), '1', '', DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 2), '00', 'UN MILLON ', 'UN MILLONES ')), 2, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 5, 1), 1, '', 'DOS MILLONES '), 3, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 5, 1), 1, '', 'TRES MILLONES '), 4, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 5, 1), 1, '', 'CUATRO MILLONES '), 5, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 5, 1), 1, '', 'CINCO MILLONES '), 6, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 5, 1), 1, '', 'SEIS MILLONES '), 7, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 5, 1), 1, '', 'SIETE MILLONES '), 8, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 5, 1), 1, '', 'OCHO MILLONES '), 9, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 5, 1), 1, '', 'NUEVE MILLONES '), 0, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 3), '000', '', 'MILLONES '))
      || --Centenas de millar.
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 7, 1), 1, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 8, 2), '00', 'CIEN ', 'CIENTO '), 2, 'DOSCIENTOS ', 3, 'TRESCIENTOS ', 4, 'CUATROCIENTOS ', 5, 'QUINIENTOS ', 6, 'SEISCIENTOS ', 7, 'SETECIENTOS ', 8, 'OCHOCIENTOS ', 9, 'NOVECIENTOS ', 0, '')
      || --Decenas de millar.
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 8, 1), 1, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 9, 1), 0, 'DIEZ ', 1, 'ONCE MIL ', 2, 'DOCE MIL ', 3, 'TRECE MIL ', 4, 'CATORCE MIL ', 5, 'QUINCE MIL ', 6, 'DICISEIS MIL ', 7, 'DIECISIETE MIL ', 8, 'DIECIOCHO MIL ', 9, 'DIECINUEVE MIL '), 2, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 9, 1), 0, 'VEINTE ', 'VEINTI'), 3, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 9, 1), 0, 'TREINTA ', 'TREINTA Y '), 4, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 9, 1), 0, 'CUARENTA ', 'CUARENTA Y '), 5, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 9, 1), 0, 'CINCUENTA ', 'CINCUENTA Y '), 6, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 9, 1), 0, 'SESENTA ', 'SESENTA Y '), 7, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 9, 1), 0, 'SETENTA ', 'SETENTA Y '), 8, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 9, 1), 0, 'OCHENTA ', 'OCHENTA Y '), 9, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 9, 1), 0, 'NOVENTA ', 'NOVENTA Y '), 0, '')
      || --Unidades de millar
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 9, 1), 1, DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 8, 1), '1', '', DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 7, 3), '001', 'MIL ', 'UN MIL ')), 2, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 8, 1), 1, '', 'DOS MIL '), 3, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 8, 1), 1, '', 'TRES MIL '), 4, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 8, 1), 1, '', 'CUATRO MIL '), 5, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 8, 1), 1, '', 'CINCO MIL '), 6, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 8, 1), 1, '', 'SEIS MIL '), 7, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 8, 1), 1, '', 'SIETE MIL '), 8, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 8, 1), 1, '', 'OCHO MIL '), 9, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 8, 1), 1, '', 'NUEVE MIL '), 0, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 7, 3), '000', '', 'MIL '))
      || --Centenas.
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 10, 1), 1, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 11, 2), '00', 'CIEN', 'CIENTO '), 2, 'DOSCIENTOS ', 3, 'TRESCIENTOS ', 4, 'CUATROCIENTOS ', 5, 'QUINIENTOS ', 6, 'SEISCIENTOS ', 7, 'SETECIENTOS ', 8, 'OCHOCIENTOS ', 9, 'NOVECIENTOS ', 0, '')
      || --Decenas.
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 11, 1), 1, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 12), 0, 'DIEZ ', 1, 'ONCE ', 2, 'DOCE ', 3, 'TRECE ', 4, 'CATORCE ', 5, 'QUINCE ', 6, 'DICISEIS ', 7, 'DIECISIETE ', 8, 'DIECIOCHO ', 9, 'DIECINUEVE '), 2, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 12), 0, 'VEINTE ', 'VEINTI'), 3, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 12), 0, 'TREINTA ', 'TREINTA Y '), 4, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 12), 0, 'CUARENTA ', 'CUARENTA Y '), 5, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 12), 0, 'CINCUENTA ', 'CINCUENTA Y '), 6, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 12), 0, 'SESENTA ', 'SESENTA Y '), 7, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 12), 0, 'SETENTA ', 'SETENTA Y '), 8, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 12), 0, 'OCHENTA ', 'OCHENTA Y '), 9, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 12), 0, 'NOVENTA ', 'NOVENTA Y '), 0, '')
      || --Unidades.
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 12, 1), 1, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 11, 1), 1, '', 'UN '), 2, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 11, 1), 1, '', 'DOS '), 3, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 11, 1), 1, '', 'TRES '), 4, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 11, 1), 1, '', 'CUATRO '), 5, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 11, 1), 1, '', 'CINCO '), 6, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 11, 1), 1, '', 'SEIS '), 7, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 11, 1), 1, '', 'SIETE '), 8, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 11, 1), 1, '', 'OCHO '), 9, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 11, 1), 1, '', 'NUEVE '), 0, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 1, 12), '000000000000', 'CERO ', ''))
      || DECODE(LPAD(impd_char, 2, '0'), '00', '', 'CON ')
      || --Decimales
      --Decenas.
      DECODE( SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 0, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 2), 1, 'UNO ', 2, 'DOS ', 3, 'TRES ', 4, 'CUATRO ', 5, 'CINCO ', 6, 'SEIS ', 7, 'SIETE ', 8, 'OCHO ', 9, 'NUEVE '), 1, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 2), 0, 'DIEZ ', 1, 'ONCE ', 2, 'DOCE ', 3, 'TRECE ', 4, 'CATORCE ', 5, 'QUINCE ', 6, 'DICISEIS ', 7, 'DIECISIETE ', 8, 'DIECIOCHO ', 9, 'DIECINUEVE '), 2, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 2), 0, 'VEINTE ', 'VEINTI'), 3, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 2), 0, 'TREINTA ', 'TREINTA Y '), 4, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 2), 0, 'CUARENTA ', 'CUARENTA Y '), 5, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 2), 0, 'CINCUENTA ', 'CINCUENTA Y '), 6, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 2), 0, 'SESENTA ', 'SESENTA Y '), 7, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 2), 0, 'SETENTA ', 'SETENTA Y '), 8, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 2), 0, 'OCHENTA ', 'OCHENTA Y '), 9, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 2), 0, 'NOVENTA ',
      'NOVENTA Y '), 0, '')
      || --Unidades.
      DECODE( SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 0, '', DECODE( SUBSTR(LPAD(impd_char, 2, '0'), 2, 1), 1, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 1, '', 'UN '), 2, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 1, '', 'DOS '), 3, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 1, '', 'TRES '), 4, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 1, '', 'CUATRO '), 5, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 1, '', 'CINCO '), 6, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 1, '', 'SEIS '), 7, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 1, '', 'SIETE '), 8, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 1, '', 'OCHO '), 9, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 1, '', 'NUEVE ')))
    INTO importe_let
    FROM DUAL;
  ELSIF idioma = 1 THEN
    SELECT --Centenes de milers de milions.
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 1, 1), 1, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 2, 2), '00', 'CENT ', 'CENT '), 2, 'DOSCENTS ', 3, 'TRESCENTS ', 4, 'QUATRECENTS ', 5, 'CINCENTS ', 6, 'SISCENTS ', 7, 'SETCENTS ', 8, 'VUITCENTS ', 9, 'NOUCENTS ', 0, '')
      || --Desenes milers de milions.
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 2, 1), 1, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 1), 0, 'DEU ', 1, 'ONZE MIL ', 2, 'DOTZE MIL ', 3, 'TRETZE MIL ', 4, 'CATORZE MIL ', 5, 'QUINZE MIL ', 6, 'SETZE MIL ', 7, 'DISSET MIL ', 8, 'DIVUIT MIL ', 9, 'DINOU MIL '), 2, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 1), 0, 'VINT ', 'VINT-I-'), 3, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 1), 0, 'TRENTA ', 'TREINTA '), 4, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 1), 0, 'QUARANTA ', 'QUARANTA '), 5, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 1), 0, 'CINQUANTA ', 'CINQUANTA '), 6, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 1), 0, 'SEIXANTA ', 'SEIXANTA '), 7, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 1), 0, 'SETANTA ', 'SETANTA '), 8, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 1), 0, 'VUITANTA ', 'VUITANTA '), 9, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 1), 0, 'NORANTA ', 'NORANTA '), 0, '')
      || --Unitats de milers de milions
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 3, 1), 1, DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 2, 1), '1', '', DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 1, 3), '001', 'MIL ', 'UN MIL ')), 2, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 2, 1), 1, '', 'DOS MIL '), 3, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 2, 1), 1, '', 'TRES MIL '), 4, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 2, 1), 1, '', 'QUATRE MIL '), 5, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 2, 1), 1, '', 'CINC MIL '), 6, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 2, 1), 1, '', 'SIS MIL '), 7, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 2, 1), 1, '', 'SET MIL '), 8, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 2, 1), 1, '', 'VUIT MIL '), 9, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 2, 1), 1, '', 'NOU MIL '), 0, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 1, 3), '000', '', 'MIL '))
      || --Centenes de miliÃ¿Â³
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 4, 1), 1, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 5, 2), '00', 'CENT ', 'CENT '), 2, 'DOS-CENTS ', 3, 'TRES-CENTS ', 4, 'CUATRE-CENTS ', 5, 'CINC-CENTS ', 6, 'SIS-CENTS ', 7, 'SET-CENTS ', 8, 'VUIT-CENTS ', 9, 'NOU-CENTS ', 0, '')
      || --Desenes de miliÃ¿Â³ (m'entra complexe d'assafata del cuponazo)
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 5, 1), 1, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 6, 1), 0, 'DEU ', 1, 'ONZE MILIONS ', 2, 'DOTZE MILIONS ', 3, 'TRETZE MILIONS ', 4, 'CATORZE MILIONS ', 5, 'QUINZE MILIONS ', 6, 'SETZE MILIONS ', 7, 'DISSET MILIONS ', 8, 'DIVUIT MILIONS ', 9, 'DINOU MILIONS '), 2, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 6, 1), 0, 'VINT ', 'VINT-I-'), 3, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 6, 1), 0, 'TRENTA ', 'TRENTA '), 4, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 6, 1), 0, 'QUARANTA ', 'QUARANTA '), 5, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 6, 1), 0, 'CINQUANTA ', 'CINQUANTA '), 6, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 6, 1), 0, 'SEIXANTA ', 'SEIXANTA '), 7, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 6, 1), 0, 'SETANTA ', 'SETANTA '), 8, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 6, 1), 0, 'VUITANTA ', 'VUITANTA '), 9, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 6, 1), 0, 'NORANTA ', 'NORANTA '), 0, '')
      || --Unitats de miliÃ¿Â³
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 6, 1), 1, DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 5, 1), '1', '', DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 2), '00', 'UN MILIÃ¿Â¿ ', 'UN MILIONS ')), 2, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 5, 1), 1, '', 'DOS MILIONS '), 3, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 5, 1), 1, '', 'TRES MILIONS '), 4, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 5, 1), 1, '', 'QUATRE MILIONS '), 5, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 5, 1), 1, '', 'CINC MILIONS '), 6, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 5, 1), 1, '', 'SIS MILIONS '), 7, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 5, 1), 1, '', 'SET MILIONS '), 8, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 5, 1), 1, '', 'VUIT MILIONS '), 9, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 5, 1), 1, '', 'NOU MILIONS '), 0, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 3, 3), '000', '', 'MILIONS '))
      || --Centenes de millar
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 7, 1), 1, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 8, 2), '00', 'CENT ', 'CENT '), 2, 'DOS-CENTS ', 3, 'TRES-CENTS ', 4, 'CUATRE-CENTS ', 5, 'CINC-CENTS ', 6, 'SIS-CENTS ', 7, 'SET-CENTS ', 8, 'VUIT-CENTS ', 9, 'NOU-CENTS ', 0, '')
      || --Desenes de millar
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 8, 1), 1, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 9, 1), 0, 'DEU ', 1, 'ONZE MIL ', 2, 'DOTZE MIL ', 3, 'TRETZE MIL ', 4, 'CATORZE MIL ', 5, 'QUINZE MIL ', 6, 'SETZE MIL ', 7, 'DISSET MIL ', 8, 'DIVUIT MIL ', 9, 'DINOU MIL '), 2, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 9, 1), 0, 'VINT ', 'VINT-I-'), 3, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 9, 1), 0, 'TRENTA ', 'TRENTA '), 4, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 9, 1), 0, 'QUARANTA ', 'QUARANTA '), 5, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 9, 1), 0, 'CINQUANTA ', 'CINQUANTA '), 6, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 9, 1), 0, 'SEIXANTA ', 'SEIXANTA '), 7, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 9, 1), 0, 'SETANTA ', 'SETANTA '), 8, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 9, 1), 0, 'VUITANTA ', 'VUITANTA '), 9, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 9, 1), 0, 'NORANTA ', 'NORANTA '), 0, '')
      || --Unitats de millar
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 9, 1), 1, DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 8, 1), '1', '', DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 7, 3), '001', 'MIL ', 'UN MIL ')), 2, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 8, 1), 1, '', 'DOS MIL '), 3, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 8, 1), 1, '', 'TRES MIL '), 4, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 8, 1), 1, '', 'QUATRE MIL '), 5, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 8, 1), 1, '', 'CINC MIL '), 6, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 8, 1), 1, '', 'SIS MIL '), 7, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 8, 1), 1, '', 'SET MIL '), 8, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 8, 1), 1, '', 'VUIT MIL '), 9, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 8, 1), 1, '', 'NOU MIL '), 0, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 7, 3), '000', '', 'MIL '))
      || --Centenes
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 10, 1), 1, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 11, 2), '00', 'CENT', 'CENT '), 2, 'DOS-CENTS ', 3, 'TRES-CENTS ', 4, 'CUATRE-CENTS ', 5, 'CINC-CENTS ', 6, 'SIS-CENTS ', 7, 'SET-CENTS ', 8, 'VUIT-CENTS ', 9, 'NOU-CENTS ', 0, '')
      || --Desenes
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 11, 1), 1, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 12), 0, 'DEU ', 1, 'ONZE ', 2, 'DOTZE ', 3, 'TRETZE ', 4, 'CATORZE ', 5, 'QUINZE ', 6, 'SETZE ', 7, 'DISSET ', 8, 'DIVUIT ', 9, 'DINOU '), 2, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 12), 0, 'VINT ', 'VINT-I-'), 3, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 12), 0, 'TRENTA ', 'TRENTA '), 4, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 12), 0, 'QUARANTA ', 'QUARANTA '), 5, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 12), 0, 'CINQUANTA ', 'CINQUANTA '), 6, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 12), 0, 'SEIXANTA ', 'SEIXANTA '), 7, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 12), 0, 'SETANTA ', 'SETANTA '), 8, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 12), 0, 'VUITANTA ', 'VUITANTA '), 9, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 12), 0, 'NORANTA ', 'NORANTA '), 0, '')
      || --Unitats.
      DECODE( SUBSTR(LPAD(imp_char, 12, '0'), 12, 1), 1, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 11, 1), 1, '', 'UN '), 2, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 11, 1), 1, '', 'DOS '), 3, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 11, 1), 1, '', 'TRES '), 4, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 11, 1), 1, '', 'QUATRE '), 5, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 11, 1), 1, '', 'CINC '), 6, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 11, 1), 1, '', 'SIS '), 7, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 11, 1), 1, '', 'SET '), 8, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 11, 1), 1, '', 'VUIT '), 9, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 11, 1), 1, '', 'NOU '), 0, DECODE(SUBSTR(LPAD(imp_char, 12, '0'), 1, 12), '000000000000', 'ZERO ', ''))
      || DECODE(LPAD(impd_char, 2, '0'), '00', '', 'AMB ')
      || --Decimals
      --Desenes.
      DECODE( SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 0, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 2), 1, 'UN ', 2, 'DOS ', 3, 'TRES ', 4, 'QUATRE ', 5, 'CINC ', 6, 'SIS ', 7, 'SET ', 8, 'VUIT ', 9, 'NOU '), 1, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 2), 0, 'DEU ', 1, 'ONZE ', 2, 'DOTZE ', 3, 'TRETZE ', 4, 'CATORZE ', 5, 'QUINZE ', 6, 'SETZE ', 7, 'DISSET ', 8, 'DIVUIT ', 9, 'DINOU '), 2, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 2), 0, 'VINT ', 'VINT-I-'), 3, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 2), 0, 'TRENTA ', 'TRENTA '), 4, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 2), 0, 'QUARANTA ', 'QUARANTA '), 5, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 2), 0, 'CINQUANTA ', 'CINQUANTA '), 6, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 2), 0, 'SEIXANTA ', 'SEIXANTA '), 7, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 2), 0, 'SETANTA ', 'SETANTA '), 8, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 2), 0, 'VUITANTA ', 'VUITANTA '), 9, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 2), 0, 'NORANTA ', 'NORANTA '), 0, '')
      || --Unitats.
      DECODE( SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 0, '', DECODE( SUBSTR(LPAD(impd_char, 2, '0'), 2, 1), 1, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 1, '', 'UN '), 2, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 1, '', 'DOS '), 3, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 1, '', 'TRES '), 4, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 1, '', 'QUATRE '), 5, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 1, '', 'CINC '), 6, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 1, '', 'SIS '), 7, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 1, '', 'SET '), 8, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 1, '', 'VUIT '), 9, DECODE(SUBSTR(LPAD(impd_char, 2, '0'), 1, 1), 1, '', 'NOU ')))
    INTO importe_let
    FROM DUAL;
  END IF;
  RETURN (importe_let);
END f_numero_a_texto;
/*****************************************************************
FUNCTION f_calculos_rea
psproces IN NUMBER          : numero del proceso
pccompani in number         : compaÃ¿Â±ia
pcampo IN NUMBER            : que campo queremos obtener
Ult. ModificaciÃ¿Â³n: KBR - 10/06/2014
DescripciÃ¿Â³n: 1. Eliminamos del Group By los campos CCONCEP y CDEBHAB de los campos 6 al 12
2. Cambiamos a.cdebhab por mc.cdebhab (Buscar de MOVCTATECNICA)
3. AÃ¿Â±adimos f_round dentro de la funciÃ¿Â³n SUM
******************************************************************/
FUNCTION f_calculos_rea(
    psproces IN NUMBER,
    pcampo   IN NUMBER,
    pcestado IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult       VARCHAR2(32000) := '';
    v_tconsulta     VARCHAR2(2000)  := '';
    v_tlinia        VARCHAR2(200)   := '';
    v_spagrea       NUMBER          := NULL;
    v_tiporeaseguro VARCHAR2(2)     := 'LP';
  BEGIN
    --Determinamos si es un pago o un ingreso
    v_tiporeaseguro := pac_isqlfor_lcol.f_tipodoc_reaseguro(psproces);
    v_tconsulta     := v_tconsulta || 'SELECT ';
    IF pcampo        = 1 THEN
      v_tconsulta   := v_tconsulta || ' decode(mc.ccompapr,null,0,mc.ccompapr) ';
    ELSIF pcampo     = 2 THEN
      v_tconsulta   := v_tconsulta || ' c.cmoneda ';
    ELSIF pcampo     = 3 THEN
      v_tconsulta   := v_tconsulta || '       DECODE(mc.ctramo, 1, ''P'', 2, ''P'', 3, ''P'', 4, ''P'', 5, ''F'', ''N'') ttipo ';
    ELSIF pcampo     = 4 THEN
      v_tconsulta   := v_tconsulta || '       pac_isqlfor.f_dades_persona(com.sperson, 1) nit ';
    ELSIF pcampo     = 5 THEN
      --AGG 26/09/2014
      --INI BUG 0035431/0203621 - 29/04/2015 - JAE - Formato numÃ¿Â©rico
      v_tconsulta := v_tconsulta || '       decode( c.cmoneda, ''COP'' ' || '       , pac_isqlfor_lcol.fu_formato(p_valor => (SUM(DECODE(mc.cconcep, 1, mc.iimport, 9, mc.iimport, 20, mc.iimport, 23, mc.iimport, 16, mc.iimport, 33, mc.iimport, 34, mc.iimport,  0)* DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'',DECODE(mc.cdebhab, 1, -1, 1),DECODE(mc.cdebhab, 1, 1, -1))))) ' || '       , pac_isqlfor_lcol.fu_formato(p_valor => (SUM(DECODE(mc.cconcep, 1, mc.iimport, 9, mc.iimport, 20, mc.iimport, 23, mc.iimport, 16, mc.iimport, 33, mc.iimport, 34, mc.iimport,  0)* DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'',DECODE(mc.cdebhab, 1, -1, 1),DECODE(mc.cdebhab, 1, 1, -1))))) ) iprimcosxl ';
    ELSIF pcampo   = 6 THEN
      --AGG 26/09/2014
      v_tconsulta := v_tconsulta || '       decode( c.cmoneda, ''COP'' ' || '       , pac_isqlfor_lcol.fu_formato(p_valor => (SUM(DECODE(mc.cconcep, 2, mc.iimport, 14, mc.iimport, 12,mc.iimport, 0) * DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'',DECODE(mc.cdebhab, 1, -1, 1),DECODE(mc.cdebhab, 1, 1, -1))))) ' || '       , pac_isqlfor_lcol.fu_formato(p_valor => (SUM(DECODE(mc.cconcep, 2, mc.iimport, 14, mc.iimport, 12,mc.iimport, 0) * DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'',DECODE(mc.cdebhab, 1, -1, 1),DECODE(mc.cdebhab, 1, 1, -1)))))) icomision ';
    ELSIF pcampo   = 7 THEN
      --AGG 26/09/2014
      v_tconsulta := v_tconsulta || '       decode( c.cmoneda, ''COP'' ' || '       , pac_isqlfor_lcol.fu_formato(p_valor => (SUM(DECODE(mc.cconcep, 3, mc.iimport, 13, mc.iimport, 6, mc.iimport, 35,mc.iimport, 36, mc.iimport, 0)* DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'',DECODE(mc.cdebhab, 1, -1, 1),DECODE(mc.cdebhab, 1, 1, -1))))) ' || '       , pac_isqlfor_lcol.fu_formato(p_valor => (SUM(DECODE(mc.cconcep, 3, mc.iimport, 13, mc.iimport, 6, mc.iimport, 35,mc.iimport, 36, mc.iimport, 0)* DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'',DECODE(mc.cdebhab, 1, -1, 1),DECODE(mc.cdebhab, 1, 1, -1))))) ) ideposito ';
    ELSIF pcampo   = 8 THEN
      v_tconsulta := v_tconsulta || '       decode( c.cmoneda, ''COP'' ' || '       , pac_isqlfor_lcol.fu_formato(p_valor => (SUM(DECODE(mc.cconcep, 5, mc.iimport, 39, mc.iimport, 40,mc.iimport, 37, mc.iimport, 38, mc.iimport, 0) * DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'',DECODE(mc.cdebhab, 1, -1, 1),DECODE(mc.cdebhab, 1, 1, -1))))) ' || '       , pac_isqlfor_lcol.fu_formato(p_valor => (SUM(DECODE(mc.cconcep, 5, mc.iimport, 39, mc.iimport, 40,mc.iimport, 37, mc.iimport, 38, mc.iimport, 0) * DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'',DECODE(mc.cdebhab, 1, -1, 1),DECODE(mc.cdebhab, 1, 1, -1))))) ) isiniestros ';
    ELSIF pcampo   = 9 THEN
      v_tconsulta := v_tconsulta || '       decode( c.cmoneda, ''COP'' ' || '       , pac_isqlfor_lcol.fu_formato(p_valor => (SUM(DECODE(mc.cconcep, 4, mc.iimport, 0)* DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'',DECODE(mc.cdebhab, 1, -1, 1),DECODE(mc.cdebhab, 1, 1, -1))))) ' || '       , pac_isqlfor_lcol.fu_formato(p_valor => (SUM(DECODE(mc.cconcep, 4, mc.iimport, 0)* DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'',DECODE(mc.cdebhab, 1, -1, 1),DECODE(mc.cdebhab, 1, 1, -1))))) ) iinteres ';
    ELSIF pcampo   = 10 THEN
      v_tconsulta := v_tconsulta || '       decode( c.cmoneda, ''COP'' ' || '       , pac_isqlfor_lcol.fu_formato(p_valor => (SUM(DECODE(mc.cconcep, 7, mc.iimport, 45, mc.iimport, 0)* DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'',DECODE(mc.cdebhab, 1, -1, 1),DECODE(mc.cdebhab, 1, 1, -1))))) ' || '       , pac_isqlfor_lcol.fu_formato(p_valor => (SUM(DECODE(mc.cconcep, 7, mc.iimport, 45, mc.iimport, 0)* DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'',DECODE(mc.cdebhab, 1, -1, 1),DECODE(mc.cdebhab, 1, 1, -1))))) ) iimpuesto '; --Inicio/Fin OJS QT57918 13/03/2020 Añyadimos concepto 45
    ELSIF pcampo   = 11 THEN
      --AGG 26/09/2014
      v_tconsulta := v_tconsulta || '       decode( c.cmoneda, ''COP'' ' || '       , pac_isqlfor_lcol.fu_formato(p_valor => (SUM(DECODE(mc.cconcep, 24, mc.iimport, 15, mc.iimport, 0)* DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'',DECODE(mc.cdebhab, 1, -1, 1),DECODE(mc.cdebhab, 1, 1, -1))))) ' || '       , pac_isqlfor_lcol.fu_formato(p_valor => (SUM(DECODE(mc.cconcep, 24, mc.iimport, 0)* DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'',DECODE(mc.cdebhab, 1, -1, 1),DECODE(mc.cdebhab, 1, 1, -1))))) ) iotros '; --Inicio/Fin OJS QT57918 13/03/2020 Añyadimos concepto 15
    ELSIF pcampo   = 12 THEN
      v_tconsulta := v_tconsulta || '       decode( c.cmoneda, ''COP'' ' || '       , pac_isqlfor_lcol.fu_formato(p_valor => (SUM(mc.iimport * DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'',DECODE(mc.cdebhab, 1, -1, 1),DECODE(mc.cdebhab, 1, 1, -1))))) ' || '       , pac_isqlfor_lcol.fu_formato(p_valor => (SUM(mc.iimport * DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'',DECODE(mc.cdebhab, 1, -1, 1),DECODE(mc.cdebhab, 1, 1, -1)))))) ivneto ';
    END IF;
    --FIN BUG 0035431/0203621 - 29/04/2015 - JAE
    v_tconsulta   := v_tconsulta || ' FROM  MOVCTATECNICA MC, codicontratos c, companias com, tipoctarea a ' || ' where mc.spagrea IN (SELECT SPAGREA FROM MOVCTATECNICA WHERE SPROCES =' || psproces || ')';
    v_tconsulta   := v_tconsulta || ' and mc.cconcep in (1, 2, 3, 4, 5, 6, 7, 9, 12, 13, 14, 16, 20, 22, 23, 24, 33, 34, 35, 36, 37, 38, 39, 40, 45, 15)  and a.cconcep = mc.CCONCEP '; --Inicio/Fin OJS QT57918 13/03/2020 Anyadimos conceptos 15 y 45
    v_tconsulta   := v_tconsulta || ' and a.cempres = 12 ' || ' and a.cempres = mc.cempres ' || ' and a.ctipcta = 1 ' || ' and mc.scontra =  c.scontra and mc.ccompani =  com.ccompani ';
    IF pcestado   IS NOT NULL THEN
      v_tconsulta := v_tconsulta || ' and mc.cestado = ' || pcestado;
    END IF;
    v_tconsulta := v_tconsulta || '  group by c.cmoneda, mc.ccompapr, mc.ctramo, com.sperson ';
    OPEN vr_cursor FOR v_tconsulta;
    LOOP
      FETCH vr_cursor INTO v_tlinia;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_calculos_rea;
/*****************************************************************
FUNCTION f_tasa
fecha     IN DATE        :Fecha en la que se desea obtener la tasa
******************************************************************/
FUNCTION f_tasa(
    pfecha IN DATE)
  RETURN NUMBER
IS
  v_tasa NUMBER;
BEGIN
  SELECT NVL( (pac_eco_tipocambio.f_cambio('USD', 'COP', NVL(pac_eco_tipocambio.f_fecha_max_cambio('USD', 'COP', pfecha), pfecha))), 1)
  INTO v_tasa
  FROM DUAL;
  RETURN v_tasa;
EXCEPTION
WHEN OTHERS THEN
  RETURN 1;
END f_tasa;
FUNCTION f_fefecto_vg(
    psseguro IN NUMBER)
  RETURN DATE
IS
  v_ret DATE;
BEGIN
  SELECT fefecto
  INTO v_ret
  FROM movseguro
  WHERE nmovimi =
    (SELECT MAX(nmovimi)
    FROM movseguro
    WHERE sseguro = psseguro
    AND (cmotven IS NULL
    OR cmotven   != 998)
    )
  AND sseguro = psseguro;
  RETURN v_ret;
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_fefecto_vg;
FUNCTION f_motmov(
    psseguro IN NUMBER,
    pcidioma IN NUMBER,
    pnmovimi IN NUMBER)
  RETURN VARCHAR2
IS
  -- Inicio Bug 40686  AABC 17/04/2018 Version 122 se agrega exception cuando no encuentra datos
  v_ret    VARCHAR2(250);
  vcmotmov NUMBER;
  vcempres NUMBER;
  vcreteni NUMBER;
  vcsituac NUMBER;
  vsproduc NUMBER;
  -- Fin Bug 40686  AABC 17/04/2018 Version 122 se agrega exception cuando no encuentra datos
BEGIN
  -- Inicio Bug 40686  AABC 17/04/2018 Version 122 se agrega exception cuando no encuentra datos
  SELECT cempres,
    cmotmov,
    creteni,
    csituac,
    sproduc
  INTO vcempres,
    vcmotmov,
    vcreteni,
    vcsituac,
    vsproduc
  FROM seguros s,
    movseguro m
  WHERE s.sseguro = psseguro
  AND s.sseguro   = m.sseguro
  AND m.nmovimi   = pnmovimi;
  -- Fin Bug 40686  AABC 17/04/2018 Version 122 se agrega exception cuando no encuentra datos
  BEGIN
    SELECT f_axis_literales(slitera, pcidioma)
    INTO v_ret
    FROM pds_supl_grup
    WHERE cmotmov = vcmotmov
    AND cempres   = vcempres;
  EXCEPTION
  WHEN NO_DATA_FOUND THEN
    NULL;
  END;
  IF v_ret IS NULL THEN
    SELECT tmotmov
    INTO v_ret
    FROM motmovseg
    WHERE cmotmov = vcmotmov
    AND cidioma   = pcidioma;
  END IF;
  -- Inicio Bug 40686  AABC 17/04/2018 Version 122 Cambio de titulo para polizas retenidas
  IF NVL(pac_parametros.f_parproducto_n(vsproduc, 'GASTEXPREHOME'), 0) = 1 AND vcsituac = 4 AND vcreteni = 1 THEN
    SELECT tsuplem
    INTO v_ret
    FROM motmovseg
    WHERE cmotmov = vcmotmov
    AND cidioma   = pcidioma;
  END IF;
  -- Fin Bug 40686  AABC 17/04/2018 Version 122
  RETURN v_ret;
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_motmov;
FUNCTION f_clausulas_cobro(
    psseguro  IN NUMBER,
    pnmovimi  IN NUMBER,
    pcidioma  IN NUMBER,
    ptabla    IN VARCHAR2 DEFAULT 'POL',
    pcduplica IN NUMBER DEFAULT 0)
  RETURN CLOB
IS
  vret CLOB;
BEGIN
  IF ptabla = 'POL' THEN
    FOR i IN
    (SELECT clau
    FROM
      (SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        c.nordcla
      FROM clausugen cg,
        claususeg c
      WHERE cg.sclagen = c.sclagen
      AND c.sseguro    = psseguro
      AND c.nmovimi    = pnmovimi
      AND cg.cidioma   = pcidioma
      UNION
      SELECT REPLACE(REPLACE(REGEXP_REPLACE(tclaesp, '[[:space:]][[:space:]]*', ' '),'<br><br>','<br>'),'<br>','\par ') clau,--AITSSD-8394 GZG 09/03/2026
        nordcla
      FROM clausuesp
      WHERE sseguro = psseguro
      AND nmovimi   = pnmovimi
      AND sclagen  IS NULL
      UNION
      SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        c.nordcla
      FROM clausugen cg,
        clausuesp c
      WHERE cg.sclagen = c.sclagen
      AND c.sseguro    = psseguro
      AND c.nmovimi    = pnmovimi
      AND c.sclagen   IS NOT NULL
      AND cg.cidioma   = pcidioma
      ORDER BY nordcla
      )
    GROUP BY clau
    )
    LOOP
      vret := vret || i.clau || ' \par \par ';
    END LOOP;
  ELSE
    FOR i IN
    (SELECT clau
    FROM
      (SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        c.nordcla
      FROM clausugen cg,
        estclaususeg c
      WHERE cg.sclagen = c.sclagen
      AND c.sseguro    = psseguro
      AND c.nmovimi    = pnmovimi
      AND cg.cidioma   = pcidioma
      UNION
      SELECT REPLACE(REPLACE(REGEXP_REPLACE(tclaesp, '[[:space:]][[:space:]]*', ' '),'<br><br>','<br>'),'<br>','\par ') clau,--AITSSD-8394 GZG 09/03/2026
        nordcla
      FROM estclausuesp
      WHERE sseguro = psseguro
      AND nmovimi   = pnmovimi
      AND sclagen  IS NULL
      UNION
      SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        c.nordcla
      FROM clausugen cg,
        estclausuesp c
      WHERE cg.sclagen = c.sclagen
      AND c.sseguro    = psseguro
      AND c.nmovimi    = pnmovimi
      AND c.sclagen   IS NOT NULL
      AND cg.cidioma   = pcidioma
      ORDER BY nordcla
      )
    GROUP BY clau
    )
    LOOP
      vret := vret || i.clau || ' \par \par ';
    END LOOP;
  END IF;
  RETURN TO_CLOB(f_jrep_trad(vret));
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_clausulas_cobro;
FUNCTION f_obtenerasegurado(
    psseguro IN NUMBER)
  RETURN NUMBER
IS
  vsperson asegurados.sperson%TYPE := NULL;
BEGIN
  BEGIN
    -- Primero va a buscar en la tabla tomadores para ese sseguro, si existe se muestra este, en caso contrario
    -- se mostrara el primero de la tabla de segurados
    BEGIN
      SELECT a.sperson
      INTO vsperson
      FROM asegurados a
      WHERE a.sseguro = psseguro
      AND a.sperson   =
        (SELECT sperson FROM tomadores WHERE sseguro = psseguro
        );
      RETURN vsperson;
    EXCEPTION
    WHEN NO_DATA_FOUND THEN
      SELECT a.sperson
      INTO vsperson
      FROM asegurados a
      WHERE a.sseguro = psseguro
      AND ROWNUM      = 1;
      RETURN vsperson;
    WHEN OTHERS THEN
      RETURN NULL;
    END;
  EXCEPTION
  WHEN OTHERS THEN
    RETURN NULL;
  END;
END;
FUNCTION f_obtener_tipo_dom(
    psperson IN NUMBER,
    psseguro IN NUMBER)
  RETURN NUMBER
IS
  vcdomici NUMBER := 1;
BEGIN
  SELECT cdomici
  INTO vcdomici
  FROM asegurados
  WHERE sperson = psperson
  AND sseguro   = psseguro;
  RETURN vcdomici;
EXCEPTION
WHEN OTHERS THEN
  RETURN 1;
END;
FUNCTION f_obtener_iva_autos(
    psseguro  IN NUMBER,
    psnriesgo IN NUMBER,
    ptablas   IN VARCHAR2 DEFAULT 'EST',
    psproces  IN NUMBER DEFAULT NULL) --BUG 47494 MPC 08/03/2019 Se adiciona parametro.
  RETURN NUMBER
IS
  iva_total NUMBER := 0;
BEGIN
  IF ptablas = 'EST' THEN
    SELECT SUM(itotimp)
    INTO iva_total
    FROM estprimasgaranseg
    WHERE sseguro = psseguro
    AND nriesgo   = psnriesgo
      --
      --INI BUG 0036286 - 11/08/2017 - CASL - Se suman los valores de la ultima fecha de simulacion.
      --
    AND finiefe =
      (SELECT MAX(finiefe)
      FROM estprimasgaranseg
      WHERE sseguro = psseguro
      AND nriesgo   = psnriesgo
      );
    --
    --FIN BUG 0036286 - 11/08/2017 - CASL
    --
  ELSE
    SELECT SUM(itotimp)
    INTO iva_total
    FROM primasgaranseg
    WHERE sseguro = psseguro
    AND nriesgo   = psnriesgo;
  END IF;
  RETURN iva_total;
EXCEPTION
WHEN OTHERS THEN
  RETURN 0;
END f_obtener_iva_autos;
FUNCTION f_calculos_rea_totales(
    psproces IN NUMBER,
    pcampo   IN NUMBER,
    pcmoneda IN VARCHAR2,
    pcestado IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tconsulta     VARCHAR2(32000) := '';
    v_tlinia        VARCHAR2(3200)  := '';
    v_spagrea       NUMBER          := NULL;
    v_tiporeaseguro VARCHAR2(2)     := 'LP';
  BEGIN
    --Determinao si es un pago o un ingreso
    v_tiporeaseguro := pac_isqlfor_lcol.f_tipodoc_reaseguro(psproces);
    v_tconsulta     := ' SELECT SUM (totales) from(    ';
    IF pcampo        = 1 THEN
      v_tconsulta   := v_tconsulta
      --AGG 29/09/2014
      || ' select SUM(DECODE(mc.cconcep, 1, mc.iimport, 9, mc.iimport, 20, mc.iimport, 23, mc.iimport, 16, mc.iimport, 33, mc.iimport, 34, mc.iimport, 0)* DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'', DECODE(mc.cdebhab, 1, -1, 1), DECODE(mc.cdebhab, 1, 1, -1))) totales ';
    ELSIF pcampo   = 2 THEN
      v_tconsulta := --AGG 29/09/2014
      v_tconsulta || ' SELECT SUM(DECODE(mc.cconcep, 2, mc.iimport, 14, mc.iimport, 12, mc.iimport, 0)* DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'', DECODE(mc.cdebhab, 1, -1, 1), DECODE(mc.cdebhab, 1, 1, -1))) totales ';
    ELSIF pcampo   = 3 THEN
      v_tconsulta := --AGG 29/09/2014
      v_tconsulta || 'SELECT SUM(DECODE(mc.cconcep, 3, mc.iimport, 13,mc.iimport, 6,mc.iimport,35,mc.iimport,36,mc.iimport, 0)* DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'', DECODE(mc.cdebhab, 1, -1, 1), DECODE(mc.cdebhab, 1, 1, -1))) totales ';
    ELSIF pcampo   = 4 THEN
      v_tconsulta := --AGG 29/09/2014
      v_tconsulta || 'SELECT SUM(DECODE(mc.cconcep, 5, mc.iimport, 39, mc.iimport, 40, mc.iimport, 37, mc.iimport, 38, mc.iimport,0)* DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'', DECODE(mc.cdebhab, 1, -1, 1), DECODE(mc.cdebhab, 1, 1, -1))) totales ';
    ELSIF pcampo   = 5 THEN
      v_tconsulta := v_tconsulta || 'SELECT  SUM(DECODE(mc.cconcep, 4, mc.iimport, 0)* DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'', DECODE(mc.cdebhab, 1, -1, 1), DECODE(mc.cdebhab, 1, 1, -1))) totales ';
    ELSIF pcampo   = 6 THEN
      v_tconsulta := v_tconsulta || 'SELECT  SUM(DECODE(mc.cconcep, 7, mc.iimport, 45, mc.iimport, 0)* DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'', DECODE(mc.cdebhab, 1, -1, 1), DECODE(mc.cdebhab, 1, 1, -1))) totales '; --Inicio/Fin OJS QT57918 13/03/2020 Añyadimos concepto 45
    ELSIF pcampo   = 7 THEN
      v_tconsulta := --AGG 29/09/2014
      v_tconsulta || 'SELECT SUM(DECODE(mc.cconcep, 24, mc.iimport, 15, mc.iimport, 0)* DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'', DECODE(mc.cdebhab, 1, -1, 1), DECODE(mc.cdebhab, 1, 1, -1))) totales '; --Inicio/Fin OJS QT57918 13/03/2020 Añyadimos concepto 15
    ELSIF pcampo   = 8 THEN
      v_tconsulta := v_tconsulta || ' SELECT SUM(mc.iimport * DECODE(' || CHR(39) || v_tiporeaseguro || CHR(39) || ',''LP'', DECODE(mc.cdebhab, 1, -1, 1), DECODE(mc.cdebhab, 1, 1, -1))) totales ';
    END IF;
    v_tconsulta   := v_tconsulta || ' FROM  MOVCTATECNICA MC, codicontratos c,companias com,  tipoctarea a  ' || ' where mc.spagrea IN (SELECT SPAGREA FROM MOVCTATECNICA WHERE SPROCES =' || psproces || ' )' || ' and mc.cconcep in (1, 2, 3, 4, 5, 6, 7, 9, 12, 13, 14, 16, 20, 22, 23, 24, 33, 34, 35, 36, 37, 38, 39, 40, 45, 15) ' || ' and a.cconcep = mc.CCONCEP ' || ' and a.cempres = 12 ' || ' and a.cempres = mc.cempres ' || ' and a.ctipcta = 1 ' || ' and mc.scontra =  c.scontra and mc.ccompani =  com.ccompani ' || ' and c.cmoneda =' || CHR(39) || pcmoneda || CHR(39); --Inicio/Fin OJS QT57918 13/03/2020 Añyadimos conceptos 45 y 15
    IF pcestado   IS NOT NULL THEN
      v_tconsulta := v_tconsulta || ' and mc.cestado = ' || pcestado;
    END IF;
    v_tconsulta := v_tconsulta || ' GROUP BY mc.ccompapr, mc.cconcep,c.cmoneda) ';
    OPEN vr_cursor FOR v_tconsulta;
    FETCH vr_cursor INTO v_tlinia;
  RETURN v_tlinia;
EXCEPTION
WHEN OTHERS THEN
  RETURN '';
END;
FUNCTION f_tipodoc_reaseguro(
    psproces IN NUMBER)
  RETURN VARCHAR2
IS
  vtipodoc   VARCHAR2(200);
  vresultado NUMBER;
BEGIN
  --Solo se deben considerar los SALDOS, redondeamos a dos decimales
  SELECT f_round(NVL(SUM(DECODE(c.cmoneda, 'COP', iimport, iimport_moncon)), 0), 2)
  INTO vresultado
  FROM movctatecnica m,
    codicontratos c
  WHERE m.sproces = psproces
  AND m.scontra   = c.scontra
  AND cconcep     = 10;
  IF (vresultado  > 0) THEN
    vtipodoc     := 'LR';
  ELSE
    vtipodoc := 'LP';
  END IF;
  RETURN vtipodoc;
EXCEPTION
WHEN OTHERS THEN
  RETURN 'LR';
END;
FUNCTION f_total_reaseguro(
    psproces IN NUMBER,
    pcestado IN NUMBER DEFAULT NULL)
  RETURN NUMBER
IS
  v_resultado     NUMBER;
  v_tiporeaseguro VARCHAR2(2) := 'LP';
BEGIN
  --Determinao si es un pago o un ingreso
  --Solo debe considerar los SALDOS
  v_tiporeaseguro := pac_isqlfor_lcol.f_tipodoc_reaseguro(psproces);
  SELECT f_round(SUM(DECODE(c.cmoneda, 'COP', iimport, iimport_moncon) * DECODE(v_tiporeaseguro, 'LP', DECODE(cdebhab, 1, -1, 1), DECODE(cdebhab, 1, 1, -1))), 2)
  INTO v_resultado
  FROM movctatecnica m,
    codicontratos c
  WHERE m.sproces = psproces
  AND m.scontra   = c.scontra
  AND m.cestado   = NVL(pcestado, m.cestado)
  AND m.cconcep   = 10;
  RETURN v_resultado;
EXCEPTION
WHEN OTHERS THEN
  RETURN 0;
END;
FUNCTION f_observaciones_cta(
    psproces  IN NUMBER,
    pcidioma  IN NUMBER,
    pccompani IN NUMBER)
  RETURN CLOB
IS
  v_observaciones CLOB := NULL;
  v_ctramo NUMBER      := NULL;
BEGIN
  -- Las observaciones solo se muestran en el caso de contrato Facultativo y XL
  FOR i IN
  (SELECT 'RAMO:'
    || DECODE(mc.sproduc, 0, 'NO PROD',
    (SELECT ttitulo
    FROM titulopro tt,
      productos pp
    WHERE pp.cramo = tt.cramo
    AND pp.cmodali = tt.cmodali
    AND pp.ctipseg = tt.ctipseg
    AND pp.ccolect = tt.ccolect
    AND tt.cidioma = pcidioma
    AND pp.sproduc = mc.sproduc
    ))
    || '\par '
    || ' P?LIZA: '
    || pac_isqlfor_lcol.f_get_numpolizas_rea(psproces)
    || '\par'
    || ' ANEXO: '
    || NVL(mc.ncertif, 0)
    || '\par '
    || ' F.INICIO VIGENCIA: '
    || TO_CHAR(co.fconini, 'DD/MM/YYYY')
    || ' F.FIN VIGENCIA: '
    || TO_CHAR(co.fconfin, 'DD/MM/YYYY')
    || '\par '
    || ' SINIESTRO: '
    || pac_isqlfor_lcol.f_get_numsiniestros_rea(psproces)
    || '\par '
    || ' OBSERVACIONES: '
    || co.tcontra observaciones,
    mc.ctramo tramo
  FROM movctatecnica mc,
    contratos co,
    companias com,
    per_personas pp,
    codicontratos c
  WHERE mc.sproces = psproces
  AND spagrea     IN
    (SELECT spagrea FROM movctatecnica WHERE sproces = psproces
    )
  AND mc.ccompani = pccompani
  AND mc.scontra  = co.scontra
  AND mc.nversio  = co.nversio
  AND mc.ccompani = com.ccompani
  AND com.sperson = pp.sperson
  AND mc.scontra  = c.scontra
  AND mc.nversio  = co.nversio
  GROUP BY mc.sproces,
    mc.ccompani,
    mc.sproduc,
    mc.ncertif,
    co.fconini,
    co.fconfin,
    co.tcontra,
    mc.ctramo
  )
  LOOP
    IF (i.tramo NOT IN (1, 2, 3, 4)) THEN
      v_observaciones := v_observaciones || i.observaciones || '\par ';
    END IF;
  END LOOP;
  RETURN TO_CLOB(f_jrep_trad(v_observaciones));
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END;
FUNCTION f_get_numpolizas_rea(
    psproces IN NUMBER)
  RETURN VARCHAR2
IS
  v_polizas VARCHAR2(32000);
BEGIN
  FOR i IN
  (SELECT DISTINCT npoliza
    || '-'
    || ncertif numpoliza,
    npoliza npoliza
  FROM movctatecnica
  WHERE spagrea IN
    (SELECT spagrea FROM movctatecnica WHERE sproces = psproces
    )
  AND sproces = psproces
  )
  LOOP
    IF (i.npoliza IS NOT NULL) THEN
      v_polizas   := v_polizas || i.numpoliza || ',';
    END IF;
  END LOOP;
  IF (LENGTH(v_polizas) > 0) THEN
    v_polizas          := SUBSTR(v_polizas, 0, LENGTH(v_polizas) - 1);
  END IF;
  RETURN v_polizas;
EXCEPTION
WHEN OTHERS THEN
  RETURN '';
END;
FUNCTION f_get_numsiniestros_rea(
    psproces IN NUMBER)
  RETURN VARCHAR2
IS
  v_siniestro VARCHAR2(32000);
BEGIN
  FOR i IN
  (SELECT DISTINCT (nsinies) numsiniestro
  FROM movctatecnica
  WHERE spagrea IN
    (SELECT spagrea FROM movctatecnica WHERE sproces = psproces
    )
  AND sproces = psproces
  )
  LOOP
    IF (i.numsiniestro IS NOT NULL) THEN
      v_siniestro      := v_siniestro || i.numsiniestro || ',';
    END IF;
  END LOOP;
  IF (LENGTH(v_siniestro) > 0) THEN
    v_siniestro          := SUBSTR(v_siniestro, 0, LENGTH(v_siniestro) - 1);
  END IF;
  RETURN v_siniestro;
EXCEPTION
WHEN OTHERS THEN
  RETURN '';
END;
FUNCTION f_des_garpro(
    psseguro seguros.sseguro%TYPE,
    pnriesgo garanseg.nriesgo%TYPE,
    pidioma  IN NUMBER,
    pcgarant IN NUMBER,
    psproduc IN NUMBER DEFAULT NULL,
    ptabla   IN VARCHAR2 DEFAULT 'POL')
  RETURN VARCHAR2
IS
  v_tgarant  VARCHAR2(2000);
  v_numerror NUMBER;
  v_respuesta pregungaranseg.crespue%TYPE;
  v_sproces   NUMBER;
  v_resultado VARCHAR2(3200);
BEGIN
  SELECT tgarant
  INTO v_tgarant
  FROM garangen
  WHERE cidioma = pidioma
  AND cgarant   = pcgarant;
  IF (psproduc IS NOT NULL) THEN
    BEGIN
      SELECT tgarant
      INTO v_tgarant
      FROM garangenpro
      WHERE cidioma = pidioma
      AND cgarant   = pcgarant
      AND sproduc   = psproduc;
    EXCEPTION
    WHEN NO_DATA_FOUND THEN
      NULL;
    END;
  END IF;
  IF ((psproduc     IS NOT NULL) AND (pcgarant = 777)) THEN
    v_numerror      := pac_preguntas.f_get_pregungaranseg(psseguro, pcgarant, pnriesgo, 4921, ptabla, v_respuesta, v_sproces);
    IF (v_respuesta IS NOT NULL) THEN
      SELECT trespue
      INTO v_resultado
      FROM respuestas
      WHERE cpregun = 4921
      AND cidioma   = pidioma
      AND crespue   = v_respuesta;
      v_tgarant    := v_tgarant || ' ' || v_resultado;
    END IF;
  END IF;
  RETURN v_tgarant;
EXCEPTION
WHEN NO_DATA_FOUND THEN
  RETURN v_tgarant;
END;
/*****************************************************************
Bug 24572-XVM-30/11/2012
FUNCTION f_garantias_certif
Devuelve todas las garantÃ¿Â­as de todos los certificados N
param IN psseguro  : codigo de seguro
param IN pcidioma  : codigo de idioma
return             : texto con las garantÃ¿Â­as
******************************************************************/
FUNCTION f_garantias_certif_rec(
    psseguro IN NUMBER,
    pcidioma IN NUMBER DEFAULT 1,
    pdummy   IN NUMBER DEFAULT 0,
    pnrecibo IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(2000);
    v_tlinia    VARCHAR2(200);
    v_norden garanpro.norden%TYPE;
    v_tpargar   VARCHAR2(200);
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    --
    vfmovdia DATE;
    --
  BEGIN
    SELECT MAX(fmovdia)
    INTO vfmovdia
    FROM recibos r,
      movrecibo m
    WHERE sseguro = psseguro
    AND r.nrecibo = m.nrecibo
    AND cestrec   = 0
    AND cestant   = 0
    AND r.nrecibo = pnrecibo;
  v_tablaseg     := 'seguros';
  v_tconsulta    := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
  EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
  IN psseguro;
  IF v_act0      = 1 THEN
    v_actividad := '0';
  ELSE
    v_actividad := 'se.cactivi';
  END IF;
  v_tconsulta := 'SELECT p.norden, REPLACE(pac_isqlfor_lcol.f_des_garpro(se.sseguro,s.nriesgo,' || NVL(pcidioma, 2) || ',p.cgarant,se.sproduc,''POL''), CHR(39), CHR(39) || CHR(39)) a';
  v_tconsulta := v_tconsulta || ' FROM garangen g, garanpro p, ';
  v_tconsulta := v_tconsulta || 'garanseg s, seguros se';
  v_tconsulta := v_tconsulta || ' WHERE g.cgarant = s.cgarant';
  v_tconsulta := v_tconsulta || ' AND p.cgarant = s.cgarant';
  v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
  v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
  v_tconsulta := v_tconsulta || ' AND se.ncertif <> 0';
  v_tconsulta := v_tconsulta || ' AND p.CACTIVI = ' || v_actividad;
  v_tconsulta := v_tconsulta || ' AND se.csituac in (0,7,5,2)';
  v_tconsulta := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM movseguro ';
  v_tconsulta := v_tconsulta || ' WHERE sseguro = s.sseguro and femisio <= to_date(''' || TO_CHAR(vfmovdia, 'ddmmyyyy hh24MISS') || ''',''ddmmyyyy hh24MISS''))';
  v_tconsulta := v_tconsulta || ' AND s.sseguro IN (SELECT sseguro FROM seguros';
  v_tconsulta := v_tconsulta || ' WHERE npoliza = (SELECT npoliza FROM seguros WHERE sseguro=  ' || psseguro || '))';
  v_tconsulta := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
  SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
    || sproduc
    || ', '
    || cactivi
    || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
  INTO v_tpargar
  FROM
    (SELECT seg.sproduc,
      seg.cactivi
    FROM seguros seg
    WHERE seg.sseguro = psseguro
    );
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' GROUP BY REPLACE(pac_isqlfor_lcol.f_des_garpro(se.sseguro,s.nriesgo,' || NVL(pcidioma, 2) || ',p.cgarant,se.sproduc,''POL''), CHR(39), CHR(39) || CHR(39)),p.norden';
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_norden, v_tlinia;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF pdummy = 1 THEN
      --Necesitamos llenar con "intros" columnas vacÃ¿Â­as para que el nÃ¿Âºmero de filas
      --concuerde con el nÃ¿Âºmero de amparos que si se muestran
      --La libreria de LibertyReportes.jar necesita recibir todos los parÃ¿Â¡metros
      --con las mismas lineas, sino da error, para evitar eso creamos esta cadena vacÃ¿Â­a con intros
      v_tresult := v_tresult || ' ' || '\par ';
    ELSE
      v_tresult := v_tresult || v_tlinia || '\par ';
    END IF;
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_garantias_certif_rec;
/*****************************************************************
Bug 24572-XVM-30/11/2012
FUNCTION f_importes_certif
Devuelve los capitales de todos los certificados diferentes a 0
param IN psseguro  : codigo de seguro padre
param IN pcampo    : 1 Valor Asegurado / 2 Prima amparo
return             : texto importes
Bug 19927 - 28/11/2011 - JTS
******************************************************************/
FUNCTION f_importes_certif_rec(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnrecibo IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(4000);
    v1          NUMBER;
    v2          NUMBER;
    v_tlinia    VARCHAR2(50);
    v_tpargar   VARCHAR2(200);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot garanseg.ipritot%TYPE;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    --
    vfmovdia DATE;
    --
  BEGIN
    SELECT MAX(fmovdia)
    INTO vfmovdia
    FROM recibos r,
      movrecibo m
    WHERE sseguro = psseguro
    AND r.nrecibo = m.nrecibo
    AND cestrec   = 0
    AND cestant   = 0
    AND r.nrecibo = pnrecibo;
  v_actividad    := 'se.cactivi';
  v_tconsulta    := 'SELECT s.cgarant, p.norden, sum(decode(s.cgarant,48,se.cforpag,1)*icaptot) a,sum(ipritot)';
  v_tconsulta    := v_tconsulta || ' FROM garanpro p, productos pp, ';
  v_tconsulta    := v_tconsulta || ' garanseg s, seguros se';
  v_tconsulta    := v_tconsulta || ' WHERE p.cgarant = s.cgarant';
  v_tconsulta    := v_tconsulta || ' AND p.sproduc = se.sproduc';
  v_tconsulta    := v_tconsulta || ' AND s.sseguro = se.sseguro';
  v_tconsulta    := v_tconsulta || ' AND p.sproduc = pp.sproduc';
  v_tconsulta    := v_tconsulta || ' AND se.csituac in (0,7,5,2)';
  v_tconsulta    := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
  v_tconsulta    := v_tconsulta || ' AND s.sseguro IN (SELECT sseguro FROM seguros';
  v_tconsulta    := v_tconsulta || ' WHERE npoliza = (SELECT npoliza FROM seguros WHERE sseguro=  ' || psseguro || ')and ncertif <> 0)';
  v_tconsulta    := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM movseguro ';
  v_tconsulta    := v_tconsulta || ' WHERE sseguro = s.sseguro and femisio <= to_date(''' || TO_CHAR(vfmovdia, 'ddmmyyyy hh24MISS') || ''',''ddmmyyyy hh24MISS''))';
  -- INI 0039502 - MAV 23/11/2017
  -- La consulta debe usar p.cgarant
  SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
    || sproduc
    || ', '
    || cactivi
    || ', p.cgarant, ''GARANT_IMP''), 0) = 1 )'
  INTO v_tpargar
  FROM
    (SELECT seg.sproduc,
      seg.cactivi
    FROM seguros seg
    WHERE seg.sseguro = psseguro
    );
  /*
  SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
  || sproduc
  || ', '
  || cactivi
  || ', s.cgarant, ''GARANT_IMP''), 0) = 1 )'
  INTO v_tpargar
  FROM
  (SELECT seg.sproduc,
  seg.cactivi
  FROM seguros seg
  WHERE seg.sseguro = psseguro
  );
  */
  -- FIN 0039502 - MAV 23/11/2017
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || 'GROUP BY s.cgarant,p.norden ORDER BY p.norden';
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v1, v2, v_icaptot, v_ipritot;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    v_tlinia   := pac_isqlfor_lcol.f_imporignomon(psseguro, v_icaptot);
    IF pcampo   = 2 THEN
      v_tlinia := pac_isqlfor_lcol.f_imporignomon(psseguro, v_ipritot);
    END IF;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_certif_rec;
/*****************************************************************
Bug 25583-FAL-30/01/2013
FUNCTION f_importes_certif_gar
Devuelve los capitales de todos los certificados diferentes a 0 de una garantia concreta
param IN psseguro  : codigo de seguro padre
param IN pcampo    : 1 Valor Asegurado / 2 Prima amparo
param IN pcgarant  : cÃ¿Â³digo garantia
return             : texto importes
******************************************************************/
FUNCTION f_importes_certif_gar_rec(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pcgarant IN NUMBER,
    pnrecibo IN NUMBER DEFAULT NULL,
    ptablas  IN VARCHAR2 DEFAULT 'POL', --BUG 47494 MPC 08/03/2019 Se adicion parametro.
    psproces IN NUMBER DEFAULT NULL)    --BUG 47494 MPC 08/03/2019 Se adicion parametro.
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult     VARCHAR2(32000) := '';
    v_tconsulta   VARCHAR2(4000);
    v_tconsulta_1 VARCHAR2(4000) := ''; --BUG 47494 08/03/2019 MPC Se crea variable
    v1            NUMBER;
    v2            NUMBER;
    v_tlinia      VARCHAR2(50);
    v_tpargar     VARCHAR2(200);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot garanseg.ipritot%TYPE;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    --
    vfmovdia DATE;
    --
  BEGIN
    SELECT MAX(fmovdia)
    INTO vfmovdia
    FROM recibos r,
      movrecibo m
    WHERE sseguro = psseguro
    AND r.nrecibo = m.nrecibo
    AND cestrec   = 0
    AND cestant   = 0
    AND r.nrecibo = pnrecibo;
  v_actividad    := 'se.cactivi';
  v_tconsulta    := 'SELECT s.cgarant, p.norden, sum(decode(s.cgarant,48,se.cforpag,1)*icaptot) a,sum(ipritot)';
  v_tconsulta    := v_tconsulta || ' FROM garanpro p, productos pp, ';
  --INI BUG 47494 MPC 08/03/2019 Se crea condicion.
  IF NVL(ptablas,'POL') = 'CAR' THEN
    --
    v_tconsulta   := v_tconsulta || ' garancar s, seguros se';
    v_tconsulta_1 := ' AND s.sproces = '||psproces;
    --
  ELSE
    --
    v_tconsulta_1 := v_tconsulta_1 || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM movseguro ';
    v_tconsulta_1 := v_tconsulta_1 || ' WHERE sseguro = s.sseguro and femisio <= to_date(''' || TO_CHAR(vfmovdia, 'ddmmyyyy hh24MISS') || ''',''ddmmyyyy hh24MISS''))';
    --
    --FIN BUG 47494 MPC 08/03/2019 Se crea condicion.
    v_tconsulta := v_tconsulta || ' garanseg s, seguros se';
  END IF; --BUG 47494 MPC 08/03/2019 Se crea condicion.
  v_tconsulta := v_tconsulta || ' WHERE p.cgarant = s.cgarant';
  v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
  v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
  v_tconsulta := v_tconsulta || ' AND p.sproduc = pp.sproduc';
  v_tconsulta := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
  v_tconsulta := v_tconsulta || ' AND se.csituac in (0,7,5,2)';
  v_tconsulta := v_tconsulta || ' AND s.sseguro IN (SELECT sseguro FROM seguros';
  v_tconsulta := v_tconsulta || ' WHERE npoliza = (SELECT npoliza FROM seguros WHERE sseguro=  ' || psseguro || ')and ncertif <> 0)';
  --INI BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
  v_tconsulta := v_tconsulta || v_tconsulta_1;
  --v_tconsulta    := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM movseguro ';
  --v_tconsulta    := v_tconsulta || ' WHERE sseguro = s.sseguro and femisio <= to_date(''' || TO_CHAR(vfmovdia, 'ddmmyyyy hh24MISS') || ''',''ddmmyyyy hh24MISS''))';
  --FIN BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
  -- INI 0039502 - MAV 23/11/2017
  -- La consulta debe usar p.cgarant
  SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
    || sproduc
    || ', '
    || cactivi
    || ', p.cgarant, ''GARANT_IMP''), 0) = 1 )'
  INTO v_tpargar
  FROM
    (SELECT seg.sproduc,
      seg.cactivi
    FROM seguros seg
    WHERE seg.sseguro = psseguro
    );
  /*
  SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
  || sproduc
  || ', '
  || cactivi
  || ', s.cgarant, ''GARANT_IMP''), 0) = 1 )'
  INTO v_tpargar
  FROM
  (SELECT seg.sproduc,
  seg.cactivi
  FROM seguros seg
  WHERE seg.sseguro = psseguro
  );
  */
  -- FIN 0039502 - MAV 23/11/2017
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || 'GROUP BY s.cgarant,p.norden ORDER BY p.norden';
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v1, v2, v_icaptot, v_ipritot;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    v_tlinia   := pac_isqlfor_lcol.f_imporignomon(psseguro, v_icaptot);
    IF pcampo   = 2 THEN
      v_tlinia := pac_isqlfor_lcol.f_imporignomon(psseguro, v_ipritot);
    END IF;
    IF v1      <> pcgarant AND v_ipritot = 0 THEN
      v_tlinia := ' ';
    END IF;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_certif_gar_rec;
FUNCTION f_es_migracion(
    psseguro IN NUMBER)
  RETURN NUMBER
IS
  v_num_err NUMBER;
  vsalida   NUMBER;
  vfefecto  DATE;
  vnmovimi  NUMBER;
BEGIN
  v_num_err := pac_seguros.f_es_migracion(psseguro, 'POL', vsalida);
  IF vsalida = 1 THEN
    SELECT fefecto INTO vfefecto FROM seguros WHERE sseguro = psseguro;
    SELECT MAX(nmovimi) INTO vnmovimi FROM movseguro WHERE sseguro = psseguro;
    IF f_vigente(psseguro, NULL, vfefecto) != 0 AND vnmovimi = 1 THEN
      RETURN 1;
    ELSE
      RETURN 0;
    END IF;
  END IF;
  RETURN vsalida;
EXCEPTION
WHEN OTHERS THEN
  RETURN 0;
END f_es_migracion;
-- 30842#c172517 - 14/04/2014
FUNCTION f_get_fecha_min(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER)
  RETURN DATE
IS
  --
  vfefecto    DATE;
  v_sseguro_0 NUMBER;
  v_nmovimi_0 NUMBER;
  --
BEGIN
  SELECT MIN(fefecto)
  INTO vfefecto
  FROM movseguro
  WHERE (sseguro, nmovimi) IN
    (SELECT sseguro_cert,
      nmovimi_cert
    FROM detmovsegurocol
    WHERE sseguro_0 = psseguro
    AND nmovimi_0   = pnmovimi
    );
  RETURN vfefecto;
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_get_fecha_min;
--32009#c189324
FUNCTION f_dias_vigencia(
    psseguro NUMBER,
    pfcaranu IN DATE,
    pfefecto IN DATE)
  RETURN NUMBER
IS
  vdd      VARCHAR2(2);
  vfcaranu DATE;
  vnrenova NUMBER;
  vdias    NUMBER;
BEGIN
  IF pfcaranu IS NULL THEN
    SELECT nrenova INTO vnrenova FROM seguros WHERE sseguro = psseguro;
    vdd      := SUBSTR(LPAD(vnrenova, 4, 0), 3, 2);
    vfcaranu := f_summeses(pfefecto, 12, vdd);
  END IF;
  vdias := NVL(pfcaranu, vfcaranu) - pfefecto;
  RETURN vdias;
END f_dias_vigencia;
-- INI BUG 0016162 - RMGA - 24/03/2015  Desarrollo funcion fu_totalprimamap para el MAP 765
-- INI BUG 0018708 - JRNC - 08/09/2015  ModificaciÃ¿Â³n de la funcion fu_totalprimamap para el MAP 765
/*****************************************************************
FUNCTION fu_totalprimamap
Devuelve los planes de una p?liza
param IN psseguro  : codigo de seguro
return             : Valor de la prima calculada para el map
******************************************************************/
FUNCTION fu_totalprimamap(
    v_sseguro IN NUMBER,
    v_linea   IN VARCHAR2,
    v_cmap    IN VARCHAR2)
  RETURN NUMBER
IS
  iprivigencia NUMBER;
  vxpro_np_360 NUMBER;
  vdifdias     NUMBER;
  vnum_err     NUMBER;
  v_ini        DATE;
  v_fin        DATE;
  v_itotalr    NUMBER;
  v_igasexpe   NUMBER;
  v_ivagasex   NUMBER;
  v_ivaprima   NUMBER;
  v_itotalge   NUMBER;
  v_csituac    NUMBER;
  v_fecperiodo VARCHAR2(7);
BEGIN
  SELECT s.csituac,
    s.fefecto,
    s.frenova,
    s.iprianu
  INTO v_csituac,
    v_ini,
    v_fin,
    v_itotalr
  FROM seguros s
  WHERE s.sseguro = v_sseguro;
  IF v_csituac   <> 2 THEN
    SELECT crespue
    INTO v_igasexpe
    FROM pregunpolseg
    WHERE cpregun = 4095
    AND sseguro   = v_sseguro
    AND nmovimi   =
      (SELECT MIN(pps.nmovimi)
      FROM pregunpolseg pps
      WHERE pps.cpregun = 4095
      AND pps.sseguro   = v_sseguro
      );
    vxpro_np_360           := f_parinstalacion_n('PRO_NP_360');
    IF NVL(vxpro_np_360, 1) = 1 THEN
      vnum_err             := f_difdata(v_ini, v_fin, 3, 3, vdifdias);
      iprivigencia         := (vdifdias * v_itotalr) / 360;
    ELSE
      vnum_err     := f_difdata(v_ini, v_fin, 1, 3, vdifdias);
      iprivigencia := (vdifdias * v_itotalr) / 365;
    END IF;
    iprivigencia := f_round(iprivigencia, 8);
    v_ivagasex   := (v_igasexpe   * 16) / 100;
    v_ivaprima   := (iprivigencia * 16) / 100;
    iprivigencia := iprivigencia  + v_ivaprima + v_igasexpe + v_ivagasex;
  ELSE
    v_fecperiodo := pac_map.f_valor_parametro('|', v_linea, 3, v_cmap) || '/' || pac_map.f_valor_parametro('|', v_linea, 4, v_cmap);
    SELECT NVL( SUM(
      CASE
        WHEN b.ctiprec IN (8, 9, 15)
        THEN a.itotalr  * -1
        ELSE a.itotalr
      END), 0)
    INTO iprivigencia
    FROM vdetrecibos a,
      recibos b,
      movrecibo c
    WHERE a.nrecibo = b.nrecibo
    AND c.nrecibo   = b.nrecibo
    AND b.sseguro   = v_sseguro
    AND c.smovrec   =
      (SELECT MIN(smovrec) FROM movrecibo mr2 WHERE mr2.nrecibo = b.nrecibo
      )
    AND b.ctiprec NOT                    IN (13, 15)
    AND c.cestrec                        <> 2
    AND TO_DATE(v_fecperiodo, 'mm/yyyy') >=
      (SELECT
        CASE
          WHEN pgp.crespue = 1
          THEN
            CASE
              WHEN TRUNC(b.fvencim) <= NVL(TRUNC(c.fcontab), TRUNC(SYSDATE))
              THEN TO_DATE(TO_CHAR(NVL(c.fcontab, SYSDATE), 'MM/YYYY'), 'MM/YYYY')
              ELSE TO_DATE(TO_CHAR(b.fvencim, 'MM/YYYY'), 'MM/YYYY')
            END
          ELSE
            CASE
              WHEN TRUNC(b.fefecto) <= NVL(TRUNC(c.fcontab), TRUNC(SYSDATE))
              THEN TO_DATE(TO_CHAR(NVL(c.fcontab, SYSDATE), 'MM/YYYY'), 'MM/YYYY')
              ELSE TO_DATE(TO_CHAR(b.fefecto, 'MM/YYYY'), 'MM/YYYY')
            END
        END
      FROM pregunpolseg pgp
      WHERE pgp.sseguro = v_sseguro
      AND pgp.nmovimi   = 1
      AND pgp.cpregun   = 4084
      );
  END IF;
  RETURN ROUND(iprivigencia);
EXCEPTION
WHEN OTHERS THEN
  RETURN 0;
END fu_totalprimamap;
-- Fin BUG 0018708 - JRNC - 08/09/2015  ModificaciÃ¿Â³n de la funcion fu_totalprimamap para el MAP 765
-- FIN BUG 0016162 - RMGA - 24/03/2015 Desarrollo funcion fu_totalprimamap para el MAP 765
-- Bug 33863/195850 - 02/02/2015 - ETM--LCOL0040_BBVA.jrml--INI
FUNCTION f_garanmodalidad(
    psseguro    IN NUMBER,
    pnriesgo    IN NUMBER DEFAULT 1,
    pcidioma    IN NUMBER DEFAULT 1,
    pmodo       IN VARCHAR2 DEFAULT 'POL',
    pnmovimi    IN NUMBER DEFAULT NULL,
    pcmodalidad IN NUMBER)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(2000);
    v_tlinia    VARCHAR2(200);
    v_tpargar   VARCHAR2(200);
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
  BEGIN
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    v_tconsulta         := 'select decode(gm.CMODALIDAD,' || pcmodalidad || ',''X'','' '') ';
    v_tconsulta         := v_tconsulta || ' FROM garanpro p, garanpromodalidad gm, ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || 'estgaranseg s, estseguros se';
      v_csituac         := '(0,7,5,2,4)';
    ELSE
      v_tconsulta                                 := v_tconsulta || 'garanseg s, seguros se';
      IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
        v_csituac                                 := '(0,7,5,2)';
      ELSE
        v_csituac := '(0,7,5,2,4)';
      END IF;
    END IF;
    v_tconsulta         := v_tconsulta || ' WHERE p.cgarant = s.cgarant';
    v_tconsulta         := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta         := v_tconsulta || ' AND p.CACTIVI = ' || v_actividad;
    v_tconsulta         := v_tconsulta || ' AND se.csituac in ' || v_csituac;
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    v_tconsulta         := v_tconsulta || ' AND p.cgarant = gm.cgarant(+)';
    v_tconsulta         := v_tconsulta || ' AND p.CACTIVI = gm.CACTIVI(+)';
    v_tconsulta         := v_tconsulta || ' AND p.ccolect = gm.ccolect(+)';
    v_tconsulta         := v_tconsulta || ' AND p.ctipseg = gm.ctipseg(+)';
    v_tconsulta         := v_tconsulta || ' AND p.cmodali = gm.cmodali(+)';
    v_tconsulta         := v_tconsulta || ' AND p.cramo = gm.cramo(+)';
    v_tconsulta         := v_tconsulta || ' AND ' || pcmodalidad || ' = gm.cmodalidad(+)';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' AND s.cobliga = 1 and s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg WHERE sseguro =' || psseguro;
      IF (pnmovimi      IS NOT NULL) THEN
        v_tconsulta     := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
        v_tconsulta := v_tconsulta || ')';
      END IF;
      SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
        || sproduc
        || ', '
        || cactivi
        || ', p.cgarant, ''GARANT_IMP''), 0) = 1 )'
      INTO v_tpargar
      FROM
        (SELECT seg.sproduc,
          seg.cactivi
        FROM estseguros seg
        WHERE seg.sseguro = psseguro
        );
  ELSE
    v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro;
    IF (pnmovimi  IS NOT NULL) THEN
      v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
    ELSE
      v_tconsulta := v_tconsulta || ')';
    END IF;
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', p.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  END IF;
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_tlinia;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_garanmodalidad;
FUNCTION f_num_cotiz(
    psinterf    IN NUMBER,
    psproduc    IN NUMBER,
    pcmodalidad IN NUMBER)
  RETURN NUMBER
IS
  v_ncotizacion NUMBER;
BEGIN
  IF psinterf IS NOT NULL THEN
    BEGIN
      SELECT MAX(nsimulacion)
      INTO v_ncotizacion
      FROM estsimulacionlin_ws
      WHERE sinterf  = psinterf
      AND sproduc    = psproduc
      AND cmodalidad = pcmodalidad;
    EXCEPTION
    WHEN NO_DATA_FOUND THEN
      v_ncotizacion := 0;
    END;
  END IF;
  RETURN NVL(v_ncotizacion, 0);
EXCEPTION
WHEN OTHERS THEN
  RETURN 0;
END f_num_cotiz;
/*****************************************************************
FUNCTION f_calcula_cotiz
Devuelve los importes de una cotizacion
param IN psinterf  : codigo de interficie
param IN pncotizacion    : numero de simualcion
param IN pnriesgo  : riesgo
ptipo in number   :  1-->Valor a pagar , 2-->iva , 3-->total a pagar
return             : texto importes
******************************************************************/
FUNCTION f_calcula_cotiz(
    psinterf     IN NUMBER,
    pncotizacion IN NUMBER,
    pnriesgo     IN NUMBER DEFAULT 1,
    ptipo        IN NUMBER)
  RETURN VARCHAR2
IS
  v_tresult     VARCHAR2(250);
  v_imp         NUMBER;
  v_prima_anual VARCHAR2(250);
  v_primens     NUMBER;
  -- pnriesgo es el ea.nriesgo
  ncot1_total VARCHAR2(250);
  ncot1_vpagm VARCHAR2(250);
  ncot1_iva   VARCHAR2(250);
  v_gastexp   NUMBER;
BEGIN
  IF pncotizacion <> 0 THEN
    v_imp         := f_prima_forpag('EST', 2, 1, pncotizacion, NULL, NULL, NULL, NULL, 1);
    v_prima_anual := pac_isqlfor_lcol.f_imporigenomon(pncotizacion, v_imp);
    -- v_primens:= pac_isqlfor_lcol.f_imporigenomon(v_ncotizacion,0) ;
    --VALOR A PAGAR
    ncot1_vpagm := v_prima_anual;
    --IVA
    ncot1_iva := pac_isqlfor_lcol.f_imporigenomon(pncotizacion, pac_isqlfor_lcol.f_obtener_iva_autos(pncotizacion, pnriesgo));
    -- v_gastexp := pac_isqlfor_lcol.f_gastexp(pncotizacion);
    BEGIN
      SELECT SUM(icderreg)
      INTO v_gastexp
      FROM estprimasgaranseg
      WHERE sseguro = pncotizacion;
    EXCEPTION
    WHEN OTHERS THEN
      v_gastexp := 0;
    END;
    --TOTAL
    -- ncot1_total:=  pac_isqlfor_lcol.f_impcopenomon(v_ncotizacion,  NVL(v_gastexp, 0));
    ncot1_total := pac_isqlfor_lcol.f_impcopenomon(pncotizacion, v_imp + NVL(v_gastexp, 0) + NVL(pac_isqlfor_lcol.f_obtener_iva_autos(pncotizacion, pnriesgo), 0));
    IF ptipo     = 1 THEN --valor a pagar
      v_tresult := ncot1_vpagm;
    ELSIF ptipo  = 2 THEN --iva
      v_tresult := ncot1_iva;
    ELSIF ptipo  = 3 THEN --total
      v_tresult := ncot1_total;
    END IF;
  END IF;
  RETURN v_tresult;
EXCEPTION
WHEN OTHERS THEN
  RETURN '';
END f_calcula_cotiz;
FUNCTION f_aut_desmodalidad(
    psseguro IN NUMBER,
    pcramo   IN NUMBER,
    pnriesgo IN NUMBER,
    pnmovimi IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 8,
    pmodo    IN VARCHAR2 DEFAULT 'POL')
  RETURN VARCHAR2
IS
  v_tresult VARCHAR2(250);
  v_cmodali seguros.cmodali%TYPE;
  v_cramo seguros.cramo%TYPE;
  v_ctipseg seguros.ctipseg%TYPE;
  v_ccolect seguros.ccolect%TYPE;
  v_cactivi seguros.cactivi%TYPE;
  v_modalidad riesgos.cmodalidad%TYPE;
BEGIN
  IF NVL(pmodo, 'POL') = 'EST' THEN
    SELECT s.cmodali,
      s.cramo,
      s.ctipseg,
      s.ccolect,
      s.cactivi,
      r.cmodalidad
    INTO v_cmodali,
      v_cramo,
      v_ctipseg,
      v_ccolect,
      v_cactivi,
      v_modalidad
    FROM estseguros s,
      estautriesgos r
    WHERE s.sseguro = psseguro
    AND s.cramo     = pcramo
    AND s.sseguro   = r.sseguro
    AND r.nriesgo   = NVL(pnriesgo, 1)
    AND r.nmovimi   = pnmovimi;
  ELSE
    SELECT s.cmodali,
      s.cramo,
      s.ctipseg,
      s.ccolect,
      s.cactivi,
      r.cmodalidad
    INTO v_cmodali,
      v_cramo,
      v_ctipseg,
      v_ccolect,
      v_cactivi,
      v_modalidad
    FROM seguros s,
      autriesgos r
    WHERE s.sseguro = psseguro
    AND s.cramo     = pcramo
    AND s.sseguro   = r.sseguro
    AND r.nriesgo   = NVL(pnriesgo, 1)
    AND r.nmovimi   = pnmovimi;
  END IF;
  BEGIN
    SELECT MAX(aut.tmodalidad)
    INTO v_tresult
    FROM garanpromodalidad gm,
      aut_desmodalidad aut
    WHERE gm.cramo     = v_cramo
    AND gm.cactivi     = v_cactivi
    AND gm.cmodali     = v_cmodali
    AND gm.ccolect     = v_ccolect
    AND gm.ctipseg     = v_ctipseg
    AND gm.cmodalidad  = aut.cmodalidad
    AND aut.cidioma    = NVL(pcidioma, 8)
    AND aut.cmodalidad = v_modalidad;
  EXCEPTION
  WHEN OTHERS THEN
    v_tresult := '';
  END;
  RETURN v_tresult;
EXCEPTION
WHEN OTHERS THEN
  RETURN '';
END f_aut_desmodalidad;
