/*****************************************************************
FUNCTION f_garantias_riesgo_car
Devuelve las garant?as de un riesgo
param IN psseguro  : codigo de seguro
param IN psproces  : codigo del proceso
param IN pnriesgo  : n?mero de riesgo
param IN pcidioma  : codigo de idioma
param IN pmodo     : modo EST/POL
return             : texto con las garant?as del riesgo
Bug 35052/201442 - 30/03/2015
******************************************************************/
FUNCTION f_garantias_riesgo_car(
    psseguro IN NUMBER,
    psproces IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 2,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(2000);
    v_tlinia    VARCHAR2(200);
    v_tpargar   VARCHAR2(200);
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
    v_es_admin  NUMBER;
    vumerr      NUMBER;
  BEGIN
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    v_tconsulta                                 := 'SELECT REPLACE(pac_isqlfor_lcol.f_des_garpro(se.sseguro,s.nriesgo,' || NVL(pcidioma, 2) || ',p.cgarant,se.sproduc,''' || pmodo || '''), CHR(39), CHR(39) || CHR(39)) a';
    v_tconsulta                                 := v_tconsulta || ' FROM garanpro p, ';
    v_tconsulta                                 := v_tconsulta || 'garancar s, seguros se';
    IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
      v_csituac                                 := '(0,7,5,2)';
    ELSE
      v_csituac := '(0,7,5,2,4)';
    END IF;
    v_tconsulta := v_tconsulta || ' WHERE p.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta := v_tconsulta || ' AND p.CACTIVI = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' AND se.csituac in ' || v_csituac;
    v_tconsulta := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    v_tconsulta := v_tconsulta || ' AND s.sproces = ' || psproces;
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', p.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  vumerr      := pac_log.f_log_consultas(v_tconsulta, 'pac_isqlfor_lcol.f_garantias_riesgo_car', 1);
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_tlinia;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_garantias_riesgo_car;
/*****************************************************************
FUNCTION f_capitales_riesgo_car
Devuelve los capitales de un riesgo
param IN psseguro  : codigo de seguro
param IN psproces  : codigo del proceso
param IN pnriesgo  : n?mero de riesgo
param IN pmodo     : modo EST/POL
return             : texto con los capitales del riesgo
Bug 35052/201442 - 30/03/2015
******************************************************************/
FUNCTION f_importes_riesgo_car(
    psseguro IN NUMBER,
    psproces IN NUMBER,
    pcampo   IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 2,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(4000);
    v_tlinia    VARCHAR2(50);
    v_tpargar   VARCHAR2(200);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot VARCHAR2(200);
    v_ctipcap garanpro.ctipcap%TYPE;
    v_cimpres garanpro.cimpres%TYPE;
    v_npargar   NUMBER := 0;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
    nerror      NUMBER;
    v_trespuegar varchar2(100) :=null; --INI/FIN JMG 26/07/2024 I4PPE-2
	  v_cgarant   NUMBER; --INI/FIN JMG 26/07/2024 I4PPE-2
    vsproduc    NUMBER;  --INI/FIN JMG 26/07/2024 I4PPE-2
    --INI JMC 05/08/2024 AITSSD-19067
    v_preglimite NUMBER;
    --FIN JMC 05/08/2024 AITSSD-19067
  BEGIN
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    --INI JMG 26/07/2024 I4PPE-2
	--INI JMC 05/08/2024 AITSSD-19067
    --v_tconsulta                                 := 'SELECT pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot) d , g.cgarant ';
	v_tconsulta                                 := 'SELECT pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot) d , g.cgarant , nvl( pac_parametros.f_pargaranpro_n( p.sproduc,  p.cactivi, g.cgarant, ''PREGUNTA_LIMITE'' ), 0) limite  ';
	--FIN JMC 05/08/2024 AITSSD-19067
    --FIN JMG 26/07/2024 I4PPE-2
    v_tconsulta                                 := v_tconsulta || ' FROM  garangen g, garanpro p, productos pp, ';
    v_tconsulta                                 := v_tconsulta || ' garancar s, seguros se';
    IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
      v_csituac                                 := '(0,7,5,2)';
    ELSE
      v_csituac := '(0,7,5,2,4)';
    END IF;
    v_tconsulta := v_tconsulta || ' WHERE g.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = pp.sproduc';
    v_tconsulta := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' AND se.csituac in ' || v_csituac;
    v_tconsulta := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
    v_tconsulta := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    v_tconsulta := v_tconsulta || ' AND s.sproces = ' || psproces;
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  nerror      := pac_log.f_log_consultas(v_tconsulta, 'pac_isqlfor_lcol.f_importes_riesgo_car', 1);
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor
    INTO v_tlinia,
      v_icaptot,
      v_ctipcap,
      v_cimpres,
      v_npargar,
      v_ipritot , --INI/FIN JMG 26/07/2024 I4PPE-2
	  --INI JMC 05/08/2024 AITSSD-19067
       --v_cgarant; --INI/FIN JMG 26/07/2024 I4PPE-2
	   v_cgarant,
	  v_preglimite;
      --FIN JMC 26/06/2024 AITSSD-19067
    EXIT
  WHEN vr_cursor%NOTFOUND;
  	--INICIO JMG 26/07/2024 I4PPE-2 - Asistencia diferenciada-PDF
    IF v_npargar = 1 AND v_icaptot = 0 THEN

          BEGIN
            --
            SELECT sproduc INTO vsproduc FROM seguros WHERE sseguro = psseguro;
            --
          EXCEPTION
          WHEN OTHERS THEN
            --
            --
            SELECT sproduc INTO vsproduc FROM estseguros WHERE sseguro = psseguro;
            --
            --
          END;

          v_trespuegar := NULL;
        IF v_cgarant = 768 THEN
            IF vsproduc = 900753 THEN
              v_trespuegar := f_amparo_pregdesc(vsproduc,psseguro,v_cgarant,9240,pmodo);
            ELSE
              v_trespuegar := f_amparo_pregdesc(vsproduc,psseguro,v_cgarant,4922,pmodo);
            END IF;
        END IF;

      IF v_trespuegar IS NOT NULL THEN
        v_tlinia := v_trespuegar;
      ELSE
          SELECT tatribu
          INTO v_tlinia
          FROM detvalores
          WHERE cvalor = 126
          AND catribu  = NVL(v_cimpres, 59)
          AND cidioma  = NVL(pcidioma, 8);
        END IF;
    END IF;
    	--FIN JMG 26/06/2024 I4PPE-2 - Asistencia diferenciada-PDF
    IF pcampo   = 2 THEN
      v_tlinia := v_ipritot;
    --INI JMC 05/08/2024 AITSSD-19067
    ELSE
       IF v_ctipcap = 4 AND NVL(v_preglimite,0) <> 0 THEN
          SELECT r.trespue
            INTO v_tlinia
            FROM pregungarancar pg, respuestas r
           WHERE sseguro = psseguro
             AND nriesgo = NVL(pnriesgo,1)
             AND cgarant = v_cgarant
			 --INI JMC 06/08/2024 AITSSD-19067
             --AND nmovimi = NVL(pnmovimi,1)
			 AND nmovimi = (SELECT MAX (nmovimi)
			                  FROM pregungarancar
							 WHERE sseguro=pg.sseguro
							   AND nriesgo=pg.nriesgo
							   AND cgarant=pg.cgarant
							   AND cpregun=pg.cpregun
							   AND sproces=pg.sproces)
			 --FIN JMC 06/08/2024 AITSSD-19067
             AND sproces = psproces
             AND pg.cpregun = v_preglimite
             AND r.cpregun=pg.cpregun
             AND r.crespue=pg.crespue
             AND r.cidioma=pcidioma;
       END IF;
    --FIN JMC 26/06/2024 AITSSD-19067
    END IF;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_riesgo_car;
/*****************************************************************
FUNCTION f_importes_franquicias
param IN psseguro  : codigo de seguro
param IN psproces  : codigo del proceso
param IN pcampo  :  campo a devolver 1: porcentaje, 2:valor,campo a devolver 10: porcentaje con el '%', campo a devolver 2:valor ,campo a devolver 20 :valor con el literal 'smmlv'
param IN pnriesgo  : n?mero de riesgo
param IN pcidioma  : idioma
param IN pmodo     : modo EST/POL
return             : texto con los importes de franquicia.
Bug 35052/201442 - 30/03/2015
******************************************************************/
FUNCTION f_importes_franquicias_car(
    psseguro IN NUMBER,
    psproces IN NUMBER,
    pcampo   IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 2,
    pmodo    IN VARCHAR2 DEFAULT 'POL')
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(4000);
    v_tlinia    VARCHAR2(50);
    v_tpargar   VARCHAR2(200);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot VARCHAR2(200);
    v_ctipcap garanpro.ctipcap%TYPE;
    v_cimpres garanpro.cimpres%TYPE;
    v_npargar   NUMBER := 0;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_porcded   NUMBER;
    v_smmlv     NUMBER;
    v_sseguro garanseg.sseguro%TYPE;
    v_cgarant garanseg.cgarant%TYPE;
    v_nmovimi garanseg.nmovimi%TYPE;
    v_norden garanpro.norden%TYPE;
    v_csituac VARCHAR2(100);
    nerror    NUMBER;
    v_tnivel  VARCHAR2(200); --BUG 33741 CSI 24/11/2017 se adiciona Funcion Previo Cartera
    vsproduc    NUMBER; -- 236. 0055909: PDF Cobertura Autos. VIDRIOS, AU AL
-- Inicio 253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
    v_cimpmin NUMBER;
-- Fin  253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
  BEGIN
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    v_tconsulta                                 := 'SELECT s.sseguro, p.cgarant, p.norden';
    v_tconsulta                                 := v_tconsulta || ' FROM  garangen g, garanpro p, productos pp, ';
    v_tconsulta                                 := v_tconsulta || ' garancar s, seguros se';
    IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
      v_csituac                                 := '(0,7,5,2)';
    ELSE
      v_csituac := '(0,7,5,2,4)';
    END IF;
    v_tconsulta := v_tconsulta || ' WHERE g.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = pp.sproduc';
    v_tconsulta := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' AND se.csituac in ' || v_csituac;
    v_tconsulta := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
    v_tconsulta := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    v_tconsulta := v_tconsulta || ' AND s.sproces = ' || psproces;
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  nerror      := pac_log.f_log_consultas(v_tconsulta, 'pac_isqlfor_lcol.f_importes_riesgo_car', 1);
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_sseguro, v_cgarant, v_norden;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    BEGIN
      SELECT sproduc INTO vsproduc FROM seguros WHERE sseguro = psseguro; -- 236. 0055909: PDF Cobertura Autos. VIDRIOS, AU AL
      SELECT bd.impvalor1 porcded,
        bd.impmin smmlv,
-- Inicio 253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
          bd.cimpmin,
-- Fin  253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
        bn.tnivel --BUG 33741 CSI 24/11/2017 se adiciona Funcion Previo Cartera
      INTO v_porcded,
        v_smmlv,
-- Inicio 253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
          v_cimpmin,
-- Fin  253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
        v_tnivel --BUG 33741 CSI 24/11/2017 se adiciona Funcion Previo Cartera
      FROM bf_progarangrup bp,
        bf_bonfransegcar bf,
        bf_detnivel bd,
        seguros s,
        bf_desnivel bn --BUG 33741 CSI 24/11/2017 se adiciona Funcion Previo Cartera
      WHERE s.sseguro = v_sseguro
      AND bp.sproduc  = s.sproduc
      AND bp.cgarant  = v_cgarant
      AND bp.cempres  = s.cempres
      AND bp.cactivi  = s.cactivi
      AND bf.sseguro  = s.sseguro
      AND bf.cgrup    = bp.codgrup
      AND bf.ctipgrup = 2
      AND bf.sproces  = psproces
      AND bd.cgrup    = bf.cgrup
      AND bd.csubgrup = bf.csubgrup
      AND bd.cversion = bf.cversion
      AND bd.cnivel   = bf.cnivel
      AND bd.cvalor1  = 1
 --  Inicio 253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
      AND bd.cimpmin IN (4,55,2)
--  Fin  253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
      AND bf.nmovimi  =
        --INI BUG 51817 MPC 30/05/2019 Se adiciona condiciÃ³n.
        (
        SELECT MAX(nmovimi)
        FROM bf_bonfransegcar cc
        WHERE cc.sseguro = s.sseguro
        AND cc.sproces   = bf.sproces
		--Ini DV 03/06/2021 QT 0067758: Previo póliza 94015258 sin deducible en RC/ el grupo de la garantia 9220 en previo queda con movimiento
		-- menor del maximo por tal motivo se filtra por grupo de deducible y maximo movimiento de la tabla bf_bonfransegcar
      --  AND cc.nmovimi  <=
      --    (SELECT MAX(nmovimi) FROM movseguro WHERE sseguro = cc.sseguro
       --   )
		   and cc.cgrup=bf.cgrup
		--Fin DV 03/06/2021 QT 0067758: Previo póliza 94015258 sin deducible en RC
        )
        --FIN BUG 51817 MPC 30/05/2019 Se adiciona condiciÃ³n.
        --INI BUG 33741 CSI 24/11/2017 se adiciona Funcion Previo Cartera
      AND bd.cgrup    = bn.cgrup
      AND bd.csubgrup = bn.csubgrup
      AND bd.cversion = bn.cversion
      AND bd.cnivel   = bn.cnivel
      AND bn.cidioma  = pcidioma;
      --FIN BUG 33741 CSI 24/11/2017 se adiciona Funcion Previo Cartera
      --Bug 35052/202537-16/04/2015
 -- Inicio 253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
      IF ( NVL ( f_parproductos_v ( vsproduc, 'IMP_DEDUCIBLE_PDF' ), 0 ) = 0) THEN
 -- Fin 253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
      IF pcampo    = 1 AND v_cgarant NOT IN (756, 757) THEN
        v_tlinia  := v_porcded;
      ELSIF pcampo = 10 AND v_cgarant NOT IN (756, 757) THEN
        v_tlinia  := v_porcded || ' % ';
      ELSIF pcampo = 2 AND v_cgarant NOT IN (756, 757) THEN
        v_tlinia  := v_smmlv;
      ELSIF pcampo = 20 AND v_cgarant NOT IN (756, 757) THEN
        v_tlinia  := v_smmlv || ' smmlv ';
        --INI BUG 33741 CSI 24/11/2017 se adiciona Funcion Previo Cartera
      ELSIF pcampo = 3 THEN
        v_tlinia  := v_tnivel;
        --FIN BUG 33741 CSI 24/11/2017 se adiciona Funcion Previo Cartera
      ELSE
        --INI - DMC - 20/01/2020 - 65632: No se genera previo
        --v_tlinia := '';
        v_tlinia := ' ';
        --FIN - DMC - 20/01/2020 - 65632: No se genera previo
      END IF;
-- Inicio 236. 0055909: PDF Cobertura Autos. VIDRIOS, AU AL
       ELSE
         -- Inicio  253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
          IF pcampo   = 1 AND v_cimpmin = 2  AND v_cgarant in (9219,9220,758,759,760,761,762,771) THEN
            v_tlinia := v_tnivel;
          ELSIF pcampo   = 1 AND v_cimpmin <> 2 AND v_cgarant NOT IN (756, 757, 9219) THEN --BUG AITSSD-13074 GZG 06/07/23 Se retira amparo 9220 para que se visualice en el pdf
            v_tlinia :=  v_porcded || ' % ';
          ELSIF pcampo = 10 AND v_cimpmin <> 2 AND v_cgarant NOT IN (756, 757, 9219,9220) THEN
            v_tlinia  := v_porcded || ' % ';
          ELSIF pcampo = 2 AND v_cimpmin <> 2 AND v_cgarant NOT IN (756, 757, 9219) THEN --BUG AITSSD-13074 GZG 06/07/23 Se retira amparo 9220 para que se visualice en el pdf
            v_tlinia  := v_smmlv;
          ELSIF pcampo = 20 AND v_cimpmin <> 2 AND v_cgarant NOT IN (756, 757, 9219,9220) THEN
          -- Fin  253.0 0059270: T?ico Autos // PDF // Validaci??structura PDF
            v_tlinia  := v_smmlv || ' smmlv ';
          ELSIF pcampo = 3 THEN
            v_tlinia  := v_tnivel;
          ELSE
            --INI - DMC - 20/01/2020 - 65632: No se genera previo
            --v_tlinia := '';
            v_tlinia := ' ';
            --FIN - DMC - 20/01/2020 - 65632: No se genera previo
          END IF;
       END IF;
-- Fin 236. 0055909: PDF Cobertura Autos. VIDRIOS, AU AL
    EXCEPTION
    WHEN OTHERS THEN
      v_tlinia := ' ';
    END;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_franquicias_car;
/*******************************************************************
FUNCTION f_personas_fi:  RelaciÃ¿Â³n de uno o mas asegurados Judicial
RelaciÃ¿Â³n de uno o mas demandados
RelaciÃ¿Â³n de uno o mas demandantes
RelaciÃ¿Â³n de uno o mas obligado a prestar caucion
psseguro IN NUMBER
pcidioma IN NUMBER
ptabla   IN VARCHAR2
pcamp    IN NUMBER
return             : texto
27/01/2015 - JCF
*******************************************************************/
FUNCTION f_personas_fi(
    psseguro IN NUMBER,
    pcidioma IN NUMBER,
    ptabla   IN VARCHAR2,
    pcamp    IN NUMBER)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult     VARCHAR2(4000);
    v_idaseg      VARCHAR2(500);
    v_nomaseg     VARCHAR2(500);
    v_telefonoase VARCHAR2(500);
    v_asepoblac   VARCHAR2(500);
    v_asedirec    VARCHAR2(500);
    v_tconsulta   VARCHAR2(2000);
    v_tabla       VARCHAR2(2000);
    v_sseguro     NUMBER;
  BEGIN
    v_tabla     := ptabla;
    v_sseguro   := psseguro;
    v_tconsulta := 'SELECT SUBSTR(pac_isqlfor_lcol.f_dades_persona(ase.sperson, 8,   8  , ''POL''), 1, 5 ) ' || ' || pac_isqlfor_lcol.f_dades_persona(ase.sperson, 1, 8, ''POL'') idaseg,' || ' (SELECT TRIM(tnombre) || '' '' ||' || '                    TRIM(tapelli1 || '' '' || tapelli2) ' || '           FROM per_detper ' || '          WHERE sperson = ase.sperson ' || '            AND ROWNUM = 1) nomaseg, ' || '        (SELECT tvalcon ' || '           FROM per_contactos ' || '          WHERE sperson = ase.sperson ' || '            AND ROWNUM = 1 ' || '            AND ctipcon = 1) telefonoase, ' || '         pac_isqlfor.f_poblacion(ase.sperson, 1) asepoblac, ' || '         pac_isqlfor_lcol.f_direccion(ase.sperson, 1, ''POL'') asedirec ' || '         FROM  ' || v_tabla || ' ase' || '        WHERE ase.sseguro = ' || v_sseguro || '     ORDER BY norden ';
    OPEN vr_cursor FOR v_tconsulta;
    LOOP
      FETCH vr_cursor
      INTO v_idaseg,
        v_nomaseg,
        v_telefonoase,
        v_asepoblac,
        v_asedirec;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF pcamp     = 1 THEN
      v_tresult := v_tresult || v_idaseg || ' \par ';
    ELSIF pcamp  = 2 THEN
      v_tresult := v_tresult || v_nomaseg || ' \par ';
    ELSIF pcamp  = 3 THEN
      v_tresult := v_tresult || v_telefonoase || ' \par ';
    ELSIF pcamp  = 4 THEN
      v_tresult := v_tresult || v_asepoblac || ' \par ';
    ELSIF pcamp  = 5 THEN
      v_tresult := v_tresult || v_asedirec || ' \par ';
    END IF;
  END LOOP;
  RETURN (REPLACE(f_jrep_trad(v_tresult), CHR(39), ''));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_personas_fi;
/*****************************************************************
GHC Funciona de planes para colectivos de hogar
FUNCTION f_planes
Devuelve los planes de una p?liza
param IN psseguro  : codigo de seguro
param IN pcampo    : 1
param IN pnmovimi  : movimiento
param IN pcidioma  : codigo idioma
return             : texto con los planes
******************************************************************/
FUNCTION f_planes_home(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnmovimi IN NUMBER,
    pcidioma IN NUMBER DEFAULT 1)
  /* Inicio ARM   Bug: 0048174 */
  RETURN CLOB
IS
  CURSOR v_cur
  IS
    SELECT nomplan,
      amparoplan,
      valorasegplan,
      incrementoplan,
      --INI BUG 0058707 GZG 13/02/2020
      deduci,
      indice
      --FIN BUG 0058707 GZG 13/02/2020
    FROM
      (SELECT NVL( r.tnatrie, TRIM(pac_isqlfor_lcol.f_dades_persona(r.sperson, 4)
        || ' '
        || pac_isqlfor_lcol.f_dades_persona(r.sperson, 5))) nomplan,
        gg.tgarant amparoplan,
        TO_CHAR(NVL(pac_preguntas.f_get_pregungaranseg_v(r.sseguro, g.cgarant, r.nriesgo, 4081, 'POL'), g.icapital), 'FM999G999G999G999G999G990D00') valorasegplan,
        TO_CHAR(NVL(g.prevali, 0), 'FM990D00') incrementoplan,
        (SELECT bn.tnivel --,bf.nmovimi,s.sseguro, bp.cgarant
        FROM bf_progarangrup bp,
          bf_bonfranseg bf,
          bf_detnivel bd,
          seguros s,
          bf_desnivel bn
        WHERE s.sseguro = r.sseguro
        AND bp.sproduc  = s.sproduc
        AND bp.cgarant  = g.cgarant
        AND bp.cempres  = s.cempres
        AND bp.cactivi  = s.cactivi
        AND bf.sseguro  = s.sseguro
        AND bf.cgrup    = bp.codgrup
        AND bf.ctipgrup = 2
        AND bf.nmovimi  = pnmovimi
        AND bd.cgrup    = bf.cgrup
        AND bd.csubgrup = bf.csubgrup
        AND bd.cversion = bf.cversion
        AND bd.cnivel   = bf.cnivel
        AND bd.cvalor1  = 1
        AND bd.cimpmin IN (4, 55) -- CAL 23/07/2015 Inclusion de valor
        AND bd.cgrup    = bn.cgrup
        AND bd.csubgrup = bn.csubgrup
        AND bd.cversion = bn.cversion
        AND bd.cnivel   = bn.cnivel
        AND bn.cidioma  = 8
        AND bf.nriesgo  = r.nriesgo
        ) deduci,
    --INI BUG 0058707 GZG 13/02/2020
    (SELECT pg.crespue
    FROM pregungaranseg pg
    WHERE pg.cpregun = 6124
    AND pg.sseguro   = r.sseguro
    AND pg.cgarant   = g.cgarant
    AND pg.nmovimi   =
      (SELECT MAX(pg2.nmovimi)
      FROM pregungaranseg pg2
      WHERE pg2.cpregun = 6124
      AND pg2.sseguro   = pg.sseguro
      AND pg2.cgarant   = pg.cgarant
      AND pg2.nmovimi   = pnmovimi --BUG 0058707 GZG 18/02/2020
      )
    ) indice,
    --FIN BUG 0058707 GZG 13/02/2020
      ga.norden
    FROM riesgos r
    INNER JOIN garanseg g
    ON g.sseguro  = r.sseguro
    AND g.nriesgo = r.nriesgo
	--INI  02/04/2026  JMC  AITSSD-8951
    AND g.nmovimi = pnmovimi
	--FIN  02/04/2026  JMC  AITSSD-8951
    INNER JOIN garangenpro gg
    ON gg.cgarant = g.cgarant -- Solucion BUG 0021759
    INNER JOIN garanpro ga
    ON gg.cgarant   = ga.cgarant
    WHERE r.sseguro = psseguro
    AND pnmovimi BETWEEN r.nmovima AND NVL(r.nmovimb, pnmovimi)
    AND gg.cidioma = pcidioma
    AND EXISTS
      (SELECT 1
      FROM seguros se
      WHERE se.sseguro = g.sseguro
      AND se.sproduc   = ga.sproduc
      )
      ) p
    GROUP BY nomplan,
      amparoplan,
      valorasegplan,
      incrementoplan,
      deduci,
      indice,--BUG 0058707 GZG 13/02/2020
      norden
    ORDER BY nomplan,
      norden;
    v_tresult CLOB; -- fin ARM   Bug: 0048174 - Se realiza cambio VARCHAR2 por CLOB -- 0019605 RMGA ERROR EN EL PDF DE LOS DEDUCIBLES POR AMPARO
    v_count NUMBER;
  BEGIN
    SELECT COUNT(1)
    INTO v_count
    FROM riesgos
    WHERE sseguro = psseguro
    AND pnmovimi BETWEEN nmovima AND NVL(nmovimb, pnmovimi);
    IF v_count >= 1 THEN
      FOR i IN v_cur
      LOOP
        IF pcampo    = 1 THEN
          v_tresult := v_tresult || i.nomplan || '\par ';
        ELSIF pcampo = 2 THEN
          v_tresult := v_tresult || i.amparoplan || '\par ';
        ELSIF pcampo = 3 THEN
          v_tresult := v_tresult || i.valorasegplan || '\par ';
        ELSIF pcampo = 4 THEN
          v_tresult := v_tresult || i.incrementoplan || '\par ';
        ELSIF pcampo = 5 THEN
          v_tresult := v_tresult || i.deduci || '\par ';
        ELSIF pcampo = 6 THEN--BUG 0058707 GZG 13/02/2020
          v_tresult := v_tresult || i.indice || '\par ';--BUG 0058707 GZG 13/02/2020
        END IF;
      END LOOP;
    ELSE
      FOR i IN v_cur
      LOOP
        IF pcampo    = 4 THEN
          v_tresult := i.incrementoplan;
        END IF;
      END LOOP;
    END IF;
    RETURN (f_jrep_trad(v_tresult));
  EXCEPTION
  WHEN OTHERS THEN
    RETURN ('');
  END f_planes_home;
  /*******************************************************************
  FUNCTION f_objcaucion_fi: Objeto de la caucion
  psseguro  IN NUMBER,
  pnmovimi IN NUMBER,
  pcidioma IN NUMBER,
  ptabla   IN VARCHAR2 DEFAULT 'POL',
  pcduplica IN NUMBER DEFAULT 0)
  return             : Clob
  20/02/2015 - JCF
  *******************************************************************/
FUNCTION f_objcaucion_fi(
    psseguro  IN NUMBER,
    pnmovimi  IN NUMBER,
    pcidioma  IN NUMBER,
    ptabla    IN VARCHAR2 DEFAULT 'POL',
    pcduplica IN NUMBER DEFAULT 0)
  RETURN CLOB
IS
  vret CLOB;
BEGIN
  IF ptabla = 'POL' THEN
    FOR i IN
    (SELECT clau
    FROM
      (SELECT cg.tclatex clau,
        c.nordcla
      FROM clausugen cg,
        clausuesp c,
        seguros s
      WHERE s.sseguro = c.sseguro
      AND cg.sclagen  = c.sclagen
      AND c.sseguro   = psseguro
      AND c.nmovimi   = 1
      AND c.sclagen  IS NOT NULL
      AND cg.cidioma  = pcidioma
      AND (s.cramo   <> 103
      OR ncertif      = 0)
      ORDER BY nordcla
      )
    GROUP BY clau
    )
    LOOP
      vret := vret || i.clau || ' \par \par ';
    END LOOP;
  ELSE
    FOR i IN
    (SELECT clau
    FROM
      (SELECT cg.tclatex clau,
        c.nordcla
      FROM clausugen cg,
        estclausuesp c,
        estseguros s
      WHERE s.sseguro = c.sseguro
      AND cg.sclagen  = c.sclagen
      AND c.sseguro   = psseguro
      AND c.nmovimi   = 1
      AND c.sclagen  IS NOT NULL
      AND cg.cidioma  = pcidioma
      AND (s.cramo   <> 103
      OR ncertif      = 0)
      ORDER BY nordcla
      )
    GROUP BY clau
    )
    LOOP
      vret := vret || i.clau || ' \par \par ';
    END LOOP;
  END IF;
  IF pnmovimi > 1 AND pcduplica = 0 THEN
    vret     := vret || f_descsup(psseguro, pnmovimi);
  END IF;
  RETURN TO_CLOB(f_jrep_trad(vret));
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_objcaucion_fi;
/*******************************************************************
FUNCTION f_clausulas_fi: solo para fianzas
psseguro IN NUMBER,
pnmovimi IN NUMBER,
pcidioma IN NUMBER,
ptabla IN VARCHAR2 DEFAULT 'POL',
pcduplica IN NUMBER DEFAULT 0)
return             : clob
20/02/2015 - JCF
*******************************************************************/
FUNCTION f_clausulas_fi(
    psseguro  IN NUMBER,
    pnmovimi  IN NUMBER,
    pcidioma  IN NUMBER,
    ptabla    IN VARCHAR2 DEFAULT 'POL',
    pcduplica IN NUMBER DEFAULT 0)
  RETURN CLOB
IS
  vret CLOB;
BEGIN
  IF ptabla = 'POL' THEN
    FOR i IN
    (SELECT clau
    FROM
      (SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        c.nordcla
      FROM clausugen cg,
        claususeg c
      WHERE cg.sclagen = c.sclagen
      AND c.sseguro    = psseguro
      AND c.nmovimi    = pnmovimi
      AND cg.cidioma   = pcidioma
      UNION
      SELECT REPLACE(REPLACE(REGEXP_REPLACE(tclaesp, '[[:space:]][[:space:]]*', ' '),'<br><br>','<br>'),'<br>','\par ') clau,--AITSSD-8394 GZG 09/03/2026
        nordcla
      FROM clausuesp
      WHERE sseguro = psseguro
      AND nmovimi   = pnmovimi
      -- INI BUG 0062239: FIANZAS - JUDICIAL - 349476 - movimiento 5 - no registra en PDF la clausula incluida
      AND cclaesp = 2
      and nordcla = (SELECT MAX(nordcla) FROM CLAUSUESP WHERE sseguro = psseguro AND nmovimi = pnmovimi AND cclaesp = 2)
      -- INI BUG 0062239: FIANZAS - JUDICIAL - 349476 - movimiento 5 - no registra en PDF la clausula incluida
      AND sclagen  IS NULL
      ORDER BY nordcla
      )
    GROUP BY clau
    ORDER BY clau
    )
    LOOP
      vret := vret || i.clau || ' \par \par ';
    END LOOP;
  ELSE
    FOR i IN
    (SELECT clau
    FROM
      (SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        c.nordcla
      FROM clausugen cg,
        estclaususeg c
      WHERE cg.sclagen = c.sclagen
      AND c.sseguro    = psseguro
      AND c.nmovimi    = pnmovimi
      AND cg.cidioma   = pcidioma
      UNION
      SELECT REPLACE(REPLACE(REGEXP_REPLACE(tclaesp, '[[:space:]][[:space:]]*', ' '),'<br><br>','<br>'),'<br>','\par ') clau,--AITSSD-8394 GZG 09/03/2026
        nordcla
      FROM estclausuesp
      WHERE sseguro = psseguro
      AND nmovimi   = pnmovimi
      AND sclagen  IS NULL
      ORDER BY nordcla
      )
    GROUP BY clau
    ORDER BY clau
    )
    LOOP
      vret := vret || i.clau || ' \par \par ';
    END LOOP;
  END IF;
  IF pnmovimi > 1 AND pcduplica = 0 THEN
    vret     := vret || f_descsup(psseguro, pnmovimi);
  END IF;
  RETURN TO_CLOB(f_jrep_trad(vret));
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_clausulas_fi;
/*****************************************************************
GH - TH
FUNCTION f_garantias_riesgo home
Devuelve las partidas de un riesgo
param IN psseguro  : codigo de seguro
param IN pnriesgo  : numero de riesgo
param IN pcidioma  : codigo de idioma
param IN pmodo     : modo EST/POL
return             : texto con las garant?as del riesgo
******************************************************************/
FUNCTION f_garantias_riesgo_parthome(
    psseguro IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pcampo   IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult    VARCHAR2(32000) := '';
    v_tconsulta  VARCHAR2(4000);
    v_tlinia     VARCHAR2(300);
    v_tlinia1    VARCHAR2(300);
    v_tlinia2    VARCHAR2(300);
    v_tlinia3    VARCHAR2(300);
    v_norden     NUMBER;
    v_nimpresion NUMBER;
    v_nlinea     NUMBER;
    v_tpargar    VARCHAR2(200);
    v_tablaseg   VARCHAR2(30);
    v_act0       NUMBER(1);
    v_cimpres garanpro.cimpres%TYPE;
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
    v_ntabs     VARCHAR2(100);
  BEGIN
    -- BUG 16092 - 12/01/2011 - JMP - AGA RC: Miramos si las garant?as est?n definidas para la actividad del seguro
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    v_tconsulta         := v_tconsulta || ' LEFT JOIN pregungaranseg pgs ON s.cgarant = pgs.cgarant AND pgs.sseguro = s.sseguro AND pgs.nriesgo = s.nriesgo AND pgs.nmovimi = s.nmovimi ';
    v_tconsulta         := v_tconsulta || ' WHERE se.csituac in ' || v_csituac;
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    v_tconsulta         := 'SELECT p.norden,g.cgarant,g.tgarant,pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot), null, ''' || pmodo || ''') a, ' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0) IMPRESION, ' || ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot, null, ''' || pmodo || ''') d, 0 nlinea FROM garangenpro g '; -- Solucion BUG 21759
    v_tconsulta         := v_tconsulta || ' INNER JOIN garanpro p ON g.cgarant = p.cgarant ';
    v_tconsulta         := v_tconsulta || ' INNER JOIN productos pp ON p.sproduc = pp.sproduc ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' INNER JOIN estgaranseg s ON g.cgarant = s.cgarant AND p.cgarant = s.cgarant ' || 'INNER JOIN estseguros se ON p.sproduc = se.sproduc AND s.sseguro = se.sseguro AND p.cactivi = ' || v_actividad;
      v_csituac         := '(0,7,5,2,4)';
    ELSE
      v_tconsulta                                 := v_tconsulta || ' INNER JOIN garanseg s ON g.cgarant = s.cgarant AND p.cgarant = s.cgarant ' || ' INNER JOIN seguros se ON p.sproduc = se.sproduc AND s.sseguro = se.sseguro AND p.cactivi = ' || v_actividad;
      IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
        v_csituac                                 := '(0,7,5,2)';
      ELSE
        v_csituac := '(0,7,5,2,4)';
      END IF;
    END IF;
    v_tconsulta         := v_tconsulta || ' WHERE se.csituac in ' || v_csituac;
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND g.cidioma = ' || pcidioma;
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' AND s.icapital IS NOT NULL ' || ' AND s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg WHERE sseguro =' || psseguro;
      IF (pnmovimi      IS NOT NULL) THEN
        v_tconsulta     := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
        v_tconsulta := v_tconsulta || ')';
      END IF;
    ELSE
      v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro;
      IF (pnmovimi  IS NOT NULL) THEN
        v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
        v_tconsulta := v_tconsulta || ')';
      END IF;
    END IF;
    v_tconsulta         := v_tconsulta || ' UNION ';
    v_tconsulta         := v_tconsulta || ' SELECT p.norden, a.cgarant, a.tvalor AS tgarant,' || ' pac_isqlfor_lcol.f_imporignomon(a.sseguro, b.nvalor, null, ''' || pmodo || ''') AS val, -1 impresion, ' || ' pac_isqlfor_lcol.f_imporignomon(a.sseguro, 0, null, ''' || pmodo || ''') d, a.nlinea ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' FROM (SELECT * FROM estpregungaransegtab WHERE sseguro = ' || psseguro || ' AND ccolumna = 1 ) a INNER JOIN ' || ' (SELECT * FROM estpregungaransegtab WHERE sseguro = ' || psseguro || ' AND ccolumna = 2) b ON a.sseguro = b.sseguro AND a.nriesgo = b.nriesgo AND a.cgarant = b.cgarant AND a.nmovimi = b.nmovimi AND a.nlinea = b.nlinea ' || ' INNER JOIN garangenpro c ON a.cgarant = c.cgarant ' -- Solucion BUG 21759
      || ' INNER JOIN garanpro p ON c.cgarant = p.cgarant ' || ' INNER JOIN productos pp ON p.sproduc = pp.sproduc ' || ' INNER JOIN estseguros se  ON p.sproduc = se.sproduc AND a.sseguro = se.sseguro AND p.cactivi = ' || v_actividad;
      v_tconsulta := v_tconsulta || ' WHERE c.cidioma = ' || pcidioma;
    ELSE
      v_tconsulta := v_tconsulta || ' FROM (SELECT * FROM pregungaransegtab WHERE sseguro = ' || psseguro || ' AND ccolumna = 1) a INNER JOIN ' || ' (SELECT * FROM pregungaransegtab WHERE sseguro = ' || psseguro || ' AND ccolumna = 2) b ON a.sseguro = b.sseguro AND a.nriesgo = b.nriesgo AND a.cgarant = b.cgarant AND a.nmovimi = b.nmovimi AND a.nlinea = b.nlinea ' || ' INNER JOIN garangenpro c ON a.cgarant = c.cgarant ' -- Solucion BUG 21759
      || ' INNER JOIN garanpro p ON c.cgarant = p.cgarant ' || ' INNER JOIN productos pp ON p.sproduc = pp.sproduc ' || ' INNER JOIN seguros se  ON p.sproduc = se.sproduc AND a.sseguro = se.sseguro AND p.cactivi = ' || v_actividad;
      v_tconsulta := v_tconsulta || ' WHERE c.cidioma = ' || pcidioma || ' and a.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro || ') ';
    END IF;
    v_tconsulta := v_tconsulta || ' ORDER BY NORDEN,IMPRESION DESC, NLINEA';
    OPEN vr_cursor FOR v_tconsulta;
    LOOP
      FETCH vr_cursor
      INTO v_norden,
        v_tlinia,
        v_tlinia1,
        v_tlinia2,
        v_nimpresion,
        v_tlinia3,
        v_nlinea;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF pcampo            = 1 THEN
      IF v_nimpresion    = 1 THEN
        v_ntabs         := ' ';
      ELSIF v_nimpresion = 0 THEN
        v_ntabs         := '\tab \tab \tab \tab ';
      ELSIF v_nimpresion = -1 THEN
        v_ntabs         := '\tab \tab \tab \tab \tab \tab \tab \tab ';
      END IF;
      v_tresult   := v_tresult || v_ntabs || v_tlinia1 || '\par ';
    ELSIF pcampo   = 2 THEN
      IF v_tlinia2 = '0' THEN
        SELECT tatribu
        INTO v_tlinia2
        FROM detvalores
        WHERE cvalor = 126
        AND catribu  = NVL(v_cimpres, 59) -- INCLOSA
        AND cidioma  = NVL(pcidioma, 8);
      END IF;
      IF v_nimpresion    = 1 THEN
        v_tresult       := v_tresult || '\par ';
      ELSIF v_nimpresion = 0 THEN
        v_tresult       := v_tresult || '\par ';
      ELSIF v_nimpresion = -1 THEN
        v_tresult       := v_tresult || v_tlinia2 || '\par ';
      END IF;
    ELSIF pcampo   = 3 THEN
      IF v_tlinia2 = '0' THEN
        SELECT tatribu
        INTO v_tlinia2
        FROM detvalores
        WHERE cvalor = 126
        AND catribu  = NVL(v_cimpres, 59) -- INCLOSA
        AND cidioma  = NVL(pcidioma, 8);
      END IF;
      IF v_nimpresion    = 1 THEN
        v_tresult       := v_tresult || '\par ';
      ELSIF v_nimpresion = 0 THEN
        v_tresult       := v_tresult || v_tlinia2 || '\par ';
      ELSIF v_nimpresion = -1 THEN
        v_tresult       := v_tresult || '\par ';
      END IF;
    ELSE
      IF v_tlinia2 = '0' THEN
        SELECT tatribu
        INTO v_tlinia2
        FROM detvalores
        WHERE cvalor = 126
        AND catribu  = NVL(v_cimpres, 59) -- INCLOSA
        AND cidioma  = NVL(pcidioma, 8);
      END IF;
      IF v_nimpresion    = 1 THEN
        v_tresult       := v_tresult || v_tlinia2 || '\par ';
      ELSIF v_nimpresion = 0 THEN
        v_tresult       := v_tresult || '\par ';
      ELSIF v_nimpresion = -1 THEN
        v_tresult       := v_tresult || '\par ';
      END IF;
    END IF;
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ' ';
END f_garantias_riesgo_parthome;
/*****************************************************************
GH
FUNCTION f_garantias_riesgo_glo
Devuelve las garant?as de un riesgo para inmuble y contenido global
param IN psseguro  : codigo de seguro
param IN pnriesgo  : n?mero de riesgo
param IN pcidioma  : codigo de idioma
param IN pmodo     : modo EST/POL
return             : texto con las garant?asdel riesgo
******************************************************************/
FUNCTION f_garantias_riesgo_glo(
    psseguro IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL,
    pcampo   IN VARCHAR2 DEFAULT 1)--Bug 45829 - YMG (29/08/2018)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(2000);
    v_tlinia    VARCHAR2(200);
    v_tlinia1   VARCHAR2(200);
    v_tlinia2   VARCHAR2(200);--Bug 45829 - YMG ( 29/08/2018 )
    v_tliniaold VARCHAR2(200);
    v_tpargar   VARCHAR2(200);
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
  BEGIN
    -- BUG 16092 - 12/01/2011 - JMP - AGA RC: Miramos si las garant?as est?n definidas para la actividad del seguro
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    v_tconsulta := 'SELECT REPLACE(pac_isqlfor_lcol.f_des_garpro(se.sseguro,s.nriesgo,' || NVL(pcidioma, 2) || ',p.cgarant,se.sproduc,''' || pmodo || '''), CHR(39), CHR(39) || CHR(39)) a, REPLACE(pre.tpregun,''%'',''Valor'') tpregun, ';--Bug 45829 - YMG (29/08/2018)
    --Inicio bug 45829 - YMG
    v_tconsulta := v_tconsulta || ' TRIM(TO_CHAR(s.icaptot, ''999,999,999,999,999,999'')) valorass ';
    --Fing bug 45829
    v_tconsulta         := v_tconsulta || ' FROM garanpro p ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || 'INNER JOIN estgaranseg s ON p.cgarant = s.cgarant INNER JOIN estseguros se ON p.sproduc = se.sproduc AND s.sseguro = se.sseguro AND p.cactivi = ' || v_actividad || ' ';
      v_tconsulta       := v_tconsulta || 'LEFT JOIN estpregungaranseg pgs ON s.cgarant = pgs.cgarant AND pgs.sseguro = s.sseguro AND pgs.nriesgo = s.nriesgo AND pgs.nmovimi = s.nmovimi AND pgs.cpregun in (5959,5960,5851,5852) ';
      --v_tconsulta := v_tconsulta || 'estgaranseg s, estseguros se';
      v_csituac := '(0,7,5,2,4)';
    ELSE
      v_tconsulta := v_tconsulta || 'INNER JOIN garanseg s ON p.cgarant = s.cgarant INNER JOIN seguros se ON p.sproduc = se.sproduc AND s.sseguro = se.sseguro AND p.cactivi = ' || v_actividad || ' ';
      v_tconsulta := v_tconsulta || 'LEFT JOIN pregungaranseg pgs ON s.cgarant = pgs.cgarant AND pgs.sseguro = s.sseguro AND pgs.nriesgo = s.nriesgo AND pgs.nmovimi = s.nmovimi AND pgs.cpregun in (5959,5960,5851,5852) ';
      --v_tconsulta := v_tconsulta || 'garanseg s, seguros se';
      IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
        -- Bug 40686  AABC 17/04/2018 Version 122 se adiciona la situacion prop alta
        v_csituac := '(0,7,5,2,4)';
      ELSE
        v_csituac := '(0,7,5,2,4)';
      END IF;
    END IF;
    v_tconsulta := v_tconsulta || 'LEFT JOIN preguntas pre ON pgs.cpregun = pre.cpregun ';
    v_tconsulta := v_tconsulta || ' WHERE se.csituac in ' || v_csituac;
    -- v_tconsulta := v_tconsulta || ' AND s.ffinefe IS NULL';
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' AND s.cobliga = 1 and s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg WHERE sseguro =' || psseguro;
      IF (pnmovimi      IS NOT NULL) THEN
        v_tconsulta     := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
        v_tconsulta := v_tconsulta || ')';
      END IF;
      SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
        || sproduc
        || ', '
        || cactivi
        || ', p.cgarant, ''GARANT_IMP''), 0) = 1 )'
      INTO v_tpargar
      FROM
        (SELECT seg.sproduc,
          seg.cactivi
        FROM estseguros seg
        WHERE seg.sseguro = psseguro
        );
  ELSE
    v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro;
    IF (pnmovimi  IS NOT NULL) THEN
      v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
    ELSE
      v_tconsulta := v_tconsulta || ')';
    END IF;
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', p.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  END IF;
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_tlinia, v_tlinia1, v_tlinia2;--Bug 45829 - YMG (29/08/2018)
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF(pcampo          = 1)THEN--Bug 45829 - YMG (29/08/2018)
      IF (v_tliniaold IS NULL OR v_tliniaold != v_tlinia) THEN
        v_tresult     := v_tresult || v_tlinia || '\par ';
        IF (v_tlinia1 IS NOT NULL) THEN
          v_tresult   := v_tresult || '\tab \tab \tab ' || v_tlinia1 || '\par ';
        END IF;
      ELSE
        IF (v_tlinia1 IS NOT NULL) THEN
          v_tresult   := v_tresult || '\tab \tab \tab ' || v_tlinia1 || '\par ';
        END IF;
      END IF;
      v_tliniaold := v_tlinia;
      --Inicio bug 45829 - (YMG)
    ELSIF(pcampo       = 2)THEN
      IF (v_tliniaold IS NULL OR v_tliniaold != v_tlinia) THEN
        v_tresult     := v_tresult || v_tlinia2 || '\par ';
        IF (v_tlinia1 IS NOT NULL) THEN
          v_tresult   := v_tresult || ' \par ';
        END IF;
      ELSE
        IF (v_tlinia1 IS NOT NULL) THEN
          v_tresult   := v_tresult || ' \par ';
        END IF;
      END IF;
      v_tliniaold := v_tlinia;
    END IF;
    --Fin bug 45829
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_garantias_riesgo_glo;
/*****************************************************************
GH
FUNCTION f_importes_riesgo_glo
Devuelve los capitales de un riesgo
param IN psseguro  : codigo de seguro
param IN pnriesgo  : n?mero de riesgo
param IN pmodo     : modo EST/POL
return             : texto con los capitales del riesgo
Bug 19927 - 28/11/2011 - JTS
******************************************************************/
FUNCTION f_importes_riesgo_glo(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL,
    pnpreamp IN NUMBER DEFAULT 0)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(4000);
    v_tlinia    VARCHAR2(50);
    v_tpargar   VARCHAR2(200);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot VARCHAR2(200);
    v_ctipcap garanpro.ctipcap%TYPE;
    v_cimpres garanpro.cimpres%TYPE;
    v_npargar    NUMBER := 0;
    v_tablaseg   VARCHAR2(30);
    v_act0       NUMBER(1);
    v_actividad  VARCHAR2(20);
    v_csituac    VARCHAR2(100);
    v_cgarant    NUMBER;
    v_valpreg    VARCHAR2(200);
    v_cgarantold NUMBER;
  BEGIN
    -- BUG 16092 - 12/01/2011 - JMP - AGA RC: Miramos si las garant?as est?n definidas para la actividad del seguro
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := 'SELECT s.cgarant,pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d,' || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(DECODE(s.cgarant, 48, se.cforpag, 1) * (s.icaptot * nvl(pgs.crespue,0))/(select sum(crespue) from estpregungaranseg pgs1 WHERE cpregun in (5959,5960,5851,5852) AND s.cgarant = pgs1.cgarant AND pgs1.sseguro = s.sseguro AND pgs1.nriesgo = s.nriesgo AND pgs1.nmovimi = s.nmovimi))) valresp ';
    ELSE
      v_tconsulta := 'SELECT s.cgarant,pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot) d,' || ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,(DECODE(s.cgarant, 48, se.cforpag, 1) * (s.icaptot * nvl(pgs.crespue,0))/(select sum(crespue) from pregungaranseg pgs1 WHERE cpregun in (5959,5960,5851,5852) AND s.cgarant = pgs1.cgarant AND pgs1.sseguro = s.sseguro AND pgs1.nriesgo = s.nriesgo AND pgs1.nmovimi = s.nmovimi))) valresp ';
    END IF;
    v_tconsulta         := v_tconsulta || ' FROM  garanpro p ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' INNER JOIN estgaranseg s ON p.cgarant = s.cgarant ';
      v_tconsulta       := v_tconsulta || ' INNER JOIN estseguros se ON p.sproduc = se.sproduc AND s.sseguro = se.sseguro AND p.cactivi = ' || v_actividad || ' ';
      --v_tconsulta := v_tconsulta || ' estgaranseg s, estseguros se';
      v_csituac := '(0,7,5,2,4)';
    ELSE
      v_tconsulta := v_tconsulta || ' INNER JOIN garanseg s ON p.cgarant = s.cgarant ';
      v_tconsulta := v_tconsulta || ' INNER JOIN seguros se ON p.sproduc = se.sproduc AND s.sseguro = se.sseguro AND p.cactivi = ' || v_actividad || ' ';
      --v_tconsulta := v_tconsulta || ' garanseg s, seguros se';
      IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
        -- INI 06/09/2018 ARM 45829: HOGAR - Se anexa codigo de situacion faltante
        v_csituac := '(0,7,5,2,4)';
        -- FIN 06/09/2018 ARM 45829: HOGAR - Se anexa codigo de situacion faltante
      ELSE
        v_csituac := '(0,7,5,2,4)';
      END IF;
    END IF;
    v_tconsulta         := v_tconsulta || ' INNER JOIN garangen g ON g.cgarant = s.cgarant ';
    v_tconsulta         := v_tconsulta || ' INNER JOIN productos pp ON p.sproduc = pp.sproduc ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' LEFT JOIN estpregungaranseg pgs ON s.cgarant = pgs.cgarant AND pgs.sseguro = s.sseguro AND pgs.nriesgo = s.nriesgo AND pgs.nmovimi = s.nmovimi AND pgs.cpregun in (5959,5960,5851,5852) ';
    ELSE
      v_tconsulta := v_tconsulta || ' LEFT JOIN pregungaranseg pgs ON s.cgarant = pgs.cgarant AND pgs.sseguro = s.sseguro AND pgs.nriesgo = s.nriesgo AND pgs.nmovimi = s.nmovimi AND pgs.cpregun in (5959,5960,5851,5852) ';
    END IF;
    v_tconsulta := v_tconsulta || ' WHERE se.csituac in ' || v_csituac;
    --v_tconsulta := v_tconsulta || ' AND s.ffinefe IS NULL';
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' AND s.cobliga = 1';
      v_tconsulta       := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg WHERE sseguro =' || psseguro;
      IF (pnmovimi      IS NOT NULL) THEN
        v_tconsulta     := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
        v_tconsulta := v_tconsulta || ')';
      END IF;
      SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
        || sproduc
        || ', '
        || cactivi
        || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
      INTO v_tpargar
      FROM
        (SELECT seg.sproduc,
          seg.cactivi
        FROM estseguros seg
        WHERE seg.sseguro = psseguro
        );
  ELSE
    v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM garanseg WHERE sseguro =' || psseguro;
    IF (pnmovimi  IS NOT NULL) THEN
      v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
    ELSE
      v_tconsulta := v_tconsulta || ')';
    END IF;
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  END IF;
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor
    INTO v_cgarant,
      v_tlinia,
      v_icaptot,
      v_ctipcap,
      v_cimpres,
      v_npargar,
      v_ipritot,
      v_valpreg;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF pnpreamp        = 0 THEN
      IF v_cgarantold IS NULL OR v_cgarantold != v_cgarant THEN
        IF v_npargar   = 1 AND v_icaptot = 0 THEN
          SELECT tatribu
          INTO v_tlinia
          FROM detvalores
          WHERE cvalor = 126
          AND catribu  = NVL(v_cimpres, 59) -- INCLOSA
          AND cidioma  = NVL(pcidioma, 8);
        END IF;
        IF pcampo   = 2 THEN
          v_tlinia := v_ipritot;
        END IF;
        IF v_valpreg != '0' THEN
          v_tlinia   := v_tlinia || '\par ';
        END IF;
      ELSE
        v_tlinia := ' ';
      END IF;
    ELSE
      IF v_cgarantold IS NULL OR v_cgarantold != v_cgarant THEN
        v_tlinia      := '\par ';
        IF v_valpreg  != '0' THEN
          v_tlinia    := v_tlinia || v_valpreg;
        ELSE
          v_tlinia := ' ';
        END IF;
      ELSE
        IF v_valpreg != '0' THEN
          v_tlinia   := v_valpreg;
        ELSE
          v_tlinia := ' ';
        END IF;
      END IF;
    END IF;
    v_cgarantold := v_cgarant;
    v_tresult    := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_riesgo_glo;
/*****************************************************************
GH
FUNCTION f_importes_franquicias_glo
param IN psseguro  : codigo de seguro
param IN pcampo  :  campo a devolver 1: porcentaje, 2:valor
param IN pnriesgo  : n?mero de riesgo
param IN pcidioma  : idioma
param IN pmodo     : modo EST/POL
-- Inicio QT46277 Amantium 13/09/2018
param IN pnmovimi  : nÃºmero de movimiento
-- Fin QT46277 Amantium 13/09/2018
return             : texto con los importes de franquicia.
******************************************************************/
FUNCTION f_importes_franquicias_glo(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL', --QT46277 Amantium 13/09/2018
    pnmovimi IN NUMBER DEFAULT NULL)    --QT46277 Amantium 13/09/2018
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(4000);
    v_tlinia    VARCHAR2(50);
    v_tpargar   VARCHAR2(200);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot VARCHAR2(200);
    v_ctipcap garanpro.ctipcap%TYPE;
    v_cimpres garanpro.cimpres%TYPE;
    v_npargar   NUMBER := 0;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_porcded   NUMBER;
    v_smmlv     NUMBER;
    v_sseguro garanseg.sseguro%TYPE;
    v_cgarant garanseg.cgarant%TYPE;
    v_nmovimi garanseg.nmovimi%TYPE;
    v_norden garanpro.norden%TYPE;
    v_nriesgo garanseg.nriesgo%TYPE;
    v_csituac VARCHAR2(100);
    v_tnivel  VARCHAR2(200);
    v_cpregun NUMBER;
    v_cgarantold garanseg.cgarant%TYPE;
    v_cgarantdeduc bf_progarangrup.cgarant%TYPE;--Bug 0040406: JMG
  BEGIN
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := 'SELECT s.sseguro, p.cgarant, s.nmovimi, p.norden,pgs.cpregun, s.nriesgo ';
    ELSE
      v_tconsulta := 'SELECT s.sseguro, p.cgarant, s.nmovimi, p.norden,pgs.cpregun, s.nriesgo ';
    END IF;
    v_tconsulta         := v_tconsulta || ' FROM  garanpro p ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' INNER JOIN estgaranseg s ON p.cgarant = s.cgarant ';
      v_tconsulta       := v_tconsulta || ' INNER JOIN estseguros se ON p.sproduc = se.sproduc AND s.sseguro = se.sseguro AND p.cactivi = ' || v_actividad || ' ';
      --v_tconsulta := v_tconsulta || ' estgaranseg s, estseguros se';
      v_csituac := '(0,7,5,2,4)';
    ELSE
      v_tconsulta := v_tconsulta || ' INNER JOIN garanseg s ON p.cgarant = s.cgarant ';
      v_tconsulta := v_tconsulta || ' INNER JOIN seguros se ON p.sproduc = se.sproduc AND s.sseguro = se.sseguro AND p.cactivi = ' || v_actividad || ' ';
      --v_tconsulta := v_tconsulta || ' garanseg s, seguros se';
      IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
        -- Bug 40686  AABC 17/04/2018 Version 122 se adiciona la situacion prop alta
        v_csituac := '(0,7,5,2,4)';
      ELSE
        v_csituac := '(0,7,5,2,4)';
      END IF;
    END IF;
    v_tconsulta         := v_tconsulta || ' INNER JOIN garangen g ON g.cgarant = s.cgarant ';
    v_tconsulta         := v_tconsulta || ' INNER JOIN productos pp ON p.sproduc = pp.sproduc ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' LEFT JOIN estpregungaranseg pgs ON s.cgarant = pgs.cgarant AND pgs.sseguro = s.sseguro AND pgs.nriesgo = s.nriesgo AND pgs.nmovimi = s.nmovimi AND pgs.cpregun in (5959,5960,5851,5852) ';
    ELSE
      v_tconsulta := v_tconsulta || ' LEFT JOIN pregungaranseg pgs ON s.cgarant = pgs.cgarant AND pgs.sseguro = s.sseguro AND pgs.nriesgo = s.nriesgo AND pgs.nmovimi = s.nmovimi AND pgs.cpregun in (5959,5960,5851,5852) ';
    END IF;
    v_tconsulta         := v_tconsulta || ' WHERE se.csituac in ' || v_csituac;
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' AND s.cobliga = 1';
      v_tconsulta       := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM ESTGARANSEG WHERE sseguro =' || psseguro;
      /*IF (pnmovimi IS NOT NULL) THEN
      v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE*/
      v_tconsulta := v_tconsulta || ')';
      --END IF;
      SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
        || sproduc
        || ', '
        || cactivi
        || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
      INTO v_tpargar
      FROM
        (SELECT seg.sproduc,
          seg.cactivi
        FROM estseguros seg
        WHERE seg.sseguro = psseguro
        );
  ELSE
    v_tconsulta := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro;
    -- Inicio QT46277 Amantium 13/09/2018
    IF (pnmovimi  IS NOT NULL) THEN
      v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
    ELSE
      v_tconsulta := v_tconsulta || ')';
    END IF;
    -- Fin QT46277 Amantium 13/09/2018
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  END IF;
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor
    INTO v_sseguro,
      v_cgarant,
      v_nmovimi,
      v_norden,
      v_cpregun,
      v_nriesgo;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    BEGIN
      IF v_cgarantold       IS NULL OR v_cgarantold != v_cgarant THEN
        IF NVL(pmodo, 'POL') = 'EST' THEN
          SELECT bd.impvalor1 porcded,
            bd.impmin smmlv,
            bn.tnivel
          INTO v_porcded,
            v_smmlv,
            v_tnivel
          FROM bf_progarangrup bp,
            estbf_bonfranseg bf,
            bf_detnivel bd,
            estseguros s,
            bf_desnivel bn
          WHERE s.sseguro = v_sseguro
          AND bp.sproduc  = s.sproduc
          AND bp.cgarant  = v_cgarant
          AND bp.cempres  = s.cempres
          AND bp.cactivi  = s.cactivi
          AND bf.sseguro  = s.sseguro
          AND bf.cgrup    = bp.codgrup
          AND bf.ctipgrup = 2
          AND bf.nmovimi  =
            (SELECT MAX(nmovimi)
            FROM estbf_bonfranseg
            WHERE sseguro = v_sseguro
            AND nriesgo   = v_nriesgo
            )
          AND bd.cgrup    = bf.cgrup
          AND bd.csubgrup = bf.csubgrup
          AND bd.cversion = bf.cversion
          AND bd.cnivel   = bf.cnivel
          AND bd.cvalor1  = 1
          AND bd.cimpmin IN (4, 55)
          AND bd.cgrup    = bn.cgrup
          AND bd.csubgrup = bn.csubgrup
          AND bd.cversion = bn.cversion
          AND bd.cnivel   = bn.cnivel
          AND bn.cidioma  = 8;
        ELSE
          SELECT DISTINCT --Bug 0040406: JMG
            bd.impvalor1 porcded,
            bd.impmin smmlv,
            bn.tnivel,
            bp.cgarant--Bug 0040406: JMG
          INTO v_porcded,
            v_smmlv,
            v_tnivel,
            v_cgarantdeduc--Bug 0040406: JMG
          FROM bf_progarangrup bp,
            bf_bonfranseg bf,
            bf_detnivel bd,
            seguros s,
            bf_desnivel bn
          WHERE s.sseguro = v_sseguro
            --AND bp.sproduc  = s.sproduc --Bug 0040406: JMG
          AND bp.cgarant  = v_cgarant
          AND bp.cempres  = s.cempres
          AND bp.cactivi  = s.cactivi
          AND bf.sseguro  = s.sseguro
          AND bf.cgrup    = bp.codgrup
          AND bf.ctipgrup = 2
          AND bf.nmovimi  =
            (SELECT MAX(nmovimi)
            FROM bf_bonfranseg
            WHERE sseguro = v_sseguro
            AND nriesgo   = v_nriesgo
              -- Inicio QT46277 Amantium 13/09/2018
            AND nmovimi <= NVL(pnmovimi, nmovimi)
              -- Fin QT46277 Amantium 13/09/2018
            )
          AND bd.cgrup    = bf.cgrup
          AND bd.csubgrup = bf.csubgrup
          AND bd.cversion = bf.cversion
          AND bd.cnivel   = bf.cnivel
          AND bd.cvalor1  = 1
          AND bd.cimpmin IN (4, 55)
          AND bd.cgrup    = bn.cgrup
          AND bd.csubgrup = bn.csubgrup
          AND bd.cversion = bn.cversion
          AND bd.cnivel   = bn.cnivel
          AND bn.cidioma  = 8;
        END IF;
        IF pcampo    = 1 AND v_cgarant NOT IN (756, 757) THEN
          v_tlinia  := v_porcded;
        ELSIF pcampo = 2 AND v_cgarant NOT IN (756, 757) THEN
          v_tlinia  := v_smmlv;
        ELSIF pcampo = 3 THEN
          v_tlinia  := v_tnivel;
        ELSE
          v_tlinia := '';
        END IF;
        IF v_cpregun IS NOT NULL THEN
          v_tlinia   := v_tlinia || '\par ';
        END IF;
      ELSE
        v_tlinia := ' ';
      END IF;
    EXCEPTION
    WHEN OTHERS THEN
      v_tlinia := ' ';
    END;
    v_cgarantold := v_cgarant;
    v_tresult    := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_franquicias_glo;
/*****************************************************************
GH
FUNCTION f_importes_certif_glo
Devuelve los capitales de todos los certificados diferentes a 0
param IN psseguro  : codigo de seguro padre
param IN pcampo    : 1 Valor Asegurado / 2 Prima amparo
return             : texto importes
******************************************************************/
FUNCTION f_importes_certif_glo(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnmovimi IN NUMBER DEFAULT NULL,
    ptablas  IN VARCHAR2 DEFAULT 'POL', --BUG 47494 MPC 08/03/2019 Se adiciona parametro.
    psproces IN NUMBER DEFAULT NULL)    --BUG 47494 MPC 08/03/2019 Se adiciona parametro.
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult     VARCHAR2(32000) := '';
    v_tconsulta   VARCHAR2(4000);
    v_tconsulta_1 VARCHAR2(4000) := '';--BUG 47494 MPC 08/03/2019 Se adiciona variable.
    v1            NUMBER;
    v2            NUMBER;
    v_tlinia      VARCHAR2(50);
    v_tlinia1     VARCHAR2(200);
    v_tlinia2     VARCHAR2(200);
    v_tpargar     VARCHAR2(200);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot garanseg.ipritot%TYPE;
    v_porcentot NUMBER;
    v_porceninm NUMBER;
    v_porcencon NUMBER;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
  BEGIN
    v_actividad := 'se.cactivi';
    v_tconsulta := 'SELECT s.cgarant, p.norden, sum(decode(s.cgarant,48,se.cforpag,1)*icaptot) a,sum(ipritot)' || ',NVL(sum((select sum(crespue) from pregungaranseg where sseguro in (select sseguro from seguros where  npoliza = se.npoliza and ncertif !=0 and cpregun in (5851,5852)) and cgarant = s.cgarant)),0) porcentot' || ',NVL(sum((select sum(crespue) from pregungaranseg where sseguro in (select sseguro from seguros where  npoliza = se.npoliza and ncertif !=0 and cpregun in (5851)) and cgarant = s.cgarant)),0) porceninm' || ',NVL(sum((select sum(crespue) from pregungaranseg where sseguro in (select sseguro from seguros where  npoliza = se.npoliza and ncertif !=0 and cpregun in (5852)) and cgarant = s.cgarant)),0) porcencon ';
    v_tconsulta := v_tconsulta || ' FROM garanpro p, productos pp, ';
    --INI BUG 47494 MPC 08/03/2019 Se adiciona condicion.
    IF NVL(ptablas,'POL') = 'CAR' THEN
      --
      v_tconsulta   := v_tconsulta || ' garancar s, seguros se';
      v_tconsulta_1 := ' s.sproces = '||psproces;
      --
    ELSE
      v_tconsulta_1 := v_tconsulta_1 || ' and s.nmovimi = (select max(ga.nmovimi) from garanseg  ga where ga.sseguro =s.sseguro and
ga.nmovimi <= (SELECT MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.SSEGURO = GA.SSEGURO AND MV.CMOVSEG!=3 ';
      v_tconsulta_1 := v_tconsulta_1 || ')) ';
      --FIN BUG 47494 MPC 08/03/2019 Se adiciona condicion.
      v_tconsulta := v_tconsulta || ' garanseg s, seguros se';
    END IF; --BUG 47494 MPC 08/03/2019 Se adiciona condicion.
    v_tconsulta := v_tconsulta || ' WHERE p.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = pp.sproduc';
    --v_tconsulta := v_tconsulta || ' AND se.csituac = 0';
    v_tconsulta := v_tconsulta || ' AND se.csituac in (0,7,5,2)';
    v_tconsulta := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' AND s.sseguro IN (SELECT sseguro FROM seguros';
    v_tconsulta := v_tconsulta || ' WHERE npoliza = (SELECT npoliza FROM seguros WHERE sseguro=  ' || psseguro || ')and ncertif <> 0)';
    --INI BUG 47494 MPC 08/03/2019 Se modifica condiciÃ³n.
    v_tconsulta := v_tconsulta || v_tconsulta_1;
    --v_tconsulta := v_tconsulta || ' and s.nmovimi = (select max(ga.nmovimi) from garanseg  ga where ga.sseguro =s.sseguro and
    --ga.nmovimi <= (SELECT MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.SSEGURO = GA.SSEGURO AND MV.CMOVSEG!=3 ';
    --v_tconsulta := v_tconsulta || ')) ';
    --FIN BUG 47494 MPC 08/03/2019 Se modifica condiciÃ³n.
    -- INI 0039502 - MAV 23/11/2017
    -- La consulta debe usar p.cgarant
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', p.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  /*
  SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
  || sproduc
  || ', '
  || cactivi
  || ', s.cgarant, ''GARANT_IMP''), 0) = 1 )'
  INTO v_tpargar
  FROM
  (SELECT seg.sproduc,
  seg.cactivi
  FROM seguros seg
  WHERE seg.sseguro = psseguro
  );
  */
  -- FIN 0039502 - MAV 23/11/2017
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || 'GROUP BY s.cgarant,p.norden ORDER BY p.norden';
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor
    INTO v1,
      v2,
      v_icaptot,
      v_ipritot,
      v_porcentot,
      v_porceninm,
      v_porcencon;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    v_tlinia   := '';
    v_tlinia1  := '';
    v_tlinia2  := '';
    IF pcampo   = 1 THEN
      v_tlinia := pac_isqlfor_lcol.f_imporignomon(psseguro, v_icaptot);
    END IF;
    IF pcampo   = 2 THEN
      v_tlinia := pac_isqlfor_lcol.f_imporignomon(psseguro, v_ipritot);
    END IF;
    v_tresult       := v_tresult || v_tlinia || '\par ';
    IF v_porcentot   > 0 THEN
      IF v_porceninm > 0 THEN
        IF pcampo    = 3 THEN
          v_tlinia1 := pac_isqlfor_lcol.f_imporignomon(psseguro, (v_icaptot * v_porceninm) / v_porcentot);
        END IF;
        v_tresult := v_tresult || '\tab \tab \tab ' || v_tlinia1 || '\par ';
      END IF;
      IF v_porcencon > 0 THEN
        IF pcampo    = 3 THEN
          v_tlinia2 := pac_isqlfor_lcol.f_imporignomon(psseguro, (v_icaptot * v_porcencon) / v_porcentot);
        END IF;
        v_tresult := v_tresult || '\tab \tab \tab ' || v_tlinia2 || '\par ';
      END IF;
    END IF;
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_certif_glo;
/*****************************************************************
FUNCTION f_importes_riesgo_fi
Devuelve los capitales de un riesgo para fianzas
param IN psseguro  : codigo de seguro
param IN pnriesgo  : n?mero de riesgo
param IN pmodo     : modo EST/POL
return             : texto con los capitales del riesgo
******************************************************************/
FUNCTION f_importes_riesgo_fi(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(4000);
    v_tlinia    VARCHAR2(50);
    -- INI BUG 0035431/0017560-- ECP -- 13/04/2015 - Se cambia v_tpargar      VARCHAR2(200); por
    v_tpargar VARCHAR2(300);
    -- FIN BUG 0035431/0017560 -- ECP -- 13/04/2015
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot VARCHAR2(200);
    v_ctipcap garanpro.ctipcap%TYPE;
    v_cimpres garanpro.cimpres%TYPE;
    v_npargar   NUMBER := 0;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
    v_es_admin  NUMBER; --Bug 33145/192146 - 03/12/2014 - AMC
    nerror      NUMBER; --BUG 33488/196537 - 26/01/2015 - AMC
    vncertif    NUMBER;
  BEGIN
    -- BUG 16092 - 12/01/2011 - JMP - AGA RC: Miramos si las garant?as est?n definidas para la actividad del seguro
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := 'SELECT pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d';
    ELSE
      v_tconsulta := 'SELECT pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot) d';
    END IF;
    v_tconsulta         := v_tconsulta || ' FROM  garangen g, garanpro p, productos pp, ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' estgaranseg s, estseguros se';
      v_csituac         := '(0,7,5,2,4)';
    ELSE
      v_tconsulta := v_tconsulta || ' garanseg s, seguros se';
      /*IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
      v_csituac := '(0,7,5,2,4)';
      ELSE*/
      v_csituac := '(0,7,5,2,4)';
      --END IF;
    END IF;
    v_tconsulta := v_tconsulta || ' WHERE g.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = pp.sproduc';
    v_tconsulta := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' AND se.csituac in ' || v_csituac;
    --v_tconsulta := v_tconsulta || ' AND s.ffinefe IS NULL';
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      --Bug 33145/192146 - 03/12/2014 - AMC
      v_es_admin := pac_seguros.f_es_col_admin(psseguro, 'EST');
      --BUG 33488/196537 - 26/01/2015 - AMC
      SELECT ncertif
      INTO vncertif
      FROM estseguros
      WHERE sseguro  = psseguro;
    IF v_es_admin    = 1 AND vncertif <> 0 THEN
      v_tconsulta   := v_tconsulta || ' AND s.cobliga = 1';
      v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg ga WHERE sseguro =' || psseguro;
      v_tconsulta   := v_tconsulta || ' and ga.nmovimi <= (SELECT MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.SSEGURO = GA.SSEGURO AND MV.CMOVSEG!=3 AND MV.NMOVIMI =(select max(nmovimi_cert) from detmovsegurocol WHERE sseguro_0 = ' || psseguro || ' and sseguro_cert =ga.sseguro ';
      IF (pnmovimi  IS NOT NULL) THEN
        v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || '))) ';
      ELSE
        v_tconsulta := v_tconsulta || ')))';
      END IF;
    ELSE
      v_tconsulta   := v_tconsulta || ' AND s.cobliga = 1';
      v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg WHERE sseguro =' || psseguro;
      IF (pnmovimi  IS NOT NULL) THEN
        v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
        v_tconsulta := v_tconsulta || ')';
      END IF;
    END IF;
    --Fi Bug 33145/192146 - 03/12/2014 - AMC
    -- INI 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo  -- INI BUG 0035431/0017560 -- ECP -- 13/04/2015 - Se agrega condiciÃ¿Â³n para mostrar la garantÃ¿Â­a Cobertura al deducible en Suplemento
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
      --|| ', g.cgarant, ''GARANT_IMP''), 0) = 1 OR exists (select 1 from garanseg where sseguro = s.sseguro and nmovimi = s.nmovimi and cgarant = 777 and iprianu <> 0))'
      -- FIN 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo  -- FIN BUG 0035431/0017560 -- ECP -- 13/04/2015
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM estseguros seg
      WHERE seg.sseguro = psseguro
      );
  ELSE
    --Bug 33145/192146 - 03/12/2014 - AMC
    v_es_admin := pac_seguros.f_es_col_admin(psseguro, 'POL');
    --BUG 33488/196537 - 26/01/2015 - AMC
    SELECT ncertif
    INTO vncertif
    FROM seguros
    WHERE sseguro    = psseguro;
    IF v_es_admin    = 1 AND vncertif <> 0 THEN
      v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM garanseg ga WHERE sseguro =' || psseguro;
      v_tconsulta   := v_tconsulta || ' and ga.nmovimi <= (SELECT MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.SSEGURO = GA.SSEGURO AND MV.CMOVSEG!=3 AND MV.NMOVIMI =(select max(nmovimi_cert) from detmovsegurocol WHERE sseguro_0 = ' || psseguro || ' and sseguro_cert =ga.sseguro ';
      IF (pnmovimi  IS NOT NULL) THEN
        v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || '))) ';
      ELSE
        v_tconsulta := v_tconsulta || ')))';
      END IF;
    ELSE
      v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM garanseg WHERE sseguro =' || psseguro;
      IF (pnmovimi  IS NOT NULL) THEN
        v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
        v_tconsulta := v_tconsulta || ')';
      END IF;
    END IF;
    --Fi Bug 33145/192146 - 03/12/2014 - AMC
    -- INI 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo  -- INI BUG 0035431/0017560 -- ECP -- 13/04/2015
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
      --|| ', g.cgarant, ''GARANT_IMP''), 0) = 1 OR exists (select 1 from garanseg where sseguro = s.sseguro and nmovimi = s.nmovimi and cgarant = 777 and iprianu <> 0))'
      -- FIN 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo  -- FIN BUG 0035431/0017560 -- ECP -- 13/04/2015
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  END IF;
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor
    INTO v_tlinia,
      v_icaptot,
      v_ctipcap,
      v_cimpres,
      v_npargar,
      v_ipritot;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF v_npargar = 1 AND v_icaptot = 0 THEN
      SELECT tatribu
      INTO v_tlinia
      FROM detvalores
      WHERE cvalor = 126
      AND catribu  = NVL(v_cimpres, 59) -- INCLOSA
      AND cidioma  = NVL(pcidioma, 8);
    END IF;
    IF pcampo   = 2 THEN
      v_tlinia := v_ipritot;
    END IF;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_riesgo_fi;
/*****************************************************************
FUNCTION f_garantias_riesgo_fi
Devuelve las garant?as de un riesgo
param IN psseguro  : codigo de seguro
param IN pnriesgo  : n?mero de riesgo
param IN pcidioma  : codigo de idioma
param IN pmodo     : modo EST/POL
return             : texto con las garant?as del riesgo
******************************************************************/
FUNCTION f_garantias_riesgo_fi(
    psseguro IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(2000);
    v_tlinia    VARCHAR2(200);
    -- INI BUG 0035054/0017140 -- ECP -- 11/03/2015 - Se cambia v_tpargar      VARCHAR2(200); por
    v_tpargar VARCHAR2(300);
    -- FIN BUG 0035054/0017140 -- ECP -- 11/03/2015
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
    v_es_admin  NUMBER; --Bug 33145/192146 - 03/12/2014 - AMC
  BEGIN
    -- BUG 16092 - 12/01/2011 - JMP - AGA RC: Miramos si las garant?as est?n definidas para la actividad del seguro
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    v_tconsulta         := 'SELECT REPLACE(pac_isqlfor_lcol.f_des_garpro(se.sseguro,s.nriesgo,' || NVL(pcidioma, 2) || ',p.cgarant,se.sproduc,''' || pmodo || '''), CHR(39), CHR(39) || CHR(39)) a';
    v_tconsulta         := v_tconsulta || ' FROM garanpro p, ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || 'estgaranseg s, estseguros se';
      v_csituac         := '(0,7,5,2,4)';
    ELSE
      v_tconsulta := v_tconsulta || 'garanseg s, seguros se';
      /*IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
      v_csituac := '(0,7,5,2,4)';
      ELSE*/
      v_csituac := '(0,7,5,2,4)';
      --END IF;
    END IF;
    v_tconsulta         := v_tconsulta || ' WHERE p.cgarant = s.cgarant';
    v_tconsulta         := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta         := v_tconsulta || ' AND p.CACTIVI = ' || v_actividad;
    v_tconsulta         := v_tconsulta || ' AND se.csituac in ' || v_csituac;
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      --Bug 33145/192146 - 03/12/2014 - AMC
      v_es_admin      := pac_seguros.f_es_col_admin(psseguro, 'EST');
      IF v_es_admin    = 1 THEN
        v_tconsulta   := v_tconsulta || ' AND s.cobliga = 1 and s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg ga WHERE sseguro =' || psseguro;
        v_tconsulta   := v_tconsulta || ' AND ga.nmovimi <= (SELECT MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.SSEGURO = GA.SSEGURO AND MV.CMOVSEG!=3 AND MV.NMOVIMI =(select max(nmovimi_cert) from detmovsegurocol WHERE sseguro_0 = ' || psseguro; -- || ' and sseguro_cert =ga.sseguro ';
        IF (pnmovimi  IS NOT NULL) THEN
          v_tconsulta := v_tconsulta || ' AND nmovimi_0 <=' || pnmovimi || '))) ';
        ELSE
          v_tconsulta := v_tconsulta || ')))';
        END IF;
      ELSE
        v_tconsulta   := v_tconsulta || ' AND s.cobliga = 1 and s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg WHERE sseguro =' || psseguro;
        IF (pnmovimi  IS NOT NULL) THEN
          v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
        ELSE
          v_tconsulta := v_tconsulta || ')';
        END IF;
      END IF;
      --Fi Bug 33145/192146 - 03/12/2014 - AMC
      -- INI 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo  -- INI BUG 00350431/0017560 -- ECP -- 13/04/2015 - Se agrega condiciÃ¿Â³n para mostrar la garantÃ¿Â­a Cobertura al deducible en Suplemento
      SELECT ' AND ((NVL(pac_parametros.f_pargaranpro_n('
        || sproduc
        || ', '
        || cactivi
        || ', p.cgarant, ''GARANT_IMP''), 0) = 1) )'
        --|| ', p.cgarant, ''GARANT_IMP''), 0) = 1) OR exists (select 1 from garanseg where sseguro = s.sseguro and nmovimi = s.nmovimi and cgarant = 777 and iprianu <> 0))'
        -- INI 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo  -- FIN BUG 0035431/0017560 -- ECP -- 13/04/2015
      INTO v_tpargar
      FROM
        (SELECT seg.sproduc,
          seg.cactivi
        FROM estseguros seg
        WHERE seg.sseguro = psseguro
        );
  ELSE
    --Bug 33145/192146 - 03/12/2014 - AMC
    v_es_admin      := pac_seguros.f_es_col_admin(psseguro, 'POL');
    IF v_es_admin    = 1 THEN
      v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG ga WHERE sseguro =' || psseguro;
      v_tconsulta   := v_tconsulta || '  and ga.nmovimi <= (SELECT MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.SSEGURO = GA.SSEGURO AND MV.CMOVSEG!=3 AND MV.NMOVIMI =(select max(nmovimi_cert) from detmovsegurocol WHERE sseguro_0 = ' || psseguro; -- || ' and sseguro_cert =ga.sseguro ';
      IF (pnmovimi  IS NOT NULL) THEN
        v_tconsulta := v_tconsulta || ' AND nmovimi_0 <=' || pnmovimi || '))) ';
      ELSE
        v_tconsulta := v_tconsulta || ')))';
      END IF;
    ELSE
      v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro;
      IF (pnmovimi  IS NOT NULL) THEN
        v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
        v_tconsulta := v_tconsulta || ')';
      END IF;
    END IF;
    --Fi Bug 33145/192146 - 03/12/2014 - AMC
    -- INI 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo  -- INI BUG 0035054/0017140 -- ECP -- 11/03/2015 - Se agrega condiciÃ¿Â³n para mostrar la garantÃ¿Â­a Cobertura al deducible en Suplemento
    SELECT ' AND ((NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', p.cgarant, ''GARANT_IMP''), 0) = 1) )'
      --|| ', p.cgarant, ''GARANT_IMP''), 0) = 1) OR exists (select 1 from garanseg where sseguro = s.sseguro and nmovimi = s.nmovimi and cgarant = 777 and iprianu <> 0))'
      -- FIN 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo  -- FIN BUG 0035054/0017140 -- ECP -- 11/03/2015
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  END IF;
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_tlinia;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_garantias_riesgo_fi;
--INI BUG 0035431/0203621 - 29/04/2015 - JAE - Formato numÃ¿Â©rico
/************************************************************************
FUNCTION fu_formato
param IN p_valor    : Valor
param IN p_ind_rep  : Ã¿Â¿ltimo dÃ¿Â­gito no significativo [1 - 0] (Default 1)
param IN p_dg_dec   : Cantidad de dÃ¿Â­gitos decimales. (Default 2)
param IN p_ind_dec  : Decimales no significativos.   [1 - 0] (Default 0)
Return              : NÃ¿Âºmero formateado (Varchar)
*************************************************************************/
FUNCTION fu_formato(
    p_valor   IN NUMBER,
    p_ind_rep IN NUMBER DEFAULT 1,
    p_dg_dec  IN NUMBER DEFAULT 2,
    p_ind_dec IN NUMBER DEFAULT 1)
  RETURN VARCHAR2
IS
  --
  v_cadena_base VARCHAR2(50) := 'FM999G999G999G999G99';
  v_cadena_dec  VARCHAR2(50) := NULL;
  v_formato     VARCHAR2(50);
  --
BEGIN
  --Ã¿Â¿ltimo dÃ¿Â­gito significativo
  IF p_ind_rep = 1 THEN
    --
    v_formato := v_cadena_base || '0';
    --
  ELSE
    --
    v_formato := v_cadena_base || '9';
    --
  END IF;
  --
  --DÃ¿Â­gitos decimales
  IF p_dg_dec > 0 THEN
    --
    FOR i IN 1 .. p_dg_dec
    LOOP
      --
      --Decimales significativos
      IF p_ind_dec = 1 THEN
        --
        v_cadena_dec := v_cadena_dec || '0';
        --
      ELSE
        --
        v_cadena_dec := v_cadena_dec || '9';
        --
      END IF;
      --
    END LOOP;
    --
    v_formato := v_formato || 'D' || v_cadena_dec;
    --
  END IF;
  --
  RETURN (TO_CHAR(p_valor, v_formato));
  --
END fu_formato;
--FIN BUG 0035431/0203621 - 29/04/2015 - JAE - Formato numÃ¿Â©rico
--
--INI BUG 17370 - 17/09/2015 - SYT - prima total vigente del seguro.
/************************************************************************
FUNCTION f_prima_vigencia_total
param IN v_sseguro  : Seguro
Return              : valor total de la prima vigente para el seguro(Number)
*************************************************************************/
FUNCTION f_prima_vigencia_total(
    v_sseguro IN NUMBER)
  RETURN NUMBER
IS
  iprivigencia NUMBER := 0;
  vxpro_np_360 NUMBER;
  vdifdias     NUMBER;
  vnum_err     NUMBER;
  v_ini        DATE;
  v_fin        DATE;
  v_itotalr    NUMBER;
  v_csituac    NUMBER;
  v_fecperiodo VARCHAR2(7);
BEGIN
  BEGIN
    SELECT s.csituac,
      s.fefecto,
      s.frenova,
      s.iprianu
    INTO v_csituac,
      v_ini,
      v_fin,
      v_itotalr
    FROM seguros s
    WHERE s.sseguro = v_sseguro;
  EXCEPTION
  WHEN NO_DATA_FOUND THEN
    BEGIN
      SELECT s.csituac,
        s.fefecto,
        s.frenova,
        s.iprianu
      INTO v_csituac,
        v_ini,
        v_fin,
        v_itotalr
      FROM estseguros s
      WHERE s.sseguro = v_sseguro;
    EXCEPTION
    WHEN OTHERS THEN
      RETURN 0;
    END;
  WHEN OTHERS THEN
    RETURN 0;
  END;
  IF v_csituac             <> 2 THEN
    vxpro_np_360           := f_parinstalacion_n('PRO_NP_360');
    IF NVL(vxpro_np_360, 1) = 1 THEN
      vnum_err             := f_difdata(v_ini, v_fin, 3, 3, vdifdias);
      iprivigencia         := (vdifdias * v_itotalr) / 360;
    ELSE
      vnum_err     := f_difdata(v_ini, v_fin, 1, 3, vdifdias);
      iprivigencia := (vdifdias * v_itotalr) / 365;
    END IF;
    iprivigencia := f_round(iprivigencia, 8);
  END IF;
  RETURN iprivigencia;
EXCEPTION
WHEN OTHERS THEN
  RETURN 0;
END f_prima_vigencia_total;
--FIN BUG 17370 - 17/04/2015 - SYT
FUNCTION f_condgen_rie(
    psseguro IN NUMBER,
    pnriesgo IN NUMBER,
    pefecto  IN DATE,
    ptabla   IN VARCHAR2 DEFAULT 'POL')
  RETURN VARCHAR2
IS
  vret     VARCHAR2(255);
  vcrespue NUMBER;
BEGIN
  IF ptabla = 'POL' THEN
    BEGIN
      SELECT crespue
      INTO vcrespue
      FROM pregunseg
      WHERE cpregun = 4777
      AND sseguro   = psseguro
      AND nriesgo   = pnriesgo
      AND nmovimi   = pac_isqlfor.f_max_nmovimi(psseguro, 1); --QT 0016974 es unmovimiento de anulaciÃ¿Â³n el ultimo y debe coger el max de garanseg no de movseguro.
      SELECT cclausu INTO vret FROM condicionadoprod WHERE ccondicio = vcrespue;
    EXCEPTION
      -- Bug 21780 - RSC - 20/03/2012 - LCOL_T004 - Ajuste parametrizaci?n plantillas del producto Seguro Saldado y Seguro Prorrogado
    WHEN NO_DATA_FOUND THEN
      BEGIN
        SELECT crespue
        INTO vcrespue
        FROM pregunseg
        WHERE cpregun = 4775
        AND sseguro   = psseguro
        AND nriesgo   = pnriesgo
        AND nmovimi   = pac_isqlfor.f_max_nmovimi(psseguro, 1); --QT 0016974 es unmovimiento de anulaciÃ¿Â³n el ultimo y debe coger el max de garanseg no de movseguro.
        SELECT cclausu INTO vret FROM condicionadoprod WHERE ccondicio = vcrespue;
      EXCEPTION
      WHEN NO_DATA_FOUND THEN
        BEGIN
          SELECT crespue
          INTO vcrespue
          FROM pregunseg
          WHERE cpregun = 4019
          AND sseguro   = psseguro
          AND nriesgo   = pnriesgo
          AND nmovimi   = pac_isqlfor.f_max_nmovimi(psseguro, 1); --QT 0016974 es unmovimiento de anulaciÃ¿Â³n el ultimo y debe coger el max de garanseg no de movseguro.
          SELECT cclausu INTO vret FROM condicionadoprod WHERE ccondicio = vcrespue;
        EXCEPTION
          -- Fin Bug 21780
        WHEN NO_DATA_FOUND THEN
          SELECT cp.cclausu
          INTO vret
          FROM seguros s,
            condicionadoprod cp
          WHERE s.sseguro = psseguro
          AND s.sproduc   = cp.sproduc
          AND pefecto BETWEEN cp.finiefe AND NVL(cp.ffinefe, pefecto)
          AND ROWNUM = 1
          GROUP BY cp.cclausu
          ORDER BY 1;
        END;
      END;
    END;
  ELSE
    BEGIN
      SELECT crespue
      INTO vcrespue
      FROM estpregunseg
      WHERE cpregun = 4777
      AND sseguro   = psseguro
      AND nriesgo   = pnriesgo
      AND nmovimi   = pac_isqlfor.f_max_nmovimi(psseguro);
      SELECT cclausu INTO vret FROM condicionadoprod WHERE ccondicio = vcrespue;
    EXCEPTION
      -- Bug 21780 - RSC - 20/03/2012 - LCOL_T004 - Ajuste parametrizaci?n plantillas del producto Seguro Saldado y Seguro Prorrogado
    WHEN NO_DATA_FOUND THEN
      BEGIN
        SELECT crespue
        INTO vcrespue
        FROM estpregunseg
        WHERE cpregun = 4775
        AND sseguro   = psseguro
        AND nriesgo   = pnriesgo
        AND nmovimi   = pac_isqlfor.f_max_nmovimi(psseguro);
        SELECT cclausu INTO vret FROM condicionadoprod WHERE ccondicio = vcrespue;
      EXCEPTION
      WHEN NO_DATA_FOUND THEN
        BEGIN
          SELECT crespue
          INTO vcrespue
          FROM estpregunseg
          WHERE cpregun = 4019
          AND sseguro   = psseguro
          AND nriesgo   = pnriesgo
          AND nmovimi   = pac_isqlfor.f_max_nmovimi(psseguro);
          SELECT cclausu INTO vret FROM condicionadoprod WHERE ccondicio = vcrespue;
        EXCEPTION
          -- Fin Bug 21780
        WHEN NO_DATA_FOUND THEN
          SELECT cp.cclausu
          INTO vret
          FROM estseguros s,
            condicionadoprod cp
          WHERE s.sseguro = psseguro
          AND s.sproduc   = cp.sproduc
          AND pefecto BETWEEN cp.finiefe AND NVL(cp.ffinefe, pefecto)
          AND ROWNUM = 1
          GROUP BY cp.cclausu
          ORDER BY 1;
        END;
      END;
    END;
  END IF;
  RETURN f_jrep_trad(vret);
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_condgen_rie;
--INTEGRACIÃ¿Â¿N--LIB_LCOL_1524- Ini
FUNCTION f_clausula_ggbb(
    pversion IN NUMBER,
    pclausul IN NUMBER,
    pval     IN NUMBER)
  RETURN VARCHAR2
IS
  vtclatext ggbb_clausulas.tclatext%TYPE;
BEGIN
  SELECT cl.tclatext
  INTO vtclatext
  FROM ggbb_clausulas cl
  WHERE cl.nclausul = pclausul
  AND (cl.ctipo     = 'CU'
  AND cl.cobliga    = 1
  OR (cl.cobliga    = 0
  AND EXISTS
    (SELECT '1'
    FROM ggbb_clausulas_gb
    WHERE nclausul = cl.nclausul
    AND ctipo      = 'CU'
    AND nversion   = pversion
    )));
  IF vtclatext  IS NOT NULL THEN
    IF pclausul  = 35 THEN
      vtclatext := REPLACE(vtclatext, '#LIMVAL#', pval);
    END IF;
    RETURN f_jrep_trad(vtclatext);
  ELSE
    RETURN f_jrep_trad(vtclatext);
  END IF;
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_clausula_ggbb;
FUNCTION f_garantias_ggbb(
    pversion IN NUMBER)
  RETURN VARCHAR2
IS
  v_tresult VARCHAR2(32000) := '';
BEGIN
  FOR x IN
  (SELECT gg.tgarant
  FROM ggbb_detalle d,
    garangen gg
  WHERE gg.cgarant = d.ccla1
  AND d.nversion   = pversion
  AND d.csubtab    = 3160
  AND gg.cidioma   = f_usu_idioma
  ORDER BY ccla1
  )
  LOOP
    v_tresult := v_tresult || x.tgarant || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_garantias_ggbb;
FUNCTION f_tasas_ggbb(
    pversion IN NUMBER)
  RETURN VARCHAR2
IS
  v_tresult VARCHAR2(32000) := '';
BEGIN
  FOR x IN
  (SELECT DECODE(nval2, NULL, nval4, nval2) val
  FROM ggbb_detalle d
  WHERE d.nversion = pversion
  AND d.csubtab    = 3160
  ORDER BY ccla1
  )
  LOOP
    v_tresult := v_tresult || x.val || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_tasas_ggbb;
FUNCTION f_clausu_tot_ggbb(
    pversion IN NUMBER)
  RETURN VARCHAR2
IS
  v_tresult VARCHAR2(32000) := '';
BEGIN
  FOR x  IN
  (SELECT *
  FROM
    (SELECT nclausul,
      tclatext,
      1 tipo
    FROM ggbb_clausulas
    WHERE ctipo = 'CU'
    AND cobliga = 1
    UNION
    SELECT a.nclausul,
      a.tclatext,
      2 tipo
    FROM ggbb_clausulas a,
      ggbb_clausulas_gb b
    WHERE b.ctipo  = a.ctipo
    AND b.nclausul = a.nclausul
    AND nversion   = pversion
    AND a.ctipo    = 'CU'
    AND a.cobliga  = 0
    ) clau
  WHERE nclausul NOT IN (35, 36, 40, 10, 9, 4, 37, 38, 39)
  ORDER BY tipo,
    nclausul
  )
  LOOP
    v_tresult := v_tresult || x.tclatext || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_clausu_tot_ggbb;
--INTEGRACIÃ¿Â¿N--LIB_LCOL_1524- Fin
--INICIO (24472-130627):JMC 27/05/2016 se aÃ¿Â±aden funciones
FUNCTION f_desacc_cot(
    ptacc IN VARCHAR2,
    ptipo IN VARCHAR2)
  RETURN VARCHAR2
IS
  preturn VARCHAR2(4000) := NULL;
  v_reg int_carga_generico%ROWTYPE;
  vcampo   NUMBER;
  vlong    NUMBER := 0;
  v_posant NUMBER := 1;
  vfirst   NUMBER := 1;
BEGIN
  IF ptacc   IS NOT NULL THEN
    v_posant := 1;
    v_reg    := NULL;
    vcampo   := 2;
    FOR y IN 1 .. LENGTH(ptacc)
    LOOP
      IF SUBSTR(ptacc, y, 1)                            IN ('#', '&') OR y = LENGTH(ptacc) THEN
        vcampo                                 := vcampo + 1;
        IF y                                    = LENGTH(ptacc) THEN
          vlong                                := (y + 1) - v_posant;
        ELSE
          vlong := y - v_posant;
        END IF;
        CASE vcampo
        WHEN 3 THEN
          v_reg.campo03 := SUBSTR(ptacc, v_posant, vlong);
        WHEN 4 THEN
          v_reg.campo06 := SUBSTR(ptacc, v_posant, vlong);
        WHEN 5 THEN
          v_reg.campo04 := SUBSTR(ptacc, v_posant, vlong);
        ELSE
          NULL;
        END CASE;
        v_posant              := y + 1;
        IF SUBSTR(ptacc, y, 1) = '&' OR y = LENGTH(ptacc) THEN
          IF ptipo             = 'A' THEN
            BEGIN
              SELECT taccesorio
              INTO v_reg.campo20
              FROM aut_accesorios
              WHERE caccesorio = v_reg.campo03;
            EXCEPTION
            WHEN OTHERS THEN
              v_reg.campo20 := 'Codigo Accesorio Incorrecto';
            END;
          ELSE
            BEGIN
              SELECT tdispositivo
              INTO v_reg.campo20
              FROM aut_dispositivos
              WHERE cdispositivo = v_reg.campo03;
            EXCEPTION
            WHEN OTHERS THEN
              v_reg.campo20 := 'Codigo Dispositivo Incorrecto';
            END;
          END IF;
          IF vfirst = 1 THEN
            --preturn := preturn || v_reg.campo20;
            vfirst := 0;
          ELSE
            preturn := preturn || '&'; --CHR (10); -- || v_reg.campo20;
          END IF;
          IF ptipo   = 'A' THEN
            preturn := preturn || v_reg.campo03 || '-' || v_reg.campo20 || ' (' || ff_desvalorfijo(292, 8, v_reg.campo04) || ') :' || v_reg.campo06;
          ELSE
            preturn := preturn || v_reg.campo03 || '-' || v_reg.campo20 || ' (' || ff_desvalorfijo(8000912, 8, v_reg.campo06) || ') ';
          END IF;
          vcampo := 2;
          IF y    = LENGTH(ptacc) OR (y = LENGTH(ptacc) AND SUBSTR(ptacc, y, 1) = '&') THEN
            EXIT;
          END IF;
        END IF;
      END IF;
    END LOOP;
  END IF;
  RETURN preturn;
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_desacc_cot;
FUNCTION f_desgar_cot(
    pcgarant IN NUMBER)
  RETURN VARCHAR2
IS
  preturn VARCHAR2(1000);
BEGIN
  SELECT tgarant
  INTO preturn
  FROM garangen
  WHERE cgarant = pcgarant
  AND cidioma   = 8;
  preturn      := preturn || '(' || pcgarant || ')';
  RETURN preturn;
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_desgar_cot;
