/*****************************************************************
FUNCTION f_ult_direccion
Devuelve la ultima direcciÃ¿Â³n seleccionada para el tomador Ã¿Â³ asegurado Ã¿Â³ conductor
param IN psseguro  : codigo de seguro
param IN psperson  : codigo de la persona
return             : direcciÃ¿Â³n actualizada
Bug 37950/0019273 - 15/10/2015
******************************************************************/
FUNCTION f_ult_direccion(
    psseguro IN NUMBER,
    psperson IN NUMBER)
  RETURN VARCHAR2
IS
  vnmotmov NUMBER;
  vndomici NUMBER;
  vtdomici per_direcciones.tdomici%TYPE;
  nerror NUMBER;
BEGIN
  SELECT m.cmotmov
  INTO vnmotmov
  FROM movseguro m
  WHERE m.sseguro = psseguro
  AND m.fmovimi   =
    (SELECT MAX(mx.fmovimi)
    FROM movseguro mx
    WHERE mx.cmotmov IN (426, 673, 677)
    AND mx.sseguro    = psseguro
    );
  IF vnmotmov = 677 THEN
    BEGIN
      SELECT cdomici
      INTO vndomici
      FROM asegurados
      WHERE sseguro = psseguro
      AND sperson   = psperson;
    EXCEPTION
    WHEN NO_DATA_FOUND THEN
      vndomici := 0;
    WHEN OTHERS THEN
      vndomici := 0;
    END;
  ELSIF vnmotmov = 673 THEN
    BEGIN
      SELECT cdomici
      INTO vndomici
      FROM tomadores
      WHERE sseguro = psseguro
      AND sperson   = psperson;
    EXCEPTION
    WHEN NO_DATA_FOUND THEN
      vndomici := 0;
    WHEN OTHERS THEN
      vndomici := 0;
    END;
  ELSIF vnmotmov = 426 THEN
    BEGIN
      SELECT ac.cdomici
      INTO vndomici
      FROM autconductores ac
      WHERE ac.sseguro = psseguro
      AND ac.sperson   = psperson
      AND ac.nmovimi   =
        (SELECT MAX(ax.nmovimi)
        FROM autconductores ax
        WHERE ax.sseguro = psseguro
        AND ax.sperson   = psperson
        );
    EXCEPTION
    WHEN NO_DATA_FOUND THEN
      vndomici := 0;
    WHEN OTHERS THEN
      vndomici := 0;
    END;
  END IF;
  IF vnmotmov > 0 AND vndomici > 0 THEN
    vtdomici := pac_isqlfor_lcol.f_direccion(psperson, NVL(vndomici, 1), 'POL');
  END IF;
  RETURN vtdomici;
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_ult_direccion;
