/*****************************************************************
FUNCTION f_clausulas_vid_indi
Devuelve las clausualas para el productos vida individual
param IN psseguro  : codigo de seguro
param IN pnmovimi  : codigo de movimiento
param IN pcidioma  : codigo de idioma
param IN ptabla    : codigo de tabla 'est' o 'pol'
return             : Clausalas
Bug 0024062 - 16/02/2016
******************************************************************/
-- INI BUG 0024062 - 16/02/2016 - CALL
FUNCTION f_clausulas_vid_indi(
    psseguro  IN NUMBER,
    pnmovimi  IN NUMBER,
    pcidioma  IN NUMBER,
    ptabla    IN VARCHAR2 DEFAULT 'POL',
    pcduplica IN NUMBER DEFAULT 0)
  RETURN CLOB
IS
  vret CLOB;
BEGIN
  IF ptabla = 'POL' THEN
    FOR i IN
    (SELECT clau,
      nordcla
    FROM
      (SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        c.nordcla
      FROM clausugen cg,
        claususeg c
      WHERE cg.sclagen = c.sclagen
      AND c.sseguro    = psseguro
      AND c.nmovimi    =
        (SELECT MAX(nmovimi)
        FROM claususeg
        WHERE sseguro = psseguro
        AND nmovimi  <= pnmovimi
        )
      AND cg.cidioma = pcidioma
      AND (((SELECT fefecto
        FROM movseguro
        WHERE sseguro = psseguro
        AND nmovimi   = pnmovimi) BETWEEN c.finiclau AND NVL(c.ffinclau, SYSDATE + 365))
      AND ((SELECT fefecto
        FROM movseguro
        WHERE sseguro = psseguro
        AND nmovimi   = pnmovimi) >= c.finiclau
      AND c.ffinclau IS NULL))
      UNION
      SELECT REPLACE(REPLACE(REGEXP_REPLACE(tclaesp, '[[:space:]][[:space:]]*', ' '),'<br><br>','<br>'),'<br>','\par ') clau,--AITSSD-8394 GZG 09/03/2026
        nordcla
      FROM clausuesp
      WHERE sseguro = psseguro
      AND nmovimi   =
        (SELECT MAX(nmovimi)
        FROM clausuesp
        WHERE sseguro = psseguro
        AND nmovimi  <= pnmovimi
        AND sclagen  IS NULL
        )
      AND (((SELECT fefecto
        FROM movseguro
        WHERE sseguro = psseguro
        AND nmovimi   = pnmovimi) BETWEEN finiclau AND NVL(ffinclau, SYSDATE + 365))
      AND ((SELECT fefecto
        FROM movseguro
        WHERE sseguro = psseguro
        AND nmovimi   = pnmovimi) >= finiclau
      AND ffinclau   IS NULL))
      AND sclagen    IS NULL
      UNION
      SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        c.nordcla
      FROM clausugen cg,
        clausuesp c,
        seguros s
      WHERE s.sseguro = c.sseguro
      AND cg.sclagen  = c.sclagen
      AND c.sseguro   = psseguro
      AND c.nmovimi   =
        (SELECT MAX(nmovimi)
        FROM clausuesp
        WHERE sseguro = psseguro
        AND nmovimi  <= pnmovimi
        AND sclagen  IS NOT NULL
        )
      AND c.sclagen IS NOT NULL
      AND cg.cidioma = pcidioma
      AND (((SELECT fefecto
        FROM movseguro
        WHERE sseguro = psseguro
        AND nmovimi   = pnmovimi) BETWEEN c.finiclau AND NVL(c.ffinclau, SYSDATE + 365))
      AND ((SELECT fefecto
        FROM movseguro
        WHERE sseguro = psseguro
        AND nmovimi   = pnmovimi) >= c.finiclau
      AND c.ffinclau IS NULL))
      AND (s.cramo   <> 103
      OR ncertif      = 0)
      ORDER BY nordcla
      )
    GROUP BY clau,
      nordcla
    ORDER BY nordcla
    )
    LOOP
      vret := vret || i.clau || ' \par \par ';
    END LOOP;
  ELSE
    FOR i IN
    (SELECT clau,
      nordcla
    FROM
      (SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        c.nordcla
      FROM clausugen cg,
        estclaususeg c
      WHERE cg.sclagen = c.sclagen
      AND c.sseguro    = psseguro
      AND c.nmovimi    = pnmovimi
      AND cg.cidioma   = pcidioma
      UNION
      SELECT REPLACE(REPLACE(REGEXP_REPLACE(tclaesp, '[[:space:]][[:space:]]*', ' '),'<br><br>','<br>'),'<br>','\par ') clau,--AITSSD-8394 GZG 09/03/2026
        nordcla
      FROM estclausuesp
      WHERE sseguro = psseguro
      AND nmovimi   = pnmovimi
      AND sclagen  IS NULL
      UNION
      SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        c.nordcla
      FROM clausugen cg,
        estclausuesp c,
        estseguros s
      WHERE s.sseguro = c.sseguro
      AND cg.sclagen  = c.sclagen
      AND c.sseguro   = psseguro
      AND c.nmovimi   = pnmovimi
      AND c.sclagen  IS NOT NULL
      AND cg.cidioma  = pcidioma
      AND (s.cramo   <> 103
      OR ncertif      = 0)
      ORDER BY nordcla
      )
    GROUP BY clau,
      nordcla
    ORDER BY nordcla
    )
    LOOP
      vret := vret || i.clau || ' \par \par ';
    END LOOP;
  END IF;
  IF pnmovimi > 1 AND pcduplica = 0 THEN
    vret     := vret || f_descsup(psseguro, pnmovimi);
  END IF;
  RETURN TO_CLOB(f_jrep_trad(vret));
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_clausulas_vid_indi;
