IS
  --
  v_valaseg garanseg.icaptot%TYPE;
  --
BEGIN
  --
  --INI BUG 0032676 - 02/05/2017 - CASL - se filtra por el ultimo movimiento.
  --
  SELECT MAX(g.icaptot)
  INTO v_valaseg
  FROM garanseg g
  WHERE g.sseguro = psseguro
  AND g.cgarant   = pcgarant
  AND g.nmovimi   =
    (SELECT MAX(nmovimi) FROM garanseg WHERE sseguro = g.sseguro
    );
  --
  --FIN BUG 0032676 - 02/05/2017 - CASL
  --
  RETURN v_valaseg;
  --
EXCEPTION
WHEN OTHERS THEN
  --
  RETURN 0;
  --
END;
--
/****************************************************************************
f_get_plan: Obtiene el plan del colectivo para
la tabla map_tabla con ctabla 400002
****************************************************************************/
--
FUNCTION f_get_plan(
    pnpoliza   IN seguros.npoliza%TYPE,
    pncertif   IN seguros.ncertif%TYPE,
    pcpregunta IN preguntas.cpregun%TYPE)
  RETURN VARCHAR2
IS
  --
  v_plan VARCHAR2(200);
  --
BEGIN
  --
  SELECT SUBSTR(
    ( SELECT DISTINCT r.tnatrie -- BUG 29065 - GNRZ  - 23/11/2016  - 71
    FROM riesgos r,
      seguros s
    WHERE r.sseguro = s.sseguro
    AND s.npoliza   = pnpoliza
    AND s.ncertif   = 0
    AND r.fanulac  IS NULL
    AND r.nriesgo   =
      (SELECT crespue
      FROM pregunpolseg
      WHERE sseguro =
        (SELECT sseguro FROM seguros WHERE npoliza = pnpoliza AND ncertif = pncertif
        )
      AND cpregun = pcpregunta
      AND nmovimi =
        (SELECT MAX(nmovimi)
        FROM pregunpolseg
        WHERE sseguro =
          (SELECT sseguro FROM seguros WHERE npoliza = pnpoliza AND ncertif = pncertif
          )
        AND cpregun = pcpregunta
        )
      )
    ), 1, 200)
  INTO v_plan -- BUG 29065 - GNRZ  - 23/11/2016         - 71
  FROM DUAL;
  --  ORDER BY r.nriesgo;
  --
  RETURN v_plan;
  --
EXCEPTION
WHEN OTHERS THEN
  --
  RETURN NULL;
  --
END;
