/*****************************************************************
GH - TH
FUNCTION f_garantias_riesgo home
Devuelve las partidas de un riesgo
param IN psseguro  : codigo de seguro
param IN pnriesgo  : numero de riesgo
param IN pcidioma  : codigo de idioma
param IN pmodo     : modo EST/POL
return             : texto con las garant?as del riesgo
******************************************************************/
FUNCTION f_garantias_riesgo_hclob(
    psseguro IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pcampo   IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL)
  RETURN CLOB
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult CLOB := '';
    v_tconsulta  VARCHAR2(4000);
    v_tlinia     VARCHAR2(300);
    v_tlinia1    VARCHAR2(300);
    v_tlinia2    VARCHAR2(300);
    v_tlinia3    VARCHAR2(300);
    v_norden     NUMBER;
    v_nimpresion NUMBER;
    v_nlinea     NUMBER;
    v_tpargar    VARCHAR2(200);
    v_tablaseg   VARCHAR2(30);
    v_act0       NUMBER(1);
    v_cimpres garanpro.cimpres%TYPE;
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
    v_ntabs     VARCHAR2(100);
    v_indice    NUMBER;-- BUG 0058707 GZG 13/02/2020
  BEGIN
    -- BUG 16092 - 12/01/2011 - JMP - AGA RC: Miramos si las garant?as est?n definidas para la actividad del seguro
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    v_tconsulta         := v_tconsulta || ' LEFT JOIN pregungaranseg pgs ON s.cgarant = pgs.cgarant AND pgs.sseguro = s.sseguro AND pgs.nriesgo = s.nriesgo AND pgs.nmovimi = s.nmovimi ';
    v_tconsulta         := v_tconsulta || ' WHERE se.csituac in ' || v_csituac;
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    --INI BUG 0058707 GZG 13/02/2020
    v_tconsulta         := 'SELECT p.norden,g.cgarant,g.tgarant,pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot), null, ''' || pmodo || ''') a, ' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0) IMPRESION, ' || ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot, null, ''' || pmodo || ''') d, 0 nlinea  '; -- Solucion BUG 21759
    IF NVL(pmodo, 'POL') = 'EST' THEN
    v_tconsulta         := v_tconsulta || ' ,(SELECT pg.crespue FROM estpregungaranseg pg WHERE pg.cpregun = 6124 AND pg.sseguro = s.sseguro AND pg.cgarant = s.cgarant AND pg.nmovimi = (SELECT MAX(pg2.nmovimi) FROM estpregungaranseg pg2 WHERE pg2.cpregun = 6124 AND pg2.sseguro = pg.sseguro AND pg2.cgarant = pg.cgarant and pg2.nmovimi = ' || pnmovimi || ')) indice FROM garangenpro g ';-- BUG 0058707 GZG 18/02/2020
    ELSE
    v_tconsulta         := v_tconsulta || ' ,(SELECT pg.crespue FROM pregungaranseg pg WHERE pg.cpregun = 6124 AND pg.sseguro = s.sseguro AND pg.cgarant = s.cgarant AND pg.nmovimi = (SELECT MAX(pg2.nmovimi) FROM pregungaranseg pg2 WHERE pg2.cpregun = 6124 AND pg2.sseguro = pg.sseguro AND pg2.cgarant = pg.cgarant and pg2.nmovimi = ' || pnmovimi || ')) indice FROM garangenpro g ';-- BUG 0058707 GZG 18/02/2020
    END IF;
    --INI BUG 0058707 GZG 13/02/2020
    v_tconsulta         := v_tconsulta || ' INNER JOIN garanpro p ON g.cgarant = p.cgarant ';
    v_tconsulta         := v_tconsulta || ' INNER JOIN productos pp ON p.sproduc = pp.sproduc ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' INNER JOIN estgaranseg s ON g.cgarant = s.cgarant AND p.cgarant = s.cgarant ' || 'INNER JOIN estseguros se ON p.sproduc = se.sproduc AND s.sseguro = se.sseguro AND p.cactivi = ' || v_actividad;
      v_csituac         := '(0,7,5,2,4)';
    ELSE
      v_tconsulta                                 := v_tconsulta || ' INNER JOIN garanseg s ON g.cgarant = s.cgarant AND p.cgarant = s.cgarant ' || ' INNER JOIN seguros se ON p.sproduc = se.sproduc AND s.sseguro = se.sseguro AND p.cactivi = ' || v_actividad;
      IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
        v_csituac                                 := '(0,7,5,2)';
      ELSE
        v_csituac := '(0,7,5,2,4)';
      END IF;
    END IF;
    v_tconsulta         := v_tconsulta || ' WHERE se.csituac in ' || v_csituac;
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND g.cidioma = ' || pcidioma;
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    -- INICIO AITSSD-4783 SE REVERSA ESTE TICKET AITSSD-4044
	--- v_tconsulta         := v_tconsulta || ' AND g.sproduc=se.sproduc '; --INI/FIN   17/07/2025  JMC  AITSSD-4044
    -- FIN AITSSD-4783
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' AND s.icapital IS NOT NULL ' || ' AND s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg WHERE sseguro =' || psseguro;
      IF (pnmovimi      IS NOT NULL) THEN
        v_tconsulta     := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
        v_tconsulta := v_tconsulta || ')';
      END IF;
    ELSE
      v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro;
      IF (pnmovimi  IS NOT NULL) THEN
        v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
        v_tconsulta := v_tconsulta || ')';
      END IF;
    END IF;
    v_tconsulta         := v_tconsulta || ' UNION ';
    v_tconsulta         := v_tconsulta || ' SELECT p.norden, a.cgarant, case when LENGTH(a.tvalor)>124 then RPAD(a.tvalor,124)||''...'' else a.tvalor end AS tgarant,' || ' pac_isqlfor_lcol.f_imporignomon(a.sseguro, b.nvalor, null, ''' || pmodo || ''') AS val, -1 impresion, ' || ' pac_isqlfor_lcol.f_imporignomon(a.sseguro, 0, null, ''' || pmodo || ''') d, a.nlinea ';-- BUG 0068346 GZG 18/05/2021
    --INI BUG 0058707 GZG 13/02/2020
    IF NVL(pmodo, 'POL') = 'EST' THEN
    v_tconsulta         := v_tconsulta || ' ,(SELECT pg.crespue FROM estpregungaranseg pg WHERE pg.cpregun = 6124 AND pg.sseguro = a.sseguro AND pg.cgarant = a.cgarant AND pg.nmovimi = (SELECT MAX(pg2.nmovimi) FROM estpregungaranseg pg2 WHERE pg2.cpregun = 6124 AND pg2.sseguro = pg.sseguro AND pg2.cgarant = pg.cgarant and pg2.nmovimi = ' || pnmovimi || ')) indice ';-- BUG 0058707 GZG 18/02/2020
    ELSE
    v_tconsulta         := v_tconsulta || ' ,(SELECT pg.crespue FROM pregungaranseg pg WHERE pg.cpregun = 6124 AND pg.sseguro = a.sseguro AND pg.cgarant = a.cgarant AND pg.nmovimi = (SELECT MAX(pg2.nmovimi) FROM pregungaranseg pg2 WHERE pg2.cpregun = 6124 AND pg2.sseguro = pg.sseguro AND pg2.cgarant = pg.cgarant and pg2.nmovimi = ' || pnmovimi || ')) indice ';-- BUG 0058707 GZG 18/02/2020
    END IF;
    --FIN BUG 0058707 GZG 13/02/2020
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' FROM (SELECT * FROM estpregungaransegtab WHERE sseguro = ' || psseguro || ' AND ccolumna = 1 ) a INNER JOIN ' || ' (SELECT * FROM estpregungaransegtab WHERE sseguro = ' || psseguro || ' AND ccolumna = 2) b ON a.sseguro = b.sseguro AND a.nriesgo = b.nriesgo AND a.cgarant = b.cgarant AND a.nmovimi = b.nmovimi AND a.nlinea = b.nlinea ' || ' INNER JOIN garangenpro c ON a.cgarant = c.cgarant ' -- Solucion BUG 21759
      || ' INNER JOIN garanpro p ON c.cgarant = p.cgarant ' || ' INNER JOIN productos pp ON p.sproduc = pp.sproduc ' || ' INNER JOIN estseguros se  ON p.sproduc = se.sproduc AND a.sseguro = se.sseguro AND p.cactivi = ' || v_actividad;
      v_tconsulta := v_tconsulta || ' WHERE c.cidioma = ' || pcidioma;
    ELSE
      v_tconsulta := v_tconsulta || ' FROM (SELECT * FROM pregungaransegtab WHERE sseguro = ' || psseguro || ' AND ccolumna = 1) a INNER JOIN ' || ' (SELECT * FROM pregungaransegtab WHERE sseguro = ' || psseguro || ' AND ccolumna = 2) b ON a.sseguro = b.sseguro AND a.nriesgo = b.nriesgo AND a.cgarant = b.cgarant AND a.nmovimi = b.nmovimi AND a.nlinea = b.nlinea ' || ' INNER JOIN garangenpro c ON a.cgarant = c.cgarant ' -- Solucion BUG 21759
      || ' INNER JOIN garanpro p ON c.cgarant = p.cgarant ' || ' INNER JOIN productos pp ON p.sproduc = pp.sproduc ' || ' INNER JOIN seguros se  ON p.sproduc = se.sproduc AND a.sseguro = se.sseguro AND p.cactivi = ' || v_actividad;
      v_tconsulta := v_tconsulta || ' WHERE c.cidioma = ' || pcidioma || ' and a.nmovimi = NVL(' || pnmovimi || ' , (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' --BUG 0033917 - 24/05/2017 - CASL - se filtra por el movimiento ingresado
      || psseguro || ')) ';
    END IF;
    v_tconsulta := v_tconsulta || ' ORDER BY NORDEN,IMPRESION DESC, NLINEA';
    OPEN vr_cursor FOR v_tconsulta;
    LOOP
      FETCH vr_cursor
      INTO v_norden,
        v_tlinia,
        v_tlinia1,
        v_tlinia2,
        v_nimpresion,
        v_tlinia3,
        v_nlinea,-- BUG 0058707 GZG 13/02/2020
        v_indice;-- BUG 0058707 GZG 13/02/2020
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF pcampo = 1 THEN
      -- INI JFN QT_28989
      IF v_nimpresion    = 1 THEN
        v_ntabs         := ' ' || 'esp!1';
      ELSIF v_nimpresion = 0 THEN
        v_ntabs         := '\tab \tab \tab \tab ' || 'esp!2';
      ELSIF v_nimpresion = -1 THEN
        v_ntabs         := '\tab \tab \tab \tab \tab \tab \tab \tab ' || 'esp!3';
      END IF;
      -- FIN JFN QT_28989
      v_tresult   := v_tresult || v_ntabs || v_tlinia1 || '\par ';
    ELSIF pcampo   = 2 THEN
      IF v_tlinia2 = '0' THEN
        SELECT tatribu
        INTO v_tlinia2
        FROM detvalores
        WHERE cvalor = 126
        AND catribu  = NVL(v_cimpres, 59) -- INCLOSA
        AND cidioma  = NVL(pcidioma, 8);
      END IF;
      IF v_nimpresion    = 1 THEN
        v_tresult       := v_tresult || '\par ';
      ELSIF v_nimpresion = 0 THEN
        v_tresult       := v_tresult || '\par ';
      ELSIF v_nimpresion = -1 THEN
        v_tresult       := v_tresult || v_tlinia2 || '\par ';
      END IF;
    ELSIF pcampo   = 3 THEN
      IF v_tlinia2 = '0' THEN
        SELECT tatribu
        INTO v_tlinia2
        FROM detvalores
        WHERE cvalor = 126
        AND catribu  = NVL(v_cimpres, 59) -- INCLOSA
        AND cidioma  = NVL(pcidioma, 8);
      END IF;
      IF v_nimpresion    = 1 THEN
        v_tresult       := v_tresult || '\par ';
      ELSIF v_nimpresion = 0 THEN
        v_tresult       := v_tresult || v_tlinia2 || '\par ';
      ELSIF v_nimpresion = -1 THEN
        v_tresult       := v_tresult || '\par ';
      END IF;
    --INI BUG 0058707 GZG 13/02/2020
    ELSIF pcampo   = 6 THEN
    v_tresult       := v_tresult || v_indice || '\par ';
    --FIN BUG 0058707 GZG 13/02/2020
    ELSE
      IF v_tlinia2 = '0' THEN
        SELECT tatribu
        INTO v_tlinia2
        FROM detvalores
        WHERE cvalor = 126
        AND catribu  = NVL(v_cimpres, 59) -- INCLOSA
        AND cidioma  = NVL(pcidioma, 8);
      END IF;
      IF v_nimpresion    = 1 THEN
        v_tresult       := v_tresult || v_tlinia2 || '\par ';
      ELSIF v_nimpresion = 0 THEN
        v_tresult       := v_tresult || '\par ';
      ELSIF v_nimpresion = -1 THEN
        v_tresult       := v_tresult || '\par ';
      END IF;
    END IF;
  END LOOP;
  --INI BUG 0047288 - 25/10/2018 - AMC Si genera error con la primera funciÃ³n, se usa la funcion con clob
  BEGIN
    RETURN (f_jrep_trad(v_tresult));
  EXCEPTION
  WHEN OTHERS THEN
    RETURN(f_jrep_trad_clob(v_tresult));
  END;
  --RETURN(f_jrep_trad(v_tresult));--BUG 0047288 - 25/10/2018 - AMC Se inactiva linea
  --FIN BUG 0047288 - 25/10/2018 - AMC
EXCEPTION
WHEN OTHERS THEN
  RETURN ' ';
END f_garantias_riesgo_hclob;
--
--FIN BUG 0028538 - 11/10/2016 - JFN
--
--INI BUG 0028151 - 03/03/2017 - CASL - Se crea funcion que identifica si la poliza es administrada o agrupada
--
/*************************************************************************
FUNCTION f_poliza_admin
psseguro IN NUMBER
return : VARCHAR2
*************************************************************************/
--
FUNCTION f_poliza_admin(
    psseguro IN NUMBER)
  RETURN VARCHAR2
IS
  --
  vnumerr    NUMBER := 0;
  vpasexec   NUMBER := 0;
  v_npoliza  NUMBER;
  v_ptipopol VARCHAR2(20);
  plistmov SYS_REFCURSOR;
  plistcarteras SYS_REFCURSOR;
  mensajes t_iax_mensajes;
  --
  vparam  VARCHAR2(1000) := ' psseguro: ' || psseguro;
  vobject VARCHAR2(200)  := 'PAC_ISQLFOR_LCOL.f_poliza_admin';
  --
  v_tmsg VARCHAR2(4000); --BUG 0032383 - 03/04/2017 - CASL -- Se crea nueva variable para obtener el mensaje
  v_listuser SYS_REFCURSOR;-- BUG 0070504 - 14/09/2021 - CASL - Se crea nuevo parametro plistuser
  --
BEGIN
  --
  SELECT DISTINCT npoliza
  INTO v_npoliza
  FROM seguros
  WHERE sseguro = psseguro;
  --
  vnumerr := pac_md_impresion.f_poliza_admin(pnpoliza => v_npoliza, ptipopol => v_ptipopol, tmsg => v_tmsg, --BUG 0032383 - 03/04/2017 - CASL -- Se crea envia nueva variable
  plistmov => plistmov, plistcarteras => plistcarteras, mensajes => mensajes, plistuser => v_listuser);-- INI BUG 0070504 - 14/09/2021 - CASL - Se añade nuevo parametro plistuser
  --
  RETURN v_ptipopol;
  --
EXCEPTION
WHEN OTHERS THEN
  --
  pac_iobj_mensajes.p_tratarmensaje(mensajes, vobject, 1000001, vpasexec, vparam, psqcode => SQLCODE, psqerrm => SQLERRM);
  --
  RETURN 1;
  --
END f_poliza_admin;
--
--INI BUG 0036002 - 26/07/2017 - CASL - Se crea funcion que devuelve un valor numerico dependiendo del dato solicitado
--
/*************************************************************************
FUNCTION f_get_maxmin_recibo
psseguro IN NUMBER
pnmovimi IN NUMBER
psproduc IN NUMBER
ptipoperacion IN VARCHAR2
return : number
*************************************************************************/
--
FUNCTION f_get_maxmin_recibo(
    psseguro      IN NUMBER,
    pnmovimi      IN NUMBER,
    psproduc      IN NUMBER,
    ptipoperacion IN VARCHAR2)
  RETURN NUMBER
IS
  --
  vparam  VARCHAR2(1000) := ' psseguro: ' || psseguro || ' -pnmovimi: ' || pnmovimi || ' -psproduc: ' || psproduc || ' -ptipoperacion: ' || ptipoperacion;
  vobject VARCHAR2(200)  := 'PAC_ISQLFOR_LCOL.f_get_maxmin_recibo';
  --
  v_resultado NUMBER;
  --
  --INI BUG 0037693 - 13/09/2017 - CASL - Se crean Variables
  --
  v_ncertif NUMBER;
  --
  v_select    VARCHAR2(100);
  v_into      VARCHAR2(50);
  v_from      VARCHAR2(100);
  v_where     VARCHAR2(1000);
  v_and       VARCHAR2(200);
  v_group     VARCHAR2(50);
  v_exception VARCHAR2(1000);
  v_fin       VARCHAR2(50);
  v_sql       VARCHAR2(2500);
  --
  v_traza NUMBER := 0;
  --
  --FIN BUG 0037693 - 13/09/2017 - CASL
  --
BEGIN
  --
  --INI BUG 0037693 - 13/09/2017 - CASL - Se modifica la funcion para dejar una unica consulta dinamica
  --
  v_traza := 1;
  --
  SELECT ncertif INTO v_ncertif FROM seguros WHERE sseguro = psseguro;
  --
  v_traza := 2;
  --
  v_select := ' BEGIN SELECT ';
  v_into   := ' INTO :v_resultado ';
  v_from   := ' FROM recibos r ';
  --
  v_traza := 3;
  --
  --Ini 0057181: CUMPLIMIENTO - 90010340- movimiento 3 - Anular recibo generado - Producto autoriza el no cobro
  --v_where := ' WHERE r.sseguro = ' || psseguro || '
--AND r.nmovimi = ' || pnmovimi || '
--AND r.ctiprec NOT IN(13, 15) ';
    v_where := ' WHERE r.sseguro = ' || psseguro ||
    --INI BUG 0057682 GZG 15/01/2020 SE AÑADE CONDICIONAL PARA EL BUG 0057181 CUMPLIMIENTO PARA QUE NO AFECTE LOS DEMAS PRODUCTOS
    ' AND r.nmovimi = ' || pnmovimi ;
    IF psproduc in (10004,10005) THEN
    v_where := v_where||' AND r.nrecibo IN (SELECT A.NRECIBO
	                      FROM (SELECT LISTAGG(CESTREC, ''; '') WITHIN GROUP (ORDER BY CESTREC) over (partition by NRECIBO) CESTREC,
                                      NRECIBO
                                 FROM MOVRECIBO t
                                WHERE NRECIBO IN (SELECT NRECIBO FROM RECIBOS WHERE sseguro = '|| psseguro ||' AND NMOVIMI = '|| pnmovimi ||')) A
                                WHERE A.CESTREC NOT LIKE ''%2%'')   ' ;
     END IF;
    v_where := v_where||'AND r.ctiprec NOT IN(13, 15) ';
    --FIN BUG 0057682 GZG 15/01/2020
  --Fin 0057181: CUMPLIMIENTO - 90010340- movimiento 3 - Anular recibo generado - Producto autoriza el no cobro
  --
  v_traza := 4;
  --
  v_and := ' AND 1 < (SELECT COUNT(1)
FROM recibos
WHERE sseguro = s.sseguro
AND nmovimi   = r.nmovimi) ';
  --
  v_traza := 5;
  --
  IF v_ncertif = 0 THEN
    --
    v_where := v_where || ' AND r.cestaux <> 2 ';
    --
  END IF;
  --
  v_traza := 6;
  --
  v_exception := ' ; EXCEPTION WHEN ';
  --
  v_fin := ' ; END; ';
  --
  v_traza := 7;
  --
  IF NVL(f_parproductos_v(psproduc, 'IMP_AJUSTE_BLANKET'), 0) = 1 THEN--BUG 0044879 - 23/01/2019 - CASL - Se valida si el producto ajusta la impresion por tener ajuste blanket
    --
    v_traza := 8;
    --
    v_where := v_where || ' AND (SELECT cestrec
FROM movrecibo
WHERE nrecibo = r.nrecibo
AND smovrec = (SELECT MAX(smovrec)
FROM movrecibo
WHERE nrecibo = r.nrecibo
AND fmovfin IS NULL)) <> 2 ';
    --
    v_traza := 9;
    --
  END IF;
  --
  v_traza := 10;
  --
  IF ptipoperacion = 'COUNT' THEN
    --
    v_traza := 11;
    --
    v_select := v_select || ' COUNT(r.femisio) ';
    --
    v_group := v_group || ' GROUP BY r.femisio ';
    --
    v_exception := v_exception || ' TOO_MANY_ROWS THEN SELECT COUNT(COUNT(DISTINCT(r.femisio))) ';
    v_exception := v_exception || v_into;
    v_exception := v_exception || v_from;
    v_exception := v_exception || v_where;
    v_exception := v_exception || v_group;
    --
    v_sql := v_select || v_into || v_from || v_where || v_group || v_exception || ' ; WHEN OTHERS THEN :v_resultado := NULL ' || v_fin;
    --
    v_traza := 12;
    --
  ELSIF ptipoperacion = 'MAX' THEN
    --
    v_traza := 13;
    --
    v_select := v_select || ' MAX(nrecibo) ';
    --
    v_sql := v_select || v_into || v_from || v_where || v_fin;
    --
    v_traza := 14;
    --
  ELSIF ptipoperacion = 'MIN' THEN
    --
    v_traza := 15;
    --
    v_select := v_select || ' MIN(nrecibo) ';
    --
    v_sql := v_select || v_into || v_from || v_where || v_fin;
    --
    v_traza := 16;
    --
  ELSIF ptipoperacion = 'VALREC' THEN
	--Ini 0057003: RCE DERIVADA CUMPLIMIENTO - 90005603 - mov 3 - PDF con recibo incorrecto
    --Ini 0057181: CUMPLIMIENTO - 90010340- movimiento 3 - Anular recibo generado - Producto autoriza el no cobro
	--IF psproduc = (10005) THEN
    IF psproduc in (10004,10005) THEN
    --Fin 0057181: CUMPLIMIENTO - 90010340- movimiento 3 - Anular recibo generado - Producto autoriza el no cobro
    --
    v_traza := 17;
    --
    v_select := v_select || ' r.nrecibo ';
    --
    v_from := v_from || ' , seguros s';
    --
    v_where := v_where || ' AND s.sseguro = r.sseguro ';
    --
    v_where := v_where || v_and;
    --
    v_exception := v_exception || ' OTHERS THEN ' || v_select;
    v_exception := v_exception || v_into;
    v_exception := v_exception || v_from;
    v_exception := v_exception || v_where;
    --
    v_sql := v_select || v_into || v_from || v_where || ' AND r.ctiprec = 0 ' || v_exception ||
	'    AND r.nrecibo IN (SELECT A.NRECIBO
	                         FROM (SELECT LISTAGG(CESTREC, ''; '') WITHIN GROUP (ORDER BY CESTREC) over (partition by NRECIBO) CESTREC,
										  NRECIBO
								     FROM MOVRECIBO t
								    WHERE NRECIBO IN (SELECT NRECIBO FROM RECIBOS WHERE sseguro = '|| psseguro ||' AND NMOVIMI = '|| pnmovimi ||')) A
								    WHERE A.CESTREC NOT LIKE ''%2%'');   ' ||
	' EXCEPTION WHEN OTHERS THEN :v_resultado := NULL; END ' || v_fin;
    --
    v_traza := 18;
    --
	ELSE
	--Fin 0057003: RCE DERIVADA CUMPLIMIENTO - 90005603 - mov 3 - PDF con recibo incorrecto
    --
    v_traza := 17;
    --
    v_select := v_select || ' r.nrecibo ';
    --
    v_from := v_from || ' , seguros s';
    --
    v_where := v_where || ' AND s.sseguro = r.sseguro ';
    --
    v_where := v_where || v_and;
    --
    v_exception := v_exception || ' OTHERS THEN ' || v_select;
    v_exception := v_exception || v_into;
    v_exception := v_exception || v_from;
    v_exception := v_exception || v_where;
    --
    --INI  11/06/2020  JMC  QT61462
    --v_sql := v_select || v_into || v_from || v_where || ' AND r.ctiprec = 0 ' || v_exception || ' AND r.ctiprec = 1; EXCEPTION WHEN OTHERS THEN :v_resultado := NULL; END ' || v_fin;
    v_sql := v_select || v_into || v_from || v_where || ' AND r.ctiprec = 0 ' || v_exception || ' AND r.ctiprec = 1 AND r.cestimp <> 0; EXCEPTION WHEN OTHERS THEN :v_resultado := NULL; END ' || v_fin;
    --FIN  11/06/2020  JMC  QT61462
    --
    v_traza := 18;
    --
	--Ini 0057003: RCE DERIVADA CUMPLIMIENTO - 90005603 - mov 3 - PDF con recibo incorrecto
	END IF;
	--Fin 0057003: RCE DERIVADA CUMPLIMIENTO - 90005603 - mov 3 - PDF con recibo incorrecto
  ELSIF ptipoperacion = 'COUNTFCARTPRO' THEN
    --
    v_traza := 19;
    --
    v_select := v_select || ' COUNT(1) ';
    --
    v_sql := v_select || v_into || v_from || v_where || v_fin;
    --
    v_traza := 20;
    --
  END IF;
  --
  v_traza := 21;
  --
  --p_control_error('CASL', vobject, v_sql);--BUG 0038337 - 26/10/2017 - CASL - Se comenta linea
  --
  EXECUTE IMMEDIATE v_sql USING OUT v_resultado;
  --
  v_traza := 22;
  --
  RETURN v_resultado;
  --
EXCEPTION
WHEN OTHERS THEN
  --
  p_tab_error(f_sysdate, f_user, vobject, v_traza, v_sql, SQLERRM);
  --
  RETURN NULL;
  --
  --FIN BUG 0037693 - 13/09/2017 - CASL
  --
END f_get_maxmin_recibo;
--
--FIN BUG 0036002 - 26/07/2017 - CASL
--
--INI BUG 0036002 - 26/07/2017 - CASL - Se invoca la funcion f_get_maxmin_recibo para unificar los calculos de recibos
--INI BUG 0028151 - 03/03/2017 - CASL - Obtiene el recibo
--
/*************************************************************************
FUNCTION f_recibo_mov
psseguro IN NUMBER,
pnmovimi IN NUMBER
return : DATE
*************************************************************************/
--
FUNCTION f_recibo_mov(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER)
  RETURN NUMBER
IS
  --
  vpasexec NUMBER := 0;
  --
  vparam  VARCHAR2(1000) := ' psseguro: ' || psseguro;
  vobject VARCHAR2(200)  := 'PAC_ISQLFOR_LCOL.f_efecto_mov';
  --
  v_nrecibo NUMBER;
  v_count   NUMBER;
  v_sproduc NUMBER; --BUG 0032095 (se reversa con bug 33160, pero se debe dejar variable para no afectar cÃ¿Â³digo) - 11/04/2017 - CASL - Se crea nueva variable
  --
  -- INICIO 257.0   22/04/2020  INFORCOL FVG-276
  pnmovimi2 NUMBER;
  pnmovimi3 NUMBER;
  nExiste   NUMBER;
  nExisteRH NUMBER;
  -- FIN 257.0   22/04/2020  INFORCOL FVG-276
BEGIN
  --
  SELECT sproduc INTO v_sproduc FROM seguros WHERE sseguro = psseguro;
  --
  v_count := f_get_maxmin_recibo(psseguro => psseguro, pnmovimi => pnmovimi, psproduc => v_sproduc, ptipoperacion => 'COUNT');
  --
  IF v_count > 1 THEN
    --
    v_nrecibo := f_get_maxmin_recibo(psseguro => psseguro, pnmovimi => pnmovimi, psproduc => v_sproduc, ptipoperacion => 'VALREC');
    --
    -- INICIO 257.0   22/04/2020  INFORCOL FVG-276
    p_tab_error(f_sysdate, f_user, ' RRR2 '||vobject, 3, 0, 'v_nrecibo'|| v_nrecibo);
    -- FIN 257.0   22/04/2020  INFORCOL FVG-276
    IF v_nrecibo IS NOT NULL THEN
      --
      RETURN v_nrecibo;
      --
    END IF;
    --
    v_nrecibo := f_get_maxmin_recibo(psseguro => psseguro, pnmovimi => pnmovimi, psproduc => v_sproduc, ptipoperacion => 'MAX');
    --
    -- INICIO 257.0   22/04/2020  INFORCOL FVG-276
    p_tab_error(f_sysdate, f_user, ' RRR3 '||vobject, 3, 0, 'v_nrecibo'|| v_nrecibo);
    -- FIN 257.0   22/04/2020  INFORCOL FVG-276
    RETURN v_nrecibo;
    --
  END IF;
  --
  v_nrecibo := f_get_maxmin_recibo(psseguro => psseguro, pnmovimi => pnmovimi, psproduc => v_sproduc, ptipoperacion => 'MIN');
  --
  --INI BUG 0068006 GZG 27/04/2021 se reversa bug por generar errores en produccion.
  /*
  -- INICIO 257.0   22/04/2020  INFORCOL FVG-276
  BEGIN
    SELECT DISTINCT 1
    INTO nExisteRH
    FROM parproductos P
    WHERE P.sproduc IN
      (SELECT S.sproduc FROM SEGUROS S WHERE S.SSEGURO = psseguro
      )
    AND P.cparpro = 'RHPDF_VIDA_FENIX';
  EXCEPTION
  WHEN NO_DATA_FOUND THEN
    nExisteRH := 0;
  END;
  BEGIN
    SELECT DISTINCT 1
    INTO nExiste
    FROM movseguro
    WHERE SSEGURO = psseguro
    AND NMOVIMI   = pnmovimi
    AND CMOTMOV   = 700;
  EXCEPTION
  WHEN NO_DATA_FOUND THEN
    nExiste := 0;
  END;
  p_tab_error(f_sysdate, f_user, ' RRR4 '||vobject, 3, 0, 'v_nrecibo'|| v_nrecibo||' nExiste: '||nExiste||' nExisteRH: '||nExisteRH);
  IF v_nrecibo IS NULL AND NVL(nExiste,0) = 1 AND NVL(nExisteRH,0) = 1 THEN
    pnmovimi3  := NVL(pnmovimi,0) - 1;
    p_tab_error(f_sysdate, f_user, ' RRR5 '||vobject, 3, 0, 'pnmovimi3'|| pnmovimi3);
    BEGIN
      SELECT MAX(NMOVIMI)
      INTO pnmovimi2
      FROM movseguro M
      WHERE SSEGURO = psseguro
      AND NMOVIMI   = pnmovimi3 - 1
      AND CMOTMOV  <> 700;
    EXCEPTION
    WHEN NO_DATA_FOUND THEN
      pnmovimi2 := NULL;
    END;
    BEGIN
      SELECT NRECIBO
      INTO v_nrecibo
      FROM RECIBOS
      WHERE SSEGURO = psseguro
      AND NMOVIMI   = pnmovimi2;
    EXCEPTION
    WHEN NO_DATA_FOUND THEN
      v_nrecibo := NULL;
    END;
  END IF;
  p_tab_error(f_sysdate, f_user, ' RRR6 '||vobject, 3, 0, 'v_nrecibo'|| v_nrecibo);
  --
  -- FIN 257.0   22/04/2020  INFORCOL FVG-276
  */
  --FIN BUG 0068006 GZG 27/04/2021
  RETURN v_nrecibo;
  --
END f_recibo_mov;
--
--FIN BUG 0028151 - 03/03/2017 - CASL
--FIN BUG 0036002 - 26/07/2017 - CASL
--
--INI BUG 0028151 - 03/03/2017 - CASL - Obtiene la fecha de proxima cartera en el alta de la poliza AGRUPADA
--INI BUG 0028151 - 09/03/2017 - CASL - Obtiene la fecha de proxima cartera en el alta de la poliza AGRUPADA
--INI BUG 0028151 - 14/03/2017 - CASL - Obtiene la fecha de proxima cartera en el alta de la poliza AGRUPADA
--
/*************************************************************************
FUNCTION f_get_fcartpro_agrup
psseguro IN NUMBER
pfecha   IN DATE
pnmovimi IN NUMBER
return : DATE
*************************************************************************/
--
FUNCTION f_get_fcartpro_agrup(
    psseguro  IN NUMBER,
    pfecha    IN DATE,
    pnmovimi  IN NUMBER,
    --INI BUG AITSSD-7940 GZG 19/04/2023 Se adiciona variable pnrecibo
    tipofecha IN NUMBER DEFAULT NULL,
    pnrecibo  IN NUMBER DEFAULT NULL)
    --FIN BUG AITSSD-7940 GZG 19/04/2023
  RETURN DATE
IS
  --
  vpasexec      NUMBER := 0;
  v_cramo       NUMBER;
  v_cmotmov     NUMBER;
  v_fecha_agrup DATE;
  mensajes t_iax_mensajes;
  --
  vparam  VARCHAR2(1000) := ' psseguro: ' || psseguro || ' -pfecha: ' || pfecha || ' -pnmovimi: ' || pnmovimi;
  vobject VARCHAR2(200)  := 'PAC_ISQLFOR_LCOL.f_poliza_admin';
  --
  v_hay_recibos NUMBER;
  v_nrecibo     NUMBER := NULL;
  v_sproduc     NUMBER; --BUG 0033810 - 30/05/2017 - CASL - Se crea nueva variable
  --
BEGIN
  --
  vpasexec := 1;
  --
  --INI BUG 0033810 - 30/05/2017 - CASL - Se obtiene el producto y se valida si es 6023, en caso contrario
  --                                      se obtiene los recibos esten anulados o no
  --
  SELECT sproduc
  INTO v_sproduc
  FROM seguros
  WHERE sseguro = psseguro;
  --
  --Se valida que el movimiento tenga recibos
  --
  --INI BUG 0036002 - 26/07/2017 - CASL - Se valida si hay recibos
  --
  v_hay_recibos := f_get_maxmin_recibo(psseguro => psseguro, pnmovimi => pnmovimi, psproduc => v_sproduc, ptipoperacion => 'COUNTFCARTPRO');
  --
  --FIN BUG 0036002 - 26/07/2017 - CASL
  --INI BUG 0036002 - 26/07/2017 - CASL - Se valida si hay recibos
  --
  v_hay_recibos := f_get_maxmin_recibo(psseguro => psseguro, pnmovimi => pnmovimi, psproduc => v_sproduc, ptipoperacion => 'COUNTFCARTPRO');
  --
  --FIN BUG 0036002 - 26/07/2017 - CASL        --
  --FIN BUG 0033810 - 30/05/2017 - CASL
  --
  -- 32006 INI JFN
  --
  --Se valida el ramo del seguro
  --
  SELECT cramo
  INTO v_cramo
  FROM seguros
  WHERE sseguro = psseguro;
  --
  --Se valida el tipo de movimiento
  --
  SELECT cmotmov
  INTO v_cmotmov
  FROM movseguro
  WHERE sseguro = psseguro
  AND nmovimi   = pnmovimi;
  -- 32006 FIN JFN
  vpasexec := 2;
  --
  IF v_hay_recibos <> 0 THEN
    --
    IF pnrecibo is null THEN-- BUG AITSSD-7940 GZG 19/04/2023
    --Si existen recibos se obtiene el recibo con el que nacio el movimiento
    --
    v_nrecibo := f_recibo_mov(psseguro => psseguro, pnmovimi => pnmovimi);
    --
    --Si el tipofecha = 1 se devuelve la fecha de efecto del recibo
    --INI BUG AITSSD-7940 GZG 19/04/2023
    ELSE
        v_nrecibo := pnrecibo;
    END IF;
    --FIN BUG AITSSD-7940 GZG 19/04/2023
    IF tipofecha = 1 THEN
      --
      BEGIN
        --
        vpasexec := 2;
        -- 32006 INI JFN
        --
        --Validamos que sea para autos
        IF v_cramo IN (104, 105, 101) THEN --BUG 0033810 - 30/05/2017 - CASL - Se aÃ¿Â±ade al filtro los productos de vida individual
          --Validamos que el movimiento sea de alta o de renovacion de cartera
          IF v_cmotmov = 100
            /*OR v_cmotmov = 404 OR v_cmotmov = 403 BUG 0032006- 04/04/2017 - CASL - Se comenta para que no tenga encuenta estos motivos */
            THEN
            SELECT fefecto INTO v_fecha_agrup FROM seguros WHERE sseguro = psseguro;
          ELSE
            SELECT ms.fefecto
            INTO v_fecha_agrup
            FROM seguros s,
              movseguro ms
            WHERE s.sseguro = ms.sseguro
            AND s.sseguro   = psseguro
            AND ms.nmovimi  = pnmovimi;
          END IF;
        ELSE
        --INI GZG AITSSD-9057 21/04/2026
          IF v_cramo IN (702) AND v_cmotmov = 324 AND pnrecibo IS NULL THEN
            SELECT ms.fefecto
            INTO v_fecha_agrup
            FROM seguros s,
              movseguro ms
            WHERE s.sseguro = ms.sseguro
            AND s.sseguro   = psseguro
            AND ms.nmovimi  = pnmovimi;
          ELSE
          -- 32006 FIN JFN
          SELECT r.fefecto
          INTO v_fecha_agrup
          FROM recibos r
          WHERE r.nrecibo = v_nrecibo;
          END IF;
        --FIN GZG AITSSD-9057 21/04/2026
        END IF;
        --
        vpasexec := 3;
        --
        RETURN TRUNC(v_fecha_agrup);
        --
      EXCEPTION
      WHEN OTHERS THEN
        --
        --Si se presenta algun error se retorna la fecha ingresada por defecto
        --
        RETURN TRUNC(pfecha);
        --
      END;
      --
    ELSE --Si el tipofecha <> 1 se devuelve la fecha de vencimiento del recibo
      --
      BEGIN
        --
        vpasexec := 2;
        --
        --Validamos que sea para autos
        -- 32006 INI JFN
        IF v_cramo IN (104, 105, 101) THEN --BUG 0033810 - 30/05/2017 - CASL - Se aÃ¿Â±ade al filtro los productos de vida individual
          --Validamos que el movimiento sea de alta o de renovacion de cartera
          BEGIN
            --
            --INI BUG 0032006- 04/04/2017 - CASL -- Se invoca la funcion para obtener la fecha de vencimiento
            --INI BUG 0032006- 10/04/2017 - CASL -- Se invoca la funcion para obtener la fecha de vencimiento
            --
            --
            SELECT f_get_fvencim(psseguro => psseguro, pnmovimi => pnmovimi, pfecha => fefecto)
            INTO v_fecha_agrup
            FROM movseguro
            WHERE sseguro = psseguro
            AND nmovimi   = pnmovimi;
            --
            --FIN BUG 0032006- 10/04/2017 - CASL
            --FIN BUG 0032006- 04/04/2017 - CASL
            --
            RETURN TRUNC(v_fecha_agrup);
            --
          EXCEPTION
          WHEN OTHERS THEN
            --
            RETURN TRUNC(pfecha);
            --
          END;
        ELSE
          -- 32006 FIN JFN
          SELECT r.fvencim
          INTO v_fecha_agrup
          FROM recibos r
          WHERE r.nrecibo = v_nrecibo;
        END IF;
        --
        vpasexec := 3;
        --
        RETURN TRUNC(v_fecha_agrup);
        --
      EXCEPTION
      WHEN OTHERS THEN
        --
        RETURN TRUNC(pfecha);
        --
      END;
      --
    END IF;
    --
  ELSE -- Si no existen recibos para el movimiento se obtiene la fecha de vencimiento de las tablas del seguro
    --
    IF tipofecha = 1 THEN
      --
      BEGIN
        --
        vpasexec := 2;
        --
        --INI BUG 0032006- 04/04/2017 - CASL -- Se obtiene la fecha de efecto
        IF v_cramo IN (104, 105, 101) --BUG 0033810 - 30/05/2017 - CASL - Se aÃ¿Â±ade al filtro los productos de vida individual
          AND v_cmotmov = 100 THEN
          --
          SELECT s.fefecto
          INTO v_fecha_agrup
          FROM seguros s
          WHERE s.sseguro = psseguro;
          --
          --FIN BUG 0032006- 04/04/2017 - CASL
        ELSE
          --
          SELECT ms.fefecto
          INTO v_fecha_agrup
          FROM seguros s,
            movseguro ms
          WHERE s.sseguro = ms.sseguro
          AND s.sseguro   = psseguro
          AND ms.nmovimi  = pnmovimi;
          --
        END IF;
        --
        vpasexec := 3;
        --
        RETURN TRUNC(v_fecha_agrup);
        --
      EXCEPTION
      WHEN OTHERS THEN
        --
        --Si se presenta algun error se retorna la fecha ingresada por defecto
        --
        RETURN TRUNC(pfecha);
        --
      END;
      --
      --INI BUG 0032006- 04/04/2017 - CASL -- Se invoca la funcion para obtener la fecha de vencimiento
      --INI BUG 0032006- 10/04/2017 - CASL -- Se invoca la funcion para obtener la fecha de vencimiento
    ELSE
      --
      IF v_cramo IN (104, 105, 101) --BUG 0033810 - 30/05/2017 - CASL - Se aÃ¿Â±ade al filtro los productos de vida individual
        THEN
        --
        SELECT f_get_fvencim( psseguro => psseguro, pnmovimi => pnmovimi, pfecha => fefecto)
        INTO v_fecha_agrup
        FROM movseguro
        WHERE sseguro = psseguro
        AND nmovimi   = pnmovimi;
        --
        RETURN TRUNC(v_fecha_agrup);
        --
        --FIN BUG 0032006- 10/04/2017 - CASL
        --FIN BUG 0032006- 04/04/2017 - CASL
      ELSE
        --
        BEGIN
          --
          SELECT
            CASE
              WHEN (SELECT fefecto
                FROM movseguro
                WHERE sseguro = psseguro
                AND nmovimi   = NVL(pnmovimi,
                  (SELECT MAX(nmovimi) FROM historicoseguros WHERE sseguro = psseguro
                  ))) >= NVL(fcarant, fefecto)
              THEN
                CASE
                  WHEN (SELECT fefecto
                    FROM movseguro
                    WHERE sseguro = psseguro
                    AND nmovimi   = NVL(pnmovimi,
                      (SELECT MAX(nmovimi) FROM historicoseguros WHERE sseguro = psseguro
                      ))) >= fcarpro
                  THEN
                    CASE
                      WHEN (SELECT fefecto
                        FROM movseguro
                        WHERE sseguro = psseguro
                        AND nmovimi   = NVL(pnmovimi,
                          (SELECT MAX(nmovimi) FROM historicoseguros WHERE sseguro = psseguro
                          ))) >= fcaranu
                      THEN
                        (SELECT fcarpro
                        FROM seguros
                        WHERE sseguro = psseguro
                        )
                      ELSE fcaranu
                    END
                  ELSE DECODE(fcarpro, NULL, fcaranu, fcarpro)
                END
              ELSE DECODE(fcarant, NULL, DECODE(fcarpro, NULL, fcaranu, fcarpro), fcarant)
            END
          INTO v_fecha_agrup
          FROM historicoseguros
          WHERE sseguro = psseguro
          AND nmovimi   = NVL(pnmovimi,
            (SELECT MAX(nmovimi) FROM historicoseguros WHERE sseguro = psseguro
            ));
          --
        EXCEPTION
        WHEN NO_DATA_FOUND THEN
          --
          BEGIN
            --
            SELECT
              CASE
                WHEN (SELECT fefecto
                  FROM movseguro
                  WHERE sseguro = psseguro
                  AND nmovimi   = NVL(pnmovimi,
                    (SELECT MAX(nmovimi) FROM historicoseguros WHERE sseguro = psseguro
                    ))) >= fcarant --BUG 0037693 - 13/09/2017 - CASL - Se aÃ¿Â±ade el = para aumentar el rango de comparacion.
                THEN DECODE(fcarpro, NULL, fcaranu, fcarpro)
                ELSE DECODE(fcarant, NULL, DECODE(fcarpro, NULL, fcaranu, fcarpro), fcarant)
              END
            INTO v_fecha_agrup
            FROM seguros
            WHERE sseguro = psseguro;
            --
            RETURN TRUNC(v_fecha_agrup);
            --
          EXCEPTION
          WHEN OTHERS THEN
            --
            RETURN TRUNC(pfecha);
            --
          END;
          --
        END;
        --
      END IF;
      --
    END IF;
    --
    RETURN TRUNC(v_fecha_agrup);
    --
  END IF;
  --
  vpasexec := 6;
  --
  RETURN TRUNC(pfecha);
  --
EXCEPTION
WHEN OTHERS THEN
  --
  pac_iobj_mensajes.p_tratarmensaje(mensajes, vobject, 1000001, vpasexec, vparam, psqcode => SQLCODE, psqerrm => SQLERRM);
  --
  RETURN TRUNC(pfecha);
  --
END f_get_fcartpro_agrup;
--
--FIN BUG 0028151 - 14/03/2017 - CASL
--FIN BUG 0028151 - 09/03/2017 - CASL
--FIN BUG 0028151 - 03/03/2017 - CASL
--
--INI BUG 0032006- 04/04/2017 - CASL - Se crea nueva funcion
--INI BUG 0032006- 10/04/2017 - CASL - Se crea nueva funcion
--
FUNCTION f_get_fvencim(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER,
    pfecha   IN DATE)
  RETURN DATE
IS
  --
  vparam  VARCHAR2(1000) := ' psseguro: ' || psseguro || ' -pnmovimi: ' || pnmovimi;
  vobject VARCHAR2(200)  := 'PAC_ISQLFOR_LCOL.f_get_fvencim';
  --
  v_fecha_agrup DATE;
  v_cramo       NUMBER;
  v_cmotmov     NUMBER;
  --
BEGIN
  --
  SELECT
    CASE
      WHEN (NVL(fcaranu, pfecha) - pfecha) > 366
      OR (NVL(fcaranu, pfecha)   - pfecha) = 0
      THEN
        --
        CASE
          WHEN (NVL(fcarpro, pfecha) - pfecha) > 366
          OR (NVL(fcarpro, pfecha)   - pfecha) = 0
          THEN
            --
            CASE
              WHEN (NVL(fcarant, pfecha) - pfecha) > 366
              OR (NVL(fcarant, pfecha)   - pfecha) = 0
              THEN
                --
                --INI BUG 0044482 - 30/06/2018 - CASL - Se Cuando una poliza tiene varias renovaciones es necesario consultar la historicoseguros
                --
                --NULL --BUG 0032392 - 10/04/2017 - CASL - Se modifica fecha
                --
                (
                SELECT
                  CASE
                    WHEN (NVL(fcaranu, pfecha) - pfecha) > 366
                    OR (NVL(fcaranu, pfecha)   - pfecha) = 0
                    THEN
                      --
                      CASE
                        WHEN (NVL(fcarpro, pfecha) - pfecha) > 366
                        OR (NVL(fcarpro, pfecha)   - pfecha) = 0
                        THEN
                          --
                          CASE
                            WHEN (NVL(fcarant, pfecha) - pfecha) > 366
                            OR (NVL(fcarant, pfecha)   - pfecha) = 0
                            THEN
                              --
                              pfecha
                              --
                            ELSE
                              --
                              fcarant
                              --
                          END
                          --
                        ELSE
                          --
                          fcarpro
                          --
                      END
                      --
                    ELSE
                      --
                      fcaranu
                      --
                  END
                  --
                FROM historicoseguros
                WHERE sseguro = psseguro
                AND nmovimi   = pnmovimi
                )
                --
                --FIN BUG 0044482 - 30/06/2018 - CASL
                --
              ELSE
                -- INI BUG 44523 17/07/2018 GNRZ
                --
                CASE
                  WHEN NVL(fcaranu, pfecha) - pfecha = 0
                  AND NVL(fcarpro, pfecha)  - pfecha = 0
                  THEN
                    --
                    fcaranu
                    --
                  ELSE
                    --
                    fcarant
                    --
                END
                --
                -- FIN BUG 44523 17/07/2018 GNRZ
            END
            --
          ELSE
            --
            fcarpro
            --
        END
        --
      ELSE
        --
        fcaranu
        --
    END
    --
  INTO v_fecha_agrup
  FROM seguros
  WHERE sseguro = psseguro;
  --
  RETURN v_fecha_agrup;
  --
  --
  --INI BUG 0032392 - 10/04/2017 - CASL - Se crea excepcion
  --
EXCEPTION
WHEN NO_DATA_FOUND THEN
  --
  SELECT
    CASE
      WHEN (NVL(fcaranu, pfecha) - pfecha) > 366
      OR (NVL(fcaranu, pfecha)   - pfecha) = 0
      THEN
        --
        CASE
          WHEN (NVL(fcarpro, pfecha) - pfecha) > 366
          OR (NVL(fcarpro, pfecha)   - pfecha) = 0
          THEN
            --
            CASE
              WHEN (NVL(fcarant, pfecha) - pfecha) > 366
              OR (NVL(fcarant, pfecha)   - pfecha) = 0
              THEN
                --
                pfecha
                --
              ELSE
                --
                fcarant
                --
            END
            --
          ELSE
            --
            fcarpro
            --
        END
        --
      ELSE
        --
        fcaranu
        --
    END
    --
  INTO v_fecha_agrup
  FROM historicoseguros
  WHERE sseguro = psseguro
  AND nmovimi   = pnmovimi;
  --
  RETURN v_fecha_agrup;
  --
  --FIN BUG 0032392 - 10/04/2017 - CASL
  --
END f_get_fvencim;
