/*****************************************************************
FUNCTION f_gastest4095
Gastos de ExpediciÃ¿Â³n cotizaciones pregunta 4093 y 4095
param IN psseguro  : codigo de seguro
return             : Valor de los gastos de expedicion
******************************************************************/
FUNCTION f_gastest4095(
    v_sseguro IN NUMBER)
  RETURN NUMBER
IS
  v_4093     NUMBER;
  v_4095     NUMBER;
  vnum_err   NUMBER;
  v_igasexpe NUMBER;
BEGIN
  SELECT a.crespue
  INTO v_igasexpe
  FROM estpregunpolseg a
  WHERE a.cpregun = 4093
  AND a.sseguro   = v_sseguro
  AND a.nmovimi   =
    (SELECT MIN(b.nmovimi)
    FROM estpregunpolseg b
    WHERE b.cpregun = 4095
    AND b.sseguro   = v_sseguro
    );
  IF v_igasexpe = 2 THEN -- Si aplica gastos de expedicion
    BEGIN
      SELECT crespue
      INTO v_igasexpe
      FROM estpregunpolseg
      WHERE cpregun = 4095
      AND sseguro   = v_sseguro
      AND nmovimi   =
        (SELECT MIN(b.nmovimi)
        FROM estpregunpolseg b
        WHERE b.cpregun = 4095
        AND b.sseguro   = v_sseguro
        );
      RETURN (v_igasexpe);
    EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN 0;
    END;
  ELSE
    RETURN 0;
  END IF;
EXCEPTION
WHEN OTHERS THEN
  RETURN 0;
END f_gastest4095;
