--INI BUG 0032232 - 11/04/2017 - LRGG
--
FUNCTION f_datos_persona(
    pmt_sseguro IN NUMBER,
    p_tipo      IN NUMBER,
    pmt_idioma  IN NUMBER DEFAULT 1,
    p_mode      IN VARCHAR2 DEFAULT 'POL',
    pmt_nmovimi IN NUMBER DEFAULT 1)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult       VARCHAR2(32000) := '';
    v_tconsulta     VARCHAR2(4000);
    v_principal     VARCHAR2(1);
    v_asegurado     VARCHAR2(4000);
    v_tipoidnumass  VARCHAR2(2000);
    v_assdirec      VARCHAR2(4000);
    v_asspoblac     VARCHAR2(3000);
    v_telefonoass   VARCHAR2(2000);
    v_fechanacimass VARCHAR2(3000);
    v_parentescoass VARCHAR2(2000);
    --p_tipo 1=Asegurado Ppal, 2 = Asegurado, 3=Tipo Identificacion, 4=Direccion, 5=PoblaciÃ¿Â¿Ã¿Â³n, 6=Telefono, 7=Fecha Nacimiento
    --8= parentesco
    --
    --INI BUG 0043553 - 23/05/2018 - CASL - Se crean nuevas variables
    --
    v_cons_aseg_riesgo NUMBER;
    v_sproduc          NUMBER;
    --
    --FIN BUG 0043553 - 23/05/2018 - CASL
    --
  BEGIN
    --
