    END IF;
    IF p_tipo    = 8 THEN
      v_tresult := v_tresult || v_parentescoass || '\par ';
    END IF;
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_datos_persona;
