--INI BUG 0050531 GZG 24/03/2019 SE CREA FUNCION PARA EL PARENTESCO DE LOS ASEGURADOS DE EL PRODUC EXQUIAS
FUNCTION f_parentescoas_exq(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER)
  RETURN VARCHAR2
IS
  --
TYPE r_cursor
IS
  REF
  CURSOR;
    --
    vr_cursor r_cursor;
    v_tconsulta  VARCHAR2(4000);
    v_cmotmov    NUMBER;
    v_parentesco VARCHAR2(4000);
    v_cmotmovs   NUMBER;
    v_sum        NUMBER := 1;--BUG 0052571 19/06/2019 GZG
    --
  BEGIN
    --
    SELECT cmotmov
    INTO v_cmotmovs
    FROM movseguro
    WHERE sseguro = psseguro
    AND nmovimi   = pnmovimi;
  --
  FOR i IN
  (SELECT cmotmov
  FROM motmovseg
  WHERE cidioma = 8
  AND tmotmov LIKE ('%Anulac%')
  )
  LOOP
    IF v_cmotmovs = i.cmotmov THEN
      v_sum      := v_sum + 1;
    END IF;
  END LOOP;
  --
  IF v_cmotmovs   IN (267,700,721,720) THEN
    v_sum := v_sum + 1;
  END IF;
  v_tconsulta   := v_tconsulta || 'SELECT PAC_ISQLFOR_LCOL.F_JREP_TRAD( ';
  v_tconsulta   := v_tconsulta || '(SELECT LISTAGG((SELECT DISTINCT P.NRIESGO|| ''-'' || NVAL7 ';
  v_tconsulta   := v_tconsulta || 'FROM PREGUNSEG P ';
  v_tconsulta   := v_tconsulta || 'INNER JOIN SGT_SUBTABS_DET ST ';
  v_tconsulta   := v_tconsulta || 'ON P.CRESPUE     = ST.NVAL1 ';
  v_tconsulta   := v_tconsulta || 'WHERE P.SSEGURO  = '||psseguro||' ';
  v_tconsulta   := v_tconsulta || 'AND P.CPREGUN    = 7989 ';
  v_tconsulta   := v_tconsulta || 'AND ST.CSUBTABLA = 70608011 ';
  v_tconsulta   := v_tconsulta || 'AND ST.NVAL1     = P.CRESPUE ';
  IF v_sum       = 0 THEN
    v_tconsulta := v_tconsulta || 'AND P.NMOVIMI    = '||pnmovimi||' ';
  ELSE
    v_tconsulta := v_tconsulta || 'AND P.NMOVIMI = (SELECT MAX(NMOVIMI) FROM PREGUNSEG WHERE SSEGURO = '||psseguro||' AND CPREGUN = 7989 AND nmovimi <= '||pnmovimi||') ';--BUG 0053677 31/07/2019 GZG, se modifica para que tome solo el maximo movimiento
  END IF;
  v_tconsulta := v_tconsulta || 'AND P.NRIESGO    = A.NORDEN ';
  v_tconsulta := v_tconsulta || 'AND ST.CCLA1     = 0 ';
  --INI BUG 0051327 06/05/2019 GZG -- SE COMENTAN LINEAS Y SE AGREGA "and ffecfin is null"
  /*v_tconsulta   := v_tconsulta || 'AND ST.CCLA4     =(SELECT ';
  v_tconsulta   := v_tconsulta || 'CASE WHEN (SELECT CRESPUE FROM PREGUNSEG ';
  IF v_sum       = 0 THEN
  v_tconsulta := v_tconsulta || 'WHERE SSEGURO = '||psseguro||' AND CPREGUN = 7989 AND NMOVIMI = '||pnmovimi||' AND NRIESGO = A.NORDEN) = 0 ';
  ELSE
  v_tconsulta := v_tconsulta || 'WHERE SSEGURO = '||psseguro||' AND CPREGUN = 7989 AND NMOVIMI <= '||pnmovimi||' AND NRIESGO = A.NORDEN) = 0 ';
  END IF;
  v_tconsulta   := v_tconsulta || 'OR (ST.CCLA4   IS NULL AND (SELECT CRESPUE FROM PREGUNSEG WHERE SSEGURO = '||psseguro||' AND CPREGUN   = 7989 ';
  IF v_sum       = 0 THEN
  v_tconsulta := v_tconsulta || 'AND NMOVIMI   = '||pnmovimi||' AND NRIESGO   = A.NORDEN) <> 0) THEN 0 ELSE ST.CCLA4 END ';
  v_tconsulta := v_tconsulta || 'FROM PREGUNSEG WHERE SSEGURO = '||psseguro||' AND CPREGUN = 7989 AND NMOVIMI = '||pnmovimi||' AND NRIESGO = A.NORDEN ) ';
  ELSE
  v_tconsulta := v_tconsulta || 'AND NMOVIMI   <= '||pnmovimi||' AND NRIESGO   = A.NORDEN) <> 0) THEN 0 ELSE ST.CCLA4 END ';
  v_tconsulta := v_tconsulta || 'FROM PREGUNSEG WHERE SSEGURO = '||psseguro||' AND CPREGUN = 7989 AND NMOVIMI <= '||pnmovimi||' AND NRIESGO = A.NORDEN ) ';
  END IF;*/
  v_tconsulta := v_tconsulta || 'and a.ffecfin is null), LOWER(''  \PAR  '')) WITHIN GROUP( ORDER BY A.NORDEN ASC) PARENTESCOASS ';
  --FIN BUG 0051327 06/05/2019 GZG
  v_tconsulta := v_tconsulta || 'FROM ASEGURADOS A INNER JOIN PER_DETPER D ON A.SPERSON    = D.SPERSON ';
  v_tconsulta := v_tconsulta || 'WHERE A.SSEGURO = '||psseguro||' )) FROM DUAL ';
  --
  -- p_control_error('GZG','f_parentescoas_exq',v_tconsulta);
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_parentesco;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    --
  END LOOP;
  --
  RETURN (v_parentesco);
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_parentescoas_exq;
--INI BUG 0050531 GZG 24/03/2019 SE CREA FUNCION PARA EL PARENTESCO DE LOS ASEGURADOS DE EL PRODUC EXQUIAS
/*****************************************************************
FUNCTION f_garantias_Pyme
Devuelve las partidas de un riesgo para Pyme
param IN psseguro  : codigo de seguro
param IN pnriesgo  : numero de riesgo
param IN pcidioma  : codigo de idioma
param IN pcampo    : recupera la cod de la garantias, desc de las garantias, el capital
param IN pmodo     : modo EST/POL
return             : texto con las garantias del riesgo
Bug 31409 - 24/07/2017 - LGG
BUG 36151 - LGG
******************************************************************/
FUNCTION f_garantias_pyme(
    psseguro IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pcampo   IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL')
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(4000);
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_cgarant   NUMBER;
    v_tlinia    VARCHAR2(300);
    v_tlinia1   VARCHAR2(300);
  BEGIN
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 's.cactivi';
    END IF;
    v_tconsulta := 'select cgarant,tgarant, icapital from  ';
    v_tconsulta := v_tconsulta || '(select distinct sgc.cgarant, gg.tgarant, gs.icapital, gs.norden ';
    v_tconsulta := v_tconsulta || ' from sin_gar_causa sgc, garanseg gs, seguros s, garangen gg ';
    v_tconsulta := v_tconsulta || ' where sgc.cactivi = ' || v_actividad || ' and sgc.ccausin = 7021 and sgc.cmotsin = 0 and sgc.cgarant =  gs.cgarant  ';
    v_tconsulta := v_tconsulta || ' and gs.sseguro = ' || psseguro;
    v_tconsulta := v_tconsulta || ' and gs.sseguro = s.sseguro  ';
    v_tconsulta := v_tconsulta || ' and gs.nriesgo = ' || pnriesgo;
    v_tconsulta := v_tconsulta || ' and sgc.sproduc = s.sproduc  ';
    v_tconsulta := v_tconsulta || ' and gg.cgarant = gs.cgarant  ';
    v_tconsulta := v_tconsulta || ' and gg.cidioma = ' || pcidioma;
    v_tconsulta := v_tconsulta || ' UNION  ';
    v_tconsulta := v_tconsulta || ' select distinct sgc.cgarant, gg.tgarant, gs.icapital, gs.norden  ';
    v_tconsulta := v_tconsulta || ' from sin_gar_causa sgc, garanseg gs, seguros s, garangen gg  ';
    v_tconsulta := v_tconsulta || ' where sgc.cactivi = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' and NOT EXISTS (SELECT 1 FROM sin_gar_causa WHERE sproduc = sgc.sproduc AND cactivi = 0) and sgc.ccausin = 7021 and sgc.cmotsin = 0 ';
    v_tconsulta := v_tconsulta || ' and sgc.cgarant =  gs.cgarant  ';
    v_tconsulta := v_tconsulta || ' and gs.sseguro = ' || psseguro;
    v_tconsulta := v_tconsulta || ' and gs.sseguro = s.sseguro  ';
    v_tconsulta := v_tconsulta || ' and gs.nriesgo = ' || pnriesgo;
    v_tconsulta := v_tconsulta || ' and sgc.sproduc = s.sproduc  ';
    v_tconsulta := v_tconsulta || ' and gg.cgarant = gs.cgarant  ';
    v_tconsulta := v_tconsulta || ' and gg.cidioma = ' || pcidioma || ')  ';
    v_tconsulta := v_tconsulta || ' order by norden ';
    OPEN vr_cursor FOR v_tconsulta;
    LOOP
      FETCH vr_cursor INTO v_cgarant, v_tlinia, v_tlinia1;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF pcampo    = 1 THEN
      v_tresult := v_tresult || v_cgarant || '\par ';
    END IF;
    IF pcampo    = 2 THEN
      v_tresult := v_tresult || v_tlinia || '\par ';
    END IF;
    IF pcampo    = 3 THEN
      v_tresult := v_tresult || v_tlinia1 || '\par ';
    END IF;
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ' ';
END f_garantias_pyme;
--
--INI BUG 0031409 - 08/05/2017 - LGG
--
/*****************************************************************
GH - TH
FUNCTION f_garantias_riesgo_pyme
Devuelve las partidas de un riesgo
param IN psseguro  : codigo de seguro
param IN pnriesgo  : numero de riesgo
param IN pcidioma  : codigo de idioma
param IN pmodo     : modo EST/POL
return             : texto con las garantias del riesgo
******************************************************************/
FUNCTION f_garantias_riesgo_pyme(
    psseguro IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pcampo   IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL)
  RETURN CLOB
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult CLOB := '';
    v_tconsulta  VARCHAR2(7000);
    v_tlinia     VARCHAR2(300);
    v_tlinia1    VARCHAR2(300);
    v_tlinia2    VARCHAR2(300);
    v_tlinia3    VARCHAR2(300);
    v_norden     NUMBER;
    v_nimpresion NUMBER;
    v_nlinea     NUMBER;
    v_tpargar    VARCHAR2(200);
    v_tablaseg   VARCHAR2(30);
    v_act0       NUMBER(1);
    v_cimpres garanpro.cimpres%TYPE;
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
    v_ntabs     VARCHAR2(100);
  BEGIN
    -- BUG 16092 - 12/01/2011 - JMP - AGA RC: Miramos si las garantias estan definidas para la actividad del seguro
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    v_tconsulta := v_tconsulta || ' LEFT JOIN pregungaranseg pgs ON s.cgarant = pgs.cgarant AND pgs.sseguro = s.sseguro AND pgs.nriesgo = s.nriesgo AND pgs.nmovimi = s.nmovimi ';
    v_tconsulta := v_tconsulta || ' WHERE se.csituac in ' || v_csituac;
    v_tconsulta := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
    v_tconsulta := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    v_tconsulta := ' select * from ( ';
    --v_tconsulta := 'SELECT p.norden,g.cgarant,g.tgarant,pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot), null, ''' || pmodo || ''') a, '
    v_tconsulta         := v_tconsulta || 'SELECT p.norden,g.cgarant,g.tgarant,pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot), null, ''' || pmodo || ''') a, ' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0) IMPRESION, ' || ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot, null, ''' || pmodo || ''') d, 0 nlinea FROM garangenpro g '; -- Solucion BUG 21759
    v_tconsulta         := v_tconsulta || ' INNER JOIN garanpro p ON g.cgarant = p.cgarant ';
    v_tconsulta         := v_tconsulta || ' INNER JOIN productos pp ON p.sproduc = pp.sproduc ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' INNER JOIN estgaranseg s ON g.cgarant = s.cgarant AND p.cgarant = s.cgarant ' || 'INNER JOIN estseguros se ON p.sproduc = se.sproduc AND s.sseguro = se.sseguro AND p.cactivi = ' || v_actividad;
      v_csituac         := '(0,7,5,2,4)';
    ELSE
      v_tconsulta                                 := v_tconsulta || ' INNER JOIN garanseg s ON g.cgarant = s.cgarant AND p.cgarant = s.cgarant ' || ' INNER JOIN seguros se ON p.sproduc = se.sproduc AND s.sseguro = se.sseguro AND p.cactivi = ' || v_actividad;
      IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
        v_csituac                                 := '(0,7,5,2)';
      ELSE
        v_csituac := '(0,7,5,2,4)';
      END IF;
    END IF;
    v_tconsulta         := v_tconsulta || ' WHERE se.csituac in ' || v_csituac;
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND g.cidioma = ' || pcidioma;
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' AND s.icapital IS NOT NULL ' || ' AND s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg WHERE sseguro =' || psseguro;
      IF (pnmovimi      IS NOT NULL) THEN
        v_tconsulta     := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
        v_tconsulta := v_tconsulta || ')';
      END IF;
    ELSE
      v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro;
      IF (pnmovimi  IS NOT NULL) THEN
        v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
        v_tconsulta := v_tconsulta || ')';
      END IF;
    END IF;
    v_tconsulta         := v_tconsulta || ' UNION ';
    v_tconsulta         := v_tconsulta || ' SELECT p.norden, a.cgarant, a.tvalor AS tgarant,' || ' pac_isqlfor_lcol.f_imporignomon(a.sseguro, b.nvalor, null, ''' || pmodo || ''') AS val, -1 impresion, ' || ' pac_isqlfor_lcol.f_imporignomon(a.sseguro, 0, null, ''' || pmodo || ''') d, a.nlinea ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' FROM (SELECT * FROM estpregungaransegtab WHERE sseguro = ' || psseguro || ' AND ccolumna = 1 ) a INNER JOIN ' || ' (SELECT * FROM estpregungaransegtab WHERE sseguro = ' || psseguro || ' AND ccolumna = 2) b ON a.sseguro = b.sseguro AND a.nriesgo = b.nriesgo AND a.cgarant = b.cgarant AND a.nmovimi = b.nmovimi AND a.nlinea = b.nlinea ' || ' INNER JOIN garangenpro c ON a.cgarant = c.cgarant ' -- Solucion BUG 21759
      || ' INNER JOIN garanpro p ON c.cgarant = p.cgarant ' || ' INNER JOIN productos pp ON p.sproduc = pp.sproduc ' || ' INNER JOIN estseguros se  ON p.sproduc = se.sproduc AND a.sseguro = se.sseguro AND p.cactivi = ' || v_actividad;
      v_tconsulta := v_tconsulta || ' WHERE c.cidioma = ' || pcidioma;
    ELSE
      v_tconsulta := v_tconsulta || ' FROM (SELECT * FROM pregungaransegtab WHERE sseguro = ' || psseguro || ' AND ccolumna = 1) a INNER JOIN ' || ' (SELECT * FROM pregungaransegtab WHERE sseguro = ' || psseguro || ' AND ccolumna = 2) b ON a.sseguro = b.sseguro AND a.nriesgo = b.nriesgo AND a.cgarant = b.cgarant AND a.nmovimi = b.nmovimi AND a.nlinea = b.nlinea ' || ' INNER JOIN garangenpro c ON a.cgarant = c.cgarant ' -- Solucion BUG 21759
      || ' INNER JOIN garanpro p ON c.cgarant = p.cgarant ' || ' INNER JOIN productos pp ON p.sproduc = pp.sproduc ' || ' INNER JOIN seguros se  ON p.sproduc = se.sproduc AND a.sseguro = se.sseguro AND p.cactivi = ' || v_actividad;
      v_tconsulta := v_tconsulta || ' WHERE c.cidioma = ' || pcidioma || ' and a.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro || ') ';
    END IF;
    v_tconsulta := v_tconsulta || ' ORDER BY NORDEN,IMPRESION DESC, NLINEA';
    v_tconsulta := v_tconsulta || ') where cgarant IN (3012,3264,3237,3013,3175,3159,3014,3022,3184,3187,3190,3241,3194,3198,3202,3206,3233,3259,3248,3251,3219,3222,3212,3123,3124,3130,3131,3247,3182,3215,3152,9304) '; --- INICIO/FIN AHYPPLMDCO-195
    --P_CONTROL_ERROR('RV','PAC_ISQLFOR_LCO','v_tconsulta:'||v_tconsulta);
    OPEN vr_cursor FOR v_tconsulta;
    LOOP
      FETCH vr_cursor
      INTO v_norden,
        v_tlinia,
        v_tlinia1,
        v_tlinia2,
        v_nimpresion,
        v_tlinia3,
        v_nlinea;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF pcampo = 1 THEN
      -- INI JFN QT_28989
      IF v_nimpresion = 1 THEN
        --v_ntabs := ' ' || 'esp!1';
        v_ntabs         := ' ';
      ELSIF v_nimpresion = 0 THEN
        --v_ntabs := '\tab \tab \tab \tab ' || 'esp!2';
        v_ntabs         := '\tab \tab \tab \tab ';
      ELSIF v_nimpresion = -1 THEN
        --v_ntabs := '\tab \tab \tab \tab \tab \tab \tab \tab ' || 'esp!3';
        v_ntabs := '\tab \tab \tab \tab \tab \tab \tab \tab ';
      END IF;
      -- FIN JFN QT_28989
      v_tresult   := v_tresult || v_ntabs || v_tlinia1 || '\par ';
    ELSIF pcampo   = 2 THEN
      IF v_tlinia2 = '0' THEN
        SELECT tatribu
        INTO v_tlinia2
        FROM detvalores
        WHERE cvalor = 126
        AND catribu  = NVL(v_cimpres, 59) -- INCLOSA
        AND cidioma  = NVL(pcidioma, 8);
      END IF;
      IF v_nimpresion    = 1 THEN
        v_tresult       := v_tresult || '\par ';
      ELSIF v_nimpresion = 0 THEN
        v_tresult       := v_tresult || '\par ';
      ELSIF v_nimpresion = -1 THEN
        v_tresult       := v_tresult || v_tlinia2 || '\par ';
      END IF;
    ELSIF pcampo   = 3 THEN
      IF v_tlinia2 = '0' THEN
        SELECT tatribu
        INTO v_tlinia2
        FROM detvalores
        WHERE cvalor = 126
        AND catribu  = NVL(v_cimpres, 59) -- INCLOSA
        AND cidioma  = NVL(pcidioma, 8);
      END IF;
      IF v_nimpresion    = 1 THEN
        v_tresult       := v_tresult || '\par ';
      ELSIF v_nimpresion = 0 THEN
        v_tresult       := v_tresult || v_tlinia2 || '\par ';
      ELSIF v_nimpresion = -1 THEN
        v_tresult       := v_tresult || '\par ';
      END IF;
    ELSE
      IF v_tlinia2 = '0' THEN
        SELECT tatribu
        INTO v_tlinia2
        FROM detvalores
        WHERE cvalor = 126
        AND catribu  = NVL(v_cimpres, 59) -- INCLOSA
        AND cidioma  = NVL(pcidioma, 8);
      END IF;
      IF v_nimpresion    = 1 THEN
        v_tresult       := v_tresult || v_tlinia2 || '\par ';
      ELSIF v_nimpresion = 0 THEN
        v_tresult       := v_tresult || '\par ';
      ELSIF v_nimpresion = -1 THEN
        v_tresult       := v_tresult || '\par ';
      END IF;
    END IF;
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ' ';
END f_garantias_riesgo_pyme;
/*****************************************************************
FUNCTION f_amp_lim_Pyme
Devuelve las sumatorias de los limites de indemnizacion de los amparos de un riesgo para Pyme
param IN psseguro  : codigo de seguro
param IN pnriesgo  : numero de riesgo
param IN pnmovimi  : numero de Movimiento
param IN pcidioma  : codigo de idioma
param IN pcampo    : recupera la cod de la garantias, desc de las garantias, el capital
param IN pmodo     : modo EST/POL
return             : texto con las garantias del riesgo
BUG 31409 - LGG
BUG 36151 - LGG
Bug 36480 - 29/08/2017 - LGG - INICIO
Bug 37907 - 27/09/2017 - LGG - INICIO
******************************************************************/
FUNCTION f_amp_lim_pyme(
    psseguro IN NUMBER,
    pnrecibo IN NUMBER,
    pcampo   IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    psproces IN NUMBER DEFAULT NULL) --BUG 47494 MPC 08/03/2019 Adiciona parametro.
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult     VARCHAR2(32000) := '';
    v_tconsulta   VARCHAR2(12000) := '';                                                                                                                                                                                         --BUG 47494 MPC 08/03/2019 Se inicializa variable.
    v_tconsulta_1 VARCHAR2(4000)  := ' select TO_CHAR(decode(b.ctiprec,9, sum(a.iconcep_monpol)*-1, sum(a.iconcep_monpol)), ''999,999,999,999,999.99'') valor from detrecibos a inner join recibos b on a.nrecibo = b.nrecibo '; --BUG 47494 MPC 08/03/2019 Se inicializa variable.
    v_tconsulta_2 VARCHAR2(4000)  := ' and a.nrecibo = ' || pnrecibo;                                                                                                                                                            --BUG 47494 MPC 08/03/2019 Se inicializa variable.
    v_tconsulta_3 VARCHAR2(4000)  := ' where sseguro = ' || psseguro;                                                                                                                                                            --BUG 47494 MPC 08/03/2019 Se inicializa variable.
    v_tconsulta_4 VARCHAR2(4000);
    v_tablaseg    VARCHAR2(30);
    v_act0        NUMBER(1);
    v_actividad   VARCHAR2(20);
    v_icapital    VARCHAR2(300) := '';
    v_valor       VARCHAR2(300);
    v_ncertif      NUMBER;--INTRAO-89 (INTRAO-111) 31/08/2022 GZG
    v_nmovimi      NUMBER;--INTRAO-89 (INTRAO-111) 31/08/2022 GZG
    v_csituac      NUMBER;--INTRAO-89 (INTRAO-111) 31/08/2022 GZG
	--INI DV 28/07/2025 AITSSD-4685 Valor de asistencia caratula producto COPROPIEDADES HDI
	v_sproduc      number;
	v_cactivi      number;
  BEGIN
      Begin
	   select  sproduc,cactivi
	   into v_sproduc,v_cactivi
	   from seguros where sseguro = psseguro;
	  EXCEPTION
	     when NO_DATA_FOUND then
	       select  sproduc,cactivi
			   into v_sproduc,v_cactivi
			   from estseguros where sseguro = psseguro;
	  end;
   --FIN DV 28/07/2025 AITSSD-4685 Valor de asistencia caratula producto COPROPIEDADES HDI
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
      --INI BUG 47494 MPC 08/03/2019 Se adiciona filtro.
    ELSIF NVL(pmodo, 'POL') = 'CAR' THEN
      v_tconsulta_1        := ' select TO_CHAR(decode(b.ctiprec,9, sum(a.iconcep_monpol)*-1, sum(a.iconcep_monpol)), ''999,999,999,999,999.99'') valor from detreciboscar a inner join reciboscar b on a.nrecibo = b.nrecibo and a.sproces = b.sproces ';
      v_tconsulta_2        := v_tconsulta_2||' and a.sproces = '||psproces;
      IF pnrecibo          IS NULL THEN
        --
        v_tconsulta_2 := ' and a.sproces = '||psproces;
        v_tconsulta_3 := ' WHERE b.sseguro in (select s.sseguro
from seguros s, seguros so
where s.npoliza = so.npoliza
AND so.sseguro = '||psseguro||')';
        --
      END IF;
      v_tablaseg := 'seguros';
      --FIN BUG 47494 MPC 08/03/2019 Se adiciona filtro.
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 's.cactivi';
    END IF;
    --Bug 36480 - 29/08/2017 - LGG - INICIO
    --Prima Danos Materiales
    IF pcampo = 1 THEN
      --INI BUG 47494 MPC 08/03/2019 Se modifica.
      --v_tconsulta := ' select TO_CHAR(decode(b.ctiprec,9, sum(a.iconcep_monpol)*-1, sum(a.iconcep_monpol)), ''999,999,999,999,999.99'') valor from detrecibos a inner join recibos b on a.nrecibo = b.nrecibo ';
      v_tconsulta := v_tconsulta_1;
      --FIN BUG 47494 MPC 08/03/2019 Se modifica.
      --INI BUG 47494 MPC 08/03/2019 Se modifica.
      v_tconsulta := v_tconsulta || v_tconsulta_3;
      --v_tconsulta := v_tconsulta || ' where sseguro = ' || psseguro;
      --FIN BUG 47494 MPC 08/03/2019 Se modifica.
