	--FIN INTRAO-111 31/01/2022 GZG (INTRAO-89)
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ' ';
END f_amp_lim_pyme;
