param IN psseguro  : codigo de seguro
param IN pcidioma  : codigo de idioma
param IN pcampo    : recupera la cod de la garantias, desc de las garantias, el capital
param IN pmodo     : modo EST/POL
return             : texto con las garantias del riesgo
BUG 31409 - LGG
BUG 36151 - LGG
******************************************************************/
FUNCTION f_amp_val_lim_pyme(
    psseguro IN NUMBER,
    pcidioma IN NUMBER DEFAULT 1,
    pcampo   IN NUMBER DEFAULT 1,
    ptipo    IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',pnmovimi   IN NUMBER DEFAULT 1)--BUG GZG 0070522 09/09/2021
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(4000);
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_cgarant   VARCHAR2(300);
    v_tgarant   VARCHAR2(3000);
    v_cpregun   VARCHAR2(300);
    v_crespue   VARCHAR2(300);
    v_sproduc   NUMBER(15);--BUG GZG 0070522 09/09/2021
  BEGIN
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
      SELECT sproduc INTO v_sproduc FROM estseguros WHERE sseguro = psseguro;--BUG GZG 0070522 09/09/2021
    ELSE
      v_tablaseg := 'seguros';
      SELECT sproduc INTO v_sproduc FROM seguros WHERE sseguro = psseguro;--BUG GZG 0070522 09/09/2021
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 's.cactivi';
    END IF;
    v_tconsulta := 'select cgarant, (';
    v_tconsulta := v_tconsulta || '        CASE ';
    v_tconsulta := v_tconsulta || '        WHEN cpregun IN (7978,7979) THEN ';
    v_tconsulta := v_tconsulta || '        tgarant||'' mas lucro cesante'' ';
    v_tconsulta := v_tconsulta || '        else  ';
    v_tconsulta := v_tconsulta || '        tgarant ';
    v_tconsulta := v_tconsulta || '        END  ';
    v_tconsulta := v_tconsulta || '      ) tgarant, cpregun,';
    --v_tconsulta := v_tconsulta || 'crespue ';
    v_tconsulta := v_tconsulta || 'TO_CHAR(crespue,''999,999,999,999,999.99'') crespue ';
    v_tconsulta := v_tconsulta || ' from   ';
    v_tconsulta := v_tconsulta || ' (select distinct sgc.cgarant, gg.tgarant, gs.icapital,gr.cpregun, gr.crespue,gs.norden  ';
    v_tconsulta := v_tconsulta || ' from sin_gar_causa sgc, garanseg gs, seguros s, garangen gg , garanpro gp, movseguro m, pregungaranseg gr ';
    v_tconsulta := v_tconsulta || ' where sgc.cactivi = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' and sgc.cmotsin = 0 and sgc.cgarant =  gs.cgarant   ';
    v_tconsulta := v_tconsulta || ' and gs.sseguro = ' || psseguro;
    v_tconsulta := v_tconsulta || ' and gs.sseguro = s.sseguro   ';
    --v_tconsulta := v_tconsulta || ' and gs.nriesgo = ' || pnriesgo;
    v_tconsulta := v_tconsulta || ' and sgc.sproduc = s.sproduc   ';
    v_tconsulta := v_tconsulta || ' and gg.cgarant = gs.cgarant   ';
    v_tconsulta := v_tconsulta || ' and gg.cidioma = ' || pcidioma;
    v_tconsulta := v_tconsulta || ' and gs.cgarant=gp.cgarant ';
    v_tconsulta := v_tconsulta || ' and gs.nmovimi=m.nmovimi ';
    --v_tconsulta := v_tconsulta || ' and gs.nmovimi=' || pnmovimi;
    v_tconsulta := v_tconsulta || ' and gs.sseguro=gr.sseguro ';
    v_tconsulta := v_tconsulta || ' and gr.sseguro=s.sseguro ';
    v_tconsulta := v_tconsulta || ' and gr.nmovimi=gs.nmovimi ';--BUG GZG 0070522 09/09/2021
    v_tconsulta := v_tconsulta || ' and gr.nmovimi=' || pnmovimi;--BUG GZG 0070522 09/09/2021
    --v_tconsulta := v_tconsulta || ' and gr.nmovimi=' || pnmovimi;
    --v_tconsulta := v_tconsulta || ' and gr.nriesgo = ' || pnriesgo;
    v_tconsulta := v_tconsulta || ' and gs.cgarant=gr.cgarant ';
    v_tconsulta := v_tconsulta || ' UNION   ';
    v_tconsulta := v_tconsulta || ' select distinct sgc.cgarant, gg.tgarant, gs.icapital,gr.cpregun, gr.crespue,gs.norden   ';
    v_tconsulta := v_tconsulta || ' from sin_gar_causa sgc, garanseg gs, seguros s, garangen gg  , garanpro gp, movseguro m, pregungaranseg gr ';
    v_tconsulta := v_tconsulta || ' where sgc.cactivi = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' and NOT EXISTS (SELECT 1 FROM sin_gar_causa WHERE sproduc = ' || v_sproduc ||' AND cactivi = 0) and sgc.ccausin = 7021 and sgc.cmotsin = 0  ';--BUG GZG 0070522 09/09/2021
    v_tconsulta := v_tconsulta || ' and sgc.cgarant =  gs.cgarant   ';
    v_tconsulta := v_tconsulta || ' and gs.sseguro = ' || psseguro;
    v_tconsulta := v_tconsulta || ' and gs.sseguro = s.sseguro   ';
    --v_tconsulta := v_tconsulta || ' and gs.nriesgo = ' || pnriesgo;
    v_tconsulta := v_tconsulta || ' and sgc.sproduc = s.sproduc   ';
    v_tconsulta := v_tconsulta || ' and gg.cgarant = gs.cgarant   ';
    v_tconsulta := v_tconsulta || ' and gg.cidioma = ' || pcidioma;
    v_tconsulta := v_tconsulta || ' and gs.nmovimi=m.nmovimi ';
    --v_tconsulta := v_tconsulta || ' and gs.nmovimi=' || pnmovimi;
    v_tconsulta := v_tconsulta || ' and gs.sseguro=gr.sseguro ';
    v_tconsulta := v_tconsulta || ' and gr.sseguro=s.sseguro ';
    --v_tconsulta := v_tconsulta || ' and gr.nmovimi=' || pnmovimi;
    --v_tconsulta := v_tconsulta || ' and gr.nriesgo = ' || pnriesgo;
    v_tconsulta := v_tconsulta || ' and gr.nmovimi=gs.nmovimi ';--BUG GZG 0070522 09/09/2021
    v_tconsulta := v_tconsulta || ' and gr.nmovimi=' || pnmovimi;--BUG GZG 0070522 09/09/2021
    v_tconsulta := v_tconsulta || ' and gs.cgarant=gr.cgarant ';
    v_tconsulta := v_tconsulta || ' order by norden)  ';
    v_tconsulta := v_tconsulta || ' where cgarant in( ';
    v_tconsulta := v_tconsulta || '3114, ';
    v_tconsulta := v_tconsulta || '3115, ';
    v_tconsulta := v_tconsulta || '3117, ';
    v_tconsulta := v_tconsulta || '3119, ';
    v_tconsulta := v_tconsulta || '3122, ';
    v_tconsulta := v_tconsulta || '3123, ';
    v_tconsulta := v_tconsulta || '3182 ';
    v_tconsulta := v_tconsulta || ') ';
    --Valores de Evento
    IF ptipo       = 1 THEN
      v_tconsulta := v_tconsulta || 'and cpregun in (9582,7978) ';
    END IF;
    --Valores de Vigencia
    IF ptipo       = 2 THEN
      v_tconsulta := v_tconsulta || 'and cpregun in (9583,7979) ';
    END IF;
    --P_CONTROL_ERROR('LG','f_amp_val_lim_pyme','v_tconsulta:'||v_tconsulta);
    OPEN vr_cursor FOR v_tconsulta;
    LOOP
      FETCH vr_cursor INTO v_cgarant, v_tgarant, v_cpregun, v_crespue;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF pcampo    = 1 THEN
      v_tresult := v_tresult || v_cgarant || '\par ';
    END IF;
    IF pcampo    = 2 THEN
      v_tresult := v_tresult || v_tgarant || '\par ';
    END IF;
    IF pcampo    = 3 THEN
      v_tresult := v_tresult || v_cpregun || '\par ';
    END IF;
    IF pcampo    = 4 THEN
      v_tresult := v_tresult || v_crespue || '\par ';
    END IF;
  END LOOP;
  --P_CONTROL_ERROR('LG','f_amp_val_lim_pyme','v_tresult:'||v_tresult);
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ' ';
END f_amp_val_lim_pyme;
/*****************************************************************
FUNCTION f_importes_franquicias_pyme
param IN psseguro  : codigo de seguro
param IN pcampo  :  campo a devolver 1: porcentaje, 2:valor,campo a devolver 10: porcentaje con el '%', campo a devolver 2:valor ,campo a devolver 20 :valor con el literal 'smmlv'
param IN pnriesgo  : numero de riesgo
param IN pcidioma  : idioma
param IN pmodo     : modo EST/POL
param IN pgararc   : numero de garantia
return             : texto con los importes de franquicia.
BUG 31409 - RV - FC
BUG 36151 - LGG
******************************************************************/
FUNCTION f_importes_franquicias_pyme(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pgararc  IN NUMBER DEFAULT NULL,
    psproces IN NUMBER DEFAULT NULL) --MPC BUG 47494 08/03/2019 Se adiciona parametro.
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(4000);
    v_tlinia    VARCHAR2(500);--BUG 0048449 - 17/01/2019 - CASL - Se aumenta taÃ±ano de variable
    v_tpargar   VARCHAR2(300);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot VARCHAR2(200);
    v_ctipcap garanpro.ctipcap%TYPE;
    v_cimpres garanpro.cimpres%TYPE;
    v_npargar   NUMBER := 0;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_porcded   NUMBER;
    v_smmlv     NUMBER;
    v_sseguro garanseg.sseguro%TYPE;
    v_cgarant garanseg.cgarant%TYPE;
    v_nmovimi garanseg.nmovimi%TYPE;
    v_norden garanpro.norden%TYPE;
    v_nriesgo garanseg.nriesgo%TYPE;
    v_csituac VARCHAR2(100);
    v_tnivel  VARCHAR2(200);
  BEGIN
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := 'SELECT s.sseguro, p.cgarant, s.nmovimi, p.norden, s.nriesgo';
    ELSE
      v_tconsulta := 'SELECT s.sseguro, p.cgarant, s.nmovimi, p.norden, s.nriesgo';
    END IF;
    v_tconsulta         := v_tconsulta || ' FROM  garangen g, garanpro p, productos pp, ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' estgaranseg s, estseguros se';
      v_csituac         := '(0,7,5,2,4)';
    ELSE
      v_tconsulta                                 := v_tconsulta || ' garanseg s, seguros se';
	--INI INTRAO-89 (INTRAO-111) 31/08/2022 GZG
     --     IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
     --     v_csituac                                 := '(0,7,5,2)';
     -- ELSE
        v_csituac := '(0,7,5,2,4)';
     -- END IF;
	--FIN INTRAO-89 (INTRAO-111) 31/08/2022 GZG
    END IF;
    --
    v_tconsulta   := v_tconsulta || ' WHERE g.cgarant = s.cgarant';
    v_tconsulta   := v_tconsulta || ' AND p.cgarant = s.cgarant';
    v_tconsulta   := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta   := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta   := v_tconsulta || ' AND p.sproduc = pp.sproduc';
    v_tconsulta   := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
    v_tconsulta   := v_tconsulta || ' AND se.csituac in ' || v_csituac;
    v_tconsulta   := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta   := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
    v_tconsulta   := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    IF pgararc     = 1 THEN
      --INI BUG 72406 HRE 23/12/2021
      v_tconsulta := v_tconsulta ||
       ' AND (p.cgarpadre = 3131 OR
       p.cgardep IN (SELECT cgarant FROM garanpro p2
                      WHERE  p2.sproduc = se.sproduc
                        AND p2.cgardep = 3131
                     )
        AND p.sproduc =  se.sproduc) ';
      --FIN BUG 72406 HRE 23/12/2021
    ELSIF pgararc  = 2 THEN
      v_tconsulta := v_tconsulta || ' AND p.cgarpadre IN (3119,3124,3149,3131)';--BUG 0052547 19/06/2019 GZG
      v_tconsulta := v_tconsulta || ' AND p.cgarant NOT IN (3213,3218,3272,3275,9305)'; --- INICIO/FIN AHYPPLMDCO-195
    ELSE
      v_tconsulta := v_tconsulta || ' AND p.cgarpadre IS NULL';
    END IF;
    --
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' AND s.cobliga = 1';
      v_tconsulta       := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM ESTGARANSEG WHERE sseguro =' || psseguro;
      v_tconsulta       := v_tconsulta || ')';
      SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
        || sproduc
        || ', '
        || cactivi
        || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
      INTO v_tpargar
      FROM
        (SELECT seg.sproduc,
          seg.cactivi
        FROM estseguros seg
        WHERE seg.sseguro = psseguro
        );
  ELSE
    v_tconsulta := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro;
    v_tconsulta := v_tconsulta || ')';
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  END IF;
  v_tconsulta := v_tconsulta || v_tpargar;
  IF pgararc IN (1, 2) THEN
    v_tconsulta := v_tconsulta || ' ORDER BY p.norden, p.cgarant';
  ELSE
    v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  END IF;
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_sseguro, v_cgarant, v_nmovimi, v_norden, v_nriesgo;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    BEGIN
      IF NVL(pmodo, 'POL') = 'EST' THEN
        SELECT bd.impvalor1 porcded,
          bd.impmin smmlv,
          bn.tnivel
        INTO v_porcded,
          v_smmlv,
          v_tnivel
        FROM bf_progarangrup bp,
          estbf_bonfranseg bf,
          bf_detnivel bd,
          estseguros s,
          bf_desnivel bn
        WHERE s.sseguro = v_sseguro
        AND bp.sproduc  = s.sproduc
        AND bp.cgarant  = v_cgarant
        AND bp.cempres  = s.cempres
        AND bp.cactivi  = s.cactivi
        AND bf.sseguro  = s.sseguro
        AND bf.cgrup    = bp.codgrup
        AND bf.ctipgrup = 2
        AND bf.nmovimi  = DECODE(s.cramo, 700,
          (SELECT MAX(nmovimi)
          FROM estbf_bonfranseg
          WHERE sseguro = v_sseguro
          AND nriesgo   = v_nriesgo
          ), DECODE(s.cramo, 701,
          (SELECT MAX(nmovimi)
          FROM estbf_bonfranseg
          WHERE sseguro = v_sseguro
          AND nriesgo   = v_nriesgo
          ),
          (SELECT MAX(nmovimi) FROM estbf_bonfranseg bff WHERE bff.sseguro = v_sseguro
          )))
        AND bd.cgrup    = bf.cgrup
        AND bd.csubgrup = bf.csubgrup
        AND bd.cversion = bf.cversion
        AND bd.cnivel   = bf.cnivel
          -- AND bd.cvalor1 = 1
          -- AND bd.cimpmin IN(4, 55)
        AND bd.cgrup    = bn.cgrup
        AND bd.csubgrup = bn.csubgrup
        AND bd.cversion = bn.cversion
        AND bd.cnivel   = bn.cnivel
        AND bn.cidioma  = 8;
        --INI BUG 0071197 GZG 01/10/2021
      ELSIF NVL(pmodo, 'POL') = 'CAR' THEN
        SELECT bd.impvalor1 porcded,
          bd.impmin smmlv,
          bn.tnivel
        INTO v_porcded,
          v_smmlv,
          v_tnivel
        FROM bf_progarangrup bp,
          bf_bonfransegcar bf,
          bf_detnivel bd,
          seguros s,
          bf_desnivel bn
        WHERE s.sseguro = v_sseguro
        AND bp.sproduc  = s.sproduc
        AND bp.cgarant  = v_cgarant
        AND bp.cempres  = s.cempres
        AND bp.cactivi  = s.cactivi
        AND bf.sseguro  = s.sseguro
        AND bf.cgrup    = bp.codgrup
        AND bf.ctipgrup = 2
        AND bf.sproces  = psproces
        AND bd.cgrup    = bf.cgrup
        AND bd.csubgrup = bf.csubgrup
        AND bd.cversion = bf.cversion
        AND bd.cnivel   = bf.cnivel
        AND bd.cgrup    = bn.cgrup
        AND bd.csubgrup = bn.csubgrup
        AND bd.cversion = bn.cversion
        AND bd.cnivel   = bn.cnivel
        AND bn.cidioma  = 8;
        --FIN BUG 0071197 GZG 01/10/2021
      ELSE
        SELECT bd.impvalor1 porcded,
          bd.impmin smmlv,
          bn.tnivel
        INTO v_porcded,
          v_smmlv,
          v_tnivel
        FROM bf_progarangrup bp,
          bf_bonfranseg bf,
          bf_detnivel bd,
          seguros s,
          bf_desnivel bn
        WHERE s.sseguro = v_sseguro
        AND bp.sproduc  = s.sproduc
        AND bp.cgarant  = v_cgarant
        AND bp.cempres  = s.cempres
        AND bp.cactivi  = s.cactivi
        AND bf.sseguro  = s.sseguro
        AND bf.cgrup    = bp.codgrup
        AND bf.ctipgrup = 2
        AND bf.nmovimi  = DECODE(s.cramo, 700,
          (SELECT MAX(nmovimi)
          FROM bf_bonfranseg
          WHERE sseguro = v_sseguro
          AND nriesgo   = v_nriesgo
          ), DECODE(s.cramo, 701,
          (SELECT MAX(nmovimi)
          FROM bf_bonfranseg
          WHERE sseguro = v_sseguro
          AND nriesgo   = v_nriesgo
          ),
          (SELECT MAX(nmovimi) FROM bf_bonfranseg bff WHERE bff.sseguro = v_sseguro
          )))
        AND bd.cgrup    = bf.cgrup
        AND bd.csubgrup = bf.csubgrup
        AND bd.cversion = bf.cversion
        AND bd.cnivel   = bf.cnivel
          -- AND bd.cvalor1 = 1
          -- AND bd.cimpmin IN(4, 55)
        AND bd.cgrup    = bn.cgrup
        AND bd.csubgrup = bn.csubgrup
        AND bd.cversion = bn.cversion
        AND bd.cnivel   = bn.cnivel
        AND bn.cidioma  = 8;
      END IF;
      IF pcampo    = 1 AND v_cgarant NOT IN (756, 757) THEN
        v_tlinia  := v_porcded;
      ELSIF pcampo = 10 AND v_cgarant NOT IN (756, 757) THEN
        v_tlinia  := v_porcded || ' % ';
      ELSIF pcampo = 2 AND v_cgarant NOT IN (756, 757) THEN
        v_tlinia  := v_smmlv;
      ELSIF pcampo = 20 AND v_cgarant NOT IN (756, 757) THEN
        v_tlinia  := v_smmlv || ' smmlv ';
      ELSIF pcampo = 3 THEN
        v_tlinia  := v_tnivel;
      ELSE
        v_tlinia := '';
      END IF;
    EXCEPTION
    WHEN OTHERS THEN
      v_tlinia := ' ';
    END;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_franquicias_pyme;
--
--FIN BUG 0031409 - 08/05/2017 - LGG
--
/*****************************************************************
FUNCTION f_benespseg_rel
Para que traiga todos los beneficiarios
param IN psidepag  :
param IN pcidioma  :
param IN pcamp     : Codigo de campo
return             : texto
Bug 0031409 - 07/06/2017 - LRG
BUG 36151 - LGG
******************************************************************/
FUNCTION f_benespseg_rel(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER,
    pcidioma IN NUMBER,
    pcamp    IN NUMBER)
  RETURN VARCHAR2
IS
  v_tresult  VARCHAR2(4000);
  v_tresult2 VARCHAR2(4000);
BEGIN
  FOR i IN
  (SELECT SUBSTR(f_dades_persona(ben.sperson, 8, pcidioma, 'POL'), 1, 5)
    || ' '
    || f_dades_persona(ben.sperson, 1, pcidioma, 'POL') idbenef,
    (SELECT TRIM(tnombre)
      || ' '
      || TRIM(tapelli1
      || ' '
      || tapelli2)
    FROM per_detper
    WHERE sperson = ben.sperson
    AND ROWNUM    = 1
    ) nombenef,
    ff_desvalorfijo(1054, pcidioma, ben.cparen) parentbenef,
    ben.pparticip porcbenef,
    f_dades_persona(ben.sperson_tit, 8, pcidioma, 'POL')
    || ' '
    || f_dades_persona(ben.sperson_tit, 1, pcidioma, 'POL') contbenef,
    NULL acrebenef,
    (SELECT tvalcon
    FROM per_contactos
    WHERE sperson = ben.sperson
    AND ROWNUM    = 1
    AND ctipcon   = 1
    ) telefonobnf,
    --pac_isqlfor.f_poblacion(ben.sperson, 1) bnfpoblac,  -- RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios Se pone en comentario ya que se va a realizar el proceso abajo en el recorrido de cursor
    NULL bnfpoblac, -- RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios Se envia NULL ya que se va a realizar el proceso abajo en el recorrido de cursor
    -- INI RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios Se pone en comentario ya que se va a realizar el proceso abajo en el recorrido de cursor
    /*PAC_ISQLFOR_LCOL.F_DIRECCION(BEN.SPERSON, (select max(CDOMICI) as RMAX_DOMICI from PER_DIRECCIONES where SPERSON = BEN.SPERSON)) -- BUG 0021554/0021678/0021636 SYT 14/10/2015 Se ajusta ya que se puede tener mas de un beneficiario
    (SELECT pac_isqlfor_lcol.f_direccion(ben.sperson, rmax_domici,
    'POL')
    FROM (SELECT MAX(cdomici) AS rmax_domici
    FROM per_direcciones
    WHERE sperson = (SELECT sperson
    FROM benespseg
    WHERE sseguro = psseguro
    AND cgarant = 0
    AND nmovimi =
    (SELECT MAX(nmovimi)
    FROM benespseg
    WHERE sseguro = psseguro
    AND nmovimi <= pnmovimi))))*/
    NULL bnfdirec,
    ben.sperson -- Bug 0019273-VCG-15/07/2015 -- RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios Se envia NULL ya que se va a realizar el proceso abajo en el recorrido de cursor
    -- FIN RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios Se pone en comentario ya que se va a realizar el proceso abajo en el recorrido de cursor
  FROM benespseg ben
  WHERE ben.sseguro = psseguro
    --AND cgarant = 0   --beneficiarios de riesgo
  AND nmovimi =
    (SELECT MAX(nmovimi)
    FROM benespseg
    WHERE sseguro = psseguro
    AND nmovimi  <= pnmovimi
    )
  ORDER BY nriesgo ASC,
    sperson_tit ASC,
    pparticip DESC,
    fmovimi ASC,
    ROWID ASC
  )
  LOOP
    IF pcamp     = 1 THEN
      v_tresult := v_tresult || i.idbenef || ' \par ';
    ELSIF pcamp  = 2 THEN
      v_tresult := v_tresult || i.nombenef || ' \par ';
    ELSIF pcamp  = 3 THEN
      v_tresult := v_tresult || i.parentbenef || ' \par ';
    ELSIF pcamp  = 4 THEN
      v_tresult := v_tresult || i.porcbenef || ' \par ';
    ELSIF pcamp  = 5 THEN
      v_tresult := v_tresult || i.contbenef || ' \par ';
    ELSIF pcamp  = 6 THEN
      v_tresult := v_tresult || i.acrebenef || ' \par ';
    ELSIF pcamp  = 7 THEN
      v_tresult := v_tresult || i.telefonobnf || ' \par ';
    ELSIF pcamp  = 8 THEN
      -- INI RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios. Se busca en asegurados - tomadores - La Direccion de Residencia -  La Maxima Direccion
      --v_tresult := v_tresult || i.bnfpoblac || ' \par ';
      BEGIN
        SELECT pac_isqlfor.f_poblacion(i.sperson, rmax_domici)
          || ' \par '
        INTO v_tresult2-- BUG 0055915 29/10/2019 GZG
        FROM
          (SELECT b.cdomici AS rmax_domici
          FROM benespseg a,
            asegurados b
          WHERE a.sseguro = psseguro
          AND a.sseguro   = b.sseguro
          AND a.sperson   = b.sperson
          AND a.sperson   = i.sperson
            --AND a.cgarant = 0
          AND a.nmovimi =
            (SELECT MAX(nmovimi)
            FROM benespseg
            WHERE sseguro = psseguro
            AND nmovimi  <= pnmovimi
            )
          );
         ---p_control_error('GZG','Direccion',psseguro|| ' \par '||pnmovimi|| ' \par '||i.sperson||v_tresult);
        -- INI BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
        IF v_tresult2 = ' \par ' THEN-- BUG 0055915 29/10/2019 GZG
          RAISE NO_DATA_FOUND;
        END IF;
        -- FIN BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
        v_tresult := v_tresult || v_tresult2;-- BUG 0055915 29/10/2019 GZG
      EXCEPTION
      WHEN NO_DATA_FOUND THEN
        BEGIN
          SELECT pac_isqlfor.f_poblacion(i.sperson, rmax_domici)
            || ' \par '
          INTO v_tresult2-- BUG 0055915 29/10/2019 GZG
          FROM
            (SELECT b.cdomici AS rmax_domici
            FROM benespseg a,
              tomadores b
            WHERE a.sseguro = psseguro
            AND a.sseguro   = b.sseguro
            AND a.sperson   = b.sperson
            AND a.sperson   = i.sperson
              --AND a.cgarant = 0 --Para que traiga todos los beneficiarios
            AND a.nmovimi =
              (SELECT MAX(nmovimi)
              FROM benespseg
              WHERE sseguro = psseguro
              AND nmovimi  <= pnmovimi
              )
            );
         --   p_control_error('GZG','Direccion2',psseguro|| ' \par '||pnmovimi|| ' \par '||i.sperson||v_tresult);
          -- INI BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
          IF v_tresult2 = ' \par ' THEN-- BUG 0055915 29/10/2019 GZG
            RAISE NO_DATA_FOUND;
          END IF;
          -- FIN BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
          v_tresult := v_tresult || v_tresult2;-- BUG 0055915 29/10/2019 GZG
        EXCEPTION
        WHEN NO_DATA_FOUND THEN
          BEGIN
            SELECT pac_isqlfor.f_poblacion(i.sperson, MAX(cdomici))
              || ' \par ' AS rmax_domici -- BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
            INTO v_tresult2-- BUG 0055915 29/10/2019 GZG
            FROM per_direcciones
            WHERE sperson = i.sperson
            AND ctipdir   = 9;
            -- INI BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
            --p_control_error('GZG','Direccion3',psseguro|| ' \par '||pnmovimi|| ' \par '||i.sperson||v_tresult);
            IF v_tresult2 = ' \par ' THEN-- BUG 0055915 29/10/2019 GZG
              RAISE NO_DATA_FOUND;
            END IF;
            -- FIN BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
          v_tresult := v_tresult || v_tresult2;-- BUG 0055915 29/10/2019 GZG
          EXCEPTION
          WHEN NO_DATA_FOUND THEN
            BEGIN
              SELECT pac_isqlfor.f_poblacion(i.sperson, MAX(cdomici))
                || ' \par ' AS rmax_domici -- BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
              INTO v_tresult2-- BUG 0055915 29/10/2019 GZG
              FROM per_direcciones
              WHERE sperson = i.sperson;
              v_tresult := v_tresult || v_tresult2;-- BUG 0055915 29/10/2019 GZG
            EXCEPTION
            WHEN OTHERS THEN
              RETURN ('');
            END;
          END;
        END;
      END;
      -- FIN RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios. Se busca en asegurados - tomadores - La Direccion de Residencia -  La Maxima Direccion
    ELSIF pcamp = 9 THEN
      -- INI RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios. Se busca en asegurados - tomadores - La Direccion de Residencia -  La Maxima Direccion
      --v_tresult := v_tresult || i.bnfdirec || ' \par ';
      BEGIN
        SELECT f_direccion(i.sperson, rmax_domici)-- BUG 0055915 29/10/2019 GZG
          || ' \par '
        INTO v_tresult2-- BUG 0055915 29/10/2019 GZG
        FROM
          (SELECT b.cdomici AS rmax_domici
          FROM benespseg a,
            asegurados b
          WHERE a.sseguro = psseguro
          AND a.sseguro   = b.sseguro
          AND a.sperson   = b.sperson
          AND a.sperson   = i.sperson
            --AND a.cgarant = 0
          AND a.nmovimi =
            (SELECT MAX(nmovimi)
            FROM benespseg
            WHERE sseguro = psseguro
            AND nmovimi  <= pnmovimi
            )
          );
        -- INI BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
        IF v_tresult2 = ' \par ' THEN-- BUG 0055915 29/10/2019 GZG
          RAISE NO_DATA_FOUND;
        END IF;
        -- FIN BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
     v_tresult := v_tresult || v_tresult2;-- BUG 0055915 29/10/2019 GZG
      EXCEPTION
      WHEN NO_DATA_FOUND THEN
        BEGIN
          SELECT f_direccion(i.sperson, rmax_domici)-- BUG 0055915 29/10/2019 GZG
            || ' \par '
          INTO v_tresult2-- BUG 0055915 29/10/2019 GZG
          FROM
            (SELECT b.cdomici AS rmax_domici
            FROM benespseg a,
              tomadores b
            WHERE a.sseguro = psseguro
            AND a.sseguro   = b.sseguro
            AND a.sperson   = b.sperson
            AND a.sperson   = i.sperson
              --AND a.cgarant = 0 --Para que traiga todos los beneficiarios
            AND a.nmovimi =
              (SELECT MAX(nmovimi)
              FROM benespseg
              WHERE sseguro = psseguro
              AND nmovimi  <= pnmovimi
              )
            );
          -- INI BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
          IF v_tresult2 = ' \par ' THEN-- BUG 0055915 29/10/2019 GZG
            RAISE NO_DATA_FOUND;
          END IF;
          -- FIN BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
	          v_tresult := v_tresult || v_tresult2;-- BUG 0055915 29/10/2019 GZG

        EXCEPTION
        WHEN NO_DATA_FOUND THEN
          BEGIN
            SELECT f_direccion(i.sperson, MAX(cdomici))-- BUG 0055915 29/10/2019 GZG
              || ' \par ' AS rmax_domici
            INTO v_tresult2-- BUG 0055915 29/10/2019 GZG
            FROM per_direcciones
            WHERE sperson = i.sperson
            AND ctipdir   = 9;
            -- INI BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
            IF v_tresult2 = ' \par ' THEN-- BUG 0055915 29/10/2019 GZG
              RAISE NO_DATA_FOUND;
            END IF;
            -- FIN BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
          v_tresult := v_tresult || v_tresult2;-- BUG 0055915 29/10/2019 GZG
          EXCEPTION
          WHEN NO_DATA_FOUND THEN
            BEGIN
              SELECT f_direccion(i.sperson, MAX(cdomici))-- BUG 0055915 29/10/2019 GZG
                || ' \par ' AS rmax_domici
              INTO v_tresult2-- BUG 0055915 29/10/2019 GZG
              FROM per_direcciones
              WHERE sperson = i.sperson;
              v_tresult := v_tresult || v_tresult2;-- BUG 0055915 29/10/2019 GZG
            EXCEPTION
            WHEN OTHERS THEN
              RETURN ('');
            END;
          END;
        END;
      END;
      -- FIN RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios. Se busca en asegurados - tomadores - La Direccion de Residencia -  La Maxima Direccion
      -- 08/06/2017 LRGG  - TIPO DE BENEFICIARIIO
    ELSIF pcamp = 10 THEN
      BEGIN
        v_tresult2 := '';
        SELECT DISTINCT
          (SELECT tatribu
          FROM detvalores
          WHERE cidioma = 8
          AND cvalor    = 1053
          AND catribu   = b.ctipben
          )
        INTO v_tresult2
        FROM benespseg b
        WHERE b.sseguro = psseguro
        AND b.sperson   = i.sperson;
        --P_CONTROL_ERROR('LG','f_benespseg_rel','2.1 v_tresult2:'||v_tresult2 ||' '||i.sperson);
        v_tresult := v_tresult || v_tresult2 || ' \par ';
      EXCEPTION
      WHEN OTHERS THEN
        RETURN ('');
      END;
    END IF;
    -- FIN 08/06/2017 LRGG TIPO DE BENEFICIARIIO
  END LOOP;
  RETURN (REPLACE(f_jrep_trad(v_tresult), CHR(39), ''));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_benespseg_rel;
