/*****************************************************************
FUNCTION f_datos_persona_Pyme
Para que traiga los datos de las personas
param IN pmt_sseguro  :
param IN p_tipo  :
param IN p_mode  :
param IN pcamp     :
return             : texto
BUG 32232 - 11/04/2017 - LRGG
BUG 36151 - LGG
******************************************************************/
FUNCTION f_datos_persona_pyme(
    pmt_sseguro IN NUMBER,
    p_tipo      IN NUMBER,
    pmt_idioma  IN NUMBER DEFAULT 1,
    p_mode      IN VARCHAR2 DEFAULT 'POL')
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    v_tablaseg VARCHAR2(30);
    v_act0     NUMBER(1);
    vr_cursor r_cursor;
    v_tresult       VARCHAR2(32000) := '';
    v_tconsulta     VARCHAR2(4000);
    v_principal     VARCHAR2(1);
    v_asegurado     VARCHAR2(4000);
    v_tipoidnumass  VARCHAR2(2000);
    v_assdirec      VARCHAR2(4000);
    v_asspoblac     VARCHAR2(3000);
    v_telefonoass   VARCHAR2(2000);
    v_fechanacimass VARCHAR2(3000);
    --p_tipo 1=Asegurado Ppal, 2 = Asegurado, 3=Tipo Identificacion, 4=Direccion, 5=Poblaci??n, 6=Telefono, 7=Fecha Nacimiento
    --INI BUG 0066543 GZG 15/03/2021
    v_cdomici NUMBER(5) DEFAULT 1;--BUG 0067776 GZG 15/04/2021
    v_sproduc NUMBER(11);
    --FIN BUG 0066543 GZG 15/03/2021
  BEGIN
    --15/06/2017
    v_tconsulta := 'BEGIN select count(*)' || ' INTO :v_act0 from asegurados WHERE SSEGURO = :psseguro; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN pmt_sseguro;
    IF v_act0     > 0 THEN
      v_tablaseg := 'asegurados';
    ELSE
      v_tablaseg := 'tomadores';
    END IF;
    --INI BUG 0066543 GZG 15/03/2021
    IF NVL(p_mode, 'POL') = 'EST' THEN
         SELECT sproduc INTO v_sproduc FROM estseguros WHERE sseguro = pmt_sseguro;
     ELSE
         SELECT sproduc INTO v_sproduc FROM seguros WHERE sseguro = pmt_sseguro;
    END IF;
    IF v_tablaseg = 'asegurados' and NVL(f_parproductos_v ( v_sproduc, 'DIRECCION_PROPERTY' ),0) = 1 then
    SELECT COUNT(cdomici) INTO  v_cdomici FROM ASEGURADOS WHERE SSEGURO = pmt_sseguro;
        IF v_cdomici = 0 THEN
            BEGIN
             SELECT T.CDOMICI
               INTO  v_cdomici
               FROM TOMADORES T,
                    ASEGURADOS S
               WHERE S.SSEGURO = pmt_sseguro
                 AND S.SSEGURO   = T.SSEGURO
                 AND S.SPERSON   = T.SPERSON
                 AND ROWNUM      = 1;
            EXCEPTION
            WHEN NO_DATA_FOUND THEN
              v_cdomici := 1;--BUG 0067776 GZG 15/04/2021
            END;
        END IF;
    END IF;
    --FIN BUG 0066543 GZG 15/03/2021
    IF p_mode IN ('POL','CAR') THEN --BUG 47494 MPC 07/05/2019 Se adiciona condiciÃ³n.
      --v_tconsulta:='SELECT  a.nordeninc, pac_isqlfor_lcol.f_dades_persona(a.sperson, 4, ';
      IF v_act0      > 0 THEN
        v_tconsulta := 'SELECT  a.nordeninc, pac_isqlfor_lcol.f_dades_persona(a.sperson, 4, ';
      ELSE
        v_tconsulta := 'SELECT  '''' nordeninc, pac_isqlfor_lcol.f_dades_persona(a.sperson, 4, ';
      END IF;
      v_tconsulta := v_tconsulta || '        ' || pmt_idioma || '  , ''POL'') ';
      v_tconsulta := v_tconsulta || '        || '' '' ';
      v_tconsulta := v_tconsulta || '        || pac_isqlfor_lcol.f_dades_persona(a.sperson, 5, ';
      v_tconsulta := v_tconsulta || '        ' || pmt_idioma || '  , ''POL'') asegurado, ';
      v_tconsulta := v_tconsulta || '        pac_isqlfor_lcol.f_dades_persona(a.sperson, ' || pmt_idioma || ', ';
      v_tconsulta := v_tconsulta || '        ' || pmt_idioma || '  , ''POL'') ';
      v_tconsulta := v_tconsulta || '        || '' '' ';
      v_tconsulta := v_tconsulta || '        || pac_isqlfor_lcol.f_dades_persona(a.sperson, 1, ';
      v_tconsulta := v_tconsulta || '        ' || pmt_idioma || '  , ''POL'') tipoidnumass,         ';
      v_tconsulta := v_tconsulta || '       pac_isqlfor_lcol.f_direccion(a.sperson, NVL(a.cdomici, NVL(' || v_cdomici || ', 1)), ''POL'') assdirec, ';--BUG 0066543 GZG 07/04/2021
      v_tconsulta := v_tconsulta || '       pac_isqlfor.f_poblacion(a.sperson, NVL(a.cdomici, NVL(' || v_cdomici || ', 1))) asspoblac, ';--BUG 0066543 GZG 11/03/2021
      v_tconsulta := v_tconsulta || ' NVL(pac_isqlfor.f_telefono(a.sperson),pac_isqlfor_lcol.f_telefono_pyme(a.sseguro)) telefonoass, ';
      v_tconsulta := v_tconsulta || '       pac_isqlfor_lcol.f_dades_persona(a.sperson, 9, ' || pmt_idioma || '  , ''POL'') fechanacimass ';
      --v_tconsulta := v_tconsulta ||' FROM asegurados a inner join per_detper d ';
      v_tconsulta := v_tconsulta || ' FROM ' || v_tablaseg || ' a inner join per_detper d ';
      v_tconsulta := v_tconsulta || ' on a.sperson=d.sperson ';
      v_tconsulta := v_tconsulta || ' WHERE a.SSEGURO=' || pmt_sseguro;-- BUG 47494 MPC 07/05/2019 Se comenta condiciÃ³n ||' ORDER BY nordeninc ASC'; --JMOS 31/12/2018 QT-0046530 se agrega order by para que muestre el asegurado principal
      --INI BUG 47494 MPC 07/05/2019 Se crea condiciÃ³n.
      IF p_mode = 'CAR' AND v_act0 > 0 THEN
        --
        v_tconsulta := v_tconsulta || ' AND a.FFECFIN IS NULL ORDER BY nordeninc ASC ' ;
        --
      ELSE
        --
        v_tconsulta := v_tconsulta || ' ORDER BY nordeninc ASC ' ;
        --
      END IF;
      --FIN BUG 47494 MPC 07/05/2019 Se crea condiciÃ³n.
      --P_CONTROL_ERROR('LG','f_datos_persona_Pyme','v_tconsulta:'||v_tconsulta);
      OPEN vr_cursor FOR v_tconsulta;
      LOOP
        FETCH vr_cursor
        INTO v_principal,
          v_asegurado,
          v_tipoidnumass,
          v_assdirec,
          v_asspoblac,
          v_telefonoass,
          v_fechanacimass;
      EXIT
    WHEN vr_cursor%NOTFOUND;
      IF p_tipo    = 1 THEN
        v_tresult := v_tresult || v_principal || '\par ';
      END IF;
      IF p_tipo    = 2 THEN
        v_tresult := v_tresult || v_asegurado || '\par ';
      END IF;
      IF p_tipo    = 3 THEN
        v_tresult := v_tresult || v_tipoidnumass || '\par ';
      END IF;
      IF p_tipo    = 4 THEN
        v_tresult := v_tresult || v_assdirec || '\par ';
      END IF;
      IF p_tipo    = 5 THEN
        v_tresult := v_tresult || v_asspoblac || '\par ';
      END IF;
      IF p_tipo    = 6 THEN
        v_tresult := v_tresult || v_telefonoass || '\par ';
      END IF;
      IF p_tipo    = 7 THEN
        v_tresult := v_tresult || v_fechanacimass || '\par ';
      END IF;
    END LOOP;
    -- ELSE
  END IF;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_datos_persona_pyme;
--
--FIN BUG 0032232 - 11/04/2017 - LRGG
