/*******************************************************************
FUNCTION f_garantias_certif_rc
Devuelve todas las garantias de todos los certificados N
param IN psseguro  : codigo de seguro
param IN pcidioma  : codigo de idioma
param IN pgararc   : 0-Todo riesgo/1-RC/2-Corriente debil, manejo y lucro
return             : texto con las garantias del riesgo
Bug 31409 - 24/07/2017 - LGG
BUG 36151 - LGG
*****************************************************************/
FUNCTION f_garantias_certif_rc(
    psseguro IN NUMBER,
    pcidioma IN NUMBER DEFAULT 1,
    pdummy   IN NUMBER DEFAULT 0,
    pgararc  IN NUMBER DEFAULT NULL,
    ptablas  IN VARCHAR2 DEFAULT 'POL', --BUG 47494 MPC 08/03/2019 Se adiciona parametro de entrada.
    psproces IN NUMBER DEFAULT NULL)    --BUG 47494 MPC 08/03/2019 Se adiciona parametro de entrada.
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult     VARCHAR2(32000) := '';
    v_tconsulta   VARCHAR2(2000);
    v_tconsulta_1 VARCHAR2(2000) := ''; --BUG 47494 MPC 08/03/2019 Se adiciona variable.
    v_tlinia      VARCHAR2(200);
    v_tlinia1     VARCHAR2(200);
    v_tlinia2     VARCHAR2(200);
    v_porcentot   NUMBER;
    v_porceninm   NUMBER;
    v_porcencon   NUMBER;
    v_cgarant     NUMBER;
    v_norden garanpro.norden%TYPE;
    v_tpargar   VARCHAR2(200);
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
  BEGIN
    v_tablaseg  := 'seguros';
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    v_tconsulta := 'SELECT p.norden,REPLACE(pac_isqlfor_lcol.f_des_garpro(se.sseguro,s.nriesgo,' || NVL(pcidioma, 2) || ',p.cgarant,se.sproduc,''POL''), CHR(39), CHR(39) || CHR(39)) a' || ',NVL(sum((select sum(crespue) from pregungaranseg where sseguro in (select sseguro from seguros where  npoliza = se.npoliza and ncertif !=0 and cpregun in (5851,5852)) and cgarant = s.cgarant)),0) porcentot' || ',NVL(sum((select sum(crespue) from pregungaranseg where sseguro in (select sseguro from seguros where  npoliza = se.npoliza and ncertif !=0 and cpregun in (5851)) and cgarant = s.cgarant)),0) porceninm' || ',NVL(sum((select sum(crespue) from pregungaranseg where sseguro in (select sseguro from seguros where  npoliza = se.npoliza and ncertif !=0 and cpregun in (5852)) and cgarant = s.cgarant)),0) porcencon';
    IF pgararc IN (1, 2) THEN
      v_tconsulta := v_tconsulta || ', p.cgarant';
    END IF;
    v_tconsulta := v_tconsulta || ' FROM garanpro p, ';
    --INI BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
    IF ptablas = 'CAR' THEN
      --
      v_tconsulta   := v_tconsulta || 'garancar s, seguros se';
      v_tconsulta_1 := ' and s.sproces = '||psproces;
      --
    ELSE
      v_tconsulta_1 := ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro || ')';
      --FIN BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
      v_tconsulta := v_tconsulta || 'garanseg s, seguros se';
    END IF; --BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
    v_tconsulta   := v_tconsulta || ' WHERE ';
    v_tconsulta   := v_tconsulta || ' p.cgarant = s.cgarant';
    v_tconsulta   := v_tconsulta || v_tconsulta_1; --BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
    v_tconsulta   := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta   := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta   := v_tconsulta || ' AND se.csituac in (0,7,5,2)';
    v_tconsulta   := v_tconsulta || ' AND p.CACTIVI = ' || v_actividad;
    IF pgararc     = 1 THEN
       --INI BUG 72406 HRE 23/12/2021
        v_tconsulta := v_tconsulta ||
        ' AND (p.cgarpadre = 3131 OR
             p.cgardep IN (SELECT cgarant FROM garanpro p2
                            WHERE  p2.sproduc = se.sproduc
                              AND p2.cgardep = 3131
                           )
          AND p.sproduc =  se.sproduc) ';
       --FIN BUG 72406 HRE 23/12/2021
    ELSIF pgararc  = 2 THEN
      v_tconsulta := v_tconsulta || ' AND p.cgarpadre IN (3119,3124,3149)';
      v_tconsulta := v_tconsulta || ' AND p.cgarant NOT IN (3213,3218,3272,3275,9305)'; --- INICIO/FIN AHYPPLMDCO-195
    ELSE
      v_tconsulta := v_tconsulta || ' AND p.cgarpadre IS NULL';
    END IF;
    --v_tconsulta := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro || ')'; --BUG 47494 MPC 08/03/2019 Se comenta codigo.
    v_tconsulta := v_tconsulta || ' AND se.sseguro =' || psseguro;
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', p.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' GROUP BY REPLACE(pac_isqlfor_lcol.f_des_garpro(se.sseguro, s.nriesgo,' || NVL(pcidioma, 2) || ',p.cgarant, se.sproduc,''POL''), CHR(39), CHR(39) || CHR(39)),p.norden';
  --
  IF pgararc IN (1, 2) THEN
    v_tconsulta := v_tconsulta || ', p.cgarant';
    v_tconsulta := v_tconsulta || ' ORDER BY p.norden, p.cgarant';
  ELSE
    v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  END IF;
  --
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor
    INTO v_norden,
      v_tlinia,
      v_porcentot,
      v_porceninm,
      v_porcencon,
      v_cgarant;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    --
    IF pdummy    = 1 THEN
      v_tresult := v_tresult || ' ' || '\par ';
    ELSE
      v_tresult       := v_tresult || v_tlinia || '\par ';
      IF v_porcentot   > 0 THEN
        IF v_porceninm > 0 THEN
          BEGIN
            SELECT REPLACE(tpregun, '%', 'Valor')
            INTO v_tlinia1
            FROM preguntas
            WHERE cidioma = 8
            AND cpregun   = 5851;
          EXCEPTION
          WHEN NO_DATA_FOUND THEN
            v_tlinia1 := '';
          END;
          v_tresult := v_tresult || '\tab \tab \tab ' || v_tlinia1 || '\par ';
        END IF;
        --
        IF v_porcencon > 0 THEN
          BEGIN
            SELECT REPLACE(tpregun, '%', 'Valor')
            INTO v_tlinia2
            FROM preguntas
            WHERE cidioma = 8
            AND cpregun   = 5852;
          EXCEPTION
          WHEN NO_DATA_FOUND THEN
            v_tlinia2 := '';
          END;
          v_tresult := v_tresult || '\tab \tab \tab ' || v_tlinia2 || '\par ';
        END IF;
      END IF;
    END IF;
  END LOOP;
  --
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_garantias_certif_rc;
--
/*******************************************************************
FUNCTION f_lim_eve_vig_garan_rc
Devuelve el limite por evento o vigencia de las garantias de RC
param IN psseguro  : codigo de seguro
param IN pcidioma  : codigo de idioma
param IN ptiplim   : tipo limite 1:Vigencia 2:Evento
return             : valores con los limites de las garantias de RC
Bug 31409 - 24/07/2017 - LGG
BUG 36151 - LGG
*****************************************************************/
FUNCTION f_lim_eve_vig_garan_rc(
    psseguro IN NUMBER,
    pcidioma IN NUMBER DEFAULT 1,
    ptiplim  IN NUMBER DEFAULT 1,
    ptabla   IN VARCHAR2 DEFAULT 'POL', --MPC BUG 47494 08/03/2019 Se adiciona filtro.
    psproces IN NUMBER DEFAULT NULL)    --MPC BUG 47494 08/03/2019 Se adiciona filtro.
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    --
    vr_cursor r_cursor;
    v_tresult     VARCHAR2(32000) := '';
    v_tconsulta   VARCHAR2(2000);
    v_tconsulta_1 VARCHAR2(2000) := ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro || ')'; --BUG 47494 MPC 08/03/2019 Se crea variable.
    v_tlinia      VARCHAR2(200);
    v_norden garanpro.norden%TYPE;
    v_cgarant garanpro.cgarant%TYPE;
    v_tpargar   VARCHAR2(200);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
  BEGIN
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, seguros s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    --
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    --
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    --
    v_tconsulta := 'SELECT p.norden, p.cgarant';
    IF ptiplim   = 2 THEN
      --INI BUG 51634 MPC 05/06/2019 Se modifica la consulta.
      v_tconsulta := v_tconsulta || ',NVL((SELECT pgs.trespue FROM pregungaranseg pgs WHERE pgs.sseguro = se.sseguro'|| ' AND pgs.cgarant = s.cgarant AND PGS.NMOVIMI = (SELECT MAX(NMOVIMI) FROM pregungaranseg WHERE SSEGURO = pgs.sseguro) AND pgs.cpregun = 9587),0) lim_evento';
      --FIN BUG 51634 MPC 05/06/2019 Se modifica la consulta.
    ELSIF ptiplim  = 1 THEN
      v_tconsulta := v_tconsulta || ',TO_CHAR(NVL(s.icapital,0), ''999,999,999,999,999.99'') lim_vigencia';
    END IF;
    v_tconsulta := v_tconsulta || ' FROM garanpro p, ';
    --INI BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
    IF NVL(ptabla,'POL') = 'CAR' THEN
      v_tconsulta       := v_tconsulta || 'garancar s, seguros se';
      v_tconsulta_1     := ' AND s.sproces = '||psproces;
    ELSE
      --FIN BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
      v_tconsulta := v_tconsulta || 'garanseg s, seguros se';
    END IF; --BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
    v_tconsulta := v_tconsulta || ' WHERE ';
    v_tconsulta := v_tconsulta || ' p.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta := v_tconsulta || ' AND se.csituac in (0,7,5,2,4)';--INTRAO-89 (INTRAO-111) 31/08/2022 GZG
    v_tconsulta := v_tconsulta || ' AND p.CACTIVI = ' || v_actividad;
    --INI BUG 72406 HRE 23/12/2021
    v_tconsulta := v_tconsulta ||
        ' AND (p.cgarpadre = 3131 OR
           p.cgardep IN (SELECT cgarant FROM garanpro p2
                          WHERE  p2.sproduc = se.sproduc
                            AND p2.cgardep = 3131
                         )
      AND p.sproduc =  se.sproduc) ';
    --FIN BUG 72406 HRE 23/12/2021
    --INI BUG 47494 MPC 08/03/2019 Se modifica condiciÃ³n.
    --v_tconsulta := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro || ')';
    v_tconsulta := v_tconsulta || v_tconsulta_1;
    --FIN BUG 47494 MPC 08/03/2019 Se modifica condiciÃ³n.
    v_tconsulta := v_tconsulta || ' AND se.sseguro =' || psseguro;
    --
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', p.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  --
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden, p.cgarant';
  --
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    --
    FETCH vr_cursor INTO v_norden, v_cgarant, v_tlinia;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    --
    v_tresult := v_tresult || v_tlinia || '\par ';
    --
  END LOOP;
  --
  RETURN (f_jrep_trad(v_tresult));
  --
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_lim_eve_vig_garan_rc;
--
/*****************************************************************
FUNCTION f_importes_riesgo_pyme
Devuelve los capitales de un riesgo
param IN psseguro  : codigo de seguro
param IN pnriesgo  : numero de riesgo
param IN pmodo     : modo EST/POL
param IN pgaracml  : 0-Todo riesgo/1-Corriente debil, manejo y lucro
return             : texto con los capitales del riesgo
Bug 31409 - 24/07/2017 - LGG
BUG 36151 - LGG
BUG 37907 - 29/09/2017
******************************************************************/
--
FUNCTION f_importes_riesgo_pyme(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL,
    pgaracml IN NUMBER DEFAULT NULL,
    psproces IN NUMBER DEFAULT NULL, --BUG 47494 MPC 08/03/2019 Se adiciona filtro. --INI/FIN JMG 29/09/2025 LTRPT-3880-AITSSD-5733
    pindsupar IN NUMBER DEFAULT NULL) --INI/FIN JMG 29/09/2025 LTRPT-3880-AITSSD-5733
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    --
    vr_cursor r_cursor;
    v_tresult     VARCHAR2(32000) := '';
    v_tconsulta   VARCHAR2(4000);
    v_tconsulta_2 VARCHAR2(4000) := ''; --BUG 47494 MPC 08/03/2019 Se crea variable.
    v_tlinia      VARCHAR2(500); --INI/FIN JMG 29/09/2025 LTRPT-3880-AITSSD-5733
    v_tpargar     VARCHAR2(300);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot VARCHAR2(200);
    v_ctipcap garanpro.ctipcap%TYPE;
    v_cimpres garanpro.cimpres%TYPE;
    v_npargar   NUMBER := 0;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
    v_es_admin  NUMBER;
    nerror      NUMBER;
    vncertif    NUMBER;
    --INICIO BUG 0037907 - 29/09/2017
    v_tlinia2 VARCHAR2(500); --INI/FIN JMG 16/05/2024 AITSSD-3344
    --FIN BUG 0037907 - 29/09/2017
    v_tgarant garangen.tgarant%TYPE; --INI/FIN JMG 29/09/2025 LTRPT-3880-AITSSD-5733
    v_cgardep garanpro.cgardep%TYPE; --INI/FIN JMG 29/09/2025 LTRPT-3880-AITSSD-5733
  BEGIN
    --
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    --
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    --
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    --
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    --
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := 'SELECT pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), '
      --INICIO BUG 0037907 - 29/09/2017
      --|| ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d';
      || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d,' || '      pac_isqlfor_lcol.f_deducible_xgarantia(se.sseguro,1,' || pnriesgo || ' ,''POL'',g.cgarant) deducible';
      --FIN BUG 0037907 - 29/09/2017
    ELSE
      --INI BUG 47494 MPC 08/03/2019 Se adiciona filtro.
      IF NVL(pmodo, 'POL') = 'CAR' THEN
         --INI JMG 29/09/2025 LTRPT-3880-AITSSD-5733
        IF NVL(pindsupar,0) = 0 THEN
        v_tconsulta       := 'SELECT pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d,' || '      pac_isqlfor_lcol.f_deducible_xgarantia(se.sseguro,1,' || pnriesgo || ' ,''CAR'',g.cgarant, '||psproces||') deducible';
         ELSE
          v_tconsulta       := 'SELECT pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d,' || '      pac_isqlfor_lcol.f_deducible_xgarantia(se.sseguro,1,' || pnriesgo || ' ,''CAR'',g.cgarant, '||psproces||') deducible, substr(upper(TGARANT),1,1)||substr(lower(TGARANT),2) tgarant, CGARDEP  ';
        END IF;
        --FIN JMG 29/09/2025 LTRPT-3880-AITSSD-5733
      ELSE
        --FIN BUG 47494 MPC 08/03/2019 Se adiciona filtro.
        --INI BUG 0052547 19/06/2019 GZG
        IF pgaracml    = 1 THEN
          v_tconsulta := 'SELECT pac_isqlfor_lcol.f_imporignomon(se.sseguro,(pr.crespue)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d,' || '      pac_isqlfor_lcol.f_deducible_xgarantia(se.sseguro,1,' || pnriesgo || ' ,''POL'',g.cgarant) deducible';
        ELSE
          --FIN BUG 0052547 19/06/2019 GZG
          v_tconsulta := 'SELECT pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), '
          --INICIO BUG 0037907 - 29/09/2017
          --|| ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d';
          || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d,' || '      pac_isqlfor_lcol.f_deducible_xgarantia(se.sseguro,1,' || pnriesgo || ' ,''POL'',g.cgarant) deducible';
          --FIN BUG 0037907 - 29/09/2017
        END IF;--BUG 0052547 19/06/2019 GZG
      END IF;  --47494 MPC 08/03/2019 Se adiciona filtro.
    END IF;
    --
    v_tconsulta := v_tconsulta || ' FROM  garangen g, garanpro p, productos pp, ';
    --
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' estgaranseg s, estseguros se';
      v_csituac         := '(0,7,5,2,4)';
    ELSE
      --INI BUG 47494 MPC 08/03/2019 Se adiciona filtro.
      IF NVL(pmodo, 'POL') = 'CAR' THEN
        v_tconsulta       := v_tconsulta || ' garancar s, seguros se';
        v_tconsulta_2     := v_tconsulta || ' AND s.sproces = '||psproces;
      ELSE
        --FIN BUG 47494 MPC 08/03/2019 Se adiciona filtro.
        v_tconsulta := v_tconsulta || ' garanseg s, seguros se';
        ---
        --INI BUG 0052547 19/06/2019 GZG
        IF pgaracml    = 1 THEN
          v_tconsulta := v_tconsulta || ', PREGUNGARANSEG pr';--GZG
        END IF;
        --FIN BUG 0052547 19/06/2019 GZG
        --
      END IF; --BUG 47494 MPC 08/03/2019 Se adiciona filtro.
	--INI INTRAO-89 (INTRAO-111) 31/08/2022 GZG se comenta codigo
    --    IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
    --      v_csituac                                 := '(0,7,5,2)';
    --   ELSE
        v_csituac := '(0,7,5,2,4)';
    --   END IF;
    --FIN INTRAO-89 (INTRAO-111) 31/08/2022 GZG
    END IF;
    --
    v_tconsulta := v_tconsulta || ' WHERE g.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = pp.sproduc';
    v_tconsulta := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' AND se.csituac in ' || v_csituac;
    --INI BUG 0063345 GZG 17/09/2020
    IF NVL(pmodo, 'POL') <> 'POL' THEN
    v_tconsulta := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    END IF;
    --FIN BUG 0063345 GZG 17/09/2020
    v_tconsulta := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
    v_tconsulta := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    --
    IF pgaracml = 1 THEN
      --INI BUG 0052547 19/06/2019 GZG
      v_tconsulta := v_tconsulta || ' AND p.cgarpadre IN (3119,3124,3149,3131)';
      v_tconsulta := v_tconsulta || ' AND p.cgarant  NOT IN (3213,3218,3272,3275,9305)'; --- INICIO/FIN AHYPPLMDCO-195
      v_tconsulta := v_tconsulta || ' and pr.sseguro = se.sseguro ';
      v_tconsulta := v_tconsulta || ' and pr.cpregun = 8791 and pr.cgarant = p.cgarant and pr.nriesgo = s.nriesgo and pr.nmovimi = s.nmovimi ';
      --FIN BUG 0052547 19/06/2019 GZG
    ELSE
    --INI JMG 29/09/2025 LTRPT-3880-AITSSD-5733
      IF NVL(pindsupar,0) = 0 THEN
      v_tconsulta := v_tconsulta || ' AND p.cgarpadre IS NULL';
      END IF;
    --FIN JMG 29/09/2025 LTRPT-3880-AITSSD-5733
    END IF;
    --
    IF NVL(pmodo, 'POL') = 'EST' THEN
      --
      v_es_admin := pac_seguros.f_es_col_admin(psseguro, 'EST');
      --
      SELECT ncertif INTO vncertif FROM estseguros WHERE sseguro = psseguro;
    --
    IF v_es_admin    = 1 AND vncertif <> 0 THEN
      v_tconsulta   := v_tconsulta || ' AND s.cobliga = 1';
      v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg ga WHERE sseguro =' || psseguro;
      v_tconsulta   := v_tconsulta || '  and ga.nmovimi <= (SELECT MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.SSEGURO = GA.SSEGURO AND MV.CMOVSEG!=3 AND MV.NMOVIMI =(select max(nmovimi_cert) from detmovsegurocol WHERE sseguro_0 = (select sseguro from seguros where npoliza = (select npoliza from seguros where sseguro = ' || psseguro || ')  and ncertif = 0) and sseguro_cert =ga.sseguro';
      IF (pnmovimi  IS NOT NULL) THEN
        v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || '))) ';
      ELSE
        v_tconsulta := v_tconsulta || ')))';
      END IF;
    ELSE
      v_tconsulta   := v_tconsulta || ' AND s.cobliga = 1';
      v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg WHERE sseguro =' || psseguro;
      IF (pnmovimi  IS NOT NULL) THEN
        v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
        v_tconsulta := v_tconsulta || ')';
      END IF;
    END IF;
    --
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM estseguros seg
      WHERE seg.sseguro = psseguro
      );
  ELSE
    --
    --INI BUG 47494 MPC 08/03/2019 Se adiciona filtro.
    IF NVL(pmodo, 'POL') = 'CAR' THEN
      v_tconsulta       := v_tconsulta || ' AND s.sproces = '||psproces;
    ELSE
      --FIN BUG 47494 MPC 08/03/2019 Se adiciona filtro.
      v_es_admin := pac_seguros.f_es_col_admin(psseguro, 'POL');
      --
      SELECT ncertif INTO vncertif FROM seguros WHERE sseguro = psseguro;
      --INI BUG 0063345 GZG 17/09/2020
      IF v_es_admin    = 1 AND vncertif = 0 THEN
        v_tconsulta   := v_tconsulta || 'AND se.npoliza IN (SELECT npoliza FROM seguros WHERE sseguro IN (' || psseguro||'))';
        v_tconsulta := v_tconsulta || 'AND (s.sseguro, s.nmovimi) IN (with c2 as (SELECT ga.sseguro, MAX (ga.nmovimi) nmovimi FROM garanseg ga, (SELECT MV.SSEGURO, MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.CMOVSEG != 3 AND (MV.SSEGURO, MV.NMOVIMI) IN ';
        v_tconsulta := v_tconsulta || '(SELECT sseguro_cert, MAX (nmovimi_cert) FROM detmovsegurocol WHERE sseguro_0 = '||psseguro||' AND nmovimi_0 <= '||pnmovimi||' GROUP BY sseguro_cert)) mv WHERE ga.sseguro = mv.sseguro AND ga.nmovimi <= mv.nmovimi GROUP BY ga.sseguro ) select sseguro, nmovimi from c2 )';
       /* v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM garanseg ga WHERE sseguro =' || psseguro;
        v_tconsulta   := v_tconsulta || '  and ga.nmovimi <= (SELECT MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.SSEGURO = GA.SSEGURO AND MV.CMOVSEG!=3 AND MV.NMOVIMI =(select max(nmovimi_cert) from detmovsegurocol WHERE sseguro_0 = (select sseguro from seguros where npoliza = (select npoliza from seguros where sseguro = ' || psseguro || ')  and ncertif = 0) and sseguro_cert =ga.sseguro';
        IF (pnmovimi  IS NOT NULL) THEN
          v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || '))) ';
        ELSE
          v_tconsulta := v_tconsulta || ')))';
        END IF;*/
      ELSE
       v_tconsulta := v_tconsulta || ' AND s.sseguro = ' || psseguro;
       --FIN BUG 0063345 GZG 17/09/2020
        v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM garanseg WHERE sseguro =' || psseguro;
        IF (pnmovimi  IS NOT NULL) THEN
          v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
        ELSE
          v_tconsulta := v_tconsulta || ')';
        END IF;
      END IF;
    END IF; --BUG 47494 MPC 08/03/2019 Se adiciona filtro.
    --
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  END IF;
  --
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  --p_control_error('LG', 'F_IMPORTES_RIESGO_PYME', 'v_tconsulta:' || v_tconsulta);
  --
  --INI JMG 29/09/2025 LTRPT-3880-AITSSD-5733
  IF NVL(pindsupar,0) = 0 THEN
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor
      --INICIO BUG 0037907 - 29/09/2017
      --INTO v_tlinia, v_icaptot, v_ctipcap, v_cimpres, v_npargar, v_ipritot;
    INTO v_tlinia,
      v_icaptot,
      v_ctipcap,
      v_cimpres,
      v_npargar,
      v_ipritot,
      v_tlinia2;
    --FIN BUG 0037907 - 29/09/2017
    EXIT
  WHEN vr_cursor%NOTFOUND;
    --
    IF v_npargar = 1 AND v_icaptot = 0 THEN
      SELECT tatribu
      INTO v_tlinia
      FROM detvalores
      WHERE cvalor = 126
      AND catribu  = NVL(v_cimpres, 59)
      AND cidioma  = NVL(pcidioma, 8);
    END IF;
    --
    --INI DMC 26/12/2023 - LTRPT-3656 - BUG PRODUCCION RENOV PYME (IAXIS): PDF del previo con información faltante
    IF pcampo   = 1 THEN
      v_tlinia := TRIM(TO_CHAR(v_icaptot,'999,999,999,999,999,999'));
    END IF;
    --FIN DMC 26/12/2023 - LTRPT-3656 - BUG PRODUCCION RENOV PYME (IAXIS): PDF del previo con información faltante
    IF pcampo   = 2 THEN
      v_tlinia := v_ipritot;
    END IF;
    --INICIO BUG 0037907 - 29/09/2017
    IF pcampo   = 7 THEN
      v_tlinia := v_tlinia2;
    END IF;
    --FIN BUG 0037907 - 29/09/2017
    --
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  ELSE
    OPEN vr_cursor FOR v_tconsulta;
      LOOP
        FETCH vr_cursor
         INTO v_tlinia,
          v_icaptot,
          v_ctipcap,
          v_cimpres,
          v_npargar,
          v_ipritot,
          v_tlinia2,
          v_tgarant,
          v_cgardep;
        EXIT
      WHEN vr_cursor%NOTFOUND;
        --
        IF v_npargar = 1 AND v_icaptot = 0 THEN
          SELECT tatribu
          INTO v_tlinia
          FROM detvalores
          WHERE cvalor = 126
          AND catribu  = NVL(v_cimpres, 59)
          AND cidioma  = NVL(pcidioma, 8);
        END IF;
        IF pcampo   = 1 THEN
          v_tlinia := TRIM(TO_CHAR(v_icaptot,'999,999,999,999,999,999'));
        END IF;
        IF pcampo   = 2 THEN
          v_tlinia := v_ipritot;
        END IF;
        IF pcampo   = 7 THEN
          v_tlinia := v_tlinia2;
        END IF;
         IF pcampo   = 8 THEN
          v_tlinia := v_tgarant;
        END IF;
        IF pcampo   = 9 THEN
          v_tlinia := v_cgardep;
        END IF;
        v_tresult := v_tresult || v_tlinia || '\par ';
      END LOOP;
  END IF;
  --FIN JMG 29/09/2025 LTRPT-3880-AITSSD-5733
  --
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_riesgo_pyme;
-- BUG 0037907 - 29/09/2017
/*****************************************************************
FUNCTION f_gar_riesgo_pyme_rc
Devuelve las garant?as de un riesgo
param IN psseguro  : codigo de seguro
param IN pnriesgo  : n?mero de riesgo
param IN pcidioma  : codigo de idioma
param IN pmodo     : modo EST/POL
param IN pgararc   : 0-Todo riesgo/1-RC/2-Corriente debil, manejo y lucro
return             : texto con las garantias del riesgo
Bug 31409 - 24/07/2017 - LGG
BUG 36151 - LGG
******************************************************************/
FUNCTION f_gar_riesgo_pyme_rc(
    psseguro IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL,
    pgararc  IN NUMBER DEFAULT NULL,
    psproces IN NUMBER DEFAULT NULL) --BUG 47494 MPC 08/03/2019 Se adiciona parametro
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult     VARCHAR2(32000) := '';
    v_tconsulta   VARCHAR2(2000);
    v_tconsulta_1 VARCHAR2(2000) := ''; --BUG 47494 MPC 08/03/2019 Se crea variable.
    v_tlinia      VARCHAR2(200);
    v_tpargar     VARCHAR2(300);
    v_tablaseg    VARCHAR2(30);
    v_act0        NUMBER(1);
    v_actividad   VARCHAR2(20);
    v_csituac     VARCHAR2(100);
    v_es_admin    NUMBER;
    vncertif      NUMBER;--INTRAO-89 (INTRAO-111) 31/08/2022 GZG
  BEGIN
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    --
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    --
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    --
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    --
    v_tconsulta := 'SELECT REPLACE(pac_isqlfor_lcol.f_des_garpro(se.sseguro,s.nriesgo,' || NVL(pcidioma, 2) || ',p.cgarant,se.sproduc,''' || pmodo || '''), CHR(39), CHR(39) || CHR(39)) a';
    v_tconsulta := v_tconsulta || ' FROM garanpro p, ';
    --
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || 'estgaranseg s, estseguros se';
      v_csituac         := '(0,7,5,2,4)';
    ELSE
      --INI BUG 47494 MPC 08/03/2019 Se adiciona filtro para previos.
      IF NVL(pmodo, 'POL') = 'CAR' THEN
        --
        v_tconsulta   := v_tconsulta || 'garancar s, seguros se';
        v_tconsulta_1 := ' AND s.sproces = '||psproces;
        --
      ELSE
        --
        v_tconsulta := v_tconsulta || 'garanseg s, seguros se';
        --
      END IF;
      --FIN BUG 47494 MPC 08/03/2019 Se adiciona filtro para previos.
	  --INI INTRAO-89 (INTRAO-111) 31/08/2022 GZG
      --   IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
      --      v_csituac                                 := '(0,7,5,2)';
      --   ELSE
        v_csituac := '(0,7,5,2,4)';
      --  END IF;
	  --FIN INTRAO-89 (INTRAO-111) 31/08/2022 GZG
    END IF;
    --
    v_tconsulta := v_tconsulta || ' WHERE p.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || v_tconsulta_1; --BUG 47494 MPC 08/03/2019 Se adiciona filtro para previos.
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta := v_tconsulta || ' AND p.CACTIVI = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' AND se.csituac in ' || v_csituac;
    v_tconsulta := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    DBMS_OUTPUT.put_line('pnriesgo: ' || pnriesgo || ' pnmovimi:' || pnmovimi);
    IF pgararc     = 1 THEN
      v_tconsulta := v_tconsulta || ' AND p.cgarpadre IN (3131,3143)';--BUG 0051176 GZG 23/04/2019
    ELSIF pgararc  = 2 THEN
      v_tconsulta := v_tconsulta || ' AND p.cgarpadre IN (3119,3124,3149,3131)';--BUG 0052547 19/06/2019 GZG
      v_tconsulta := v_tconsulta || ' AND p.cgarant NOT IN (3213,3218,3272,3275)';
    ELSE
      v_tconsulta := v_tconsulta || ' AND p.cgarpadre IS NULL';
    END IF;
    --
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_es_admin        := pac_seguros.f_es_col_admin(psseguro, 'EST');
      --
      IF v_es_admin    = 1 THEN
        v_tconsulta   := v_tconsulta || ' AND s.cobliga = 1 and s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg ga WHERE sseguro =' || psseguro;
        v_tconsulta   := v_tconsulta || ' AND ga.nmovimi <= (SELECT MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.SSEGURO = GA.SSEGURO AND MV.CMOVSEG!=3 AND MV.NMOVIMI =(select max(nmovimi_cert) from detmovsegurocol WHERE sseguro_0 =  (select sseguro from seguros where npoliza = (select npoliza from seguros where sseguro = ' || psseguro || ')  and ncertif = 0 ) ' || ' AND sseguro_cert = ' || psseguro;
        IF (pnmovimi  IS NOT NULL) AND (pgararc = 1) THEN
          v_tconsulta := v_tconsulta || ' AND nmovimi_0 >=' || pnmovimi || '))) ';
        ELSE
          v_tconsulta := v_tconsulta || ')))';
        END IF;
      ELSE
        v_tconsulta   := v_tconsulta || ' AND s.cobliga = 1 and s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg WHERE sseguro =' || psseguro;
        IF (pnmovimi  IS NOT NULL) THEN
          v_tconsulta := v_tconsulta || ' AND nmovimi >=' || pnmovimi || ') ';
        ELSE
          v_tconsulta := v_tconsulta || ')';
        END IF;
      END IF;
      --
      SELECT ' AND ((NVL(pac_parametros.f_pargaranpro_n('
        || sproduc
        || ', '
        || cactivi
        || ', p.cgarant, ''GARANT_IMP''), 0) = 1) )'
      INTO v_tpargar
      FROM
        (SELECT seg.sproduc,
          seg.cactivi
        FROM estseguros seg
        WHERE seg.sseguro = psseguro
        );
    --INI BUG 47494 MPC 08/03/2019 Se adiciona validaciÃ³n.
  ELSIF NVL(pmodo, 'POL') = 'CAR' THEN
    --
    SELECT ' AND ((NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', p.cgarant, ''GARANT_IMP''), 0) = 1) )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
    --FIN BUG 47494 MPC 08/03/2019 Se adiciona validaciÃ³n.
  ELSE
    v_es_admin := pac_seguros.f_es_col_admin(psseguro, 'POL');
    --
    --INI INTRAO-89 (INTRAO-111) 31/08/2022 GZG
    SELECT ncertif INTO vncertif FROM seguros WHERE sseguro = psseguro;
      IF v_es_admin    = 1 AND vncertif = 0 THEN
      v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG ga WHERE sseguro =' || psseguro;
      v_tconsulta   := v_tconsulta || '  and ga.nmovimi <= (SELECT MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.SSEGURO = GA.SSEGURO AND MV.CMOVSEG!=3 AND MV.NMOVIMI =(select max(nmovimi_cert) from detmovsegurocol WHERE sseguro_0 = (select sseguro from seguros where npoliza = (select npoliza from seguros where sseguro = ' || psseguro || ' )  and ncertif = 0 )' || ' AND sseguro_cert = ' || psseguro;
      IF (pnmovimi  IS NOT NULL) AND (pgararc = 1) THEN
        v_tconsulta := v_tconsulta || ' AND nmovimi_0 >=' || pnmovimi || '))) ';
      ELSE
        v_tconsulta := v_tconsulta || ')))';
      END IF;
    ELSE
      v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro;
      IF (pnmovimi  IS NOT NULL) THEN
        v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
        v_tconsulta := v_tconsulta || ')';
      END IF;
    END IF;
    --FIN INTRAO-89 (INTRAO-111) 31/08/2022 GZG
    --
    SELECT ' AND ((NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', p.cgarant, ''GARANT_IMP''), 0) = 1) )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  END IF;
  --
  v_tconsulta := v_tconsulta || v_tpargar;
  IF pgararc IN (1, 2) THEN
    v_tconsulta := v_tconsulta || ' ORDER BY p.norden, p.cgarant';
  ELSE
    v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  END IF;
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor
    INTO v_tlinia;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  --
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_gar_riesgo_pyme_rc;
/*****************************************************************
FUNCTION f_clausulas_pyme
Clausulas de Pyme sin las observaciones del movimiento (ant/actual)
param IN psseguro  :
param IN pnmovimi  :
param IN pcidioma :
param IN ptabla   :
para IN pcduplica:
para IN pregini: nordcla inicial
para IN pregfin: nordcla final
return            : number
Bug 31409 - 24/07/2017 - LGG
BUG 36151 - LGG
Bug 36480 - 29/08/2017 - LGG - INICIO
******************************************************************/
FUNCTION f_clausulas_pyme(
    psseguro  IN NUMBER,
    pnmovimi  IN NUMBER,
    pcidioma  IN NUMBER,
    ptabla    IN VARCHAR2 DEFAULT 'POL',
    pcduplica IN NUMBER DEFAULT 0,
    pregini   IN NUMBER DEFAULT 1,
    pregfin   IN NUMBER,
    pvdescsup IN VARCHAR2 DEFAULT 'S')
  RETURN CLOB
IS
  vret CLOB;
BEGIN
  IF ptabla = 'POL' THEN
    FOR i IN
    --INI AITSSD-2098 GZG 18/03/2025
    (SELECT clau,linea from (SELECT clau,
      nordcla,
      ROWNUM linea
	   --FIN AITSSD-2098 GZG 18/03/2025
    FROM
      (SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        c.nordcla
      FROM clausugen cg,
        claususeg c
      WHERE cg.sclagen = c.sclagen
      AND c.sseguro    = psseguro
        --                                  AND c.nmovimi = pnmovimi
      AND c.nmovimi =
        (SELECT MAX(nmovimi)
        FROM claususeg
        WHERE sseguro = psseguro
        AND nmovimi  <= pnmovimi
        )
      AND cg.cidioma = pcidioma
      UNION
      SELECT REPLACE(REPLACE(REGEXP_REPLACE(tclaesp, '[[:space:]][[:space:]]*', ' '),'<br><br>','<br>'),'<br>','\par ') clau,--AITSSD-8394 GZG 09/03/2026
        nordcla
      FROM clausuesp
      WHERE sseguro = psseguro
        --                                  AND nmovimi = pnmovimi
      AND nmovimi =
        (SELECT MAX(nmovimi)
        FROM clausuesp
        WHERE sseguro = psseguro
        AND nmovimi  <= pnmovimi
        AND sclagen  IS NULL
        )
      AND sclagen IS NULL
      UNION
      SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        c.nordcla
      FROM clausugen cg,
        clausuesp c,
        seguros s
      WHERE s.sseguro = c.sseguro
      AND cg.sclagen  = c.sclagen
      AND c.sseguro   = psseguro
        --                                  AND c.nmovimi = pnmovimi
      AND c.nmovimi =
        (SELECT MAX(nmovimi)
        FROM clausuesp
        WHERE sseguro = psseguro
        AND nmovimi  <= pnmovimi
        AND sclagen  IS NOT NULL
        )
      AND c.sclagen IS NOT NULL
      AND cg.cidioma = pcidioma
      AND (s.cramo  <> 103
      OR ncertif     = 0)
      ORDER BY nordcla
      )
      --INI AITSSD-2098 GZG 18/03/2025
   -- WHERE nordcla BETWEEN pregini AND pregfin
    --GROUP BY clau,
    --  nordcla
    ORDER BY nordcla
    )WHERE linea BETWEEN pregini AND pregfin)
      --FIN AITSSD-2098 GZG 18/03/2025
    LOOP
      vret := vret || i.clau || ' \par \par ';
    END LOOP;
  ELSE
    FOR i IN
    (SELECT clau,
      nordcla
    FROM
      (SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        c.nordcla
      FROM clausugen cg,
        estclaususeg c
      WHERE cg.sclagen = c.sclagen
      AND c.sseguro    = psseguro
      AND c.nmovimi    = pnmovimi
      AND cg.cidioma   = pcidioma
      UNION
      SELECT REPLACE(REPLACE(REGEXP_REPLACE(tclaesp, '[[:space:]][[:space:]]*', ' '),'<br><br>','<br>'),'<br>','\par ') clau,--AITSSD-8394 GZG 09/03/2026
        nordcla
      FROM estclausuesp
      WHERE sseguro = psseguro
      AND nmovimi   = pnmovimi
      AND sclagen  IS NULL
      UNION
      SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        c.nordcla
      FROM clausugen cg,
        estclausuesp c,
        estseguros s
      WHERE s.sseguro = c.sseguro
      AND cg.sclagen  = c.sclagen
      AND c.sseguro   = psseguro
      AND c.nmovimi   = pnmovimi
      AND c.sclagen  IS NOT NULL
      AND cg.cidioma  = pcidioma
      AND (s.cramo   <> 103
      OR ncertif      = 0)
      ORDER BY nordcla
      )
    GROUP BY clau,
      nordcla
    ORDER BY nordcla
    )
    LOOP
      vret := vret || i.clau || ' \par \par ';
    END LOOP;
  END IF;
  --  Bug 36480 - 29/08/2017 - LGG - INICIO
  IF pvdescsup  = 'S' THEN
    IF pnmovimi > 1 AND pcduplica = 0 THEN
      vret     := vret || f_descsup(psseguro, pnmovimi);
    END IF;
  END IF;
  --  Bug 36480 - 29/08/2017 - LGG - FIN
  RETURN f_jrep_trad_pyme(vret);
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_clausulas_pyme;
--Bug 36480 - 29/08/2017 - LGG - FIN
/*******************************************************************
FUNCTION f_amparo_bien_pyme
Devuelve todos los amparos subamparos y bienes
param IN psseguro  : codigo de seguro
param IN pcidioma  : codigo de idioma
param IN pnriesgo  : numero de riesgo
param IN pnmovimi  : numero de movimiento
param IN pcampo    : 1:NomAmparo/2:
return             : Amparos en jerarquia
Bug 31409 - 24/07/2017 - LGG
BUG 36151 - LGG
BUG 37907 - 19/10/2017 - LGG
*****************************************************************/
FUNCTION f_amparo_bien_pyme(
    psseguro IN NUMBER,
    pcidioma IN NUMBER DEFAULT 1,
    priesgo  IN NUMBER DEFAULT 1,
    pnmovimi IN NUMBER DEFAULT NULL,
    pcampo   IN NUMBER DEFAULT 1,
    ptabla   IN VARCHAR2 DEFAULT 'POL', --BUG 47497 MPC 08/03/2019 Se adiciona filtro.
    psproces IN NUMBER DEFAULT NULL)    --BUG 47497 MPC 08/03/2019 Se adiciona filtro.
  RETURN CLOB
IS
  --
  v_tresult CLOB := '';
  v_tresult2 VARCHAR2(2000);--AITSSD-15541 GZG 22/01/2024 se aumenta valor
  v_ntabs    VARCHAR2(1000);--AITSSD-15541 GZG 22/01/2024 se aumenta valor
  v_flag_778 BOOLEAN := FALSE;
  --
BEGIN
  --INI BUG 47497 MPC 08/03/2019 Se adiciona filtro.
  IF NVL(ptabla,'POL') = 'CAR' THEN
    --
    FOR cons IN
    (SELECT LEVEL nivel,
      cgarant,
      orden,
      cgarpadre,
      nomgarant,
      ind_variable,
      valor
    FROM
      (SELECT DISTINCT g.cgarant,
        1 orden,
        g.cgarpadre,
        (SELECT DISTINCT gg.tgarant
        FROM garangen gg
        WHERE gg.cgarant = a1.cgarant
        AND gg.cidioma   = pcidioma
        ) nomgarant,
        (SELECT DISTINCT crespue
        FROM pregungaranseg
        WHERE sseguro = a1.sseguro
        AND cgarant   = g.cgarant
        AND cpregun   = 6124
        AND nriesgo   = priesgo
        ) ind_variable,
        (pac_isqlfor_lcol.f_imporignomon(a1.sseguro, (DECODE(g.cgarant, 48, a1.cforpag, 1) * a1.icaptot), NULL, 'POL')) valor,
        1
      FROM garanpro g
      INNER JOIN
        (SELECT a.cgarant,
          b.sseguro,
          a.icaptot,
          b.cforpag,b.cmodali--BUG 0061612 GZG 24/06/2020
        FROM garancar a,
          seguros b
        WHERE a.sseguro = b.sseguro
        AND a.sseguro   = psseguro
        AND a.sproces   = psproces
        AND a.nriesgo   = priesgo
        ) a1
     --INI BUG 0061612 GZG 24/06/2020 -- Se comenta ya que se requiere que las garantias salgan en el pdf
      ON (g.cgarant           = a1.cgarant
	  AND g.cmodali=a1.cmodali)
     -- WHERE (g.cgarpadre NOT IN (3131, 3124)
     -- OR g.cgarpadre         IS NULL)
     -- AND g.cgarant NOT      IN (3131, 3124, 3154, 3153)
     --FIN BUG 0061612 GZG 24/06/2020
      --
      UNION
      SELECT DISTINCT a.cgarant,
        3 orden,
        g.cgarpadre,
        a.tvalor AS nomgarant,
        (SELECT crespue
        FROM pregungaranseg
        WHERE sseguro = se.sseguro
        AND cgarant   = g.cgarant
        AND cpregun   = 6124
        AND nriesgo   = priesgo
        --INI AITSSD-15541 GZG 22/01/2024
        AND nmovimi = (SELECT max(nmovimi)
        FROM pregungaranseg
        WHERE sseguro=se.sseguro
        AND cgarant  =g.cgarant
        AND cpregun  =6124
        AND nriesgo  = priesgo
        AND nmovimi <= NVL(pnmovimi,1))
        --FIN AITSSD-15541 GZG 22/01/2024
        ) ind_variable,
        pac_isqlfor_lcol.f_imporignomon(a.sseguro, b.nvalor, NULL, 'POL') AS valor,
        a.nlinea
      FROM
        (SELECT *
        FROM pregungaransegtab
        WHERE sseguro = psseguro
        AND ccolumna  = 1
        AND nriesgo   = priesgo
        ) a
      INNER JOIN
        (SELECT *
        FROM pregungaransegtab
        WHERE sseguro = psseguro
        AND ccolumna  = 2
        AND nriesgo   = priesgo
        ) b
      ON a.sseguro  = b.sseguro
      AND a.nriesgo = b.nriesgo
      AND a.cgarant = b.cgarant
      AND a.nmovimi = b.nmovimi
      AND a.nlinea  = b.nlinea
      INNER JOIN garangenpro c
      ON a.cgarant = c.cgarant
      INNER JOIN garanpro g
      ON c.cgarant = g.cgarant
      INNER JOIN seguros se
      ON g.sproduc          = se.sproduc
      AND a.sseguro         = se.sseguro
      AND g.cactivi         = se.cactivi
      WHERE c.cidioma       = pcidioma
      AND a.nmovimi         = pnmovimi
      --INI BUG 0061612 GZG 24/06/2020 -- Se comenta ya que se requiere que las garantias salgan en el pdf
      --AND (g.cgarpadre NOT IN (3131, 3124)
      --OR g.cgarpadre       IS NULL)
      --AND g.cgarant NOT    IN (3131, 3124, 3154, 3153)
      --FIN BUG 0061612 GZG 24/06/2020
        --
      ORDER BY 3
      )
      START WITH cgarpadre    IS NULL
      CONNECT BY PRIOR cgarant = cgarpadre
    )
    LOOP
      --
      IF cons.nivel    = 1 THEN
        v_ntabs       := ' ';
      ELSIF cons.nivel = 2 THEN
        IF cons.orden  = 3 THEN
          v_ntabs     := '\tab \tab \tab \tab \tab \tab \tab \tab ';
        ELSE
          v_ntabs := '\tab \tab \tab \tab ';
        END IF;
      END IF;
      --
      IF pcampo         = 1 THEN
        IF cons.cgarant = 778 THEN
          v_flag_778   := TRUE;
          v_tresult2   := v_ntabs || cons.nomgarant || '\par ';
        ELSE
          v_tresult := v_tresult || v_ntabs || cons.nomgarant || '\par ';
        END IF;
      ELSIF pcampo      = 2 THEN
        IF cons.cgarant = 778 THEN
          v_flag_778   := TRUE;
          v_tresult2   := cons.ind_variable || '\par ';
        ELSE
          v_tresult := v_tresult || cons.ind_variable || '\par ';
        END IF;
      ELSIF pcampo      = 3 THEN
        IF cons.cgarant = 778 THEN
          v_flag_778   := TRUE;
          v_tresult2   := v_ntabs || cons.valor || '\par ';
        ELSE
          IF cons.nivel = 1 THEN
            v_tresult  := v_tresult || cons.valor || '\par ';
          ELSE
            v_tresult := v_tresult || '\par ';
          END IF;
        END IF;
      ELSIF pcampo      = 4 THEN
        IF cons.cgarant = 778 THEN
          v_flag_778   := TRUE;
          v_tresult2   := '\par ';
        ELSE
          IF cons.nivel = 2 THEN
            v_tresult  := v_tresult || cons.valor || '\par ';
          ELSE
            v_tresult := v_tresult || '\par ';
          END IF;
        END IF;
      END IF;
      --
    END LOOP;
    --
  ELSE
    --FIN BUG 47497 BUG 08/03/2019 Se adiciona filtro.
    FOR cons IN
    (SELECT LEVEL nivel,
      cgarant,
      orden,
      cgarpadre,
      nomgarant,
      ind_variable,
      valor
    FROM
      (SELECT DISTINCT g.cgarant,
        1 orden,
        g.cgarpadre,
        (SELECT DISTINCT gg.tgarant
        FROM garangen gg
        WHERE gg.cgarant = a1.cgarant
        AND gg.cidioma   = pcidioma
        ) nomgarant,
        (SELECT DISTINCT crespue
        FROM pregungaranseg
        WHERE sseguro = a1.sseguro
        AND cgarant   = g.cgarant
        AND cpregun   = 6124
          --INICIO BUG 37907 - 19/10/2017 - LGG
        AND nriesgo = priesgo--FIN BUG 37907 - 19/10/2017 - LGG
        ) ind_variable,
        (pac_isqlfor_lcol.f_imporignomon(a1.sseguro, (DECODE(g.cgarant, 48, a1.cforpag, 1) * a1.icaptot), NULL, 'POL')) valor,
        1
      FROM garanpro g
      INNER JOIN
        (SELECT a.cgarant,
          b.sseguro,
          a.icaptot,b.cramo,--INTRAO-89 (INTRAO-111) 31/08/2022 GZG
          b.cforpag,b.cmodali-- BUG 0061612 GZG 24/06/2020
        FROM garanseg a,
          seguros b
        WHERE a.sseguro = b.sseguro
        AND a.sseguro   = psseguro
        AND a.nmovimi   = NVL(NULL, a.nmovimi)
        AND a.nriesgo   = priesgo
        AND a.nmovimi   = pnmovimi
        ) a1
	 --INI BUG 0061612 GZG 24/06/2020 -- Se comenta ya que se requiere que las garantias salgan en el pdf
      ON (g.cgarant = a1.cgarant
	  AND g.cmodali = a1.cmodali AND g.cramo = a1.cramo)--INTRAO-89 (INTRAO-111) 31/08/2022 GZG
        --09/06/2017 LRGG
      --WHERE (g.cgarpadre NOT IN (3131, 3124)
      --OR g.cgarpadre         IS NULL)
      --AND g.cgarant NOT      IN (3131, 3124, 3154, 3153)
      --FIN BUG 0061612 GZG 24/06/2020
      --
      UNION
      SELECT DISTINCT a.cgarant,
        3 orden,
        g.cgarpadre,
        a.tvalor AS nomgarant,
        (SELECT crespue
        FROM pregungaranseg
        WHERE sseguro = se.sseguro
        AND cgarant   = g.cgarant
        AND cpregun   = 6124
          --INICIO BUG 37907 - 19/10/2017 - LGG
        AND nriesgo = priesgo--FIN BUG 37907 - 19/10/2017 - LGG
        --BUG 0054700 17/09/2019 GZG
        AND nmovimi = (SELECT max(nmovimi)
      FROM pregungaranseg
      WHERE sseguro=se.sseguro
      AND cgarant  =g.cgarant
      AND cpregun  =6124
      AND nriesgo  = priesgo
      and nmovimi <= NVL(pnmovimi,1))
      --BUG 0054700 17/09/2019 GZG
        ) ind_variable,
        pac_isqlfor_lcol.f_imporignomon(a.sseguro, b.nvalor, NULL, 'POL') AS valor,
        a.nlinea
      FROM
        (SELECT *
        FROM pregungaransegtab
        WHERE sseguro = psseguro
        AND ccolumna  = 1
        AND nriesgo   = priesgo
        ) a
      INNER JOIN
        (SELECT *
        FROM pregungaransegtab
        WHERE sseguro = psseguro
        AND ccolumna  = 2
        AND nriesgo   = priesgo
        ) b
      ON a.sseguro  = b.sseguro
      AND a.nriesgo = b.nriesgo
      AND a.cgarant = b.cgarant
      AND a.nmovimi = b.nmovimi
      AND a.nlinea  = b.nlinea
      INNER JOIN garangenpro c
      ON a.cgarant = c.cgarant
      INNER JOIN garanpro g
      ON c.cgarant = g.cgarant
      INNER JOIN seguros se
      ON g.sproduc    = se.sproduc
      AND a.sseguro   = se.sseguro
      AND g.cactivi   = se.cactivi
      WHERE c.cidioma = pcidioma
      AND a.nmovimi   = pnmovimi
        -- 09/06/2017 LRGG
        --INI BUG 0061612 GZG 24/06/2020 -- Se comenta ya que se requiere que las garantias salgan en el pdf
      --AND (g.cgarpadre NOT IN (3131, 3124)
      --OR g.cgarpadre       IS NULL)
      --AND g.cgarant NOT    IN (3131, 3124, 3154, 3153)
      --FIN BUG 0061612 GZG 24/06/2020
        --
      ORDER BY 3
      )
      START WITH cgarpadre    IS NULL
      CONNECT BY PRIOR cgarant = cgarpadre
    )
    LOOP
      --
      IF cons.nivel    = 1 THEN
        v_ntabs       := ' ';
      ELSIF cons.nivel = 2 THEN
        IF cons.orden  = 3 THEN
          v_ntabs     := '\tab \tab \tab \tab \tab \tab \tab \tab ';
        ELSE
          v_ntabs := '\tab \tab \tab \tab ';
        END IF;
      END IF;
      --
      IF pcampo         = 1 THEN
        IF cons.cgarant = 778 THEN
          v_flag_778   := TRUE;
          v_tresult2   := v_ntabs || cons.nomgarant || '\par ';
        ELSE
          v_tresult := v_tresult || v_ntabs || cons.nomgarant || '\par ';
        END IF;
      ELSIF pcampo      = 2 THEN
        IF cons.cgarant = 778 THEN
          v_flag_778   := TRUE;
          v_tresult2   := cons.ind_variable || '\par ';
        ELSE
          v_tresult := v_tresult || cons.ind_variable || '\par ';
        END IF;
      ELSIF pcampo      = 3 THEN
        IF cons.cgarant = 778 THEN
          v_flag_778   := TRUE;
          v_tresult2   := v_ntabs || cons.valor || '\par ';
        ELSE
          IF cons.nivel = 1 THEN
            v_tresult  := v_tresult || cons.valor || '\par ';
          ELSE
            v_tresult := v_tresult || '\par ';
          END IF;
        END IF;
      ELSIF pcampo      = 4 THEN
        IF cons.cgarant = 778 THEN
          v_flag_778   := TRUE;
          v_tresult2   := '\par ';
        ELSE
          IF cons.nivel = 2 THEN
            v_tresult  := v_tresult || cons.valor || '\par ';
          ELSE
            v_tresult := v_tresult || '\par ';
          END IF;
        END IF;
      END IF;
      --
    END LOOP;
    --
  END IF;--BUG 47497 BUG 08/03/2019 Se adiciona.
  --
  IF v_flag_778 THEN
    v_tresult := v_tresult || v_tresult2;
  END IF;
  -- INI BUG 49323 - JAGB - 15/02/2019 - RELACION DE BIENES
  RETURN (f_jrep_trad_clob(v_tresult));
  -- FIN BUG 49323 - JAGB - 15/02/2019 - RELACION DE BIENES
EXCEPTION
WHEN OTHERS THEN
  DBMS_OUTPUT.put_line(SQLERRM);
  RETURN ('');
END f_amparo_bien_pyme;
/*******************************************************************
FUNCTION f_nom_inter_pyme
Devuelve el nombre de los intermediarios
param IN psseguro  : codigo de seguro
param IN pnmovimi  : Movimiento de la poliza
param IN pcolumn   : 2 Nombre
return             : nombre de los intermediarios
Bug 31409 - 24/07/2017 - LGG
BUG 36151 - LGG
*****************************************************************/
--
FUNCTION f_nom_inter_pyme(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER,
    pcolumn  IN NUMBER)
  RETURN VARCHAR2
IS
  vret VARCHAR2(2000);
BEGIN
  vret := NULL;
  FOR i IN
  (SELECT ac.cagente,
    (SELECT tapelli1
      || DECODE(tapelli1, NULL, NULL, ' ')
      || tapelli2
      || DECODE(tapelli1
      || tapelli2, NULL, NULL, DECODE(tnombre1, NULL, NULL, ', '))
      || tnombre1
    FROM per_detper c,
      agentes a
    WHERE c.sperson = a.sperson
    AND a.cagente   = ac.cagente
    ) tagente,
    pac_isqlfor.f_per_contactos(
    (SELECT a.sperson FROM agentes a WHERE a.cagente = ac.cagente
    ), 1) telf,
    ac.ppartici
    || '%' porc_part
  FROM age_corretaje ac
  WHERE ac.sseguro = psseguro
  AND nmovimi      =
    (SELECT MAX(nmovimi)
    FROM age_corretaje
    WHERE sseguro = psseguro
    AND nmovimi  <= pnmovimi
    )
  ORDER BY islider DESC,
    cagente
  )
  LOOP
    IF pcolumn    = 1 THEN
      vret       := vret || i.cagente || ' \par ';
    ELSIF pcolumn = 2 THEN
      vret       := vret || i.tagente || ' \par ';
    ELSIF pcolumn = 3 THEN
      vret       := vret || i.telf || ' \par ';
    ELSIF pcolumn = 4 THEN
      vret       := vret || i.porc_part || ' \par ';
    END IF;
  END LOOP;
  RETURN f_jrep_trad(vret);
EXCEPTION
WHEN OTHERS THEN
  RETURN '';
END f_nom_inter_pyme;
/*****************************************************************
FUNCTION f_telefono_pyme
Para que traiga el telefono
param IN psseguro  : sseguro
return             : texto
Bug 0031409 - 08/06/2017 - LRG
BUG 36151 - LGG
******************************************************************/
FUNCTION f_telefono_pyme(
    psseguro IN NUMBER)
  RETURN VARCHAR2
IS
  v_telefono VARCHAR2(100);
BEGIN
  --
  SELECT tvalcon
  INTO v_telefono
  FROM per_contactos
  WHERE sperson =
    (SELECT sperson FROM tomadores WHERE sseguro = psseguro
    )
  AND ROWNUM  = 1
  AND ctipcon = 1;
  --
  RETURN v_telefono;
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_telefono_pyme;
/*****************************************************************
FUNCTION f_tipo_ben
Para que traiga el tipo de beneficiario
param IN psseguro  : sseguro
param IN psperson  : cod de la persona
return             : texto
Bug 0031409 - 08/06/2017 - LRG
BUG 36151 - LGG
******************************************************************/
FUNCTION f_tipo_ben(
    psseguro IN NUMBER,
    psperson IN NUMBER,
    pidioma  IN NUMBER)
  RETURN VARCHAR2
IS
  v_tipo VARCHAR2(100);
BEGIN
  SELECT DISTINCT
    (SELECT tatribu
    FROM detvalores
    WHERE cidioma = pidioma
    AND cvalor    = 1053
    AND catribu   = b.ctipben
    )
  INTO v_tipo
  FROM seguros s
  INNER JOIN benespseg b
  ON s.sseguro    = b.sseguro
  WHERE b.sseguro = psseguro
  AND b.sperson   = psperson;
  RETURN v_tipo;
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_tipo_ben;
/*****************************************************************
FUNCTION f_obs_amp_Pyme
Devuelve descripciones y valores de las de los amparos de un riesgo para Pyme
para renta, mercancias flotantes, relacion de bienes
param IN psseguro  : codigo de seguro
param IN pnriesgo  : numero de riesgo
param IN pnmovimi  : numero de Movimiento
param IN pcidioma  : codigo de idioma
param IN pcampo    : recupera la cod de la garantias, desc de las garantias, el capital
param IN pmodo     : modo EST/POL
return             : texto con las garantias del riesgo
BUG 31409 - 08/06/2017 - LGG
BUG 36151 - LGG
******************************************************************/
FUNCTION f_obs_amp_pyme(
    psseguro IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pnmovimi IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pcampo   IN NUMBER DEFAULT 1,
    ptipo    IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    psproces IN NUMBER DEFAULT NULL)--BUG 47494 MPC 08/03/2019 Se adiciona filtro
  RETURN CLOB--INI BUG 0074155 GZG 08/03/2022 SE CAMBIA A TIPO CLOB
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult    CLOB := ''; --BUG GZG 0066609 22/02/2021 se cambia tipo de variable a CLOB
    v_tablagar   VARCHAR2(4000)  := 'garanseg';--BUG 47494 MPC 08/03/2019 Se adiciona variable.
    v_filtrogar2 VARCHAR2(2000)  := '';        --BUG 47494 MPC 08/03/2019 Se adiciona variable.
    v_filtrogar  VARCHAR2(2000)  := '';        --BUG 47494 MPC 08/03/2019 Se adiciona variable.
    v_tconsulta  VARCHAR2(4000);
    v_tablaseg   VARCHAR2(30);
    v_act0       NUMBER(1);
    v_actividad  VARCHAR2(20);
    v_csituac    VARCHAR2(100);
    v_cpadre     VARCHAR2(500);--BUG GZG 0071841 25/10/2021
    v_cpadre_ant VARCHAR2(500);--BUG GZG 0071841 25/10/2021
    v_desc_a     VARCHAR2(3000);
    v_desc_b     VARCHAR2(3000);
  BEGIN
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      --INI BUG 47494 MPC 08/03/2019 Se adiciona filtron
      IF NVL(pmodo, 'POL') = 'CAR' THEN
        --
        v_tablagar   := 'garancar';
        v_filtrogar  := ' and d.sproces = '||psproces;
        v_filtrogar2 := ' and ga.sproces = '||psproces;
        --
      END IF;
      --FIN BUG 47494 MPC 08/03/2019 Se adiciona filtron
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    v_tconsulta := 'SELECT e.cgarant,';
    v_tconsulta := v_tconsulta || '  REPLACE(pac_isqlfor_lcol.f_des_garpro(c.sseguro,d.nriesgo,8,e.cgarant, ';
    v_tconsulta := v_tconsulta || '  c.sproduc,''POL''), CHR(39), CHR(39) ';
    v_tconsulta := v_tconsulta || '  || CHR(39)) a, ';
    v_tconsulta := v_tconsulta || '  f.tpregun ';
    v_tconsulta := v_tconsulta || '  ||'': '' ';
    v_tconsulta := v_tconsulta || '  ||DECODE(g.ctippre , 5, a.trespue,3, a.crespue ,6 ,a.crespue , b.trespue) c ';
    v_tconsulta := v_tconsulta || ' from pregungaranseg a left outer  join respuestas b on a.cpregun = b.cpregun and a.crespue = b.crespue and b.cidioma = ' || pcidioma;
    --INI BUG 0074155 GZG 08/03/2022 Se adiciona nmovimi
    v_tconsulta := v_tconsulta || ' inner join '||v_tablagar||' d on a.cgarant = d.cgarant and a.sseguro = d.sseguro AND a.nmovimi = d.nmovimi'; --BUG 47494 MPC 08/03/2019 Se modifica para poder modificar la tabla de garanseg.
    --FIN BUG 0074155 GZG 08/03/2022
    v_tconsulta := v_tconsulta || ' inner join seguros c on a.sseguro = c.sseguro ';
    v_tconsulta := v_tconsulta || ' inner join garanpro e on d.cgarant = e.cgarant  and a.cgarant = e.cgarant  and d.cgarant = e.cgarant and c.sproduc = e.sproduc ';
    v_tconsulta := v_tconsulta || ' inner join preguntas f on a.cpregun = f.cpregun  and f.cidioma = ' || pcidioma;
    v_tconsulta := v_tconsulta || ' inner join codipregun g on a.cpregun = g.cpregun and f.cidioma = ' || pcidioma;
    v_tconsulta := v_tconsulta || ' where d.cgarant in (3149,3175,3187,3190,3241,9584,6120,9585, 3152) ';
    v_tconsulta := v_tconsulta || ' and a.sseguro= ' || psseguro;
    v_tconsulta := v_tconsulta || v_filtrogar;                    --BUG 47494 MPC 08/03/2019 Se adiciona filtro de psproces.
    v_tconsulta := v_tconsulta || ' and a.sseguro= ' || psseguro; --BUG 47494 MPC 08/03/2019 Se adiciona filtro de psproces.
    v_tconsulta := v_tconsulta || ' AND d.nmovimi      = ';
    v_tconsulta := v_tconsulta || '  ( ';
    v_tconsulta := v_tconsulta || '    SELECT ';
    v_tconsulta := v_tconsulta || '      MAX(nmovimi) ';
    v_tconsulta := v_tconsulta || '    FROM ';
    v_tconsulta := v_tconsulta || '      '||v_tablagar||' ga '; --BUG 47494 MPC 08/03/2019 Se modifica para poder modificar la tabla de garanseg.
    v_tconsulta := v_tconsulta || '    WHERE ';
    v_tconsulta := v_tconsulta || '      sseguro       = ' || psseguro;
    v_tconsulta := v_tconsulta || v_filtrogar2; --BUG 47494 MPC 08/03/2019 Se adiciona filtro de psproces.
    v_tconsulta := v_tconsulta || '    AND ga.nmovimi <= ';
    v_tconsulta := v_tconsulta || '      ( ';
    v_tconsulta := v_tconsulta || '        SELECT ';
    v_tconsulta := v_tconsulta || '          MV.NMOVIMI ';
    v_tconsulta := v_tconsulta || '        FROM ';
    v_tconsulta := v_tconsulta || '          MOVSEGURO MV ';
    v_tconsulta := v_tconsulta || '        WHERE ';
    v_tconsulta := v_tconsulta || '          MV.SSEGURO   = GA.SSEGURO ';
    v_tconsulta := v_tconsulta || '        AND MV.CMOVSEG!=3 ';
    v_tconsulta := v_tconsulta || '        AND MV.NMOVIMI = ';
    v_tconsulta := v_tconsulta || '          ( ';
    v_tconsulta := v_tconsulta || '            SELECT ';
    v_tconsulta := v_tconsulta || '              MAX(nmovimi_cert) ';
    v_tconsulta := v_tconsulta || '            FROM ';
    v_tconsulta := v_tconsulta || '              detmovsegurocol ';
    v_tconsulta := v_tconsulta || '            WHERE ';
    v_tconsulta := v_tconsulta || '              sseguro_0 = ';
    v_tconsulta := v_tconsulta || '              ( ';
    v_tconsulta := v_tconsulta || '                SELECT ';
    v_tconsulta := v_tconsulta || '                  sseguro ';
    v_tconsulta := v_tconsulta || '                FROM ';
    v_tconsulta := v_tconsulta || '                  seguros ';
    v_tconsulta := v_tconsulta || '                WHERE ';
    v_tconsulta := v_tconsulta || '                  npoliza = ';
    v_tconsulta := v_tconsulta || '                  ( ';
    v_tconsulta := v_tconsulta || '                    SELECT ';
    v_tconsulta := v_tconsulta || '                      npoliza ';
    v_tconsulta := v_tconsulta || '                    FROM ';
    v_tconsulta := v_tconsulta || '                      seguros ';
    v_tconsulta := v_tconsulta || '                    WHERE ';
    v_tconsulta := v_tconsulta || '                      sseguro = ' || psseguro;
    v_tconsulta := v_tconsulta || '                  ) ';
    v_tconsulta := v_tconsulta || '                AND ncertif = 0 ';
    v_tconsulta := v_tconsulta || '              ) ';
    v_tconsulta := v_tconsulta || '            AND sseguro_cert = ' || psseguro;
    v_tconsulta := v_tconsulta || '          ) ';
    v_tconsulta := v_tconsulta || '      ) ';
    v_tconsulta := v_tconsulta || '  ) ';
    --P_CONTROL_ERROR('LG','1 f_obs_amp_Pyme','v_tconsulta:'||v_tconsulta);
    OPEN vr_cursor FOR v_tconsulta;
    LOOP
      FETCH vr_cursor --INTO v_cpadre, v_cgarant, v_tgarant, v_tpregun, v_cpregun, v_crespue;
      INTO v_cpadre,
        v_desc_a,
        v_desc_b;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF (v_cpadre_ant IS NULL) OR (v_cpadre_ant != v_cpadre) THEN
      v_tresult      := v_tresult || '\par ' || v_desc_a || '\par ';
    END IF;
    v_tresult    := v_tresult || v_desc_b || '\par ';
    v_cpadre_ant := v_cpadre;
  END LOOP;
  --P_CONTROL_ERROR('LG','2 f_obs_amp_Pyme','v_tresult:'||v_tresult);
  RETURN (f_jrep_trad_clob(v_tresult));--BUG GZG 0066609 22/02/2021 se cambia tipo de funcion a CLOB
EXCEPTION
WHEN OTHERS THEN
  RETURN ' ';
END f_obs_amp_pyme;
/*****************************************************************
FUNCTION f_agente_pyme
Devuelve el nombre del agente
BUG 31409 - 08/06/2017 - LGG
BUG 36151 - LGG
******************************************************************/
FUNCTION f_agente_pyme(
    pcagente IN NUMBER)
  RETURN VARCHAR
IS
  agente VARCHAR2(100);
BEGIN
  -- Busqueda del Agente
  IF pcagente IS NOT NULL THEN
    SELECT f_nombre(p.sperson, 1, NULL)
    INTO agente
    FROM agentes a
    INNER JOIN per_personas p
    ON a.sperson    = p.sperson
    WHERE a.cagente = pcagente;
  END IF;
  RETURN agente;
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_agente_pyme;
/*****************************************************************
FUNCTION f_importes_riesgo_pyme0
Devuelve los capitales de un riesgo
param IN psseguro  : codigo de seguro
param IN pnriesgo  : numero de riesgo
param IN pmodo     : modo EST/POL
param IN pgaracml  : 0-Todo riesgo/1-Corriente debil, manejo y lucro
return             : texto con los capitales del riesgo
BUG 31409 - 12/06/2017 - RV
BUG 36151 - LGG
BUG 36480 - 29/08/2017 - LGG - INICIO
BUG 37907 - 05/10/2017 - LGG
******************************************************************/
FUNCTION f_importes_riesgo_pyme0(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL,
    pgaracml IN NUMBER DEFAULT NULL,
    psproces IN NUMBER DEFAULT NULL, --MPC BUG 47494 07/03/2019 Se adiciona filtro. --INI/FIN JMG 29/09/2025 LTRPT-3880-AITSSD-5733
    pindsupar IN NUMBER DEFAULT NULL) --INI/FIN JMG 29/09/2025 LTRPT-3880-AITSSD-5733
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    --
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(4000);
    v_tlinia    VARCHAR2(500);--garangen.tgarant%TYPE;-- INICIO BUG 0049121 - 25/01/2019 - GZG - SE CAMBIA A VARCHAR2(500)
    v_tpargar   VARCHAR2(300);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot VARCHAR2(200);
    v_ctipcap garanpro.ctipcap%TYPE;
    v_cimpres garanpro.cimpres%TYPE;
    v_tgarant garangen.tgarant%TYPE;
    v_npargar   NUMBER := 0;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
    v_produc seguros.sproduc%TYPE;
    v_norden garanpro.norden%TYPE;
    v_es_admin NUMBER;
    nerror     NUMBER;
    vncertif   NUMBER;
    --INICIO BUG 37907 - 05/10/2017
    v_tlinia2 VARCHAR2(500);--FIN BUG 0049121 - 25/01/2019 - GZG - SE AUMENTA EL TAMAÃ`O DE LA VARIABLE DE 50 A 500
    --FIN BUG 37907 - 05/10/2017
    v_cgardep garanpro.cgardep%TYPE; --INI/FIN JMG 29/09/2025 LTRPT-3880-AITSSD-5733
  BEGIN
    --
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    --
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    --
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    --
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    --
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := --INICIO BUG 37907 - 05/10/2017
      --'select DISTINCT a.sproduc, pp.norden, TRIM(TO_CHAR(SUM(b),''999,999,999,999,999,999'')), TRIM(tgarant) from(SELECT ps.sproduc, s.cgarant, g.tgarant, pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,'
      'select DISTINCT a.sproduc, pp.norden, TRIM(TO_CHAR(SUM(b),''999,999,999,999,999,999'')), TRIM(tgarant), deducible from(SELECT ps.sproduc, s.cgarant, g.tgarant, pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,'
      --FIN BUG 37907 - 05/10/2017
      || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), '
      --INICIO BUG 37907 - 05/10/2017
      --|| ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d';
      || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d,' || '      pac_isqlfor_lcol.f_deducible_xgarantia(se.sseguro,1,' || pnriesgo || ' ,''POL'',g.cgarant) deducible';
      --FIN BUG 37907 - 05/10/2017
      --INI BUG 47494 MPC 07/03/2019 Se adiciona funcionalidad para previos de Cartera.
    ELSIF NVL(pmodo, 'POL') = 'CAR' THEN
      --INI JMG 29/09/2025 LTRPT-3880-AITSSD-5733
      IF NVL(pindsupar,0) = 0 THEN
      v_tconsulta          := 'select DISTINCT a.sproduc, pp.norden, TRIM(TO_CHAR(SUM(b),''999,999,999,999,999,999'')), TRIM(tgarant), deducible from(SELECT ps.sproduc, s.cgarant, g.tgarant, pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot),''POL'') a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), '
      --INI BUG 51634 MPC 05/06/2019 Se modifica filtro.
      || ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot,''POL'') d,' || '      pac_isqlfor_lcol.f_deducible_xgarantia((select sseguro from seguros where npoliza = se.npoliza and ncertif = 0),1,' || pnriesgo || ' ,''POL'',g.cgarant) deducible';
      --FIN BUG 51634 MPC 05/06/2019 Se modifica filtro.
      --FIN BUG 47494 MPC 07/03/2019 Se adiciona funcionalidad para previos de Cartera.
      ELSE
        v_tconsulta          := 'select DISTINCT a.sproduc, pp.norden, TRIM(TO_CHAR(SUM(b),''999,999,999,999,999,999'')), substr(upper(TGARANT),1,1)||substr(lower(TGARANT),2), deducible, CGARDEP from(SELECT ps.sproduc, s.cgarant, g.tgarant, pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot),''POL'') a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), '
        || ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot,''POL'') d,' || '      pac_isqlfor_lcol.f_deducible_xgarantia((select sseguro from seguros where npoliza = se.npoliza and ncertif = 0),1,' || pnriesgo || ' ,''POL'',g.cgarant) deducible';
      END IF;
       --FIN JMG 29/09/2025 LTRPT-3880-AITSSD-5733
    ELSE
      --INI BUG 0053242 GZG 16/07/2019
      SELECT ncertif,
        sproduc
      INTO vncertif,
        v_produc
      FROM seguros
      WHERE sseguro                                         = psseguro;
    IF NVL(f_parproductos_v(v_produc, 'DEDUCIBLE_CERO'), 0) = 1 AND vncertif = 0 THEN
      v_tconsulta                                          := 'select DISTINCT a.sproduc, pp.norden, TRIM(TO_CHAR(SUM(b),''999,999,999,999,999,999'')), TRIM(tgarant), deducible from(SELECT ps.sproduc, s.cgarant, g.tgarant, pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d,' || '      pac_isqlfor_lcol.f_deducible_xgarantia(' || psseguro || ',1,' || pnriesgo || ' ,''POL'',g.cgarant) deducible';
    ELSE
      --FIN BUG 0053242 GZG 16/07/2019
      v_tconsulta := --INICIO BUG 37907 - 05/10/2017
      --'select DISTINCT a.sproduc, pp.norden, TRIM(TO_CHAR(SUM(b),''999,999,999,999,999,999'')), TRIM(tgarant) from(SELECT ps.sproduc, s.cgarant, g.tgarant, pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,'
      'select DISTINCT a.sproduc, pp.norden, TRIM(TO_CHAR(SUM(b),''999,999,999,999,999,999'')), TRIM(tgarant), deducible from(SELECT ps.sproduc, s.cgarant, g.tgarant, pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,'
      --FIN BUG 37907 - 05/10/2017
      || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), '
      --INICIO BUG 37907 - 05/10/2017
      --|| ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot) d';
      || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d,' || '      pac_isqlfor_lcol.f_deducible_xgarantia(se.sseguro,1,' || pnriesgo || ' ,''POL'',g.cgarant) deducible';
      --FIN BUG 37907 - 05/10/2017
    END IF;--BUG 0053242 GZG 16/07/2019
  END IF;
  --
  v_tconsulta := v_tconsulta || ' FROM  garangen g, garanpro p, productos ps, ';
  --
  IF NVL(pmodo, 'POL') = 'EST' THEN
    v_tconsulta       := v_tconsulta || ' estgaranseg s, estseguros se'; --Se adiciona filtro de
    v_csituac         := '(0,7,5,2,4)';
    --INI BUG 47494 MPC 07/03/2019 Se adiciona funcionalidad para previos de Cartera.
  ELSIF NVL(pmodo, 'POL') = 'CAR' THEN
    v_tconsulta          := v_tconsulta || ' garancar s, seguros se';--BUG 0071311 GZG 28/09/2021 se comenta codigo, seguros so';
    v_csituac            := '(0,7,5,2,4)';
    --FIN BUG 47494 MPC 07/03/2019 Se adiciona funcionalidad para previos de Cartera.
  ELSE
    v_tconsulta                                 := v_tconsulta || ' garanseg s, seguros se';--BUG 0071311 GZG 28/09/2021 se comenta codigo, seguros so';
    IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
      v_csituac                                 := '(0,7,5,2)';
    ELSE
      v_csituac := '(0,7,5,2,4)';
    END IF;
  END IF;
  --
  v_tconsulta := v_tconsulta || ' WHERE g.cgarant = s.cgarant';
  v_tconsulta := v_tconsulta || ' AND p.cgarant = s.cgarant';
  v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
  v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
  v_tconsulta := v_tconsulta || ' AND p.sproduc = ps.sproduc';
  v_tconsulta := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
  v_tconsulta := v_tconsulta || ' AND se.csituac in ' || v_csituac;
  -- v_tconsulta := v_tconsulta || ' AND s.sseguro = so.sseguro'; --BUG 47494 MPC 07/03/2019 Se commenta
  --
  --INI JMG 29/09/2025 LTRPT-3880-AITSSD-5733
  IF NVL(pindsupar,0) = 0 THEN
  v_tconsulta := v_tconsulta || ' AND (p.CGARPADRE IS NULL )';
  END IF;
  --FIN JMG 29/09/2025 LTRPT-3880-AITSSD-5733
  --
  --INI BUG 0054043 GZG 12/08/2019
  IF pnmovimi   IS NOT NULL AND NVL(pmodo, 'POL') = 'POL' THEN--AITSSD-3746 GZG 05/12/2022
    v_tconsulta := v_tconsulta || ' AND s.nmovimi = (SELECT max(nmovimi) FROM garanseg where SSEGURO = ' || psseguro || ' and NMOVIMI <= ' || pnmovimi || ')';
  ELSE
    --FIN BUG 0054043 GZG 12/08/2019
    --INICIO BUG 0037907 - 05/10/2017 - LGG
    v_tconsulta := v_tconsulta || ' AND s.ffinefe is null ';
    --FIN    BUG 0037907 - 05/10/2017 - LGG
  END IF;--BUG 0054043 GZG 12/08/2019
  --INI BUG 47494 MPC 07/03/2019 Se adiciona funcionalidad para previos de Cartera.
  IF NVL(pmodo, 'POL') != 'EST' THEN
    --FIN BUG 47494 MPC 07/03/2019 Se adiciona funcionalidad para previos de Cartera.
    --v_tconsulta := v_tconsulta || ' AND s.sseguro = so.sseguro'; --BUG 47494 MPC 07/03/2019 Se adiciona codigo.--BUG 0071311 GZG 28/09/2021 se comenta codigo
    v_tconsulta := v_tconsulta || ' AND se.npoliza in  (select npoliza from seguros where sseguro in (' || psseguro || '))';--BUG 0071311 GZG 28/09/2021
  END IF; --BUG 47494 MPC 07/03/2019 Se adiciona funcionalidad para previos de Cartera.
  v_tconsulta := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
  v_tconsulta := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
  --BUG 36480 - 29/08/2017 - LGG - INICIO
  --INI BUG 47494 MPC 07/03/2019 Se adiciona funcionalidad para previos de Cartera.
  IF NVL(pmodo, 'POL') = 'CAR' THEN
    v_tconsulta       := v_tconsulta || ' AND s.sproces = '||psproces;
  --ELSE--INI BUG 0071311 GZG 28/09/2021 Se comenta
    --FIN BUG 47494 MPC 07/03/2019 Se adiciona funcionalidad para previos de Cartera.
    /*
    v_tconsulta := v_tconsulta || '    AND s.nmovimi = ';
    v_tconsulta := v_tconsulta || '      ( ';
    v_tconsulta := v_tconsulta || '        SELECT MAX(nmovimi) ';
    v_tconsulta := v_tconsulta || '        FROM garanseg WHERE ';
    v_tconsulta := v_tconsulta || '          sseguro=s.sseguro ';
    v_tconsulta := v_tconsulta || '          and cgarant= g.cgarant ';
    v_tconsulta := v_tconsulta || '          and nriesgo=' || pnriesgo || ' ) ';
    */--FIN BUG 0071311 GZG 28/09/2021
  END IF;--BUG 47494 MPC 07/03/2019 Se adiciona para previos de Cartera.
  --BUG 36480 - 29/08/2017 - LGG - FIN
  IF NVL(pmodo, 'POL') = 'EST' THEN
    --
    v_es_admin := pac_seguros.f_es_col_admin(psseguro, 'EST');
    --
    SELECT ncertif INTO vncertif FROM estseguros WHERE sseguro = psseguro;
    --
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM estseguros seg
      WHERE seg.sseguro = psseguro
      );
  ELSE
    --
    v_es_admin := pac_seguros.f_es_col_admin(psseguro, 'POL');
    --
    SELECT ncertif INTO vncertif FROM seguros WHERE sseguro = psseguro;
    --
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  END IF;
  --
  v_tconsulta := v_tconsulta || v_tpargar;
  --INICIO BUG 0037907 - 05/10/2017 - LGG
  --v_tconsulta := v_tconsulta || ' ORDER BY p.norden) a, garanpro pp WHERE a.cgarant=pp.cgarant AND  pp.sproduc = a.sproduc GROUP BY a.sproduc, pp.norden, a.cgarant, a.tgarant ORDER BY pp.norden';
  --INI JMG 29/09/2025 LTRPT-3880-AITSSD-5733
    v_tconsulta := v_tconsulta || ' ORDER BY p.norden) a, garanpro pp WHERE a.cgarant=pp.cgarant AND  pp.sproduc = a.sproduc GROUP BY a.sproduc, pp.norden, a.cgarant,pp.CGARDEP, a.tgarant,a.deducible ORDER BY pp.norden';
  --FIN JMG 29/09/2025 LTRPT-3880-AITSSD-5733
  --FIN BUG 0037907 - 05/10/2017 - LGG
  p_control_error('LG', 'f_importes_riesgo_pyme0', 'v_tconsulta:' || v_tconsulta);
  --
  --INI JMG 29/09/2025 LTRPT-3880-AITSSD-5733
  IF NVL(pindsupar,0) = 0 THEN
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor --INICIO BUG 0037907 - 05/10/2017 - LGG
      --INTO v_produc, v_norden, v_tlinia,v_tgarant;
    INTO v_produc,
      v_norden,
      v_tlinia,
      v_tgarant,
      v_tlinia2;
    --FIN BUG 0037907 - 05/10/2017 - LGG
    EXIT
  WHEN vr_cursor%NOTFOUND;
    --
    IF v_npargar = 1 AND v_icaptot = 0 THEN
      SELECT tatribu
      INTO v_tlinia
      FROM detvalores
      WHERE cvalor = 126
      AND catribu  = NVL(v_cimpres, 59)
      AND cidioma  = NVL(pcidioma, 8);
    END IF;
    --
    IF pcampo   = 2 THEN
      v_tlinia := v_tgarant;
    END IF;
    --
    --INICIO BUG 0037907 - 05/10/2017
    IF pcampo   = 5 THEN
      v_tlinia := v_tlinia2;
    END IF;
    --FIN BUG 0037907 - 05/10/2017
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  ELSE
    OPEN vr_cursor FOR v_tconsulta;
      LOOP
        FETCH vr_cursor
        INTO v_produc,
          v_norden,
          v_tlinia,
          v_tgarant,
          v_tlinia2,
          v_cgardep;
        EXIT
      WHEN vr_cursor%NOTFOUND;
        --
        IF v_npargar = 1 AND v_icaptot = 0 THEN
          SELECT tatribu
          INTO v_tlinia
          FROM detvalores
          WHERE cvalor = 126
          AND catribu  = NVL(v_cimpres, 59)
          AND cidioma  = NVL(pcidioma, 8);
        END IF;
        --
        IF pcampo   = 2 THEN
          v_tlinia := v_tgarant;
        END IF;

        IF pcampo   = 5 THEN
          v_tlinia := v_tlinia2;
        END IF;

        IF pcampo   = 6 THEN
          v_tlinia := v_cgardep;
        END IF;

        v_tresult := v_tresult || v_tlinia || '\par ';
      END LOOP;
  END IF;

  --FIN JMG 29/09/2025 LTRPT-3880-AITSSD-5733
  --
  --INI BUG 0048449 - 24/12/2018 - AMC Si genera error con la primera funciÃ³n, se usa la funcion con clob
  BEGIN
    RETURN(f_jrep_trad(v_tresult));
  EXCEPTION
  WHEN OTHERS THEN
    RETURN(f_jrep_trad_clob(v_tresult));
  END;
  --RETURN (f_jrep_trad(v_tresult));--BUG 0048449 - 24/12/2018 - AMC Se inactiva linea
  --FIN BUG 0048449 - 24/12/2018 - AMC
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_riesgo_pyme0;
-- FIN  BUG 31409 - 12/06/2017 - RV
--BUG 36480 - 29/08/2017 - LGG - FIN
-- FIN  BUG 37907 - 05/10/2017 - LGG
-- INICIO BUG 0047668 - 07/02/2019 - GZG - Se crea funcion para solo los amparos vigentes
FUNCTION f_importes_riesgo_pyme0_vig(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL,
    pgaracml IN NUMBER DEFAULT NULL,
    psproces IN NUMBER DEFAULT NULL) --BUG 47494 MPC 08/03/2019 Se adiciona parametro.
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    --
    vr_cursor r_cursor;
    v_tresult     VARCHAR2(32000) := '';
    v_tconsulta   VARCHAR2(4000);
    v_tconsulta_1 VARCHAR2(4000) := ''; --BUG 47494 MPC 08/03/2019 Se adiciona variable.
    v_tlinia garangen.tgarant%TYPE;
    v_tpargar VARCHAR2(300);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot VARCHAR2(200);
    v_ctipcap garanpro.ctipcap%TYPE;
    v_cimpres garanpro.cimpres%TYPE;
    v_tgarant garangen.tgarant%TYPE;
    v_npargar   NUMBER := 0;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
    v_produc seguros.sproduc%TYPE;
    v_norden garanpro.norden%TYPE;
    v_es_admin NUMBER;
    nerror     NUMBER;
    vncertif   NUMBER;
    v_tlinia2  VARCHAR2(200);--BUG 0063566 GZG 22/09/2020 se aumenta valor de 50 a 200
    v_cmotmov  VARCHAR2(1000);
    v_total    NUMBER;
    v_sum      NUMBER := 0;
  BEGIN
    --
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    --
    SELECT COUNT(*)
    INTO v_total
    FROM motmovseg
    WHERE cidioma = 8
    AND tmotmov LIKE ('%Anulac%');
  FOR i IN
  (SELECT TO_CHAR(cmotmov) cmotmov
  FROM motmovseg
  WHERE cidioma = 8
  AND tmotmov LIKE ('%Anulac%')
  )
  LOOP
    v_sum       := v_sum + 1;
    IF v_sum     < v_total THEN
      v_cmotmov := v_cmotmov || i.cmotmov || ''',''' ;
    ELSE
      v_cmotmov := v_cmotmov || i.cmotmov;
    END IF;
  END LOOP;
  --
  v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
  --
  EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
  IN psseguro;
  --
  IF v_act0      = 1 THEN
    v_actividad := '0';
  ELSE
    v_actividad := 'se.cactivi';
  END IF;
  --
  IF NVL(pmodo, 'POL') = 'EST' THEN
    --FIN BUG GZG 0050295: Se reemplaza v_cmotmov por 100 para que cuente unicamente las altas de poliza
    v_tconsulta := 'select DISTINCT a.sproduc, pp.norden, TRIM(TO_CHAR(SUM(b),''999,999,999,999,999,999'')), TRIM(tgarant), deducible from(SELECT ps.sproduc, s.cgarant, g.tgarant, pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a,' || ' case when m.cmotmov in (''' || v_cmotmov || ''') then s.icaptot * -1 when m.cmotmov = 100 then s.icaptot end b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d,' || '      pac_isqlfor_lcol.f_deducible_xgarantia(se.sseguro,1,' || pnriesgo || ' ,''POL'',g.cgarant) deducible';
    --INI BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n
  ELSIF NVL(pmodo, 'POL') = 'CAR' THEN
    --
    v_tconsulta := 'select DISTINCT a.sproduc, pp.norden, TRIM(TO_CHAR(SUM(b),''999,999,999,999,999,999'')), TRIM(tgarant), deducible from(SELECT ps.sproduc, s.cgarant, g.tgarant, pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a,' || ' case when m.cmotmov in (''' || v_cmotmov || ''') then s.icaptot * -1 when m.cmotmov not in (''' || v_cmotmov || ''') then s.icaptot end b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d,' || '      pac_isqlfor_lcol.f_deducible_xgarantia(se.sseguro,1,' || pnriesgo || ' ,''CAR'',g.cgarant,'||psproces||') deducible';
    --
    --FIN BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n
  ELSE
    v_tconsulta := 'select DISTINCT a.sproduc, pp.norden, TRIM(TO_CHAR(SUM(b),''999,999,999,999,999,999'')), TRIM(tgarant), deducible from(SELECT ps.sproduc, s.cgarant, g.tgarant, pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a,' || ' case when m.cmotmov in (''' || v_cmotmov || ''') then s.icaptot * -1 when m.cmotmov = 100 then s.icaptot end b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d,' || '      pac_isqlfor_lcol.f_deducible_xgarantia(se.sseguro,1,' || pnriesgo || ' ,''POL'',g.cgarant) deducible';
    --FIN BUG GZG 0050295: Se reemplaza v_cmotmov por 100 para que cuente unicamente las altas de poliza
  END IF;
  --
  v_tconsulta := v_tconsulta || ' FROM  garangen g, garanpro p, productos ps, ';
  --
  IF NVL(pmodo, 'POL') = 'EST' THEN
    v_tconsulta       := v_tconsulta || ' estgaranseg s, estseguros se';
    v_csituac         := '(0,7,5,2,4)';
    --INI BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n
  ELSIF NVL(pmodo, 'POL') = 'CAR' THEN
    --
    v_tconsulta   := v_tconsulta || ' garancar s, seguros se, DETMOVSEGUROCOL d, movseguro m';
    v_tconsulta_1 := ' AND s.sproces = '||psproces;
    --
    --FIN BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n
  ELSE
    v_tconsulta := v_tconsulta || ' garanseg s, seguros se, DETMOVSEGUROCOL d, movseguro m';
  END IF;
  --
  v_tconsulta := v_tconsulta || ' WHERE d.sseguro_0 = ' || psseguro;
  v_tconsulta := v_tconsulta || ' AND d.nmovimi_0 BETWEEN 1 AND ' || pnmovimi;
  v_tconsulta := v_tconsulta || ' AND sseguro_cert = se.sseguro';
  v_tconsulta := v_tconsulta || ' AND se.npoliza in  (select npoliza from seguros where sseguro in (' || psseguro || '))';
  --
  v_tconsulta := v_tconsulta || v_tconsulta_1; --BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
  v_tconsulta := v_tconsulta || ' AND g.cgarant = s.cgarant';
  v_tconsulta := v_tconsulta || ' AND p.cgarant = s.cgarant';
  v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
  v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
  v_tconsulta := v_tconsulta || ' AND p.sproduc = ps.sproduc';
  v_tconsulta := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
  --
  v_tconsulta := v_tconsulta || ' AND (p.CGARPADRE IS NULL )';
  --
  v_tconsulta := v_tconsulta || ' AND s.ffinefe is null ';
  v_tconsulta := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
  v_tconsulta := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
  --
  IF NVL(pmodo, 'POL') = 'EST' THEN
    --
    v_es_admin := pac_seguros.f_es_col_admin(psseguro, 'EST');
    --
    SELECT ncertif INTO vncertif FROM estseguros WHERE sseguro = psseguro;
    --
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM estseguros seg
      WHERE seg.sseguro = psseguro
      );
  ELSE
    --
    v_es_admin := pac_seguros.f_es_col_admin(psseguro, 'POL');
    --
    SELECT ncertif INTO vncertif FROM seguros WHERE sseguro = psseguro;
    --
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  END IF;
  --
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' and m.sseguro = d.sseguro_cert';
  v_tconsulta := v_tconsulta || ' and d.nmovimi_cert = m.nmovimi';
  v_tconsulta := v_tconsulta || ') a, garanpro pp WHERE a.cgarant=pp.cgarant AND  pp.sproduc = a.sproduc GROUP BY a.sproduc, pp.norden, a.cgarant, a.tgarant,a.deducible ORDER BY pp.norden';
  --
  --p_control_error('LG', 'f_importes_riesgo_pyme0', 'v_tconsulta:' || v_tconsulta);
  --
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_produc, v_norden, v_tlinia, v_tgarant, v_tlinia2;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    --
    IF v_npargar = 1 AND v_icaptot = 0 THEN
      SELECT tatribu
      INTO v_tlinia
      FROM detvalores
      WHERE cvalor = 126
      AND catribu  = NVL(v_cimpres, 59)
      AND cidioma  = NVL(pcidioma, 8);
    END IF;
    --
    IF pcampo   = 2 THEN
      v_tlinia := v_tgarant;
    END IF;
    --
    IF pcampo   = 5 THEN
      v_tlinia := v_tlinia2;
    END IF;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  --
  BEGIN
    RETURN(f_jrep_trad(v_tresult));
  EXCEPTION
  WHEN OTHERS THEN
    RETURN(f_jrep_trad_clob(v_tresult));
  END;
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_riesgo_pyme0_vig;
-- FIN BUG 0047668 - 07/02/2019 - GZG - Se crea funcion para solo los amparos vigentes
/*****************************************************************
FUNCTION f_importes_riesgo_pyme_bie
Devuelve los valores de detalle bienes
Para solo "Basico todo riesgo daÃ¿Â±os materiales"
param IN psseguro  : codigo de seguro
param IN pnriesgo  : numero de riesgo
param IN pmodo     : modo EST/POL
return             : texto con los valores
BUG 31409 - 16/06/2017 - LGG
BUG 36151 - LGG
******************************************************************/
FUNCTION f_importes_riesgo_pyme_bie(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL,
    psproces IN NUMBER DEFAULT NULL) --MPC BUG 47494 08/03/2019 Se adiciona filtro.
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(4000);
    v_tlinia garangen.tgarant%TYPE;
    v_tpargar VARCHAR2(300);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot VARCHAR2(200);
    v_ctipcap garanpro.ctipcap%TYPE;
    v_cimpres garanpro.cimpres%TYPE;
    v_tgarant garangen.tgarant%TYPE;
    v_npargar   NUMBER := 0;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
    v_produc seguros.sproduc%TYPE;
    v_norden garanpro.norden%TYPE;
    v_es_admin NUMBER;
    nerror     NUMBER;
    vncertif   NUMBER;
  BEGIN
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := 'select DISTINCT a.sproduc, pp.norden, TRIM(TO_CHAR(SUM(b),''999,999,999,999,999,999'')), TRIM(tgarant) from(SELECT ps.sproduc, s.cgarant, g.tgarant, pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d';
    ELSE
      v_tconsulta := 'select DISTINCT a.sproduc, pp.norden, TRIM(TO_CHAR(SUM(b),''999,999,999,999,999,999'')), TRIM(tgarant) from(SELECT ps.sproduc, s.cgarant, g.tgarant, pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot) d';
    END IF;
    v_tconsulta         := v_tconsulta || ' FROM  garangen g, garanpro p, productos ps, ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' estgaranseg s, estseguros se';
      v_csituac         := '(0,7,5,2,4)';
      --INI BUG 47494 MPC 08/03/2019 Se crea filtro para previos de cartera.
    ELSIF NVL(pmodo, 'POL')                        = 'CAR' THEN
      v_tconsulta                                 := v_tconsulta || ' garancar s, seguros se, seguros so';
      IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
        v_csituac                                 := '(0,7,5,2)';
      ELSE
        v_csituac := '(0,7,5,2,4)';
      END IF;
      --FIN BUG 47494 MPC 08/03/2019 Se crea filtro para previos de cartera.
    ELSE
      v_tconsulta                                 := v_tconsulta || ' garanseg s, seguros se, seguros so';
      IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
        v_csituac                                 := '(0,7,5)';--BUG 0063464 GZG 18/09/2020 Se elimina csituac 2
      ELSE
        v_csituac := '(0,7,5,4)';--BUG 0063464 GZG 18/09/2020 Se elimina csituac 2
      END IF;
    END IF;
    v_tconsulta := v_tconsulta || ' WHERE g.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = ps.sproduc';
    v_tconsulta := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' AND se.csituac in ' || v_csituac;
    --v_tconsulta := v_tconsulta || ' AND s.sseguro = so.sseguro'; -- BUG 47494 MPC 08/03/2019 Se comenta.
    --
    -- Para solo "Basico todo riesgo daÃ¿Â±os materiales"
    v_tconsulta := v_tconsulta || ' AND p.cgarpadre = 3114';
    --INI BUG 47494 MPC 08/03/2019 Se Adiciona filtro.
    IF NVL(pmodo, 'POL') != 'EST' THEN
      v_tconsulta        := v_tconsulta || ' AND s.sseguro = so.sseguro';
      v_tconsulta        := v_tconsulta || ' and s.ffinefe is null';--BUG 0056673 28/11/2019 GZG
      --
      IF NVL(pmodo, 'POL') = 'CAR' THEN
        --
        v_tconsulta := v_tconsulta || ' AND s.sproces = '||psproces;
        --
      END IF;
      --FIN  BUG 47494 MPC 08/03/2019 Se Adiciona filtro.
      --
      --INI BUG 0056781 - 02/12/2019 - CASL - Se Adicionan filtros.
      --
      --v_tconsulta := v_tconsulta || ' AND so.npoliza in  (select npoliza from seguros where sseguro in (' || psseguro || '))';
      --
      v_tconsulta := v_tconsulta || ' AND so.sseguro IN(SELECT DISTINCT(sseguro_cert)
                                                          FROM detmovsegurocol
                                                         WHERE sseguro_0 = '||psseguro||'
                                                           AND nmovimi_0 <= NVL('||NVL(TO_CHAR(pnmovimi), 'NULL')||', (SELECT MAX(nmovimi)
                                                                                                                         FROM movseguro
                                                                                                                        WHERE sseguro = '||psseguro||'
                                                                                                                          AND cmovseg <> 52)))';
      v_tconsulta := v_tconsulta || ' AND s.nmovimi = (SELECT MAX(nmovimi)
                                                         FROM garanseg
                                                        WHERE sseguro = s.sseguro
                                                          AND nriesgo = s.nriesgo
                                                          AND ffinefe IS NULL)';
      --
      --FIN BUG 0056781 - 02/12/2019 - CASL

      --
    END IF;--BUG 47494 MPC 08/03/2019 Se Adiciona filtro.
    v_tconsulta         := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_es_admin        := pac_seguros.f_es_col_admin(psseguro, 'EST');
      SELECT ncertif INTO vncertif FROM estseguros WHERE sseguro = psseguro;
    --
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM estseguros seg
      WHERE seg.sseguro = psseguro
      );
  ELSE
    v_es_admin := pac_seguros.f_es_col_admin(psseguro, 'POL');
    SELECT ncertif INTO vncertif FROM seguros WHERE sseguro = psseguro;
    --
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  END IF;
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden) a, garanpro pp WHERE a.cgarant=pp.cgarant AND  pp.sproduc = a.sproduc GROUP BY a.sproduc, pp.norden, a.cgarant, a.tgarant ORDER BY pp.norden';
  --p_control_error('LG', 'F_IMPORTES_RIESGO_PYME', 'v_tconsulta:' || v_tconsulta);
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_produc, v_norden, v_tlinia, v_tgarant;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF v_npargar = 1 AND v_icaptot = 0 THEN
      SELECT tatribu
      INTO v_tlinia
      FROM detvalores
      WHERE cvalor = 126
      AND catribu  = NVL(v_cimpres, 59)
      AND cidioma  = NVL(pcidioma, 8);
    END IF;
    IF pcampo   = 2 THEN
      v_tlinia := v_tgarant;
    END IF;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_riesgo_pyme_bie;
-- FIN  BUG 31409 - 16/06/2017 - LGG
---INI BUG 31409 - 20/06/2017 - LGG
/*****************************************************************
FUNCTION f_dat_recibo_codbarras
param IN psseguro  :
param IN pnmovimi  :
param IN pcampo    :
param IN pnrecibo  :
return             : texto
BUG 31409 - 20/06/2017 - LGG
BUG 36151 - LGG
BUG 36480 - LGG
BUG 37907 - LGG
******************************************************************/
FUNCTION f_dat_recibo_codbarras(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER,
    pcampo   IN NUMBER,
    pnrecibo IN NUMBER DEFAULT NULL,
    psproces IN NUMBER DEFAULT NULL,   --BUG 47494 MPC 08/03/2019 Se adiciona parametro
    ptablas  IN VARCHAR2 DEFAULT 'POL')--BUG 47494 MPC 08/03/2019 Se adiciona parametro
  RETURN VARCHAR2
IS
  v_tresult VARCHAR2(4000);
  vnrec     VARCHAR2(100);
  vtot      VARCHAR2(100);
  vtot_aux  NUMBER; --BUG 47494 MPC 08/03/2019 Se crea variable.
  vfefec    VARCHAR2(100);
  Vfemis    DATE; --BUG 47494 MPC 08/03/2019 Se crea variable.
  v_nrecibo recibos.nrecibo%TYPE;
  --INCIO BUG 36480 - LGG
  v_ctiprec recibos.ctiprec%TYPE;
  --FIN BUG 36480 - LGG
  vcramo     NUMBER;
  vcccompani NUMBER;
  v_ncertif  NUMBER;
  vitotalr   NUMBER;
BEGIN
  SELECT cramo,
    DECODE(ccompani, 325, 0, ccompani),
    ncertif
  INTO vcramo,
    vcccompani,
    v_ncertif
  FROM seguros
  WHERE sseguro = psseguro;
  IF vcramo     = 103 AND pnrecibo IS NULL AND v_ncertif <> 0 THEN
    RETURN NULL;
  END IF;
  IF pnrecibo IS NULL THEN
    BEGIN
      --INI BUG 47494 MPC 08/12/2019 Se adiciona condiciÃ³n
      IF ptablas = 'CAR' THEN
        SELECT nrecibo
        INTO v_nrecibo
        FROM reciboscar
        WHERE sseguro = psseguro
        AND sproces   = psproces
        AND nrecibo   =
          (SELECT MAX(nrecibo)
          FROM reciboscar
          WHERE sseguro = psseguro
          AND sproces   = psproces
          );
      ELSE
        --FIN BUG 47494 MPC 08/12/2019 Se adiciona condiciÃ³n
        SELECT nrecibo
        INTO v_nrecibo
        FROM recibos
        WHERE sseguro = psseguro
        AND nrecibo   =
          (SELECT MAX(nrecibo)
          FROM recibos
          WHERE sseguro = psseguro
          AND nmovimi   = pnmovimi
          );
      END IF; --BUG 47494 MPC 08/12/2019 Se adiciona condiciÃ³n
    EXCEPTION
    WHEN OTHERS THEN
      v_nrecibo := 0;
    END;
  ELSE
    --INCIO BUG 36480 - LGG
    --INI BUG 47494 MPC 08/12/2019 Se adiciona condiciÃ³n
    IF ptablas = 'CAR' THEN
      SELECT ctiprec
      INTO v_ctiprec
      FROM reciboscar
      WHERE nrecibo = pnrecibo
      AND sproces   = psproces;
    ELSE
      --FIN BUG 47494 MPC 08/12/2019 Se adiciona condiciÃ³n
      SELECT ctiprec
      INTO v_ctiprec
      FROM recibos
      WHERE nrecibo = pnrecibo;
      --FIN BUG 36480 - LGG
    END IF; --BUG 47494 MPC 08/12/2019 Se adiciona condiciÃ³n
    v_nrecibo := pnrecibo;
  END IF;
  BEGIN
    --INI BUG 47494 MPC 08/12/2019 Se adiciona condiciÃ³n
    IF ptablas = 'CAR' THEN
      SELECT itotalr
      INTO vitotalr
      FROM vdetreciboscar
      WHERE nrecibo = v_nrecibo
      AND sproces   = psproces;
    ELSE
      --FIN BUG 47494 MPC 08/12/2019 Se adiciona condiciÃ³n
      SELECT itotalr
      INTO vitotalr
      FROM vdetrecibos
      WHERE nrecibo = v_nrecibo;
    END IF; --BUG 47494 MPC 08/12/2019 Se adiciona condiciÃ³n
  EXCEPTION
  WHEN NO_DATA_FOUND THEN
    NULL;
  END;
  IF vitotalr = 0 THEN
    RETURN NULL;
  END IF;
  --INCIO BUG 36480 - LGG
  IF v_ctiprec = 9 AND ptablas != 'CAR' THEN --BUG 47494 MPC 08/12/2019 Se adiciona condiciÃ³n
    SELECT LPAD(r.nrecibo, 20, '0') nrec,
      '-'
      || TRIM(TO_CHAR(LPAD(NVL(ROUND(vd.itotalr, 0), 0), ((TRUNC(LENGTH(ROUND(vd.itotalr, 0)) / 2) + (((LENGTH(ROUND(vd.itotalr, 0)) / 2) - TRUNC(LENGTH(ROUND(vd.itotalr, 0)) / 2)) * 2)) * 2), '0'), '999,999,999,999,999.99')) tot,
      UPPER(TO_CHAR(NVL(f_flimitepag(psseguro, pnmovimi, m.cmotmov, 1, pnrecibo), (m.femisio  + pac_propio_lcol.f_numdias_periodo_gracia(s.sseguro))), 'yyyy-mon-dd')) fefec
    INTO vnrec,
      vtot,
      vfefec
    FROM vdetrecibos_monpol vd,
      recibos r,
      seguros s,
      productos pp,
      movseguro m
    WHERE vd.nrecibo = r.nrecibo
    AND r.sseguro    = s.sseguro
    AND s.sseguro    = m.sseguro
    AND r.nmovimi    = m.nmovimi
    AND r.sseguro    = psseguro
    AND s.sproduc    = pp.sproduc
    AND r.nmovimi    = pnmovimi
    AND r.nrecibo    = v_nrecibo;
  ELSE
    --INI BUG 47494 MPC 08/12/2019 Se adiciona condiciÃ³n
    IF ptablas = 'CAR' AND v_nrecibo != 0 THEN --BUG 47494 MPC 08/03/2019 Se modifica codigo
      SELECT LPAD(r.nrecibo, 20, '0') nrec,
        TO_CHAR(LPAD(NVL(ROUND(vd.itotalr, 0), 0), ((TRUNC(LENGTH(ROUND(vd.itotalr, 0)) / 2) + (((LENGTH(ROUND(vd.itotalr, 0)) / 2) - TRUNC(LENGTH(ROUND(vd.itotalr, 0)) / 2)) * 2)) * 2), '0'), '999,999,999,999,999.99') tot,
        UPPER(TO_CHAR(r.femisio                                                         + pac_propio_lcol.f_numdias_periodo_gracia(s.sseguro), 'yyyy-mon-dd')) fefec
      INTO vnrec,
        vtot,
        vfefec
      FROM vdetreciboscar_monpol vd,
        reciboscar r,
        seguros s,
        productos pp
      WHERE vd.nrecibo = r.nrecibo
      AND vd.sproces   = r.sproces
      AND r.sseguro    = s.sseguro
      AND r.sseguro    = psseguro
      AND s.sproduc    = pp.sproduc
      AND r.sproces    = psproces
      AND r.nrecibo    = v_nrecibo;
      --
    ELSIF ptablas = 'CAR' THEN
      --
      SELECT SUM(vd.itotalr),
        TRUNC(r.femisio)
      INTO vtot_aux,
        Vfemis
      FROM vdetreciboscar_monpol vd,
        reciboscar r,
        seguros s,
        productos pp
      WHERE vd.nrecibo = r.nrecibo
      AND vd.sproces   = r.sproces
      AND r.sseguro    = s.sseguro
      AND s.npoliza   IN
        (SELECT npoliza FROM seguros WHERE sseguro = psseguro
        )
      AND s.sproduc = pp.sproduc
      AND r.sproces = psproces
      GROUP BY r.sproces,
        TRUNC(r.femisio);
      --
      vtot_aux := vtot_aux                                                                    + pac_isqlfor_lcol.f_gast4095(psseguro,1,Vfemis) + pac_isqlfor_lcol.f_gast4095(psseguro,2,Vfemis);
      vtot     := TO_CHAR(LPAD(NVL(ROUND(vtot_aux, 0), 0), ((TRUNC(LENGTH(ROUND(vtot_aux, 0)) / 2) + (((LENGTH(ROUND(vtot_aux, 0)) / 2) - TRUNC(LENGTH(ROUND(vtot_aux, 0)) / 2)) * 2)) * 2), '0'), '999,999,999,999,999.99');
      --
    ELSE
      --FIN BUG 47494 MPC 08/12/2019 Se adiciona condiciÃ³n
      SELECT LPAD(r.nrecibo, 20, '0') nrec,
        TO_CHAR(LPAD(NVL(ROUND(vd.itotalr, 0), 0), ((TRUNC(LENGTH(ROUND(vd.itotalr, 0))        / 2) + (((LENGTH(ROUND(vd.itotalr, 0)) / 2) - TRUNC(LENGTH(ROUND(vd.itotalr, 0)) / 2)) * 2)) * 2), '0'), '999,999,999,999,999.99') tot,
        UPPER(TO_CHAR(NVL(f_flimitepag(psseguro, pnmovimi, m.cmotmov, 1, pnrecibo), (m.femisio + pac_propio_lcol.f_numdias_periodo_gracia(s.sseguro))), 'yyyy-mon-dd')) fefec
      INTO vnrec,
        vtot,
        vfefec
      FROM vdetrecibos_monpol vd,
        recibos r,
        seguros s,
        productos pp,
        movseguro m
      WHERE vd.nrecibo = r.nrecibo
      AND r.sseguro    = s.sseguro
      AND s.sseguro    = m.sseguro
      AND r.nmovimi    = m.nmovimi
      AND r.sseguro    = psseguro
      AND s.sproduc    = pp.sproduc
      AND r.nmovimi    = pnmovimi
      AND r.nrecibo    = v_nrecibo;
    END IF; --BUG 47494 MPC 08/12/2019 Se adiciona condiciÃ³n
  END IF;
  --FIN BUG 36480 - LGG
  --No de recibo
  IF pcampo    = 1 THEN
    v_tresult := vnrec;
  END IF;
  --Valor total del recibo que sale en el codigo barras
  IF pcampo    = 2 THEN
    v_tresult := vtot;
  END IF;
  --Fecha de Efecto del recibo que sale en el codigo barras
  IF pcampo    = 3 THEN
    v_tresult := vfefec;
  END IF;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_dat_recibo_codbarras;
---FIN BUG 31409 - 20/06/2017 - LGG
---FIN BUG 36480 - 20/06/2017 - LGG
---FIN BUG 37907 - LGG
/*****************************************************************
FUNCTION f_jrep_trad_pyme
Formatea un varchar con saltos para su visualizaci?n correcta en CSV
param IN pentrada  : texto de entrada
return             : texto formateado para csv
Bug 19927 - 28/11/2011 - JTS
Bug 31409 - 24/07/2017 - LGG
BUG 36151 - LGG
******************************************************************/
FUNCTION f_jrep_trad_pyme(
    pentrada IN CLOB)
  RETURN CLOB
IS
  --
  --INI BUG 0043014 - 04/05/2018 - CASL - Se crea variable
  --
  v_entrada CLOB;
  --
  --FIN BUG 0043014 - 04/05/2018 - CASL
  --
BEGIN
  IF pentrada IS NULL THEN
    RETURN NULL; -- para que funcionen los NVLS
  END IF;
  --
  --INI BUG 0043014 - 04/05/2018 - CASL - Se reemplaza el texto <br> en Mayuscula y minuscula
  --
  v_entrada := REPLACE(pentrada, '<BR>', '\par ');
  v_entrada := REPLACE(pentrada, '<br>', '\par ');
  --
  --FIN BUG 0043014 - 04/05/2018 - CASL
  --
  --Bug 22798 - 16/07/2012 - ECP -LCOL897 - Tratamiento de comillas dobles en la caratula
  -- Se cambio RETURN REPLACE(REPLACE('"' || pentrada || '"', '\par "', '"'), '\par ', CHR(10)); por
  RETURN REPLACE(REPLACE(REPLACE('"' || REPLACE(v_entrada, CHR(34), CHR(39)) || '"', '\par "', '"'), '\par ', CHR(10)), '\tab ', CHR(32));----BUG 0043014 - 04/05/2018 - CASL - Se cambia pentrada por v_entrada
END f_jrep_trad_pyme;
/*****************************************************************
FUNCTION f_clausulas_pyme_descsup
Clausulas de Pyme con las observaciones del movimiento (ant/actual)
param IN psseguro  :
param IN pnmovimi  :
param IN pcidioma :
param IN ptabla   :
param IN ptablas  :
para IN pcduplica:
para IN pregini: nordcla inicial
para IN pregfin: nordcla final
return            : number
Bug  - 24/07/2017 - LGG
BUG 36151 - LGG
******************************************************************/
FUNCTION f_clausulas_pyme_descsup(
    psseguro  IN NUMBER,
    pnmovimi  IN NUMBER,
    pcidioma  IN NUMBER,
    ptabla    IN VARCHAR2 DEFAULT 'POL',
    pcduplica IN NUMBER DEFAULT 0,
    pregini   IN NUMBER DEFAULT 0, --MPC BUG 0049242 25/01/2019 Se modifica default por de 1 a 0.
    pregfin   IN NUMBER DEFAULT 60)--MPC BUG 0049242 25/01/2019 Se adiciona default 60.
  RETURN CLOB
IS
  vret CLOB;
  vsproduc NUMBER;--BUG 0061783 GZG 05/01/2020
  vcmotmov NUMBER;--BUG 0061783 GZG 05/01/2020
BEGIN
  IF ptabla = 'POL' THEN
    --INI BUG 0061783 GZG 30/12/2020
    SELECT sproduc INTO vsproduc
      FROM seguros
     WHERE sseguro = psseguro;
     --
    SELECT cmotmov INTO vcmotmov
      FROM movseguro
     WHERE sseguro = psseguro
       AND nmovimi = pnmovimi;
     --
     IF vcmotmov IN (404) and NVL(pac_parametros.f_parproducto_n(vsproduc, 'NMOVIMI_CLAUESP'), 0) = 1 THEN
     return f_clausulas_pyme(psseguro,pnmovimi,pcidioma,ptabla,pcduplica,pregini,pregfin,'N');
     END IF;
     --FIN BUG 0061783 GZG 30/12/2020
    --Inicio bug 37755 - YMG
    FOR i IN
    --INI BUG 0060567 GZG 20/05/2020
    (SELECT clau,linea from (SELECT clau,
      nordcla,
      ROWNUM linea
	   --FIN BUG 0060567 GZG 20/05/2020
    FROM
      (SELECT DECODE( cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || pac_clausulas.f_get_descclausulapar(cg.sclagen, psseguro, pcidioma)) clau,
        c.nordcla
      FROM clausugen cg,
        claususeg c
      WHERE cg.sclagen = c.sclagen
      AND c.sseguro    = psseguro
      AND c.nmovimi    =
        (SELECT MAX(nmovimi)
        FROM claususeg
        WHERE sseguro = psseguro
        AND nmovimi  <= pnmovimi
        )
      AND cg.cidioma = pcidioma
      UNION
      --INI BUG 0054805 GZG 11/09/2019
      SELECT REPLACE(REPLACE(REGEXP_REPLACE(tclaesp, '[[:space:]][[:space:]]*', ' '),'<br><br>','<br>'),'<br>','\par ') clau,--AITSSD-8394 GZG 09/03/2026
     -- tclaesp clau,--Bug 0039987  - YMG (08/02/2017)
      --FIN BUG 0054805 GZG 11/09/2019
        nordcla
      FROM clausuesp
      WHERE sseguro = psseguro
            --INI BUG 0061783 GZG 30/12/2020
      AND ((nmovimi   =
        (SELECT MAX(nmovimi)
        FROM clausuesp
        WHERE sseguro = psseguro
        AND nmovimi  <= pnmovimi
        AND sclagen  IS NULL
        --INI AITSSD-7537 GZG 23/01/2026 se adiciona filtro de fecha fin para que no salgan las polizas
        ) and NVL(pac_parametros.f_parproducto_n(vsproduc, 'NMOVIMI_CLAUESP'), 0) = 0 AND ffinclau IS NULL) or (nmovimi_alt   = pnmovimi and NVL(pac_parametros.f_parproducto_n(vsproduc, 'NMOVIMI_CLAUESP'), 0) = 1) )
        --FIN AITSSD-7537 GZG 23/01/2026
      --FIN BUG 0061783 GZG 30/12/2020
      AND sclagen IS NULL
      UNION
      SELECT DECODE( cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || pac_clausulas.f_get_descclausulapar(cg.sclagen, psseguro, pcidioma)) clau,
        c.nordcla
      FROM clausugen cg,
        clausuesp c,
        seguros s
      WHERE s.sseguro = c.sseguro
      AND cg.sclagen  = c.sclagen
      AND c.sseguro   = psseguro
      AND c.nmovimi   =
        (SELECT MAX(nmovimi)
        FROM clausuesp
        WHERE sseguro = psseguro
        AND nmovimi  <= pnmovimi
        AND sclagen  IS NOT NULL
        )
      AND c.sclagen IS NOT NULL
      AND cg.cidioma = pcidioma
      AND (s.cramo  <> 103
      OR ncertif     = 0)
        --AND c.nriesgo IN (0, 1) --Bug 0044677 - YMG (09/07/2018), Bug 0038779 - YMG --QT44484 Amantium 25/09/2018
      ORDER BY nordcla
      )
      --INI MPC BUG 0049242 25/01/2019 Se adiciona filtro para enviarlo en consulta se modifica 0 por pregini y 60 por pregfin
   -- WHERE nordcla BETWEEN pregini AND pregfin -- BUG 0060567 GZG 20/05/2020
      --FIN MPC BUG 0049242 25/01/2019 Se adiciona filtro para enviarlo en consulta se modifica 0 por pregini y 60 por pregfin
    --GROUP BY clau,
    --  nordcla
    ORDER BY nordcla
    )WHERE linea BETWEEN pregini AND pregfin) --BUG 0060567 GZG 20/05/2020
    LOOP
      --Fin bug 37755 - YMG
      vret := vret || i.clau || ' \par \par ';
    END LOOP;
  ELSE
    FOR i IN
    (SELECT clau,
      nordcla
    FROM
      (SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        c.nordcla
      FROM clausugen cg,
        estclaususeg c
      WHERE cg.sclagen = c.sclagen
      AND c.sseguro    = psseguro
      AND c.nmovimi    = pnmovimi
      AND cg.cidioma   = pcidioma
      UNION
      SELECT REPLACE(REPLACE(REGEXP_REPLACE(tclaesp, '[[:space:]][[:space:]]*', ' '),'<br><br>','<br>'),'<br>','\par ') clau,--AITSSD-8394 GZG 09/03/2026
        nordcla
      FROM estclausuesp
      WHERE sseguro = psseguro
      AND nmovimi   = pnmovimi
      AND sclagen  IS NULL
      UNION
      SELECT DECODE(cg.tclatex, cg.tclatit, cg.tclatit, cg.tclatit
        || '\par '
        || cg.tclatex) clau,
        c.nordcla
      FROM clausugen cg,
        estclausuesp c,
        estseguros s
      WHERE s.sseguro = c.sseguro
      AND cg.sclagen  = c.sclagen
      AND c.sseguro   = psseguro
      AND c.nmovimi   = pnmovimi
      AND c.sclagen  IS NOT NULL
      AND cg.cidioma  = pcidioma
      AND (s.cramo   <> 103
      OR ncertif      = 0)
      ORDER BY nordcla
      )
    GROUP BY clau,
      nordcla
    ORDER BY nordcla
    )
    LOOP
      vret := vret || i.clau || ' \par \par ';
    END LOOP;
  END IF;
  --INI AITSSD-1360 GZG 19/09/2022
  /*
  IF pnmovimi > 1 AND pcduplica = 0 THEN
    vret     := vret || f_descsup(psseguro, pnmovimi);
  END IF;
  */
  --FIN AITSSD-1360 GZG 19/09/2022
  RETURN f_jrep_trad_pyme(vret);
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_clausulas_pyme_descsup;
/*******************************************************************
FUNCTION f_lim_eve_vig_garan_rc_mr
Devuelve el limite por evento o vigencia de las garantias de RC
param IN psseguro  : codigo de seguro
param IN pcidioma  : codigo de idioma
param IN pnriesgo  : riesgo
param IN ptiplim   : tipo limite 1:Vigencia 2:Evento
param IN pcampo    : pcampo Indica el tipo de campo a devolver
return             : valores con los limites de las garantias de RC
BUG 0036151 - 27/07/2017 - LGG
BUG 0037907 - 29/09/2017 - LGG
*****************************************************************/
FUNCTION f_lim_eve_vig_garan_rc_mr(
    psseguro IN NUMBER,
    pcidioma IN NUMBER DEFAULT 1,
    pnriesgo IN NUMBER,
    ptiplim  IN NUMBER DEFAULT 1,
    --BUG 37907 - 06/10/2017
    pcampo   IN NUMBER,
    ptabla   IN VARCHAR2 DEFAULT 'POL', --MPC BUG 47494 08/03/2019 Se adiciona filtro.
    psproces IN NUMBER DEFAULT NULL)    --MPC BUG 47494 08/03/2019 Se adiciona filtro.
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    --
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(2000);
    v_tlinia    VARCHAR2(200);
    v_norden garanpro.norden%TYPE;
    v_cgarant garanpro.cgarant%TYPE;
    v_tpargar   VARCHAR2(200);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    --INICIO BUG 37907 - 06/10/2017
    v_tlinia2 VARCHAR2(200);
    v_tlinia3 VARCHAR2(200);
    --FIN BUG 37907 - 06/10/2017
  BEGIN
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, seguros s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    v_tconsulta := 'SELECT p.norden, p.cgarant';
    IF ptiplim   = 2 THEN
      --INICIO BUG 37907 - 06/10/2017 - LGG
      --INI BUG 47494 MPC 08/03/2019 Se modifica consulta.
      v_tconsulta := v_tconsulta || ',NVL((SELECT NVL(pgs.trespue,pgs.crespue) respue FROM pregungaranseg pgs WHERE pgs.sseguro = se.sseguro
AND pgs.cgarant = s.cgarant AND pgs.cpregun = 6137 and pgs.nriesgo = ' || pnriesgo; -- BUG 47494 MPC 07/05/2019 Se comenta codigo. || ' and pgs.nmovimi = s.nmovimi ),0) lim_evento,     ';
      IF ptabla    = 'CAR' THEN
        --
        v_tconsulta := v_tconsulta || ' AND pgs.nmovimi in (select max(nmovimi) from pregungaranseg where sseguro = pgs.sseguro and cpregun = pgs.cpregun and cgarant = pgs.cgarant) ),0) lim_evento,     '; --BUG 47494 MPC 08/05/2019 Se modifica condiciÃ³n.
        --
      ELSE
        --
        v_tconsulta := v_tconsulta || ' and pgs.nmovimi = (SELECT MAX(nmovimi) FROM pregungaranseg pgs2 WHERE pgs2.sseguro = pgs.sseguro AND pgs2.nriesgo = pgs.nriesgo AND pgs2.cpregun = pgs.cpregun and pgs2.nmovimi <= s.nmovimi)),0) lim_evento, ';--BUG 55936 28/10/2019 GZG
        --
      END IF;
      --FIN BUG 47494 MPC 08/03/2019 Se modifica consulta.
      --INICIO BUG 37907 - 06/10/2017 - LGG
    ELSIF ptiplim = 1 THEN
      /*
      v_tconsulta := v_tconsulta || ',TO_CHAR(NVL(s.icapital,0), ''999,999,999,999,999.99'') lim_vigencia';
      */
      --INICIO BUG 37907 - 06/10/2017 - LGG
      --v_tconsulta := v_tconsulta || ',TO_CHAR(NVL(s.icapital,0), ''999,999,999,999,999.99'') lim_vigencia,';
      --FIN BUG 37907 - 06/10/2017 - LGG
      --INICIO BUG 37907 - 19/10/2017 - LGG
      --INI BUG 47494 MPC 08/03/2019 Se adiciona filtro.
      IF NVL(ptabla,'POL') = 'CAR' THEN
        --
        v_tconsulta := v_tconsulta || ',TO_CHAR(NVL((SELECT NVL(icapital,0) respue FROM garancar pgs WHERE pgs.sseguro = se.sseguro AND pgs.cgarant = s.cgarant and pgs.sproces = '||psproces||' and pgs.nriesgo = ' || pnriesgo || ' ),0), ''999,999,999,999,999.99'') lim_vigencia,     ';
        --
      ELSE
        --FIN BUG 47494 MPC 08/03/2019 Se adiciona filtro.
        v_tconsulta := v_tconsulta || ',TO_CHAR(NVL((SELECT NVL(icapital,0) respue FROM garanseg pgs WHERE pgs.sseguro = se.sseguro
AND pgs.cgarant = s.cgarant and pgs.nriesgo = ' || pnriesgo || ' and pgs.nmovimi = s.nmovimi ),0), ''999,999,999,999,999.99'') lim_vigencia,     ';
      END IF; --BUG 47494 MPC 08/03/2019 Se adiciona filtro.
      --FIN BUG 37907 - 19/10/2017 - LGG
    END IF;
    --INICIO BUG 37907 - 18/10/2017 - LGG
    --INI BUG 47494 MPC 08/03/2019 Se adiciona filtro.
    IF NVL(ptabla,'POL') = 'CAR' THEN
      --
      v_tconsulta := v_tconsulta || ' g.tgarant, replace (pac_isqlfor_lcol.f_deducible_xgarantia(se.sseguro,1,1,''CAR'',g.cgarant,'||psproces||'),''"'','''') deducible';
      v_tconsulta := v_tconsulta || ' FROM garanpro p, ';
      v_tconsulta := v_tconsulta || 'garancar s, seguros se ,';
      v_tconsulta := v_tconsulta || ' garangen g ';
      v_tconsulta := v_tconsulta || ' WHERE p.cgarant = s.cgarant ';
      v_tconsulta := v_tconsulta || ' AND s.sproces = '||psproces;
      --
    ELSE
      --FIN BUG 47494 MPC 08/03/2019 Se adiciona filtro.
      v_tconsulta := v_tconsulta || ' g.tgarant,
replace (pac_isqlfor_lcol.f_deducible_xgarantia(se.sseguro,1,1,''POL'',g.cgarant),''"'','''') deducible';
      --FIN BUG 37907 - 18/10/2017 - LGG
      v_tconsulta := v_tconsulta || ' FROM garanpro p, ';
      v_tconsulta := v_tconsulta || 'garanseg s, seguros se ,';
      --INICIO BUG 37907 - 06/10/2017 - LGG
      v_tconsulta := v_tconsulta || ' garangen g ';
      --FIN BUG 37907 - 06/10/2017 - LGG
      v_tconsulta := v_tconsulta || ' WHERE ';
      v_tconsulta := v_tconsulta || ' p.cgarant = s.cgarant';
      --
    END IF; --BUG 47494 MPC 08/03/2019 Se adiciona filtro.
    --INICIO BUG 37907 - 06/10/2017 - LGG
    v_tconsulta := v_tconsulta || ' and g.cgarant     = s.cgarant ';
    v_tconsulta := v_tconsulta || ' and g.cidioma=' || pcidioma;
    --FIN BUG 37907 - 06/10/2017 - LGG
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta := v_tconsulta || ' AND se.csituac in (0,7,5,2)';
    v_tconsulta := v_tconsulta || ' AND p.CACTIVI = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' AND p.cgarpadre in (3131,3143)';
    --INI BUG 47494 MPC 08/03/2019 Se adiciona condicion.
    IF NVL(ptabla,'POL') != 'CAR' THEN
      --FIN BUG 47494 MPC 08/03/2019 Se adiciona condicion.
      v_tconsulta := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro || ')'; --BUG 47494 MPC 08/03/2019 Se comenta codigo.
    END IF;                                                                                                                   --BUG 47494 MPC 08/03/2019 Se adiciona condicion.
    v_tconsulta := v_tconsulta || ' AND se.sseguro =' || psseguro;
    v_tconsulta := v_tconsulta || ' AND s.nriesgo =' || pnriesgo;
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', p.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden, p.cgarant';
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor --INTO v_norden, v_cgarant,v_tlinia;
      --INICIO BUG 37907 - 06/10/2017 - LGG
    INTO v_norden,
      v_cgarant,
      v_tlinia,
      v_tlinia2,
      v_tlinia3;
    --FIN BUG 37907 - 06/10/2017 - LGG
    EXIT
  WHEN vr_cursor%NOTFOUND;
    --INICIO BUG 37907 - 06/10/2017 - LGG
    IF pcampo   = 2 THEN
      v_tlinia := v_tlinia2;
    END IF;
    IF pcampo   = 3 THEN
      v_tlinia := v_tlinia3;
    END IF;
    --FIN BUG 37907 - 06/10/2017 - LGG
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_lim_eve_vig_garan_rc_mr;
--FIN BUG 0037907 - 29/09/2017 - LGG
FUNCTION f_despachos_trans(
    psseguro IN NUMBER,
    pcidioma IN NUMBER DEFAULT 8,
    pnmovimi IN NUMBER DEFAULT NULL,
    pcampo   IN NUMBER,
    pfuncion IN VARCHAR2 DEFAULT 'DESPACHO',
    ptablas  IN VARCHAR2 DEFAULT 'POL')
  RETURN VARCHAR2
IS
  v_tresult VARCHAR2(32000) := '';
  v_riesgo_comp pregunsegtab.nriesgo%TYPE;
  v_cont PLS_INTEGER := 1;
  --INICIO BUG 37755 - YMG
  v_temp VARCHAR2(32000) := '';
  --FIN BUG 37755
  v_sproduc     NUMBER; -- BUG 0048545 - GZG
  v_crespue4084 NUMBER; --BUG 47494 MPC 08/05/2019 Se adiciona variable.
BEGIN
  --INICIO BUG 0048545 - GZG
  BEGIN
    SELECT sproduc INTO v_sproduc FROM seguros WHERE sseguro = psseguro;
  EXCEPTION
  WHEN OTHERS THEN
    SELECT sproduc INTO v_sproduc FROM ESTseguros WHERE sseguro = psseguro;
  END;
  --FIN BUG 0048545
  --INI BUG 47494 MPC 03/05/2019 Se adiciona filtro y codigo de validaciÃ³n.
  IF (ptablas IN ('POL','CAR')) THEN --PÃ¿Â³liza emitida
    IF ptablas = 'CAR' THEN
      --
      BEGIN
        SELECT crespue
        INTO v_crespue4084
        FROM pregunpolseg
        WHERE cpregun = 4084
        AND sseguro   = psseguro
        AND nmovimi   =
          (SELECT MAX(nmovimi)
          FROM pregunpolseg
          WHERE sseguro = psseguro
          AND cpregun   = 4084
          );
      EXCEPTION
      WHEN NO_DATA_FOUND THEN
        v_crespue4084 := 2; -- por defecto
      END;
      --
    END IF;
    --FIN BUG 47494 MPC 03/05/2019 Se adiciona filtro y codigo de validaciÃ³n.
    IF (pcampo = 1) THEN --Tipo despacho
      --INICIO BUG 0036583: YMG Se ajusta consulta de tipos de despacho
      FOR i IN
      (SELECT DISTINCT ccla3 crespue,
        nval7 trespue,
        p.nriesgo
      FROM sgt_subtabs_det d,
        pregunseg p
      WHERE d.ccla2   = p.cpregun
      AND d.ccla3     = p.crespue
      AND p.sseguro   = psseguro
      AND d.csubtabla = 70608184
      AND d.ccla1     = 70107
      AND d.ccla2     = 9318
        -- Inicio QT44484 Amantium 25/09/2018
        -- SegÃºn el comportamiento de iAxis en pruebas realizadas hasta la fecha, al ser una pregunta obligatoria
        -- se espera que estÃ© presente para cada riesgo en cada movimiento, si no estÃ¡, el riesgo fue dado de baja
        -- en dicho movimiento y no se imprimirÃ¡.
      AND p.nmovimi = NVL(pnmovimi,p.nmovimi)
        -- Fin QT44484 Amantium 25/09/2018
      ORDER BY p.nriesgo
      )
      LOOP
        --FIN BUG 0036583
        IF (pfuncion    = 'DESPACHO') THEN
          v_tresult    := v_tresult || i.nriesgo || ';' || i.trespue || ' \par ';
        ELSIF (pfuncion = 'POLIZA') THEN
          v_tresult    := v_tresult || i.trespue || ', ';
        END IF;
      END LOOP;
    ELSIF (pcampo = 2) THEN --Presupuesto anual de movilizaciÃ¿Â³n
      FOR i IN
      (SELECT DISTINCT p.crespue,
        p.nriesgo
      FROM pregunseg p
      WHERE p.cpregun = 9339
      AND p.sseguro   = psseguro
      AND p.nmovimi   = pnmovimi --15/06/2018  JPOQ  0044040 - Se aÃ±ade filtro de movimiento
      ORDER BY p.nriesgo
      )
      LOOP
        v_tresult := v_tresult || i.nriesgo || ';' || pac_isqlfor_lcol.f_imp(psseguro, i.crespue, 1) || ' \par ';
      END LOOP;
      --INI  JMC  24/01/2025   AITSSD-21522
      IF v_tresult IS NULL THEN
         v_tresult := '1;'||pac_isqlfor_lcol.f_imp(psseguro, 0, 1) || ' \par ';
      END IF;
      --FIN  JMC  24/01/2025   AITSSD-21522
    ELSIF (pcampo = 3) THEN --Tipo de mercancÃ¿Â­a
      FOR i IN              --INICIO BUG 0036583: YMG Se ajusta consulta para tipo de mercancÃ¿Â­a
      (SELECT DISTINCT d.ccla3 crespue,
        d.nval7 trespue,
        p.nriesgo
      FROM sgt_subtabs_det d,
        pregunseg p
      WHERE d.ccla2   = p.cpregun
      AND d.ccla3     = p.crespue
      AND p.sseguro   = psseguro
      AND d.csubtabla = 70608184
      AND p.cpregun   = 9319
      AND d.ccla1     = 70107
        -- Inicio QT44484 Amantium 25/09/2018
        -- SegÃºn el comportamiento de iAxis en pruebas realizadas hasta la fecha, al ser una pregunta obligatoria
        -- se espera que estÃ© presente para cada riesgo en cada movimiento, si no estÃ¡, el riesgo fue dado de baja
        -- en dicho movimiento y no se imprimirÃ¡.
      AND p.nmovimi = NVL(pnmovimi, p.nmovimi)
        -- Fin QT44484 Amantium 25/09/2018
      ORDER BY nriesgo
      ) --FIN BUG 0036583
      LOOP
        v_tresult := v_tresult || i.nriesgo || ';' || i.trespue || ' \par ';
      END LOOP;
    ELSIF (pcampo = 4) THEN --Estado de mercancÃ¿Â­a (Nueva, Usada, No aplica)
      FOR i IN              --INICIO BUG 0036583: YMG Se ajusta consulta para estado de mercancÃ¿Â­a
      (SELECT DISTINCT d.ccla3 crespue,
        d.nval7 trespue,
        p.nriesgo
      FROM sgt_subtabs_det d,
        pregunseg p
      WHERE d.ccla2   = p.cpregun
      AND d.ccla3     = p.crespue
      AND p.sseguro   = psseguro
      AND d.csubtabla = 70608214
      AND p.cpregun   = 9340
        -- Inicio QT44484 Amantium 25/09/2018
        -- SegÃºn el comportamiento de iAxis en pruebas realizadas hasta la fecha, al ser una pregunta obligatoria
        -- se espera que estÃ© presente para cada riesgo en cada movimiento, si no estÃ¡, el riesgo fue dado de baja
        -- en dicho movimiento y no se imprimirÃ¡.
      AND p.nmovimi = NVL(pnmovimi, p.nmovimi)
        -- Fin QT44484 Amantium 25/09/2018
      ORDER BY nriesgo
      ) --FIN BUG 0036583
      LOOP
        v_tresult := v_tresult || i.nriesgo || ';' || i.trespue || ' \par ';
      END LOOP;
    ELSIF (pcampo = 5) THEN --Tipo de trayecto
      FOR i IN
      (SELECT DISTINCT p.nriesgo,
        r.trespue
      FROM respuestas_dep r,
        pregunseg p
      WHERE p.cpregun = r.cpregun
      AND p.crespue   = r.crespue
      AND p.cpregun   = 9320
      AND p.sseguro   = psseguro
      AND r.cidioma   = pcidioma
        -- Inicio QT44484 Amantium 25/09/2018
        -- SegÃºn el comportamiento de iAxis en pruebas realizadas hasta la fecha, al ser una pregunta obligatoria
        -- se espera que estÃ© presente para cada riesgo en cada movimiento, si no estÃ¡, el riesgo fue dado de baja
        -- en dicho movimiento y no se imprimirÃ¡.
      AND p.nmovimi = NVL(pnmovimi, p.nmovimi)
        -- Fin QT44484 Amantium 25/09/2018
      ORDER BY p.nriesgo
      )
      LOOP
        v_tresult := v_tresult || i.nriesgo || ';' || i.trespue || ' \par ';
      END LOOP;
    ELSIF (pcampo = 6) THEN --PaÃ¿Â­s orÃ¿Â­gen
      FOR i IN
      (SELECT DISTINCT p.nriesgo,
        r.trespue
      FROM respuestas_dep r,
        pregunseg p
      WHERE p.cpregun = r.cpregun
      AND p.crespue   = r.crespue
      AND p.cpregun   = 9363
      AND p.sseguro   = psseguro
      AND r.cidioma   = pcidioma
        -- Inicio QT44484 Amantium 25/09/2018
        -- SegÃºn el comportamiento de iAxis en pruebas realizadas hasta la fecha, al ser una pregunta obligatoria
        -- se espera que estÃ© presente para cada riesgo en cada movimiento, si no estÃ¡, el riesgo fue dado de baja
        -- en dicho movimiento y no se imprimirÃ¡.
      AND p.nmovimi = NVL(pnmovimi, p.nmovimi)
        -- Fin QT44484 Amantium 25/09/2018
      ORDER BY p.nriesgo
      )
      LOOP
        v_tresult := v_tresult || i.nriesgo || ';' || i.trespue || ' \par ';
      END LOOP;
    ELSIF (pcampo = 7) THEN --Ciudad orÃ¿Â­gen
      FOR i IN
      (SELECT DISTINCT p.nriesgo,
        r.trespue,
        r.crespuedep
      FROM respuestas_dep r,
        pregunseg p,
        pregunseg p2
      WHERE p.cpregun = r.cpregun
      AND p.crespue   = r.crespue
      AND p2.crespue  = r.crespuedep
      AND p2.sseguro  = p.sseguro
      AND p2.nriesgo  = p.nriesgo
      AND p2.nmovimi  = p.nmovimi
      AND p2.cpregun  = 9363 --Pregunta dependiente (PAÃ¿ÂS)
      AND p.cpregun   = 9364
      AND p.sseguro   = psseguro
      AND r.cidioma   = pcidioma
        -- Inicio QT44484 Amantium 25/09/2018
        -- SegÃºn el comportamiento de iAxis en pruebas realizadas hasta la fecha, al ser una pregunta obligatoria
        -- se espera que estÃ© presente para cada riesgo en cada movimiento, si no estÃ¡, el riesgo fue dado de baja
        -- en dicho movimiento y no se imprimirÃ¡.
      AND p.nmovimi = NVL(pnmovimi, p.nmovimi)
        -- Fin QT44484 Amantium 25/09/2018
      ORDER BY p.nriesgo
      )
      LOOP
        v_tresult := v_tresult || i.nriesgo || ';' || i.trespue || ' \par ';
      END LOOP;
    ELSIF (pcampo = 8) THEN --PaÃ¿Â­s destino
      FOR i IN
      (SELECT DISTINCT p.nriesgo,
        r.trespue
      FROM respuestas_dep r,
        pregunseg p
      WHERE p.cpregun = r.cpregun
      AND p.crespue   = r.crespue
      AND p.cpregun   = 9925
      AND p.sseguro   = psseguro
      AND r.cidioma   = pcidioma
        -- Inicio QT44484 Amantium 25/09/2018
        -- SegÃºn el comportamiento de iAxis en pruebas realizadas hasta la fecha, al ser una pregunta obligatoria
        -- se espera que estÃ© presente para cada riesgo en cada movimiento, si no estÃ¡, el riesgo fue dado de baja
        -- en dicho movimiento y no se imprimirÃ¡.
      AND p.nmovimi = NVL(pnmovimi, p.nmovimi)
        -- Fin QT44484 Amantium 25/09/2018
      ORDER BY p.nriesgo
      )
      LOOP
        v_tresult := v_tresult || i.nriesgo || ';' || i.trespue || ' \par ';
      END LOOP;
    ELSIF (pcampo = 9) THEN --Ciudad destino
      FOR i IN
      (SELECT DISTINCT p.nriesgo,
        r.trespue,
        r.crespuedep
      FROM respuestas_dep r,
        pregunseg p,
        pregunseg p2
      WHERE p.cpregun = r.cpregun
      AND p.crespue   = r.crespue
      AND p2.crespue  = r.crespuedep
      AND p2.sseguro  = p.sseguro
      AND p2.nriesgo  = p.nriesgo
      AND p2.nmovimi  = p.nmovimi
      AND p2.cpregun  = 9925 --Pregunta dependiente (PAÃ¿ÂS)
      AND p.cpregun   = 9926
      AND p.sseguro   = psseguro
      AND r.cidioma   = pcidioma
        -- Inicio QT44484 Amantium 25/09/2018
        -- SegÃºn el comportamiento de iAxis en pruebas realizadas hasta la fecha, al ser una pregunta obligatoria
        -- se espera que estÃ© presente para cada riesgo en cada movimiento, si no estÃ¡, el riesgo fue dado de baja
        -- en dicho movimiento y no se imprimirÃ¡.
      AND p.nmovimi = NVL(pnmovimi, p.nmovimi)
        -- Fin QT44484 Amantium 25/09/2018
      ORDER BY p.nriesgo
      )
      LOOP
        v_tresult := v_tresult || i.nriesgo || ';' || i.trespue || ' \par ';
      END LOOP;
    ELSIF (pcampo = 10) THEN --Tasa
      --INICIO BUG 37755 - YMG
      --Validar si la poliza se encuentra vencida
      BEGIN
        SELECT ps.crespue
        INTO v_temp
        FROM pregunpolseg ps
        WHERE ps.cpregun = 4084
        AND ps.sseguro   = psseguro
          -- Inicio QT44484 Amantium 25/09/2018
        AND ps.nmovimi = NVL(pnmovimi,
          (SELECT MAX(nmovimi)
          FROM pregunpolseg
          WHERE cpregun = 4084
          AND sseguro   = psseguro
          ))
          -- Fin QT44484 Amantium 25/09/2018
          ;
      EXCEPTION
      WHEN NO_DATA_FOUND THEN
        v_temp := 2;
      END;
      IF (v_temp = 1) THEN --Si es vencida (crespue: 1)
        FOR i IN
        --INI BUG 51633 MPC 14/05/2019 Se modifica cursor
        /* (SELECT ri.nriesgo,
        pr.crespue,
        pr.nmovimi
        FROM riesgos ri,
        pregunseg pr
        WHERE ri.sseguro  = pr.sseguro(+)
        AND ri.nriesgo    = pr.nriesgo(+)
        AND pr.cpregun(+) = 4090
        AND ri.sseguro    = psseguro
        -- Inicio QT44484 Amantium 25/09/2018
        AND NVL(pr.nmovimi, 0) = NVL(pnmovimi, NVL(
        (SELECT MAX(nmovimi)
        FROM pregunseg
        WHERE cpregun = 4090
        AND sseguro   = psseguro
        ), 0))
        -- Fin QT44484 Amantium 25/09/2018
        )*/
        (
        SELECT ri.nriesgo,
          pr.crespue,
          pr.nmovimi
        FROM riesgos ri
        LEFT JOIN pregunseg pr
        ON ri.sseguro    = pr.sseguro
        AND ri.nriesgo   = pr.nriesgo
        AND pr.cpregun   = 4090
        WHERE ri.sseguro = psseguro
        AND ri.fanulac  IS NULL
        AND (pr.nmovimi  =
          (SELECT MAX(nmovimi)
          FROM pregunseg
          WHERE cpregun = 4090
          AND sseguro   = psseguro
          AND nmovimi  <= NVL(pnmovimi,0)
          )
        OR ( pr.nmovimi IS NULL
