        DECODE(e.crespue, NULL, det.nval7, det.nval7
        || ' ('
        || e.crespue
        || '%)') tgarant
      FROM estgaranseg g,
        estpregungaranseg e,
        garangen gr,
        garanpro p,
        sgt_subtabs_det det
      WHERE g.cgarant   = p.cgarant
      AND det.csubtabla = 700000234
      AND DET.CCLA1     = v_sproduc
      AND DET.CCLA2     = g.CGARANT
      AND g.cgarant     = gr.cgarant
      AND g.sseguro     = e.sseguro(+)
      AND g.nriesgo     = e.nriesgo(+)
      AND g.nmovimi     = e.nmovimi(+)
      AND g.cgarant     = e.cgarant(+)
      AND e.cpregun(+) IN (9341, 9342) --Porcentaje de lucro cesante o gastos adicionales
      AND gr.cidioma    = pcidioma
      AND g.sseguro     = psseguro
      AND p.cgarpadre  IS NULL
      AND p.sproduc     = 70107
      AND g.cobliga     = 1
      ORDER BY g.nriesgo,
        p.norden
      ) --FIN BUG 36583
      LOOP
        --ValidaciÃ¿Â¿Ã¿Â³n para dividir lÃ¿Â¿Ã¿Â­nea Ã¿Â¿Ã¿Âºnicamente cuando el riesgo sea diferente
        IF (NVL(v_riesgo_comp, i.nriesgo) = i.nriesgo) THEN
          v_riesgo_comp                  := i.nriesgo;
          v_tresult                      := v_tresult || i.tgarant || ';';
        ELSE
          --Genera salto de lÃ¿Â¿Ã¿Â­nea solo una vez por registro
          v_cont       := 1;
          WHILE (v_cont = 1)
          LOOP
            v_tresult := v_tresult || ' \par ';
            v_cont    := 0;
          END LOOP;
          v_riesgo_comp := i.nriesgo;
          v_tresult     := v_tresult || i.tgarant || ';';
        END IF;
      END LOOP;
      ----FIN CALL 12/08/2019 0054010: Amparos Transporte ----------------------------------------
    END IF;
  END IF;
  RETURN f_jrep_trad(v_tresult);
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_despachos_trans;
FUNCTION f_inf_pol_trans(
    psseguro IN NUMBER,
    pcidioma IN NUMBER DEFAULT 8,
    pnmovimi IN NUMBER DEFAULT NULL,
    pcampo   IN NUMBER,
    ptablas  IN VARCHAR2 DEFAULT 'POL',
    pnrecibo IN NUMBER DEFAULT NULL, -- QT44484 Amantium 25/09/2018
    psproces IN NUMBER DEFAULT NULL) --BUG 47494 MPC 08/03/2019 Se adiciona parametro de entrada.
  RETURN VARCHAR2
IS
  v_tresult VARCHAR2(32000) := '';
  v_temp    VARCHAR2(200)   := '';
  v_cont PLS_INTEGER        := 0;
  v_crespue4084 NUMBER; --BUG 47494 MPC 06/05/2019 Se adiciona variable.
BEGIN
  IF (ptablas IN ('POL','CAR')) THEN --PÃ¿Â³liza emitida --BUG 47494 MPC 08/03/2019 Se modifica condiciÃ³n para agregar tablas CAR.
    IF (pcampo = 1) THEN             --Sistema de pago
      SELECT DISTINCT res.trespue
      INTO v_tresult
      FROM pregunpolseg pre,
        respuestas res
      WHERE pre.cpregun = res.cpregun
      AND pre.crespue   = res.crespue
      AND res.cidioma   = pcidioma
      AND pre.sseguro   = psseguro
      AND pre.cpregun   = 4084;
    ELSIF (pcampo       = 2) THEN --Total a pagar (Incluye asistencia legal trans.)
      --INICIO BUG 37755 - YMG
      --INI BUG 47494 MPC 08/03/2019 Se adiciona condicion.
      IF ptablas = 'CAR' THEN
        --INI BUG 47494 MPC 06/05/2019 Se adiciona condiciÃ³n para vencidos previos
        BEGIN
          SELECT crespue
          INTO v_crespue4084
          FROM pregunpolseg
          WHERE cpregun = 4084
          AND sseguro   = psseguro
          AND nmovimi   =
            (SELECT MAX(nmovimi)
            FROM pregunpolseg
            WHERE sseguro = psseguro
            AND cpregun   = 4084
            );
        EXCEPTION
        WHEN NO_DATA_FOUND THEN
          v_crespue4084 := 2; -- por defecto
        END;
        IF v_crespue4084 = 1 THEN
          v_tresult     := 'Cobro con base en los despachos';
        ELSE
          --FIN BUG 47494 MPC 06/05/2019 Se adiciona condiciÃ³n para vencidos previos
          SELECT pac_isqlfor_lcol.f_imp(psseguro, SUM(campo), 1)
          INTO v_tresult
          FROM
            (SELECT SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * itotalr) campo
            FROM vdetreciboscar_monpol v,
              reciboscar r
            WHERE v.nrecibo = pnrecibo
            AND r.sproces   = psproces
            AND r.sproces   = v.sproces
            AND r.nrecibo   = v.nrecibo
            );
          v_tresult := '$ '||v_tresult; -- BUG 47494 MPC 06/05/2019 Se adiciona condiciÃ³n para vencidos previos
        END IF;                         -- BUG 47494 MPC 06/05/2019 Se adiciona condiciÃ³n para vencidos previos
      ELSE
        --FIN BUG 47494 MPC 08/03/2019 Se adiciona condicion.
        SELECT pac_isqlfor_lcol.f_imp(psseguro, SUM(campo), 1)
        INTO v_tresult
        FROM
          (SELECT SUM(DECODE(r.ctiprec, 9, -1, 13, 0, 15, 0, 1) * itotalr) campo
          FROM vdetrecibos_monpol v,
            recibos r
            -- Inicio QT44484 Amantium 25/09/2018
          WHERE v.nrecibo =
            --(SELECT MAX(nrecibo) FROM recibos WHERE sseguro = psseguro
            NVL(pnrecibo, f_recibo_mov(psseguro, pnmovimi))
            -- Fin QT44484 Amantium 25/09/2018
          AND r.nrecibo = v.nrecibo
          );
        --FIN BUG 37755
      END IF;               --BUG 47494 MPC 08/03/2019 Se adiciona condicion.
    ELSIF (pcampo = 3) THEN --PerÃ¿Â­odo de ajuste
      SELECT DISTINCT res.trespue
      INTO v_tresult
      FROM pregunpolseg pre,
        respuestas res
      WHERE pre.cpregun = res.cpregun
      AND pre.crespue   = res.crespue
      AND res.cidioma   = pcidioma
      AND pre.sseguro   = psseguro
      AND pre.cpregun   = 9345;
    ELSIF (pcampo       = 4) THEN --Prima mÃ¿Â­nima de ajuste
      --INICIO BUG 0036583: YMG - Se agrega identificador de pregunta 6209
      SELECT DISTINCT pac_isqlfor_lcol.f_imp(psseguro, crespue, 1)
      INTO v_tresult
      FROM pregunpolseg pre
      WHERE pre.sseguro = psseguro
      AND pre.cpregun  IN (6209, 9334);
      --FIN BUG 0036583
    ELSIF (pcampo = 5) THEN --CÃ¿Â³digo de actividad
      SELECT par.tvalpar
      INTO v_tresult
      FROM per_parpersonas per,
        detparam par,
        tomadores tom
      WHERE per.sperson = tom.sperson
      AND per.nvalpar   = par.cvalpar
      AND par.cidioma   = pcidioma
      AND tom.sseguro   = psseguro
      AND per.cparam    = 'CCIIU';
    ELSIF (pcampo IN (6, 7, 8)) THEN --PaÃ¿Â­s, Departamento, Ciudad
      SELECT INITCAP(pa.tpais)
        || ';'
        || INITCAP(po.tpoblac)
        || ';'
        || INITCAP(pv.tprovin)
      INTO v_temp
      FROM tomadores tm,
        per_direcciones pr,
        per_detper pd,
        provincias pv,
        poblaciones po,
        paises pa
      WHERE tm.sseguro = psseguro
      AND tm.sperson   = pd.sperson
      AND tm.sperson   = pr.sperson
      --INI  JMC  24/01/2025   AITSSD-21522
      AND tm.cdomici   = pr.cdomici
      --FIN  JMC  24/01/2025   AITSSD-21522
      AND pr.cprovin   = pv.cprovin
      AND pd.cpais     = pv.cpais
      AND pd.cpais     = pa.cpais
      AND pr.cpoblac   = po.cpoblac
      AND pr.cprovin   = po.cprovin;
      IF (pcampo       = 6) THEN --PaÃ¿Â­s
        v_tresult     := SUBSTR(v_temp, 1, INSTR(v_temp, ';', 1, 1) - 1);
      ELSIF (pcampo    = 7) THEN --Departamento
        v_tresult     := SUBSTR(v_temp, INSTR(v_temp, ';', 1, 1) + 1, INSTR(v_temp, ';', INSTR(v_temp, ';', 1, 1) + 1, 1) - INSTR(v_temp, ';', 1, 1) - 1);
      ELSIF (pcampo    = 8) THEN --Ciudad
        v_tresult     := SUBSTR(v_temp, INSTR(v_temp, ';', 1, 2) + 1, LENGTH(v_temp));
      END IF;
    ELSIF (pcampo = 9) THEN --LÃ¿Â­mite agregado anual
      SELECT DISTINCT pac_isqlfor_lcol.f_imp(psseguro, crespue, 1)
      INTO v_tresult
      FROM pregunpolseg
      WHERE sseguro = psseguro
      AND cpregun   = 9338;
    ELSIF (pcampo IN (10, 11, 12)) THEN --INCOTERM
      IF (pcampo = 10) THEN             --INCOTERM 1
        SELECT DISTINCT r.trespue
        INTO v_tresult
        FROM pregunpolseg p,
          respuestas r,
          preguntas pr
        WHERE p.cpregun = r.cpregun
        AND p.crespue   = r.crespue
        AND p.cpregun   = pr.cpregun
        AND r.cidioma   = pr.cidioma
        AND r.cidioma   = pcidioma
        AND p.sseguro   = psseguro
        AND p.cpregun  IN (9315);
      ELSIF (pcampo     = 11) THEN --INCOTERM 2
        SELECT DISTINCT r.trespue
        INTO v_tresult
        FROM pregunpolseg p,
          respuestas r,
          preguntas pr
        WHERE p.cpregun = r.cpregun
        AND p.crespue   = r.crespue
        AND p.cpregun   = pr.cpregun
        AND r.cidioma   = pr.cidioma
        AND r.cidioma   = pcidioma
        AND p.sseguro   = psseguro
        AND p.cpregun  IN (9316);
      ELSIF (pcampo     = 12) THEN --INCOTERM 3
        SELECT DISTINCT r.trespue
        INTO v_tresult
        FROM pregunpolseg p,
          respuestas r,
          preguntas pr
        WHERE p.cpregun = r.cpregun
        AND p.crespue   = r.crespue
        AND p.cpregun   = pr.cpregun
        AND r.cidioma   = pr.cidioma
        AND r.cidioma   = pcidioma
        AND p.sseguro   = psseguro
        AND p.cpregun  IN (9317);
      END IF;
    ELSIF (pcampo = 13) THEN --CÃ¿Â³digo de modalidad
      SELECT DISTINCT r.crespue
      INTO v_tresult
      FROM pregunpolseg p,
        respuestas r,
        preguntas pr
      WHERE p.cpregun                                                                                                         = r.cpregun
      AND p.crespue                                                                                                           = r.crespue
      AND p.cpregun                                                                                                           = pr.cpregun
      AND r.cidioma                                                                                                           = pr.cidioma
      AND r.cidioma                                                                                                           = pcidioma
      AND p.sseguro                                                                                                           = psseguro
      AND p.cpregun                                                                                                          IN (9343);
      --INI  JMC  24/01/2025   AITSSD-21522
      IF v_tresult = '4' THEN
         v_tresult := '1'; --Para que en la plantilla muestre los INCOTERM, solo los muestra si modalidad=1
      END IF;
      --FIN  JMC  24/01/2025   AITSSD-21522
    ELSIF (pcampo                                                                                                             = 14) THEN --TÃ¿Â­tulo de reporte de acuerdo a la modadlidad
      IF (f_inf_pol_trans(psseguro => psseguro, pcidioma => pcidioma, pnmovimi => pnmovimi, pcampo => 13, ptablas => ptablas) = 1) THEN  --AutomÃ¿Â¡tica de mercancÃ¿Â­as (1)
        SELECT REPLACE(cclausu, 'Version Febrero 2017', '')
        INTO v_tresult
        FROM condicionadoprod c
        WHERE c.sproduc                                                                                                          = 70107
        AND c.ccondicio                                                                                                          = 604922;
      ELSIF (f_inf_pol_trans(psseguro => psseguro, pcidioma => pcidioma, pnmovimi => pnmovimi, pcampo => 13, ptablas => ptablas) = 2) THEN --AutomÃ¿Â¡tica de valores (2)
        SELECT REPLACE(cclausu, 'Version Febrero 2017', '')
        INTO v_tresult
        FROM condicionadoprod c
        WHERE c.sproduc                                                                                                          = 70107
        AND c.ccondicio                                                                                                          = 604923;
      ELSIF (f_inf_pol_trans(psseguro => psseguro, pcidioma => pcidioma, pnmovimi => pnmovimi, pcampo => 13, ptablas => ptablas) = 3) THEN --EspecÃ¿Â­fica de mercancÃ¿Â­as (3)
        SELECT REPLACE(cclausu, 'Version Febrero 2017', '')
        INTO v_tresult
