      AND p.sseguro   = psseguro
      AND r.cidioma   = pcidioma
      ORDER BY p.nriesgo
      )
      LOOP
        IF (i.crespue     IN (1, 2)) THEN
          v_cont := v_cont + 1;
        END IF;
      END LOOP;
      v_tresult := v_cont;
    END IF;
  ELSE                   --SimulaciÃ¿Â³n / EmisiÃ¿Â³n
    IF (pcampo = 1) THEN --Sistema de pago
      SELECT DISTINCT res.trespue
      INTO v_tresult
      FROM estpregunpolseg pre,
