        respuestas res
      WHERE pre.cpregun = res.cpregun
      AND pre.crespue   = res.crespue
      AND res.cidioma   = pcidioma
      AND pre.sseguro   = psseguro
      AND pre.cpregun   = 9345;
    ELSIF (pcampo       = 4) THEN --Prima mÃ¿Â­nima de ajuste
      --INICIO BUG 0036583: YMG - Se agrega identificador de pregunta 6209
      SELECT DISTINCT crespue
      INTO v_tresult
      FROM estpregunpolseg pre
      WHERE pre.sseguro = psseguro
      AND pre.cpregun  IN (6209, 9334);
      --FIN BUG 0036583
    ELSIF (pcampo = 5) THEN --CÃ¿Â³digo de actividad
      SELECT par.tvalpar
      INTO v_tresult
      FROM estper_parpersonas per,
        detparam par,
        esttomadores tom
      WHERE per.sperson = tom.sperson
      AND per.nvalpar   = par.cvalpar
      AND par.cidioma   = pcidioma
      AND tom.sseguro   = psseguro
      AND per.cparam    = 'CCIIU';
    ELSIF (pcampo IN (6, 7, 8)) THEN --PaÃ¿Â­s, Departamento, Ciudad
      SELECT INITCAP(pa.tpais)
        || ';'
        || INITCAP(po.tpoblac)
        || ';'
        || INITCAP(pv.tprovin)
      INTO v_temp
      FROM esttomadores tm,
        estper_direcciones pr,
        estper_detper pd,
        provincias pv,
        poblaciones po,
        paises pa
      WHERE tm.sseguro = psseguro
      AND tm.sperson   = pd.sperson
      AND tm.sperson   = pr.sperson
      AND pr.cprovin   = pv.cprovin
      AND pd.cpais     = pv.cpais
      AND pd.cpais     = pa.cpais
      AND pr.cpoblac   = po.cpoblac
      AND pr.cprovin   = po.cprovin;
      IF (pcampo       = 6) THEN --PaÃ¿Â­s
        v_tresult     := SUBSTR(v_temp, 1, INSTR(v_temp, ';', 1, 1) - 1);
      ELSIF (pcampo    = 7) THEN --Departamento
        v_tresult     := SUBSTR(v_temp, INSTR(v_temp, ';', 1, 1) + 1, INSTR(v_temp, ';', INSTR(v_temp, ';', 1, 1) + 1, 1) - INSTR(v_temp, ';', 1, 1) - 1);
      ELSIF (pcampo    = 8) THEN --Ciudad
        v_tresult     := SUBSTR(v_temp, INSTR(v_temp, ';', 1, 2) + 1, LENGTH(v_temp));
      END IF;
    ELSIF (pcampo = 9) THEN --LÃ¿Â­mite agregado anual
      SELECT DISTINCT pac_isqlfor_lcol.fu_formato(p_valor => crespue, p_dg_dec => 0)
      INTO v_tresult
      FROM estpregunpolseg
      WHERE sseguro = psseguro
      AND cpregun   = 9338;
    ELSIF (pcampo IN (10, 11, 12)) THEN --INCOTERM
      IF (pcampo = 10) THEN             --INCOTERM 1
        SELECT DISTINCT r.trespue
        INTO v_tresult
        FROM estpregunpolseg p,
          respuestas r,
          preguntas pr
        WHERE p.cpregun = r.cpregun
        AND p.crespue   = r.crespue
        AND p.cpregun   = pr.cpregun
        AND r.cidioma   = pr.cidioma
        AND r.cidioma   = pcidioma
        AND p.sseguro   = psseguro
        AND p.cpregun  IN (9315);
      ELSIF (pcampo     = 11) THEN --INCOTERM 2
        SELECT DISTINCT r.trespue
        INTO v_tresult
        FROM estpregunpolseg p,
          respuestas r,
          preguntas pr
        WHERE p.cpregun = r.cpregun
        AND p.crespue   = r.crespue
        AND p.cpregun   = pr.cpregun
        AND r.cidioma   = pr.cidioma
        AND r.cidioma   = pcidioma
        AND p.sseguro   = psseguro
        AND p.cpregun  IN (9316);
      ELSIF (pcampo     = 12) THEN --INCOTERM 3
        SELECT DISTINCT r.trespue
        INTO v_tresult
        FROM estpregunpolseg p,
          respuestas r,
          preguntas pr
        WHERE p.cpregun = r.cpregun
        AND p.crespue   = r.crespue
        AND p.cpregun   = pr.cpregun
        AND r.cidioma   = pr.cidioma
        AND r.cidioma   = pcidioma
        AND p.sseguro   = psseguro
        AND p.cpregun  IN (9317);
      END IF;
    ELSIF (pcampo = 13) THEN --CÃ¿Â³digo de modalidad
      SELECT DISTINCT r.crespue
      INTO v_tresult
      FROM estpregunpolseg p,
        respuestas r,
        preguntas pr
      WHERE p.cpregun                                                                                                         = r.cpregun
      AND p.crespue                                                                                                           = r.crespue
      AND p.cpregun                                                                                                           = pr.cpregun
      AND r.cidioma                                                                                                           = pr.cidioma
      AND r.cidioma                                                                                                           = pcidioma
      AND p.sseguro                                                                                                           = psseguro
      AND p.cpregun                                                                                                          IN (9343);
    ELSIF (pcampo                                                                                                             = 14) THEN --TÃ¿Â­tulo de reporte de acuerdo a la modadlidad
      IF (f_inf_pol_trans(psseguro => psseguro, pcidioma => pcidioma, pnmovimi => pnmovimi, pcampo => 13, ptablas => ptablas) = 1) THEN  --AutomÃ¿Â¡tica de mercancÃ¿Â­as (1)
        SELECT REPLACE(cclausu, 'Version Febrero 2017', '')
        INTO v_tresult
        FROM condicionadoprod c
        WHERE c.sproduc                                                                                                          = 70107
        AND c.ccondicio                                                                                                          = 604922;
      ELSIF (f_inf_pol_trans(psseguro => psseguro, pcidioma => pcidioma, pnmovimi => pnmovimi, pcampo => 13, ptablas => ptablas) = 2) THEN --AutomÃ¿Â¡tica de valores (2)
        SELECT REPLACE(cclausu, 'Version Febrero 2017', '')
        INTO v_tresult
        FROM condicionadoprod c
        WHERE c.sproduc                                                                                                          = 70107
        AND c.ccondicio                                                                                                          = 604923;
      ELSIF (f_inf_pol_trans(psseguro => psseguro, pcidioma => pcidioma, pnmovimi => pnmovimi, pcampo => 13, ptablas => ptablas) = 3) THEN --EspecÃ¿Â­fica de mercancÃ¿Â­as (3)
        SELECT REPLACE(cclausu, 'Version Febrero 2017', '')
        INTO v_tresult
        FROM condicionadoprod c
        WHERE c.sproduc = 70107
        AND c.ccondicio = 604924;
      END IF;
    ELSIF (pcampo = 15) THEN --Validar si los INCOTERMS deben mostrarse en el PDF
      FOR i IN
      (SELECT DISTINCT p.nriesgo,
        r.crespue,
        r.trespue
      FROM respuestas_dep r,
        estpregunseg p
      WHERE p.cpregun = r.cpregun
      AND p.crespue   = r.crespue
      AND p.cpregun   = 9318
      AND p.sseguro   = psseguro
      AND r.cidioma   = pcidioma
      ORDER BY p.nriesgo
      )
      LOOP
        IF (i.crespue     IN (1, 2)) THEN
          v_cont := v_cont + 1;
        END IF;
      END LOOP;
      v_tresult := TO_CHAR(v_cont);
    END IF;
  END IF;
  RETURN v_tresult;
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_inf_pol_trans;
FUNCTION f_inf_recibos_trans(
    psseguro IN NUMBER,
    pcidioma IN NUMBER DEFAULT 8,
    pnmovimi IN NUMBER DEFAULT NULL,
    pcmotmov IN NUMBER DEFAULT 0,
    pcampo   IN NUMBER,
    ptablas  IN VARCHAR2 DEFAULT 'POL', -- inicio ARM 0046063
    pnrecibo IN NUMBER DEFAULT NULL,    -- QT44484 Amantium 25/09/2018
    psproces IN NUMBER DEFAULT NULL)    --BUG 47494 MPC 08/03/2019 Se adiciona parametro de entrada.
  -- fin ARM 0046063
  RETURN VARCHAR2
IS
  v_tresult     VARCHAR2(32000) := '';
  -- INICIO 11/02/2020 0058569: validación de liquidación en PDF póliza de transporte TRM 283192
  v_tresult_lega  detrecibos.iconcep%TYPE := 0;
  -- FIN 11/02/2020 0058569: validación de liquidación en PDF póliza de transporte TRM 283192
  v_crespue4084 NUMBER; --INI BUG 47494 MPC 03/05/2019 Se crea variable.
BEGIN
  IF (ptablas IN ('POL','CAR')) THEN --PÃ¿Â³liza emitida --BUG 47494 MPC 08/03/2019
    --INICIO BUG 0036809: YMG
    --INI BUG 47494 MPC 03/05/2019 Se adiciona consulta.
    BEGIN
      SELECT crespue
      INTO v_crespue4084
      FROM pregunpolseg
      WHERE cpregun = 4084
      AND sseguro   = psseguro
      AND nmovimi   =
        (SELECT MAX(nmovimi)
        FROM pregunpolseg
        WHERE sseguro = psseguro
        AND cpregun   = 4084
        );
    EXCEPTION
    WHEN NO_DATA_FOUND THEN
      v_crespue4084 := 2; -- por defecto
    END;
    --FIN BUG 47494 MPC 03/05/2019 Se adiciona consulta.
    IF (pcampo = 0) THEN --NÃ¿Âºmero de recibo
