      AND r.sseguro   = psseguro
      AND r.nrecibo   = pnrecibo;
      --FIN BUG MPC 49470 20/02/2019 Se adiciona DECODE debido a que el valor debe ser negativo si es un extorno
    END IF;
    -- FIN ARM 0046063
  ELSE --SimulaciÃ¿Â³n / EmisiÃ¿Â³n
    --INICIO BUG 0036809: YMG
    IF (pcampo = 0) THEN --NÃ¿Âºmero de recibo
      SELECT r.nrecibo
      INTO v_tresult
      FROM recibos r
      WHERE r.sseguro = psseguro
      AND r.nmovimi   =
        (SELECT MAX(nmovimi) FROM recibos WHERE sseguro = psseguro
        );
    ELSIF (pcampo = 1) THEN --Fecha de cobro
	  -- INI AMANTIUM 30/12/2024 AITSSD21666 Se modifica formateo de fechas.
      SELECT PAC_ISQLFOR_LCOL.F_FECHA(r.femisio) --TO_CHAR(r.femisio, 'YYYY-MON-DD')
	  -- FIN AMANTIUM 30/12/2024 AITSSD21666 Se modifica formateo de fechas.
      INTO v_tresult
      FROM recibos r
      WHERE r.sseguro = psseguro
      AND r.nmovimi   =
        (SELECT MAX(nmovimi) FROM recibos WHERE sseguro = psseguro
        );
    ELSIF (pcampo = 2) THEN --Fecha inicio de cobro
	  -- INI AMANTIUM 30/12/2024 AITSSD21666 Se modifica formateo de fechas.
      SELECT PAC_ISQLFOR_LCOL.F_FECHA(r.fefecto) --TO_CHAR(r.fefecto, 'YYYY-MON-DD')
	  -- FIN AMANTIUM 30/12/2024 AITSSD21666 Se modifica formateo de fechas.
      INTO v_tresult
      FROM recibos r
      WHERE r.sseguro = psseguro
      AND r.nmovimi   =
        (SELECT MAX(nmovimi) FROM recibos WHERE sseguro = psseguro
        );
    ELSIF (pcampo = 3) THEN --Fecha fin de cobro
	  -- INI AMANTIUM 30/12/2024 AITSSD21666 Se modifica formateo de fechas.
      SELECT PAC_ISQLFOR_LCOL.F_FECHA(r.fvencim) --TO_CHAR(r.fvencim, 'YYYY-MON-DD')
	  -- FIN AMANTIUM 30/12/2024 AITSSD21666 Se modifica formateo de fechas.
      INTO v_tresult
      FROM recibos r
      WHERE r.sseguro = psseguro
      AND r.nmovimi   =
        (SELECT MAX(nmovimi) FROM recibos WHERE sseguro = psseguro
        );
      --FIN BUG 0036809: YMG
    ELSIF (pcampo = 4) THEN --Fecha lÃ¿Â­mite de pago
	  -- INI AMANTIUM 30/12/2024 AITSSD21666 Se modifica formateo de fechas.
      v_tresult  := PAC_ISQLFOR_LCOL.F_FECHA(pac_isqlfor_lcol.f_flimitepag(psseguro => psseguro, pnmovimi => pnmovimi, pcmotmov => pcmotmov));
      -- FIN AMANTIUM 30/12/2024 AITSSD21666 Se modifica formateo de fechas.
    ELSIF (pcampo = 5) THEN --Prima neta vigencia
      SELECT pac_isqlfor_lcol.fu_formato(p_valor => SUM(e.ipritar), p_dg_dec => 0)
      INTO v_tresult
      FROM estprimasgaranseg e
      WHERE e.sseguro = psseguro;
    ELSIF (pcampo     = 6) THEN --Asistencia legal trans
      BEGIN
        --INICIO BUG 0036583 - 24/08/2017 YMG
        SELECT pac_isqlfor_lcol.fu_formato(p_valor => SUM(iprianu), p_dg_dec => 0)
        INTO v_tresult
        FROM estprimasgaranseg
        WHERE sseguro = psseguro
        AND cgarant   = 8048;
        --FIN BUG 0036583 - 24/08/2017 YMG
      EXCEPTION
      WHEN NO_DATA_FOUND THEN
        v_tresult := NULL;
      END;
      IF (v_tresult IS NULL) THEN
        v_tresult   := 'No contratada';
      ELSE
        v_tresult := '$' || v_tresult;
      END IF;
    END IF;
  END IF;
  RETURN v_tresult;
END f_inf_recibos_trans;
FUNCTION f_clausulas_trans(
    psseguro IN NUMBER,
    pcidioma IN NUMBER DEFAULT 8,
    pnmovimi IN NUMBER DEFAULT NULL,
    pcampo   IN NUMBER,
    pcmotmov IN NUMBER DEFAULT 0,
    ptablas  IN VARCHAR2 DEFAULT 'POL')
  RETURN CLOB
IS
  v_tresult CLOB;
  v_cont PLS_INTEGER := 0;
  v_crespue respuestas.crespue%TYPE;-- 0039168 31/07/2019 AGREGA VARIABLE
  vclausula VARCHAR2(4000);         --0039168 31/07/2019 AGREGA VARIABLE
BEGIN
  IF (ptablas  = 'POL') THEN --PÃ¿Â³liza emitida
    IF (pcampo = 1) THEN     --ClÃ¿Â¡usulas especÃ¿Â­ficas
      FOR i IN
      (SELECT DISTINCT tclaesp, s.nordcla -- GZG AITSSD-6588 07/11/2025
      FROM clausuesp s
      WHERE s.sseguro = psseguro
      AND s.sclagen  IS NULL
      ORDER BY s.nordcla ASC -- GZG AITSSD-6588 07/11/2025
      )
      LOOP
        v_tresult := v_tresult || i.tclaesp || ' \par \par ';
      END LOOP;
    ELSIF (pcampo = 2) THEN --ClÃ¿Â¡usulas generales
      FOR i IN
      (SELECT DISTINCT g.tclatit
        || ' \par '
        || pac_clausulas.f_get_descclausulapar( g.sclagen, s.sseguro, g.cidioma) clausula
      FROM clausuesp s,
        clausugen g
      WHERE s.sclagen = g.sclagen
      AND g.cidioma   = pcidioma
      AND s.sseguro   = psseguro
      AND s.sclagen  IS NOT NULL
      )
      LOOP
        v_tresult := v_tresult || i.clausula || ' \par \par ';
      END LOOP;
    END IF;
  ELSE                   --SimulaciÃ¿Â³n / EmisiÃ¿Â³n
    IF (pcampo = 1) THEN --ClÃ¿Â¡usulas especÃ¿Â­ficas
      FOR i IN
      (SELECT tclaesp
      FROM estclausuesp s
      WHERE s.sseguro = psseguro
      AND s.nmovimi   = pnmovimi
      AND s.sclagen  IS NULL
      )
      LOOP
        v_tresult := v_tresult || i.tclaesp || ' \par \par ';
      END LOOP;
    ELSIF (pcampo = 2) THEN --ClÃ¿Â¡usulas generales
      --1. Validar clÃ¿Â¡usulas ligadas a preguntas
      --PREGUNTA: Modalidad
      IF (f_inf_pol_trans(psseguro => psseguro, pcidioma => pcidioma, pnmovimi => pnmovimi, pcampo => 13, ptablas => ptablas) IN (1, 2, 3)) THEN --AutomÃ¿Â¡tica (1) Valores (2) y EspecÃ¿Â­fica (3)
        FOR i                                                                                                                 IN                 --INICIO BUG 0036641 - 18/08/2017 YMG
        (SELECT DISTINCT c.tclatit
          || ' \par '
          || REPLACE(c.tclatex, '#1#', 'DIEZ (10) DIAS') clausula
        FROM clausugen c
        WHERE c.cidioma = 8
        AND c.sclagen  IN (8298, 8338, 8320, 8379, 8263, 8255)
        ) --FIN BUG 0036641 - 18/08/2017 YMG
        LOOP
          v_tresult := v_tresult || i.clausula || ' \par \par ';
        END LOOP;
        -- INI 0039168 31/07/2019 JAPH SE AGREGA VALIDACION DE MODALIDAD DE COBRO, CONOCER SI ES VENCIDO(1)
        SELECT NVL(crespue,0) INTO v_crespue  FROM
             (SELECT crespue
              FROM Estpregunpolseg WHERE sseguro = psseguro
              AND cpregun = 4084 ORDER BY nmovimi DESC)
              WHERE ROWNUM = 1;
        --
        IF  v_crespue = 1 THEN
          SELECT DISTINCT c.tclatit
          || ' \par '
          || REPLACE(c.tclatex, '#1#', 'DIEZ (10) DIAS') clausula INTO vclausula
             FROM clausugen c
             WHERE c.cidioma = 8
             AND c.sclagen  =9020;
          v_tresult:= v_tresult|| vclausula || ' \par \par ';
        END IF;
        -- FIN 0039168 31/07/2019 JAPH
        --Inicio bug 0039365 - YMG
        /*
        --Solamente para AutomÃ¿Â¡tica de mercancÃ¿Â­as
        IF(f_inf_pol_trans(psseguro => psseguro,pcidioma => pcidioma, pnmovimi => pnmovimi,pcampo => 13, ptablas => ptablas) = 1)THEN
        FOR i IN
        (SELECT DISTINCT c.tclatit
        ||' \par '
        ||c.tclatex clausula
        FROM clausugen c
        WHERE c.cidioma = pcidioma
        AND c.sclagen  IN (8255)
        )
        LOOP
        v_tresult := v_tresult || i.clausula || ' \par \par ';
        END LOOP;
        ELSIF(f_inf_pol_trans(psseguro => psseguro,pcidioma => pcidioma, pnmovimi => pnmovimi,pcampo => 13, ptablas => ptablas) = 2)THEN--AutomÃ¿Â¡tica de valores (2)*/
        --Fin bug 0039365
        IF (f_inf_pol_trans(psseguro => psseguro, pcidioma => pcidioma, pnmovimi => pnmovimi, pcampo => 13, ptablas => ptablas) = 1) THEN
          FOR i IN
          (SELECT DISTINCT c.tclatit
            || ' \par '
            || c.tclatex clausula
          FROM clausugen c
          WHERE c.cidioma = pcidioma
          AND c.sclagen  IN (8255)
          )
          LOOP
            v_tresult := v_tresult || i.clausula || ' \par \par ';
          END LOOP;
        ELSIF (f_inf_pol_trans(psseguro => psseguro, pcidioma => pcidioma, pnmovimi => pnmovimi, pcampo => 13, ptablas => ptablas) = 2) THEN --AutomÃ¿Â¡tica de valores (2)
          FOR i IN
          (SELECT DISTINCT c.tclatit
            || ' \par '
            || c.tclatex clausula
          FROM clausugen c
          WHERE c.cidioma = pcidioma
          AND c.sclagen  IN (8244, 8246, 8247, 8248, 8249, 8250, 8251, 8252, 8253)
          ORDER BY 1
          )
          LOOP
            v_tresult := v_tresult || i.clausula || ' \par \par ';
          END LOOP;
          --INICIO BUG 37755 - YMG
        ELSIF (f_inf_pol_trans(psseguro => psseguro, pcidioma => pcidioma, pnmovimi => pnmovimi, pcampo => 13, ptablas => ptablas) IN (1, 3)) THEN --Mercancia
          FOR i                                                                                                                    IN
          (SELECT DISTINCT c.tclatit
            || ' \par '
            || c.tclatex clausula
          FROM clausugen c
          WHERE c.cidioma = pcidioma
          AND c.sclagen  IN (8488, 8489)
          ORDER BY 1
          )
          LOOP
            v_tresult := v_tresult || i.clausula || ' \par \par ';
          END LOOP;
        END IF;
        --FIN BUG 37755
      END IF;
      --AMPAROS: Amparo de guerra
      --
      SELECT COUNT(1)
      INTO v_cont
      FROM estgaranseg
      WHERE cgarant = 8045
      AND sseguro   = psseguro
      AND nmovimi   = pnmovimi;
      --
      IF (v_cont > 0 AND f_inf_pol_trans(psseguro => psseguro, pcidioma => pcidioma, pnmovimi => pnmovimi, pcampo => 13, ptablas => ptablas) IN (1, 3)) THEN
        FOR i                                                                                                                                IN
        (SELECT DISTINCT c.tclatit
          || ' \par '
          || c.tclatex clausula
        FROM clausugen c
        WHERE c.cidioma = pcidioma
        AND c.sclagen  IN (8262)
        )
        LOOP
          v_tresult := v_tresult || i.clausula || ' \par \par ';
        END LOOP;
      END IF;
      --PREGUNTAS: Tipo mercancÃ¿Â­a (Animales Vivos)
      SELECT COUNT(1)
      INTO v_cont
      FROM estpregunseg
      WHERE sseguro = psseguro
      AND nmovimi   = pnmovimi
      AND cpregun   = 9319
      AND crespue   = 20;
      IF (v_cont    > 0 AND f_inf_pol_trans(psseguro => psseguro, pcidioma => pcidioma, pnmovimi => pnmovimi, pcampo => 13, ptablas => ptablas) IN (1, 3)) THEN
        FOR i                                                                                                                                   IN
        (SELECT DISTINCT c.tclatit
          || ' \par '
          || c.tclatex clausula
        FROM clausugen c
        WHERE c.cidioma = pcidioma
        AND c.sclagen  IN (8238)
        )
        LOOP
          v_tresult := v_tresult || i.clausula || ' \par \par ';
        END LOOP;
      END IF;
      --PREGUNTAS: Estado mercancÃ¿Â­a (Usada)
      SELECT COUNT(1)
      INTO v_cont
      FROM estpregunseg p
      WHERE p.sseguro = psseguro
      AND p.nmovimi   = pnmovimi
      AND p.cpregun   = 9340
      AND p.crespue   = 2
      ORDER BY p.nriesgo;
      IF (v_cont > 0 AND f_inf_pol_trans(psseguro => psseguro, pcidioma => pcidioma, pnmovimi => pnmovimi, pcampo => 13, ptablas => ptablas) IN (1, 3)) THEN
        FOR i                                                                                                                                IN
        (SELECT DISTINCT c.tclatit
          || ' \par '
          || c.tclatex clausula
        FROM clausugen c
        WHERE c.cidioma = 8
        AND c.sclagen  IN (8317)
        )
        LOOP
          v_tresult := v_tresult || i.clausula || ' \par \par ';
        END LOOP;
      END IF;
      --2. ClÃ¿Â¡usulas seleccionadas por el usuario
      FOR i IN
      (SELECT g.tclatit
        || ' \par '
        || DECODE( g.sclagen, 8223, REPLACE(REPLACE(g.tclatex, '#1#', 'LUNES A SÃ¿ÂBADO'), '#2#', 'LAS 6:00 Y 18:00 HORAS'), 8226, REPLACE(g.tclatex, '#1#', '25 AÃ¿`OS'), 8230, REPLACE(g.tclatex, '#1#', '$300.000.000'), 8231, REPLACE(g.tclatex, '#1#', '30'), 8241, REPLACE(g.tclatex, '#1#', '10%'), g.tclatex) clausula
      FROM estpregunsegtab p,
        clausugen g
      WHERE p.nvalor = g.sclagen
      AND cpregun    = 7993
      AND sseguro    = psseguro
      AND g.cidioma  = pcidioma
      )
      LOOP
        v_tresult := v_tresult || i.clausula || ' \par \par ';
      END LOOP;
    END IF;
  END IF;
  RETURN f_jrep_trad_clob(v_tresult);--AITSSD-4306 GZG 21/12/2022
END f_clausulas_trans;
/*****************************************************************
FUNCTION f_importes_riesgo_certif_n
Devuelve totalizados los valores por todos los certiticados que tiene
la pÃ¿Â³liza
Devuelve los capitales de un riesgo, la prima
param IN psseguro  : codigo de seguro
param IN pnriesgo  : numero de riesgo
param IN pmodo     : modo EST/POL
param IN pgaracml  : 0-Todo riesgo/1-Corriente debil, manejo y lucro
return             : texto con los capitales del riesgo
BUG 32035 - 01/08/2017 - LGG
BUG 37017 - 05/09/2017 - LGG
BUG 37034 - 11/09/2017 - LGG
******************************************************************/
FUNCTION f_importes_riesgo_certif_n(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL,
    pgaracml IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(4000);
    v_tlinia garangen.tgarant%TYPE;
    v_tpargar VARCHAR2(300);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot VARCHAR2(200);
    v_ctipcap garanpro.ctipcap%TYPE;
    v_cimpres garanpro.cimpres%TYPE;
    v_tgarant garangen.tgarant%TYPE;
    v_npargar   NUMBER := 0;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
    v_produc seguros.sproduc%TYPE;
    v_norden garanpro.norden%TYPE;
    v_es_admin NUMBER;
    nerror     NUMBER;
    vncertif   NUMBER;
  BEGIN
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := 'SELECT ps.sproduc, p.norden, pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, ' || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d, g.tgarant,';
    ELSE
      v_tconsulta := 'SELECT ps.sproduc,  p.norden, pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, ' || ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot) d, g.tgarant';
    END IF;
    v_tconsulta         := v_tconsulta || ' FROM  garangen g, garanpro p, productos ps, ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' estgaranseg s, estseguros se';
      v_csituac         := '(0,7,5,2,4)';
    ELSE
      v_tconsulta                                 := v_tconsulta || ' garanseg s, seguros se, seguros so';
      IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
        v_csituac                                 := '(0,7,5,2)';
      ELSE
        v_csituac := '(0,7,5,2,4)';
      END IF;
    END IF;
    v_tconsulta := v_tconsulta || ' WHERE g.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = ps.sproduc';
    v_tconsulta := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' AND se.csituac in ' || v_csituac;
    v_tconsulta := v_tconsulta || ' AND s.sseguro = so.sseguro';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta := v_tconsulta || ' AND (p.CGARPADRE IS NULL )';
    v_tconsulta := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
    v_tconsulta := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    --INICIO Bug 37034 - 05/09/2017 - LGG
    v_tconsulta := v_tconsulta || ' AND s.nmovimi = ' || pnmovimi;
    --FIN Bug 37034 - 05/09/2017 - LGG
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_es_admin        := pac_seguros.f_es_col_admin(psseguro, 'EST');
      SELECT ncertif INTO vncertif FROM estseguros WHERE sseguro = psseguro;
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM estseguros seg
      WHERE seg.sseguro = psseguro
      );
  ELSE
    v_es_admin := pac_seguros.f_es_col_admin(psseguro, 'POL');
    SELECT ncertif INTO vncertif FROM seguros WHERE sseguro = psseguro;
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  END IF;
  --INICIO Bug 37017 - 05/09/2017 - LGG
  v_tconsulta := v_tconsulta || ' AND s.nmovimi = (  ';
  v_tconsulta := v_tconsulta || '    SELECT MAX(nmovimi) ';
  v_tconsulta := v_tconsulta || '    FROM  garanseg ';
  v_tconsulta := v_tconsulta || '    WHERE sseguro=s.sseguro ';
  v_tconsulta := v_tconsulta || '      and cgarant= g.cgarant ';
  v_tconsulta := v_tconsulta || '      and nriesgo=' || pnriesgo || ' ) ';
  --FIN Bug 37017 - 05/09/2017 - LGG
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_produc, v_norden, v_tlinia, v_ipritot, v_tgarant;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    --
    IF v_npargar = 1 AND v_icaptot = 0 THEN
      SELECT tatribu
      INTO v_tlinia
      FROM detvalores
      WHERE cvalor = 126
      AND catribu  = NVL(v_cimpres, 59)
      AND cidioma  = NVL(pcidioma, 8);
    END IF;
    IF pcampo   = 2 THEN
      v_tlinia := v_tgarant;
    END IF;
    IF pcampo   = 3 THEN
      v_tlinia := v_ipritot;
    END IF;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  --
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_riesgo_certif_n;
-- FIN  BUG 32035 - 01/08/2017 - LGG
-- FIN  BUG 37017 - 05/09/2017 - LGG
-- FIN  BUG 37034 - 11/09/2017 - LGG
/*****************************************************************
FUNCTION f_importes_riesgo_certif0
Devuelve totalizados los valores por todos los certiticados que tiene
la pÃ¿Â³liza
Devuelve los capitales de un riesgo, la prima
param IN psseguro  : codigo de seguro
param IN pnriesgo  : numero de riesgo
param IN pmodo     : modo EST/POL
param IN pgaracml  : 0-Todo riesgo/1-Corriente debil, manejo y lucro
return             : texto con los capitales del riesgo
BUG 32035 - 01/08/2017 - LGG
******************************************************************/
FUNCTION f_importes_riesgo_certif0(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL,
    pgaracml IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(4000);
    v_tlinia garangen.tgarant%TYPE;
    v_tpargar VARCHAR2(300);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot VARCHAR2(200);
    v_ctipcap garanpro.ctipcap%TYPE;
    v_cimpres garanpro.cimpres%TYPE;
    v_tgarant garangen.tgarant%TYPE;
    v_npargar   NUMBER := 0;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
    v_produc seguros.sproduc%TYPE;
    v_norden garanpro.norden%TYPE;
    v_es_admin NUMBER;
    nerror     NUMBER;
    vncertif   NUMBER;
    v_sproduc  NUMBER;--BUG 0044879 - 23/01/2019 - CASL - Se crea nueva variable
  BEGIN
    --
    --INI BUG 0044879 - 23/01/2019 - CASL - Se obtiene el producto
    --
    BEGIN
      --
      IF NVL(pmodo, 'POL') = 'EST' THEN
        --
        SELECT sproduc INTO v_sproduc FROM estseguros WHERE sseguro = psseguro;
      --
    ELSE
      --
      SELECT sproduc INTO v_sproduc FROM seguros WHERE sseguro = psseguro;
      --
    END IF;
    --
  EXCEPTION
  WHEN OTHERS THEN
    --
    v_sproduc:= NULL;
    --
  END;
  --
  --FIN BUG 0044879 - 23/01/2019 - CASL
  --
  IF NVL(pmodo, 'POL') = 'EST' THEN
    v_tablaseg        := 'estseguros';
  ELSE
    v_tablaseg := 'seguros';
  END IF;
  v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
  EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
  IN psseguro;
  IF v_act0      = 1 THEN
    v_actividad := '0';
  ELSE
    v_actividad := 'se.cactivi';
  END IF;
  IF NVL(pmodo, 'POL') = 'EST' THEN
    v_tconsulta       := 'select DISTINCT a.sproduc, pp.norden, TRIM(TO_CHAR(SUM(b),''999,999,999,999,999,999'')), TRIM(TO_CHAR(SUM(dd),''999,999,999,999,999,999'')), TRIM(tgarant) from (SELECT ps.sproduc, s.cgarant, g.tgarant, pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d, s.ipritot dd';
  ELSE
    v_tconsulta := 'select DISTINCT a.sproduc, pp.norden, TRIM(TO_CHAR(SUM(b),''999,999,999,999,999,999'')), TRIM(TO_CHAR(SUM(dd),''999,999,999,999,999,999'')), TRIM(tgarant) from (SELECT ps.sproduc, s.cgarant, g.tgarant, pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot) d, s.ipritot dd';
  END IF;
  v_tconsulta         := v_tconsulta || ' FROM  garangen g, garanpro p, productos ps, ';
  IF NVL(pmodo, 'POL') = 'EST' THEN
    v_tconsulta       := v_tconsulta || ' estgaranseg s, estseguros se';
    v_csituac         := '(0,7,5,2,4)';
  ELSE
    v_tconsulta                                 := v_tconsulta || ' garanseg s, seguros se, seguros so';
    IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
      v_csituac                                 := '(0,7,5)';--BUG 0063477 GZG 19/09/2020
    ELSE
      v_csituac := '(0,7,5,4)';--BUG 0063477 GZG 19/09/2020
    END IF;
  END IF;
  v_tconsulta := v_tconsulta || ' WHERE g.cgarant = s.cgarant';
  v_tconsulta := v_tconsulta || ' AND p.cgarant = s.cgarant';
  v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
  v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
  v_tconsulta := v_tconsulta || ' AND p.sproduc = ps.sproduc';
  v_tconsulta := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
  v_tconsulta := v_tconsulta || ' AND se.csituac in ' || v_csituac;
  v_tconsulta := v_tconsulta || ' AND s.sseguro = so.sseguro';
  v_tconsulta := v_tconsulta || ' AND (p.CGARPADRE IS NULL )';
  --
  --INI BUG 0044879 - 23/01/2019 - CASL - Si el producto tiene ajuste blanket se filta solo por los movimientos que afectaron certificados
  --
  IF NVL(f_parproductos_v(v_sproduc, 'IMP_AJUSTE_BLANKET'), 0) = 1 THEN
    --INI BUG 0063477 GZG 19/09/2020 Se agrega Max(dx.nmovimi_cert)
    v_tconsulta := v_tconsulta || ' AND (SO.SSEGURO,S.NMOVIMI) IN(SELECT DX.SSEGURO_CERT, MAX(DX.NMOVIMI_CERT)
FROM DETMOVSEGUROCOL DX
WHERE DX.SSEGURO_0 = (SELECT DY.SSEGURO
FROM SEGUROS DY
WHERE DY.NPOLIZA = (SELECT BV.NPOLIZA
FROM SEGUROS BV
WHERE BV.SSEGURO = '||psseguro||')
AND DY.NCERTIF = 0)
AND DX.NMOVIMI_0 <= '||pnmovimi||
'GROUP BY DX.SSEGURO_CERT
) ';
    --FIN BUG 0063477 GZG 19/09/2020
  ELSE
    --
    v_tconsulta := v_tconsulta || ' AND so.npoliza in  (select npoliza from seguros where sseguro in (' || psseguro || '))';
    --
  END IF;
  --
  --FIN BUG 0044879 - 23/01/2019 - CASL
  --
  v_tconsulta         := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
  v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
  IF NVL(pmodo, 'POL') = 'EST' THEN
    v_es_admin        := pac_seguros.f_es_col_admin(psseguro, 'EST');
    SELECT ncertif INTO vncertif FROM estseguros WHERE sseguro = psseguro;
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM estseguros seg
      WHERE seg.sseguro = psseguro
      );
  ELSE
    v_es_admin := pac_seguros.f_es_col_admin(psseguro, 'POL');
    SELECT ncertif INTO vncertif FROM seguros WHERE sseguro = psseguro;
    SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  END IF;
  --v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden) a, garanpro pp WHERE a.cgarant=pp.cgarant AND  pp.sproduc = a.sproduc GROUP BY a.sproduc, pp.norden, a.cgarant, a.tgarant ORDER BY pp.norden';
  --p_control_error('LG', 'f_importes_riesgo_pyme0', 'v_tconsulta:' || v_tconsulta);
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_produc, v_norden, v_tlinia, v_ipritot, v_tgarant;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    --
    IF v_npargar = 1 AND v_icaptot = 0 THEN
      SELECT tatribu
      INTO v_tlinia
      FROM detvalores
      WHERE cvalor = 126
      AND catribu  = NVL(v_cimpres, 59)
      AND cidioma  = NVL(pcidioma, 8);
    END IF;
    IF pcampo   = 2 THEN
      v_tlinia := v_tgarant;
    END IF;
    IF pcampo   = 3 THEN
      v_tlinia := v_ipritot;
    END IF;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  --
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_riesgo_certif0;
-- FIN  BUG 32035 - 01/08/2017 - LGG
/*****************************************************************
FUNCTION f_intermediarios_corretaje
Devuelve la informacion de los intermediarios de corretaje
param IN psseguro  : codigo de seguro
param IN pnmovimi  : numero de movimiento
param IN pcolumn   : numero de la columna a mostrar
return             : texto con los datos segun la columna solicitada
BUG 37907 - 21/09/2017 - LGG
******************************************************************/
FUNCTION f_intermediarios_corretaje(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER,
    pcolumn  IN NUMBER)
  RETURN VARCHAR2
IS
  vret VARCHAR2(2000);
  vcrespue NUMBER := 0;--AITSSD-18878 GZG 07/06/2024
BEGIN
  --INI AITSSD-18878 GZG 07/06/2024
  BEGIN
      --
      SELECT crespue
        INTO vcrespue
        FROM pregunpolseg
       WHERE sseguro = psseguro
         AND cpregun = 4780--tiene corretaje?
         AND nmovimi = pnmovimi;
      --
  EXCEPTION
  WHEN OTHERS THEN
    --
    vcrespue:= 0;
    --
  END;
  --FIN AITSSD-18878 GZG 07/06/2024
  vret := NULL;
  IF vcrespue <> 0 THEN--AITSSD-18878 GZG 07/06/2024
  FOR i IN
  (SELECT ac.cagente,
    pac_isqlfor.f_agente(ac.cagente) tagente,
    pac_isqlfor.f_per_contactos(
    (SELECT a.sperson FROM agentes a WHERE a.cagente = ac.cagente
    ), 1) telf,
    ac.ppartici
    || '%' porc_part,
    pac_isqlfor_lcol.f_agente_pyme(ac.cagente) nombre
  FROM age_corretaje ac
  WHERE ac.sseguro = psseguro
  AND nmovimi      =
    (SELECT MAX(nmovimi)
    FROM age_corretaje
    WHERE sseguro = psseguro
    AND nmovimi  <= pnmovimi
    )
  ORDER BY islider DESC,
    cagente
  )
  LOOP
    IF pcolumn    = 1 THEN
      vret       := vret || i.cagente || ' \par ';
    ELSIF pcolumn = 2 THEN
      vret       := vret || i.tagente || ' \par ';
    ELSIF pcolumn = 3 THEN
      vret       := vret || i.telf || ' \par ';
    ELSIF pcolumn = 4 THEN
      vret       := vret || i.porc_part || ' \par ';
    ELSIF pcolumn = 5 THEN
      vret       := vret || i.nombre || ' \par ';
    END IF;
  END LOOP;
  END IF;--AITSSD-18878 GZG 07/06/2024
  --p_control_error('LG', 'f_intermediarios_corretaje', 'vret:' || vret);
  RETURN f_jrep_trad(vret);
EXCEPTION
WHEN OTHERS THEN
  RETURN '';
END f_intermediarios_corretaje;
-- FIN - BUG 37907 - 21/09/2017 - LGG
/*****************************************************************
FUNCTION f_amp_val_lim_pyme_mr
Devuelve descripciones y valores de las vigencias y eventos de los limites de indemnizacion de los amparos de un riesgo para Pyme
param IN psseguro  : codigo de seguro
param IN pcidioma  : codigo de idioma
param IN pcampo    : recupera la cod de la garantias, desc de las garantias, el capital
param IN pmodo     : modo EST/POL
return             : texto con las garantias del riesgo
BUG 37907 - 27/09/2017 - LGG
******************************************************************/
FUNCTION f_amp_val_lim_pyme_mr(
    psseguro IN NUMBER,
    pcidioma IN NUMBER DEFAULT 1,
    pcampo   IN NUMBER DEFAULT 1,
    ptipo    IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnriesgo IN NUMBER DEFAULT 1,
    pnmovimi IN NUMBER DEFAULT 1,
    psproces IN NUMBER DEFAULT NULL) --MPC BUG 47494 08/03/2019 Se adiciona parametro.
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult     VARCHAR2(32000) := '';
    v_tconsulta   VARCHAR2(4000);
    v_tconsulta_1 VARCHAR2(4000) := ''; --MPC BUG 47494 08/03/2019 Se adiciona variable.
    v_tablaseg    VARCHAR2(30);
    v_act0        NUMBER(1);
    v_actividad   VARCHAR2(20);
    v_cgarant     VARCHAR2(300);
    v_tgarant     VARCHAR2(3000);
    v_cpregun     VARCHAR2(300);
    v_crespue     VARCHAR2(300);
  BEGIN
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 's.cactivi';
    END IF;
    v_tconsulta := 'select cgarant, (';
    v_tconsulta := v_tconsulta || '        CASE ';
    v_tconsulta := v_tconsulta || '        WHEN cpregun IN (7978,797) THEN ';
    v_tconsulta := v_tconsulta || '        tgarant||'' mas lucro cesante'' ';
    v_tconsulta := v_tconsulta || '        else  ';
    v_tconsulta := v_tconsulta || '        tgarant ';
    v_tconsulta := v_tconsulta || '        END  ';
    v_tconsulta := v_tconsulta || '      ) tgarant, cpregun,';
    --v_tconsulta := v_tconsulta || 'crespue ';
    v_tconsulta := v_tconsulta || ' CASE WHEN cpregun IN (9583) AND (' || ptipo || '=1) THEN '' '' ELSE TO_CHAR(crespue,''999,999,999,999,999.99'') END crespue ';
    v_tconsulta := v_tconsulta || ' from   ';
    v_tconsulta := v_tconsulta || ' (select distinct sgc.cgarant, gg.tgarant, gs.icapital,gr.cpregun, gr.crespue,gs.norden  ';
    --INI BUG 47494 MPC 08/03/2019 Se adiciona filtro.
    IF NVL(pmodo, 'POL') = 'CAR' THEN
      v_tconsulta       := v_tconsulta || ' from sin_gar_causa sgc, garancar gs, seguros s, garangen gg , garanpro gp, movseguro m, pregungaranseg gr ';
      v_tconsulta_1     := ' and gs.sproces = '||psproces;
    ELSE
      --FIN BUG 47494 MPC 08/03/2019 Se adiciona filtro.
      v_tconsulta := v_tconsulta || ' from sin_gar_causa sgc, garanseg gs, seguros s, garangen gg , garanpro gp, movseguro m, pregungaranseg gr ';
    END IF;--BUG 47494 MPC 08/03/2019 Se adiciona filtro.
    v_tconsulta := v_tconsulta || ' where sgc.cactivi = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' and sgc.cmotsin = 0 and sgc.cgarant =  gs.cgarant   ';
    v_tconsulta := v_tconsulta || v_tconsulta_1; --BUG 47494 MPC 08/03/2019 Se adiciona filtro.
    v_tconsulta := v_tconsulta || ' and gs.sseguro = ' || psseguro;
    v_tconsulta := v_tconsulta || ' and gs.sseguro = s.sseguro   ';
    --
    v_tconsulta := v_tconsulta || ' and gs.nriesgo = ' || pnriesgo;
    --
    v_tconsulta := v_tconsulta || ' and sgc.sproduc = s.sproduc   ';
    v_tconsulta := v_tconsulta || ' and gg.cgarant = gs.cgarant   ';
    v_tconsulta := v_tconsulta || ' and gg.cidioma = ' || pcidioma;
    v_tconsulta := v_tconsulta || ' and gs.cgarant=gp.cgarant ';
    v_tconsulta := v_tconsulta || ' and gs.nmovimi=m.nmovimi ';
    --
    v_tconsulta := v_tconsulta || ' and gs.nmovimi=' || pnmovimi;
    --
    v_tconsulta := v_tconsulta || ' and gs.sseguro=gr.sseguro ';
    v_tconsulta := v_tconsulta || ' and gr.sseguro=s.sseguro ';
    --
    v_tconsulta := v_tconsulta || ' and gr.nmovimi=' || pnmovimi;
    v_tconsulta := v_tconsulta || ' and gr.nriesgo = ' || pnriesgo;
    --
    v_tconsulta := v_tconsulta || ' and gs.cgarant=gr.cgarant ';
    --INICIO BUG 37907 - 18/10/2017 - LGG
    v_tconsulta := v_tconsulta || ' AND s.sseguro  = ' || psseguro;
    v_tconsulta := v_tconsulta || ' AND m.sseguro  = ' || psseguro;
    --FIN BUG 37907 - 18/10/2017 - LGG
    v_tconsulta := v_tconsulta || ' UNION   ';
    v_tconsulta := v_tconsulta || ' select distinct sgc.cgarant, gg.tgarant, gs.icapital,gr.cpregun, gr.crespue,gs.norden   ';
    --INI BUG 47494 MPC 08/03/2019 Se adiciona filtro.
    IF NVL(pmodo, 'POL') = 'CAR' THEN
      v_tconsulta       := v_tconsulta || ' from sin_gar_causa sgc, garancar gs, seguros s, garangen gg , garanpro gp, movseguro m, pregungaranseg gr ';
      v_tconsulta_1     := ' and gs.sproces = '||psproces;
    ELSE
      --FIN BUG 47494 MPC 08/03/2019 Se adiciona filtro.
      v_tconsulta := v_tconsulta || ' from sin_gar_causa sgc, garanseg gs, seguros s, garangen gg  , garanpro gp, movseguro m, pregungaranseg gr ';
    END IF; --BUG 47494 MPC 08/03/2019 Se adiciona filtro.
    v_tconsulta := v_tconsulta || ' where sgc.cactivi = ' || v_actividad;
    v_tconsulta := v_tconsulta || v_tconsulta_1; --BUG 47494 MPC 08/03/2019 Se adiciona filtro.
    v_tconsulta := v_tconsulta || ' and NOT EXISTS (SELECT 1 FROM sin_gar_causa WHERE sproduc = sgc.sproduc AND cactivi = 0) and sgc.ccausin = 7021 and sgc.cmotsin = 0  ';
    v_tconsulta := v_tconsulta || ' and sgc.cgarant =  gs.cgarant   ';
    v_tconsulta := v_tconsulta || ' and gs.sseguro = ' || psseguro;
    v_tconsulta := v_tconsulta || ' and gs.sseguro = s.sseguro   ';
    --
    v_tconsulta := v_tconsulta || ' and gs.nriesgo = ' || pnriesgo;
    --
    v_tconsulta := v_tconsulta || ' and sgc.sproduc = s.sproduc   ';
    v_tconsulta := v_tconsulta || ' and gg.cgarant = gs.cgarant   ';
    v_tconsulta := v_tconsulta || ' and gg.cidioma = ' || pcidioma;
    v_tconsulta := v_tconsulta || ' and gs.nmovimi=m.nmovimi ';
    --
    v_tconsulta := v_tconsulta || ' and gs.nmovimi=' || pnmovimi;
    --
    v_tconsulta := v_tconsulta || ' and gs.sseguro=gr.sseguro ';
    v_tconsulta := v_tconsulta || ' and gr.sseguro=s.sseguro ';
    --
    v_tconsulta := v_tconsulta || ' and gr.nmovimi=' || pnmovimi;
    v_tconsulta := v_tconsulta || ' and gr.nriesgo = ' || pnriesgo;
    --
    v_tconsulta := v_tconsulta || ' and gs.cgarant=gr.cgarant ';
    --INICIO BUG 37907 - 18/10/2017 - LGG
    v_tconsulta := v_tconsulta || ' AND s.sseguro  = ' || psseguro;
    v_tconsulta := v_tconsulta || ' AND m.sseguro  = ' || psseguro;
    --FIN BUG 37907 - 18/10/2017 - LGG
    v_tconsulta := v_tconsulta || ' order by norden)  ';
    v_tconsulta := v_tconsulta || ' where cgarant in( ';
    v_tconsulta := v_tconsulta || '3114, ';
    v_tconsulta := v_tconsulta || '3115, ';
    v_tconsulta := v_tconsulta || '3117, ';
    v_tconsulta := v_tconsulta || '3119, ';
    v_tconsulta := v_tconsulta || '3122, ';
    v_tconsulta := v_tconsulta || '3123, ';
    v_tconsulta := v_tconsulta || '3182 ';
    v_tconsulta := v_tconsulta || ') ';
    --Valores de Evento
    IF ptipo       = 1 THEN
      v_tconsulta := v_tconsulta || 'and cpregun in (9582,7978,9583) ';
    END IF;
    --Valores de Vigencia
    IF ptipo       = 2 THEN
      v_tconsulta := v_tconsulta || 'and cpregun in (9583,7979,9583) ';
    END IF;
    --P_CONTROL_ERROR('LG','f_amp_val_lim_pyme_mr','v_tconsulta:'||v_tconsulta);
    OPEN vr_cursor FOR v_tconsulta;
    LOOP
      FETCH vr_cursor
      INTO v_cgarant,
        v_tgarant,
        v_cpregun,
        v_crespue;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF pcampo    = 1 THEN
      v_tresult := v_tresult || v_cgarant || '\par ';
    END IF;
    IF pcampo    = 2 THEN
      v_tresult := v_tresult || v_tgarant || '\par ';
    END IF;
    IF pcampo    = 3 THEN
      v_tresult := v_tresult || v_cpregun || '\par ';
    END IF;
    IF pcampo    = 4 THEN
      v_tresult := v_tresult || v_crespue || '\par ';
    END IF;
  END LOOP;
  --P_CONTROL_ERROR('LG','f_amp_val_lim_pyme_mr','v_tresult:'||v_tresult);
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ' ';
END f_amp_val_lim_pyme_mr;
-- BUG 37907 - 27/09/2017 - LGG - FIN
/*****************************************************************
FUNCTION f_benespseg_rel_xriesgo
Para que traiga todos los beneficiarios por riesgo
param IN psseguro  :
param IN pnmovimi  :
param IN pcidioma  :
param IN pnriesgo  :
param IN pcamp     : Codigo de campo
return             : texto
BUG 37907 - 27/09/2017 - LGG
******************************************************************/
FUNCTION f_benespseg_rel_xriesgo(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER,
    pcidioma IN NUMBER,
    pnriesgo IN NUMBER,
    pcamp    IN NUMBER)
  RETURN VARCHAR2
IS
  v_tresult  VARCHAR2(4000);
  v_tresult2 VARCHAR2(4000);
BEGIN
  FOR i IN
  (SELECT SUBSTR(f_dades_persona(ben.sperson, 8, pcidioma, 'POL'), 1, 5)
    || ' '
    || f_dades_persona(ben.sperson, 1, pcidioma, 'POL') idbenef,
    (SELECT TRIM(tnombre)
      || ' '
      || TRIM(tapelli1
      || ' '
      || tapelli2)
    FROM per_detper
    WHERE sperson = ben.sperson
    AND ROWNUM    = 1
    ) nombenef,
    ff_desvalorfijo(1054, pcidioma, ben.cparen) parentbenef,
    ben.pparticip porcbenef,
    f_dades_persona(ben.sperson_tit, 8, pcidioma, 'POL')
    || ' '
    || f_dades_persona(ben.sperson_tit, 1, pcidioma, 'POL') contbenef,
    NULL acrebenef,
    (SELECT tvalcon
    FROM per_contactos
    WHERE sperson = ben.sperson
    AND ROWNUM    = 1
    AND ctipcon   = 1
    ) telefonobnf,
    NULL bnfpoblac,
    NULL bnfdirec,
    ben.sperson,
    ben.cgarant
  FROM benespseg ben
  WHERE ben.sseguro = psseguro
    --AND cgarant = 0   --beneficiarios de riesgo
  AND nmovimi =
    (SELECT MAX(nmovimi)
    FROM benespseg
    WHERE sseguro = psseguro
      --INCIO BUG 37907 - 06/10/2017 - LGG
      --AND nmovimi <= pnmovimi
      --FIN BUG 37907 - 06/10/2017 - LGG
    AND nriesgo = pnriesgo
    )
  AND nriesgo = pnriesgo
  ORDER BY nriesgo ASC,
    sperson_tit ASC,
    pparticip DESC,
    fmovimi ASC,
    ROWID ASC
  )
  LOOP
    IF pcamp     = 1 THEN
      v_tresult := v_tresult || i.idbenef || ' \par ';
    ELSIF pcamp  = 2 THEN
      v_tresult := v_tresult || i.nombenef || ' \par ';
    ELSIF pcamp  = 3 THEN
      v_tresult := v_tresult || i.parentbenef || ' \par ';
    ELSIF pcamp  = 4 THEN
      v_tresult := v_tresult || i.porcbenef || ' \par ';
    ELSIF pcamp  = 5 THEN
      v_tresult := v_tresult || i.contbenef || ' \par ';
    ELSIF pcamp  = 6 THEN
      v_tresult := v_tresult || i.acrebenef || ' \par ';
    ELSIF pcamp  = 7 THEN
      v_tresult := v_tresult || i.telefonobnf || ' \par ';
    ELSIF pcamp  = 8 THEN
      BEGIN
        --INICIO BUG 37907 - 24/10/2017 - LGG
        --SELECT pac_isqlfor.f_poblacion(i.sperson, rmax_domici) || ' \par '
        SELECT DISTINCT pac_isqlfor.f_poblacion(i.sperson, rmax_domici)
          || ' \par '
        INTO v_tresult2
          --FIN BUG 37907 - 24/10/2017 - LGG
        FROM
          (SELECT b.cdomici AS rmax_domici
          FROM benespseg a,
            asegurados b
          WHERE a.sseguro = psseguro
          AND a.sseguro   = b.sseguro
          AND a.sperson   = b.sperson
          AND a.sperson   = i.sperson
            --AND a.cgarant = 0
          AND a.nmovimi =
            (SELECT MAX(nmovimi)
            FROM benespseg
            WHERE sseguro = psseguro
              --INCIO BUG 37907 - 06/10/2017 - LGG
              --AND nmovimi <= pnmovimi
              --FIN BUG 37907 - 06/10/2017 - LGG
            AND nriesgo = pnriesgo
            )
          );
        --INICIO BUG 37907 - 24/10/2017 - LGG
        IF v_tresult2 = ' \par ' THEN
          --FIN BUG 37907 - 24/10/2017 - LGG
          RAISE NO_DATA_FOUND;
        END IF;
      EXCEPTION
      WHEN NO_DATA_FOUND THEN
        BEGIN
          --INICIO BUG 37907 - 24/10/2017 - LGG
          --SELECT pac_isqlfor.f_poblacion(i.sperson, rmax_domici) || ' \par '
          SELECT DISTINCT pac_isqlfor.f_poblacion(i.sperson, rmax_domici)
            || ' \par '
          INTO v_tresult2
            --FIN BUG 37907 - 24/10/2017 - LGG
          FROM
            (SELECT b.cdomici AS rmax_domici
            FROM benespseg a,
              tomadores b
            WHERE a.sseguro = psseguro
            AND a.sseguro   = b.sseguro
            AND a.sperson   = b.sperson
            AND a.sperson   = i.sperson
              --AND a.cgarant = 0 --Para que traiga todos los beneficiarios
            AND a.nmovimi =
              (SELECT MAX(nmovimi)
              FROM benespseg
              WHERE sseguro = psseguro
                --INCIO BUG 37907 - 06/10/2017 - LGG
                --AND nmovimi <= pnmovimi
                --FIN BUG 37907 - 06/10/2017 - LGG
              AND nriesgo = pnriesgo
              )
            );
          --INICIO BUG 37907 - 24/10/2017 - LGG
          IF v_tresult2 = ' \par ' THEN
            --FIN BUG 37907 - 24/10/2017 - LGG
            RAISE NO_DATA_FOUND;
          END IF;
        EXCEPTION
        WHEN NO_DATA_FOUND THEN
          BEGIN
            --INICIO BUG 37907 - 24/10/2017 - LGG
            /*
            SELECT pac_isqlfor.f_poblacion(i.sperson, MAX(cdomici)) || ' \par '
            AS rmax_domici
            */
            SELECT DISTINCT pac_isqlfor.f_poblacion(i.sperson, MAX(cdomici))
              || ' \par ' AS rmax_domici
            INTO v_tresult2
              --FIN BUG 37907 - 24/10/2017 - LGG
            FROM per_direcciones
            WHERE sperson = i.sperson
            AND ctipdir   = 9;
            --INICIO BUG 37907 - 24/10/2017 - LGG
            IF v_tresult2 = ' \par ' THEN
              --FIN BUG 37907 - 24/10/2017 - LGG
              RAISE NO_DATA_FOUND;
            END IF;
          EXCEPTION
          WHEN NO_DATA_FOUND THEN
            BEGIN
              --INICIO BUG 37907 - 24/10/2017 - LGG
              /*
              SELECT pac_isqlfor.f_poblacion(i.sperson, MAX(cdomici))
              || ' \par ' AS rmax_domici
              */
              SELECT DISTINCT pac_isqlfor.f_poblacion(i.sperson, MAX(cdomici))
                || ' \par ' AS rmax_domici
              INTO v_tresult2
                --FIN BUG 37907 - 24/10/2017 - LGG
              FROM per_direcciones
              WHERE sperson = i.sperson;
            EXCEPTION
            WHEN OTHERS THEN
              RETURN ('');
            END;
          END;
        END;
        --INICIO BUG 37907 - 24/10/2017 - LGG
        v_tresult := v_tresult || v_tresult2;
        --FIN BUG 37907 - 24/10/2017 - LGG
        --p_control_error('LG', 'f_benespseg_rel_xriesgo', 'v_tresult:8 ' || v_tresult);
      END;
    ELSIF pcamp = 9 THEN
      BEGIN
        --INICIO BUG 37907 - 24/10/2017 - LGG
        --SELECT  pac_isqlfor.f_direccion(i.sperson, rmax_domici) || ' \par '
        SELECT DISTINCT pac_isqlfor.f_direccion(i.sperson, rmax_domici)
          || ' \par '
        INTO v_tresult2
          --FIN BUG 37907 - 24/10/2017 - LGG
        FROM
          (SELECT b.cdomici AS rmax_domici
          FROM benespseg a,
            asegurados b
          WHERE a.sseguro = psseguro
          AND a.sseguro   = b.sseguro
          AND a.sperson   = b.sperson
          AND a.sperson   = i.sperson
            --AND a.cgarant = 0
          AND a.nmovimi =
            (SELECT MAX(nmovimi)
            FROM benespseg
            WHERE sseguro = psseguro
              --INCIO BUG 37907 - 06/10/2017 - LGG
              --  AND nmovimi <= pnmovimi
              --FIN BUG 37907 - 06/10/2017 - LGG
            AND nriesgo = pnriesgo
            )
          );
        --INICIO BUG 37907 - 24/10/2017 - LGG
        IF v_tresult2 = ' \par ' THEN
          --FIN BUG 37907 - 24/10/2017 - LGG
          RAISE NO_DATA_FOUND;
        END IF;
      EXCEPTION
      WHEN NO_DATA_FOUND THEN
        BEGIN
          --INICIO BUG 37907 - 24/10/2017 - LGG
          --SELECT pac_isqlfor.f_direccion(i.sperson, rmax_domici) || ' \par '
          SELECT DISTINCT pac_isqlfor.f_direccion(i.sperson, rmax_domici)
            || ' \par '
          INTO v_tresult2
            --FIN BUG 37907 - 24/10/2017 - LGG
          FROM
            (SELECT b.cdomici AS rmax_domici
            FROM benespseg a,
              tomadores b
            WHERE a.sseguro = psseguro
            AND a.sseguro   = b.sseguro
            AND a.sperson   = b.sperson
            AND a.sperson   = i.sperson
              --AND a.cgarant = 0 --Para que traiga todos los beneficiarios
            AND a.nmovimi =
              (SELECT MAX(nmovimi)
              FROM benespseg
              WHERE sseguro = psseguro
                --INCIO BUG 37907 - 06/10/2017 - LGG
                --   AND nmovimi <= pnmovimi
                --FIN BUG 37907 - 06/10/2017 - LGG
              AND nriesgo = pnriesgo
              )
            );
          --INICIO BUG 37907 - 24/10/2017 - LGG
          IF v_tresult2 = ' \par ' THEN
            --FIN BUG 37907 - 24/10/2017 - LGG
            RAISE NO_DATA_FOUND;
          END IF;
        EXCEPTION
        WHEN NO_DATA_FOUND THEN
          BEGIN
            --INICIO BUG 37907 - 24/10/2017 - LGG
            /*
            SELECT pac_isqlfor.f_direccion(i.sperson, MAX(cdomici)) || ' \par '
            AS rmax_domici
            */
            SELECT DISTINCT pac_isqlfor.f_direccion(i.sperson, MAX(cdomici))
              || ' \par ' AS rmax_domici
            INTO v_tresult2
              --FIN BUG 37907 - 24/10/2017 - LGG
            FROM per_direcciones
            WHERE sperson = i.sperson
            AND ctipdir   = 9;
            IF v_tresult  = ' \par ' THEN
              RAISE NO_DATA_FOUND;
            END IF;
          EXCEPTION
          WHEN NO_DATA_FOUND THEN
            BEGIN
              --INICIO BUG 37907 - 24/10/2017 - LGG
              --SELECT pac_isqlfor.f_direccion(i.sperson, MAX(cdomici))
              SELECT DISTINCT pac_isqlfor.f_direccion(i.sperson, MAX(cdomici))
                || ' \par ' AS rmax_domici
              INTO v_tresult2
                --FIN BUG 37907 - 24/10/2017 - LGG
              FROM per_direcciones
              WHERE sperson = i.sperson;
            EXCEPTION
            WHEN OTHERS THEN
              RETURN ('');
            END;
          END;
        END;
        --INICIO BUG 37907 - 24/10/2017 - LGG
        v_tresult := v_tresult || v_tresult2;
        --FIN BUG 37907 - 24/10/2017 - LGG
        --p_control_error('LG', 'f_benespseg_rel_xriesgo', 'v_tresult:9 ' || v_tresult);
      END;
    ELSIF pcamp = 10 THEN
      BEGIN
        v_tresult2 := '';
        --INICIO BUG 37907 - 24/10/2017 - LGG
        --select (select tatribu from detvalores where cidioma=8 and cvalor=1053 and catribu=b.ctipben)
        SELECT DISTINCT
          (SELECT tatribu
          FROM detvalores
          WHERE cidioma = 8
          AND cvalor    = 1053
          AND catribu   = b.ctipben
          )
          || DECODE(b.cgarant, 0, ' ', ' - ')
          ||
          (SELECT tgarant FROM garangen WHERE cgarant = b.cgarant AND cidioma = 8
          )
          --FIN BUG 37907 - 24/10/2017 - LGG
        INTO v_tresult2
        FROM benespseg b
        WHERE b.sseguro = psseguro
          --INICIO BUG 37907 - 23/10/2017 - LGG
        AND b.nriesgo = pnriesgo
          --FIN BUG 37907 - 23/10/2017 - LGG
        AND b.sperson = i.sperson
        AND b.cgarant = i.cgarant
        AND b.nmovimi = pnmovimi;
        --P_CONTROL_ERROR('LG','f_benespseg_rel','2.1 v_tresult2:'||v_tresult2 ||' '||i.sperson);
        v_tresult := v_tresult || v_tresult2 || ' \par ';
      EXCEPTION
      WHEN OTHERS THEN
        p_control_error('JFN-PYME', 'PAC_ISQLFOR_LCOL', 1);
        RETURN ('');
      END;
    END IF;
  END LOOP;
  RETURN (REPLACE(f_jrep_trad(v_tresult), CHR(39), ''));
EXCEPTION
WHEN OTHERS THEN
  p_control_error('JFN-PYME', 'PAC_ISQLFOR_LCOL', 2);
  RETURN ('');
END f_benespseg_rel_xriesgo;
