/*****************************************************************
FUNCTION f_deducible_xgarantia
Devuelve la descripciÃ¿Â¿Ã¿Â³n del deducible para una garantia
param IN psseguro  : codigo de seguro
param IN pcampo    : codigo del valor a devolver
param IN pnriesgo  : numero de riesgo
param IN pmodo     : modo EST/POL
return             : texto con los capitales del riesgo
BUG 37907 - 29/09/2017 - LGG
******************************************************************/
FUNCTION f_deducible_xgarantia(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pcgarant IN garangen.cgarant%TYPE,
    psproces IN NUMBER DEFAULT NULL) --MPC BUG 47494 08/03/2019 Se adiciona filtro.
  RETURN VARCHAR2
IS
  v_tresult VARCHAR2(32000) := '';
  v_tlinia garangen.tgarant%TYPE;
  v_porcded NUMBER;
  v_smmlv   NUMBER;
  v_tnivel  VARCHAR2(200);
BEGIN
  IF NVL(pmodo, 'POL') = 'EST' THEN
    SELECT bd.impvalor1 porcded,
      bd.impmin smmlv,
      bn.tnivel
    INTO v_porcded,
      v_smmlv,
      v_tnivel
    FROM bf_progarangrup bp,
      estbf_bonfranseg bf,
      bf_detnivel bd,
      estseguros s,
      bf_desnivel bn
    WHERE s.sseguro = psseguro
    AND bp.sproduc  = s.sproduc
    AND bp.cgarant  = pcgarant
    AND bp.cempres  = s.cempres
    AND bp.cactivi  = s.cactivi
    AND bf.sseguro  = s.sseguro
    AND bf.cgrup    = bp.codgrup
    AND bf.ctipgrup = 2
    AND bf.nmovimi  = DECODE(s.cramo, 700,
      (SELECT MAX(nmovimi)
      FROM estbf_bonfranseg
      WHERE sseguro = psseguro
      AND nriesgo   = pnriesgo
      ), DECODE(s.cramo, 701,
      (SELECT MAX(nmovimi)
      FROM estbf_bonfranseg
      WHERE sseguro = psseguro
      AND nriesgo   = pnriesgo
      ),
      (SELECT MAX(nmovimi) FROM estbf_bonfranseg bff WHERE bff.sseguro = psseguro
      )))
    AND bd.cgrup    = bf.cgrup
    AND bd.csubgrup = bf.csubgrup
    AND bd.cversion = bf.cversion
    AND bd.cnivel   = bf.cnivel
    AND bd.cgrup    = bn.cgrup
    AND bd.csubgrup = bn.csubgrup
    AND bd.cversion = bn.cversion
    AND bd.cnivel   = bn.cnivel
      --INICIO BUG 37907 - 18/10/2017 LGG
    AND bn.cidioma = 8
    AND bf.nriesgo = pnriesgo;
    --FIN BUG 37907 - 18/10/2017 LGG
    --INI BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
  ELSIF NVL(pmodo, 'POL') = 'CAR' THEN
    --
    SELECT bd.impvalor1 porcded,
      bd.impmin smmlv,
      bn.tnivel
    INTO v_porcded,
      v_smmlv,
      v_tnivel
    FROM bf_progarangrup bp,
      bf_bonfransegcar bf,
      bf_detnivel bd,
      seguros s,
      bf_desnivel bn
    WHERE s.sseguro = psseguro
    AND bf.sproces  = psproces
    AND bp.sproduc  = s.sproduc
    AND bp.cgarant  = pcgarant
    AND bp.cempres  = s.cempres
    AND bp.cactivi  = s.cactivi
    AND bf.sseguro  = s.sseguro
    AND bf.cgrup    = bp.codgrup
    AND bf.ctipgrup = 2
    AND bd.cgrup    = bf.cgrup
    AND bd.csubgrup = bf.csubgrup
    AND bd.cversion = bf.cversion
    AND bd.cnivel   = bf.cnivel
    AND bd.cgrup    = bn.cgrup
    AND bd.csubgrup = bn.csubgrup
    AND bd.cversion = bn.cversion
    AND bd.cnivel   = bn.cnivel
    AND bn.cidioma  = 8
    AND bf.nriesgo  = pnriesgo;
    --
    --FIN BUG 47494 MPC 08/03/2019 Se adiciona condiciÃ³n.
  ELSE
    SELECT bd.impvalor1 porcded,
      bd.impmin smmlv,
      bn.tnivel
    INTO v_porcded,
      v_smmlv,
      v_tnivel
    FROM bf_progarangrup bp,
      bf_bonfranseg bf,
      bf_detnivel bd,
      seguros s,
      bf_desnivel bn
    WHERE s.sseguro = psseguro
    AND bp.sproduc  = s.sproduc
    AND bp.cgarant  = pcgarant
    AND bp.cempres  = s.cempres
    AND bp.cactivi  = s.cactivi
    AND bf.sseguro  = s.sseguro
    AND bf.cgrup    = bp.codgrup
    AND bf.ctipgrup = 2
    AND bf.nmovimi  = DECODE(s.cramo, 700,
      (SELECT MAX(nmovimi)
      FROM bf_bonfranseg
      WHERE sseguro = psseguro
      AND nriesgo   = pnriesgo
      ), DECODE(s.cramo, 701,
      (SELECT MAX(nmovimi)
      FROM bf_bonfranseg
      WHERE sseguro = psseguro
      AND nriesgo   = pnriesgo
      ),
      (SELECT MAX(nmovimi) FROM bf_bonfranseg bff WHERE bff.sseguro = psseguro
      )))
    AND bd.cgrup    = bf.cgrup
    AND bd.csubgrup = bf.csubgrup
    AND bd.cversion = bf.cversion
    AND bd.cnivel   = bf.cnivel
    AND bd.cgrup    = bn.cgrup
    AND bd.csubgrup = bn.csubgrup
    AND bd.cversion = bn.cversion
    AND bd.cnivel   = bn.cnivel
      --INICIO BUG 37907 - 18/10/2017 LGG
    AND bn.cidioma = 8
    AND bf.nriesgo = pnriesgo;
    --FIN BUG 37907 - 18/10/2017 LGG
  END IF;
  -- Columna deducibles
  IF pcampo      = 1 THEN
    IF v_tnivel IS NOT NULL THEN
      v_tlinia  := v_tnivel;
    END IF;
  END IF;
  v_tresult := v_tresult || v_tlinia || '\par ';
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_deducible_xgarantia;
-- FIN  BUG 37907 - 29/09/2017 - LGG
/*****************************************************************
FUNCTION f_importes_riesgo_pyme_mr0
Devuelve los capitales de la caratula cero para una poliza Multiriesgo
Devuelve totalizado por todos los riesgos que tenga la pÃ¿Â¿Ã¿Â³liza
param IN psseguro  : codigo de seguro
param IN pmodo     : modo EST/POL
return             : texto con los capitales del riesgo
BUG 37907 - 04/10/2017 - LGG
******************************************************************/
FUNCTION f_importes_riesgo_pyme_mr0(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL,
    psproces IN NUMBER DEFAULT NULL) --BUG 47494 MPC 08/03/2019 Se adiciona parametro.
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult     VARCHAR2(32000) := '';
    v_tconsulta   VARCHAR2(4000);
    v_tconsulta_1 VARCHAR2(4000) := ''; --BUG 47494 MPC 08/03/2019 Se adiciona variable.
    v_tlinia garangen.tgarant%TYPE;
    v_tpargar VARCHAR2(300);
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot VARCHAR2(200);
    v_ctipcap garanpro.ctipcap%TYPE;
    v_cimpres garanpro.cimpres%TYPE;
    v_tgarant garangen.tgarant%TYPE;
    v_npargar   NUMBER := 0;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
    v_produc seguros.sproduc%TYPE;
    v_norden garanpro.norden%TYPE;
    v_es_admin NUMBER;
    nerror     NUMBER;
    vncertif   NUMBER;
  BEGIN
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := 'select DISTINCT a.sproduc, pp.norden, TRIM(TO_CHAR(SUM(b),''999,999,999,999,999,999'')), TRIM(tgarant) from(SELECT ps.sproduc, s.cgarant, g.tgarant, pac_isqlfor_lcol.f_imporigenomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporigenomon(se.sseguro,ipritot) d';
    ELSE
      v_tconsulta := 'select DISTINCT a.sproduc, pp.norden, TRIM(TO_CHAR(SUM(b),''999,999,999,999,999,999'')), TRIM(tgarant) from(SELECT ps.sproduc, s.cgarant, g.tgarant, pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot)) a, s.icaptot b, p.ctipcap c, p.cimpres,' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0), ' || ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot) d';
    END IF;
    v_tconsulta         := v_tconsulta || ' FROM  garangen g, garanpro p, productos ps, ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' estgaranseg s, estseguros se';
      v_csituac         := '(0,7,5,2,4)';
    ELSE
      --INI BUG 47494 MPC 08/03/2019 Se adiciona filtro.
      IF NVL(pmodo, 'POL') = 'CAR' THEN
        --
        v_tconsulta   := v_tconsulta || ' garancar s, seguros se, seguros so';
        v_tconsulta_1 := ' and s.sproces = '||psproces;
        --
      ELSE
        --FIN BUG 47494 MPC 08/03/2019 Se adiciona filtro.
        v_tconsulta := v_tconsulta || ' garanseg s, seguros se, seguros so';
      END IF; --BUG 47494 MPC 08/03/2019 Se adiciona filtro.
      IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
        v_csituac                                 := '(0,7,5,2)';
      ELSE
        v_csituac := '(0,7,5,2,4)';
      END IF;
    END IF;
    v_tconsulta := v_tconsulta || ' WHERE g.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || v_tconsulta_1; --BUG 47494 MPC 08/03/2019 Se adiciona codigo.
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = ps.sproduc';
    v_tconsulta := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' AND se.csituac in ' || v_csituac;
    v_tconsulta := v_tconsulta || ' AND s.sseguro = so.sseguro';
    v_tconsulta := v_tconsulta || ' AND (p.CGARPADRE IS NULL )';
    --INI BUG 0054043 GZG 12/08/2019
    IF pnmovimi   IS NOT NULL THEN
      v_tconsulta := v_tconsulta || ' AND s.nmovimi = (SELECT max(nmovimi) FROM garanseg where SSEGURO = ' || psseguro || ' and NMOVIMI <= ' || pnmovimi || ')';
    ELSE
      --FIN BUG 0054043 GZG 12/08/2019
      v_tconsulta := v_tconsulta || ' AND FFINEFE IS NULL ';
    END IF;--BUG 0054043 GZG 12/08/2019
    v_tconsulta         := v_tconsulta || ' AND so.npoliza in  (select npoliza from seguros where sseguro in (' || psseguro || '))';
    v_tconsulta         := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_es_admin        := pac_seguros.f_es_col_admin(psseguro, 'EST');
      SELECT ncertif INTO vncertif FROM estseguros WHERE sseguro = psseguro;
    --
    --INI GZG AITSSD-3915 15/07/2025
     IF NVL(pac_parametros.f_parproducto_n(v_produc, 'GARANT_IMP0'), 0) = 1 THEN
        SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
          || sproduc
          || ', '
          || cactivi
          || ', g.cgarant, ''GARANT_IMP2''), 0) = 1 )'
        INTO v_tpargar
        FROM
          (SELECT seg.sproduc,
            seg.cactivi
          FROM estseguros seg
          WHERE seg.sseguro = psseguro
          );
      ELSE
        SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
          || sproduc
          || ', '
          || cactivi
          || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
        INTO v_tpargar
        FROM
          (SELECT seg.sproduc,
            seg.cactivi
          FROM estseguros seg
          WHERE seg.sseguro = psseguro
          );
      END IF;
    --FIN GZG AITSSD-3915 15/07/2025
  ELSE
    v_es_admin := pac_seguros.f_es_col_admin(psseguro, 'POL');
    SELECT ncertif INTO vncertif FROM seguros WHERE sseguro = psseguro;
    --
    --INI GZG AITSSD-3915 15/07/2025
      IF NVL(pac_parametros.f_parproducto_n(v_produc, 'GARANT_IMP0'), 0) = 1 THEN
        SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
          || sproduc
          || ', '
          || cactivi
          || ', g.cgarant, ''GARANT_IMP2''), 0) = 1 )'
        INTO v_tpargar
        FROM
          (SELECT seg.sproduc,
            seg.cactivi
          FROM seguros seg
          WHERE seg.sseguro = psseguro
          );
      ELSE
        SELECT ' AND (NVL(pac_parametros.f_pargaranpro_n('
          || sproduc
          || ', '
          || cactivi
          || ', g.cgarant, ''GARANT_IMP''), 0) = 1 )'
        INTO v_tpargar
        FROM
          (SELECT seg.sproduc,
            seg.cactivi
          FROM seguros seg
          WHERE seg.sseguro = psseguro
          );
      END IF;
    --FIN GZG AITSSD-3915 15/07/2025
  END IF;
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden) a, garanpro pp WHERE a.cgarant=pp.cgarant AND  pp.sproduc = a.sproduc GROUP BY a.sproduc, pp.norden, a.cgarant, a.tgarant ORDER BY pp.norden';
  --p_control_error('LG', 'f_importes_riesgo_pyme_mr0', 'v_tconsulta:' || v_tconsulta);
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_produc, v_norden, v_tlinia, v_tgarant;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF v_npargar = 1 AND v_icaptot = 0 THEN
      SELECT tatribu
      INTO v_tlinia
      FROM detvalores
      WHERE cvalor = 126
      AND catribu  = NVL(v_cimpres, 59)
      AND cidioma  = NVL(pcidioma, 8);
    END IF;
    IF pcampo   = 2 THEN
      v_tlinia := v_tgarant;
    END IF;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_importes_riesgo_pyme_mr0;
-- FIN  BUG 37907 - 04/10/2017 - LGG
/*****************************************************************
FUNCTION f_importes_mov_xriesgo
Devuelve las sumatoria del total de la prima por riesgo para una poliza Pyme MR
param IN psseguro  : codigo de seguro
param IN pnrecibo  : numero de recibo
param IN pcampo    : recupera la cod de la garantias, desc de las garantias, el capital
param IN pmodo     : modo
param IN pnriesgo  : numero de riesgo
return             : texto con las garantias del riesgo
BUG 37907 - 06/10/2017 - LGG
******************************************************************/
FUNCTION f_importes_mov_xriesgo(
    psseguro IN NUMBER,
    pnrecibo IN NUMBER,
    pcampo   IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnriesgo IN NUMBER DEFAULT 1,
    psproces IN NUMBER DEFAULT NULL) --MPC BUG 47494 08/03/2019 Se adiciona filtro.
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult     VARCHAR2(32000) := '';
    v_tconsulta   VARCHAR2(12000);
    v_tconsulta_1 VARCHAR2(12000);       --MPC BUG 47494 08/03/2019 Se adiciona variable.
    v_tconsulta_2 VARCHAR2(12000) := ''; --MPC BUG 47494 08/03/2019 Se adiciona variable.
    v_valor       VARCHAR2(300);
  BEGIN
    --INI BUG 47494 MPC 08/03/2019 Se adiciona filtro.
    IF NVL(pmodo,'POL') = 'CAR' THEN
    --INI BUG 0071197 GZG 01/10/2021 Se agrega parentesis
      v_tconsulta      := 'select TO_CHAR(decode(b.ctiprec,9, sum(a.iconcep_monpol)*-1, sum(a.iconcep_monpol))) valor from detreciboscar a inner join reciboscar b on a.nrecibo = b.nrecibo and a.sproces = b.sproces  ';-- BUG 0053421 22/07/2019 se agrega decode para que salga negativo los extornos en el PDF---
    --FIN BUG 0071197 GZG 01/10/2021
      v_tconsulta_1    := ' and a.sproces = '||psproces;
    ELSE
    --INI AITSSD-6891 GZG 25/11/2025 se retiran los decimales
      v_tconsulta := 'select TO_CHAR(decode(b.ctiprec,9, sum(a.iconcep_monpol)*-1, sum(a.iconcep_monpol)), ''999,999,999,999,999'') valor from detrecibos a inner join recibos b on a.nrecibo = b.nrecibo  ';-- BUG 0053421 22/07/2019 se agrega decode para que salga negativo los extornos en el PDF
    --FIN AITSSD-6891 GZG 25/11/2025
    END IF;
    --FIN BUG 47494 MPC 08/03/2019 Se adiciona filtro.
    --Total Prima Neta (Prima Neta+Prima Devengada Cedida)
    IF pcampo = 1 THEN
      --INI BUG 47494 MPC 08/03/2019 Se modifica codigo.
      v_tconsulta := v_tconsulta ||v_tconsulta_1;
      --v_tconsulta := 'select TO_CHAR(sum(a.iconcep_monpol), ''999,999,999,999,999.99'') valor from detrecibos a inner join recibos b on a.nrecibo = b.nrecibo  ';
      --FIN BUG 47494 MPC 08/03/2019 Se modifica codigo.
      v_tconsulta := v_tconsulta || ' where sseguro = ' || psseguro;
      v_tconsulta := v_tconsulta || ' and a.nrecibo = ' || pnrecibo;
      v_tconsulta := v_tconsulta || ' and cconcep in (0,71)';
      v_tconsulta := v_tconsulta || ' and a.nriesgo=' || pnriesgo;
      v_tconsulta := v_tconsulta || ' group by b.ctiprec '; -- BUG 0053421 22/07/2019 se agrega group by b.ctiprec
    END IF;
    --Asistencia
    IF pcampo = 2 THEN
      --INI BUG 47494 MPC 08/03/2019 Se modifica codigo.
      v_tconsulta := v_tconsulta ||v_tconsulta_1;
      --v_tconsulta := 'select TO_CHAR(sum(a.iconcep_monpol), ''999,999,999,999,999.99'') valor from detrecibos a inner join recibos b on a.nrecibo = b.nrecibo  ';
      --FIN BUG 47494 MPC 08/03/2019 Se modifica codigo.v_tconsulta := v_tconsulta || ' where sseguro = ' || psseguro;
      v_tconsulta := v_tconsulta || ' and cgarant in (3173) ';
      v_tconsulta := v_tconsulta || ' and a.nrecibo = ' || pnrecibo;
      v_tconsulta := v_tconsulta || ' and cconcep in (0,71)';
      v_tconsulta := v_tconsulta || ' and a.nriesgo=' || pnriesgo;
      v_tconsulta := v_tconsulta || ' group by b.ctiprec '; -- BUG 0053421 22/07/2019 se agrega group by b.ctiprec
    END IF;
    --Gastos de Expedicion
    IF pcampo = 3 THEN
      --INI BUG 47494 MPC 08/03/2019 Se modifica codigo.
      v_tconsulta := v_tconsulta ||v_tconsulta_1;
      --v_tconsulta := 'select TO_CHAR(sum(a.iconcep_monpol), ''999,999,999,999,999.99'') valor from detrecibos a inner join recibos b on a.nrecibo = b.nrecibo  ';
      --FIN BUG 47494 MPC 08/03/2019 Se modifica codigo.v_tconsulta := v_tconsulta || ' where sseguro = ' || psseguro;
      v_tconsulta := v_tconsulta || ' and a.nrecibo = ' || pnrecibo;
      v_tconsulta := v_tconsulta || ' and cconcep in (14)';
      v_tconsulta := v_tconsulta || ' and a.nriesgo IN(1,' || pnriesgo|| ')';--BUG 0060023 GZG 13/04/2020
      v_tconsulta := v_tconsulta || ' group by b.ctiprec '; -- BUG 0053421 22/07/2019 se agrega group by b.ctiprec
    END IF;
    --Iva
    IF pcampo = 4 THEN
      --INI BUG 47494 MPC 08/03/2019 Se modifica codigo.
      v_tconsulta := v_tconsulta ||v_tconsulta_1;
      --v_tconsulta := 'select TO_CHAR(sum(a.iconcep_monpol), ''999,999,999,999,999.99'') valor from detrecibos a inner join recibos b on a.nrecibo = b.nrecibo  ';
      --FIN BUG 47494 MPC 08/03/2019 Se modifica codigo.v_tconsulta := v_tconsulta || ' where sseguro = ' || psseguro;
      v_tconsulta := v_tconsulta || ' and a.nrecibo = ' || pnrecibo;
      v_tconsulta := v_tconsulta || ' and cconcep in (4,86)';
      v_tconsulta := v_tconsulta || ' and a.nriesgo=' || pnriesgo;
      v_tconsulta := v_tconsulta || ' group by b.ctiprec '; -- BUG 0053421 22/07/2019 se agrega group by b.ctiprec
    END IF;
    OPEN vr_cursor FOR v_tconsulta;
    LOOP
      IF pcampo IN (1, 2, 3, 4) THEN
        FETCH vr_cursor INTO v_valor;
      EXIT
    WHEN vr_cursor%NOTFOUND;
    END IF;
    --Total Prima Neta
    IF pcampo    = 1 THEN
      v_tresult := v_tresult || v_valor || '\par ';
    END IF;
    --Asistencia
    IF pcampo    = 2 THEN
      v_tresult := v_tresult || v_valor || '\par ';
    END IF;
    --Gastos Expedicion
    IF pcampo    = 3 THEN
      v_tresult := v_tresult || v_valor || '\par ';
    END IF;
    --Iva
    IF pcampo    = 4 THEN
      v_tresult := v_tresult || v_valor || '\par ';
    END IF;
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ' ';
END f_importes_mov_xriesgo;
---BUG 37907 - 06/10/2017 - LGG
/*****************************************************************
FUNCTION f_amp_vig_cump
Devuelve descripciones y valores de las vigencias de los amparos de un riesgo para Cumplimiento
param IN psseguro  : codigo de seguro
param IN pcidioma  : codigo de idioma
param IN pcampo    : recupera la cod de la garantias, desc de las garantias, el capital
param IN pmodo     : modo EST/POL
return             : texto con las garantias del riesgo
INICIO BUG 37912 - LGG
INICIO BUG 38748 - LGG
******************************************************************/
FUNCTION f_amp_vig_cump(
    psseguro IN NUMBER,
    pcidioma IN NUMBER DEFAULT 1,
    pcampo   IN NUMBER DEFAULT 1,
    ptipo    IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pcgarant IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pnmovimi IN NUMBER DEFAULT NULL,
    psproces IN NUMBER DEFAULT NULL) --BUG 47494 MPC 08/03/2019 Se adiciona filtro.
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult     VARCHAR2(32000) := '';
    v_tconsulta   VARCHAR2(4000);
    v_tconsulta_1 VARCHAR2(4000) := 'SELECT substr(gr.CRESPUE,7,2)||''/''||substr(gr.CRESPUE,5,2)||''/''||substr(gr.CRESPUE,1,4) crespue ' || '    FROM ' || '      garangen g, ' || '      garanpro p, ' || '      productos ps, ' || '      garanseg s, ' || '      seguros se, ' || '      seguros so, ' || '      pregungaranseg gr ' || '    WHERE ' || '      g.cgarant     = s.cgarant ' || '    AND p.cgarant   = s.cgarant ' || '    AND p.sproduc   = se.sproduc ' || '    AND s.sseguro   = se.sseguro ' || '    AND p.sproduc   = ps.sproduc ' || '    AND p.cactivi   = se.cactivi '; --BUG 47494 MPC 08/03/2019 Se crea nueva variable.
    v_tconsulta_2 VARCHAR2(4000) := '    AND s.nmovimi = ' || pnmovimi;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            --BUG 47494 MPC 08/03/2019 Se crea nueva variable.
    v_tablaseg    VARCHAR2(30);
    v_act0        NUMBER(1);
    v_actividad   VARCHAR2(20);
    v_cgarant     VARCHAR2(300);
    v_tgarant     VARCHAR2(3000);
    v_cpregun     VARCHAR2(300);
    v_crespue     VARCHAR2(300);
    v_csituac     VARCHAR2(100);
  BEGIN
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 's.cactivi';
    END IF;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' estgaranseg s, estseguros se';
      v_csituac         := '(0,7,5,2,4)';
    ELSE
      --INI BUG 47494 MPC 08/03/2019 Se adicion condiciÃ³n.
      IF NVL(pmodo, 'POL') = 'CAR' THEN
        --
        v_tconsulta   := v_tconsulta || ' garancar s, seguros se, seguros so';
        v_tconsulta_1 := 'SELECT substr(gr.CRESPUE,7,2)||''/''||substr(gr.CRESPUE,5,2)||''/''||substr(gr.CRESPUE,1,4) crespue ' || '    FROM ' || '      garangen g, ' || '      garanpro p, ' || '      productos ps, ' || '      garancar s, ' || '      seguros se, ' || '      seguros so, ' || '      pregungaranseg gr ' || '    WHERE ' || '      g.cgarant     = s.cgarant ' || '    AND p.cgarant   = s.cgarant ' || '    AND p.sproduc   = se.sproduc ' || '    AND s.sseguro   = se.sseguro ' || '    AND p.sproduc   = ps.sproduc ' || '    AND p.cactivi   = se.cactivi '; --BUG 47494 MPC 08/03/2019 Se crea nueva variable.
        v_tconsulta_2 := ' AND s.sproces = ' || psproces;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               --BUG 47494 MPC 08/03/2019 Se crea nueva variable.
        --
      ELSE
        --FIN BUG 47494 MPC 08/03/2019 Se adicion condiciÃ³n.
        v_tconsulta := v_tconsulta || ' garanseg s, seguros se, seguros so';
      END IF; --BUG 47494 MPC 08/03/2019 Se adicion condiciÃ³n.
      IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
        v_csituac                                 := '(0,7,5,2)';
      ELSE
        v_csituac := '(0,7,5,2,4)';
      END IF;
    END IF;
    --INI BUG 47494 MPC 08/03/2019 Se modifica condiciÃ³n.
    v_tconsulta := v_tconsulta_1;
    --v_tconsulta := 'SELECT substr(gr.CRESPUE,7,2)||''/''||substr(gr.CRESPUE,5,2)||''/''||substr(gr.CRESPUE,1,4) crespue ' || '    FROM ' || '      garangen g, ' || '      garanpro p, ' || '      productos ps, ' || '      garanseg s, ' || '      seguros se, ' || '      seguros so, ' || '      pregungaranseg gr ' || '    WHERE ' || '      g.cgarant     = s.cgarant ' || '    AND p.cgarant   = s.cgarant ' || '    AND p.sproduc   = se.sproduc ' || '    AND s.sseguro   = se.sseguro ' || '    AND p.sproduc   = ps.sproduc ' || '    AND p.cactivi   = se.cactivi ';
    --FIN BUG 47494 MPC 08/03/2019 Se modifica condiciÃ³n.
    v_tconsulta := v_tconsulta || '    AND se.csituac IN ' || v_csituac || '    AND s.sseguro   = so.sseguro ' || '    AND ' || '      ( ' || '        p.CGARPADRE IS NULL ' || '      ) ' || '    AND so.npoliza IN ' || '      ( ' || '        SELECT  npoliza' || '        FROM  seguros' || '        WHERE ';
    v_tconsulta := v_tconsulta || '  sseguro IN ( ' || psseguro || ' )' || '      ) ' || '    AND g.cidioma = ' || pcidioma;
    v_tconsulta := v_tconsulta || '    AND s.nriesgo = ' || pnriesgo;
    --INI BUG 47494 MPC 08/03/2019 Se modifica condiciÃ³n.
    --v_tconsulta := v_tconsulta || '    AND s.nmovimi = ' || pnmovimi;
    v_tconsulta := v_tconsulta || v_tconsulta_2;
    --FIN BUG 47494 MPC 08/03/2019 Se modifica condiciÃ³n.
    v_tconsulta := v_tconsulta || '    AND s.sseguro  =gr.sseguro ' || '    AND se.sseguro  =gr.sseguro ' || '    AND g.cgarant  =gr.cgarant ';
    --Valores de Fecha Inicio
    IF ptipo       = 1 THEN
      v_tconsulta := v_tconsulta || ' and gr.CPREGUN in (6020) ';
      v_tconsulta := v_tconsulta || ' and gr.cgarant = ' || pcgarant;
      --INICIO BUG 38748 - 24/10/2017 - LG
      v_tconsulta := v_tconsulta || ' and gr.nmovimi =  ' || pnmovimi;
      --FIN BUG 38748 - 24/10/2017 - LG
    END IF;
    --Valores de Fecha Fin
    IF ptipo       = 2 THEN
      v_tconsulta := v_tconsulta || ' and gr.CPREGUN in (6021) ';
      v_tconsulta := v_tconsulta || ' and gr.cgarant = ' || pcgarant;
      --INICIO BUG 38748 - 24/10/2017 - LG
      v_tconsulta := v_tconsulta || ' and gr.nmovimi =  ' || pnmovimi;
      --FIN BUG 38748 - 24/10/2017 - LG
    END IF;
    --P_CONTROL_ERROR('LG','f_amp_vig_cump','v_tconsulta:'||v_tconsulta);
    OPEN vr_cursor FOR v_tconsulta;
    LOOP
      FETCH vr_cursor INTO v_crespue;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF pcampo    = 1 THEN
      v_tresult := v_tresult || v_crespue || '\par ';
    END IF;
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ' ';
END f_amp_vig_cump;
--FIN BUG 37912 - LGG
--FIN BUG 38728 - LGG
/*****************************************************************
FUNCTION f_importes_riesgo_vig_certif0
Devuelve totalizados los valores por todos los certiticados que tiene
la poliza con vigencia
Devuelve los capitales de un riesgo, la prima
param IN psseguro  : codigo de seguro
param IN pnriesgo  : numero de riesgo
param IN pmodo     : modo EST/POL
return             : texto con los capitales del riesgo
BUG 37912 - 19/09/2017 - LGG
BUG 37913 - 21/09/2017 - LGG
BUG 38478 - 19/10/2017 - LGG
BUG 38748 - 24/10/2017 - LGG
******************************************************************/
FUNCTION f_importes_riesgo_vig_certif0(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL,
    psproces IN NUMBER DEFAULT NULL) --BUG 47494 08/03/2019 MPC Se adiciona parametro de entrada.
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult     VARCHAR2(32000) := '';
    v_tconsulta   VARCHAR2(4000);
    v_tconsulta_1 VARCHAR2(4000) := ' AND s.nmovimi = decode(so.csituac,2,'||(pnmovimi-1)||','||pnmovimi||')'; --BUG 47494 MPC 08/03/2019 Se adiciona variable
    v_tlinia garangen.tgarant%TYPE;
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot VARCHAR2(200);
    v_ctipcap garanpro.ctipcap%TYPE;
    v_cimpres garanpro.cimpres%TYPE;
    v_tgarant garangen.tgarant%TYPE;
    v_npargar   NUMBER := 0;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
    v_produc seguros.sproduc%TYPE;
    v_norden garanpro.norden%TYPE;
    v_es_admin NUMBER;
    nerror     NUMBER;
    vncertif   NUMBER;
    v_fechaini VARCHAR2(20);
    v_fechafin VARCHAR2(20);
    v_itotaseg VARCHAR2(100);
    --INICIO - BUG 37912 - 19/09/2017 - LGG
    v_cgarant garangen.cgarant%TYPE;
    v_porcded NUMBER;
    v_smmlv   NUMBER;
    v_tnivel  VARCHAR2(200);
    --FIN - BUG 37912 - 19/09/2017 - LGG
    --INICIO - BUG 38478 - 19/10/2017 - LGG
    vtotaseg  NUMBER;
    vtotaseg1 NUMBER := 0;
    --FIN - BUG 38478 - 19/10/2017 - LGG
  BEGIN
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := 'SELECT DISTINCT ' || '  a.sproduc, ' || '  pp.norden, ' ||                                                                                                                                                                           --INICIO - BUG 37912 - 19/09/2017 - LGG
      '  a.cgarant, ' ||                                                                                                                                                                                                                                         --FIN - BUG 37912 - 19/09/2017 - LGG
      '  TRIM(TO_CHAR(SUM(b),''999,999,999,999,999,999'')), ' || '  TRIM(TO_CHAR(SUM(dd),''999,999,999,999,999,999'')), ' || '  TRIM(tgarant), ' || '  fechaini, ' || '  fechafin, ' || '  TRIM(TO_CHAR(SUM(totaseg),''999,999,999,999,999,999'')) totaseg, ' || --INICIO - BUG 38478 - 19/10/2017 - LGG
      --'  deducible ';
      '  deducible, ' || '  totaseg ';
      --FIN - BUG 38478 - 19/10/2017 - LGG
      v_tconsulta := v_tconsulta || ' FROM ( ';
      v_tconsulta := v_tconsulta || '    SELECT ps.sproduc, s.cgarant, g.tgarant,';
      v_tconsulta := v_tconsulta || '      pac_isqlfor_lcol.f_imporignomon(se.sseguro,(DECODE(s.cgarant,4,' || NVL(pcidioma, 1);
      v_tconsulta := v_tconsulta || '      , se.cforpag,1)*icaptot)) a, ';
      v_tconsulta := v_tconsulta || '      s.icaptot b, ';
      v_tconsulta := v_tconsulta || '      p.ctipcap c, ';
      v_tconsulta := v_tconsulta || '      p.cimpres, ';
      v_tconsulta := v_tconsulta || '      NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant, ';
      v_tconsulta := v_tconsulta || '      ''GARANT_IMP''), 0), ';
      v_tconsulta := v_tconsulta || '      pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot) d, ';
      v_tconsulta := v_tconsulta || '      s.ipritot dd, ';
      v_tconsulta := v_tconsulta || '      REPLACE(pac_isqlfor_lcol.f_amp_vig_cump(se.sseguro, ' || pcidioma || ' ,1,1,''POL'',s.cgarant,' || pnriesgo || ' ,' || pnmovimi || '),''"'','''') fechaini, ';
      v_tconsulta := v_tconsulta || '      REPLACE(pac_isqlfor_lcol.f_amp_vig_cump(se.sseguro, ' || pcidioma || ' ,1,2,''POL'',s.cgarant,' || pnriesgo || ' ,' || pnmovimi || '),''"'','''') fechafin, ';
      --INICIO - BUG 37912 - 28/09/2017 - LGG
      --v_tconsulta := v_tconsulta ||'      s.icaptot totaseg ';
      v_tconsulta := v_tconsulta || '      s.icaptot totaseg, ';
      v_tconsulta := v_tconsulta || '      pac_isqlfor_lcol.f_deducible_vig_certif0(se.sseguro,1,' || pnriesgo || ' ,''POL'',g.cgarant) deducible';
      --FIN - BUG 37912 - 28/09/2017 - LGG
    ELSE
      v_tconsulta := 'SELECT DISTINCT ' || '  a.sproduc, ' || '  pp.norden, ' ||                                                                                                                                                                                  --INICIO - BUG 37912 - 19/09/2017 - LGG
      '  a.cgarant, ' ||                                                                                                                                                                                                                                          --FIN - BUG 37912 - 19/09/2017 - LGG
      '  TRIM(TO_CHAR(SUM(b),''999,999,999,999,999,999'')), ' || '  TRIM(TO_CHAR(SUM(dd),''999,999,999,999,999,999'')), ' || '  TRIM(tgarant), ' || '  fechaini, ' || '  fechafin,  ' || '  TRIM(TO_CHAR(SUM(totaseg),''999,999,999,999,999,999'')) totaseg, ' || --INICIO - BUG 38478 - 19/10/2017 - LGG
      --'  deducible ';
      '  deducible, ' || '  totaseg ';
      --FIN - BUG 38478 - 19/10/2017 - LGG
      v_tconsulta := v_tconsulta || ' FROM ( ';
      v_tconsulta := v_tconsulta || '    SELECT ps.sproduc, s.cgarant, g.tgarant,';
      v_tconsulta := v_tconsulta || '      pac_isqlfor_lcol.f_imporignomon(se.sseguro,(DECODE(s.cgarant,4,' || NVL(pcidioma, 1);
      v_tconsulta := v_tconsulta || '      , se.cforpag,1)*icaptot)) a, ';
      v_tconsulta := v_tconsulta || '      s.icaptot b, ';
      v_tconsulta := v_tconsulta || '      p.ctipcap c, ';
      v_tconsulta := v_tconsulta || '      p.cimpres, ';
      v_tconsulta := v_tconsulta || '      NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant, ';
      v_tconsulta := v_tconsulta || '      ''GARANT_IMP''), 0), ';
      v_tconsulta := v_tconsulta || '      pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot) d, ';
      v_tconsulta := v_tconsulta || '      s.ipritot dd, ';
      --INI BUG 47494 MPC 08/03/2019 Se adiciona condicion.
      IF NVL(pmodo, 'POL') = 'CAR' THEN
        --
        v_tconsulta := v_tconsulta || '      REPLACE(pac_isqlfor_lcol.f_amp_vig_cump(se.sseguro, ' || pcidioma || ' ,1,1,''CAR'',s.cgarant,' || pnriesgo || ' ,' || pnmovimi || ','||psproces||'),''"'','''') fechaini, ';
        v_tconsulta := v_tconsulta || '      REPLACE(pac_isqlfor_lcol.f_amp_vig_cump(se.sseguro, ' || pcidioma || ' ,1,2,''CAR'',s.cgarant,' || pnriesgo || ' ,' || pnmovimi || ','||psproces||'),''"'','''') fechafin, ';
        --
      ELSE
        --FIN BUG 47494 MPC 08/03/2019 Se adiciona condicion.
        v_tconsulta := v_tconsulta || '      REPLACE(pac_isqlfor_lcol.f_amp_vig_cump(se.sseguro, ' || pcidioma || ' ,1,1,''POL'',s.cgarant,' || pnriesgo || ' ,' || pnmovimi || '),''"'','''') fechaini, ';
        v_tconsulta := v_tconsulta || '      REPLACE(pac_isqlfor_lcol.f_amp_vig_cump(se.sseguro, ' || pcidioma || ' ,1,2,''POL'',s.cgarant,' || pnriesgo || ' ,' || pnmovimi || '),''"'','''') fechafin, ';
      END IF; --BUG 47494 MPC 08/03/2019 Se adiciona condicion.
      --INICIO - BUG 37912 - 28/09/2017 - LGG
      --v_tconsulta := v_tconsulta ||'      s.icaptot totaseg ';
      v_tconsulta := v_tconsulta || '      s.icaptot totaseg, ';
      v_tconsulta := v_tconsulta || '      pac_isqlfor_lcol.f_deducible_vig_certif0(se.sseguro,1,' || pnriesgo || ' ,''POL'',g.cgarant) deducible';
      --FIN - BUG 37912 - 28/09/2017 - LGG
    END IF;
    v_tconsulta         := v_tconsulta || ' FROM  garangen g, garanpro p, productos ps, ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' estgaranseg s, estseguros se';
      v_csituac         := '(0,7,5,2,4)';
    ELSE
      --INICIO - BUG 37912 - 02/10/2017 - LGG
      /*
      v_tconsulta := v_tconsulta || ' garanseg s, seguros se, seguros so';
      IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
      v_csituac := '(0,7,5,2)';
      ELSE
      v_csituac := '(0,7,5,2,4)';
      END IF;
      */
      --FIN - BUG 37912 - 02/10/2017 - LGG
      --INI BUG 47494 MPC 08/03/2019 Se adiciona codigo.
      IF NVL(pmodo, 'POL') = 'CAR' THEN
        --
        v_tconsulta   := v_tconsulta || ' garancar s, seguros se, seguros so';
        v_tconsulta_1 := ' AND sproces = '||psproces;
        --
      ELSE
        --FIN BUG 47494 MPC 08/03/2019 Se adiciona codigo.
        v_tconsulta := v_tconsulta || ' garanseg s, seguros se, seguros so';
      END IF; --BUG 47494 MPC 08/03/2019 Se adiciona codigo.
      v_csituac := '(0,7,5,2,4)';
    END IF;
    v_tconsulta := v_tconsulta || ' WHERE g.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.cgarant = s.cgarant';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta := v_tconsulta || ' AND p.sproduc = ps.sproduc';
    v_tconsulta := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
    v_tconsulta := v_tconsulta || ' AND se.csituac in ' || v_csituac;
    v_tconsulta := v_tconsulta || ' AND s.sseguro = so.sseguro';
    v_tconsulta := v_tconsulta || ' AND (p.CGARPADRE IS NULL )';
    v_tconsulta := v_tconsulta || ' AND so.npoliza in  (select npoliza from seguros where sseguro in (' || psseguro || '))';
    v_tconsulta := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
    v_tconsulta := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    --INI BUG 47494 MPC 08/03/2019 Se modifica filtro.
    v_tconsulta := v_tconsulta || v_tconsulta_1;
    --v_tconsulta := v_tconsulta || ' AND s.nmovimi = decode(so.csituac,2,'||(pnmovimi-1)||','||pnmovimi||')'; --jfn 18082018 QT45177
    --FIN BUG 47494 MPC 08/03/2019 Se modifica filtro.
    v_tconsulta := v_tconsulta || ' ORDER BY p.norden) a, garanpro pp WHERE a.cgarant=pp.cgarant AND  pp.sproduc = a.sproduc GROUP BY a.sproduc, pp.norden, a.cgarant, a.tgarant, a.fechaini,  a.fechafin, a.totaseg, a.deducible ORDER BY pp.norden';
    --p_control_error('LG', 'f_importes_riesgo_vig_certif0', 'v_tconsulta:' || v_tconsulta);
    OPEN vr_cursor FOR v_tconsulta;
    LOOP
      FETCH vr_cursor
        --INICIO - BUG 38748 - 24/10/2017 - LGG
        --INTO v_produc, v_norden, v_cgarant, v_tlinia, v_ipritot, v_tgarant, v_fechaini, v_fechafin, v_itotaseg,v_tnivel,vtotaseg;
      INTO v_produc,
        v_norden,
        v_cgarant,
        v_tlinia,
        v_ipritot,
        v_tgarant,
        v_fechaini,
        v_fechafin,
        v_itotaseg,
        v_tnivel,
        vtotaseg;
    --FIN - BUG 38748 - 24/10/2017 - LGG
    EXIT
  WHEN vr_cursor%NOTFOUND;
    BEGIN
      --INICIO - BUG 38748 - 24/10/2017 - LGG
      --Valor asegurado
      IF pcampo = 4 AND v_icaptot = 0 THEN
        SELECT tatribu
        INTO v_tlinia
        FROM detvalores
        WHERE cvalor = 126
        AND catribu  = NVL(v_cimpres, 59)
        AND cidioma  = NVL(pcidioma, 8);
      END IF;
      --Prima
      IF pcampo   = 5 THEN
        v_tlinia := v_ipritot;
      END IF;
      --amparo
      IF pcampo   = 6 THEN
        v_tlinia := v_tgarant;
      END IF;
      --Fecha Inicial
      IF pcampo   = 7 THEN
        v_tlinia := v_fechaini;
      END IF;
      --Fecha Final
      IF pcampo   = 8 THEN
        v_tlinia := v_fechafin;
      END IF;
      --IF pcampo = 6 THEN
      IF pcampo   = 9 THEN
        v_tlinia := v_itotaseg;
      END IF;
      ---INICIO - BUG 37912 - 19/09/2017 - LGG
      -- Columna deducibles
      IF pcampo      = 10 THEN
        IF v_tnivel IS NOT NULL THEN
          v_tlinia  := v_tnivel;
        ELSE
          v_tlinia := ' ';
        END IF;
      END IF;
      ---FIN - BUG 37912 - 19/09/2017 - LGG
      --Valor total asegurado a mostrar en el certificado
      IF pcampo    = 11 THEN
        vtotaseg1 := vtotaseg1 + vtotaseg;
      END IF;
    EXCEPTION
    WHEN OTHERS THEN
      v_tlinia := ' ';
    END;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  --Valor total asegurado a mostrar en el certificado
  IF pcampo    = 11 THEN
    v_tlinia  := TRIM(TO_CHAR(vtotaseg1, '999,999,999,999,999,999'));
    v_tresult := v_tlinia || '\par ';
  END IF;
  --FIN - BUG 38748 - 24/10/2017 - LGG
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  p_control_error('LG', 'f_importes_riesgo_vig_certif0', 'EXCEPTION: Ultima ');
  RETURN ('');
END f_importes_riesgo_vig_certif0;
-- FIN  BUG 37912 - 19/09/2017 - LGG
-- FIN  BUG 37913 - 21/09/2017 - LGG
-- FIN  BUG 38478 - 19/10/2017 - LGG
-- FIN  BUG 38748 - 24/10/2017 - LGG
/*****************************************************************
FUNCTION f_objeto_contrato
Devuelve el objeto del contrato de una poliza
param IN psseguro  : codigo de seguro
param IN pnmovimi  : numero de Movimiento
return             : texto con las informaciÃ¿Â³n del objeto contrato
BUG 37912 - 13/09/2017 - LGG
BUG 38863 - 27/10/2017 - LGG
******************************************************************/
--INI JFN CUMPLI_17012018 QT39750
FUNCTION f_objeto_contrato(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER DEFAULT 1)
  --INICIO BUG 38863 - 27/10/2017 - LGG
  --RETURN VARCHAR2 IS
  RETURN CLOB
IS
  V_OBJETO VARCHAR2 (32000);
  --FIN BUG 38863 - 27/10/2017 - LGG
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    --v_tresult      VARCHAR2(32000) := '';
    v_tresult CLOB := '';
    v_tconsulta VARCHAR2(4000);
    v_trespue   VARCHAR2(4000);
  BEGIN
    BEGIN--Bug 40064 - YMG (06/03/2018)
      SELECT PAC_CLAUSULAS.f_get_descclausulapar (CG.SCLAGEN, psseguro, 8)
      INTO V_OBJETO
      FROM clausugen cg,
        clausuesp c,
        seguros s
      WHERE s.sseguro = c.sseguro
      AND cg.sclagen  = c.sclagen
      AND c.sseguro   = psseguro
        --                                  AND c.nmovimi = pnmovimi
      AND c.nmovimi =
        (SELECT MAX (nmovimi)
        FROM clausuesp
        WHERE sseguro = psseguro
        AND nmovimi  <= pnmovimi
        AND sclagen  IS NOT NULL
        )
    AND c.sclagen IS NOT NULL
    AND cg.cidioma = 8
    AND (s.cramo  <> 103
    OR ncertif     = 0);
    --Inicio bug 0040064 - YMG (06/03/2018)
  EXCEPTION
  WHEN OTHERS THEN
    v_objeto := '';
  END;
  --Fin bug 0040064 - YMG (06/03/2018)
  v_tconsulta := 'select trespue from pregunpolseg  ';
  v_tconsulta := v_tconsulta || ' where cpregun in (6059,6072,9227,9228,9946) and sseguro = ' || psseguro;
  v_tconsulta := v_tconsulta || ' and nmovimi = ' || pnmovimi;
  v_tconsulta := v_tconsulta || ' order by cpregun  ';
  --p_control_error('LG', 'f_objeto_contrato', 'v_tconsulta:' || v_tconsulta);
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_trespue;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    v_tresult := v_tresult || v_trespue || ' ';
  END LOOP;
  --INICIO BUG 38863 - 27/10/2017 - LGG
  --RETURN(f_jrep_trad(v_tresult));
  RETURN (f_jrep_trad_pyme (V_OBJETO || ' ' || v_tresult));
  --FIN BUG 38863 - 27/10/2017 - LGG
EXCEPTION
WHEN OTHERS THEN
  RETURN ' ';
END f_objeto_contrato;
--FIN JFN CUMPLI_17012018 QT39750
--FIN  BUG 37912 - 13/09/2017 - LGG
--FIN  BUG 38863 - 27/10/2017 - LGG
/*****************************************************************
FUNCTION f_listaprovpoblac
Devuelve el lugar de ejecuciÃ¿Â³n de una poblaciÃ¿Â³n y provincia
param IN psseguro  : codigo de seguro
param IN pnmovimi  : numero de Movimiento
param IN pnriesgo  : numero de riesgo
param IN pcodpropo : codigo de la provincia + poblacion
param IN pcampo    : codigo del campo 1=lugar 2=Ciudad
return             : Lugar de ejecuciÃ¿Â³n de una poblaciÃ¿Â³n y provincia
BUG 37912 - 19/09/2017 - LGG
BUG 37913 - 15/09/2017 - LGG
******************************************************************/
FUNCTION f_listaprovpoblac(
    psseguro  IN NUMBER,
    pnmovimi  IN NUMBER DEFAULT 1,
    pnriesgo  IN NUMBER DEFAULT 1,
    pcodpropo IN VARCHAR2,
    pcampo    IN NUMBER)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(4000);
    v_lugar     VARCHAR2(4000);
    v_tpoblac   VARCHAR2(4000);
  BEGIN
    v_tconsulta := ' SELECT  pr.tprovin  || '' - '' || po.tpoblac b, ';
    v_tconsulta := v_tconsulta || ' po.tpoblac ';
    v_tconsulta := v_tconsulta || ' FROM ';
    v_tconsulta := v_tconsulta || '  poblaciones po, ';
    v_tconsulta := v_tconsulta || '  provincias pr ';
    v_tconsulta := v_tconsulta || ' WHERE po.cprovin = pr.cprovin ';
    v_tconsulta := v_tconsulta || ' AND pr.cpais = 170 ';
    v_tconsulta := v_tconsulta || 'and lpad(po.cprovin*1000 + po.cpoblac,5,''0'')=' || pcodpropo;
    v_tconsulta := v_tconsulta || ' ORDER BY ';
    v_tconsulta := v_tconsulta || '  TRANSLATE(UPPER(pr.tprovin), ''Ã¿ÂÃ¿Â¿Ã¿ÂÃ¿Â¿Ã¿Â¿'',''AEIOU'') ';
    v_tconsulta := v_tconsulta || '  || '' - '' ';
    v_tconsulta := v_tconsulta || '  || TRANSLATE(UPPER(po.tpoblac),''Ã¿ÂÃ¿Â¿Ã¿ÂÃ¿Â¿Ã¿Â¿'',''AEIOU'') ';
    OPEN vr_cursor FOR v_tconsulta;
    LOOP
      FETCH vr_cursor INTO v_lugar, v_tpoblac;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF pcampo    = 1 THEN
      v_tresult := v_tresult || v_lugar || '\par ';
    END IF;
    IF pcampo    = 2 THEN
      v_tresult := v_tresult || v_tpoblac || '\par ';
    END IF;
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ' ';
END f_listaprovpoblac;
--FIN  BUG 37912 - 19/09/2017 - LGG
--FIN  BUG 37913 - 15/09/2017 - LGG
/*****************************************************************
FUNCTION f_deducible_vig_certif0
Devuelve la descripciÃ¿Â³n del deducible para una garantia
Devuelve los capitales de un riesgo, la prima
param IN psseguro  : codigo de seguro
param IN pnriesgo  : numero de riesgo
param IN pmodo     : modo EST/POL
return             : texto con los capitales del riesgo
BUG 37912 - 19/09/2017 - LGG
******************************************************************/
FUNCTION f_deducible_vig_certif0(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pcgarant IN garangen.cgarant%TYPE)
  RETURN VARCHAR2
IS
  v_tresult VARCHAR2(32000) := '';
  v_tlinia garangen.tgarant%TYPE;
  v_porcded NUMBER;
  v_smmlv   NUMBER;
  v_tnivel  VARCHAR2(200);
BEGIN
  IF NVL(pmodo, 'POL') = 'EST' THEN
    SELECT bd.impvalor1 porcded,
      bd.impmin smmlv,
      bn.tnivel
    INTO v_porcded,
      v_smmlv,
      v_tnivel
    FROM bf_progarangrup bp,
      estbf_bonfranseg bf,
      bf_detnivel bd,
      estseguros s,
      bf_desnivel bn
    WHERE s.sseguro = psseguro
    AND bp.sproduc  = s.sproduc
    AND bp.cgarant  = pcgarant
    AND bp.cempres  = s.cempres
    AND bp.cactivi  = s.cactivi
    AND bf.sseguro  = s.sseguro
    AND bf.cgrup    = bp.codgrup
    AND bf.ctipgrup = 2
    AND bf.nmovimi  = DECODE(s.cramo, 700,
      (SELECT MAX(nmovimi)
      FROM estbf_bonfranseg
      WHERE sseguro = psseguro
      AND nriesgo   = pnriesgo
      ), DECODE(s.cramo, 701,
      (SELECT MAX(nmovimi)
      FROM estbf_bonfranseg
      WHERE sseguro = psseguro
      AND nriesgo   = pnriesgo
      ),
      (SELECT MAX(nmovimi) FROM estbf_bonfranseg bff WHERE bff.sseguro = psseguro
      )))
    AND bd.cgrup    = bf.cgrup
    AND bd.csubgrup = bf.csubgrup
    AND bd.cversion = bf.cversion
    AND bd.cnivel   = bf.cnivel
    AND bd.cgrup    = bn.cgrup
    AND bd.csubgrup = bn.csubgrup
    AND bd.cversion = bn.cversion
    AND bd.cnivel   = bn.cnivel
    AND bn.cidioma  = 8;
  ELSE
    p_control_error('LG', 'f_importes_riesgo_vig_certif0', 'ENTRO ELSE P2 - 3');
    SELECT bd.impvalor1 porcded,
      bd.impmin smmlv,
      bn.tnivel
    INTO v_porcded,
      v_smmlv,
      v_tnivel
    FROM bf_progarangrup bp,
      bf_bonfranseg bf,
      bf_detnivel bd,
      seguros s,
      bf_desnivel bn
    WHERE s.sseguro = psseguro
    AND bp.sproduc  = s.sproduc
    AND bp.cgarant  = pcgarant
    AND bp.cempres  = s.cempres
    AND bp.cactivi  = s.cactivi
    AND bf.sseguro  = s.sseguro
    AND bf.cgrup    = bp.codgrup
    AND bf.ctipgrup = 2
    AND bf.nmovimi  = DECODE(s.cramo, 700,
      (SELECT MAX(nmovimi)
      FROM bf_bonfranseg
      WHERE sseguro = psseguro
      AND nriesgo   = pnriesgo
      ), DECODE(s.cramo, 701,
      (SELECT MAX(nmovimi)
      FROM bf_bonfranseg
      WHERE sseguro = psseguro
      AND nriesgo   = pnriesgo
      ),
      (SELECT MAX(nmovimi) FROM bf_bonfranseg bff WHERE bff.sseguro = psseguro
      )))
    AND bd.cgrup    = bf.cgrup
    AND bd.csubgrup = bf.csubgrup
    AND bd.cversion = bf.cversion
    AND bd.cnivel   = bf.cnivel
    AND bd.cgrup    = bn.cgrup
    AND bd.csubgrup = bn.csubgrup
    AND bd.cversion = bn.cversion
    AND bd.cnivel   = bn.cnivel
    AND bn.cidioma  = 8;
    --p_control_error('LG', 'f_importes_riesgo_vig_certif0', 'v_porcded:' || v_porcded);
    --p_control_error('LG', 'f_importes_riesgo_vig_certif0', 'v_porcded:' || v_porcded);
  END IF;
  -- Columna deducibles
  IF pcampo      = 1 THEN
    IF v_tnivel IS NOT NULL THEN
      v_tlinia  := v_tnivel;
    END IF;
  END IF;
  /*
  EXCEPTION
  WHEN OTHERS THEN
  v_tlinia := ' ';
  END;
  */
  v_tresult := v_tresult || v_tlinia || '\par ';
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_deducible_vig_certif0;
-- FIN  BUG 37912 - 19/09/2017 - LGG
/*****************************************************************
FUNCTION f_listatipoContratos
Devuelve el lugar de ejecuciÃ¿Â³n de una poblaciÃ¿Â³n y provincia
param IN ppoliza  : codigo de poliza
param IN pcodigo  : codigo de la provincia + poblacion
param IN pcampo   : codigo del campo 1=lugar 2=Ciudad
return            : DescripciÃ¿Â³n del tipo de contrato
BUG 37912 - 02/10/2017 - LGG
BUG 37913 - 02/10/2017 - LGG
******************************************************************/
FUNCTION f_listatipocontratos(
    ppoliza IN NUMBER,
    pcodigo IN VARCHAR2)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult    VARCHAR2(32000) := '';
    v_tconsulta  VARCHAR2(32000);
    v_tconsulta1 VARCHAR2(32000);
    v_tconsulta2 CLOB;
    v_codigo  VARCHAR2(30);
    v_descrip VARCHAR2(4000);
  BEGIN
    v_tconsulta := 'select distinct ccla3, nval7
from sgt_subtabs_det d
where d.csubtabla = 3158
and d.cversubt = (select max(cversubt)
from sgt_subtabs_ver v
where v.csubtabla = d.csubtabla
and v.fefecto <= f_sysdate)';
    v_tconsulta := v_tconsulta || ' and ccla3=' || pcodigo;
    v_tconsulta := v_tconsulta || ' order by 1 asc ';
    --p_control_error('LG', 'f_listatipoContratos', 'v_tconsulta: ' || v_tconsulta);
    OPEN vr_cursor FOR v_tconsulta;
    LOOP
      FETCH vr_cursor INTO v_codigo, v_descrip;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    v_tresult := v_tresult || v_descrip || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ' ';
END f_listatipocontratos;
