--FIN  BUG 37913 - 02/10/2017 - LGG
/*****************************************************************
FUNCTION f_coaseguro_anexo
Devuelve totalizados los valores por todos los certiticados que tiene
la poliza con vigencia
Devuelve los capitales de un riesgo, la prima
param IN psseguro  : codigo de seguro
param IN pnriesgo  : numero de riesgo
param IN pmodo     : modo EST/POL
return             : texto con los capitales del riesgo
BUG 24678 - 30/10/2017 - LG
******************************************************************/
FUNCTION f_coaseguro_anexo(
    psseguro IN NUMBER,
    pcampo   IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL,
    psproces IN NUMBER DEFAULT NULL,--BUG 47494 08/03/2019 MPC Se adiciona parametro.
    ptipo    IN NUMBER DEFAULT 0)--BUG 0067332 GZG 09/04/2021
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult     VARCHAR2(32000) := '';
    v_tconsulta   VARCHAR2(4000);
    v_tconsulta_1 VARCHAR2(4000) := ' AND s.nmovimi = ' || pnmovimi;                                                                                                                                           --BUG 47494 MPC 08/03/2019 Se crea variable.
    v_tconsulta_2 VARCHAR2(4000) := '';                                                                                                                                                                        --BUG 47494 MPC 08/03/2019 Se crea variable.
    v_tconsulta_3 VARCHAR2(4000) := ' AND s.nmovimi = (select max(nmovimi) from garanseg re where re.nmovimi <= ' || pnmovimi || '  and re.SSEGURO = ' || psseguro || ')';--BUG 0060070 GZG 14/04/2020
    v_tlinia garangen.tgarant%TYPE;
    v_icaptot garanseg.icaptot%TYPE;
    v_ipritot VARCHAR2(200);
    v_ctipcap garanpro.ctipcap%TYPE;
    v_cimpres garanpro.cimpres%TYPE;
    v_tgarant garangen.tgarant%TYPE;
    v_npargar   NUMBER := 0;
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
    v_produc seguros.sproduc%TYPE;
    v_norden garanpro.norden%TYPE;
    v_es_admin NUMBER;
    nerror     NUMBER;
    vncertif   NUMBER;
    v_fechaini VARCHAR2(20);
    v_fechafin VARCHAR2(20);
    v_itotaseg VARCHAR2(100);
    v_cgarant garangen.cgarant%TYPE;
    v_porcded     NUMBER;
    v_smmlv       NUMBER;
    v_tnivel      VARCHAR2(200);
    vtotaseg      NUMBER;
    vtotaseg1     NUMBER := 0;
    vtotprim      NUMBER := 0;
    vtotprim1     NUMBER := 0;
    vsproduc      VARCHAR2(30);
    v_ult_nrecibo NUMBER;--BUG 0050591 09/04/2019 GZG
  BEGIN
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
      SELECT sproduc INTO vsproduc FROM estseguros WHERE sseguro = psseguro;
  ELSE
    v_tablaseg := 'seguros';
    SELECT sproduc INTO vsproduc FROM seguros WHERE sseguro = psseguro;
  END IF;
  -- INICIO BUG 0047083 01/02/2019 GZG --Se retira del loop y se trabaja individualmente
  IF pcampo = 13 THEN
    --INI BUG 0050591 09/04/2019 GZG
    v_ult_nrecibo    := f_recibo_mov(psseguro => psseguro, pnmovimi => pnmovimi);
    IF v_ult_nrecibo IS NULL THEN
      --
      SELECT MAX(nrecibo)
      INTO v_ult_nrecibo
      FROM recibos
      WHERE sseguro = psseguro;
      --
    END IF;
    --FIN BUG 0050591 09/04/2019 GZG
    FOR i IN
    --INI BUG 0060070 GZG 14/04/2020
    (SELECT DECODE(ipridev,0,iprinet,ipridev) totprim FROM vdetrecibos WHERE nrecibo = v_ult_nrecibo --BUG 0050591 09/04/2019 GZG
    UNION ALL
    SELECT DECODE(icednet,0,it2pri,icednet) totprim
    FROM vdetrecibos
    WHERE nrecibo = v_ult_nrecibo --BUG 0050591 09/04/2019 GZG
      --ORDER BY totprim DESC --BUG 0050591 09/04/2019 GZG
    )
    --FIN BUG 0060070 GZG 14/04/2020
    LOOP
    --INI BUG 0067332 GZG 09/04/2021
      vtotprim1 := vtotprim1 + i.totprim; --BUG 0050591 09/04/2019 GZG
      IF ptipo = 1 THEN
      v_tresult := v_tresult || TO_CHAR((i.totprim), '999,999,999,999,999,999') || ' \par ';--BUG 0050591 09/04/2019 GZG
      END IF;
    END LOOP;
     IF ptipo = 1 THEN
        RETURN (f_jrep_trad(v_tresult));
     ELSE
         v_tresult := vtotprim1;--BUG 0050591 09/04/2019 GZG
         RETURN (f_jrep_trad(v_tresult));
     END IF;
     --FIN BUG 0067332 GZG 09/04/2021
  END IF;
  --FIN BUG 0047083 01/02/2019 GZG
  v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
  EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
  IN psseguro;
  IF v_act0      = 1 THEN
    v_actividad := '0';
  ELSE
    v_actividad := 'se.cactivi';
  END IF;
  IF NVL(pmodo, 'POL') = 'EST' THEN
    v_tconsulta       := 'SELECT DISTINCT ' || '  a.sproduc, ' || '  pp.norden, ' || '  a.cgarant, ' || '  TRIM(TO_CHAR(SUM(b),''999,999,999,999,999,999'')), ' || '  TRIM(TO_CHAR(SUM(dd),''999,999,999,999,999,999'')), ' || '  TRIM(tgarant), ' || '  fechaini, ' || '  fechafin, ' || '  TRIM(TO_CHAR(SUM(totaseg),''999,999,999,999,999,999'')) totaseg, ' || '  deducible, ' || '  totaseg ';
    v_tconsulta       := v_tconsulta || ' FROM ( ';
    v_tconsulta       := v_tconsulta || '    SELECT ps.sproduc, s.cgarant, g.tgarant,';
    v_tconsulta       := v_tconsulta || '      pac_isqlfor_lcol.f_imporignomon(se.sseguro,(DECODE(s.cgarant,4,' || NVL(pcidioma, 1);
    v_tconsulta       := v_tconsulta || '      , se.cforpag,1)*icaptot)) a, ';
    v_tconsulta       := v_tconsulta || '      s.icaptot b, ';
    v_tconsulta       := v_tconsulta || '      p.ctipcap c, ';
    v_tconsulta       := v_tconsulta || '      p.cimpres, ';
    v_tconsulta       := v_tconsulta || '      NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant, ';
    v_tconsulta       := v_tconsulta || '      ''GARANT_IMP''), 0), ';
    v_tconsulta       := v_tconsulta || '      pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot) d, ';
    v_tconsulta       := v_tconsulta || '      s.ipritot dd, ';
    v_tconsulta       := v_tconsulta || '      REPLACE(pac_isqlfor_lcol.f_amp_vig_cump(se.sseguro, ' || pcidioma || ' ,1,1,''POL'',s.cgarant,' || pnriesgo || ' ,' || pnmovimi || '),''"'','''') fechaini, ';
    v_tconsulta       := v_tconsulta || '      REPLACE(pac_isqlfor_lcol.f_amp_vig_cump(se.sseguro, ' || pcidioma || ' ,1,2,''POL'',s.cgarant,' || pnriesgo || ' ,' || pnmovimi || '),''"'','''') fechafin, ';
    v_tconsulta       := v_tconsulta || '      s.icaptot totaseg, ';
    v_tconsulta       := v_tconsulta || '      pac_isqlfor_lcol.f_deducible_vig_certif0(se.sseguro,1,' || pnriesgo || ' ,''POL'',g.cgarant) deducible';
  ELSE
  --INI BUG 0060070 GZG 22/05/2020
    v_tconsulta := 'SELECT DISTINCT ' || '  a.sproduc, ' || '  pp.norden, ' || '  a.cgarant, ' || '  TRIM(TO_CHAR(SUM(b),''999,999,999,999,999,999'')), ' || '  TRIM(TO_CHAR(SUM(dd),''999,999,999,999,999,999'')), ' || '  TRIM(tgarant), ' || '  fechaini, ' || '  fechafin,  ' || '  TRIM(TO_CHAR(SUM(totaseg),''999,999,999,999,999,999'')) totaseg, ' || '  deducible, ' || '  SUM(totaseg) ,
SUM(dd) totprima';
--INI BUG 0060070 GZG 22/05/2020
    v_tconsulta := v_tconsulta || ' FROM ( ';
    v_tconsulta := v_tconsulta || '    SELECT ps.sproduc, s.cgarant, g.tgarant,';
    v_tconsulta := v_tconsulta || '      pac_isqlfor_lcol.f_imporignomon(se.sseguro,(DECODE(s.cgarant,4,' || NVL(pcidioma, 1);
    v_tconsulta := v_tconsulta || '      , se.cforpag,1)*icaptot)) a, ';
    v_tconsulta := v_tconsulta || '      s.icaptot b, ';
    v_tconsulta := v_tconsulta || '      p.ctipcap c, ';
    v_tconsulta := v_tconsulta || '      p.cimpres, ';
    v_tconsulta := v_tconsulta || '      NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant, ';
    v_tconsulta := v_tconsulta || '      ''GARANT_IMP''), 0), ';
    v_tconsulta := v_tconsulta || '      pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot) d, ';
    v_tconsulta := v_tconsulta || '      s.ipritot dd, ';
    v_tconsulta := v_tconsulta || '      REPLACE(pac_isqlfor_lcol.f_amp_vig_cump(se.sseguro, ' || pcidioma || ' ,1,1,''POL'',s.cgarant,' || pnriesgo || ' ,' || pnmovimi || '),''"'','''') fechaini, ';
    v_tconsulta := v_tconsulta || '      REPLACE(pac_isqlfor_lcol.f_amp_vig_cump(se.sseguro, ' || pcidioma || ' ,1,2,''POL'',s.cgarant,' || pnriesgo || ' ,' || pnmovimi || '),''"'','''') fechafin, ';
    v_tconsulta := v_tconsulta || '      s.icaptot totaseg, ';
    v_tconsulta := v_tconsulta || '      pac_isqlfor_lcol.f_deducible_vig_certif0(se.sseguro,1,' || pnriesgo || ' ,''POL'',g.cgarant) deducible';
  END IF;
  v_tconsulta         := v_tconsulta || ' FROM  garangen g, garanpro p, productos ps, ';
  IF NVL(pmodo, 'POL') = 'EST' THEN
    --v_tconsulta := v_tconsulta || ' estgaranseg s, estseguros se';
    v_tconsulta := v_tconsulta || ' estgaranseg s, estseguros se, ';
    v_tconsulta := v_tconsulta || '(select cgarant from PARGARANPRO where cpargar like ''%NO_CEDE_COASEGURO%'' and sproduc=' || vsproduc || ') pa ';
    v_csituac   := '(0,7,5,2,4)';
  ELSE
    --INI BUG 47494 MPC 08/03/2019 Se adiciona codigo de condiciÃ³n.
    IF NVL(pmodo, 'POL') = 'CAR' THEN
      --
      v_tconsulta   := v_tconsulta || ' garancar s, seguros se, seguros so,';
      v_tconsulta_1 := ' and s.sproces = '||psproces;
      --
    ELSE
      --FIN BUG 47494 MPC 08/03/2019 Se adiciona codigo de condiciÃ³n.
      --v_tconsulta := v_tconsulta || ' garanseg s, seguros se, seguros so';
      v_tconsulta := v_tconsulta || ' garanseg s, seguros se, seguros so,';
    END IF; --BUG 47494 MPC 08/03/2019 Se adiciona codigo de condiciÃ³n.
    v_tconsulta := v_tconsulta || '(select cgarant from PARGARANPRO where cpargar like ''%NO_CEDE_COASEGURO%'' and sproduc=' || vsproduc || ') pa ';
    v_csituac   := '(0,7,5,2,4)';
  END IF;
  v_tconsulta := v_tconsulta || ' WHERE g.cgarant = s.cgarant';
  -- INICIO BUG 0047083 01/02/2019 GZG
  -- INICIO 0051918: PDF - Anexo de Coaseguro Cedido sin valores Asegurados
  --INI FPP 09/10/2020 - QT56490
  --IF pcampo      = 12 AND vsproduc <> '10004' THEN
  --INI BUG 0067609 GZG 28/04/2021
  IF pcampo      = 12 AND vsproduc NOT IN ('10004', '10024') AND NVL(pac_parametros.f_parproducto_n(vsproduc, 'COASEGURO_RC'), 0) = 0 THEN
  --INI BUG 0060070 GZG 14/04/2020
    --v_tconsulta := v_tconsulta || ' AND g.cgarant IN (''3114'',''3149'',''9944'')'; --se filtra por garantias para anexo coaseguro--BUG 0050591 09/04/2019 GZG SE AGREGA 9944
    v_tconsulta := v_tconsulta || ' AND (p.CGARANT IN (SELECT GG.CGARANT FROM GARANPRO GG WHERE GG.SPRODUC = p.sproduc AND GG.CGARPADRE IS NULL AND gg.cbasica = 1) OR p.CGARANT IN ';
    v_tconsulta := v_tconsulta || ' (SELECT G2.CGARANT FROM garanpro g2 WHERE g2.cgarant IN (3149,3153,3154,3100,8046,9752,9957,9604,9605,9606,3124,3131,3158,3122) AND g2.sproduc = p.sproduc ))';
    v_tconsulta := v_tconsulta || ' AND so.sseguro = ' || psseguro;
  --FIN BUG 0060070 GZG 14/04/2020
  END IF;
  -- FIN BUG 0047083 01/02/2019 GZG
  IF pcampo = 12 AND NVL(pac_parametros.f_parproducto_n(vsproduc, 'COASEGURO_RC'), 0) = 1 THEN
    v_tconsulta := v_tconsulta || ' AND (p.CGARANT IN (SELECT GG.CGARANT FROM GARANPRO GG WHERE GG.SPRODUC = p.sproduc AND GG.CGARPADRE IS NULL )) ';
    v_tconsulta := v_tconsulta || ' AND so.sseguro = ' || psseguro;
  END IF;
    --FIN BUG 0067609 GZG 28/04/2021
  --INI FPP 09/10/2020 - QT56490
  IF pcampo = 12 AND vsproduc = '10024' THEN
    v_tconsulta := v_tconsulta || ' AND (p.CGARANT IN (SELECT GG.CGARANT FROM GARANPRO GG WHERE GG.SPRODUC = p.sproduc AND GG.CGARPADRE IS NULL AND gg.cbasica = 1)) ';
    v_tconsulta := v_tconsulta || ' AND so.sseguro = ' || psseguro;
  END IF;
  --FIN FPP 09/10/2020 - QT56490
  v_tconsulta := v_tconsulta || ' AND p.cgarant = s.cgarant';
  v_tconsulta := v_tconsulta || ' AND p.sproduc = se.sproduc';
  v_tconsulta := v_tconsulta || ' AND s.sseguro = se.sseguro';
  v_tconsulta := v_tconsulta || ' AND p.sproduc = ps.sproduc';
  v_tconsulta := v_tconsulta || ' AND p.cactivi = ' || v_actividad;
  v_tconsulta := v_tconsulta || ' AND se.csituac in ' || v_csituac;
  v_tconsulta := v_tconsulta || ' AND s.sseguro = so.sseguro';
  v_tconsulta := v_tconsulta || ' AND (p.CGARPADRE IS NULL )';
  v_tconsulta := v_tconsulta || ' AND so.npoliza in  (select npoliza from seguros where sseguro in (' || psseguro || '))';
  v_tconsulta := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
  --v_tconsulta := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;--BUG 0060070 GZG 14/04/2020
  --INI BUG 0050591 09/04/2019 GZG para que traiga el valor anterior cuando es anulacion
  --INI BUG 47494 MPC 08/03/2019 Se modifica condiciÃ¿Â³n.
  --v_tconsulta := v_tconsulta || ' AND s.nmovimi = ' || pnmovimi;
  IF NVL(pmodo, 'POL') = 'CAR' THEN
    --
    v_tconsulta := v_tconsulta || v_tconsulta_1;
    --
  ELSE
    --
    v_tconsulta := v_tconsulta || v_tconsulta_3;
    --
  END IF;
  v_tconsulta := v_tconsulta || ' and pa.CGARANT(+)=s.cgarant ';
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden) a, garanpro pp WHERE a.cgarant=pp.cgarant AND  pp.sproduc = a.sproduc ';
  v_tconsulta := v_tconsulta || ' GROUP BY a.sproduc, pp.norden, a.cgarant, a.tgarant, a.fechaini,  a.fechafin, a.totaseg, a.deducible ORDER BY pp.norden';
  --FIN BUG 0050591 09/04/2019 GZG para que traiga el valor anterior cuando es anulacion
  --p_control_error('LG', 'f_coaseguro_anexo', 'v_tconsulta:' || v_tconsulta);
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor
    INTO v_produc,
      v_norden,
      v_cgarant,
      v_tlinia,
      v_ipritot,
      v_tgarant,
      v_fechaini,
      v_fechafin,
      v_itotaseg,
      v_tnivel,
      vtotaseg,
      vtotprim;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    BEGIN
      --Valor asegurado
      IF pcampo = 4 AND v_icaptot = 0 THEN
        SELECT tatribu
        INTO v_tlinia
        FROM detvalores
        WHERE cvalor = 126
        AND catribu  = NVL(v_cimpres, 59)
        AND cidioma  = NVL(pcidioma, 8);
      END IF;
      --Prima
      IF pcampo   = 5 THEN
        v_tlinia := v_ipritot;
      END IF;
      --amparo
      IF pcampo   = 6 THEN
        v_tlinia := v_tgarant;
      END IF;
      --Fecha Inicial
      IF pcampo   = 7 THEN
        v_tlinia := v_fechaini;
      END IF;
      --Fecha Final
      IF pcampo   = 8 THEN
        v_tlinia := v_fechafin;
      END IF;
      --Valor total asegurado
      IF pcampo   = 9 THEN
        v_tlinia := v_itotaseg;
      END IF;
      -- Columna deducibles
      IF pcampo      = 10 THEN
        IF v_tnivel IS NOT NULL THEN
          v_tlinia  := v_tnivel;
        ELSE
          v_tlinia := ' ';
        END IF;
      END IF;
      --Valor total asegurado a mostrar en el certificado
      IF pcampo    = 11 THEN
        vtotaseg1 := vtotaseg1 + vtotaseg;
      END IF;
      --Valor total asegurado a mostrar en el anexo sin formato
      IF pcampo    = 12 THEN
        vtotaseg1 := vtotaseg1 + vtotaseg;
      END IF;
      --Valor total prima a mostrar en el anexo sin formato
      -- IF pcampo = 13 THEN
      -- vtotprim1 := vtotprim1 + vtotprim;-- BUG 0047083 01/02/2019 GZG
      -- END IF;
    EXCEPTION
    WHEN OTHERS THEN
      v_tlinia := ' ';
    END;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  IF pcampo    = 11 THEN
    v_tlinia  := TRIM(TO_CHAR(vtotaseg1, '999,999,999,999,999,999'));
    v_tresult := v_tlinia || '\par ';
  END IF;
  IF pcampo    = 12 THEN
    v_tresult := vtotaseg1;
  END IF;
  --IF pcampo    = 13 THEN
  --  v_tresult := vtotprim1;-- BUG 0047083 01/02/2019 GZG
  --END IF;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_coaseguro_anexo;
/*****************************************************************
FUNCTION f_coaseguro_p
Devuelve la informaciÃ¿Â³n del coaseguro
param IN psseguro  : codigo de seguro
param IN pcampo    : numero de dato a devolver
param IN ptablas   : modo EST/POL
param IN pvtotaseg : Valor total asegurado de la pÃ¿Â³liza
param IN pvtotprim : Valor total prima de la pÃ¿Â³liza
return             : texto con los capitales del riesgo
BUG 24678 - 30/10/2017 - LG
******************************************************************/
FUNCTION f_coaseguro_p(
    psseguro  IN NUMBER,
    pcampo    IN NUMBER,
    ptablas   IN VARCHAR2 DEFAULT 'POL',
    pvtotaseg IN NUMBER DEFAULT NULL,
    --INI CPEMEU-232 GZG 18/02/2026
    pvtotprim IN NUMBER DEFAULT NULL,
    pdolar  IN NUMBER DEFAULT 0)
    --FIN CPEMEU-232 GZG 18/02/2026
  RETURN VARCHAR2
IS
  v_tresult VARCHAR2(4000);
  vcoaseg seguros.ccompani%TYPE;
  vtcoaseg companias.tcompani%TYPE;
  vpcoaseg    VARCHAR2(4);
  vtipocoaseg VARCHAR2(2);
  vntipocoa   NUMBER;
  vporc       NUMBER;
BEGIN
  IF ptablas = 'POL' THEN
    SELECT ctipcoa
    INTO vntipocoa
    FROM seguros
    WHERE sseguro = psseguro;
    FOR i IN
    (SELECT DECODE(s.ccompani, 1, 2, 1) coaseg,
      tcompani tcoaseg,
      ploccoa
      || '%' pcoaseg,
      DECODE(vntipocoa, 1, 'C', 2, 'C', 'A') tipocoaseg,
      ploccoa porc
    FROM coacuadro cc,
      companias c,
      seguros s
    WHERE s.sseguro = psseguro
    AND cc.sseguro  = s.sseguro
    AND s.ccompani  = c.ccompani
    AND cc.ncuacoa  =
      (SELECT MAX(ncuacoa) FROM coacedido WHERE sseguro = psseguro
      )
    UNION
    SELECT ccompan coaseg,
      tcompani tcoaseg,
      pcescoa
      || '%' pcoaseg,
      DECODE(vntipocoa, 1, 'A', 2, 'A', 'C') tipocoaseg,
      pcescoa porc
    FROM coacedido cc,
      companias c
    WHERE cc.sseguro = psseguro
    AND cc.ccompan   = c.ccompani
    AND cc.ncuacoa   =
      (SELECT MAX(ncuacoa) FROM coacedido WHERE sseguro = psseguro
      )
    )
    LOOP
      IF pcampo    = 1 THEN
        v_tresult := v_tresult || i.coaseg || ' \par ';
      ELSIF pcampo = 2 THEN
        v_tresult := v_tresult || i.tcoaseg || ' \par ';
      ELSIF pcampo = 3 THEN
        v_tresult := v_tresult || i.pcoaseg || ' \par ';
      ELSIF pcampo = 4 THEN
        v_tresult := v_tresult || i.tipocoaseg || ' \par ';
	--INI CPEMEU-232 GZG 18/02/2026
      ELSIF pcampo = 5 AND pdolar = 1 THEN
        v_tresult := v_tresult || RTRIM(TO_CHAR(((pvtotaseg * i.porc) / 100), 'FM999G999G990D99','NLS_NUMERIC_CHARACTERS=''.,''' ),'.') || ' \par ';
      ELSIF pcampo = 5 THEN
        v_tresult := v_tresult || TO_CHAR(((pvtotaseg * i.porc) / 100), '999,999,999,999,999,999') || ' \par ';
      ELSIF pcampo = 6 AND pdolar = 1 THEN
        v_tresult := v_tresult || RTRIM(TO_CHAR(((pvtotprim * i.porc) / 100), 'FM999G999G990D99','NLS_NUMERIC_CHARACTERS=''.,''' ),'.') || ' \par ';
	--FIN CPEMEU-232 GZG 18/02/2026
      ELSIF pcampo = 6 THEN
        v_tresult := v_tresult || TO_CHAR(((pvtotprim * i.porc) / 100), '999,999,999,999,999,999') || ' \par ';
      END IF;
    END LOOP;
    --Si no hay, por defecto...
    IF v_tresult IS NULL THEN
      SELECT DECODE(s.ccompani, 1, 2, 1) coaseg,
        tcompani tcoaseg,
        DECODE(s.ccompani, 325, '50%', '100%') pcoaseg,
        'A' tipocoaseg,
        DECODE(s.ccompani, 325, '50', '100') porc
      INTO vcoaseg,
        vtcoaseg,
        vpcoaseg,
        vtipocoaseg,
        vporc
      FROM companias c,
        seguros s
      WHERE s.sseguro = psseguro
      AND s.ccompani  = c.ccompani;
      IF pcampo       = 1 THEN
        v_tresult    := vcoaseg;
      ELSIF pcampo    = 2 THEN
        v_tresult    := vtcoaseg;
      ELSIF pcampo    = 3 THEN
        v_tresult    := vpcoaseg;
      ELSIF pcampo    = 4 THEN
        v_tresult    := vtipocoaseg;
	--INI CPEMEU-232 GZG 18/02/2026
      ELSIF pcampo = 5 AND pdolar = 1 THEN
        v_tresult := v_tresult || RTRIM(TO_CHAR(((pvtotaseg * vporc) / 100), 'FM999G999G990D99','NLS_NUMERIC_CHARACTERS=''.,''' ),'.') || ' \par ';
      ELSIF pcampo = 5 THEN
        v_tresult := v_tresult || TO_CHAR(((pvtotaseg * vporc) / 100), '999,999,999,999,999,999') || ' \par ';
      ELSIF pcampo = 6 AND pdolar = 1 THEN
        v_tresult := v_tresult || RTRIM(TO_CHAR(((pvtotprim * vporc) / 100), 'FM999G999G990D99','NLS_NUMERIC_CHARACTERS=''.,''' ),'.') || ' \par ';
	--FIN CPEMEU-232 GZG 18/02/2026
      ELSIF pcampo    = 6 THEN
        v_tresult    := v_tresult || TO_CHAR(((pvtotprim * vporc) / 100), '999,999,999,999,999,999') || ' \par ';
      END IF;
    END IF;
  ELSE
    SELECT ctipcoa
    INTO vntipocoa
    FROM estseguros
    WHERE sseguro = psseguro;
    FOR i IN
    (SELECT DECODE(s.ccompani, 1, 2, 1) coaseg,
      tcompani tcoaseg,
      ploccoa
      || '%' pcoaseg,
      DECODE(vntipocoa, 1, 'C', 2, 'C', 'A') tipocoaseg,
      ploccoa porc
    FROM coacuadro cc,
      companias c,
      estseguros s
    WHERE s.sseguro = psseguro
    AND cc.sseguro  = s.sseguro
    AND s.ccompani  = c.ccompani
    AND cc.ncuacoa  =
      (SELECT MAX(ncuacoa) FROM coacedido WHERE sseguro = psseguro
      )
    UNION
    SELECT ccompan coaseg,
      tcompani tcoaseg,
      pcescoa
      || '%' pcoaseg,
      DECODE(vntipocoa, 1, 'A', 2, 'A', 'C') tipocoaseg,
      pcescoa porc
    FROM coacedido cc,
      companias c
    WHERE cc.sseguro = psseguro
    AND cc.ccompan   = c.ccompani
    AND cc.ncuacoa   =
      (SELECT MAX(ncuacoa) FROM coacedido WHERE sseguro = psseguro
      )
    )
    LOOP
      IF pcampo    = 1 THEN
        v_tresult := v_tresult || i.coaseg || ' \par ';
      ELSIF pcampo = 2 THEN
        v_tresult := v_tresult || i.tcoaseg || ' \par ';
      ELSIF pcampo = 3 THEN
        v_tresult := v_tresult || i.pcoaseg || ' \par ';
      ELSIF pcampo = 4 THEN
        v_tresult := v_tresult || i.tipocoaseg || ' \par ';
	--INI CPEMEU-232 GZG 18/02/2026
      ELSIF pcampo = 5 AND pdolar = 1 THEN
        v_tresult := v_tresult || RTRIM(TO_CHAR(((pvtotaseg * i.porc) / 100), 'FM999G999G990D99','NLS_NUMERIC_CHARACTERS=''.,''' ),'.') || ' \par ';
      ELSIF pcampo = 5 THEN
        v_tresult := v_tresult || TO_CHAR(((pvtotaseg * i.porc) / 100), '999,999,999,999,999,999') || ' \par ';
      ELSIF pcampo = 6 AND pdolar = 1 THEN
        v_tresult := v_tresult || RTRIM(TO_CHAR(((pvtotprim * i.porc) / 100), 'FM999G999G990D99','NLS_NUMERIC_CHARACTERS=''.,''' ),'.') || ' \par ';
	--INI CPEMEU-232 GZG 18/02/2026
      ELSIF pcampo = 6 THEN
        v_tresult := v_tresult || TO_CHAR(((pvtotprim * i.porc) / 100), '999,999,999,999,999,999') || ' \par ';
      END IF;
    END LOOP;
    --Si no hay, por defecto...
    IF v_tresult IS NULL THEN
      SELECT DECODE(s.ccompani, 1, 2, 1) coaseg,
        tcompani tcoaseg,
        DECODE(s.ccompani, 325, '50%', '100%') pcoaseg,
        'A' tipocoaseg,
        DECODE(s.ccompani, 325, '50', '100') porc
      INTO vcoaseg,
        vtcoaseg,
        vpcoaseg,
        vtipocoaseg,
        vporc
      FROM companias c,
        estseguros s
      WHERE s.sseguro = psseguro
      AND s.ccompani  = c.ccompani;
      IF pcampo       = 1 THEN
        v_tresult    := vcoaseg;
      ELSIF pcampo    = 2 THEN
        v_tresult    := vtcoaseg;
      ELSIF pcampo    = 3 THEN
        v_tresult    := vpcoaseg;
      ELSIF pcampo    = 4 THEN
        v_tresult    := vtipocoaseg;
	--INI CPEMEU-232 GZG 18/02/2026
      ELSIF pcampo = 5 AND pdolar = 1 THEN
        v_tresult := v_tresult || RTRIM(TO_CHAR(((pvtotaseg * vporc) / 100), 'FM999G999G990D99','NLS_NUMERIC_CHARACTERS=''.,''' ),'.') || ' \par ';
      ELSIF pcampo = 5 THEN
        v_tresult := v_tresult || TO_CHAR(((pvtotaseg * vporc) / 100), '999,999,999,999,999,999') || ' \par ';
      ELSIF pcampo = 6 AND pdolar = 1 THEN
        v_tresult := v_tresult || RTRIM(TO_CHAR(((pvtotprim * vporc) / 100), 'FM999G999G990D99','NLS_NUMERIC_CHARACTERS=''.,''' ),'.') || ' \par ';
	--FIN CPEMEU-232 GZG 18/02/2026
      ELSIF pcampo    = 6 THEN
        v_tresult    := v_tresult || TO_CHAR(((pvtotprim * vporc) / 100), '999,999,999,999,999,999') || ' \par ';
      END IF;
    END IF;
  END IF;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN '';
END f_coaseguro_p;
