/*****************************************************************
FUNCTION f_amp_lim_Pyme_xriesgo
Devuelve las sumatorias de los limites de indemnizacion de los amparos de un riesgo para Pyme
filtrado por riessgo
param IN psseguro  : codigo de seguro
param IN pnriesgo  : numero de riesgo
param IN pnmovimi  : numero de Movimiento
param IN pcidioma  : codigo de idioma
param IN pcampo    : recupera la cod de la garantias, desc de las garantias, el capital
param IN pmodo     : modo EST/POL
return             : texto con las garantias del riesgo
Bug 37907 - 23/10/2017 - LGG - INICIO
******************************************************************/
FUNCTION f_amp_lim_pyme_xriesgo(
    psseguro IN NUMBER,
    pnrecibo IN NUMBER,
    pcampo   IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    priesgo  IN NUMBER DEFAULT 1,
    --INI CPEMEU-232 GZG 22/12/2O25
    psproces IN NUMBER DEFAULT NULL,
    pdolar  IN NUMBER DEFAULT 0) --MPC BUG 47494 08/03/2019 Se adiciona parametro.
    --FIN CPEMEU-232 GZG 22/12/2O25
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult     VARCHAR2(32000) := '';
    v_tconsulta   VARCHAR2(12000);
    v_tconsulta_1 VARCHAR2(4000) := ''; --MPC BUG 47494 08/03/2019 Se inicializa consulta.
    v_tconsulta_2 VARCHAR2(4000) := ''; --MPC BUG 47494 08/03/2019 Se inicializa consulta.
    v_tconsulta_3 VARCHAR2(4000) := ''; --MPC BUG 47494 08/03/2019 Se inicializa consulta.
    v_tconsulta_4 VARCHAR2(4000);
    v_tablaseg    VARCHAR2(30);
    v_act0        NUMBER(1);
    v_actividad   VARCHAR2(20);
    v_icapital    VARCHAR2(300) := '';
    v_valor       VARCHAR2(300);
  BEGIN
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
      --INI BUG 47494 MPC 08/03/2019 Se dicionan condiciones y filtro para previos.
      --INI BUG 66657 GZG 02/03/2021
      v_tconsulta_1 := ' select TO_CHAR(decode(b.ctiprec,9, sum(a.iconcep_monpol)*-1, sum(a.iconcep_monpol)), ''999,999,999,999,999'') valor from detrecibos a inner join recibos b on a.nrecibo = b.nrecibo ';
      v_tconsulta_3 := 'select TO_CHAR(decode(b.ctiprec,9, sum(a.iconcep_monpol)*-1, sum(a.iconcep_monpol)), ''999,999,999,999,999'') valor from detrecibos a inner join recibos b on a.nrecibo = b.nrecibo  '; -- BUG 0053421 22/07/2019 se agrega decode para que salga negativo los extornos en el PDF
      --FIN BUG 66657 GZG 02/03/2021
    ELSIF NVL(pmodo, 'POL') = 'CAR' THEN
      --
      v_tablaseg := 'seguros';
      --
      v_tconsulta_1 := ' select TO_CHAR(decode(b.ctiprec,9, sum(a.iconcep_monpol)*-1, sum(a.iconcep_monpol)), ''999,999,999,999,999.99'') valor from detreciboscar a inner join reciboscar b on a.nrecibo = b.nrecibo AND a.sproces = b.sproces ';
      v_tconsulta_2 := ' and a.sproces = '||psproces;
      v_tconsulta_3 := 'select TO_CHAR(decode(b.ctiprec,9, sum(a.iconcep_monpol)*-1, sum(a.iconcep_monpol)), ''999,999,999,999,999.99'') valor from detreciboscar a inner join reciboscar b on a.nrecibo = b.nrecibo AND a.sproces = b.sproces';-- BUG 0053421 22/07/2019 se agrega decode para que salga negativo los extornos en el PDF
      --
    ELSE
      --INI BUG 66657 GZG 02/03/2021
      v_tconsulta_1 := ' select TO_CHAR(decode(b.ctiprec,9, sum(a.iconcep_monpol)*-1, sum(a.iconcep_monpol)), ''999,999,999,999,999'') valor from detrecibos a inner join recibos b on a.nrecibo = b.nrecibo ';
      --INI CPEMEU-232 GZG 19/01/2026
      IF pdolar = 1 THEN
      v_tconsulta_3 := 'select RTRIM(TO_CHAR(SUM(DECODE(b.ctiprec, 9, -1, 13, 0, 15, 0, 1) * a.iconcep), ''FM999G999G990D99'',''NLS_NUMERIC_CHARACTERS=''''.,'''''' ),''.'') valor from detrecibos a inner join recibos b on a.nrecibo = b.nrecibo ';
      v_tconsulta_1 := 'select RTRIM(TO_CHAR(SUM(DECODE(b.ctiprec, 9, -1, 13, 0, 15, 0, 1) * a.iconcep), ''FM999G999G990D99'',''NLS_NUMERIC_CHARACTERS=''''.,'''''' ),''.'') valor from detrecibos a inner join recibos b on a.nrecibo = b.nrecibo ';
      ELSE
      v_tconsulta_3 := 'select TO_CHAR(decode(b.ctiprec,9, sum(a.iconcep_monpol)*-1, sum(a.iconcep_monpol)), ''999,999,999,999,999'') valor from detrecibos a inner join recibos b on a.nrecibo = b.nrecibo  ';-- BUG 0053421 22/07/2019 se agrega decode para que salga negativo los extornos en el PDF
      END IF;
      --FIN CPEMEU-232 GZG 19/01/2026
      --FIN BUG 66657 GZG 02/03/2021
      --FIN BUG 47494 MPC 08/03/2019 Se dicionan condiciones y filtro para previos.
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 's.cactivi';
    END IF;
    --Bug 36480 - 29/08/2017 - LGG - INICIO
    --Prima Danos Materiales
    IF pcampo = 1 THEN
      --INI BUG 47494 MPC 08/03/2019 Se modifica filtros.
      --v_tconsulta := ' select TO_CHAR(decode(b.ctiprec,9, sum(a.iconcep_monpol)*-1, sum(a.iconcep_monpol)), ''999,999,999,999,999.99'') valor from detrecibos a inner join recibos b on a.nrecibo = b.nrecibo ';
      v_tconsulta := v_tconsulta_1;
      --FIN BUG 47494 MPC 08/03/2019 Se modifica filtros.
      v_tconsulta := v_tconsulta || ' where sseguro = ' || psseguro;
      v_tconsulta := v_tconsulta || ' and cgarant in (3114,3115,3116,3117,3118, 3123, 3119, 3122,3130, 3182, 3183,400) ';--BUG 0052368 GZG se adiciona 400
      v_tconsulta := v_tconsulta || ' and a.nrecibo = ' || pnrecibo;
      v_tconsulta := v_tconsulta || v_tconsulta_2;            --BUG 47494 MPC 08/03/2019 Se modifica filtros.
      v_tconsulta := v_tconsulta || ' and cconcep in (0,50)'; --BUG 47494 MPC 10/05/2019 Se adiciona todos los conceptos cedido (0,71).
      v_tconsulta := v_tconsulta || ' and a.nriesgo = ' || priesgo;
      v_tconsulta := v_tconsulta || ' group by b.ctiprec ';
    END IF;
    --Prima Lucro Cesante Da?os Mat
    IF pcampo = 2 THEN
      --INI BUG 47494 MPC 08/03/2019 Se modifica filtros.
      --v_tconsulta := ' select TO_CHAR(decode(b.ctiprec,9, sum(a.iconcep_monpol)*-1, sum(a.iconcep_monpol)), ''999,999,999,999,999.99'') valor from detrecibos a inner join recibos b on a.nrecibo = b.nrecibo ';
      v_tconsulta := v_tconsulta_1;
      --FIN BUG 47494 MPC 08/03/2019 Se modifica filtros.v_tconsulta := v_tconsulta || ' where sseguro = ' || psseguro;
      v_tconsulta := v_tconsulta || ' where sseguro = ' || psseguro;
      v_tconsulta := v_tconsulta || ' and cgarant in (3149, 3150, 3151,9268) '; -- INICIO/FIN AHYPPLMDCO-195
      v_tconsulta := v_tconsulta || ' and a.nrecibo = ' || pnrecibo;
      v_tconsulta := v_tconsulta || v_tconsulta_2;            --BUG 47494 MPC 08/03/2019 Se modifica filtros.
      v_tconsulta := v_tconsulta || ' and cconcep in (0,50)'; --BUG 47494 MPC 10/05/2019 Se adiciona todos los conceptos cedido (0,71).
      v_tconsulta := v_tconsulta || ' and a.nriesgo = ' || priesgo;
      v_tconsulta := v_tconsulta || ' group by b.ctiprec ';
    END IF;
    --Prima Lucro Cesante Rotura Maq
    IF pcampo = 3 THEN
      --INI BUG 47494 MPC 08/03/2019 Se modifica filtros.
      --v_tconsulta := ' select TO_CHAR(decode(b.ctiprec,9, sum(a.iconcep_monpol)*-1, sum(a.iconcep_monpol)), ''999,999,999,999,999.99'') valor from detrecibos a inner join recibos b on a.nrecibo = b.nrecibo ';
      v_tconsulta := v_tconsulta_1;
      --FIN BUG 47494 MPC 08/03/2019 Se modifica filtros.v_tconsulta := v_tconsulta || ' where sseguro = ' || psseguro;
      v_tconsulta := v_tconsulta || ' where sseguro = ' || psseguro;
      v_tconsulta := v_tconsulta || ' and cgarant in (3152) ';
      v_tconsulta := v_tconsulta || ' and a.nrecibo = ' || pnrecibo;
      v_tconsulta := v_tconsulta || v_tconsulta_2;            --BUG 47494 MPC 08/03/2019 Se modifica filtros.
      v_tconsulta := v_tconsulta || ' and cconcep in (0,50)'; --BUG 47494 MPC 10/05/2019 Se adiciona todos los conceptos cedido (0,71).
      v_tconsulta := v_tconsulta || ' and a.nriesgo = ' || priesgo;
      v_tconsulta := v_tconsulta || ' group by b.ctiprec ';
    END IF;
    --Prima Responsabilidad
    IF pcampo = 4 THEN
      --INI BUG 47494 MPC 08/03/2019 Se modifica filtros.
      --v_tconsulta := ' select TO_CHAR(decode(b.ctiprec,9, sum(a.iconcep_monpol)*-1, sum(a.iconcep_monpol)), ''999,999,999,999,999.99'') valor from detrecibos a inner join recibos b on a.nrecibo = b.nrecibo ';
      v_tconsulta := v_tconsulta_1;
      --FIN BUG 47494 MPC 08/03/2019 Se modifica filtros.v_tconsulta := v_tconsulta || ' where sseguro = ' || psseguro;
      v_tconsulta := v_tconsulta || ' where sseguro = ' || psseguro;
      v_tconsulta := v_tconsulta || ' and cgarant in (3131) ';
      v_tconsulta := v_tconsulta || ' and a.nrecibo = ' || pnrecibo;
      v_tconsulta := v_tconsulta || v_tconsulta_2;           --BUG 47494 MPC 08/03/2019 Se modifica filtros.
      v_tconsulta := v_tconsulta || ' and cconcep in (0,50)';--BUG 47494 MPC 10/05/2019 Se adiciona todos los conceptos cedido (0,71).
      v_tconsulta := v_tconsulta || ' and a.nriesgo = ' || priesgo;
      v_tconsulta := v_tconsulta || ' group by b.ctiprec ';
    END IF;
    --Prima Manejo
    IF pcampo = 5 THEN
      --INI BUG 47494 MPC 08/03/2019 Se modifica filtros.
