END f_amp_lim_pyme_xriesgo;
/*****************************************************************
FUNCTION f_obs_gar_Pyme_xriesgo
Devuelve el texto de las preguntas de algunas garantias
filtrado por riessgo
param IN psseguro  : codigo de seguro
param IN pnriesgo  : numero de riesgo
param IN pnmovimi  : numero de parametro
return             : texto con las respuestas de las preguntas de algunas garantias
Bug 37907 - 23/10/2017 - LGG - INICIO
******************************************************************/
FUNCTION f_obs_gar_pyme_xriesgo(
    psseguro IN NUMBER,
    pnriesgo IN NUMBER,
    pnmovimi IN NUMBER)
  RETURN VARCHAR2
IS
  v_tresult VARCHAR2(32000) := '';
BEGIN
  SELECT pac_isqlfor_lcol.f_jrep_trad( LISTAGG(garantia, LOWER(' \par ')) WITHIN GROUP (
  ORDER BY cgarant))
  INTO v_tresult
  FROM
    (SELECT cgarant,
      garantia
    FROM
      (SELECT DISTINCT pgs.cgarant,
        LOWER(' \par ')
        || tgarant garantia
      FROM pregungaranseg pgs
      JOIN garangen gg
      ON gg.cgarant  = pgs.cgarant
      AND gg.cidioma = 8
      JOIN preguntas pg
      ON pg.cpregun     = pgs.cpregun
      AND pg.cidioma    = 8
      WHERE pgs.sseguro = psseguro
      AND pgs.cgarant  IN (3175, 3241, 3187, 3149, 3247, 3152)
      AND pgs.nriesgo   = pnriesgo
      AND pgs.nmovimi   = pnmovimi
      UNION
      SELECT pgs.cgarant,
        pg.tpregun
        || ': '
        ||
        CASE
          WHEN pgs.trespue IS NOT NULL
          THEN pgs.trespue
          ELSE
            CASE
              WHEN rta.cpregun IS NULL
              THEN TO_CHAR(pgs.crespue)
              ELSE rta.trespue
            END
        END garantia
      FROM pregungaranseg pgs
      JOIN garangen gg
      ON gg.cgarant  = pgs.cgarant
      AND gg.cidioma = 8
      JOIN preguntas pg
      ON pg.cpregun  = pgs.cpregun
      AND pg.cidioma = 8
      LEFT JOIN respuestas rta
      ON rta.cpregun       = pgs.cpregun
      AND rta.crespue      = pgs.crespue
      AND rta.cidioma      = 8
      WHERE pgs.sseguro    = psseguro
      AND pgs.cgarant     IN (3175, 3241, 3187, 3149, 3247, 3152)
      AND pgs.nriesgo      = pnriesgo
      AND pgs.nmovimi      = pnmovimi
      AND pgs.cpregun NOT IN (9759, 9760)
      )
    );
  RETURN v_tresult;
EXCEPTION
WHEN OTHERS THEN
  RETURN ' ';
END f_obs_gar_pyme_xriesgo;
-- Bug 37907 - 23/10/2017 - LGG - FIN
--INI BUG 33741 CSI 24/11/2017 se adiciona Funcion Previo Cartera
/*****************************************************************
GH - TH
FUNCTION f_garantias_riesgo car home Previo Cartera
Devuelve las partidas de un riesgo
param IN psseguro  : codigo de seguro
param IN pnriesgo  : numero de riesgo
param IN pcidioma  : codigo de idioma
param IN pmodo     : modo EST/POL
return             : texto con las garant?as del riesgo
******************************************************************/
FUNCTION f_garantias_riesgo_car_hclob(
    psseguro IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pcampo   IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    psproces IN NUMBER DEFAULT NULL)
  RETURN CLOB
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult CLOB := '';
    v_tconsulta  VARCHAR2(4000);
    v_tlinia     VARCHAR2(300);
    v_tlinia1    VARCHAR2(300);
    v_tlinia2    VARCHAR2(300);
    v_tlinia3    VARCHAR2(300);
    v_norden     NUMBER;
    v_nimpresion NUMBER;
    v_nlinea     NUMBER;
    v_tpargar    VARCHAR2(200);
    v_tablaseg   VARCHAR2(30);
    v_act0       NUMBER(1);
    v_cimpres garanpro.cimpres%TYPE;
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
    v_ntabs     VARCHAR2(100);
  BEGIN
    --
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    v_tconsulta         := v_tconsulta || ' LEFT JOIN pregungarancar pgs ON s.cgarant = pgs.cgarant AND pgs.sseguro = s.sseguro AND pgs.nriesgo = s.nriesgo AND pgs.nmovimi = s.nmovimi ';
    v_tconsulta         := v_tconsulta || ' WHERE se.csituac in ' || v_csituac;
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND g.cidioma = ' || NVL(pcidioma, 1);
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    v_tconsulta         := 'SELECT p.norden,g.cgarant,g.tgarant,pac_isqlfor_lcol.f_imporignomon(se.sseguro,(decode(s.cgarant,48,se.cforpag,1)*icaptot), null, ''' || pmodo || ''') a, ' || ' NVL(pac_parametros.f_pargaranpro_n(p.sproduc,p.cactivi,g.cgarant,''GARANT_IMP''), 0) IMPRESION, ' || ' pac_isqlfor_lcol.f_imporignomon(se.sseguro,ipritot, null, ''' || pmodo || ''') d, 0 nlinea FROM garangenpro g ';
    v_tconsulta         := v_tconsulta || ' INNER JOIN garanpro p ON g.cgarant = p.cgarant ';
    v_tconsulta         := v_tconsulta || ' INNER JOIN productos pp ON p.sproduc = pp.sproduc ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' INNER JOIN estgaranseg s ON g.cgarant = s.cgarant AND p.cgarant = s.cgarant ' || 'INNER JOIN estseguros se ON p.sproduc = se.sproduc AND s.sseguro = se.sseguro AND p.cactivi = ' || v_actividad;
      v_csituac         := '(0,7,5,2,4)';
    ELSE
      v_tconsulta                                 := v_tconsulta || ' INNER JOIN garancar s ON g.cgarant = s.cgarant AND p.cgarant = s.cgarant ' || ' INNER JOIN seguros se ON p.sproduc = se.sproduc AND s.sseguro = se.sseguro AND p.cactivi = ' || v_actividad;
      IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
        v_csituac                                 := '(0,7,5,2)';
      ELSE
        v_csituac := '(0,7,5,2,4)';
      END IF;
    END IF;
    v_tconsulta         := v_tconsulta || ' WHERE se.csituac in ' || v_csituac;
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND g.cidioma = ' || pcidioma;
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' AND s.icapital IS NOT NULL ';
      v_tconsulta       := v_tconsulta || ' AND s.sproces =' || psproces;
    ELSE
      v_tconsulta := v_tconsulta || ' AND s.sproces =' || psproces;
    END IF;
    v_tconsulta         := v_tconsulta || ' UNION ';
    v_tconsulta         := v_tconsulta || ' SELECT p.norden, a.cgarant, a.tvalor AS tgarant,' || ' pac_isqlfor_lcol.f_imporignomon(a.sseguro, TRUNC(b.nvalor+((b.nvalor*(((g.icapital*100)/gs.icapital)-100))/100)), null, ''' || pmodo || ''') AS val, -1 impresion, ' || ' pac_isqlfor_lcol.f_imporignomon(a.sseguro, 0, null, ''' || pmodo || ''') d, a.nlinea ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || ' FROM (SELECT * FROM estpregungaransegtab WHERE sseguro = ' || psseguro || ' AND ccolumna = 1 ) a INNER JOIN ' || ' (SELECT * FROM pregungarancartab WHERE sseguro = ' || psseguro || ' AND ccolumna = 2) b ON a.sseguro = b.sseguro AND a.nriesgo = b.nriesgo AND a.cgarant = b.cgarant AND a.nlinea = b.nlinea ' || ' INNER JOIN garangenpro c ON a.cgarant = c.cgarant ' || ' INNER JOIN garanpro p ON c.cgarant = p.cgarant ' || ' INNER JOIN productos pp ON p.sproduc = pp.sproduc ' || ' INNER JOIN estseguros se  ON p.sproduc = se.sproduc AND a.sseguro = se.sseguro AND p.cactivi = ' || v_actividad;
      v_tconsulta       := v_tconsulta || ' WHERE c.cidioma = ' || pcidioma;
    ELSE
      --INI-MPC-BUG 45497-13/08/2018 - Se adiciona filtro AND nmovimi = (SELECT MAX(nmovimi) FROM pregungaransegtab WHERE sseguro = aa.sseguro) y cruces AND a.nmovimi = b.nmovimi y AND gs.nmovimi = a.nmovimi para evitar duplicados de registros.
      v_tconsulta := v_tconsulta || ' FROM (SELECT * FROM pregungaransegtab aa WHERE sseguro = ' || psseguro || ' AND ccolumna = 1 AND nmovimi = (SELECT MAX(nmovimi) FROM pregungaransegtab WHERE sseguro = aa.sseguro) ) a INNER JOIN ' || ' (SELECT * FROM pregungarancartab WHERE sseguro = ' || psseguro || ' AND ccolumna = 2) b ON a.sseguro = b.sseguro AND a.nriesgo = b.nriesgo AND a.cgarant = b.cgarant AND a.nlinea = b.nlinea AND a.nmovimi = b.nmovimi ' || ' INNER JOIN garangenpro c ON a.cgarant = c.cgarant ' || ' INNER JOIN garanpro p ON c.cgarant = p.cgarant ' || ' INNER JOIN productos pp ON p.sproduc = pp.sproduc ' || ' INNER JOIN seguros se  ON p.sproduc = se.sproduc AND a.sseguro = se.sseguro AND p.cactivi = ' || v_actividad;
      v_tconsulta := v_tconsulta || ' INNER JOIN garancar g ON g.sseguro = b.sseguro AND g.cgarant = b.cgarant AND g.sproces = ' || psproces || ' INNER JOIN garanseg gs ON gs.sseguro = b.sseguro AND gs.cgarant = b.cgarant AND gs.nmovimi = a.nmovimi';
      --FIN-MPC-BUG 45497-13/08/2018 - Se adiciona filtro AND nmovimi = (SELECT MAX(nmovimi) FROM pregungaransegtab WHERE sseguro = aa.sseguro) y cruces AND a.nmovimi = b.nmovimi y AND gs.nmovimi = a.nmovimi para evitar duplicados de registros.
      v_tconsulta := v_tconsulta || ' WHERE c.cidioma = ' || pcidioma;
    END IF;
    v_tconsulta := v_tconsulta || ' ORDER BY NORDEN,IMPRESION DESC, NLINEA';
    OPEN vr_cursor FOR v_tconsulta;
    LOOP
      FETCH vr_cursor
      INTO v_norden,
        v_tlinia,
        v_tlinia1,
        v_tlinia2,
        v_nimpresion,
        v_tlinia3,
        v_nlinea;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    IF pcampo = 1 THEN
      -- INI JFN QT_28989
      IF v_nimpresion    = 1 THEN
        v_ntabs         := ' ' || 'esp!1';
      ELSIF v_nimpresion = 0 THEN
        v_ntabs         := '\tab \tab \tab \tab ' || 'esp!2';
      ELSIF v_nimpresion = -1 THEN
        v_ntabs         := '\tab \tab \tab \tab \tab \tab \tab \tab ' || 'esp!3';
      END IF;
      -- FIN JFN QT_28989
      v_tresult   := v_tresult || v_ntabs || v_tlinia1 || '\par ';
    ELSIF pcampo   = 2 THEN
      --amantium - 29/VI/2021 - QT64890 - Inicio ****************
      --IF v_tlinia2 = '0' THEN
