      END IF;
      IF v_nimpresion    = 1 THEN
        --amantium - 29/VI/2021 - QT64890 - Inicio ****************
        --v_tresult       := v_tresult || '\par ';
        v_tresult       := v_tresult || '  '  || '\par ';
        --amantium - 29/VI/2021 - QT64890 - Fin *******************
      ELSIF v_nimpresion = 0 THEN
      --INI BUG AITSSD-1635 - 28/09/2022 - GZG se retira bug QT64890 y se deja como estaba inicialmente
        --amantium - 29/VI/2021 - QT64890 - Inicio ****************
        v_tresult       := v_tresult || '  ' || v_tlinia2 || '\par ';
        --v_tresult       := v_tresult || '\par ';
        --amantium - 29/VI/2021 - QT64890 - Fin *******************
      --FIN BUG AITSSD-1635 - 28/09/2022 - GZG
      ELSIF v_nimpresion = -1 THEN
        --amantium - 29/VI/2021 - QT64890 - Inicio ****************
        --v_tresult       := v_tresult || '\par ';
