/*****************************************************************
FUNCTION f_titulo_cumplimiento
Devuelve el texto del titulo de las polizas de cumplimiento
filtrado por sseguro y nmovimi
param IN psseguro  : codigo de seguro
param IN pnmovimi  : numero de movimiento
return             : texto de la pregunta 6006 con el titulo del producto
-- Bug 39750 - 13/12/2017 - JFN - INICIO
******************************************************************/
--INI JFN CUMPLI_17012018 QT39750
FUNCTION f_titulo_cumplimiento(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER)
  RETURN VARCHAR2
IS
  v_tconsulta    VARCHAR2 (32000);
  v_act0         VARCHAR2 (32000);
  v_tconsultacod VARCHAR2 (32000);
  respuesta      NUMBER := 1;
BEGIN
  SELECT crespue
  INTO respuesta
  FROM pregunpolseg
  WHERE cpregun = 6006
  AND sseguro   = psseguro
    -- Inicio  27/02/2019  WAFS   BUG 48926
  AND nmovimi =
    (SELECT MAX(pps.nmovimi)
    FROM pregunpolseg pps
    WHERE pps.cpregun = 6006
    AND pps.sseguro   = psseguro
    );
  -- Fin 27/02/2019  WAFS   BUG 48926
  SELECT tconsulta
  INTO v_tconsultacod
  FROM codipregun
  WHERE cpregun = 6006;
  v_tconsulta  := 'BEGIN select nval7 into :v_act0 from ';
  v_tconsulta  := v_tconsulta || ' ( ' || v_tconsultacod || ' )';
  v_tconsulta  := v_tconsulta || ' where ccla1 = :respuesta; END;';
  --v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
  EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
  IN respuesta;
  RETURN v_act0;
EXCEPTION
WHEN OTHERS THEN
  RETURN ' ';
END f_titulo_cumplimiento;
FUNCTION f_cod_barras_cumplimiento(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER,
    pcdup    IN NUMBER DEFAULT 0,
    pnrecibo IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
  v_tresult VARCHAR2 (4000);
  vcod      VARCHAR2 (100);
  vnrec     VARCHAR2 (100);
  vtot      VARCHAR2 (100);
  vfefec    VARCHAR2 (100);
  v_nrecibo recibos.nrecibo%TYPE;
  vcramo        NUMBER;
  vcccompani    NUMBER;
  v_cod_ean     NUMBER;
  v_ncertif     NUMBER;
  vitotalr      NUMBER;
  v_ult_nrecibo NUMBER;
  v_sproduc seguros.sproduc%TYPE;
  v_crespue6006 pregunpolseg.crespue%TYPE;
BEGIN
  --Obtener el Ãºltimo recibo generado.
  v_ult_nrecibo := pac_isqlfor_lcol.f_recibo_mov (psseguro => psseguro, pnmovimi => pnmovimi);
  IF pcdup       = 1 THEN
    RETURN NULL;
  END IF;
  SELECT cramo,
    DECODE (ccompani, 325, 0, ccompani),
    ncertif,
    sproduc
  INTO vcramo,
    vcccompani,
    v_ncertif,
    v_sproduc
  FROM seguros
  WHERE sseguro = psseguro;
  IF (vcramo    = 103 AND pnrecibo IS NULL AND v_ncertif <> 0) THEN
    RETURN NULL;
  END IF;
  IF (pnrecibo IS NULL) THEN
    BEGIN
      SELECT nrecibo
      INTO v_nrecibo
      FROM recibos
      WHERE sseguro = psseguro
      AND nrecibo   =
        (SELECT MAX (nrecibo)
        FROM recibos r
        WHERE r.sseguro = psseguro
        AND r.nmovimi   = pnmovimi
        AND r.nrecibo   = NVL (v_ult_nrecibo, r.nrecibo)
        );
    EXCEPTION
    WHEN OTHERS THEN
      v_nrecibo := 0;
    END;
  ELSE
    v_nrecibo := NVL (v_ult_nrecibo, pnrecibo);
  END IF;
  BEGIN
    SELECT itotalr INTO vitotalr FROM vdetrecibos WHERE nrecibo = v_nrecibo;
  EXCEPTION
  WHEN NO_DATA_FOUND THEN
    NULL;
  END;
  IF (vitotalr = 0) THEN
    RETURN NULL;
  END IF;
  --Obtener el cÃ³digo EAN de acuerdo a la pregunta 6006
  BEGIN
    SELECT crespue
    INTO v_crespue6006
    FROM pregunpolseg
    WHERE sseguro = psseguro
    AND nmovimi   = pnmovimi
    AND cpregun   = 6006;
    IF (v_crespue6006 IN (8, 13)) THEN --Particular/Disposiciones legales
      SELECT nval1
      INTO v_cod_ean
      FROM SGT_SUBTABS_DET
      WHERE ccla2   = 701
      AND csubtabla = 3032
      AND cversubt  = 3;
    ELSE --Estatal
      SELECT nval1
      INTO v_cod_ean
      FROM SGT_SUBTABS_DET
      WHERE ccla2   = 701
      AND csubtabla = 3032
      AND cversubt  = 1;
    END IF;
  EXCEPTION
  WHEN OTHERS THEN
    RETURN '';
  END;
  SELECT '415'
    || v_cod_ean cod,
    '-8020'
    || LPAD (r.nrecibo, 20, '0') nrec,
    '-3900'
    || LPAD ( NVL (ROUND (ABS (vd.itotalr), 0), 0), ( ( TRUNC (LENGTH (ROUND (ABS (vd.itotalr), 0)) / 2) + ( ( (LENGTH (ROUND (ABS (vd.itotalr), 0)) / 2) - TRUNC ( LENGTH (ROUND (ABS (vd.itotalr), 0)) / 2)) * 2)) * 2), '0') tot,
    '-96'
    || TO_CHAR ( NVL ( pac_isqlfor_lcol.f_flimitepag (psseguro, pnmovimi, m.cmotmov, 1, pnrecibo), ( m.femisio + pac_propio_lcol.f_numdias_periodo_gracia ( s.sseguro))), 'yyyymmdd') fefec
  INTO vcod,
    vnrec,
    vtot,
    vfefec
  FROM vdetrecibos_monpol vd,
    recibos r,
    seguros s,
    productos pp,
    movseguro m
  WHERE vd.nrecibo = r.nrecibo
  AND r.sseguro    = s.sseguro
  AND s.sseguro    = m.sseguro
  AND r.nmovimi    = m.nmovimi
  AND r.sseguro    = psseguro
  AND s.sproduc    = pp.sproduc
  AND r.nmovimi    = pnmovimi
  AND r.nrecibo    = v_nrecibo;
  v_tresult       := vcod || vnrec || vtot || vfefec;
  RETURN (pac_isqlfor_lcol.f_jrep_trad (v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_cod_barras_cumplimiento;
--FIN JFN CUMPLI_17012018 QT39750
--INICIO BUG 0040064 - YMG
FUNCTION f_clausulas_ggbb(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER)
  RETURN CLOB
IS
  w_clave_convenio pregunseg.crespue%TYPE;
  vret CLOB;
BEGIN
  SELECT crespue
  INTO w_clave_convenio
  FROM pregunseg
  WHERE sseguro = psseguro
  AND cpregun   = 6032
  AND nmovimi   = pnmovimi
  AND nriesgo   = 1;
  FOR i IN
  (SELECT ttitulo
    || ' \par '
    || tclatext clau
  FROM ggbb_clausulas
  WHERE (nclausul, ctipo) IN
    (SELECT nclausul,
      ctipo
    FROM ggbb_clausulas_gb
    WHERE nversion = w_clave_convenio
    )
  )
  LOOP
    vret := vret || i.clau || ' \par \par ';
  END LOOP;
  vret := REPLACE (vret, CHR (10), ' '); --Bug 0040064 (13/02/2018)
  RETURN f_jrep_trad_pyme (' \par \par ' || vret);
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_clausulas_ggbb;
