/*****************************************************************
FUNCTION f_total_recibo_monpol
Devuelve el total de los recibos sobre el monpol.
param IN pnrecibo  : codigo de recibo
param IN ptpconce  : tipo de concepto 1 total prima
2 total gastos de expedicion
3 total impuestos
return             : Valor total recibo.
--Bug 0042736 - 25/06/2018 - AABC - INICIO
******************************************************************/
FUNCTION f_total_recibo_monpol(
    pnrecibo IN NUMBER,
    ptpconce IN NUMBER)
  RETURN NUMBER
IS
  v_totmonpol NUMBER := 0;
  v_recanter  NUMBER;
BEGIN
  --
  IF v_recanter IS NULL THEN
    v_recanter  := pnrecibo;
  END IF;
  --
  IF ptpconce = 1 THEN
    --
    SELECT ROUND(NVL(SUM(iconcep_monpol),0),2)
    INTO v_totmonpol
    FROM detrecibos
    WHERE nrecibo = pnrecibo
    AND cconcep  IN (0,4,14,86);
  ELSIF ptpconce  = 2 THEN
    --
    SELECT ROUND(NVL(SUM(iconcep_monpol),0),2)
    INTO v_totmonpol
    FROM detrecibos
    WHERE nrecibo = pnrecibo
    AND cconcep   = 14;
    --
  ELSIF ptpconce = 3 THEN
    --
    SELECT ROUND(NVL(SUM(iconcep_monpol),0),2)
    INTO v_totmonpol
    FROM detrecibos
    WHERE nrecibo = pnrecibo
    AND cconcep  IN(4,86);
    --
  END IF;
  --
  RETURN ROUND(v_totmonpol,0);
EXCEPTION
WHEN OTHERS THEN
  v_totmonpol := 0;
  RETURN v_totmonpol;
END f_total_recibo_monpol;
--
/*****************************************************************
FUNCTION f_rec_total_monpol
Devuelve el total de los recibos sobre el monpol.
param IN psseguro  : codigo de sseguro
param IN pfecha    : fecha de recibos
param IN ptpconce  : tipo de concepto 1 total prima
2 total gastos de expedicion
3 total impuestos
4 total recibo
5 total descuentos
6 total IT2REC
7 total IRECFRA
return             : Valor total recibo.
--Bug 0042736 - 25/06/2018 - AABC
******************************************************************/
FUNCTION f_rec_total_monpol(
    psseguro IN NUMBER,
    pfecha   IN VARCHAR2,
    ptpconce IN NUMBER)
  RETURN NUMBER
IS
  CURSOR c_recibo
  IS
    SELECT RCB.NRECIBO,
      (
      CASE
        WHEN MRCB.CESTREC = 0
        THEN TO_DATE(TO_CHAR(RCB.FEMISIO,'MM/YYYY'),'MM/YYYY')
        ELSE
          CASE
            WHEN MRCB.CESTREC = 2
            THEN TO_DATE(TO_CHAR(MRCB.FMOVDIA,'MM/YYYY'),'MM/YYYY')
          END
      END) AS FECHA,
      RCB.CTIPREC,
      MRCB.CESTREC
    FROM RECIBOS RCB,
      SEGUROS S,
      PREGUNPOLSEG PGP,
      MOVRECIBO MRCB
    WHERE S.NPOLIZA      = psseguro
    AND S.CRAMO          = 105
    AND PGP.NMOVIMI      = 1
    AND PGP.CPREGUN      = 4084
    AND RCB.CTIPREC NOT IN (13, 15)
    AND RCB.SSEGURO      = S.SSEGURO
    AND PGP.SSEGURO      = S.SSEGURO
    AND (
      CASE
        WHEN MRCB.CESTREC = 0
        THEN TO_CHAR(RCB.FEMISIO, 'MM/YYYY')
        ELSE
          CASE
            WHEN MRCB.CESTREC = 2
            THEN TO_CHAR(MRCB.FMOVDIA, 'MM/YYYY')
          END
      END)            = pfecha
    AND MRCB.CESTREC IN (0, 2)
    AND MRCB.NRECIBO  = RCB.NRECIBO;
  --
  v_total_acum NUMBER := 0;
  v_total_pag  NUMBER := 0;
  v_cconcep    VARCHAR2(20);
  --
BEGIN
  --
  IF ptpconce = 1 THEN
    --
    v_cconcep := '0';
    --
  ELSIF ptpconce = 2 THEN
    --
    v_cconcep := '14';
    --
  END IF;
  --
  FOR x IN c_recibo
  LOOP
    --
    IF ptpconce NOT IN (3,4) THEN
      --
      SELECT ROUND(NVL(SUM(DR.ICONCEP_MONPOL),0),2)
      INTO v_total_pag
      FROM DETRECIBOS DR
      WHERE DR.NRECIBO = X.NRECIBO
      AND dr.cconcep  IN (v_cconcep);
      --
    ELSIF ptpconce = 3 THEN
      --
      SELECT ROUND(NVL(SUM(DR.ICONCEP_MONPOL),0),2)
      INTO v_total_pag
      FROM DETRECIBOS DR
      WHERE DR.NRECIBO = X.NRECIBO
      AND dr.cconcep  IN (4,86);
      --
    ELSIF ptpconce = 4 THEN
      --
      SELECT ROUND(NVL(SUM(DR.ICONCEP_MONPOL),0),2)
      INTO v_total_pag
      FROM DETRECIBOS DR
      WHERE DR.NRECIBO = X.NRECIBO
      AND dr.cconcep  IN (0,4,14,86);
      --
    ELSIF ptpconce = 5 THEN
      --
      SELECT ROUND(NVL(SUM(DR.IT1DTO),0),2)
      INTO v_total_pag
      FROM VDETRECIBOS DR
      WHERE DR.NRECIBO = X.NRECIBO ;
      --
    ELSIF ptpconce = 6 THEN
      --
      SELECT ROUND(NVL(SUM(DR.IT2REC),0),2)
      INTO v_total_pag
      FROM VDETRECIBOS DR
      WHERE DR.NRECIBO = X.NRECIBO ;
      --
    ELSIF ptpconce = 7 THEN
      --
      SELECT ROUND(NVL(SUM(DR.IRECFRA),0),2)
      INTO v_total_pag
      FROM VDETRECIBOS DR
      WHERE DR.NRECIBO = X.NRECIBO ;
      --
    END IF;
    --
    IF X.CTIPREC      = 9 THEN
      IF X.CESTREC    = 0 THEN
        v_total_pag  := v_total_pag * -1;
      ELSIF X.CESTREC = 2 THEN
        v_total_pag  := v_total_pag;
      END IF;
    ELSE
      IF X.CESTREC   = 2 THEN
        v_total_pag := v_total_pag * -1;
      ELSE
        v_total_pag := v_total_pag;
      END IF;
    END IF;
    --
    v_total_acum := v_total_acum + ROUND(v_total_pag,2);
    --
  END LOOP;
  --
  RETURN v_total_acum;
  --
END f_rec_total_monpol;
--Bug 0042736 - 25/06/2018 - AABC - FIN
--Bug 0043870 - 27/07/2018 - JMOS - INICIO
/*****************************************************************
FUNCTION f_calcu_prima_min
Devuelve el valor de la prima minima dependiendo la pregunta.
param IN psseguro  : codigo de sseguro
return             : Valor total prima minima.
******************************************************************/
FUNCTION f_calcu_prima_min(
    psseguro IN NUMBER)
  RETURN NUMBER
IS
  v_resultado NUMBER:=0;
BEGIN
  BEGIN
    SELECT (
      CASE
        WHEN pre2.crespue IS NOT NULL
        THEN pre2.crespue
        WHEN pre2.crespue IS NULL
        AND pre.crespue    >
          (SELECT SUM(itotalr) FROM estprimasgaranseg e WHERE e.sseguro = s.sseguro
          )
        THEN pre.crespue
        ELSE
          (SELECT SUM(e.ipritar) FROM estprimasgaranseg e WHERE e.sseguro = psseguro
          )
      END) prima_total
    INTO v_resultado
    FROM estseguros s
    INNER JOIN estdetmovseguro m
    ON s.sseguro = m.sseguro
    INNER JOIN estpregunpolseg pre
    ON pre.sseguro  = s.sseguro
    AND pre.cpregun = 9886
    LEFT JOIN estpregunpolseg pre2
    ON pre2.sseguro  = s.sseguro
    AND pre2.cpregun = 4821
    WHERE s.sseguro  = psseguro;
  EXCEPTION
  WHEN no_data_found THEN
    v_resultado := 0;
  END;
  RETURN v_resultado;
END f_calcu_prima_min;
