/*****************************************************************
FUNCTION f_calcu_iva
Devuelve el valor del IVA mas 1
return             : Valor del IVA mas 1
******************************************************************/
FUNCTION f_calcu_iva
  RETURN NUMBER
IS
  v_resultado NUMBER:=0;
  v_total_iva NUMBER:=0;
BEGIN
  BEGIN
    SELECT ptipiva
    INTO v_resultado
    FROM tipoiva
    WHERE ffinvig IS NULL
    AND ctipiva    = 1;
  EXCEPTION
  WHEN no_data_found THEN
