  END;
  v_total_iva:=((v_resultado / 100)+1);
  RETURN v_total_iva;
END f_calcu_iva;
/*****************************************************************
FUNCTION f_calcu_tot_impue
Devuelve el valor de los impuestos dependiendo el valor de la prima minima.
param IN psseguro  : codigo de sseguro
pcforpag  : codigo de forma de pago
return             : Valor total de los impuesto segun prima minima
******************************************************************/
FUNCTION f_calcu_tot_impue(
    psseguro IN NUMBER,
    pcforpag IN seguros.cforpag%TYPE)
  RETURN NUMBER
IS
  v_resultado NUMBER:=0;
  v_prima_tarifa estprimasgaranseg.ipritar%TYPE;
  v_valor_prima NUMBER:=0;
  --
  --INI BUG 0045800 - 23/08/2018 - CASL - Se crea nueva variable
  --
  v_cforpag NUMBER;
  --
  --FIN BUG 0045800 - 23/08/2018 - CASL
  --
BEGIN
  --
  --INI BUG 0045800 - 23/08/2018 - CASL - Se valida que la forma de pago no sea cero(0)
  --
  IF pcforpag = 0 THEN
    --
    v_cforpag := 1;
    --
  ELSE
    --
    v_cforpag := pcforpag;
    --
  END IF;
  --
  --FIN BUG 0045800 - 23/08/2018 - CASL
  --
  BEGIN
    SELECT SUM(e.itotalr)
    INTO v_valor_prima
    FROM estprimasgaranseg e
    WHERE e.sseguro = psseguro;
  EXCEPTION
  WHEN no_data_found THEN
    v_valor_prima := 0;
  END;
  IF v_valor_prima >= f_calcu_prima_min(psseguro) THEN
    BEGIN
      SELECT SUM(e.ipritar)
      INTO v_prima_tarifa
      FROM estprimasgaranseg e
      WHERE e.sseguro = psseguro;
    EXCEPTION
    WHEN no_data_found THEN
      v_prima_tarifa := 0;
    END;
    v_resultado:=((v_prima_tarifa/v_cforpag)+f_calcu_asistencia(psseguro)+f_calcu_gast_exped(psseguro))*((f_calcu_iva)-1);--BUG 0045800 - 23/08/2018 - CASL - Se cambia pcforpag por v_cforpag
  ELSE
    v_resultado:= (((f_calcu_prima_min(psseguro)/v_cforpag)+f_calcu_asistencia(psseguro)+f_calcu_gast_exped(psseguro))*(f_calcu_iva-1));--BUG 0045800 - 23/08/2018 - CASL - Se cambia pcforpag por v_cforpag
  END IF;
  RETURN v_resultado;
END f_calcu_tot_impue;
