******************************************************************/
FUNCTION f_calcu_primer_recibo(
    psseguro IN NUMBER,
    pcforpag IN seguros.cforpag%TYPE)
  RETURN NUMBER
IS
  v_resultado   NUMBER:=0;
  v_valor_prima NUMBER:=0;
BEGIN
  BEGIN
    SELECT SUM(e.itotalr)
    INTO v_valor_prima
    FROM estprimasgaranseg e
    WHERE e.sseguro = psseguro;
  EXCEPTION
  WHEN no_data_found THEN
