/*****************************************************************
FUNCTION f_triesgo
Devuelve el tipo de riesgo.
para imprimir en PDF Automovil
param IN psseguro  : codigo de sseguro
pnmovimi  : codigo movimiento
pcidioma  : codigo de idioma
return    : Valor del tipo de riesgo Pesado, Liviano, Moto o Taxi
Bug 44835 - 27/08/2018 - ARM - INICIO
******************************************************************/
FUNCTION f_triesgo_val(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER,
    pcidioma IN NUMBER)
  RETURN VARCHAR2
IS
  v_tconsulta  VARCHAR2 (32000);
  v_tconsulta2 VARCHAR2 (32000);
  v_resultado  VARCHAR2 (32000);
BEGIN
  SELECT A.CUSO
  INTO v_tconsulta2
  FROM autriesgos A,
    aut_versiones B,
    aut_desuso C
  WHERE A.SSEGURO = psseguro
  AND A.CVERSION  = B.CVERSION
  AND A.CUSO      = C.CUSO
  AND A.NMOVIMI   = pnmovimi
  AND C.CIDIOMA   =pcidioma;
  SELECT b.ctipveh nro_tipo_vehiculo
  INTO v_tconsulta
  FROM aut_versiones a,
    aut_destipveh b,
    autriesgos c
  WHERE b.CTIPVEH = a.ctipveh
  AND cidioma     = pcidioma
  AND a.cversion  = c.cversion
  AND c.nmovimi   = pnmovimi
  AND c.sseguro   = psseguro;
  IF v_tconsulta2 = 19 THEN
    v_resultado  := 'TAXI';
  ELSIF v_tconsulta IN ('17', '18', '19') THEN
    v_resultado := 'MOTO';
  ELSIF v_tconsulta IN ('03', '04', '07', '10', '11', '12', '22', '23', '25', '26') THEN
    v_resultado := 'PESADO';
  ELSIF v_tconsulta IN ('01', '02', '06', '08', '20', 21) THEN
    v_resultado := 'LIVIANO';
  END IF;
  RETURN v_resultado;
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_triesgo_val;
--Bug 44835 - 27/08/2018 - ARM - FIN
--INI BUG 47494 MPC 08/03/2019 Se crea funcion.
FUNCTION f_gast4095(
    v_sseguro IN NUMBER,
    pcampo    IN NUMBER,
    pfefecto  IN DATE)
  RETURN NUMBER
IS
  v_4093               NUMBER;
  v_4095               NUMBER;
  vnum_err             NUMBER;
  v_igasexpe           NUMBER;
  v_vprovin            NUMBER;
  v_sproduc            NUMBER;
  v_nriesgo            NUMBER;
  v_resp_4928          NUMBER;
  v_ivarec             NUMBER;
  tot_iconcepivaderreg NUMBER := 0;
  v_ncertif            NUMBER;
BEGIN
  --
  SELECT ncertif INTO v_ncertif FROM seguros WHERE sseguro = v_sseguro;
  --
  SELECT a.crespue,
    (SELECT SPRODUC FROM SEGUROS WHERE SSEGURO = v_sseguro
    ) sproduc
  INTO v_igasexpe,
    v_sproduc
  FROM pregunpolseg a
  WHERE a.cpregun = 4093
  AND a.sseguro   = v_sseguro
  AND a.nmovimi   =
    (SELECT MIN(b.nmovimi)
    FROM pregunpolseg b
    WHERE b.cpregun = 4095
    AND b.sseguro   = v_sseguro
    );
  IF v_igasexpe = 1 THEN -- Si aplica gastos de expedicion
    BEGIN
      SELECT crespue
      INTO v_igasexpe
      FROM pregunpolseg
      WHERE cpregun = 4095
      AND sseguro   = v_sseguro
      AND nmovimi   =
        (SELECT MIN(b.nmovimi)
        FROM pregunpolseg b
        WHERE b.cpregun = 4095
        AND b.sseguro   = v_sseguro
        );
      IF pcampo = 1 AND ((v_ncertif = 0 AND v_igasexpe = 1) OR (v_ncertif != 0 AND v_igasexpe = 2)) THEN
        RETURN (v_igasexpe);
      ELSIF (v_ncertif = 0 AND v_igasexpe = 1) OR (v_ncertif != 0 AND v_igasexpe = 2) THEN
        --
        IF v_sproduc = 900742 OR pac_parametros.f_parproducto_n(v_sproduc, 'GASTEXP_CALCULO') = 3 THEN
          BEGIN
            SELECT MIN(b.nriesgo)
            INTO v_nriesgo
            FROM sitriesgo a
            INNER JOIN riesgos b
            ON a.nriesgo    = b.nriesgo
            AND a.sseguro   = b.sseguro
            WHERE a.sseguro = v_sseguro
            AND fanulac    IS NULL;
          EXCEPTION
          WHEN OTHERS THEN
            v_nriesgo := 1;
          END;
          SELECT (
            CASE
                --TRANSPORTADORAS - RECIBO - NO GENERA IVA PARA LOS GASTOS DE EXPEDICION
              WHEN NVL(pac_impuestos_lcol.f_iva_provinciariesgo('SEG', v_sseguro, v_nriesgo), 0) NOT IN(91, 88) -- Agregar nvl para mejor validacion
                --
              THEN 1
              ELSE 0
            END)
          INTO v_vprovin
          FROM DUAL;
        ELSE
          v_vprovin := 1;
        END IF;
        --
        vnum_err := pac_preguntas.f_get_pregunpolseg(v_sseguro, 4928, 'SEG', v_resp_4928);
        --
        IF (NVL(v_vprovin, 1) = 1
          -- COBRO DE GASTOS DE EXPEDICION
          AND v_resp_4928 IN(0)) THEN
          -- COBRO DE GASTOS DE EXPEDICION
          BEGIN
            SELECT ptipiva
            INTO v_ivarec
            FROM tipoiva
            WHERE finivig >= TRUNC(pfefecto)
            AND ffinvig   IS NULL
            AND ctipiva    = 1;
          EXCEPTION
          WHEN OTHERS THEN
            BEGIN
              SELECT ptipiva
              INTO v_ivarec
              FROM tipoiva
              WHERE finivig < TRUNC(pfefecto)
              AND ffinvig  IS NULL
              AND ctipiva   = 1;
            EXCEPTION
            WHEN OTHERS THEN
              v_ivarec := 0;
            END;
          END;
          tot_iconcepivaderreg :=(v_igasexpe *(v_ivarec / 100));
          --
          RETURN tot_iconcepivaderreg;
        END IF;
        --
      END IF;
      RETURN 0;
    EXCEPTION
    WHEN OTHERS THEN
      RETURN 0;
    END;
  ELSE
    RETURN 0;
  END IF;
EXCEPTION
WHEN OTHERS THEN
  RETURN 0;
END f_gast4095;
