--INI BUG 51633 MPC 13/05/2019 Se crea funcion.
/*****************************************************************
FUNCTION f_benespseg_p_t
param IN psidepag  :
param IN pcidioma  :
param IN pcamp     : Codigo de campo
return             : texto
Se clona la funciÃ³n debido a que no debe repetir los beneficiaros debe traer los distintos solamente.
******************************************************************/
FUNCTION f_benespseg_p_t(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER,
    pcidioma IN NUMBER,
    pcamp    IN NUMBER)
  RETURN VARCHAR2
IS
  v_tresult  VARCHAR2(4000);
  v_tresult2 VARCHAR2(4000);
  v_ncont    NUMBER := 0;
  v_sproduc  NUMBER;
  v_nerror   NUMBER;
BEGIN
  --
  v_nerror := pac_seguros.f_get_sproduc(psseguro, 'POL', v_sproduc);
  FOR i IN
  (SELECT b.sperson
  FROM benespseg b
  WHERE b.sseguro = psseguro
  AND b.nmovimi   = pnmovimi
  )
  LOOP
    v_ncont := v_ncont + 1;
  END LOOP;
  IF v_ncont = 0 THEN
    FOR i IN
    (SELECT b.sperson
    FROM benespseg b
    WHERE b.sseguro = psseguro
    AND b.nmovimi   =
      (SELECT MAX(nmovimi) FROM benespseg WHERE sseguro = psseguro
      )
    )
    LOOP
      v_ncont := v_ncont + 1;
    END LOOP;
  END IF;
  IF NVL(pac_parametros.f_parproducto_n(v_sproduc, 'VIG_BENEFICIARIO'), 0) = 1 AND v_ncont = 0 AND v_nerror = 0 THEN
    RAISE NO_DATA_FOUND;
  END IF;
  --
  FOR i           IN
  (SELECT DISTINCT *
  FROM
    (SELECT SUBSTR(f_dades_persona(ben.sperson, 8, pcidioma, 'POL'), 1, 5) --BUG 47494 MPC 10/05/2019 Se adiciona DISTINCT
      || ' '
      || f_dades_persona(ben.sperson, 1, pcidioma, 'POL') idbenef,
      (SELECT TRIM(tnombre)
        || ' '
        || TRIM(tapelli1
        || ' '
        || tapelli2)
      FROM per_detper
      WHERE sperson = ben.sperson
      AND ROWNUM    = 1
      ) nombenef,
      ff_desvalorfijo(1054, pcidioma, ben.cparen) parentbenef,
      ben.pparticip porcbenef,
      f_dades_persona(ben.sperson_tit, 8, pcidioma, 'POL')
      || ' '
      || f_dades_persona(ben.sperson_tit, 1, pcidioma, 'POL') contbenef,
      NULL acrebenef,
      'S' benefaccid,
      (SELECT tvalcon
      FROM per_contactos
      WHERE sperson = ben.sperson
      AND ctipcon   = 1
      AND cmodcon   =
        (SELECT MAX(cmodcon)
        FROM per_contactos
        WHERE sperson = ben.sperson
        AND ctipcon   = 1
        )
      ) telefonobnf,
      NULL bnfpoblac,
      NULL bnfdirec,
      ben.sperson,
      ( SELECT fnacimi FROM per_personas WHERE sperson = ben.sperson
      ) fechanacim
    FROM benespseg ben
    WHERE ben.sseguro = psseguro
    AND cgarant       = 0
    AND nmovimi       =
      (SELECT MAX(nmovimi)
      FROM benespseg
      WHERE sseguro = psseguro
      AND nmovimi  <= pnmovimi
      )
    ORDER BY nriesgo ASC,
      sperson_tit ASC,
      pparticip DESC,
      fmovimi ASC,
      ROWID ASC
    )
  )
  LOOP
    IF pcamp     = 1 THEN
      v_tresult := v_tresult || i.idbenef || ' \par ';
    ELSIF pcamp  = 2 THEN
      v_tresult := v_tresult || i.nombenef || ' \par ';
    ELSIF pcamp  = 3 THEN
      v_tresult := v_tresult || i.parentbenef || ' \par ';
    ELSIF pcamp  = 4 THEN
      v_tresult := v_tresult || i.porcbenef || ' \par ';
    ELSIF pcamp  = 5 THEN
      v_tresult := v_tresult || i.contbenef || ' \par ';
    ELSIF pcamp  = 6 THEN
      v_tresult := v_tresult || i.acrebenef || ' \par ';
    ELSIF pcamp  = 7 THEN
      v_tresult := v_tresult || i.telefonobnf || ' \par ';
    ELSIF pcamp  = 8 THEN
      -- INI RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios. Se busca en asegurados - tomadores - La Direccion de Residencia -  La Maxima Direccion
      --v_tresult := v_tresult || i.bnfpoblac || ' \par ';
      BEGIN
        --
        SELECT DISTINCT pac_isqlfor.f_poblacion(i.sperson, rmax_domici) --SELECT PAC_ISQLFOR.F_POBLACION(i.SPERSON, RMAX_DOMICI)
          --FIN BUG 37907 - 17/10/2017 - LGG
          || ' \par '
        INTO v_tresult
        FROM
          -- Ini  47966 -- ECP -- 11/12/2019
          (
          SELECT MAX(b.cdomici) AS rmax_domici
          FROM benespseg a,
            asegurados b
          WHERE a.sseguro = psseguro
          AND a.sseguro   = b.sseguro
          AND a.sperson   = b.sperson
          AND a.sperson   = i.sperson
          AND a.cgarant   = 0
          AND a.nmovimi   =
            (SELECT MAX(nmovimi)
            FROM benespseg
            WHERE sseguro = psseguro
            AND nmovimi  <= pnmovimi
            )
          );
        -- Fin  47966 -- ECP -- 11/12/2019
        -- INI BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
        IF v_tresult = ' \par ' THEN
          RAISE NO_DATA_FOUND;
        END IF;
        -- FIN BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
      EXCEPTION
      WHEN NO_DATA_FOUND THEN
        BEGIN
          --INICIO BUG 37907 - 17/10/2017 - LGG
          SELECT DISTINCT pac_isqlfor.f_poblacion(i.sperson, rmax_domici) --SELECT PAC_ISQLFOR.F_POBLACION(i.SPERSON, RMAX_DOMICI)
            --FIN BUG 37907 - 17/10/2017 - LGG
            || ' \par '
          INTO v_tresult
          FROM
            -- Ini  47966 -- ECP -- 11/12/2019
            (
            SELECT MAX(b.cdomici) AS rmax_domici
            FROM benespseg a,
              tomadores b
            WHERE a.sseguro = psseguro
            AND a.sseguro   = b.sseguro
            AND a.sperson   = b.sperson
            AND a.sperson   = i.sperson
            AND a.cgarant   = 0
            AND a.nmovimi   =
              (SELECT MAX(nmovimi)
              FROM benespseg
              WHERE sseguro = psseguro
              AND nmovimi  <= pnmovimi
              )
            );
          -- Fin  47966 -- ECP -- 11/12/2019
          -- INI BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
          IF v_tresult = ' \par ' THEN
            RAISE NO_DATA_FOUND;
          END IF;
          -- FIN BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
        EXCEPTION
        WHEN NO_DATA_FOUND THEN
          BEGIN
            SELECT pac_isqlfor.f_poblacion(i.sperson, MAX(cdomici))
              || ' \par ' AS rmax_domici -- BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
            INTO v_tresult
            FROM per_direcciones
            WHERE sperson = i.sperson
            AND ctipdir   = 9;
            -- INI BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
            IF v_tresult = ' \par ' THEN
              RAISE NO_DATA_FOUND;
            END IF;
            -- FIN BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
          EXCEPTION
          WHEN NO_DATA_FOUND THEN
            BEGIN
              SELECT pac_isqlfor.f_poblacion(i.sperson, MAX(cdomici))
                || ' \par ' AS rmax_domici -- BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
              INTO v_tresult
              FROM per_direcciones
              WHERE sperson = i.sperson;
            EXCEPTION
            WHEN OTHERS THEN
              RETURN ('');
            END;
          END;
        END;
      END;
      -- FIN RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios. Se busca en asegurados - tomadores - La Direccion de Residencia -  La Maxima Direccion
    ELSIF pcamp = 9 THEN
      -- INI RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios. Se busca en asegurados - tomadores - La Direccion de Residencia -  La Maxima Direccion
      --v_tresult := v_tresult || i.bnfdirec || ' \par ';
      BEGIN
        --Inicio bug 0039987 - YMG
        SELECT PAC_ISQLFOR_LCOL.F_DIRECCION(i.SPERSON, RMAX_DOMICI)
          --Fin bug
          || ' \par '
        INTO v_tresult2--BUG 0043516 - 24/05/2018 - CASL - Se cambia la variable del resultado
        FROM
          (SELECT b.cdomici AS rmax_domici
          FROM benespseg a,
            asegurados b
          WHERE a.sseguro = psseguro
          AND a.sseguro   = b.sseguro
          AND a.sperson   = b.sperson
          AND a.sperson   = i.sperson
          AND a.cgarant   = 0
          AND a.nmovimi   =
            (SELECT MAX(nmovimi)
            FROM benespseg
            WHERE sseguro = psseguro
            AND nmovimi  <= pnmovimi
            )
          );
        -- INI BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
        IF v_tresult2 = ' \par ' THEN--BUG 0043516 - 24/05/2018 - CASL - Se cambia la variable del resultado
          RAISE NO_DATA_FOUND;
        END IF;
        -- FIN BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
      EXCEPTION
      WHEN NO_DATA_FOUND THEN
        BEGIN
          --Inicio bug 0039987 - YMG
          --Ini 47966 -- ECP -- 11/12/2018
          SELECT PAC_ISQLFOR_LCOL.F_DIRECCION(i.SPERSON, RMAX_DOMICI)
            --Fin bug 0039987
            || ' \par '
          INTO v_tresult2--BUG 0043516 - 24/05/2018 - CASL - Se cambia la variable del resultado
          FROM
            (SELECT MAX(b.cdomici) AS rmax_domici
            FROM benespseg a,
              tomadores b
            WHERE a.sseguro = psseguro
            AND a.sseguro   = b.sseguro
            AND a.sperson   = b.sperson
            AND a.sperson   = i.sperson
            AND a.cgarant   = 0
            AND a.nmovimi   =
              (SELECT MAX(nmovimi)
              FROM benespseg
              WHERE sseguro = psseguro
              AND nmovimi  <= pnmovimi
              )
            );
          --Fin 47966 -- ECP -- 11/12/2018
          -- INI BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
          IF v_tresult2 = ' \par ' THEN--BUG 0043516 - 24/05/2018 - CASL - Se cambia la variable del resultado
            RAISE NO_DATA_FOUND;
          END IF;
          -- FIN BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
        EXCEPTION
        WHEN NO_DATA_FOUND THEN
          BEGIN
            --Inicio bug 0039987 - YMG
            SELECT PAC_ISQLFOR_LCOL.F_DIRECCION(I.SPERSON,MAX(CDOMICI))
              --Fin bug 0039987
              || ' \par ' AS rmax_domici
            INTO v_tresult2--BUG 0043516 - 24/05/2018 - CASL - Se cambia la variable del resultado
            FROM per_direcciones
            WHERE sperson = i.sperson
            AND ctipdir   = 9;
            -- INI BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
            IF v_tresult2 = ' \par ' THEN--BUG 0043516 - 24/05/2018 - CASL - Se cambia la variable del resultado
              RAISE NO_DATA_FOUND;
            END IF;
            -- FIN BUG 0024342 RMGA  04/04/2016   INFORMACION INCOMPLETA EN PLANTILLAS PDF HOGAR GHI THI GHC THC - Ajuste para impresion de datos de beneficiarios .
          EXCEPTION
          WHEN NO_DATA_FOUND THEN
            BEGIN
              --Inicio bug 0039987 - YMG
              SELECT PAC_ISQLFOR_LCOL.F_DIRECCION(I.SPERSON,MAX(CDOMICI))
                --Fin bug 0039987
                || ' \par ' AS rmax_domici
              INTO v_tresult2--BUG 0043516 - 24/05/2018 - CASL - Se cambia la variable del resultado
              FROM per_direcciones
              WHERE sperson = i.sperson;
            EXCEPTION
            WHEN OTHERS THEN
              RETURN ('');
            END;
          END;
        END;
      END;
      --
      --INI BUG 0043516 - 24/05/2018 - CASL - Se asigna el resultado concatenado
      --
      v_tresult := v_tresult||v_tresult2;
      --
      --FIN BUG 0043516 - 24/05/2018 - CASL
      --
      -- FIN RMGA 25/02/2016 BUG 24268 Datos de Beneficiarios. Se busca en asegurados - tomadores - La Direccion de Residencia -  La Maxima Direccion
      -- INICIO Bug 31777 - LRGG - Adicion de la fecha de Nacimiento
    ELSIF pcamp  = 10 THEN
      v_tresult := v_tresult || i.fechanacim || ' \par ';
      -- FIN Bug 31777 - LRGG - Adicion de la fecha de Nacimiento
      -- inicio 164.0 22/10/2018  AAN   0046937 se ajusta funcion F_BENESPSEG
    ELSIF pcamp  = 11 THEN
      v_tresult := v_tresult || i.benefaccid || ' \par ';
    END IF;
    -- fin 164.0 22/10/2018  AAN  0046937 se ajusta funcion F_BENESPSEG
  END LOOP;
  RETURN (REPLACE(f_jrep_trad(v_tresult), CHR(39), ''));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_benespseg_p_t;
--FIN BUG 51633 MPC 13/05/2019 Se crea funcion.
--INI CALL 08/08/2019 0054010: Amparos Transporte
/*****************************************************************
FUNCTION f_garantias_riesgo_trans
Devuelve las garant?as de un riesgo
param IN psseguro  : codigo de seguro
param IN pnriesgo  : n?mero de riesgo
param IN pcidioma  : codigo de idioma
param IN pmodo     : modo EST/POL
return             : texto con las garant?as del riesgo
Bug 19927 - 28/11/2011 - JTS
******************************************************************/
FUNCTION f_garantias_riesgo_trans(
    psseguro IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1,
    pcidioma IN NUMBER DEFAULT 1,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(2000);
    v_tlinia    VARCHAR2(200);
    -- INI BUG 0035054/0017140 -- ECP -- 11/03/2015 - Se cambia v_tpargar      VARCHAR2(200); por
    v_tpargar VARCHAR2(300);
    -- FIN BUG 0035054/0017140 -- ECP -- 11/03/2015
    v_tablaseg  VARCHAR2(30);
    v_act0      NUMBER(1);
    v_actividad VARCHAR2(20);
    v_csituac   VARCHAR2(100);
    v_es_admin  NUMBER; --Bug 33145/192146 - 03/12/2014 - AMC
    v_ncertif   NUMBER; --BUG 0036927 - 18/08/2017 - CASL - Se crea la variable del certificado.
  BEGIN
    -- BUG 16092 - 12/01/2011 - JMP - AGA RC: Miramos si las garant?as est?n definidas para la actividad del seguro
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tablaseg        := 'estseguros';
    ELSE
      v_tablaseg := 'seguros';
    END IF;
    v_tconsulta := 'BEGIN SELECT decode(count(*), 0, 1, 0)' || ' INTO :v_act0 FROM garanpro gp, ' || v_tablaseg || ' s' || ' WHERE s.sseguro = :psseguro AND gp.sproduc = s.sproduc' || ' AND gp.cactivi = s.cactivi; END;';
    EXECUTE IMMEDIATE v_tconsulta USING OUT v_act0,
    IN psseguro;
    IF v_act0      = 1 THEN
      v_actividad := '0';
    ELSE
      v_actividad := 'se.cactivi';
    END IF;
    v_tconsulta         := 'SELECT REPLACE(DET.NVAL7, CHR(39), CHR(39) || CHR(39)) a';
    v_tconsulta         := v_tconsulta || ' FROM garanpro p, ';
    IF NVL(pmodo, 'POL') = 'EST' THEN
      v_tconsulta       := v_tconsulta || 'estgaranseg s, estseguros se,  sgt_subtabs_det det';
      v_csituac         := '(0,7,5,2,4)';
    ELSE
      v_tconsulta                                 := v_tconsulta || 'garanseg s, seguros se,   sgt_subtabs_det det';
      IF pac_isqlfor_lcol.f_es_migracion(psseguro) = 0 THEN
        -- INI BUG 45008 GNRZ 19/07/2018  Se incluyen  estados posibles de pÃ³liza
        -- Inicio QT44626 Amantium 12/07/2018
        -- Se incluyen las pÃ³lizas vencidas
        --v_csituac                                 := '(0,7,5,2,4)'; --BUG 0028151 - 01/03/2017 - CASL - se aÃ¿Â±anden las propuestas
        --v_csituac := '(0,7,5,2,4,3)';
        v_csituac := '(0,7,5,2,4,3,17,1,7,8,9,10,16)';
        -- Fin QT44626 Amantium 12/07/2018
        -- FIN BUG 45008 GNRZ 19/07/2018  Se incluyen  estados posibles de pÃ³liza
      ELSE
        v_csituac := '(0,7,5,2,4)';
      END IF;
    END IF;
    v_tconsulta         := v_tconsulta || ' WHERE p.cgarant = s.cgarant';
    v_tconsulta         := v_tconsulta || ' AND det.csubtabla = 700000234';
    v_tconsulta         := v_tconsulta || ' AND DET.CCLA1 = SE.SPRODUC';
    v_tconsulta         := v_tconsulta || ' AND DET.CCLA2 = S.CGARANT';
    v_tconsulta         := v_tconsulta || ' AND p.sproduc = se.sproduc';
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = se.sseguro';
    v_tconsulta         := v_tconsulta || ' AND p.CACTIVI = ' || v_actividad;
    v_tconsulta         := v_tconsulta || ' AND se.csituac in ' || v_csituac;
    v_tconsulta         := v_tconsulta || ' AND s.sseguro = ' || psseguro;
    v_tconsulta         := v_tconsulta || ' AND s.nriesgo = ' || pnriesgo;
    IF NVL(pmodo, 'POL') = 'EST' THEN
      --Bug 33145/192146 - 03/12/2014 - AMC
      v_es_admin    := pac_seguros.f_es_col_admin(psseguro, 'EST');
      IF v_es_admin  = 1 THEN
        v_tconsulta := v_tconsulta || ' AND s.cobliga = 1 and s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg ga WHERE sseguro =' || psseguro;
        v_tconsulta := v_tconsulta || ' AND ga.nmovimi <= (SELECT MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.SSEGURO = GA.SSEGURO AND MV.CMOVSEG!=3 AND MV.NMOVIMI =(select max(nmovimi_cert) from detmovsegurocol WHERE sseguro_0 =  (select sseguro from seguros where npoliza = (select npoliza from seguros where sseguro = ' || psseguro || ')  and ncertif = 0 ) '
        --INI 0023950: Vida grupo-GNO-poliza 135291-se genran los PDF de los certificados y salen sin los amparos
        || ' AND sseguro_cert = ' || psseguro;
        --FIN 0023950: Vida grupo-GNO-poliza 135291-se genran los PDF de los certificados y salen sin los amparos
        IF (pnmovimi  IS NOT NULL) THEN
          v_tconsulta := v_tconsulta || ' AND nmovimi_0 <=' || pnmovimi || '))) ';
        ELSE
          v_tconsulta := v_tconsulta || ')))';
        END IF;
      ELSE
        v_tconsulta   := v_tconsulta || ' AND s.cobliga = 1 and s.nmovimi = (SELECT MAX(nmovimi) FROM estgaranseg WHERE sseguro =' || psseguro;
        IF (pnmovimi  IS NOT NULL) THEN
          v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
        ELSE
          v_tconsulta := v_tconsulta || ')';
        END IF;
      END IF;
      --Fi Bug 33145/192146 - 03/12/2014 - AMC
      -- INI 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo  -- INI BUG 00350431/0017560 -- ECP -- 13/04/2015 - Se agrega condiciÃ¿Â³n para mostrar la garantÃ¿Â­a Cobertura al deducible en Suplemento
      SELECT ' AND ((NVL(pac_parametros.f_pargaranpro_n('
        || sproduc
        || ', '
        || cactivi
        || ', p.cgarant, ''GARANT_IMP''), 0) = 1) )'
        --|| ', p.cgarant, ''GARANT_IMP''), 0) = 1) OR exists (select 1 from garanseg where sseguro = s.sseguro and nmovimi = s.nmovimi and cgarant = 777 and iprianu <> 0))'
        -- FIN BUG 0035431/0017560 -- ECP -- 13/04/2015
        -- FIN 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo
      INTO v_tpargar
      FROM
        (SELECT seg.sproduc,
          seg.cactivi
        FROM estseguros seg
        WHERE seg.sseguro = psseguro
        );
  ELSE
    --
    --INI BUG 0036927 - 18/08/2017 - CASL - Se obtiene el certificado a imprimir
    --
    SELECT ncertif
    INTO v_ncertif
    FROM seguros
    WHERE sseguro = psseguro;
    --
    --FIN BUG 0036927 - 18/08/2017 - CASL
    --
    --Bug 33145/192146 - 03/12/2014 - AMC
    v_es_admin    := pac_seguros.f_es_col_admin(psseguro, 'POL');
    IF v_es_admin  = 1 THEN
      v_tconsulta := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG ga WHERE sseguro =' || psseguro;
      v_tconsulta := v_tconsulta || '  and ga.nmovimi <= (SELECT MV.NMOVIMI FROM MOVSEGURO MV WHERE MV.SSEGURO = GA.SSEGURO AND MV.CMOVSEG!=3 AND MV.NMOVIMI =(select max(nmovimi_cert) from detmovsegurocol WHERE sseguro_0 = (select sseguro from seguros where npoliza = (select npoliza from seguros where sseguro = ' || psseguro || ' )  and ncertif = 0 )'
      --INI 0024170: Vida grupo-GNO-poliza 141199-los pdf salen sin valor asegurado en los certificados
      || ' AND sseguro_cert = ' || psseguro;
      --FIN 0024170: Vida grupo-GNO-poliza 141199-los pdf salen sin valor asegurado en los certificados
      IF (pnmovimi IS NOT NULL) THEN
        --
        --INI BUG 0036927 - 18/08/2017 - CASL - Si la poliza es administrada y el certificado es diferente de 0 se filtra por el nmovimi_cert
        --
        IF v_ncertif <> 0 THEN
          --
          v_tconsulta := v_tconsulta || ' AND nmovimi_cert <=' || pnmovimi || '))) ';
          --
        ELSE
          --
          v_tconsulta := v_tconsulta || ' AND nmovimi_0 <=' || pnmovimi || '))) ';
          --
        END IF;
        --
        --FIN BUG 0036927 - 18/08/2017 - CASL
        --
      ELSE
        v_tconsulta := v_tconsulta || ')))';
      END IF;
    ELSE
      v_tconsulta   := v_tconsulta || ' and s.nmovimi = (SELECT MAX(nmovimi) FROM GARANSEG WHERE sseguro =' || psseguro;
      IF (pnmovimi  IS NOT NULL) THEN
        v_tconsulta := v_tconsulta || ' AND nmovimi <=' || pnmovimi || ') ';
      ELSE
        v_tconsulta := v_tconsulta || ')';
      END IF;
    END IF;
    --Fi Bug 33145/192146 - 03/12/2014 - AMC
    -- INI 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo  -- INI BUG 0035054/0017140 -- ECP -- 11/03/2015 - Se agrega condiciÃ¿Â³n para mostrar la garantÃ¿Â­a Cobertura al deducible en Suplemento
    SELECT ' AND ((NVL(pac_parametros.f_pargaranpro_n('
      || sproduc
      || ', '
      || cactivi
      || ', p.cgarant, ''GARANT_IMP''), 0) = 1) )'
      --|| ', p.cgarant, ''GARANT_IMP''), 0) = 1) OR exists (select 1 from garanseg where sseguro = s.sseguro and nmovimi = s.nmovimi and cgarant = 777 and iprianu <> 0))'
      -- FIN 25/02/2016  RMGA Para las garantias que se desean visualizar en la impresion se debe configurar el parametro GARANT_IMP no adicionar condiciones por eso se elimina codigo  -- FIN BUG 0035054/0017140 -- ECP -- 11/03/2015
    INTO v_tpargar
    FROM
      (SELECT seg.sproduc,
        seg.cactivi
      FROM seguros seg
      WHERE seg.sseguro = psseguro
      );
  END IF;
  v_tconsulta := v_tconsulta || v_tpargar;
  v_tconsulta := v_tconsulta || ' ORDER BY p.norden';
  p_tab_error(f_sysdate, f_user, 'CONSULTA', 1, 'Importe', v_tconsulta);
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_tlinia;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    v_tresult := v_tresult || v_tlinia || '\par ';
  END LOOP;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_garantias_riesgo_trans;
