--FIN CALL 08/08/2019 0054010: Amparos Transporte
--INI WAFS 29/04/2020 0060124: Rubro de informacion incompleto
FUNCTION f_gastexp_concepto(
    psseguro IN NUMBER,
	pnriesgo IN NUMBER)
	 RETURN NUMBER
IS
-- SECCION DECLARE
    vnmovimi     NUMBER;
    pmode        VARCHAR2(3);
    vcrecfra     NUMBER;
    v_dummy      NUMBER;
    picderreg    NUMBER;
    pivaderreg   NUMBER;
    v_error      NUMBER;
    v_total      NUMBER;
    v_tipiva     FLOAT;
BEGIN

    pmode := 'POL';
    v_error := 0;
    vnmovimi := 0;
    v_total := 0;
    v_dummy := 0;
    picderreg := 0;
    pivaderreg := 0;

	-- Se extrae iva parametrizado
BEGIN
    SELECT
        ptipiva /100
    INTO v_tipiva
    FROM
        tipoiva
    WHERE
        ctipiva = 1
        AND finivig = (
            SELECT
                MAX(finivig)
            FROM
                tipoiva
            WHERE
                ctipiva = 1
        );

EXCEPTION
    WHEN OTHERS THEN
        v_tipiva := 0;
END;

-- Ultimo movimiento de la garanseg
BEGIN
    SELECT
        MAX(nmovimi)
    INTO vnmovimi
    FROM
        garanseg
    WHERE
        sseguro = psseguro;

EXCEPTION
    WHEN OTHERS THEN
        vnmovimi := 0;
END;

-- Identificador refraccionamiento
BEGIN
    SELECT
        crecfra
    INTO vcrecfra
    FROM
        seguros
    WHERE
        sseguro = psseguro;
EXCEPTION
    WHEN OTHERS THEN
        vcrecfra := 0;
END;
-- Se inicia cursor para recorrer las garantias que aplican para gastos y recargos
FOR cur_garan IN (
    SELECT
        cgarant
    FROM
        garanseg
    WHERE
        sseguro = psseguro
        AND nmovimi = vnmovimi) LOOP
    -- trae los gastos de expedicion
    v_error := nvl(pac_tarifas.f_calcula_concepto(psseguro, pnriesgo, vnmovimi, pmode, 14, vcrecfra, cur_garan.cgarant, v_dummy, v_dummy
    , picderreg), 1);

    v_total := picderreg + v_total;
   -- trae iva de los gastos de expedicion
    v_error := nvl(pac_tarifas.f_calcula_concepto(psseguro, pnriesgo, vnmovimi, pmode, 86, vcrecfra, cur_garan.cgarant, v_dummy, v_dummy
    , pivaderreg), 1);

    v_total := pivaderreg + v_total;

END LOOP;
--Si no encuentra gastos los consulta con la función anterior
IF v_total = 0 THEN
    v_total := pac_isqlfor_lcol.f_importes_mov(561648, 1, 7) * v_tipiva;
    v_total := pac_isqlfor_lcol.f_importes_mov(561648, 1, 7) + v_total;
END IF;
--
RETURN v_total;
--
END f_gastexp_concepto;
--FIN WAFS 29/04/2020 0060124: Rubro de informacion incompleto
-- INICIO 260.0   04/09/2020
FUNCTION f_planes_incremen(
    psseguro IN NUMBER,
    pnmovimi IN NUMBER,
    pcidioma IN NUMBER DEFAULT 1,
    priesgo  IN NUMBER DEFAULT 1)
  RETURN VARCHAR2
IS
  CURSOR v_cur
  IS
    SELECT TO_CHAR(NVL(g.prevali, 0), 'FM990D00') incrementoplan
    FROM riesgos r,
      garanseg g,
      garangen gg,
      garanpro ga
    WHERE r.sseguro = psseguro
    AND pnmovimi BETWEEN r.nmovima AND NVL(r.nmovimb, pnmovimi)
    AND g.sseguro  = r.sseguro
    AND g.nriesgo  = r.nriesgo
    AND gg.cgarant = g.cgarant
    AND gg.cidioma = pcidioma
    AND gg.cgarant = ga.cgarant
    AND r.nriesgo  = priesgo
    AND EXISTS
      (SELECT 1
      FROM seguros se
      WHERE se.sseguro = g.sseguro
      AND se.sproduc   = ga.sproduc
      )
  GROUP BY NVL(r.tnatrie, TRIM(pac_isqlfor_lcol.f_dades_persona(r.sperson, 4)
    || ' '
    || pac_isqlfor_lcol.f_dades_persona(r.sperson, 5))),
    gg.tgarant,
    fu_formato(p_valor => (NVL(pac_preguntas.f_get_pregungaranseg_v(r.sseguro, g.cgarant, r.nriesgo, 4081, 'POL'), g.icapital))),
    TO_CHAR(NVL(g.prevali, 0), 'FM990D00'),
    ga.norden
  ORDER BY NVL(r.tnatrie, TRIM(pac_isqlfor_lcol.f_dades_persona(r.sperson, 4)
    || ' '
    || pac_isqlfor_lcol.f_dades_persona(r.sperson, 5))),
    ga.norden;
  v_tresult VARCHAR2(4000) := '';
  v_count   NUMBER;
BEGIN
  SELECT COUNT(1)
  INTO v_count
  FROM riesgos
  WHERE sseguro = psseguro
  AND pnmovimi BETWEEN nmovima AND NVL(nmovimb, pnmovimi);
  IF v_count > 1 THEN
    FOR i IN v_cur
    LOOP
      v_tresult := v_tresult || i.incrementoplan || '\par ';
    END LOOP;
  ELSE
    FOR i IN v_cur
    LOOP
      v_tresult := i.incrementoplan;
    END LOOP;
  END IF;
  RETURN (f_jrep_trad(v_tresult));
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_planes_incremen;
FUNCTION f_pago_total_cert(
    pmt_sseguro IN NUMBER,
    pmt_idioma  IN NUMBER DEFAULT 1,
    pmt_nmovimi IN NUMBER,
    pmt_nrecibo IN NUMBER,
    pmt_nriesgo IN NUMBER,
    pcampo      IN NUMBER DEFAULT 2)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult  VARCHAR2(32000) := '';
    v_primatot NUMBER          := 0;
    v_gastexpd NUMBER          := 0;
    v_crespue  NUMBER;
    v_forpago  NUMBER;
    v_fraccio  NUMBER := 100;
    v_temp_tot NUMBER;
    v_refrac   NUMBER;
  BEGIN
    SELECT cforpag INTO v_forpago FROM seguros WHERE sseguro = pmt_sseguro;
  SELECT crecfra INTO v_refrac FROM seguros WHERE sseguro = pmt_sseguro;
  IF v_refrac       = 1 THEN
    IF v_forpago    = 2 THEN
      v_fraccio    := 0.02;
    ELSIF v_forpago = 4 THEN
      v_fraccio    := 0.08;
    ELSIF v_forpago = 12 THEN
      v_fraccio    := 0.10;
    ELSIF v_forpago = 1 THEN
      v_fraccio    := 0;
    END IF;
  ELSE
    v_fraccio := 0;
  END IF;
  IF pcampo = 1 THEN
    SELECT
      (SELECT SUM(gsg.ipritot)
      FROM garanseg gsg
      WHERE gsg.nriesgo = pmt_nriesgo
      AND gsg.sseguro   = s.sseguro
      AND gsg.nmovimi   = pmt_nmovimi
      )/s.cforpag
    INTO v_primatot
    FROM seguros s
    WHERE s.sseguro = pmt_sseguro;
    v_temp_tot     := v_primatot * v_fraccio;
    IF pmt_nriesgo  = 1 THEN
      SELECT v.iderreg
      INTO v_gastexpd
      FROM vdetrecibos_monpol v,
        recibos r
      WHERE v.nrecibo = r.nrecibo
      AND r.sseguro   = pmt_sseguro
      AND r.nrecibo   = pmt_nrecibo
      AND r.nmovimi   = pmt_nmovimi;
    END IF;
    v_tresult := v_primatot + v_gastexpd + v_temp_tot;
  ELSIF pcampo = 2 THEN
    SELECT
      (SELECT SUM(gsg.ipritot)
      FROM garanseg gsg
      WHERE gsg.sseguro = s.sseguro
      AND gsg.nmovimi   = pmt_nmovimi
      )/s.cforpag
    INTO v_primatot
    FROM seguros s
    WHERE s.sseguro = pmt_sseguro;
    v_temp_tot     := v_primatot * v_fraccio;
    SELECT v.iderreg
    INTO v_gastexpd
    FROM vdetrecibos_monpol v,
      recibos r
    WHERE v.nrecibo = r.nrecibo
    AND r.sseguro   = pmt_sseguro
    AND r.nrecibo   = pmt_nrecibo
    AND r.nmovimi   = pmt_nmovimi;
    v_tresult      := v_primatot + v_gastexpd + v_temp_tot;
  ELSIF pcampo      = 3 THEN
    SELECT
      (SELECT SUM(gsg.ipritot)
      FROM garanseg gsg
      WHERE gsg.nriesgo = pmt_nriesgo
      AND gsg.sseguro   = s.sseguro
      AND gsg.nmovimi   = pmt_nmovimi
      ) / s.cforpag
    INTO v_primatot
    FROM seguros s
    WHERE s.sseguro = pmt_sseguro;
    v_temp_tot     := v_primatot * v_fraccio;
    v_tresult      := v_primatot + v_temp_tot;
  ELSIF pcampo      = 4 THEN
    SELECT
      (SELECT SUM(gsg.ipritot)
      FROM garanseg gsg
      WHERE gsg.sseguro = s.sseguro
      AND gsg.nmovimi   = pmt_nmovimi
      ) / s.cforpag
    INTO v_primatot
    FROM seguros s
    WHERE s.sseguro = pmt_sseguro;
    v_temp_tot     := v_primatot * v_fraccio;
    v_tresult      := v_primatot + v_temp_tot;
  END IF;
  v_tresult := v_tresult + 0;
  RETURN (v_tresult);
EXCEPTION
WHEN OTHERS THEN
  RETURN('');
END f_pago_total_cert;
-- FIN 260.0   04/09/2020
--INI JFLJ QT66977 12/04/2021

    FUNCTION f_despachos_trans_marine (
        psseguro   IN NUMBER,
        pcidioma   IN NUMBER DEFAULT 8,
        pnmovimi   IN NUMBER DEFAULT NULL,
        pcampo     IN NUMBER,
        pfuncion   IN VARCHAR2 DEFAULT 'DESPACHO',
    ptablas  IN VARCHAR2 DEFAULT 'POL')
  RETURN VARCHAR2
IS
        v_tresult       VARCHAR2(32000) := '';
        v_riesgo_comp   pregunsegtab.nriesgo%TYPE;
        v_cont          PLS_INTEGER := 1;
        v_temp          VARCHAR2(32000) := '';
        v_sproduc       NUMBER;
        v_crespue4084   NUMBER;
        v_nmovimi   NUMBER;--BUG 0075250 GZG  10/06/2022
    BEGIN
        BEGIN
    SELECT sproduc INTO v_sproduc FROM seguros WHERE sseguro = psseguro;
  EXCEPTION
  WHEN OTHERS THEN
    SELECT sproduc INTO v_sproduc FROM ESTseguros WHERE sseguro = psseguro;
  END;
  IF (ptablas IN ('POL','CAR')) THEN
    IF ptablas = 'CAR' THEN
      --
      BEGIN
        SELECT crespue
        INTO v_crespue4084
        FROM pregunpolseg
        WHERE cpregun = 4084
        AND sseguro   = psseguro
        AND nmovimi   =
          (SELECT MAX(nmovimi)
          FROM pregunpolseg
          WHERE sseguro = psseguro
          AND cpregun   = 4084
          );
      EXCEPTION
      WHEN NO_DATA_FOUND THEN
        v_crespue4084 := 2; -- por defecto
      END;
      --
    END IF;
    IF (pcampo = 1) THEN --Tipo despacho
      FOR i IN
      (select a.nriesgo, decode(ccolumna,1,decode(nvalor,1,'Importación',2,'Exportación',3,'Nacional',4,'Urbano',5,'Único')) partida
        ,(select b.tvalor from pregunsegtab b where b.sseguro = a.sseguro and b.cpregun = a.cpregun and b.ccolumna = 2 and b.NLINEA = a.nlinea) panual_movi
        from pregunsegtab a
        where a.sseguro = psseguro
        and a.cpregun = 8505
        and a.ccolumna = 1
        and a.nmovimi = NVL(pnmovimi,a.nmovimi)
      ORDER BY nvalor asc --a.nriesgo,
      )
      LOOP
        IF (pfuncion    = 'DESPACHO') THEN
          v_tresult    := v_tresult || i.partida || ' \par ';
        ELSIF (pfuncion = 'POLIZA') THEN
          v_tresult    := v_tresult || i.partida || ', ';
        END IF;
      END LOOP;
      IF v_tresult IS NULL AND pfuncion = 'DESPACHO' THEN
        v_tresult := ' \par ';
      END IF;
    ELSIF (pcampo = 2) THEN --Presupuesto anual de movilizacion
      FOR i IN
      (select a.nriesgo, decode(ccolumna,1,decode(nvalor,1,'Importación',2,'Exportación',3,'Nacional',4,'Urbano',5,'Único')) partida
        ,(select b.tvalor from pregunsegtab b where b.sseguro = a.sseguro and b.cpregun = a.cpregun and b.ccolumna = 2 and b.NLINEA = a.nlinea) panual_movi
        from pregunsegtab a
        where a.sseguro = psseguro
        and a.cpregun = 8505
        and a.ccolumna = 1
        and a.nmovimi = NVL(pnmovimi,a.nmovimi)
      ORDER BY nvalor asc --a.nriesgo,
      )
      LOOP
        v_tresult := v_tresult || pac_isqlfor_lcol.f_imp(psseguro, i.panual_movi, 1) || ' \par ';
      END LOOP;
      IF v_tresult IS NULL THEN
        v_tresult := ' \par ';
      END IF;
    ELSIF (pcampo = 3) THEN --Tipo de mercancia
      FOR i IN
      (SELECT DISTINCT d.ccla3 crespue,
        d.nval7 trespue,
        p.nriesgo
      FROM sgt_subtabs_det d,
        pregunseg p
      WHERE d.ccla2   = p.cpregun
      AND d.ccla3     = p.crespue
      AND p.sseguro   = psseguro
      AND d.csubtabla = 70608184
      AND p.cpregun   = 9319
      AND d.ccla1     = v_sproduc
      AND p.nmovimi = NVL(pnmovimi, p.nmovimi)
      ORDER BY nriesgo
      )
      LOOP
        v_tresult := v_tresult || i.trespue || ' \par ';
      END LOOP;
      IF v_tresult IS NULL THEN
        v_tresult := ' \par ';
      END IF;
    ELSIF (pcampo = 4) THEN
      FOR i IN
      (SELECT DISTINCT d.ccla3 crespue,
        d.nval7 trespue,
        p.nriesgo
      FROM sgt_subtabs_det d,
        pregunseg p
      WHERE d.ccla2   = p.cpregun
      AND d.ccla3     = p.crespue
      AND p.sseguro   = psseguro
      AND d.csubtabla = 70608214
      AND p.cpregun   = 9340
      AND p.nmovimi = NVL(pnmovimi, p.nmovimi)
      ORDER BY nriesgo
      )
      LOOP
        v_tresult := v_tresult || i.trespue || ' \par ';
      END LOOP;
      IF v_tresult IS NULL THEN
        v_tresult := ' \par ';
      END IF;
    ELSIF (pcampo = 5) THEN --Tipo de trayecto
      FOR i IN
      (SELECT DISTINCT a.nriesgo, DECODE(nvalor,1,'Marítimo',2,'Aéreo',3,'Terrestre',4,'Férreo',5,'Fluvial',6,'Cabotaje') trespue
         FROM pregunsegtab a
        WHERE a.cpregun   = 8263
          AND a.sseguro   = psseguro
        ORDER BY a.nriesgo
      )
      LOOP
        v_tresult := v_tresult || i.trespue || ' \par ';
      END LOOP;
      IF v_tresult IS NULL THEN
        v_tresult := ' \par ';
      END IF;
    ELSIF (pcampo = 6) THEN --Pais origen
      FOR i IN
      (SELECT DISTINCT p.nriesgo,
        r.trespue
      FROM respuestas_dep r,
        pregunseg p
      WHERE p.cpregun = r.cpregun
      AND p.crespue   = r.crespue
      AND p.cpregun   = 9363
      AND p.sseguro   = psseguro
      AND r.cidioma   = pcidioma
      AND p.nmovimi = NVL(pnmovimi, p.nmovimi)
      ORDER BY p.nriesgo
      )
      LOOP
        v_tresult := v_tresult || i.trespue || ' \par ';
      END LOOP;
    ELSIF (pcampo = 7) THEN --Ciudad origen
      FOR i IN
      (SELECT DISTINCT p.nriesgo,
        r.trespue,
        r.crespuedep
      FROM respuestas_dep r,
        pregunseg p,
        pregunseg p2
      WHERE p.cpregun = r.cpregun
      AND p.crespue   = r.crespue
      AND p2.crespue  = r.crespuedep
      AND p2.sseguro  = p.sseguro
      AND p2.nriesgo  = p.nriesgo
      AND p2.nmovimi  = p.nmovimi
      AND p2.cpregun  = 9363
      AND p.cpregun   = 9364
      AND p.sseguro   = psseguro
      AND r.cidioma   = pcidioma
      AND p.nmovimi = NVL(pnmovimi, p.nmovimi)
      ORDER BY p.nriesgo
      )
      LOOP
        v_tresult := v_tresult || i.trespue || ' \par ';
      END LOOP;
    ELSIF (pcampo = 8) THEN --Pais destino
      FOR i IN
      (SELECT DISTINCT p.nriesgo,
        r.trespue
      FROM respuestas_dep r,
        pregunseg p
      WHERE p.cpregun = r.cpregun
      AND p.crespue   = r.crespue
      AND p.cpregun   = 9925
      AND p.sseguro   = psseguro
      AND r.cidioma   = pcidioma
      AND p.nmovimi = NVL(pnmovimi, p.nmovimi)
      ORDER BY p.nriesgo
      )
      LOOP
        v_tresult := v_tresult || i.trespue || ' \par ';
      END LOOP;
    ELSIF (pcampo = 9) THEN --Ciudad destino
      FOR i IN
      (SELECT DISTINCT p.nriesgo,
        r.trespue,
        r.crespuedep
      FROM respuestas_dep r,
        pregunseg p,
        pregunseg p2
      WHERE p.cpregun = r.cpregun
      AND p.crespue   = r.crespue
      AND p2.crespue  = r.crespuedep
      AND p2.sseguro  = p.sseguro
      AND p2.nriesgo  = p.nriesgo
      AND p2.nmovimi  = p.nmovimi
      AND p2.cpregun  = 9925
      AND p.cpregun   = 9926
      AND p.sseguro   = psseguro
      AND r.cidioma   = pcidioma
      AND p.nmovimi = NVL(pnmovimi, p.nmovimi)
      ORDER BY p.nriesgo
      )
      LOOP
        v_tresult := v_tresult || i.trespue || ' \par ';
      END LOOP;
    ELSIF (pcampo = 10) THEN --Tasa

      BEGIN
        SELECT ps.crespue
        INTO v_temp
        FROM pregunpolseg ps
        WHERE ps.cpregun = 4084
        AND ps.sseguro   = psseguro
        AND ps.nmovimi = NVL(pnmovimi,
          (SELECT MAX(nmovimi)
          FROM pregunpolseg
          WHERE cpregun = 4084
          AND sseguro   = psseguro
          ))
          ;
      EXCEPTION
      WHEN NO_DATA_FOUND THEN
        v_temp := 2;
      END;
      v_temp := 1;--JFLJ
      IF (v_temp = 1) THEN --Si es vencida (crespue: 1)
        FOR i IN
        (
        SELECT ri.nriesgo,
          pr.crespue,
          pr.nmovimi
        FROM riesgos ri
        LEFT JOIN pregunseg pr
        ON ri.sseguro    = pr.sseguro
        AND ri.nriesgo   = pr.nriesgo
        AND pr.cpregun   = 4090
        WHERE ri.sseguro = psseguro
        AND ri.fanulac  IS NULL
        AND (pr.nmovimi  =
          (SELECT MAX(nmovimi)
          FROM pregunseg
          WHERE cpregun = 4090
          AND sseguro   = psseguro
          AND nmovimi  <= NVL(pnmovimi,0)
          )
        OR ( pr.nmovimi IS NULL
        AND RI.NMOVIMA  >= NVL(pnmovimi,0)))
        )
        LOOP
          v_tresult := v_tresult || i.crespue || ' \par ';
        END LOOP;
      ELSIF (v_temp = 2) THEN --Si es anticipada (crespue: 2)
        FOR i IN
        (SELECT DISTINCT ri.nriesgo,
          dp.nmovimi,
          RTRIM(TO_CHAR(ROUND(dp.iconcep, 6), '90.999999'), 0) iconcep
        FROM riesgos ri,
          detprimas dp
        WHERE ri.sseguro   = dp.sseguro(+)
        AND ri.nriesgo     = dp.nriesgo(+)
        AND dp.cconcep(+)  = 'TASATEC'
        AND dp.cgarant(+) IN (8040, 8041, 8042, 8043, 8049, 8050)
        AND ri.sseguro     = psseguro
        AND NVL(dp.nmovimi, 0) = NVL(pnmovimi, NVL(
          (SELECT MAX(nmovimi)
          FROM detprimas
          WHERE sseguro = psseguro
          AND cgarant  IN (8040, 8041, 8042, 8043, 8049, 8050)
          AND cconcep   = 'TASATEC'
          ), 0))
        ORDER BY ri.nriesgo
        )
        LOOP
          v_tresult := v_tresult ||  i.iconcep || ' \par ';
        END LOOP;
        IF v_tresult IS NULL THEN
            v_tresult := ' \par ';
        END IF;
      END IF;
    ELSIF (pcampo = 11) THEN --Medios
      IF NVL(pac_parametros.f_parproducto_n(v_sproduc, 'DEDUC_TRANS'), 0) = 1 THEN
        FOR i IN
        ( SELECT DISTINCT g.nriesgo,
          p.norden,
          DECODE(pe.crespue, NULL, gr.tgarant, gr.tgarant
          || ' ('
          || pe.crespue
          || '%)')tgarant,
          gr.cgarant,
          g.icapital
        FROM garanseg g,
          pregungaranseg pe,
          garanpro p,
          garangen gr
        WHERE g.cgarant    = p.cgarant
        AND p.sproduc      = v_sproduc
        AND g.cgarant      = gr.cgarant
        AND gr.cidioma     = pcidioma
        AND g.sseguro      = psseguro
        AND g.sseguro      = pe.sseguro(+)
        AND g.nriesgo      = pe.nriesgo(+)
        AND g.nmovimi      = pe.nmovimi(+)
        AND g.cgarant      = pe.cgarant(+)
        AND pe.cpregun(+) IN (9341, 9342)
        AND g.nmovimi      = NVL(pnmovimi,
          (SELECT MAX(nmovimi) FROM garanseg WHERE sseguro = psseguro
          ))
        ORDER BY g.nriesgo,
          p.norden,
          gr.cgarant DESC
        )
        LOOP
          IF (NVL(v_riesgo_comp, i.nriesgo) = i.nriesgo) THEN
            v_riesgo_comp                  := i.nriesgo;
            v_tresult                      := v_tresult || i.tgarant || ' \par ';
          ELSE
            v_cont       := 1;
            WHILE (v_cont = 1)
            LOOP
              v_tresult := v_tresult || ' \par ';
              v_cont    := 0;
            END LOOP;
            v_riesgo_comp := i.nriesgo;
            v_tresult     := v_tresult || i.tgarant || ' \par ';
          END IF;
        END LOOP;
      ELSE
        FOR i IN
        (
        SELECT DISTINCT g.nriesgo,
          gr.tgarant,
          gr.cgarant,
          g.icapital,
          p.norden
        FROM garanseg g,
          garanpro p,
          garangen gr
        WHERE g.cgarant = p.cgarant
        AND p.sproduc   = v_sproduc
        AND g.cgarant   = gr.cgarant
        AND gr.cidioma  = pcidioma
        AND g.sseguro   = psseguro
        AND g.nmovimi = NVL(pnmovimi,
          (SELECT MAX(nmovimi) FROM garanseg WHERE sseguro = psseguro
          ))
        ORDER BY g.nriesgo,
          p.norden,
          gr.cgarant DESC
        )
        LOOP
          --Una linea de medios por cada despacho (riesgo)
          IF (NVL(v_riesgo_comp, i.nriesgo) = i.nriesgo) THEN
            v_riesgo_comp                  := i.nriesgo;
            v_tresult                      := v_tresult || i.tgarant || ';';
          ELSE
            v_cont       := 1;
            WHILE (v_cont = 1)
            LOOP
              v_tresult := v_tresult || ' \par ';
              v_cont    := 0;
            END LOOP;
            v_riesgo_comp := i.nriesgo;
            v_tresult     := v_tresult || i.tgarant || ';';
          END IF;
        END LOOP;
      END IF;
    ELSIF (pcampo = 12) THEN --Limite maximo por medio
      FOR i IN
      (SELECT DISTINCT g.nriesgo,
        gr.tgarant,
        gr.cgarant,
        g.icapital,
        p.norden
      FROM garanseg g,
        garanpro p,
        garangen gr
      WHERE g.cgarant = p.cgarant
      AND p.sproduc   = v_sproduc
      AND g.cgarant   = gr.cgarant
      AND gr.cidioma  = pcidioma
      AND g.sseguro   = psseguro
      AND g.nmovimi = NVL(pnmovimi,
        (SELECT MAX(nmovimi) FROM garanseg WHERE sseguro = psseguro
        ))
      ORDER BY g.nriesgo,
        p.norden,
        gr.cgarant DESC
      )
      LOOP
        --Validacion para dividir linea unicamente cuando el riesgo sea diferente
        IF (NVL(v_riesgo_comp, i.nriesgo) = i.nriesgo) THEN
          v_riesgo_comp                  := i.nriesgo;
          IF i.icapital                   = 0 AND i.cgarant IN (8048,8052) THEN
            v_tresult                    := v_tresult || ' \par ';
          ELSIF i.cgarant IN (8040,8041,8042,8043,8044,8045,8046,8047,8049)
            AND ptablas   IN ('CAR') AND v_crespue4084 = 1 THEN
            --
            v_tresult := v_tresult ||'Con base en el reporte periodico;';
            --
          ELSE
            v_tresult := v_tresult || pac_isqlfor_lcol.f_imp(psseguro, i.icapital, 1) || ' \par ';
          END IF;
        ELSE
          --Genera salto de linea solo una vez por registro
          v_cont       := 1;
          WHILE (v_cont = 1)
          LOOP
            v_tresult := v_tresult || ' \par ';
            v_cont    := 0;
          END LOOP;
          v_riesgo_comp := i.nriesgo;
          IF i.cgarant IN (8040,8041,8042,8043,8044,8045,8046,8047,8049) AND ptablas IN ('CAR') AND v_crespue4084 = 1 THEN
            --
            v_tresult := v_tresult ||'Con base en el reporte periodico;';
            --
          ELSE
            v_tresult := v_tresult || pac_isqlfor_lcol.f_imp(psseguro, i.icapital, 1) || ' \par ';
          END IF;
        END IF;
      END LOOP;
      --FIN BUG GZG 0048545
    ELSIF (pcampo = 13) THEN --Tipos de vehiculos por despacho (riesgo)
      FOR i IN
      (SELECT DISTINCT ri.nriesgo,
        pt.cpregun,
        SUBSTR( pr.tpregun, INSTR(pr.tpregun, ':', 1) + 2, LENGTH(pr.tpregun)) tpregun
      FROM riesgos ri,
        pregunseg pt,
        preguntas pr
      WHERE ri.sseguro = pt.sseguro(+)
      AND ri.nriesgo   = pt.nriesgo(+)
      AND pt.cpregun     = pr.cpregun(+)
      AND ri.sseguro     = psseguro
      AND pt.cpregun(+) IN (9322, 9323, 9324, 9325)
      AND pt.crespue(+)  = 1
      AND pr.cidioma(+)  = pcidioma
      AND pt.nmovimi(+) = pnmovimi
      ORDER BY ri.nriesgo,
        pt.cpregun
      )
      LOOP
        --Validacion para dividir linea unicamente cuando el riesgo sea diferente
        IF (NVL(v_riesgo_comp, i.nriesgo) = i.nriesgo) THEN
          v_riesgo_comp                  := i.nriesgo;
          v_tresult                      := v_tresult || i.tpregun || ' \par ';
        ELSE
          --Genera salto de linea solo una vez por registro
          v_cont       := 1;
          WHILE (v_cont = 1)
          LOOP
            v_tresult := v_tresult || ' \par ';
            v_cont    := 0;
          END LOOP;
          v_riesgo_comp := i.nriesgo;
          v_tresult     := v_tresult || i.tpregun || ' \par ';
        END IF;
      END LOOP;
    ELSIF (pcampo = 14) THEN --Limite maximo por registro
      FOR i IN
      (SELECT DISTINCT ri.nriesgo,
        pt.cpregun,
        pt.crespue
      FROM riesgos ri,
        pregunseg pt,
        preguntas pr
      WHERE ri.sseguro = pt.sseguro(+)
      AND ri.nriesgo   = pt.nriesgo(+)
      AND pt.cpregun     = pr.cpregun(+)
      AND ri.sseguro     = psseguro
      AND pt.cpregun(+) IN (916, 917, 918, 919)
      AND pr.cidioma(+)  = pcidioma
      AND pt.nmovimi(+)  = pnmovimi
      ORDER BY ri.nriesgo,
        pt.cpregun
      )
      LOOP
        --Validacion para dividir linea unicamente cuando el riesgo sea diferente
        IF (NVL(v_riesgo_comp, i.nriesgo) = i.nriesgo) THEN
          v_riesgo_comp                  := i.nriesgo;
          IF (i.crespue                  IS NULL) THEN
            v_tresult                    := v_tresult || i.crespue || ' \par ';
          ELSE
            v_tresult := v_tresult || pac_isqlfor_lcol.f_imp(psseguro, i.crespue, 1) || ' \par ';
          END IF;
        ELSE
          --Genera salto de linea solo una vez por registro
          v_cont       := 1;
          WHILE (v_cont = 1)
          LOOP
            v_tresult := v_tresult || ' \par ';
            v_cont    := 0;
          END LOOP;
          v_riesgo_comp := i.nriesgo;
          IF (i.crespue IS NULL) THEN
            v_tresult   := v_tresult || i.crespue || ' \par ';
          ELSE
            v_tresult := v_tresult || pac_isqlfor_lcol.f_imp(psseguro, i.crespue, 1) || ' \par ';
          END IF;
        END IF;
      END LOOP;
    ELSIF (pcampo = 15) THEN --Coberturas (amparos por riesgo)
      FOR i IN
      (SELECT DISTINCT g.nriesgo,
        g.cgarant,
        p.norden,
        DECODE(pe.crespue, NULL, gr.tgarant, gr.tgarant
        || ' ('
        || pe.crespue
        || '%)') tgarant
      FROM garanseg g,
        pregungaranseg pe,
        garangen gr,
        garanpro p
      WHERE g.cgarant    = p.cgarant
      AND g.cgarant      = gr.cgarant
      AND g.sseguro      = pe.sseguro(+)
      AND g.nriesgo      = pe.nriesgo(+)
      AND g.nmovimi      = pe.nmovimi(+)
      AND g.cgarant      = pe.cgarant(+)
      AND pe.cpregun(+) IN (9341, 9342)
      AND gr.cidioma     = pcidioma
      AND g.sseguro      = psseguro
      AND p.cgarpadre   IS NULL
      AND p.sproduc      = v_sproduc
      AND g.nmovimi = NVL(pnmovimi, g.nmovimi)
      ORDER BY g.nriesgo,
        p.norden
      )
      LOOP
        --Validacion para dividir linea unicamente cuando el riesgo sea diferente
        IF (NVL(v_riesgo_comp, i.nriesgo) = i.nriesgo) THEN
          v_riesgo_comp                  := i.nriesgo;
          v_tresult                      := v_tresult || i.tgarant || ';';
        ELSE
          --Genera salto de linea solo una vez por registro
          v_cont       := 1;
          WHILE (v_cont = 1)
          LOOP
            v_tresult := v_tresult || ' \par ';
            v_cont    := 0;
          END LOOP;
          v_riesgo_comp := i.nriesgo;
          v_tresult     := v_tresult || i.tgarant || ';';
        END IF;
      END LOOP;
    ELSIF (pcampo = 16) THEN --Deducibles por medio

      IF NVL(pac_parametros.f_parproducto_n(v_sproduc, 'DEDUC_TRANS'), 0) = 1 THEN
        FOR i IN
        (SELECT DISTINCT g.nriesgo,
          gr.tgarant,
          gr.cgarant,
          g.icapital,
          p.norden,
          pac_isqlfor_lcol.f_deducible_xgarantia(psseguro, 1, g.nriesgo, 'POL', g.cgarant) tnivel
        FROM garanseg g,
          garanpro p,
          garangen gr
        WHERE g.cgarant = p.cgarant
        AND p.sproduc   = v_sproduc
        AND g.cgarant   = gr.cgarant
        AND gr.cidioma  = pcidioma
        AND g.sseguro   = psseguro
        AND g.nmovimi   = NVL(pnmovimi,
          (SELECT MAX(nmovimi) FROM garanseg WHERE sseguro = psseguro
          ))
        ORDER BY g.nriesgo,
          p.norden,
          gr.cgarant DESC
        )
        LOOP
          --Validacion para dividir linea unicamente cuando el riesgo sea diferente
          IF (NVL(v_riesgo_comp, i.nriesgo) = i.nriesgo) THEN
            v_riesgo_comp                  := i.nriesgo;
            v_tresult                      := v_tresult || i.tnivel || ' \par ';
          ELSE
            --Genera salto de linea solo una vez por registro
            v_cont       := 1;
            WHILE (v_cont = 1)
            LOOP
              v_tresult := v_tresult || ' \par ';
              v_cont    := 0;
            END LOOP;
            v_riesgo_comp := i.nriesgo;
            v_tresult     := v_tresult || i.tnivel || ' \par ';
          END IF;
        END LOOP;
      ELSE
        FOR i IN
        (SELECT r.nriesgo,
          n.tnivel,
          b.nmovimi
        FROM bf_bonfranseg b,
          bf_progarangrup p,
          garanseg g,
          garanpro gp,
          bf_desnivel n,
          riesgos r
        WHERE r.sseguro   = psseguro
        AND n.cidioma(+)  = pcidioma
        AND b.cgrup       = n.cgrup(+)
        AND b.cgrup       = p.codgrup(+)
        AND b.csubgrup    = n.csubgrup(+)
        AND b.cversion    = n.cversion(+)
        AND b.cnivel      = n.cnivel(+)
        AND b.sseguro(+)  = r.sseguro
        AND g.sseguro(+)  = r.sseguro
        AND b.nriesgo(+)  = r.nriesgo
        AND g.nriesgo(+)  = r.nriesgo
        AND g.nmovimi(+)  = r.nmovima
        AND g.cgarant     = p.cgarant
        AND g.cgarant     = gp.cgarant
        AND gp.cgarpadre IS NOT NULL
        AND NVL(b.nmovimi, 0) = NVL(pnmovimi, NVL(
          (SELECT MAX(nmovimi) FROM bf_bonfranseg WHERE sseguro = psseguro
          ), 0))
        ORDER BY r.nriesgo
        )
        LOOP
          --Validacion para dividir linea unicamente cuando el riesgo sea diferente
          IF (NVL(v_riesgo_comp, i.nriesgo) = i.nriesgo) THEN
            v_riesgo_comp                  := i.nriesgo;
            v_tresult                      := v_tresult || i.tnivel || ' \par ';
          ELSE
            --Genera salto de linea solo una vez por registro
            v_cont       := 1;
            WHILE (v_cont = 1)
            LOOP
              v_tresult := v_tresult || ' \par ';
              v_cont    := 0;
            END LOOP;
            v_riesgo_comp := i.nriesgo;
            v_tresult     := v_tresult || i.tnivel || ' \par ';
          END IF;
        END LOOP;
      END IF;
    ELSIF (pcampo = 18) THEN --Coberturas (amparos por riesgo)
      FOR i IN
      (SELECT DISTINCT g.nriesgo,
        g.cgarant,
        p.norden,
        DECODE(pe.crespue, NULL, det.nval7, det.nval7
        || ' ('
        || pe.crespue
        || '%)')tgarant,
        g.icapital
      FROM garanseg g,
        pregungaranseg pe,
        garangen gr,
        garanpro p,
        sgt_subtabs_det det
      WHERE g.cgarant    = p.cgarant
      AND det.csubtabla  = 700000234
      AND DET.CCLA1      = v_sproduc
      AND g.cgarant      = gr.cgarant
      AND DET.CCLA2      = g.CGARANT
      AND g.sseguro      = pe.sseguro(+)
      AND g.nriesgo      = pe.nriesgo(+)
      AND g.nmovimi      = pe.nmovimi(+)
      AND g.cgarant      = pe.cgarant(+)
      AND pe.cpregun(+) IN (9341, 9342) --Porcentaje de lucro cesante y gastos adicionales
      AND gr.cidioma     = pcidioma
      AND g.sseguro      = psseguro
      AND p.cgarpadre   IS NULL
      AND p.sproduc      = v_sproduc
      AND g.nmovimi = NVL(pnmovimi, g.nmovimi)
      ORDER BY g.nriesgo,
        p.norden
      )
      LOOP
        --Validacion para dividir linea unicamente cuando el riesgo sea diferente
        IF (NVL(v_riesgo_comp, i.nriesgo) = i.nriesgo) THEN
          v_riesgo_comp                  := i.nriesgo;
          v_tresult                      := v_tresult || i.tgarant || ';';
        ELSE
          --Genera salto de linea solo una vez por registro
          v_cont       := 1;
          WHILE (v_cont = 1)
          LOOP
            v_tresult := v_tresult || ' \par ';
            v_cont    := 0;
          END LOOP;
          v_riesgo_comp := i.nriesgo;
          v_tresult     := v_tresult || i.tgarant || ';';
        END IF;
      END LOOP;
    ELSIF (pcampo = 19) THEN --condicionado
    --INI BUG 0075250 GZG 13/06/2022
        IF pnmovimi IS NULL THEN
        SELECT MAX(nmovimi)
          INTO v_nmovimi
          FROM pregunpolseg
         WHERE sseguro = psseguro;
        ELSE
          v_nmovimi := pnmovimi;
        END IF;
    --FIN BUG 0075250 GZG 13/06/2022
        SELECT cclausu
          INTO v_tresult
          FROM pregunpolseg a, condicionadoprod b
         WHERE b.sproduc = v_sproduc
           AND a.cpregun = 1301
           AND a.sseguro = psseguro
           AND a.crespue = b.ccondicio AND a.nmovimi = v_nmovimi;--BUG 0075250 GZG 13/06/2022
           --
           v_tresult := v_tresult || ' \par ';
           --
    END IF;
  END IF;
  RETURN f_jrep_trad(v_tresult);
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_despachos_trans_marine;
--FIN JFLJ QT66977 12/04/2021
  --INI AITSSD-3723 GZG 01/12/2022 se crea funcion que retorna las respuestas de las preguntas
  FUNCTION f_respuesta_preg(
    psseguro IN NUMBER,
    ppregun IN NUMBER DEFAULT NULL,
    ptippreg IN NUMBER,
    ptipres IN NUMBER DEFAULT 0,
    pcidioma IN NUMBER DEFAULT 8,
    pmodo    IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT 1,
    ptabla    IN VARCHAR2 DEFAULT 'PREGUNSEG',
    pnriesgo IN NUMBER DEFAULT NULL)
  RETURN VARCHAR2
IS
TYPE r_cursor
IS
  REF
  CURSOR;
    vr_cursor r_cursor;
    v_tresult   VARCHAR2(32000) := '';
    v_tconsulta VARCHAR2(2000);
    v_tlinia    VARCHAR2(200);
  BEGIN
  --
  IF ptippreg = 1 THEN--DISEÑADO PARA PREGUNSEG, PREGUNPOLSEG Y SITRIESGO
    v_tconsulta := v_tconsulta || ' SELECT ';
        IF ptipres = 0 THEN
            v_tconsulta := v_tconsulta || ' s.trespue ';
        ELSIF ptipres = 1  THEN
            v_tconsulta := v_tconsulta || ' s.crespue ';
        ELSIF ptipres = 2  THEN
            v_tconsulta := v_tconsulta || ' MAX(s.nmovimi) ';
        END IF;
    v_tconsulta := v_tconsulta || ' FROM ';
    v_tconsulta := v_tconsulta || ptabla||' s ';
    v_tconsulta := v_tconsulta || ' WHERE ';
    v_tconsulta := v_tconsulta || ' s.sseguro = '||psseguro;
        IF ppregun IS NOT NULL THEN
            v_tconsulta := v_tconsulta || ' AND s.cpregun = '||ppregun;
        END IF;
        IF pnriesgo IS NOT NULL THEN
            v_tconsulta := v_tconsulta || ' AND s.nriesgo = '||pnriesgo;
        END IF;
        IF ptipres <> 2 THEN
                v_tconsulta := v_tconsulta || ' AND s.nmovimi = ( ';
                v_tconsulta := v_tconsulta || ' SELECT ';
                v_tconsulta := v_tconsulta || ' MAX(s2.nmovimi) ';
                v_tconsulta := v_tconsulta || ' FROM ';
                v_tconsulta := v_tconsulta || ptabla||' s2 ';
                v_tconsulta := v_tconsulta || ' WHERE ';
                v_tconsulta := v_tconsulta || ' s2.sseguro = '||psseguro;
                    IF ppregun IS NOT NULL THEN
                        v_tconsulta := v_tconsulta || ' AND s2.cpregun = '||ppregun;
                    END IF;
                    IF pnriesgo IS NOT NULL THEN
                        v_tconsulta := v_tconsulta || ' AND s2.nriesgo = '||pnriesgo;
                    END IF;
                v_tconsulta := v_tconsulta || ' AND s2.nmovimi <= '||pnmovimi||')';
        ELSE
                v_tconsulta := v_tconsulta || ' AND s.nmovimi <= '||pnmovimi;
        END IF;
  --ELSIF ptippreg = 2 THEN--tipo deducible
  --CODIGO
  --ELSE
  END IF;
--P_CONTROL_ERROR('GZG','f_respuesta_preg',v_tconsulta);
  OPEN vr_cursor FOR v_tconsulta;
  LOOP
    FETCH vr_cursor INTO v_tlinia;
    EXIT
  WHEN vr_cursor%NOTFOUND;
    v_tresult := v_tresult || v_tlinia ;
  END LOOP;
  RETURN v_tresult;
EXCEPTION
WHEN OTHERS THEN
  RETURN ('');
END f_respuesta_preg;
  --FIN AITSSD-3723 GZG 01/12/2022
  --INI AITSSD-19993 GZG 22/07/2024
  FUNCTION f_aseg_princ(
    psseguro IN NUMBER,
    pnriesgo IN NUMBER DEFAULT 1)
  RETURN NUMBER
  IS
    v_sperson NUMBER;
    v_cont NUMBER;
    --
    BEGIN
      --
      SELECT COUNT(*)
      INTO v_cont
      FROM asegurados
      WHERE sseguro = psseguro
      AND nriesgo = pnriesgo;
      --
        IF v_cont > 1 THEN
         FOR i IN
          (SELECT a.sperson, p.ctipide, a.nordeninc--GZG AITSSD-6056 01/10/2025
            FROM asegurados a, per_personas p
            WHERE a.sseguro = psseguro
            AND a.nriesgo = pnriesgo
            AND a.norden = 1
            AND a.ffecfin IS NULL
            AND p.sperson = a.sperson
            ORDER BY a.nordeninc DESC--GZG AITSSD-6056 01/10/2025
          )
          LOOP -- se deja en loop por si existe mas de un asegurado como persona natural
            IF i.ctipide IN (36,37) AND v_sperson IS NULL THEN--GZG AITSSD-6056 08/10/2025 se adiciona persona juridica
              v_sperson := i.sperson;
            END IF;
          END LOOP;
        END IF;
      RETURN v_sperson;
    EXCEPTION
    WHEN OTHERS THEN
      RETURN NULL;
    END f_aseg_princ;
  --FIN AITSSD-19993 GZG 22/07/2024
  --INI AITSSD-20328 GZG 02/08/2024
    /*****************************************************************
    FUNCTION f_caracter_esp
    param IN tdomici  : texto a editar
    return             : texto sin caracteres especiales
    ******************************************************************/
  FUNCTION f_caracter_esp(
    tdomici IN VARCHAR2)
  RETURN VARCHAR2
  IS
    v_tdomici VARCHAR2(4000);
    --
  BEGIN
  --
   v_tdomici := tdomici;
   v_tdomici := replace(v_tdomici,'&#8216;',CHR(209)) ;
   v_tdomici := replace(v_tdomici,'&#8240;','%') ;
   v_tdomici := replace(v_tdomici,'&#180;','') ;
   v_tdomici := replace(v_tdomici,'&#8226;','-');
   v_tdomici := replace(v_tdomici,'&#8220;','');
   v_tdomici := replace(v_tdomici,'&#8221;','');
   v_tdomici := replace(v_tdomici,'&#8211;','-');
   v_tdomici := replace(v_tdomici,';','') ;
   v_tdomici := replace(v_tdomici,'"','');--AITSSD-5027 GZG 11/08/2025 se retira porque si viene uno solo daña el pdf
        RETURN v_tdomici;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN NULL;
  END f_caracter_esp;
  --FIN AITSSD-20328 GZG 02/08/2024
   -- INICIO AITSSD-1231
 FUNCTION f_cond_fenix(
    psseguro IN NUMBER)
  RETURN VARCHAR2
IS
  v_tresult VARCHAR2(250);

BEGIN

BEGIN
   SELECT cdp.TDESCRIP
   INTO v_tresult
   FROM CONDICIONADOPROD  cdp, PREGUNPOLSEG pps
   WHERE cdp.CCONDICIO = pps.crespue
   AND  pps.sseguro = psseguro
   and  pps.cpregun = 8425
   AND  pps.nmovimi in(select MAX(pps2.nmovimi)
                       from PREGUNPOLSEG pps2
                       where  pps2.sseguro = pps.sseguro
                       and  pps2.cpregun = pps.cpregun);
  EXCEPTION
  WHEN OTHERS THEN
    v_tresult := '';
  END;

  RETURN v_tresult;
EXCEPTION
WHEN OTHERS THEN
  RETURN '';
END f_cond_fenix;
 -- FIN AITSSD-1231
 -- INICIO AITSSD-5774
 FUNCTION f_condgen_900758(
    psseguro IN NUMBER,
    pefecto  IN DATE,
    ptabla   IN VARCHAR2 DEFAULT 'POL',
    pnmovimi IN NUMBER DEFAULT 1
  )
  RETURN VARCHAR2
IS
  vret     VARCHAR2(255);
  vcrespue NUMBER;
  v_sproduc seguros.sproduc%TYPE;
  vparam    VARCHAR2(500) := 'psseguro: '||psseguro||' - pefecto: '||pefecto||' - ptabla: '||ptabla||' - pnmovimi: '||pnmovimi;
  v_cmovseg NUMBER;
BEGIN
  IF ptabla = 'POL' THEN
    SELECT sproduc
    INTO v_sproduc
    FROM seguros
    WHERE sseguro = psseguro;

    BEGIN
      SELECT crespue
      INTO vcrespue
      FROM pregunpolseg
      WHERE cpregun = 4777
      AND sseguro   = psseguro
      AND nmovimi = pnmovimi;
     EXCEPTION
    WHEN NO_DATA_FOUND THEN
     NULL;
    END;

    BEGIN
      SELECT cclausu
      INTO vret
      FROM condicionadoprod
      WHERE ccondicio = vcrespue;
    EXCEPTION
    WHEN NO_DATA_FOUND THEN
      NULL;
    END;

  ELSE

    SELECT sproduc
    INTO v_sproduc
    FROM estseguros
    WHERE sseguro = psseguro;

    BEGIN
      SELECT crespue
      INTO vcrespue
      FROM estpregunpolseg
      WHERE cpregun = 4777
      AND sseguro   = psseguro
      AND nmovimi = pnmovimi;
     EXCEPTION
    WHEN NO_DATA_FOUND THEN
     NULL;
    END;

    BEGIN
      SELECT cclausu
      INTO vret
      FROM condicionadoprod
      WHERE ccondicio = vcrespue;
    EXCEPTION
    WHEN NO_DATA_FOUND THEN
     NULL;
    END;
  END IF;
  RETURN f_jrep_trad(vret);
EXCEPTION
WHEN OTHERS THEN
  RETURN NULL;
END f_condgen_900758;
 -- FIN AITSSD-5774
 -- INI AITSSD-6368 29/10/2025
  /*****************************************************************
  FUNCTION f_benespseg_n
  esta funcion se basa en la f_benespseg pero optimizada,
  la reemplazara paulatinamente
  param IN psseguro  : Codigo del seguro
  param IN pnmovimi  : Codigo del movimiento
  param IN pcidioma  : Codigo del idioma
  param IN pcamp     : Codigo del campo
  return             : texto
  ******************************************************************/
    FUNCTION f_benespseg_n(
        psseguro IN NUMBER,
        pnmovimi IN NUMBER,
        pcidioma IN NUMBER,
        pcamp    IN NUMBER)
      RETURN VARCHAR2
    IS
      v_tresult  VARCHAR2(4000);
      v_tresult2 VARCHAR2(4000);
      v_ncont   NUMBER := 0;
      v_sproduc NUMBER;
      v_nerror  NUMBER;
    BEGIN
      v_nerror := pac_seguros.f_get_sproduc(psseguro, 'POL', v_sproduc);

      SELECT COUNT(*) INTO v_ncont
      FROM benespseg b
      WHERE b.sseguro = psseguro
      AND b.nmovimi = pnmovimi;

      IF v_ncont = 0 THEN
        SELECT COUNT(*) INTO v_ncont
        FROM benespseg b
        WHERE b.sseguro = psseguro
        AND b.nmovimi = (SELECT MAX(nmovimi) FROM benespseg WHERE sseguro = psseguro);
      END IF;
      IF NVL(pac_parametros.f_parproducto_n(v_sproduc, 'VIG_BENEFICIARIO'), 0) = 1 AND v_ncont = 0 AND v_nerror = 0 THEN
        RAISE NO_DATA_FOUND;
      END IF;
    BEGIN
      SELECT sproduc INTO v_sproduc FROM seguros WHERE sseguro = psseguro;
    EXCEPTION
    WHEN OTHERS THEN
      BEGIN
        SELECT sproduc INTO v_sproduc FROM estseguros WHERE sseguro = psseguro;
      EXCEPTION
      WHEN OTHERS THEN
        v_sproduc := NULL;
      END;
    END;
      FOR i IN
      (SELECT SUBSTR(f_dades_persona(ben.sperson, 8, pcidioma, 'POL'), 1, 5) || ' ' || f_dades_persona(ben.sperson, 1, pcidioma, 'POL') idbenef,
        (SELECT TRIM(tnombre) || ' ' || TRIM(tapelli1 || ' ' || tapelli2) FROM per_detper WHERE sperson = ben.sperson AND ROWNUM = 1) nombenef,
        ff_desvalorfijo(1054, pcidioma, ben.cparen) parentbenef,
        ben.pparticip porcbenef,
        f_dades_persona(ben.sperson_tit, 8, pcidioma, 'POL') || ' ' || f_dades_persona(ben.sperson_tit, 1, pcidioma, 'POL') contbenef,
        NULL acrebenef,
        'S' benefaccid,
        pac_isqlfor.f_telefono(ben.sperson) telefonobnf,
        pac_isqlfor.f_poblacion(ben.sperson, NVL((SELECT cdomici FROM (
          SELECT a.cdomici FROM benespseg a WHERE a.sseguro = psseguro AND a.sperson = ben.sperson AND a.cgarant = 0 AND a.nmovimi = (SELECT MAX(nmovimi) FROM benespseg WHERE sseguro = psseguro AND nmovimi <= pnmovimi)
          UNION ALL
          SELECT MAX(b.cdomici) FROM benespseg a, asegurados b WHERE a.sseguro = psseguro AND a.sseguro = b.sseguro AND a.sperson = b.sperson AND a.sperson = ben.sperson AND a.cgarant = 0 AND a.nmovimi = (SELECT MAX(nmovimi) FROM benespseg WHERE sseguro = psseguro AND nmovimi <= pnmovimi)
          UNION ALL
          SELECT MAX(b.cdomici) FROM benespseg a, tomadores b WHERE a.sseguro = psseguro AND a.sseguro = b.sseguro AND a.sperson = b.sperson AND a.sperson = ben.sperson AND a.cgarant = 0 AND a.nmovimi = (SELECT MAX(nmovimi) FROM benespseg WHERE sseguro = psseguro AND nmovimi <= pnmovimi)
          UNION ALL
          SELECT MAX(cdomici) FROM per_direcciones WHERE sperson = ben.sperson AND ctipdir = 9
          UNION ALL
          SELECT MAX(cdomici) FROM per_direcciones WHERE sperson = ben.sperson
        ) WHERE cdomici IS NOT NULL AND ROWNUM = 1), 1)) bnfpoblac,
        PAC_ISQLFOR_LCOL.F_DIRECCION(ben.sperson, NVL((SELECT cdomici FROM (
          SELECT a.cdomici FROM benespseg a WHERE a.sseguro = psseguro AND a.sperson = ben.sperson AND a.cgarant = 0 AND a.nmovimi = (SELECT MAX(nmovimi) FROM benespseg WHERE sseguro = psseguro AND nmovimi <= pnmovimi)
          UNION ALL
          SELECT MAX(b.cdomici) FROM benespseg a, asegurados b WHERE a.sseguro = psseguro AND a.sseguro = b.sseguro AND a.sperson = b.sperson AND a.sperson = ben.sperson AND a.cgarant = 0 AND a.nmovimi = (SELECT MAX(nmovimi) FROM benespseg WHERE sseguro = psseguro AND nmovimi <= pnmovimi)
          UNION ALL
          SELECT MAX(b.cdomici) FROM benespseg a, tomadores b WHERE a.sseguro = psseguro AND a.sseguro = b.sseguro AND a.sperson = b.sperson AND a.sperson = ben.sperson AND a.cgarant = 0 AND a.nmovimi = (SELECT MAX(nmovimi) FROM benespseg WHERE sseguro = psseguro AND nmovimi <= pnmovimi)
          UNION ALL
          SELECT MAX(cdomici) FROM per_direcciones WHERE sperson = ben.sperson AND ctipdir = 9
          UNION ALL
          SELECT MAX(cdomici) FROM per_direcciones WHERE sperson = ben.sperson
        ) WHERE cdomici IS NOT NULL AND ROWNUM = 1), 1)) bnfdirec,
        ben.sperson,
        (SELECT fnacimi FROM per_personas WHERE sperson = ben.sperson) fechanacim,
        pac_isqlfor.f_provincia(ben.sperson, NVL((SELECT cdomici FROM (
          SELECT a.cdomici FROM benespseg a WHERE a.sseguro = psseguro AND a.sperson = ben.sperson AND a.cgarant = 0 AND a.nmovimi = (SELECT MAX(nmovimi) FROM benespseg WHERE sseguro = psseguro AND nmovimi <= pnmovimi)
          UNION ALL
          SELECT MAX(b.cdomici) FROM benespseg a, asegurados b WHERE a.sseguro = psseguro AND a.sseguro = b.sseguro AND a.sperson = b.sperson AND a.sperson = ben.sperson AND a.cgarant = 0 AND a.nmovimi = (SELECT MAX(nmovimi) FROM benespseg WHERE sseguro = psseguro AND nmovimi <= pnmovimi)
          UNION ALL
          SELECT MAX(b.cdomici) FROM benespseg a, tomadores b WHERE a.sseguro = psseguro AND a.sseguro = b.sseguro AND a.sperson = b.sperson AND a.sperson = ben.sperson AND a.cgarant = 0 AND a.nmovimi = (SELECT MAX(nmovimi) FROM benespseg WHERE sseguro = psseguro AND nmovimi <= pnmovimi)
          UNION ALL
          SELECT MAX(cdomici) FROM per_direcciones WHERE sperson = ben.sperson AND ctipdir = 9
          UNION ALL
          SELECT MAX(cdomici) FROM per_direcciones WHERE sperson = ben.sperson
        ) WHERE cdomici IS NOT NULL AND ROWNUM = 1), 1)) bnfprovincia,
        pac_isqlfor.f_per_contactos(ben.sperson,3) emailbnf
      FROM benespseg ben
      WHERE ben.sseguro = psseguro
      AND cgarant       = 0
      AND ((ben.CTIPBEN = (select NVL(max(be.CTIPBEN),3) FROM benespseg be WHERE be.sseguro = psseguro and be.ctipben <= 2 and be.nmovimi = ben.nmovimi  and be.cgarant = ben.cgarant) AND NVL(pac_parametros.f_parproducto_n(v_sproduc, 'BEN_ENDOSO_AU'), 0) = 1)
      OR (ben.CTIPBEN IS NOT NULL AND NVL(pac_parametros.f_parproducto_n(v_sproduc, 'BEN_ENDOSO_AU'), 0) = 0))
      AND nmovimi       =
        (SELECT MAX(nmovimi)
        FROM benespseg
        WHERE sseguro = psseguro
        AND nmovimi  <= pnmovimi
        )
      ORDER BY nriesgo ASC,
        sperson_tit ASC,
        pparticip DESC,
        fmovimi ASC,
        ROWID ASC
      )
      LOOP
        IF pcamp = 1 THEN
          v_tresult := v_tresult || i.idbenef || ' \par ';
        ELSIF pcamp = 2 THEN
          v_tresult := v_tresult || i.nombenef || ' \par ';
        ELSIF pcamp = 3 THEN
          v_tresult := v_tresult || i.parentbenef || ' \par ';
        ELSIF pcamp = 4 THEN
          v_tresult := v_tresult || i.porcbenef || ' \par ';
        ELSIF pcamp = 5 THEN
          v_tresult := v_tresult || i.contbenef || ' \par ';
        ELSIF pcamp = 6 THEN
          v_tresult := v_tresult || i.acrebenef || ' \par ';
        ELSIF pcamp = 7 THEN
          v_tresult := v_tresult || i.telefonobnf || ' \par ';
        ELSIF pcamp = 8 THEN
          v_tresult := v_tresult || i.bnfpoblac || ' \par ';
        ELSIF pcamp = 9 THEN
          v_tresult := v_tresult || i.bnfdirec || ' \par ';
        ELSIF pcamp = 10 THEN
          v_tresult := v_tresult || i.fechanacim || ' \par ';
        ELSIF pcamp = 11 THEN
          v_tresult := v_tresult || i.benefaccid || ' \par ';
        ELSIF pcamp = 12 THEN
          v_tresult := v_tresult || i.bnfprovincia || ' \par ';
        ELSIF pcamp = 13 THEN
          v_tresult := v_tresult || i.emailbnf || ' \par ';
        ELSIF pcamp = 14 THEN
          v_tresult := v_tresult || i.bnfdirec || ' / ' || i.emailbnf || ' \par ';--campo unico para pyme lt
        END IF;
      END LOOP;
      RETURN (REPLACE(f_jrep_trad(v_tresult), CHR(39), ''));
    EXCEPTION
    WHEN OTHERS THEN
      RETURN ('');
    END f_benespseg_n;
 --FIN AITSSD-6368 29/10/2025
END pac_isqlfor_lcol;